INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1001, '《中华人民共和国民法典》', '第五百七十七条', '民事', '法律', '违约责任', NULL, NULL, NULL, '当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1002, '《中华人民共和国民法典》', '第五百七十八条', '民事', '法律', '预期违约', NULL, NULL, NULL, '当事人一方明确表示或者以自己的行为表明不履行合同义务的，对方可以在履行期限届满前请求其承担违约责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1003, '《中华人民共和国民法典》', '第一百七十九条', '民事', '法律', '承担民事责任的方式', NULL, NULL, NULL, '承担民事责任的方式主要有：（一）停止侵害；（二）排除妨碍；（三）消除危险；（四）返还财产；（五）恢复原状；（六）修理、重作、更换；（七）继续履行；（八）赔偿损失；（九）支付违约金；（十）消除影响、恢复名誉；（十一）赔礼道歉。法律规定惩罚性赔偿的，依照其规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1004, '《中华人民共和国民法典》', '第一百八十八条', '民事', '法律', '诉讼时效', NULL, NULL, NULL, '向人民法院请求保护民事权利的诉讼时效期间为三年。法律另有规定的，依照其规定。诉讼时效期间自权利人知道或者应当知道权利受到损害以及义务人之日起计算。法律另有规定的，依照其规定。但是，自权利受到损害之日起超过二十年的，人民法院不予保护。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1009, '《中华人民共和国刑法》', '第二百六十四条', '刑事', '法律', '盗窃罪', NULL, NULL, NULL, '盗窃公私财物，数额较大的，或者多次盗窃、入户盗窃、携带凶器盗窃、扒窃的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1010, '《诉讼费用交纳办法》', '第十三条', '程序', '行政法规', '案件受理费的交纳标准', NULL, NULL, NULL, '财产案件根据诉讼请求的金额或者价额，按照下列比例分段累计交纳：不超过1万元的，每件交纳50元；超过1万元至10万元的部分，按照2.5%交纳；超过10万元至20万元的部分，按照2%交纳；超过20万元至50万元的部分，按照1.5%交纳；超过50万元至100万元的部分，按照1%交纳；超过100万元至200万元的部分，按照0.9%交纳。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1011, '《中华人民共和国消费者权益保护法》', '第五十五条', '民事', '法律', '惩罚性赔偿', NULL, NULL, NULL, '经营者提供商品或者服务有欺诈行为的，应当按照消费者的要求增加赔偿其受到的损失，增加赔偿的金额为消费者购买商品的价款或者接受服务的费用的三倍；增加赔偿的金额不足五百元的，为五百元。法律另有规定的，依照其规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (1012, '《中华人民共和国民法典》', '第一千一百七十九条', '民事', '法律', '人身损害赔偿范围', NULL, NULL, NULL, '侵害他人造成人身损害的，应当赔偿医疗费、护理费、交通费、营养费、住院伙食补助费等为治疗和康复支出的合理费用，以及因误工减少的收入。造成残疾的，还应当赔偿辅助器具费和残疾赔偿金；造成死亡的，还应当赔偿丧葬费和死亡赔偿金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2001, '《中华人民共和国民法典》', '第一千零六十二条', '民事', '法律', '夫妻共同财产', NULL, NULL, NULL, '夫妻在婚姻关系存续期间所得的下列财产，为夫妻的共同财产，归夫妻共同所有：（一）工资、奖金、劳务报酬；（二）生产、经营、投资的收益；（三）知识产权的收益；（四）继承或者受赠的财产，但是本法第一千零六十三条第三项规定的除外；（五）其他应当归共同所有的财产。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2002, '《中华人民共和国民法典》', '第一千零八十七条', '民事', '法律', '离婚时共同财产的处理', NULL, NULL, NULL, '离婚时，夫妻的共同财产由双方协议处理；协议不成的，由人民法院根据财产的具体情况，按照照顾子女、女方和无过错方权益的原则判决。对夫或者妻在家庭土地承包经营中享有的权益等，应当依法予以保护。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2003, '《中华人民共和国民法典》', '第一千一百六十五条', '民事', '法律', '过错责任原则', NULL, NULL, NULL, '行为人因过错侵害他人民事权益造成损害的，应当承担侵权责任。依照法律规定推定行为人有过错，其不能证明自己没有过错的，应当承担侵权责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2004, '《中华人民共和国民法典》', '第一千一百八十八条', '民事', '法律', '监护人责任', NULL, NULL, NULL, '无民事行为能力人、限制民事行为能力人造成他人损害的，由监护人承担侵权责任。监护人尽到监护职责的，可以减轻其侵权责任。有财产的无民事行为能力人、限制民事行为能力人造成他人损害的，从本人财产中支付赔偿费用；不足部分，由监护人赔偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2005, '《中华人民共和国民法典》', '第五百八十四条', '民事', '法律', '违约损害赔偿范围', NULL, NULL, NULL, '当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2006, '《中华人民共和国民法典》', '第五百六十三条', '民事', '法律', '合同法定解除', NULL, NULL, NULL, '有下列情形之一的，当事人可以解除合同：（一）因不可抗力致使不能实现合同目的；（二）在履行期限届满前，当事人一方明确表示或者以自己的行为表明不履行主要债务；（三）当事人一方迟延履行主要债务，经催告后在合理期限内仍未履行；（四）当事人一方迟延履行债务或者有其他违约行为致使不能实现合同目的；（五）法律规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2007, '《中华人民共和国民法典》', '第六百六十七条', '民事', '法律', '借款合同定义', NULL, NULL, NULL, '借款合同是借款人向贷款人借款，到期返还借款并支付利息的合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2008, '《中华人民共和国民法典》', '第六百八十条', '民事', '法律', '禁止高利放贷', NULL, NULL, NULL, '禁止高利放贷，借款的利率不得违反国家有关规定。借款合同对支付利息没有约定的，视为没有利息。借款合同对支付利息约定不明确，当事人不能达成补充协议的，按照当地或者当事人的交易方式、交易习惯、市场利率等因素确定利息；自然人之间借款的，视为没有利息。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2009, '《中华人民共和国民法典》', '第四百九十六条', '民事', '法律', '格式条款', NULL, NULL, NULL, '格式条款是当事人为了重复使用而预先拟定，并在订立合同时未与对方协商的条款。采用格式条款订立合同的，提供格式条款的一方应当遵循公平原则确定当事人之间的权利和义务，并采取合理的方式提示对方注意免除或者减轻其责任等与对方有重大利害关系的条款，按照对方的要求，对该条款予以说明。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2010, '《中华人民共和国民法典》', '第一千一百七十六条', '民事', '法律', '自甘风险', NULL, NULL, NULL, '自愿参加具有一定风险的文体活动，因其他参加者的行为受到损害的，受害人不得请求其他参加者承担侵权责任；但是，其他参加者对损害的发生有故意或者重大过失的除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2021, '《中华人民共和国刑法》', '第二百三十四条', '刑事', '法律', '故意伤害罪', NULL, NULL, NULL, '故意伤害他人身体的，处三年以下有期徒刑、拘役或者管制。犯前款罪，致人重伤的，处三年以上十年以下有期徒刑；致人死亡或者以特别残忍手段致人重伤造成严重残疾的，处十年以上有期徒刑、无期徒刑或者死刑。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2022, '《中华人民共和国刑法》', '第二百六十六条', '刑事', '法律', '诈骗罪', NULL, NULL, NULL, '诈骗公私财物，数额较大的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2023, '《中华人民共和国刑法》', '第一百三十三条', '刑事', '法律', '交通肇事罪', NULL, NULL, NULL, '违反交通运输管理法规，因而发生重大事故，致人重伤、死亡或者使公私财产遭受重大损失的，处三年以下有期徒刑或者拘役；交通运输肇事后逃逸或者有其他特别恶劣情节的，处三年以上七年以下有期徒刑；因逃逸致人死亡的，处七年以上有期徒刑。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2024, '《中华人民共和国刑法》', '第二十条', '刑事', '法律', '正当防卫', NULL, NULL, NULL, '为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在进行的不法侵害，而采取的制止不法侵害的行为，对不法侵害人造成损害的，属于正当防卫，不负刑事责任。正当防卫明显超过必要限度造成重大损害的，应当负刑事责任，但是应当减轻或者免除处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2025, '《中华人民共和国刑法》', '第六十七条', '刑事', '法律', '自首', NULL, NULL, NULL, '犯罪以后自动投案，如实供述自己的罪行的，是自首。对于自首的犯罪分子，可以从轻或者减轻处罚。其中，犯罪较轻的，可以免除处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2026, '《中华人民共和国公司法》', '第四十七条', '商事', '法律', '认缴出资期限', NULL, NULL, NULL, '有限责任公司的注册资本为在公司登记机关登记的全体股东认缴的出资额。全体股东认缴的出资额由股东按照公司章程的规定自公司成立之日起五年内缴足。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2027, '《中华人民共和国公司法》', '第八十四条', '商事', '法律', '股权转让', NULL, NULL, NULL, '有限责任公司的股东之间可以相互转让其全部或者部分股权。股东向股东以外的人转让股权的，应当将股权转让的数量、价格、支付方式和期限等事项书面通知其他股东，其他股东在同等条件下有优先购买权。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2028, '《中华人民共和国公司法》', '第八十九条', '商事', '法律', '异议股东回购请求权', NULL, NULL, NULL, '有下列情形之一的，对股东会该项决议投反对票的股东可以请求公司按照合理的价格收购其股权：（一）公司连续五年不向股东分配利润，而公司该五年连续盈利，并且符合本法规定的分配利润条件；（二）公司合并、分立、转让主要财产；（三）公司章程规定的营业期限届满或者章程规定的其他解散事由出现，股东会会议通过决议修改章程使公司存续。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2029, '《中华人民共和国民事诉讼法》', '第一百二十二条', '程序', '法律', '起诉条件', NULL, NULL, NULL, '起诉必须符合下列条件：（一）原告是与本案有直接利害关系的公民、法人和其他组织；（二）有明确的被告；（三）有具体的诉讼请求和事实、理由；（四）属于人民法院受理民事诉讼的范围和受诉人民法院管辖。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2030, '《中华人民共和国民事诉讼法》', '第六十七条', '程序', '法律', '举证责任', NULL, NULL, NULL, '当事人对自己提出的主张，有责任提供证据。当事人及其诉讼代理人因客观原因不能自行收集的证据，或者人民法院认为审理案件需要的证据，人民法院应当调查收集。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2031, '《中华人民共和国民事诉讼法》', '第二百四十六条', '程序', '法律', '申请执行期间', NULL, NULL, NULL, '申请执行的期间为二年。申请执行时效的中止、中断，适用法律有关诉讼时效中止、中断的规定。前款规定的期间，从法律文书规定履行期间的最后一日起计算；法律文书规定分期履行的，从规定的每次履行期间的最后一日起计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2032, '《中华人民共和国民法典》', '第一千零四十二条', '民事', '法律', '婚姻家庭禁止性规定', NULL, NULL, NULL, '禁止包办、买卖婚姻和其他干涉婚姻自由的行为。禁止借婚姻索取财物。禁止重婚。禁止有配偶者与他人同居。禁止家庭暴力。禁止家庭成员间的虐待和遗弃。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (2033, '《中华人民共和国民法典》', '第一千零七十六条', '民事', '法律', '协议离婚', NULL, NULL, NULL, '夫妻双方自愿离婚的，应当签订书面离婚协议，并亲自到婚姻登记机关申请离婚登记。离婚协议应当载明双方自愿离婚的意思表示和对子女抚养、财产以及债务处理等事项协商一致的意见。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10001, '《中华人民共和国劳动法》', '第一条', '劳动', '法律', NULL, NULL, '第一章 　总则　　', NULL, '第一条　为了保护劳动者的合法权益，调整劳动关系，建立和维护适应社会主义市场经济的劳动制度，促进经济发展和社会进步，根据宪法，制定本法。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10002, '《中华人民共和国劳动法》', '第二条', '劳动', '法律', NULL, NULL, '第一章 　总则　　', NULL, '第二条　在中华人民共和国境内的企业、个体经济组织（以下统称用人单位）和与之形成劳动关系的劳动者，适用本法。 　　国家机关、事业组织、社会团体和与之建立劳动合同关系的劳动者，依照本法执行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10003, '《中华人民共和国劳动法》', '第三条', '劳动', '法律', NULL, NULL, '第一章 　总则　　', NULL, '第三条　劳动者享有平等就业和选择职业的权利、取得劳动报酬的权利、休息休假的权利、获得劳动安全卫生保护的权利、接受职业技能培训的权利、享受社会保险和福利的权利、提请劳动争议处理的权利以及法律规定的其他劳动权利。 　　劳动者应当完成劳动任务，提高职业技能，执行劳动安全卫生规程，遵守劳动纪律和职业道德。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10004, '《中华人民共和国劳动法》', '第四条', '劳动', '法律', NULL, NULL, '第一章 　总则　　', NULL, '第四条　用人单位应当依法建立和完善规章制度，保障劳动者享有劳动权利和履行劳动义务。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10005, '《中华人民共和国劳动法》', '第五条', '劳动', '法律', NULL, NULL, '第一章 　总则　　', NULL, '第五条　国家采取各种措施，促进劳动就业，发展职业教育，制定劳动标准，调节社会收入，完善社会保险，协调劳动关系，逐步提高劳动者的生活水平。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10006, '《中华人民共和国劳动法》', '第六条', '劳动', '法律', NULL, NULL, '第一章 　总则　　', NULL, '第六条　国家提倡劳动者参加社会义务劳动，开展劳动竞赛和合理化建议活动，鼓励和保护劳动者进行科学研究、技术革新和发明创造，表彰和奖励劳动模范和先进工作者。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10007, '《中华人民共和国劳动法》', '第七条', '劳动', '法律', NULL, NULL, '第一章 　总则　　', NULL, '第七条　劳动者有权依法参加和组织工会。 　　工会代表和维护劳动者的合法权益，依法独立自主地开展活动。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10008, '《中华人民共和国劳动法》', '第八条', '劳动', '法律', NULL, NULL, '第一章 　总则　　', NULL, '第八条　劳动者依照法律规定，通过职工大会、职工代表大会或者其他形式，参与民主管理或者就保护劳动者合法权益与用人单位进行平等协商。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10009, '《中华人民共和国劳动法》', '第九条', '劳动', '法律', NULL, NULL, '第一章 　总则　　', NULL, '第九条　国务院劳动行政部门主管全国劳动工作。 　　县级以上地方人民政府劳动行政部门主管本行政区域内的劳动工作。 第二章　促进就业 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10010, '《中华人民共和国劳动法》', '第十条', '劳动', '法律', NULL, NULL, '第二章 　促进就业　　', NULL, '第十条　国家通过促进经济和社会发展，创造就业条件，扩大就业机会。 　　国家鼓励企业、事业组织、社会团体在法律、行政法规规定的范围内兴办产业或者拓展经营，增加就业。 　　国家支持劳动者自愿组织起来就业和从事个体经营实现就业。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10011, '《中华人民共和国劳动法》', '第十一条', '劳动', '法律', NULL, NULL, '第二章 　促进就业　　', NULL, '第十一条　地方各级人民政府应当采取措施，发展多种类型的职业介绍机构，提供就业服务。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10012, '《中华人民共和国劳动法》', '第十二条', '劳动', '法律', NULL, NULL, '第二章 　促进就业　　', NULL, '第十二条　劳动者就业，不因民族、种族、性别、宗教信仰不同而受歧视。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10013, '《中华人民共和国劳动法》', '第十三条', '劳动', '法律', NULL, NULL, '第二章 　促进就业　　', NULL, '第十三条　妇女享有与男子平等的就业权利。在录用职工时，除国家规定的不适合妇女的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10014, '《中华人民共和国劳动法》', '第十四条', '劳动', '法律', NULL, NULL, '第二章 　促进就业　　', NULL, '第十四条　残疾人、少数民族人员、退出现役的军人的就业，法律、法规有特别规定的，从其规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10015, '《中华人民共和国劳动法》', '第十五条', '劳动', '法律', NULL, NULL, '第二章 　促进就业　　', NULL, '第十五条　禁止用人单位招用未满十六周岁的未成年人。 　　文艺、体育和特种工艺单位招用未满十六周岁的未成年人，必须遵守国家有关规定，并保障其接受义务教育的权利。 第三章　劳动合同和集体合同 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10016, '《中华人民共和国劳动法》', '第十六条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第十六条　劳动合同是劳动者与用人单位确立劳动关系、明确双方权利和义务的协议。 　　建立劳动关系应当订立劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10017, '《中华人民共和国劳动法》', '第十七条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第十七条　订立和变更劳动合同，应当遵循平等自愿、协商一致的原则，不得违反法律、行政法规的规定。 　　劳动合同依法订立即具有法律约束力，当事人必须履行劳动合同规定的义务。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10018, '《中华人民共和国劳动法》', '第十八条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第十八条　下列劳动合同无效： 　　（一）违反法律、行政法规的劳动合同； 　　（二）采取欺诈、威胁等手段订立的劳动合同。 　　无效的劳动合同，从订立的时候起，就没有法律约束力。确认劳动合同部分无效的，如果不影响其余部分的效力，其余部分仍然有效。 　　劳动合同的无效，由劳动争议仲裁委员会或者人民法院确认。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10019, '《中华人民共和国劳动法》', '第十九条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第十九条　劳动合同应当以书面形式订立，并具备以下条款： 　　（一）劳动合同期限； 　　（二）工作内容； 　　（三）劳动保护和劳动条件； 　　（四）劳动报酬； 　　（五）劳动纪律； 　　（六）劳动合同终止的条件； 　　（七）违反劳动合同的责任。 　　劳动合同除前款规定的必备条款外，当事人可以协商约定其他内容。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10020, '《中华人民共和国劳动法》', '第二十条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第二十条　劳动合同的期限分为有固定期限、无固定期限和以完成一定的工作为期限。 　　劳动者在同一用人单位连续工作满十年以上，当事人双方同意续延劳动合同的，如果劳动者提出订立无固定期限的劳动合同，应当订立无固定期限的劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10021, '《中华人民共和国劳动法》', '第二十一条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第二十一条　劳动合同可以约定试用期。试用期最长不得超过六个月。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10022, '《中华人民共和国劳动法》', '第二十二条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第二十二条　劳动合同当事人可以在劳动合同中约定保守用人单位商业秘密的有关事项。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10023, '《中华人民共和国劳动法》', '第二十三条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第二十三条　劳动合同期满或者当事人约定的劳动合同终止条件出现，劳动合同即行终止。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10024, '《中华人民共和国劳动法》', '第二十四条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第二十四条　经劳动合同当事人协商一致，劳动合同可以解除。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10025, '《中华人民共和国劳动法》', '第二十五条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第二十五条　劳动者有下列情形之一的，用人单位可以解除劳动合同： 　　（一）在试用期间被证明不符合录用条件的； 　　（二）严重违反劳动纪律或者用人单位规章制度的； 　　（三）严重失职，营私舞弊，对用人单位利益造成重大损害的； 　　（四）被依法追究刑事责任的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10026, '《中华人民共和国劳动法》', '第二十六条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第二十六条　有下列情形之一的，用人单位可以解除劳动合同，但是应当提前三十日以书面形式通知劳动者本人： 　　（一）劳动者患病或者非因工负伤，医疗期满后，不能从事原工作也不能从事由用人单位另行安排的工作的； 　　（二）劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的； 　　（三）劳动合同订立时所依据的客观情况发生重大变化，致使原劳动合同无法履行，经当事人协商不能就变更劳动合同达成协议的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10027, '《中华人民共和国劳动法》', '第二十七条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第二十七条　用人单位濒临破产进行法定整顿期间或者生产经营状况发生严重困难，确需裁减人员的，应当提前三十日向工会或者全体职工说明情况，听取工会或者职工的意见，经向劳动行政部门报告后，可以裁减人员。 　　用人单位依据本条规定裁减人员，在六个月内录用人员的，应当优先录用被裁减的人员。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10028, '《中华人民共和国劳动法》', '第二十八条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第二十八条　用人单位依据本法第二十四条、第二十六条、第二十七条的规定解除劳动合同的，应当依照国家有关规定给予经济补偿。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10029, '《中华人民共和国劳动法》', '第二十九条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第二十九条　劳动者有下列情形之一的，用人单位不得依据本法第二十六条、第二十七条的规定解除劳动合同： 　　（一）患职业病或者因工负伤并被确认丧失或者部分丧失劳动能力的； 　　（二）患病或者负伤，在规定的医疗期内的； 　　（三）女职工在孕期、产期、哺乳期内的； 　　（四）法律、行政法规规定的其他情形。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10030, '《中华人民共和国劳动法》', '第三十条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第三十条　用人单位解除劳动合同，工会认为不适当的，有权提出意见。如果用人单位违反法律、法规或者劳动合同，工会有权要求重新处理；劳动者申请仲裁或者提起诉讼的，工会应当依法给予支持和帮助。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10031, '《中华人民共和国劳动法》', '第三十一条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第三十一条　劳动者解除劳动合同，应当提前三十日以书面形式通知用人单位。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10032, '《中华人民共和国劳动法》', '第三十二条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第三十二条　有下列情形之一的，劳动者可以随时通知用人单位解除劳动合同： 　　（一）在试用期内的； 　　（二）用人单位以暴力、威胁或者非法限制人身自由的手段强迫劳动的； 　　（三）用人单位未按照劳动合同约定支付劳动报酬或者提供劳动条件的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10033, '《中华人民共和国劳动法》', '第三十三条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第三十三条　企业职工一方与企业可以就劳动报酬、工作时间、休息休假、劳动安全卫生、保险福利等事项，签订集体合同。集体合同草案应当提交职工代表大会或者全体职工讨论通过。 　　集体合同由工会代表职工与企业签订；没有建立工会的企业，由职工推举的代表与企业签订。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10034, '《中华人民共和国劳动法》', '第三十四条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第三十四条　集体合同签订后应当报送劳动行政部门；劳动行政部门自收到集体合同文本之日起十五日内未提出异议的，集体合同即行生效。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10035, '《中华人民共和国劳动法》', '第三十五条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同和集体合同　　', NULL, '第三十五条　依法签订的集体合同对企业和企业全体职工具有约束力。职工个人与企业订立的劳动合同中劳动条件和劳动报酬等标准不得低于集体合同的规定。 第四章　工作时间和休息休假 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10036, '《中华人民共和国劳动法》', '第三十六条', '劳动', '法律', NULL, NULL, '第四章 　工作时间和休息休假　　', NULL, '第三十六条　国家实行劳动者每日工作时间不超过八小时、平均每周工作时间不超过四十四小时的工时制度。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10037, '《中华人民共和国劳动法》', '第三十七条', '劳动', '法律', NULL, NULL, '第四章 　工作时间和休息休假　　', NULL, '第三十七条　对实行计件工作的劳动者，用人单位应当根据本法第三十六条规定的工时制度合理确定其劳动定额和计件报酬标准。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10038, '《中华人民共和国劳动法》', '第三十八条', '劳动', '法律', NULL, NULL, '第四章 　工作时间和休息休假　　', NULL, '第三十八条　用人单位应当保证劳动者每周至少休息一日。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10039, '《中华人民共和国劳动法》', '第三十九条', '劳动', '法律', NULL, NULL, '第四章 　工作时间和休息休假　　', NULL, '第三十九条　企业因生产特点不能实行本法第三十六条、第三十八条规定的，经劳动行政部门批准，可以实行其他工作和休息办法。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10040, '《中华人民共和国劳动法》', '第四十条', '劳动', '法律', NULL, NULL, '第四章 　工作时间和休息休假　　', NULL, '第四十条　用人单位在下列节日期间应当依法安排劳动者休假： 　　（一）元旦； 　　（二）春节； 　　（三）国际劳动节； 　　（四）国庆节； 　　（五）法律、法规规定的其他休假节日。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10041, '《中华人民共和国劳动法》', '第四十一条', '劳动', '法律', NULL, NULL, '第四章 　工作时间和休息休假　　', NULL, '第四十一条　用人单位由于生产经营需要，经与工会和劳动者协商后可以延长工作时间，一般每日不得超过一小时；因特殊原因需要延长工作时间的，在保障劳动者身体健康的条件下延长工作时间每日不得超过三小时，但是每月不得超过三十六小时。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10042, '《中华人民共和国劳动法》', '第四十二条', '劳动', '法律', NULL, NULL, '第四章 　工作时间和休息休假　　', NULL, '第四十二条　有下列情形之一的，延长工作时间不受本法第四十一条规定的限制： 　　（一）发生自然灾害、事故或者因其他原因，威胁劳动者生命健康和财产安全，需要紧急处理的； 　　（二）生产设备、交通运输线路、公共设施发生故障，影响生产和公众利益，必须及时抢修的； 　　（三）法律、行政法规规定的其他情形。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10043, '《中华人民共和国劳动法》', '第四十三条', '劳动', '法律', NULL, NULL, '第四章 　工作时间和休息休假　　', NULL, '第四十三条　用人单位不得违反本法规定延长劳动者的工作时间。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10044, '《中华人民共和国劳动法》', '第四十四条', '劳动', '法律', NULL, NULL, '第四章 　工作时间和休息休假　　', NULL, '第四十四条　有下列情形之一的，用人单位应当按照下列标准支付高于劳动者正常工作时间工资的工资报酬： 　　（一）安排劳动者延长工作时间的，支付不低于工资的百分之一百五十的工资报酬； 　　（二）休息日安排劳动者工作又不能安排补休的，支付不低于工资的百分之二百的工资报酬； 　　（三）法定休假日安排劳动者工作的，支付不低于工资的百分之三百的工资报酬。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10045, '《中华人民共和国劳动法》', '第四十五条', '劳动', '法律', NULL, NULL, '第四章 　工作时间和休息休假　　', NULL, '第四十五条　国家实行带薪年休假制度。 　　劳动者连续工作一年以上的，享受带薪年休假。具体办法由国务院规定。 第五章　工资 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10046, '《中华人民共和国劳动法》', '第四十六条', '劳动', '法律', NULL, NULL, '第五章 　工资　　', NULL, '第四十六条　工资分配应当遵循按劳分配原则，实行同工同酬。 　　工资水平在经济发展的基础上逐步提高。国家对工资总量实行宏观调控。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10047, '《中华人民共和国劳动法》', '第四十七条', '劳动', '法律', NULL, NULL, '第五章 　工资　　', NULL, '第四十七条　用人单位根据本单位的生产经营特点和经济效益，依法自主确定本单位的工资分配方式和工资水平。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10048, '《中华人民共和国劳动法》', '第四十八条', '劳动', '法律', NULL, NULL, '第五章 　工资　　', NULL, '第四十八条　国家实行最低工资保障制度。最低工资的具体标准由省、自治区、直辖市人民政府规定，报国务院备案。 　　用人单位支付劳动者的工资不得低于当地最低工资标准。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10049, '《中华人民共和国劳动法》', '第四十九条', '劳动', '法律', NULL, NULL, '第五章 　工资　　', NULL, '第四十九条　确定和调整最低工资标准应当综合参考下列因素： 　　（一）劳动者本人及平均赡养人口的最低生活费用； 　　（二）社会平均工资水平； 　　（三）劳动生产率； 　　（四）就业状况； 　　（五）地区之间经济发展水平的差异。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10050, '《中华人民共和国劳动法》', '第五十条', '劳动', '法律', NULL, NULL, '第五章 　工资　　', NULL, '第五十条　工资应当以货币形式按月支付给劳动者本人。不得克扣或者无故拖欠劳动者的工资。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10051, '《中华人民共和国劳动法》', '第五十一条', '劳动', '法律', NULL, NULL, '第五章 　工资　　', NULL, '第五十一条　劳动者在法定休假日和婚丧假期间以及依法参加社会活动期间，用人单位应当依法支付工资。 第六章　劳动安全卫生 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10052, '《中华人民共和国劳动法》', '第五十二条', '劳动', '法律', NULL, NULL, '第六章 　劳动安全卫生　　', NULL, '第五十二条　用人单位必须建立、健全劳动安全卫生制度，严格执行国家劳动安全卫生规程和标准，对劳动者进行劳动安全卫生教育，防止劳动过程中的事故，减少职业危害。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10053, '《中华人民共和国劳动法》', '第五十三条', '劳动', '法律', NULL, NULL, '第六章 　劳动安全卫生　　', NULL, '第五十三条　劳动安全卫生设施必须符合国家规定的标准。 　　新建、改建、扩建工程的劳动安全卫生设施必须与主体工程同时设计、同时施工、同时投入生产和使用。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10054, '《中华人民共和国劳动法》', '第五十四条', '劳动', '法律', NULL, NULL, '第六章 　劳动安全卫生　　', NULL, '第五十四条　用人单位必须为劳动者提供符合国家规定的劳动安全卫生条件和必要的劳动防护用品，对从事有职业危害作业的劳动者应当定期进行健康检查。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10055, '《中华人民共和国劳动法》', '第五十五条', '劳动', '法律', NULL, NULL, '第六章 　劳动安全卫生　　', NULL, '第五十五条　从事特种作业的劳动者必须经过专门培训并取得特种作业资格。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10056, '《中华人民共和国劳动法》', '第五十六条', '劳动', '法律', NULL, NULL, '第六章 　劳动安全卫生　　', NULL, '第五十六条　劳动者在劳动过程中必须严格遵守安全操作规程。 　　劳动者对用人单位管理人员违章指挥、强令冒险作业，有权拒绝执行；对危害生命安全和身体健康的行为，有权提出批评、检举和控告。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10057, '《中华人民共和国劳动法》', '第五十七条', '劳动', '法律', NULL, NULL, '第六章 　劳动安全卫生　　', NULL, '第五十七条　国家建立伤亡事故和职业病统计报告和处理制度。县级以上各级人民政府劳动行政部门、有关部门和用人单位应当依法对劳动者在劳动过程中发生的伤亡事故和劳动者的职业病状况，进行统计、报告和处理。 第七章　女职工和未成年工特殊保护 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10058, '《中华人民共和国劳动法》', '第五十八条', '劳动', '法律', NULL, NULL, '第七章 　女职工和未成年工特殊保护　　', NULL, '第五十八条　国家对女职工和未成年工实行特殊劳动保护。 　　未成年工是指年满十六周岁未满十八周岁的劳动者。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10059, '《中华人民共和国劳动法》', '第五十九条', '劳动', '法律', NULL, NULL, '第七章 　女职工和未成年工特殊保护　　', NULL, '第五十九条　禁止安排女职工从事矿山井下、国家规定的第四级体力劳动强度的劳动和其他禁忌从事的劳动。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10060, '《中华人民共和国劳动法》', '第六十条', '劳动', '法律', NULL, NULL, '第七章 　女职工和未成年工特殊保护　　', NULL, '第六十条　不得安排女职工在经期从事高处、低温、冷水作业和国家规定的第三级体力劳动强度的劳动。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10061, '《中华人民共和国劳动法》', '第六十一条', '劳动', '法律', NULL, NULL, '第七章 　女职工和未成年工特殊保护　　', NULL, '第六十一条　不得安排女职工在怀孕期间从事国家规定的第三级体力劳动强度的劳动和孕期禁忌从事的劳动。对怀孕七个月以上的女职工，不得安排其延长工作时间和夜班劳动。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10062, '《中华人民共和国劳动法》', '第六十二条', '劳动', '法律', NULL, NULL, '第七章 　女职工和未成年工特殊保护　　', NULL, '第六十二条　女职工生育享受不少于九十天的产假。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10063, '《中华人民共和国劳动法》', '第六十三条', '劳动', '法律', NULL, NULL, '第七章 　女职工和未成年工特殊保护　　', NULL, '第六十三条　不得安排女职工在哺乳未满一周岁的婴儿期间从事国家规定的第三级体力劳动强度的劳动和哺乳期禁忌从事的其他劳动，不得安排其延长工作时间和夜班劳动。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10064, '《中华人民共和国劳动法》', '第六十四条', '劳动', '法律', NULL, NULL, '第七章 　女职工和未成年工特殊保护　　', NULL, '第六十四条　不得安排未成年工从事矿山井下、有毒有害、国家规定的第四级体力劳动强度的劳动和其他禁忌从事的劳动。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10065, '《中华人民共和国劳动法》', '第六十五条', '劳动', '法律', NULL, NULL, '第七章 　女职工和未成年工特殊保护　　', NULL, '第六十五条　用人单位应当对未成年工定期进行健康检查。 第八章　职业培训 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10066, '《中华人民共和国劳动法》', '第六十六条', '劳动', '法律', NULL, NULL, '第八章 　职业培训　　', NULL, '第六十六条　国家通过各种途径，采取各种措施，发展职业培训事业，开发劳动者的职业技能，提高劳动者素质，增强劳动者的就业能力和工作能力。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10067, '《中华人民共和国劳动法》', '第六十七条', '劳动', '法律', NULL, NULL, '第八章 　职业培训　　', NULL, '第六十七条　各级人民政府应当把发展职业培训纳入社会经济发展的规划，鼓励和支持有条件的企业、事业组织、社会团体和个人进行各种形式的职业培训。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10068, '《中华人民共和国劳动法》', '第六十八条', '劳动', '法律', NULL, NULL, '第八章 　职业培训　　', NULL, '第六十八条　用人单位应当建立职业培训制度，按照国家规定提取和使用职业培训经费，根据本单位实际，有计划地对劳动者进行职业培训。 　　从事技术工种的劳动者，上岗前必须经过培训。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10069, '《中华人民共和国劳动法》', '第六十九条', '劳动', '法律', NULL, NULL, '第八章 　职业培训　　', NULL, '第六十九条　国家确定职业分类，对规定的职业制定职业技能标准，实行职业资格证书制度，由经备案的考核鉴定机构负责对劳动者实施职业技能考核鉴定。 第九章　社会保险和福利 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10070, '《中华人民共和国劳动法》', '第七十条', '劳动', '法律', NULL, NULL, '第九章 　社会保险和福利　　', NULL, '第七十条　国家发展社会保险事业，建立社会保险制度，设立社会保险基金，使劳动者在年老、患病、工伤、失业、生育等情况下获得帮助和补偿。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10071, '《中华人民共和国劳动法》', '第七十一条', '劳动', '法律', NULL, NULL, '第九章 　社会保险和福利　　', NULL, '第七十一条　社会保险水平应当与社会经济发展水平和社会承受能力相适应。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10072, '《中华人民共和国劳动法》', '第七十二条', '劳动', '法律', NULL, NULL, '第九章 　社会保险和福利　　', NULL, '第七十二条　社会保险基金按照保险类型确定资金来源，逐步实行社会统筹。用人单位和劳动者必须依法参加社会保险，缴纳社会保险费。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10073, '《中华人民共和国劳动法》', '第七十三条', '劳动', '法律', NULL, NULL, '第九章 　社会保险和福利　　', NULL, '第七十三条　劳动者在下列情形下，依法享受社会保险待遇： 　　（一）退休； 　　（二）患病、负伤； 　　（三）因工伤残或者患职业病； 　　（四）失业； 　　（五）生育。 　　劳动者死亡后，其遗属依法享受遗属津贴。 　　劳动者享受社会保险待遇的条件和标准由法律、法规规定。 　　劳动者享受的社会保险金必须按时足额支付。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10074, '《中华人民共和国劳动法》', '第七十四条', '劳动', '法律', NULL, NULL, '第九章 　社会保险和福利　　', NULL, '第七十四条　社会保险基金经办机构依照法律规定收支、管理和运营社会保险基金，并负有使社会保险基金保值增值的责任。 　　社会保险基金监督机构依照法律规定，对社会保险基金的收支、管理和运营实施监督。 　　社会保险基金经办机构和社会保险基金监督机构的设立和职能由法律规定。 　　任何组织和个人不得挪用社会保险基金。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10075, '《中华人民共和国劳动法》', '第七十五条', '劳动', '法律', NULL, NULL, '第九章 　社会保险和福利　　', NULL, '第七十五条　国家鼓励用人单位根据本单位实际情况为劳动者建立补充保险。 　　国家提倡劳动者个人进行储蓄性保险。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10076, '《中华人民共和国劳动法》', '第七十六条', '劳动', '法律', NULL, NULL, '第九章 　社会保险和福利　　', NULL, '第七十六条　国家发展社会福利事业，兴建公共福利设施，为劳动者休息、休养和疗养提供条件。 　　用人单位应当创造条件，改善集体福利，提高劳动者的福利待遇。 第十章　劳动争议 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10077, '《中华人民共和国劳动法》', '第七十七条', '劳动', '法律', NULL, NULL, '第十章 　劳动争议　　', NULL, '第七十七条　用人单位与劳动者发生劳动争议，当事人可以依法申请调解、仲裁、提起诉讼，也可以协商解决。 　　调解原则适用于仲裁和诉讼程序。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10078, '《中华人民共和国劳动法》', '第七十八条', '劳动', '法律', NULL, NULL, '第十章 　劳动争议　　', NULL, '第七十八条　解决劳动争议，应当根据合法、公正、及时处理的原则，依法维护劳动争议当事人的合法权益。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10079, '《中华人民共和国劳动法》', '第七十九条', '劳动', '法律', NULL, NULL, '第十章 　劳动争议　　', NULL, '第七十九条　劳动争议发生后，当事人可以向本单位劳动争议调解委员会申请调解；调解不成，当事人一方要求仲裁的，可以向劳动争议仲裁委员会申请仲裁。当事人一方也可以直接向劳动争议仲裁委员会申请仲裁。对仲裁裁决不服的，可以向人民法院提起诉讼。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10080, '《中华人民共和国劳动法》', '第八十条', '劳动', '法律', NULL, NULL, '第十章 　劳动争议　　', NULL, '第八十条　在用人单位内，可以设立劳动争议调解委员会。劳动争议调解委员会由职工代表、用人单位代表和工会代表组成。劳动争议调解委员会主任由工会代表担任。 　　劳动争议经调解达成协议的，当事人应当履行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10081, '《中华人民共和国劳动法》', '第八十一条', '劳动', '法律', NULL, NULL, '第十章 　劳动争议　　', NULL, '第八十一条　劳动争议仲裁委员会由劳动行政部门代表、同级工会代表、用人单位方面的代表组成。劳动争议仲裁委员会主任由劳动行政部门代表担任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10082, '《中华人民共和国劳动法》', '第八十二条', '劳动', '法律', NULL, NULL, '第十章 　劳动争议　　', NULL, '第八十二条　提出仲裁要求的一方应当自劳动争议发生之日起六十日内向劳动争议仲裁委员会提出书面申请。仲裁裁决一般应在收到仲裁申请的六十日内作出。对仲裁裁决无异议的，当事人必须履行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10083, '《中华人民共和国劳动法》', '第八十三条', '劳动', '法律', NULL, NULL, '第十章 　劳动争议　　', NULL, '第八十三条　劳动争议当事人对仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼。一方当事人在法定期限内不起诉又不履行仲裁裁决的，另一方当事人可以申请人民法院强制执行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10084, '《中华人民共和国劳动法》', '第八十四条', '劳动', '法律', NULL, NULL, '第十章 　劳动争议　　', NULL, '第八十四条　因签订集体合同发生争议，当事人协商解决不成的，当地人民政府劳动行政部门可以组织有关各方协调处理。 　　因履行集体合同发生争议，当事人协商解决不成的，可以向劳动争议仲裁委员会申请仲裁；对仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼。 第十一章　监督检查 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10085, '《中华人民共和国劳动法》', '第八十五条', '劳动', '法律', NULL, NULL, '第十一章 　监督检查　　', NULL, '第八十五条　县级以上各级人民政府劳动行政部门依法对用人单位遵守劳动法律、法规的情况进行监督检查，对违反劳动法律、法规的行为有权制止，并责令改正。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10086, '《中华人民共和国劳动法》', '第八十六条', '劳动', '法律', NULL, NULL, '第十一章 　监督检查　　', NULL, '第八十六条　县级以上各级人民政府劳动行政部门监督检查人员执行公务，有权进入用人单位了解执行劳动法律、法规的情况，查阅必要的资料，并对劳动场所进行检查。 　　县级以上各级人民政府劳动行政部门监督检查人员执行公务，必须出示证件，秉公执法并遵守有关规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10087, '《中华人民共和国劳动法》', '第八十七条', '劳动', '法律', NULL, NULL, '第十一章 　监督检查　　', NULL, '第八十七条　县级以上各级人民政府有关部门在各自职责范围内，对用人单位遵守劳动法律、法规的情况进行监督。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10088, '《中华人民共和国劳动法》', '第八十八条', '劳动', '法律', NULL, NULL, '第十一章 　监督检查　　', NULL, '第八十八条　各级工会依法维护劳动者的合法权益，对用人单位遵守劳动法律、法规的情况进行监督。 　　任何组织和个人对于违反劳动法律、法规的行为有权检举和控告。 第十二章　法律责任 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10089, '《中华人民共和国劳动法》', '第八十九条', '劳动', '法律', NULL, NULL, '第十二章 　法律责任　　', NULL, '第八十九条　用人单位制定的劳动规章制度违反法律、法规规定的，由劳动行政部门给予警告，责令改正；对劳动者造成损害的，应当承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10090, '《中华人民共和国劳动法》', '第九十条', '劳动', '法律', NULL, NULL, '第十二章 　法律责任　　', NULL, '第九十条　用人单位违反本法规定，延长劳动者工作时间的，由劳动行政部门给予警告，责令改正，并可以处以罚款。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10091, '《中华人民共和国劳动法》', '第九十一条', '劳动', '法律', NULL, NULL, '第十二章 　法律责任　　', NULL, '第九十一条　用人单位有下列侵害劳动者合法权益情形之一的，由劳动行政部门责令支付劳动者的工资报酬、经济补偿，并可以责令支付赔偿金： 　　（一）克扣或者无故拖欠劳动者工资的； 　　（二）拒不支付劳动者延长工作时间工资报酬的； 　　（三）低于当地最低工资标准支付劳动者工资的； 　　（四）解除劳动合同后，未依照本法规定给予劳动者经济补偿的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10092, '《中华人民共和国劳动法》', '第九十二条', '劳动', '法律', NULL, NULL, '第十二章 　法律责任　　', NULL, '第九十二条　用人单位的劳动安全设施和劳动卫生条件不符合国家规定或者未向劳动者提供必要的劳动防护用品和劳动保护设施的，由劳动行政部门或者有关部门责令改正，可以处以罚款；情节严重的，提请县级以上人民政府决定责令停产整顿；对事故隐患不采取措施，致使发生重大事故，造成劳动者生命和财产损失的，对责任人员依照刑法有关规定追究刑事责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10093, '《中华人民共和国劳动法》', '第九十三条', '劳动', '法律', NULL, NULL, '第十二章 　法律责任　　', NULL, '第九十三条　用人单位强令劳动者违章冒险作业，发生重大伤亡事故，造成严重后果的，对责任人员依法追究刑事责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10094, '《中华人民共和国劳动法》', '第九十四条', '劳动', '法律', NULL, NULL, '第十二章 　法律责任　　', NULL, '第九十四条　用人单位非法招用未满十六周岁的未成年人的，由劳动行政部门责令改正，处以罚款；情节严重的，由市场监督管理部门吊销营业执照。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10095, '《中华人民共和国劳动法》', '第九十五条', '劳动', '法律', NULL, NULL, '第十二章 　法律责任　　', NULL, '第九十五条　用人单位违反本法对女职工和未成年工的保护规定，侵害其合法权益的，由劳动行政部门责令改正，处以罚款；对女职工或者未成年工造成损害的，应当承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10096, '《中华人民共和国劳动法》', '第九十六条', '劳动', '法律', NULL, NULL, '第十二章 　法律责任　　', NULL, '第九十六条　用人单位有下列行为之一，由公安机关对责任人员处以十五日以下拘留、罚款或者警告；构成犯罪的，对责任人员依法追究刑事责任： 　　（一）以暴力、威胁或者非法限制人身自由的手段强迫劳动的； 　　（二）侮辱、体罚、殴打、非法搜查和拘禁劳动者的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10097, '《中华人民共和国劳动法》', '第九十七条', '劳动', '法律', NULL, NULL, '第十二章 　法律责任　　', NULL, '第九十七条　由于用人单位的原因订立的无效合同，对劳动者造成损害的，应当承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10098, '《中华人民共和国劳动法》', '第九十八条', '劳动', '法律', NULL, NULL, '第十二章 　法律责任　　', NULL, '第九十八条　用人单位违反本法规定的条件解除劳动合同或者故意拖延不订立劳动合同的，由劳动行政部门责令改正；对劳动者造成损害的，应当承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10099, '《中华人民共和国劳动法》', '第九十九条', '劳动', '法律', NULL, NULL, '第十二章 　法律责任　　', NULL, '第九十九条　用人单位招用尚未解除劳动合同的劳动者，对原用人单位造成经济损失的，该用人单位应当依法承担连带赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10100, '《中华人民共和国劳动法》', '第一百条', '劳动', '法律', NULL, NULL, '第十二章 　法律责任　　', NULL, '第一百条　用人单位无故不缴纳社会保险费的，由劳动行政部门责令其限期缴纳；逾期不缴的，可以加收滞纳金。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10101, '《中华人民共和国劳动法》', '第一百零一条', '劳动', '法律', NULL, NULL, '第十二章 　法律责任　　', NULL, '第一百零一条　用人单位无理阻挠劳动行政部门、有关部门及其工作人员行使监督检查权，打击报复举报人员的，由劳动行政部门或者有关部门处以罚款；构成犯罪的，对责任人员依法追究刑事责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10102, '《中华人民共和国劳动法》', '第一百零二条', '劳动', '法律', NULL, NULL, '第十二章 　法律责任　　', NULL, '第一百零二条　劳动者违反本法规定的条件解除劳动合同或者违反劳动合同中约定的保密事项，对用人单位造成经济损失的，应当依法承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10103, '《中华人民共和国劳动法》', '第一百零三条', '劳动', '法律', NULL, NULL, '第十二章 　法律责任　　', NULL, '第一百零三条　劳动行政部门或者有关部门的工作人员滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；不构成犯罪的，给予行政处分。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10104, '《中华人民共和国劳动法》', '第一百零四条', '劳动', '法律', NULL, NULL, '第十二章 　法律责任　　', NULL, '第一百零四条　国家工作人员和社会保险基金经办机构的工作人员挪用社会保险基金，构成犯罪的，依法追究刑事责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10105, '《中华人民共和国劳动法》', '第一百零五条', '劳动', '法律', NULL, NULL, '第十二章 　法律责任　　', NULL, '第一百零五条　违反本法规定侵害劳动者合法权益，其他法律、行政法规已规定处罚的，依照该法律、行政法规的规定处罚。 第十三章　附则 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10106, '《中华人民共和国劳动法》', '第一百零六条', '劳动', '法律', NULL, NULL, '第十三章 　附则　　', NULL, '第一百零六条　省、自治区、直辖市人民政府根据本法和本地区的实际情况，规定劳动合同制度的实施步骤，报国务院备案。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10107, '《中华人民共和国劳动法》', '第一百零七条', '劳动', '法律', NULL, NULL, '第十三章 　附则　　', NULL, '第一百零七条　本法自1995年1月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10201, '《中华人民共和国劳动合同法》', '第一条', '劳动', '法律', NULL, NULL, '第一章 　总则　　', NULL, '第一条　为了完善劳动合同制度，明确劳动合同双方当事人的权利和义务，保护劳动者的合法权益，构建和发展和谐稳定的劳动关系，制定本法。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10202, '《中华人民共和国劳动合同法》', '第二条', '劳动', '法律', NULL, NULL, '第一章 　总则　　', NULL, '第二条　中华人民共和国境内的企业、个体经济组织、民办非企业单位等组织（以下称用人单位）与劳动者建立劳动关系，订立、履行、变更、解除或者终止劳动合同，适用本法。 　　国家机关、事业单位、社会团体和与其建立劳动关系的劳动者，订立、履行、变更、解除或者终止劳动合同，依照本法执行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10203, '《中华人民共和国劳动合同法》', '第三条', '劳动', '法律', NULL, NULL, '第一章 　总则　　', NULL, '第三条　订立劳动合同，应当遵循合法、公平、平等自愿、协商一致、诚实信用的原则。 　　依法订立的劳动合同具有约束力，用人单位与劳动者应当履行劳动合同约定的义务。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10204, '《中华人民共和国劳动合同法》', '第四条', '劳动', '法律', NULL, NULL, '第一章 　总则　　', NULL, '第四条　用人单位应当依法建立和完善劳动规章制度，保障劳动者享有劳动权利、履行劳动义务。 　　用人单位在制定、修改或者决定有关劳动报酬、工作时间、休息休假、劳动安全卫生、保险福利、职工培训、劳动纪律以及劳动定额管理等直接涉及劳动者切身利益的规章制度或者重大事项时，应当经职工代表大会或者全体职工讨论，提出方案和意见，与工会或者职工代表平等协商确定。 　　在规章制度和重大事项决定实施过程中，工会或者职工认为不适当的，有权向用人单位提出，通过协商予以修改完善。 　　用人单位应当将直接涉及劳动者切身利益的规章制度和重大事项决定公示，或者告知劳动者。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10205, '《中华人民共和国劳动合同法》', '第五条', '劳动', '法律', NULL, NULL, '第一章 　总则　　', NULL, '第五条　县级以上人民政府劳动行政部门会同工会和企业方面代表，建立健全协调劳动关系三方机制，共同研究解决有关劳动关系的重大问题。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10206, '《中华人民共和国劳动合同法》', '第六条', '劳动', '法律', NULL, NULL, '第一章 　总则　　', NULL, '第六条　工会应当帮助、指导劳动者与用人单位依法订立和履行劳动合同，并与用人单位建立集体协商机制，维护劳动者的合法权益。 第二章　劳动合同的订立 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10207, '《中华人民共和国劳动合同法》', '第七条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第七条　用人单位自用工之日起即与劳动者建立劳动关系。用人单位应当建立职工名册备查。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10208, '《中华人民共和国劳动合同法》', '第八条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第八条　用人单位招用劳动者时，应当如实告知劳动者工作内容、工作条件、工作地点、职业危害、安全生产状况、劳动报酬，以及劳动者要求了解的其他情况；用人单位有权了解劳动者与劳动合同直接相关的基本情况，劳动者应当如实说明。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10209, '《中华人民共和国劳动合同法》', '第九条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第九条　用人单位招用劳动者，不得扣押劳动者的居民身份证和其他证件，不得要求劳动者提供担保或者以其他名义向劳动者收取财物。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10210, '《中华人民共和国劳动合同法》', '第十条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十条　建立劳动关系，应当订立书面劳动合同。 　　已建立劳动关系，未同时订立书面劳动合同的，应当自用工之日起一个月内订立书面劳动合同。 　　用人单位与劳动者在用工前订立劳动合同的，劳动关系自用工之日起建立。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10211, '《中华人民共和国劳动合同法》', '第十一条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十一条　用人单位未在用工的同时订立书面劳动合同，与劳动者约定的劳动报酬不明确的，新招用的劳动者的劳动报酬按照集体合同规定的标准执行；没有集体合同或者集体合同未规定的，实行同工同酬。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10212, '《中华人民共和国劳动合同法》', '第十二条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十二条　劳动合同分为固定期限劳动合同、无固定期限劳动合同和以完成一定工作任务为期限的劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10213, '《中华人民共和国劳动合同法》', '第十三条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十三条　固定期限劳动合同，是指用人单位与劳动者约定合同终止时间的劳动合同。 　　用人单位与劳动者协商一致，可以订立固定期限劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10214, '《中华人民共和国劳动合同法》', '第十四条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十四条　无固定期限劳动合同，是指用人单位与劳动者约定无确定终止时间的劳动合同。 　　用人单位与劳动者协商一致，可以订立无固定期限劳动合同。有下列情形之一，劳动者提出或者同意续订、订立劳动合同的，除劳动者提出订立固定期限劳动合同外，应当订立无固定期限劳动合同: 　　（一）劳动者在该用人单位连续工作满十年的； 　　（二）用人单位初次实行劳动合同制度或者国有企业改制重新订立劳动合同时，劳动者在该用人单位连续工作满十年且距法定退休年龄不足十年的； 　　（三）连续订立二次固定期限劳动合同，且劳动者没有本法第三十九条和第四十条第一项、第二项规定的情形，续订劳动合同的。 　　用人单位自用工之日起满一年不与劳动者订立书面劳动合同的，视为用人单位与劳动者已订立无固定期限劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10215, '《中华人民共和国劳动合同法》', '第十五条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十五条　以完成一定工作任务为期限的劳动合同，是指用人单位与劳动者约定以某项工作的完成为合同期限的劳动合同。 　　用人单位与劳动者协商一致，可以订立以完成一定工作任务为期限的劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10216, '《中华人民共和国劳动合同法》', '第十六条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十六条　劳动合同由用人单位与劳动者协商一致，并经用人单位与劳动者在劳动合同文本上签字或者盖章生效。 　　劳动合同文本由用人单位和劳动者各执一份。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10217, '《中华人民共和国劳动合同法》', '第十七条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十七条　劳动合同应当具备以下条款: 　　（一）用人单位的名称、住所和法定代表人或者主要负责人； 　　（二）劳动者的姓名、住址和居民身份证或者其他有效身份证件号码； 　　（三）劳动合同期限； 　　（四）工作内容和工作地点； 　　（五）工作时间和休息休假； 　　（六）劳动报酬； 　　（七）社会保险； 　　（八）劳动保护、劳动条件和职业危害防护； 　　（九）法律、法规规定应当纳入劳动合同的其他事项。 　　劳动合同除前款规定的必备条款外，用人单位与劳动者可以约定试用期、培训、保守秘密、补充保险和福利待遇等其他事项。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10218, '《中华人民共和国劳动合同法》', '第十八条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十八条　劳动合同对劳动报酬和劳动条件等标准约定不明确，引发争议的，用人单位与劳动者可以重新协商；协商不成的，适用集体合同规定；没有集体合同或者集体合同未规定劳动报酬的，实行同工同酬；没有集体合同或者集体合同未规定劳动条件等标准的，适用国家有关规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10219, '《中华人民共和国劳动合同法》', '第十九条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十九条　劳动合同期限三个月以上不满一年的，试用期不得超过一个月；劳动合同期限一年以上不满三年的，试用期不得超过二个月；三年以上固定期限和无固定期限的劳动合同，试用期不得超过六个月。 　　同一用人单位与同一劳动者只能约定一次试用期。 　　以完成一定工作任务为期限的劳动合同或者劳动合同期限不满三个月的，不得约定试用期。 　　试用期包含在劳动合同期限内。劳动合同仅约定试用期的，试用期不成立，该期限为劳动合同期限。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10220, '《中华人民共和国劳动合同法》', '第二十条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第二十条　劳动者在试用期的工资不得低于本单位相同岗位最低档工资或者劳动合同约定工资的百分之八十，并不得低于用人单位所在地的最低工资标准。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10221, '《中华人民共和国劳动合同法》', '第二十一条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第二十一条　在试用期中，除劳动者有本法第三十九条和第四十条第一项、第二项规定的情形外，用人单位不得解除劳动合同。用人单位在试用期解除劳动合同的，应当向劳动者说明理由。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10222, '《中华人民共和国劳动合同法》', '第二十二条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第二十二条　用人单位为劳动者提供专项培训费用，对其进行专业技术培训的，可以与该劳动者订立协议，约定服务期。 　　劳动者违反服务期约定的，应当按照约定向用人单位支付违约金。违约金的数额不得超过用人单位提供的培训费用。用人单位要求劳动者支付的违约金不得超过服务期尚未履行部分所应分摊的培训费用。 　　用人单位与劳动者约定服务期的，不影响按照正常的工资调整机制提高劳动者在服务期期间的劳动报酬。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10223, '《中华人民共和国劳动合同法》', '第二十三条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第二十三条　用人单位与劳动者可以在劳动合同中约定保守用人单位的商业秘密和与知识产权相关的保密事项。 　　对负有保密义务的劳动者，用人单位可以在劳动合同或者保密协议中与劳动者约定竞业限制条款，并约定在解除或者终止劳动合同后，在竞业限制期限内按月给予劳动者经济补偿。劳动者违反竞业限制约定的，应当按照约定向用人单位支付违约金。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10224, '《中华人民共和国劳动合同法》', '第二十四条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第二十四条　竞业限制的人员限于用人单位的高级管理人员、高级技术人员和其他负有保密义务的人员。竞业限制的范围、地域、期限由用人单位与劳动者约定，竞业限制的约定不得违反法律、法规的规定。 　　在解除或者终止劳动合同后，前款规定的人员到与本单位生产或者经营同类产品、从事同类业务的有竞争关系的其他用人单位，或者自己开业生产或者经营同类产品、从事同类业务的竞业限制期限，不得超过二年。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10225, '《中华人民共和国劳动合同法》', '第二十五条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第二十五条　除本法第二十二条和第二十三条规定的情形外，用人单位不得与劳动者约定由劳动者承担违约金。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10226, '《中华人民共和国劳动合同法》', '第二十六条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第二十六条　下列劳动合同无效或者部分无效: 　　（一）以欺诈、胁迫的手段或者乘人之危，使对方在违背真实意思的情况下订立或者变更劳动合同的； 　　（二）用人单位免除自己的法定责任、排除劳动者权利的； 　　（三）违反法律、行政法规强制性规定的。 　　对劳动合同的无效或者部分无效有争议的，由劳动争议仲裁机构或者人民法院确认。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10227, '《中华人民共和国劳动合同法》', '第二十七条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第二十七条　劳动合同部分无效，不影响其他部分效力的，其他部分仍然有效。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10228, '《中华人民共和国劳动合同法》', '第二十八条', '劳动', '法律', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第二十八条　劳动合同被确认无效，劳动者已付出劳动的，用人单位应当向劳动者支付劳动报酬。劳动报酬的数额，参照本单位相同或者相近岗位劳动者的劳动报酬确定。 第三章　劳动合同的履行和变更 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10229, '《中华人民共和国劳动合同法》', '第二十九条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同的履行和变更　　', NULL, '第二十九条　用人单位与劳动者应当按照劳动合同的约定，全面履行各自的义务。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10230, '《中华人民共和国劳动合同法》', '第三十条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同的履行和变更　　', NULL, '第三十条　用人单位应当按照劳动合同约定和国家规定，向劳动者及时足额支付劳动报酬。 　　用人单位拖欠或者未足额支付劳动报酬的，劳动者可以依法向当地人民法院申请支付令，人民法院应当依法发出支付令。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10231, '《中华人民共和国劳动合同法》', '第三十一条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同的履行和变更　　', NULL, '第三十一条　用人单位应当严格执行劳动定额标准，不得强迫或者变相强迫劳动者加班。用人单位安排加班的，应当按照国家有关规定向劳动者支付加班费。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10232, '《中华人民共和国劳动合同法》', '第三十二条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同的履行和变更　　', NULL, '第三十二条　劳动者拒绝用人单位管理人员违章指挥、强令冒险作业的，不视为违反劳动合同。 　　劳动者对危害生命安全和身体健康的劳动条件，有权对用人单位提出批评、检举和控告。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10233, '《中华人民共和国劳动合同法》', '第三十三条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同的履行和变更　　', NULL, '第三十三条　用人单位变更名称、法定代表人、主要负责人或者投资人等事项，不影响劳动合同的履行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10234, '《中华人民共和国劳动合同法》', '第三十四条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同的履行和变更　　', NULL, '第三十四条　用人单位发生合并或者分立等情况，原劳动合同继续有效，劳动合同由承继其权利和义务的用人单位继续履行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10235, '《中华人民共和国劳动合同法》', '第三十五条', '劳动', '法律', NULL, NULL, '第三章 　劳动合同的履行和变更　　', NULL, '第三十五条　用人单位与劳动者协商一致，可以变更劳动合同约定的内容。变更劳动合同，应当采用书面形式。 　　变更后的劳动合同文本由用人单位和劳动者各执一份。 第四章　劳动合同的解除和终止 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10236, '《中华人民共和国劳动合同法》', '第三十六条', '劳动', '法律', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第三十六条　用人单位与劳动者协商一致，可以解除劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10237, '《中华人民共和国劳动合同法》', '第三十七条', '劳动', '法律', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第三十七条　劳动者提前三十日以书面形式通知用人单位，可以解除劳动合同。劳动者在试用期内提前三日通知用人单位，可以解除劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10238, '《中华人民共和国劳动合同法》', '第三十八条', '劳动', '法律', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第三十八条　用人单位有下列情形之一的，劳动者可以解除劳动合同: 　　（一）未按照劳动合同约定提供劳动保护或者劳动条件的； 　　（二）未及时足额支付劳动报酬的； 　　（三）未依法为劳动者缴纳社会保险费的； 　　（四）用人单位的规章制度违反法律、法规的规定，损害劳动者权益的； 　　（五）因本法第二十六条第一款规定的情形致使劳动合同无效的； 　　（六）法律、行政法规规定劳动者可以解除劳动合同的其他情形。 　　用人单位以暴力、威胁或者非法限制人身自由的手段强迫劳动者劳动的，或者用人单位违章指挥、强令冒险作业危及劳动者人身安全的，劳动者可以立即解除劳动合同，不需事先告知用人单位。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10239, '《中华人民共和国劳动合同法》', '第三十九条', '劳动', '法律', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第三十九条　劳动者有下列情形之一的，用人单位可以解除劳动合同: 　　（一）在试用期间被证明不符合录用条件的； 　　（二）严重违反用人单位的规章制度的； 　　（三）严重失职，营私舞弊，给用人单位造成重大损害的； 　　（四）劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的； 　　（五）因本法第二十六条第一款第一项规定的情形致使劳动合同无效的； 　　（六）被依法追究刑事责任的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10240, '《中华人民共和国劳动合同法》', '第四十条', '劳动', '法律', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第四十条　有下列情形之一的，用人单位提前三十日以书面形式通知劳动者本人或者额外支付劳动者一个月工资后，可以解除劳动合同: 　　（一）劳动者患病或者非因工负伤，在规定的医疗期满后不能从事原工作，也不能从事由用人单位另行安排的工作的； 　　（二）劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的； 　　（三）劳动合同订立时所依据的客观情况发生重大变化，致使劳动合同无法履行，经用人单位与劳动者协商，未能就变更劳动合同内容达成协议的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10241, '《中华人民共和国劳动合同法》', '第四十一条', '劳动', '法律', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第四十一条　有下列情形之一，需要裁减人员二十人以上或者裁减不足二十人但占企业职工总数百分之十以上的，用人单位提前三十日向工会或者全体职工说明情况，听取工会或者职工的意见后，裁减人员方案经向劳动行政部门报告，可以裁减人员: 　　（一）依照企业破产法规定进行重整的； 　　（二）生产经营发生严重困难的； 　　（三）企业转产、重大技术革新或者经营方式调整，经变更劳动合同后，仍需裁减人员的； 　　（四）其他因劳动合同订立时所依据的客观经济情况发生重大变化，致使劳动合同无法履行的。 　　裁减人员时，应当优先留用下列人员: 　　（一）与本单位订立较长期限的固定期限劳动合同的； 　　（二）与本单位订立无固定期限劳动合同的； 　　（三）家庭无其他就业人员，有需要扶养的老人或者未成年人的。 　　用人单位依照本条第一款规定裁减人员，在六个月内重新招用人员的，应当通知被裁减的人员，并在同等条件下优先招用被裁减的人员。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10242, '《中华人民共和国劳动合同法》', '第四十二条', '劳动', '法律', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第四十二条　劳动者有下列情形之一的，用人单位不得依照本法第四十条、第四十一条的规定解除劳动合同: 　　（一）从事接触职业病危害作业的劳动者未进行离岗前职业健康检查，或者疑似职业病病人在诊断或者医学观察期间的； 　　（二）在本单位患职业病或者因工负伤并被确认丧失或者部分丧失劳动能力的； 　　（三）患病或者非因工负伤，在规定的医疗期内的； 　　（四）女职工在孕期、产期、哺乳期的； 　　（五）在本单位连续工作满十五年，且距法定退休年龄不足五年的； 　　（六）法律、行政法规规定的其他情形。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10243, '《中华人民共和国劳动合同法》', '第四十三条', '劳动', '法律', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第四十三条　用人单位单方解除劳动合同，应当事先将理由通知工会。用人单位违反法律、行政法规规定或者劳动合同约定的，工会有权要求用人单位纠正。用人单位应当研究工会的意见，并将处理结果书面通知工会。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10244, '《中华人民共和国劳动合同法》', '第四十四条', '劳动', '法律', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第四十四条　有下列情形之一的，劳动合同终止: 　　（一）劳动合同期满的； 　　（二）劳动者开始依法享受基本养老保险待遇的； 　　（三）劳动者死亡，或者被人民法院宣告死亡或者宣告失踪的； 　　（四）用人单位被依法宣告破产的； 　　（五）用人单位被吊销营业执照、责令关闭、撤销或者用人单位决定提前解散的； 　　（六）法律、行政法规规定的其他情形。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10245, '《中华人民共和国劳动合同法》', '第四十五条', '劳动', '法律', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第四十五条　劳动合同期满，有本法第四十二条规定情形之一的，劳动合同应当续延至相应的情形消失时终止。但是，本法第四十二条第二项规定丧失或者部分丧失劳动能力劳动者的劳动合同的终止，按照国家有关工伤保险的规定执行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10246, '《中华人民共和国劳动合同法》', '第四十六条', '劳动', '法律', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第四十六条　有下列情形之一的，用人单位应当向劳动者支付经济补偿: 　　（一）劳动者依照本法第三十八条规定解除劳动合同的； 　　（二）用人单位依照本法第三十六条规定向劳动者提出解除劳动合同并与劳动者协商一致解除劳动合同的； 　　（三）用人单位依照本法第四十条规定解除劳动合同的； 　　（四）用人单位依照本法第四十一条第一款规定解除劳动合同的； 　　（五）除用人单位维持或者提高劳动合同约定条件续订劳动合同，劳动者不同意续订的情形外，依照本法第四十四条第一项规定终止固定期限劳动合同的； 　　（六）依照本法第四十四条第四项、第五项规定终止劳动合同的； 　　（七）法律、行政法规规定的其他情形。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10247, '《中华人民共和国劳动合同法》', '第四十七条', '劳动', '法律', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第四十七条　经济补偿按劳动者在本单位工作的年限，每满一年支付一个月工资的标准向劳动者支付。六个月以上不满一年的，按一年计算；不满六个月的，向劳动者支付半个月工资的经济补偿。 　　劳动者月工资高于用人单位所在直辖市、设区的市级人民政府公布的本地区上年度职工月平均工资三倍的，向其支付经济补偿的标准按职工月平均工资三倍的数额支付，向其支付经济补偿的年限最高不超过十二年。 　　本条所称月工资是指劳动者在劳动合同解除或者终止前十二个月的平均工资。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10248, '《中华人民共和国劳动合同法》', '第四十八条', '劳动', '法律', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第四十八条　用人单位违反本法规定解除或者终止劳动合同，劳动者要求继续履行劳动合同的，用人单位应当继续履行；劳动者不要求继续履行劳动合同或者劳动合同已经不能继续履行的，用人单位应当依照本法第八十七条规定支付赔偿金。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10249, '《中华人民共和国劳动合同法》', '第四十九条', '劳动', '法律', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第四十九条　国家采取措施，建立健全劳动者社会保险关系跨地区转移接续制度。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10250, '《中华人民共和国劳动合同法》', '第五十条', '劳动', '法律', NULL, NULL, '第四章 　劳动合同的解除和终止　　', NULL, '第五十条　用人单位应当在解除或者终止劳动合同时出具解除或者终止劳动合同的证明，并在十五日内为劳动者办理档案和社会保险关系转移手续。 　　劳动者应当按照双方约定，办理工作交接。用人单位依照本法有关规定应当向劳动者支付经济补偿的，在办结工作交接时支付。 　　用人单位对已经解除或者终止的劳动合同的文本，至少保存二年备查。 第五章　特别规定 第一节　集体合同 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10251, '《中华人民共和国劳动合同法》', '第五十一条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第一节 　集体合同　　', '第五十一条　企业职工一方与用人单位通过平等协商，可以就劳动报酬、工作时间、休息休假、劳动安全卫生、保险福利等事项订立集体合同。集体合同草案应当提交职工代表大会或者全体职工讨论通过。 　　集体合同由工会代表企业职工一方与用人单位订立；尚未建立工会的用人单位，由上级工会指导劳动者推举的代表与用人单位订立。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10252, '《中华人民共和国劳动合同法》', '第五十二条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第一节 　集体合同　　', '第五十二条　企业职工一方与用人单位可以订立劳动安全卫生、女职工权益保护、工资调整机制等专项集体合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10253, '《中华人民共和国劳动合同法》', '第五十三条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第一节 　集体合同　　', '第五十三条　在县级以下区域内，建筑业、采矿业、餐饮服务业等行业可以由工会与企业方面代表订立行业性集体合同，或者订立区域性集体合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10254, '《中华人民共和国劳动合同法》', '第五十四条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第一节 　集体合同　　', '第五十四条　集体合同订立后，应当报送劳动行政部门；劳动行政部门自收到集体合同文本之日起十五日内未提出异议的，集体合同即行生效。 　　依法订立的集体合同对用人单位和劳动者具有约束力。行业性、区域性集体合同对当地本行业、本区域的用人单位和劳动者具有约束力。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10255, '《中华人民共和国劳动合同法》', '第五十五条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第一节 　集体合同　　', '第五十五条　集体合同中劳动报酬和劳动条件等标准不得低于当地人民政府规定的最低标准；用人单位与劳动者订立的劳动合同中劳动报酬和劳动条件等标准不得低于集体合同规定的标准。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10256, '《中华人民共和国劳动合同法》', '第五十六条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第一节 　集体合同　　', '第五十六条　用人单位违反集体合同，侵犯职工劳动权益的，工会可以依法要求用人单位承担责任；因履行集体合同发生争议，经协商解决不成的，工会可以依法申请仲裁、提起诉讼。 第二节　劳务派遣 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10257, '《中华人民共和国劳动合同法》', '第五十七条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第五十七条　经营劳务派遣业务应当具备下列条件: 　　（一）注册资本不得少于人民币二百万元； 　　（二）有与开展业务相适应的固定的经营场所和设施； 　　（三）有符合法律、行政法规规定的劳务派遣管理制度； 　　（四）法律、行政法规规定的其他条件。 　　经营劳务派遣业务，应当向劳动行政部门依法申请行政许可；经许可的，依法办理相应的公司登记。未经许可，任何单位和个人不得经营劳务派遣业务。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10258, '《中华人民共和国劳动合同法》', '第五十八条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第五十八条　劳务派遣单位是本法所称用人单位，应当履行用人单位对劳动者的义务。劳务派遣单位与被派遣劳动者订立的劳动合同，除应当载明本法第十七条规定的事项外，还应当载明被派遣劳动者的用工单位以及派遣期限、工作岗位等情况。 　　劳务派遣单位应当与被派遣劳动者订立二年以上的固定期限劳动合同，按月支付劳动报酬；被派遣劳动者在无工作期间，劳务派遣单位应当按照所在地人民政府规定的最低工资标准，向其按月支付报酬。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10259, '《中华人民共和国劳动合同法》', '第五十九条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第五十九条　劳务派遣单位派遣劳动者应当与接受以劳务派遣形式用工的单位（以下称用工单位）订立劳务派遣协议。劳务派遣协议应当约定派遣岗位和人员数量、派遣期限、劳动报酬和社会保险费的数额与支付方式以及违反协议的责任。 　　用工单位应当根据工作岗位的实际需要与劳务派遣单位确定派遣期限，不得将连续用工期限分割订立数个短期劳务派遣协议。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10260, '《中华人民共和国劳动合同法》', '第六十条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第六十条　劳务派遣单位应当将劳务派遣协议的内容告知被派遣劳动者。 　　劳务派遣单位不得克扣用工单位按照劳务派遣协议支付给被派遣劳动者的劳动报酬。 　　劳务派遣单位和用工单位不得向被派遣劳动者收取费用。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10261, '《中华人民共和国劳动合同法》', '第六十一条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第六十一条　劳务派遣单位跨地区派遣劳动者的，被派遣劳动者享有的劳动报酬和劳动条件，按照用工单位所在地的标准执行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10262, '《中华人民共和国劳动合同法》', '第六十二条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第六十二条　用工单位应当履行下列义务: 　　（一）执行国家劳动标准，提供相应的劳动条件和劳动保护； 　　（二）告知被派遣劳动者的工作要求和劳动报酬； 　　（三）支付加班费、绩效奖金，提供与工作岗位相关的福利待遇； 　　（四）对在岗被派遣劳动者进行工作岗位所必需的培训； 　　（五）连续用工的，实行正常的工资调整机制。 　　用工单位不得将被派遣劳动者再派遣到其他用人单位。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10263, '《中华人民共和国劳动合同法》', '第六十三条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第六十三条　被派遣劳动者享有与用工单位的劳动者同工同酬的权利。用工单位应当按照同工同酬原则，对被派遣劳动者与本单位同类岗位的劳动者实行相同的劳动报酬分配办法。用工单位无同类岗位劳动者的，参照用工单位所在地相同或者相近岗位劳动者的劳动报酬确定。 　　劳务派遣单位与被派遣劳动者订立的劳动合同和与用工单位订立的劳务派遣协议，载明或者约定的向被派遣劳动者支付的劳动报酬应当符合前款规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10264, '《中华人民共和国劳动合同法》', '第六十四条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第六十四条　被派遣劳动者有权在劳务派遣单位或者用工单位依法参加或者组织工会，维护自身的合法权益。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10265, '《中华人民共和国劳动合同法》', '第六十五条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第六十五条　被派遣劳动者可以依照本法第三十六条、第三十八条的规定与劳务派遣单位解除劳动合同。 　　被派遣劳动者有本法第三十九条和第四十条第一项、第二项规定情形的，用工单位可以将劳动者退回劳务派遣单位，劳务派遣单位依照本法有关规定，可以与劳动者解除劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10266, '《中华人民共和国劳动合同法》', '第六十六条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第六十六条　劳动合同用工是我国的企业基本用工形式。劳务派遣用工是补充形式，只能在临时性、辅助性或者替代性的工作岗位上实施。 　　前款规定的临时性工作岗位是指存续时间不超过六个月的岗位；辅助性工作岗位是指为主营业务岗位提供服务的非主营业务岗位；替代性工作岗位是指用工单位的劳动者因脱产学习、休假等原因无法工作的一定期间内，可以由其他劳动者替代工作的岗位。 　　用工单位应当严格控制劳务派遣用工数量，不得超过其用工总量的一定比例，具体比例由国务院劳动行政部门规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10267, '《中华人民共和国劳动合同法》', '第六十七条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第二节 　劳务派遣　　', '第六十七条　用人单位不得设立劳务派遣单位向本单位或者所属单位派遣劳动者。 第三节　非全日制用工 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10268, '《中华人民共和国劳动合同法》', '第六十八条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第三节 　非全日制用工　　', '第六十八条　非全日制用工，是指以小时计酬为主，劳动者在同一用人单位一般平均每日工作时间不超过四小时，每周工作时间累计不超过二十四小时的用工形式。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10269, '《中华人民共和国劳动合同法》', '第六十九条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第三节 　非全日制用工　　', '第六十九条　非全日制用工双方当事人可以订立口头协议。 　　从事非全日制用工的劳动者可以与一个或者一个以上用人单位订立劳动合同；但是，后订立的劳动合同不得影响先订立的劳动合同的履行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10270, '《中华人民共和国劳动合同法》', '第七十条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第三节 　非全日制用工　　', '第七十条　非全日制用工双方当事人不得约定试用期。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10271, '《中华人民共和国劳动合同法》', '第七十一条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第三节 　非全日制用工　　', '第七十一条　非全日制用工双方当事人任何一方都可以随时通知对方终止用工。终止用工，用人单位不向劳动者支付经济补偿。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10272, '《中华人民共和国劳动合同法》', '第七十二条', '劳动', '法律', NULL, NULL, '第五章 　特别规定', '第三节 　非全日制用工　　', '第七十二条　非全日制用工小时计酬标准不得低于用人单位所在地人民政府规定的最低小时工资标准。 　　非全日制用工劳动报酬结算支付周期最长不得超过十五日。 第六章　监督检查 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10273, '《中华人民共和国劳动合同法》', '第七十三条', '劳动', '法律', NULL, NULL, '第六章 　监督检查　　', NULL, '第七十三条　国务院劳动行政部门负责全国劳动合同制度实施的监督管理。 　　县级以上地方人民政府劳动行政部门负责本行政区域内劳动合同制度实施的监督管理。 　　县级以上各级人民政府劳动行政部门在劳动合同制度实施的监督管理工作中，应当听取工会、企业方面代表以及有关行业主管部门的意见。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10274, '《中华人民共和国劳动合同法》', '第七十四条', '劳动', '法律', NULL, NULL, '第六章 　监督检查　　', NULL, '第七十四条　县级以上地方人民政府劳动行政部门依法对下列实施劳动合同制度的情况进行监督检查: 　　（一）用人单位制定直接涉及劳动者切身利益的规章制度及其执行的情况； 　　（二）用人单位与劳动者订立和解除劳动合同的情况； 　　（三）劳务派遣单位和用工单位遵守劳务派遣有关规定的情况； 　　（四）用人单位遵守国家关于劳动者工作时间和休息休假规定的情况； 　　（五）用人单位支付劳动合同约定的劳动报酬和执行最低工资标准的情况； 　　（六）用人单位参加各项社会保险和缴纳社会保险费的情况； 　　（七）法律、法规规定的其他劳动监察事项。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10275, '《中华人民共和国劳动合同法》', '第七十五条', '劳动', '法律', NULL, NULL, '第六章 　监督检查　　', NULL, '第七十五条　县级以上地方人民政府劳动行政部门实施监督检查时，有权查阅与劳动合同、集体合同有关的材料，有权对劳动场所进行实地检查，用人单位和劳动者都应当如实提供有关情况和材料。 　　劳动行政部门的工作人员进行监督检查，应当出示证件，依法行使职权，文明执法。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10276, '《中华人民共和国劳动合同法》', '第七十六条', '劳动', '法律', NULL, NULL, '第六章 　监督检查　　', NULL, '第七十六条　县级以上人民政府建设、卫生、安全生产监督管理等有关主管部门在各自职责范围内，对用人单位执行劳动合同制度的情况进行监督管理。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10277, '《中华人民共和国劳动合同法》', '第七十七条', '劳动', '法律', NULL, NULL, '第六章 　监督检查　　', NULL, '第七十七条　劳动者合法权益受到侵害的，有权要求有关部门依法处理，或者依法申请仲裁、提起诉讼。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10278, '《中华人民共和国劳动合同法》', '第七十八条', '劳动', '法律', NULL, NULL, '第六章 　监督检查　　', NULL, '第七十八条　工会依法维护劳动者的合法权益，对用人单位履行劳动合同、集体合同的情况进行监督。用人单位违反劳动法律、法规和劳动合同、集体合同的，工会有权提出意见或者要求纠正；劳动者申请仲裁、提起诉讼的，工会依法给予支持和帮助。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10279, '《中华人民共和国劳动合同法》', '第七十九条', '劳动', '法律', NULL, NULL, '第六章 　监督检查　　', NULL, '第七十九条　任何组织或者个人对违反本法的行为都有权举报，县级以上人民政府劳动行政部门应当及时核实、处理，并对举报有功人员给予奖励。 第七章　法律责任 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10280, '《中华人民共和国劳动合同法》', '第八十条', '劳动', '法律', NULL, NULL, '第七章 　法律责任　　', NULL, '第八十条　用人单位直接涉及劳动者切身利益的规章制度违反法律、法规规定的，由劳动行政部门责令改正，给予警告；给劳动者造成损害的，应当承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10281, '《中华人民共和国劳动合同法》', '第八十一条', '劳动', '法律', NULL, NULL, '第七章 　法律责任　　', NULL, '第八十一条　用人单位提供的劳动合同文本未载明本法规定的劳动合同必备条款或者用人单位未将劳动合同文本交付劳动者的，由劳动行政部门责令改正；给劳动者造成损害的，应当承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10282, '《中华人民共和国劳动合同法》', '第八十二条', '劳动', '法律', NULL, NULL, '第七章 　法律责任　　', NULL, '第八十二条　用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当向劳动者每月支付二倍的工资。 　　用人单位违反本法规定不与劳动者订立无固定期限劳动合同的，自应当订立无固定期限劳动合同之日起向劳动者每月支付二倍的工资。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10283, '《中华人民共和国劳动合同法》', '第八十三条', '劳动', '法律', NULL, NULL, '第七章 　法律责任　　', NULL, '第八十三条　用人单位违反本法规定与劳动者约定试用期的，由劳动行政部门责令改正；违法约定的试用期已经履行的，由用人单位以劳动者试用期满月工资为标准，按已经履行的超过法定试用期的期间向劳动者支付赔偿金。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10284, '《中华人民共和国劳动合同法》', '第八十四条', '劳动', '法律', NULL, NULL, '第七章 　法律责任　　', NULL, '第八十四条　用人单位违反本法规定，扣押劳动者居民身份证等证件的，由劳动行政部门责令限期退还劳动者本人，并依照有关法律规定给予处罚。 　　用人单位违反本法规定，以担保或者其他名义向劳动者收取财物的，由劳动行政部门责令限期退还劳动者本人，并以每人五百元以上二千元以下的标准处以罚款；给劳动者造成损害的，应当承担赔偿责任。 　　劳动者依法解除或者终止劳动合同，用人单位扣押劳动者档案或者其他物品的，依照前款规定处罚。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10285, '《中华人民共和国劳动合同法》', '第八十五条', '劳动', '法律', NULL, NULL, '第七章 　法律责任　　', NULL, '第八十五条　用人单位有下列情形之一的，由劳动行政部门责令限期支付劳动报酬、加班费或者经济补偿；劳动报酬低于当地最低工资标准的，应当支付其差额部分；逾期不支付的，责令用人单位按应付金额百分之五十以上百分之一百以下的标准向劳动者加付赔偿金: 　　（一）未按照劳动合同的约定或者国家规定及时足额支付劳动者劳动报酬的； 　　（二）低于当地最低工资标准支付劳动者工资的； 　　（三）安排加班不支付加班费的； 　　（四）解除或者终止劳动合同，未依照本法规定向劳动者支付经济补偿的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10286, '《中华人民共和国劳动合同法》', '第八十六条', '劳动', '法律', NULL, NULL, '第七章 　法律责任　　', NULL, '第八十六条　劳动合同依照本法第二十六条规定被确认无效，给对方造成损害的，有过错的一方应当承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10287, '《中华人民共和国劳动合同法》', '第八十七条', '劳动', '法律', NULL, NULL, '第七章 　法律责任　　', NULL, '第八十七条　用人单位违反本法规定解除或者终止劳动合同的，应当依照本法第四十七条规定的经济补偿标准的二倍向劳动者支付赔偿金。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10288, '《中华人民共和国劳动合同法》', '第八十八条', '劳动', '法律', NULL, NULL, '第七章 　法律责任　　', NULL, '第八十八条　用人单位有下列情形之一的，依法给予行政处罚；构成犯罪的，依法追究刑事责任；给劳动者造成损害的，应当承担赔偿责任: 　　（一）以暴力、威胁或者非法限制人身自由的手段强迫劳动的； 　　（二）违章指挥或者强令冒险作业危及劳动者人身安全的； 　　（三）侮辱、体罚、殴打、非法搜查或者拘禁劳动者的； 　　（四）劳动条件恶劣、环境污染严重，给劳动者身心健康造成严重损害的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10289, '《中华人民共和国劳动合同法》', '第八十九条', '劳动', '法律', NULL, NULL, '第七章 　法律责任　　', NULL, '第八十九条　用人单位违反本法规定未向劳动者出具解除或者终止劳动合同的书面证明，由劳动行政部门责令改正；给劳动者造成损害的，应当承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10290, '《中华人民共和国劳动合同法》', '第九十条', '劳动', '法律', NULL, NULL, '第七章 　法律责任　　', NULL, '第九十条　劳动者违反本法规定解除劳动合同，或者违反劳动合同中约定的保密义务或者竞业限制，给用人单位造成损失的，应当承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10291, '《中华人民共和国劳动合同法》', '第九十一条', '劳动', '法律', NULL, NULL, '第七章 　法律责任　　', NULL, '第九十一条　用人单位招用与其他用人单位尚未解除或者终止劳动合同的劳动者，给其他用人单位造成损失的，应当承担连带赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10292, '《中华人民共和国劳动合同法》', '第九十二条', '劳动', '法律', NULL, NULL, '第七章 　法律责任　　', NULL, '第九十二条　违反本法规定，未经许可，擅自经营劳务派遣业务的，由劳动行政部门责令停止违法行为，没收违法所得，并处违法所得一倍以上五倍以下的罚款；没有违法所得的，可以处五万元以下的罚款。 　　劳务派遣单位、用工单位违反本法有关劳务派遣规定的，由劳动行政部门责令限期改正；逾期不改正的，以每人五千元以上一万元以下的标准处以罚款，对劳务派遣单位，吊销其劳务派遣业务经营许可证。用工单位给被派遣劳动者造成损害的，劳务派遣单位与用工单位承担连带赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10293, '《中华人民共和国劳动合同法》', '第九十三条', '劳动', '法律', NULL, NULL, '第七章 　法律责任　　', NULL, '第九十三条　对不具备合法经营资格的用人单位的违法犯罪行为，依法追究法律责任；劳动者已经付出劳动的，该单位或者其出资人应当依照本法有关规定向劳动者支付劳动报酬、经济补偿、赔偿金；给劳动者造成损害的，应当承担赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10294, '《中华人民共和国劳动合同法》', '第九十四条', '劳动', '法律', NULL, NULL, '第七章 　法律责任　　', NULL, '第九十四条　个人承包经营违反本法规定招用劳动者，给劳动者造成损害的，发包的组织与个人承包经营者承担连带赔偿责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10295, '《中华人民共和国劳动合同法》', '第九十五条', '劳动', '法律', NULL, NULL, '第七章 　法律责任　　', NULL, '第九十五条　劳动行政部门和其他有关主管部门及其工作人员玩忽职守、不履行法定职责，或者违法行使职权，给劳动者或者用人单位造成损害的，应当承担赔偿责任；对直接负责的主管人员和其他直接责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任。 第八章　附则 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10296, '《中华人民共和国劳动合同法》', '第九十六条', '劳动', '法律', NULL, NULL, '第八章 　附则　　', NULL, '第九十六条　事业单位与实行聘用制的工作人员订立、履行、变更、解除或者终止劳动合同，法律、行政法规或者国务院另有规定的，依照其规定；未作规定的，依照本法有关规定执行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10297, '《中华人民共和国劳动合同法》', '第九十七条', '劳动', '法律', NULL, NULL, '第八章 　附则　　', NULL, '第九十七条　本法施行前已依法订立且在本法施行之日存续的劳动合同，继续履行；本法第十四条第二款第三项规定连续订立固定期限劳动合同的次数，自本法施行后续订固定期限劳动合同时开始计算。 　　本法施行前已建立劳动关系，尚未订立书面劳动合同的，应当自本法施行之日起一个月内订立。 　　本法施行之日存续的劳动合同在本法施行后解除或者终止，依照本法第四十六条规定应当支付经济补偿的，经济补偿年限自本法施行之日起计算；本法施行前按照当时有关规定，用人单位应当向劳动者支付经济补偿的，按照当时有关规定执行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10298, '《中华人民共和国劳动合同法》', '第九十八条', '劳动', '法律', NULL, NULL, '第八章 　附则　　', NULL, '第九十八条　本法自2008年1月1日起施行。 分享 打印本页 关闭窗口', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10301, '《中华人民共和国劳动合同法实施条例》', '第一条', '劳动', '行政法规', NULL, NULL, '第一章 　总　则　　', NULL, '第一条　为了贯彻实施《中华人民共和国劳动合同法》（以下简称劳动合同法），制定本条例。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10302, '《中华人民共和国劳动合同法实施条例》', '第二条', '劳动', '行政法规', NULL, NULL, '第一章 　总　则　　', NULL, '第二条　各级人民政府和县级以上人民政府劳动行政等有关部门以及工会等组织，应当采取措施，推动劳动合同法的贯彻实施，促进劳动关系的和谐。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10303, '《中华人民共和国劳动合同法实施条例》', '第三条', '劳动', '行政法规', NULL, NULL, '第一章 　总　则　　', NULL, '第三条　依法成立的会计师事务所、律师事务所等合伙组织和基金会，属于劳动合同法规定的用人单位。 　　第二章　劳动合同的订立 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10304, '《中华人民共和国劳动合同法实施条例》', '第四条', '劳动', '行政法规', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第四条　劳动合同法规定的用人单位设立的分支机构，依法取得营业执照或者登记证书的，可以作为用人单位与劳动者订立劳动合同；未依法取得营业执照或者登记证书的，受用人单位委托可以与劳动者订立劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10305, '《中华人民共和国劳动合同法实施条例》', '第五条', '劳动', '行政法规', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第五条　自用工之日起一个月内，经用人单位书面通知后，劳动者不与用人单位订立书面劳动合同的，用人单位应当书面通知劳动者终止劳动关系，无需向劳动者支付经济补偿，但是应当依法向劳动者支付其实际工作时间的劳动报酬。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10306, '《中华人民共和国劳动合同法实施条例》', '第六条', '劳动', '行政法规', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第六条　用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同的，应当依照劳动合同法第八十二条的规定向劳动者每月支付两倍的工资，并与劳动者补订书面劳动合同；劳动者不与用人单位订立书面劳动合同的，用人单位应当书面通知劳动者终止劳动关系，并依照劳动合同法第四十七条的规定支付经济补偿。 　　前款规定的用人单位向劳动者每月支付两倍工资的起算时间为用工之日起满一个月的次日，截止时间为补订书面劳动合同的前一日。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10307, '《中华人民共和国劳动合同法实施条例》', '第七条', '劳动', '行政法规', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第七条　用人单位自用工之日起满一年未与劳动者订立书面劳动合同的，自用工之日起满一个月的次日至满一年的前一日应当依照劳动合同法第八十二条的规定向劳动者每月支付两倍的工资，并视为自用工之日起满一年的当日已经与劳动者订立无固定期限劳动合同，应当立即与劳动者补订书面劳动合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10308, '《中华人民共和国劳动合同法实施条例》', '第八条', '劳动', '行政法规', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第八条　劳动合同法第七条规定的职工名册，应当包括劳动者姓名、性别、公民身份号码、户籍地址及现住址、联系方式、用工形式、用工起始时间、劳动合同期限等内容。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10309, '《中华人民共和国劳动合同法实施条例》', '第九条', '劳动', '行政法规', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第九条　劳动合同法第十四条第二款规定的连续工作满１０年的起始时间，应当自用人单位用工之日起计算，包括劳动合同法施行前的工作年限。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10310, '《中华人民共和国劳动合同法实施条例》', '第十条', '劳动', '行政法规', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十条　劳动者非因本人原因从原用人单位被安排到新用人单位工作的，劳动者在原用人单位的工作年限合并计算为新用人单位的工作年限。原用人单位已经向劳动者支付经济补偿的，新用人单位在依法解除、终止劳动合同计算支付经济补偿的工作年限时，不再计算劳动者在原用人单位的工作年限。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10311, '《中华人民共和国劳动合同法实施条例》', '第十一条', '劳动', '行政法规', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十一条　除劳动者与用人单位协商一致的情形外，劳动者依照劳动合同法第十四条第二款的规定，提出订立无固定期限劳动合同的，用人单位应当与其订立无固定期限劳动合同。对劳动合同的内容，双方应当按照合法、公平、平等自愿、协商一致、诚实信用的原则协商确定；对协商不一致的内容，依照劳动合同法第十八条的规定执行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10312, '《中华人民共和国劳动合同法实施条例》', '第十二条', '劳动', '行政法规', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十二条　地方各级人民政府及县级以上地方人民政府有关部门为安置就业困难人员提供的给予岗位补贴和社会保险补贴的公益性岗位，其劳动合同不适用劳动合同法有关无固定期限劳动合同的规定以及支付经济补偿的规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10313, '《中华人民共和国劳动合同法实施条例》', '第十三条', '劳动', '行政法规', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十三条　用人单位与劳动者不得在劳动合同法第四十四条规定的劳动合同终止情形之外约定其他的劳动合同终止条件。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10314, '《中华人民共和国劳动合同法实施条例》', '第十四条', '劳动', '行政法规', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十四条　劳动合同履行地与用人单位注册地不一致的，有关劳动者的最低工资标准、劳动保护、劳动条件、职业危害防护和本地区上年度职工月平均工资标准等事项，按照劳动合同履行地的有关规定执行；用人单位注册地的有关标准高于劳动合同履行地的有关标准，且用人单位与劳动者约定按照用人单位注册地的有关规定执行的，从其约定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10315, '《中华人民共和国劳动合同法实施条例》', '第十五条', '劳动', '行政法规', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十五条　劳动者在试用期的工资不得低于本单位相同岗位最低档工资的８０％或者不得低于劳动合同约定工资的８０％，并不得低于用人单位所在地的最低工资标准。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10316, '《中华人民共和国劳动合同法实施条例》', '第十六条', '劳动', '行政法规', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十六条　劳动合同法第二十二条第二款规定的培训费用，包括用人单位为了对劳动者进行专业技术培训而支付的有凭证的培训费用、培训期间的差旅费用以及因培训产生的用于该劳动者的其他直接费用。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10317, '《中华人民共和国劳动合同法实施条例》', '第十七条', '劳动', '行政法规', NULL, NULL, '第二章 　劳动合同的订立　　', NULL, '第十七条　劳动合同期满，但是用人单位与劳动者依照劳动合同法第二十二条的规定约定的服务期尚未到期的，劳动合同应当续延至服务期满；双方另有约定的，从其约定。 　　第三章　劳动合同的解除和终止 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10318, '《中华人民共和国劳动合同法实施条例》', '第十八条', '劳动', '行政法规', NULL, NULL, '第三章 　劳动合同的解除和终止　　', NULL, '第十八条　有下列情形之一的，依照劳动合同法规定的条件、程序，劳动者可以与用人单位解除固定期限劳动合同、无固定期限劳动合同或者以完成一定工作任务为期限的劳动合同： 　　（一）劳动者与用人单位协商一致的； 　　（二）劳动者提前３０日以书面形式通知用人单位的； 　　（三）劳动者在试用期内提前３日通知用人单位的； 　　（四）用人单位未按照劳动合同约定提供劳动保护或者劳动条件的； 　　（五）用人单位未及时足额支付劳动报酬的； 　　（六）用人单位未依法为劳动者缴纳社会保险费的； 　　（七）用人单位的规章制度违反法律、法规的规定，损害劳动者权益的； 　　（八）用人单位以欺诈、胁迫的手段或者乘人之危，使劳动者在违背真实意思的情况下订立或者变更劳动合同的； 　　（九）用人单位在劳动合同中免除自己的法定责任、排除劳动者权利的； 　　（十）用人单位违反法律、行政法规强制性规定的； 　　（十一）用人单位以暴力、威胁或者非法限制人身自由的手段强迫劳动者劳动的； 　　（十二）用人单位违章指挥、强令冒险作业危及劳动者人身安全的； 　　（十三）法律、行政法规规定劳动者可以解除劳动合同的其他情形。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10319, '《中华人民共和国劳动合同法实施条例》', '第十九条', '劳动', '行政法规', NULL, NULL, '第三章 　劳动合同的解除和终止　　', NULL, '第十九条　有下列情形之一的，依照劳动合同法规定的条件、程序，用人单位可以与劳动者解除固定期限劳动合同、无固定期限劳动合同或者以完成一定工作任务为期限的劳动合同： 　　（一）用人单位与劳动者协商一致的； 　　（二）劳动者在试用期间被证明不符合录用条件的； 　　（三）劳动者严重违反用人单位的规章制度的； 　　（四）劳动者严重失职，营私舞弊，给用人单位造成重大损害的； 　　（五）劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的； 　　（六）劳动者以欺诈、胁迫的手段或者乘人之危，使用人单位在违背真实意思的情况下订立或者变更劳动合同的； 　　（七）劳动者被依法追究刑事责任的； 　　（八）劳动者患病或者非因工负伤，在规定的医疗期满后不能从事原工作，也不能从事由用人单位另行安排的工作的； 　　（九）劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的； 　　（十）劳动合同订立时所依据的客观情况发生重大变化，致使劳动合同无法履行，经用人单位与劳动者协商，未能就变更劳动合同内容达成协议的； 　　（十一）用人单位依照企业破产法规定进行重整的； 　　（十二）用人单位生产经营发生严重困难的； 　　（十三）企业转产、重大技术革新或者经营方式调整，经变更劳动合同后，仍需裁减人员的； 　　（十四）其他因劳动合同订立时所依据的客观经济情况发生重大变化，致使劳动合同无法履行的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10320, '《中华人民共和国劳动合同法实施条例》', '第二十条', '劳动', '行政法规', NULL, NULL, '第三章 　劳动合同的解除和终止　　', NULL, '第二十条　用人单位依照劳动合同法第四十条的规定，选择额外支付劳动者一个月工资解除劳动合同的，其额外支付的工资应当按照该劳动者上一个月的工资标准确定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10321, '《中华人民共和国劳动合同法实施条例》', '第二十一条', '劳动', '行政法规', NULL, NULL, '第三章 　劳动合同的解除和终止　　', NULL, '第二十一条　劳动者达到法定退休年龄的，劳动合同终止。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10322, '《中华人民共和国劳动合同法实施条例》', '第二十二条', '劳动', '行政法规', NULL, NULL, '第三章 　劳动合同的解除和终止　　', NULL, '第二十二条　以完成一定工作任务为期限的劳动合同因任务完成而终止的，用人单位应当依照劳动合同法第四十七条的规定向劳动者支付经济补偿。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10323, '《中华人民共和国劳动合同法实施条例》', '第二十三条', '劳动', '行政法规', NULL, NULL, '第三章 　劳动合同的解除和终止　　', NULL, '第二十三条　用人单位依法终止工伤职工的劳动合同的，除依照劳动合同法第四十七条的规定支付经济补偿外，还应当依照国家有关工伤保险的规定支付一次性工伤医疗补助金和伤残就业补助金。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10324, '《中华人民共和国劳动合同法实施条例》', '第二十四条', '劳动', '行政法规', NULL, NULL, '第三章 　劳动合同的解除和终止　　', NULL, '第二十四条　用人单位出具的解除、终止劳动合同的证明，应当写明劳动合同期限、解除或者终止劳动合同的日期、工作岗位、在本单位的工作年限。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10325, '《中华人民共和国劳动合同法实施条例》', '第二十五条', '劳动', '行政法规', NULL, NULL, '第三章 　劳动合同的解除和终止　　', NULL, '第二十五条　用人单位违反劳动合同法的规定解除或者终止劳动合同，依照劳动合同法第八十七条的规定支付了赔偿金的，不再支付经济补偿。赔偿金的计算年限自用工之日起计算。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10326, '《中华人民共和国劳动合同法实施条例》', '第二十六条', '劳动', '行政法规', NULL, NULL, '第三章 　劳动合同的解除和终止　　', NULL, '第二十六条　用人单位与劳动者约定了服务期，劳动者依照劳动合同法第三十八条的规定解除劳动合同的，不属于违反服务期的约定，用人单位不得要求劳动者支付违约金。 　　有下列情形之一，用人单位与劳动者解除约定服务期的劳动合同的，劳动者应当按照劳动合同的约定向用人单位支付违约金： 　　（一）劳动者严重违反用人单位的规章制度的； 　　（二）劳动者严重失职，营私舞弊，给用人单位造成重大损害的； 　　（三）劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的； 　　（四）劳动者以欺诈、胁迫的手段或者乘人之危，使用人单位在违背真实意思的情况下订立或者变更劳动合同的； 　　（五）劳动者被依法追究刑事责任的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10327, '《中华人民共和国劳动合同法实施条例》', '第二十七条', '劳动', '行政法规', NULL, NULL, '第三章 　劳动合同的解除和终止　　', NULL, '第二十七条　劳动合同法第四十七条规定的经济补偿的月工资按照劳动者应得工资计算，包括计时工资或者计件工资以及奖金、津贴和补贴等货币性收入。劳动者在劳动合同解除或者终止前１２个月的平均工资低于当地最低工资标准的，按照当地最低工资标准计算。劳动者工作不满１２个月的，按照实际工作的月数计算平均工资。 　　第四章　劳务派遣特别规定 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10328, '《中华人民共和国劳动合同法实施条例》', '第二十八条', '劳动', '行政法规', NULL, NULL, '第四章 　劳务派遣特别规定　　', NULL, '第二十八条　用人单位或者其所属单位出资或者合伙设立的劳务派遣单位，向本单位或者所属单位派遣劳动者的，属于劳动合同法第六十七条规定的不得设立的劳务派遣单位。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10329, '《中华人民共和国劳动合同法实施条例》', '第二十九条', '劳动', '行政法规', NULL, NULL, '第四章 　劳务派遣特别规定　　', NULL, '第二十九条　用工单位应当履行劳动合同法第六十二条规定的义务，维护被派遣劳动者的合法权益。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10330, '《中华人民共和国劳动合同法实施条例》', '第三十条', '劳动', '行政法规', NULL, NULL, '第四章 　劳务派遣特别规定　　', NULL, '第三十条　劳务派遣单位不得以非全日制用工形式招用被派遣劳动者。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10331, '《中华人民共和国劳动合同法实施条例》', '第三十一条', '劳动', '行政法规', NULL, NULL, '第四章 　劳务派遣特别规定　　', NULL, '第三十一条　劳务派遣单位或者被派遣劳动者依法解除、终止劳动合同的经济补偿，依照劳动合同法第四十六条、第四十七条的规定执行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10332, '《中华人民共和国劳动合同法实施条例》', '第三十二条', '劳动', '行政法规', NULL, NULL, '第四章 　劳务派遣特别规定　　', NULL, '第三十二条　劳务派遣单位违法解除或者终止被派遣劳动者的劳动合同的，依照劳动合同法第四十八条的规定执行。 　　第五章　法津责任 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10333, '《中华人民共和国劳动合同法实施条例》', '第三十三条', '劳动', '行政法规', NULL, NULL, '第五章 　法津责任　　', NULL, '第三十三条　用人单位违反劳动合同法有关建立职工名册规定的，由劳动行政部门责令限期改正；逾期不改正的，由劳动行政部门处２０００元以上２万元以下的罚款。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10334, '《中华人民共和国劳动合同法实施条例》', '第三十四条', '劳动', '行政法规', NULL, NULL, '第五章 　法津责任　　', NULL, '第三十四条　用人单位依照劳动合同法的规定应当向劳动者每月支付两倍的工资或者应当向劳动者支付赔偿金而未支付的，劳动行政部门应当责令用人单位支付。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10335, '《中华人民共和国劳动合同法实施条例》', '第三十五条', '劳动', '行政法规', NULL, NULL, '第五章 　法津责任　　', NULL, '第三十五条　用工单位违反劳动合同法和本条例有关劳务派遣规定的，由劳动行政部门和其他有关主管部门责令改正；情节严重的，以每位被派遣劳动者１０００元以上５０００元以下的标准处以罚款；给被派遣劳动者造成损害的，劳务派遣单位和用工单位承担连带赔偿责任。 　　第六章　附　则 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10336, '《中华人民共和国劳动合同法实施条例》', '第三十六条', '劳动', '行政法规', NULL, NULL, '第六章 　附　则　　', NULL, '第三十六条　对违反劳动合同法和本条例的行为的投诉、举报，县级以上地方人民政府劳动行政部门依照《劳动保障监察条例》的规定处理。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10337, '《中华人民共和国劳动合同法实施条例》', '第三十七条', '劳动', '行政法规', NULL, NULL, '第六章 　附　则　　', NULL, '第三十七条　劳动者与用人单位因订立、履行、变更、解除或者终止劳动合同发生争议的，依照《中华人民共和国劳动争议调解仲裁法》的规定处理。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10338, '《中华人民共和国劳动合同法实施条例》', '第三十八条', '劳动', '行政法规', NULL, NULL, '第六章 　附　则　　', NULL, '第三十八条　本条例自公布之日起施行。 www.nt12333.com 南通劳动保障服务网提供资讯参考 重点招聘 　 　 　 　 　 关于我们 | 法律声明 | 资费标准 | 友情链接 | 设为首页| 加入收藏 | 联系我们 服务电话：88866428 13912400180 联系Email：halwd@126.com 联系QQ：583542580 联系地址：海安县鸿鹄劳动保障事务所 邮政编码：226600 南通劳动保障服务网 海安县鸿鹄劳动保障事务所 版权所有', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10401, '《中华人民共和国劳动争议调解仲裁法》', '第一条', '劳动', '法律', NULL, NULL, '第一章 　总　　则　　　　　', NULL, '第一条为了公正及时解决劳动争议，保护当事人合法权益，促进劳动关系和谐稳定，制定本法。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10402, '《中华人民共和国劳动争议调解仲裁法》', '第二条', '劳动', '法律', NULL, NULL, '第一章 　总　　则　　　　　', NULL, '第二条中华人民共和国境内的用人单位与劳动者发生的下列劳动争议，适用本法： 　　　 （一）因确认劳动关系发生的争议； 　　　 （二）因订立、履行、变更、解除和终止劳动合同发生的争议； 　　　 （三）因除名、辞退和辞职、离职发生的争议； 　　　 （四）因工作时间、休息休假、社会保险、福利、培训以及劳动保护发生的争议； 　　　 （五）因劳动报酬、工伤医疗费、经济补偿或者赔偿金等发生的争议； 　　　 （六）法律、法规规定的其他劳动争议。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10403, '《中华人民共和国劳动争议调解仲裁法》', '第三条', '劳动', '法律', NULL, NULL, '第一章 　总　　则　　　　　', NULL, '第三条解决劳动争议，应当根据事实，遵循合法、公正、及时、着重调解的原则，依法保护当事人的合法权益。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10404, '《中华人民共和国劳动争议调解仲裁法》', '第四条', '劳动', '法律', NULL, NULL, '第一章 　总　　则　　　　　', NULL, '第四条发生劳动争议，劳动者可以与用人单位协商，也可以请工会或者第三方共同与用人单位协商，达成和解协议。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10405, '《中华人民共和国劳动争议调解仲裁法》', '第五条', '劳动', '法律', NULL, NULL, '第一章 　总　　则　　　　　', NULL, '第五条发生劳动争议，当事人不愿协商、协商不成或者达成和解协议后不履行的，可以向调解组织申请调解；不愿调解、调解不成或者达成调解协议后不履行的，可以向劳动争议仲裁委员会申请仲裁；对仲裁裁决不服的，除本法另有规定的外，可以向人民法院提起诉讼。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10406, '《中华人民共和国劳动争议调解仲裁法》', '第六条', '劳动', '法律', NULL, NULL, '第一章 　总　　则　　　　　', NULL, '第六条发生劳动争议，当事人对自己提出的主张，有责任提供证据。与争议事项有关的证据属于用人单位掌握管理的，用人单位应当提供；用人单位不提供的，应当承担不利后果。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10407, '《中华人民共和国劳动争议调解仲裁法》', '第七条', '劳动', '法律', NULL, NULL, '第一章 　总　　则　　　　　', NULL, '第七条发生劳动争议的劳动者一方在十人以上，并有共同请求的，可以推举代表参加调解、仲裁或者诉讼活动。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10408, '《中华人民共和国劳动争议调解仲裁法》', '第八条', '劳动', '法律', NULL, NULL, '第一章 　总　　则　　　　　', NULL, '第八条县级以上人民政府劳动行政部门会同工会和企业方面代表建立协调劳动关系三方机制，共同研究解决劳动争议的重大问题。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10409, '《中华人民共和国劳动争议调解仲裁法》', '第九条', '劳动', '法律', NULL, NULL, '第一章 　总　　则　　　　　', NULL, '第九条用人单位违反国家规定，拖欠或者未足额支付劳动报酬，或者拖欠工伤医疗费、经济补偿或者赔偿金的，劳动者可以向劳动行政部门投诉，劳动行政部门应当依法处理。 　　 　　第二章　调　　解 　　 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10410, '《中华人民共和国劳动争议调解仲裁法》', '第十条', '劳动', '法律', NULL, NULL, '第二章 　调　　解　　　　　', NULL, '第十条发生劳动争议，当事人可以到下列调解组织申请调解： 　　　 （一）企业劳动争议调解委员会； 　　　 （二）依法设立的基层人民调解组织； 　　　 （三）在乡镇、街道设立的具有劳动争议调解职能的组织。 　　　 企业劳动争议调解委员会由职工代表和企业代表组成。职工代表由工会成员担任或者由全体职工推举产生，企业代表由企业负责人指定。企业劳动争议调解委员会主任由工会成员或者双方推举的人员担任。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10411, '《中华人民共和国劳动争议调解仲裁法》', '第十一条', '劳动', '法律', NULL, NULL, '第二章 　调　　解　　　　　', NULL, '第十一条劳动争议调解组织的调解员应当由公道正派、联系群众、热心调解工作，并具有一定法律知识、政策水平和文化水平的成年公民担任。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10412, '《中华人民共和国劳动争议调解仲裁法》', '第十二条', '劳动', '法律', NULL, NULL, '第二章 　调　　解　　　　　', NULL, '第十二条当事人申请劳动争议调解可以书面申请，也可以口头申请。口头申请的，调解组织应当当场记录申请人基本情况、申请调解的争议事项、理由和时间。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10413, '《中华人民共和国劳动争议调解仲裁法》', '第十三条', '劳动', '法律', NULL, NULL, '第二章 　调　　解　　　　　', NULL, '第十三条调解劳动争议，应当充分听取双方当事人对事实和理由的陈述，耐心疏导，帮助其达成协议。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10414, '《中华人民共和国劳动争议调解仲裁法》', '第十四条', '劳动', '法律', NULL, NULL, '第二章 　调　　解　　　　　', NULL, '第十四条经调解达成协议的，应当制作调解协议书。 　　　 调解协议书由双方当事人签名或者盖章，经调解员签名并加盖调解组织印章后生效，对双方当事人具有约束力，当事人应当履行。 　　　 自劳动争议调解组织收到调解申请之日起十五日内未达成调解协议的，当事人可以依法申请仲裁。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10415, '《中华人民共和国劳动争议调解仲裁法》', '第十五条', '劳动', '法律', NULL, NULL, '第二章 　调　　解　　　　　', NULL, '第十五条达成调解协议后，一方当事人在协议约定期限内不履行调解协议的，另一方当事人可以依法申请仲裁。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10416, '《中华人民共和国劳动争议调解仲裁法》', '第十六条', '劳动', '法律', NULL, NULL, '第二章 　调　　解　　　　　', NULL, '第十六条因支付拖欠劳动报酬、工伤医疗费、经济补偿或者赔偿金事项达成调解协议，用人单位在协议约定期限内不履行的，劳动者可以持调解协议书依法向人民法院申请支付令。人民法院应当依法发出支付令。 　　 　　第三章　仲　　裁 　　 　　　 第一节一般规定 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10417, '《中华人民共和国劳动争议调解仲裁法》', '第十七条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第一节 一般规定　　　', '第十七条劳动争议仲裁委员会按照统筹规划、合理布局和适应实际需要的原则设立。省、自治区人民政府可以决定在市、县设立；直辖市人民政府可以决定在区、县设立。直辖市、设区的市也可以设立一个或者若干个劳动争议仲裁委员会。劳动争议仲裁委员会不按行政区划层层设立。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10418, '《中华人民共和国劳动争议调解仲裁法》', '第十八条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第一节 一般规定　　　', '第十八条国务院劳动行政部门依照本法有关规定制定仲裁规则。省、自治区、直辖市人民政府劳动行政部门对本行政区域的劳动争议仲裁工作进行指导。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10419, '《中华人民共和国劳动争议调解仲裁法》', '第十九条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第一节 一般规定　　　', '第十九条劳动争议仲裁委员会由劳动行政部门代表、工会代表和企业方面代表组成。劳动争议仲裁委员会组成人员应当是单数。 　　　 劳动争议仲裁委员会依法履行下列职责： 　　　 （一）聘任、解聘专职或者兼职仲裁员； 　　　 （二）受理劳动争议案件； 　　　 （三）讨论重大或者疑难的劳动争议案件； 　　　 （四）对仲裁活动进行监督。 　　　 劳动争议仲裁委员会下设办事机构，负责办理劳动争议仲裁委员会的日常工作。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10420, '《中华人民共和国劳动争议调解仲裁法》', '第二十条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第一节 一般规定　　　', '第二十条劳动争议仲裁委员会应当设仲裁员名册。 　　　 仲裁员应当公道正派并符合下列条件之一： 　　　 （一）曾任审判员的； 　　　 （二）从事法律研究、教学工作并具有中级以上职称的； 　　　 （三）具有法律知识、从事人力资源管理或者工会等专业工作满五年的； 　　　 （四）律师执业满三年的。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10421, '《中华人民共和国劳动争议调解仲裁法》', '第二十一条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第一节 一般规定　　　', '第二十一条劳动争议仲裁委员会负责管辖本区域内发生的劳动争议。 　　　 劳动争议由劳动合同履行地或者用人单位所在地的劳动争议仲裁委员会管辖。双方当事人分别向劳动合同履行地和用人单位所在地的劳动争议仲裁委员会申请仲裁的，由劳动合同履行地的劳动争议仲裁委员会管辖。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10422, '《中华人民共和国劳动争议调解仲裁法》', '第二十二条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第一节 一般规定　　　', '第二十二条发生劳动争议的劳动者和用人单位为劳动争议仲裁案件的双方当事人。 　　　 劳务派遣单位或者用工单位与劳动者发生劳动争议的，劳务派遣单位和用工单位为共同当事人。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10423, '《中华人民共和国劳动争议调解仲裁法》', '第二十三条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第一节 一般规定　　　', '第二十三条与劳动争议案件的处理结果有利害关系的第三人，可以申请参加仲裁活动或者由劳动争议仲裁委员会通知其参加仲裁活动。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10424, '《中华人民共和国劳动争议调解仲裁法》', '第二十四条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第一节 一般规定　　　', '第二十四条当事人可以委托代理人参加仲裁活动。委托他人参加仲裁活动，应当向劳动争议仲裁委员会提交有委托人签名或者盖章的委托书，委托书应当载明委托事项和权限。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10425, '《中华人民共和国劳动争议调解仲裁法》', '第二十五条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第一节 一般规定　　　', '第二十五条丧失或者部分丧失民事行为能力的劳动者，由其法定代理人代为参加仲裁活动；无法定代理人的，由劳动争议仲裁委员会为其指定代理人。劳动者死亡的，由其近亲属或者代理人参加仲裁活动。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10426, '《中华人民共和国劳动争议调解仲裁法》', '第二十六条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第一节 一般规定　　　', '第二十六条劳动争议仲裁公开进行，但当事人协议不公开进行或者涉及国家秘密、商业秘密和个人隐私的除外。 　　　 第二节申请和受理 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10427, '《中华人民共和国劳动争议调解仲裁法》', '第二十七条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第二节 申请和受理　　　', '第二十七条劳动争议申请仲裁的时效期间为一年。仲裁时效期间从当事人知道或者应当知道其权利被侵害之日起计算。 　　　 前款规定的仲裁时效，因当事人一方向对方当事人主张权利，或者向有关部门请求权利救济，或者对方当事人同意履行义务而中断。从中断时起，仲裁时效期间重新计算。 　　　 因不可抗力或者有其他正当理由，当事人不能在本条第一款规定的仲裁时效期间申请仲裁的，仲裁时效中止。从中止时效的原因消除之日起，仲裁时效期间继续计算。 　　　 劳动关系存续期间因拖欠劳动报酬发生争议的，劳动者申请仲裁不受本条第一款规定的仲裁时效期间的限制；但是，劳动关系终止的，应当自劳动关系终止之日起一年内提出。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10428, '《中华人民共和国劳动争议调解仲裁法》', '第二十八条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第二节 申请和受理　　　', '第二十八条申请人申请仲裁应当提交书面仲裁申请，并按照被申请人人数提交副本。 　　　 仲裁申请书应当载明下列事项： 　　　 （一）劳动者的姓名、性别、年龄、职业、工作单位和住所，用人单位的名称、住所和法定代表人或者主要负责人的姓名、职务； 　　　 （二）仲裁请求和所根据的事实、理由； 　　　 （三）证据和证据来源、证人姓名和住所。 　　　 书写仲裁申请确有困难的，可以口头申请，由劳动争议仲裁委员会记入笔录，并告知对方当事人。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10429, '《中华人民共和国劳动争议调解仲裁法》', '第二十九条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第二节 申请和受理　　　', '第二十九条劳动争议仲裁委员会收到仲裁申请之日起五日内，认为符合受理条件的，应当受理，并通知申请人；认为不符合受理条件的，应当书面通知申请人不予受理，并说明理由。对劳动争议仲裁委员会不予受理或者逾期未作出决定的，申请人可以就该劳动争议事项向人民法院提起诉讼。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10430, '《中华人民共和国劳动争议调解仲裁法》', '第三十条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第二节 申请和受理　　　', '第三十条劳动争议仲裁委员会受理仲裁申请后，应当在五日内将仲裁申请书副本送达被申请人。 　　　 被申请人收到仲裁申请书副本后，应当在十日内向劳动争议仲裁委员会提交答辩书。劳动争议仲裁委员会收到答辩书后，应当在五日内将答辩书副本送达申请人。被申请人未提交答辩书的，不影响仲裁程序的进行。 　　　 第三节开庭和裁决 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10431, '《中华人民共和国劳动争议调解仲裁法》', '第三十一条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第三十一条劳动争议仲裁委员会裁决劳动争议案件实行仲裁庭制。仲裁庭由三名仲裁员组成，设首席仲裁员。简单劳动争议案件可以由一名仲裁员独任仲裁。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10432, '《中华人民共和国劳动争议调解仲裁法》', '第三十二条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第三十二条劳动争议仲裁委员会应当在受理仲裁申请之日起五日内将仲裁庭的组成情况书面通知当事人。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10433, '《中华人民共和国劳动争议调解仲裁法》', '第三十三条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第三十三条仲裁员有下列情形之一，应当回避，当事人也有权以口头或者书面方式提出回避申请： 　　　 （一）是本案当事人或者当事人、代理人的近亲属的； 　　　 （二）与本案有利害关系的； 　　　 （三）与本案当事人、代理人有其他关系，可能影响公正裁决的； 　　　 （四）私自会见当事人、代理人，或者接受当事人、代理人的请客送礼的。 　　　 劳动争议仲裁委员会对回避申请应当及时作出决定，并以口头或者书面方式通知当事人。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10434, '《中华人民共和国劳动争议调解仲裁法》', '第三十四条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第三十四条仲裁员有本法第三十三条第四项规定情形，或者有索贿受贿、徇私舞弊、枉法裁决行为的，应当依法承担法律责任。劳动争议仲裁委员会应当将其解聘。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10435, '《中华人民共和国劳动争议调解仲裁法》', '第三十五条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第三十五条仲裁庭应当在开庭五日前，将开庭日期、地点书面通知双方当事人。当事人有正当理由的，可以在开庭三日前请求延期开庭。是否延期，由劳动争议仲裁委员会决定。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10436, '《中华人民共和国劳动争议调解仲裁法》', '第三十六条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第三十六条申请人收到书面通知，无正当理由拒不到庭或者未经仲裁庭同意中途退庭的，可以视为撤回仲裁申请。 　　　 被申请人收到书面通知，无正当理由拒不到庭或者未经仲裁庭同意中途退庭的，可以缺席裁决。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10437, '《中华人民共和国劳动争议调解仲裁法》', '第三十七条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第三十七条仲裁庭对专门性问题认为需要鉴定的，可以交由当事人约定的鉴定机构鉴定；当事人没有约定或者无法达成约定的，由仲裁庭指定的鉴定机构鉴定。 　　　 根据当事人的请求或者仲裁庭的要求，鉴定机构应当派鉴定人参加开庭。当事人经仲裁庭许可，可以向鉴定人提问。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10438, '《中华人民共和国劳动争议调解仲裁法》', '第三十八条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第三十八条当事人在仲裁过程中有权进行质证和辩论。质证和辩论终结时，首席仲裁员或者独任仲裁员应当征询当事人的最后意见。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10439, '《中华人民共和国劳动争议调解仲裁法》', '第三十九条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第三十九条当事人提供的证据经查证属实的，仲裁庭应当将其作为认定事实的根据。 　　　 劳动者无法提供由用人单位掌握管理的与仲裁请求有关的证据，仲裁庭可以要求用人单位在指定期限内提供。用人单位在指定期限内不提供的，应当承担不利后果。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10440, '《中华人民共和国劳动争议调解仲裁法》', '第四十条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第四十条仲裁庭应当将开庭情况记入笔录。当事人和其他仲裁参加人认为对自己陈述的记录有遗漏或者差错的，有权申请补正。如果不予补正，应当记录该申请。 　　　 笔录由仲裁员、记录人员、当事人和其他仲裁参加人签名或者盖章。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10441, '《中华人民共和国劳动争议调解仲裁法》', '第四十一条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第四十一条当事人申请劳动争议仲裁后，可以自行和解。达成和解协议的，可以撤回仲裁申请。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10442, '《中华人民共和国劳动争议调解仲裁法》', '第四十二条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第四十二条仲裁庭在作出裁决前，应当先行调解。 　　　 调解达成协议的，仲裁庭应当制作调解书。 　　　 调解书应当写明仲裁请求和当事人协议的结果。调解书由仲裁员签名，加盖劳动争议仲裁委员会印章，送达双方当事人。调解书经双方当事人签收后，发生法律效力。 　　　 调解不成或者调解书送达前，一方当事人反悔的，仲裁庭应当及时作出裁决。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10443, '《中华人民共和国劳动争议调解仲裁法》', '第四十三条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第四十三条仲裁庭裁决劳动争议案件，应当自劳动争议仲裁委员会受理仲裁申请之日起四十五日内结束。案情复杂需要延期的，经劳动争议仲裁委员会主任批准，可以延期并书面通知当事人，但是延长期限不得超过十五日。逾期未作出仲裁裁决的，当事人可以就该劳动争议事项向人民法院提起诉讼。 　　　 仲裁庭裁决劳动争议案件时，其中一部分事实已经清楚，可以就该部分先行裁决。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10444, '《中华人民共和国劳动争议调解仲裁法》', '第四十四条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第四十四条仲裁庭对追索劳动报酬、工伤医疗费、经济补偿或者赔偿金的案件，根据当事人的申请，可以裁决先予执行，移送人民法院执行。 　　　 仲裁庭裁决先予执行的，应当符合下列条件： 　　　 （一）当事人之间权利义务关系明确； 　　　 （二）不先予执行将严重影响申请人的生活。 　　　 劳动者申请先予执行的，可以不提供担保。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10445, '《中华人民共和国劳动争议调解仲裁法》', '第四十五条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第四十五条裁决应当按照多数仲裁员的意见作出，少数仲裁员的不同意见应当记入笔录。仲裁庭不能形成多数意见时，裁决应当按照首席仲裁员的意见作出。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10446, '《中华人民共和国劳动争议调解仲裁法》', '第四十六条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第四十六条裁决书应当载明仲裁请求、争议事实、裁决理由、裁决结果和裁决日期。裁决书由仲裁员签名，加盖劳动争议仲裁委员会印章。对裁决持不同意见的仲裁员，可以签名，也可以不签名。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10447, '《中华人民共和国劳动争议调解仲裁法》', '第四十七条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第四十七条下列劳动争议，除本法另有规定的外，仲裁裁决为终局裁决，裁决书自作出之日起发生法律效力： 　　　 （一）追索劳动报酬、工伤医疗费、经济补偿或者赔偿金，不超过当地月最低工资标准十二个月金额的争议； 　　　 （二）因执行国家的劳动标准在工作时间、休息休假、社会保险等方面发生的争议。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10448, '《中华人民共和国劳动争议调解仲裁法》', '第四十八条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第四十八条劳动者对本法第四十七条规定的仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10449, '《中华人民共和国劳动争议调解仲裁法》', '第四十九条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第四十九条用人单位有证据证明本法第四十七条规定的仲裁裁决有下列情形之一，可以自收到仲裁裁决书之日起三十日内向劳动争议仲裁委员会所在地的中级人民法院申请撤销裁决： 　　　 （一）适用法律、法规确有错误的； 　　　 （二）劳动争议仲裁委员会无管辖权的； 　　　 （三）违反法定程序的； 　　　 （四）裁决所根据的证据是伪造的； 　　　 （五）对方当事人隐瞒了足以影响公正裁决的证据的； 　　　 （六）仲裁员在仲裁该案时有索贿受贿、徇私舞弊、枉法裁决行为的。 　　　 人民法院经组成合议庭审查核实裁决有前款规定情形之一的，应当裁定撤销。 　　　 仲裁裁决被人民法院裁定撤销的，当事人可以自收到裁定书之日起十五日内就该劳动争议事项向人民法院提起诉讼。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10450, '《中华人民共和国劳动争议调解仲裁法》', '第五十条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第五十条当事人对本法第四十七条规定以外的其他劳动争议案件的仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼；期满不起诉的，裁决书发生法律效力。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10451, '《中华人民共和国劳动争议调解仲裁法》', '第五十一条', '劳动', '法律', NULL, NULL, '第三章 　仲　　裁　　　　　', '第三节 开庭和裁决　　　', '第五十一条当事人对发生法律效力的调解书、裁决书，应当依照规定的期限履行。一方当事人逾期不履行的，另一方当事人可以依照民事诉讼法的有关规定向人民法院申请执行。受理申请的人民法院应当依法执行。 　　 　　第四章　附　　则 　　 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10452, '《中华人民共和国劳动争议调解仲裁法》', '第五十二条', '劳动', '法律', NULL, NULL, '第四章 　附　　则　　　　　', NULL, '第五十二条事业单位实行聘用制的工作人员与本单位发生劳动争议的，依照本法执行；法律、行政法规或者国务院另有规定的，依照其规定。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10453, '《中华人民共和国劳动争议调解仲裁法》', '第五十三条', '劳动', '法律', NULL, NULL, '第四章 　附　　则　　　　　', NULL, '第五十三条劳动争议仲裁不收费。劳动争议仲裁委员会的经费由财政予以保障。 　　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10454, '《中华人民共和国劳动争议调解仲裁法》', '第五十四条', '劳动', '法律', NULL, NULL, '第四章 　附　　则　　　　　', NULL, '第五十四条本法自2008年5月1日起施行。 　　 皖ICP备 050001008 中国科学院合肥物质科学研究院 版权所有　 地址:安徽省合肥市蜀山湖路350号 邮编:230031 电话:0551-5591245 电子邮件:yzxx@hfcas.ac.cn', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10501, '《工伤保险条例》', '第一条', '劳动', '行政法规', NULL, NULL, '第一章 　总　　则　　', NULL, '第一条　为了保障因工作遭受事故伤害或者患职业病的职工获得医疗救治和经济补偿，促进工伤预防和职业康复，分散用人单位的工伤风险，制定本条例。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10502, '《工伤保险条例》', '第二条', '劳动', '行政法规', NULL, NULL, '第一章 　总　　则　　', NULL, '第二条　中华人民共和国境内的企业、事业单位、社会团体、民办非企业单位、基金会、律师事务所、会计师事务所等组织和有雇工的个体工商户（以下称用人单位）应当依照本条例规定参加工伤保险，为本单位全部职工或者雇工（以下称职工）缴纳工伤保险费。 　　中华人民共和国境内的企业、事业单位、社会团体、民办非企业单位、基金会、律师事务所、会计师事务所等组织的职工和个体工商户的雇工，均有依照本条例的规定享受工伤保险待遇的权利。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10503, '《工伤保险条例》', '第三条', '劳动', '行政法规', NULL, NULL, '第一章 　总　　则　　', NULL, '第三条　工伤保险费的征缴按照《社会保险费征缴暂行条例》关于基本养老保险费、基本医疗保险费、失业保险费的征缴规定执行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10504, '《工伤保险条例》', '第四条', '劳动', '行政法规', NULL, NULL, '第一章 　总　　则　　', NULL, '第四条　用人单位应当将参加工伤保险的有关情况在本单位内公示。 　　用人单位和职工应当遵守有关安全生产和职业病防治的法律法规，执行安全卫生规程和标准，预防工伤事故发生，避免和减少职业病危害。 　　职工发生工伤时，用人单位应当采取措施使工伤职工得到及时救治。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10505, '《工伤保险条例》', '第五条', '劳动', '行政法规', NULL, NULL, '第一章 　总　　则　　', NULL, '第五条　国务院社会保险行政部门负责全国的工伤保险工作。 　　县级以上地方各级人民政府社会保险行政部门负责本行政区域内的工伤保险工作。 　　社会保险行政部门按照国务院有关规定设立的社会保险经办机构（以下称经办机构）具体承办工伤保险事务。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10506, '《工伤保险条例》', '第六条', '劳动', '行政法规', NULL, NULL, '第一章 　总　　则　　', NULL, '第六条　社会保险行政部门等部门制定工伤保险的政策、标准，应当征求工会组织、用人单位代表的意见。 第二章　工伤保险基金 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10507, '《工伤保险条例》', '第七条', '劳动', '行政法规', NULL, NULL, '第二章 　工伤保险基金　　', NULL, '第七条　工伤保险基金由用人单位缴纳的工伤保险费、工伤保险基金的利息和依法纳入工伤保险基金的其他资金构成。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10508, '《工伤保险条例》', '第八条', '劳动', '行政法规', NULL, NULL, '第二章 　工伤保险基金　　', NULL, '第八条　工伤保险费根据以支定收、收支平衡的原则，确定费率。 　　国家根据不同行业的工伤风险程度确定行业的差别费率，并根据工伤保险费使用、工伤发生率等情况在每个行业内确定若干费率档次。行业差别费率及行业内费率档次由国务院社会保险行政部门制定，报国务院批准后公布施行。 　　统筹地区经办机构根据用人单位工伤保险费使用、工伤发生率等情况，适用所属行业内相应的费率档次确定单位缴费费率。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10509, '《工伤保险条例》', '第九条', '劳动', '行政法规', NULL, NULL, '第二章 　工伤保险基金　　', NULL, '第九条　国务院社会保险行政部门应当定期了解全国各统筹地区工伤保险基金收支情况，及时提出调整行业差别费率及行业内费率档次的方案，报国务院批准后公布施行。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10510, '《工伤保险条例》', '第十条', '劳动', '行政法规', NULL, NULL, '第二章 　工伤保险基金　　', NULL, '第十条　用人单位应当按时缴纳工伤保险费。职工个人不缴纳工伤保险费。 　　用人单位缴纳工伤保险费的数额为本单位职工工资总额乘以单位缴费费率之积。 　　对难以按照工资总额缴纳工伤保险费的行业，其缴纳工伤保险费的具体方式，由国务院社会保险行政部门规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10511, '《工伤保险条例》', '第十一条', '劳动', '行政法规', NULL, NULL, '第二章 　工伤保险基金　　', NULL, '第十一条　工伤保险基金逐步实行省级统筹。 　　跨地区、生产流动性较大的行业，可以采取相对集中的方式异地参加统筹地区的工伤保险。具体办法由国务院社会保险行政部门会同有关行业的主管部门制定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10512, '《工伤保险条例》', '第十二条', '劳动', '行政法规', NULL, NULL, '第二章 　工伤保险基金　　', NULL, '第十二条　工伤保险基金存入社会保障基金财政专户，用于本条例规定的工伤保险待遇，劳动能力鉴定，工伤预防的宣传、培训等费用，以及法律、法规规定的用于工伤保险的其他费用的支付。 　　工伤预防费用的提取比例、使用和管理的具体办法，由国务院社会保险行政部门会同国务院财政、卫生行政、安全生产监督管理等部门规定。 　　任何单位或者个人不得将工伤保险基金用于投资运营、兴建或者改建办公场所、发放奖金，或者挪作其他用途。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10513, '《工伤保险条例》', '第十三条', '劳动', '行政法规', NULL, NULL, '第二章 　工伤保险基金　　', NULL, '第十三条　工伤保险基金应当留有一定比例的储备金，用于统筹地区重大事故的工伤保险待遇支付；储备金不足支付的，由统筹地区的人民政府垫付。储备金占基金总额的具体比例和储备金的使用办法，由省、自治区、直辖市人民政府规定。 第三章　工伤认定 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10514, '《工伤保险条例》', '第十四条', '劳动', '行政法规', NULL, NULL, '第三章 　工伤认定　　', NULL, '第十四条　职工有下列情形之一的，应当认定为工伤： 　　（一）在工作时间和工作场所内，因工作原因受到事故伤害的； 　　（二）工作时间前后在工作场所内，从事与工作有关的预备性或者收尾性工作受到事故伤害的； 　　（三）在工作时间和工作场所内，因履行工作职责受到暴力等意外伤害的； 　　（四）患职业病的； 　　（五）因工外出期间，由于工作原因受到伤害或者发生事故下落不明的； 　　（六）在上下班途中，受到非本人主要责任的交通事故或者城市轨道交通、客运轮渡、火车事故伤害的； 　　（七）法律、行政法规规定应当认定为工伤的其他情形。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10515, '《工伤保险条例》', '第十五条', '劳动', '行政法规', NULL, NULL, '第三章 　工伤认定　　', NULL, '第十五条　职工有下列情形之一的，视同工伤： 　　（一）在工作时间和工作岗位，突发疾病死亡或者在48小时之内经抢救无效死亡的； 　　（二）在抢险救灾等维护国家利益、公共利益活动中受到伤害的； 　　（三）职工原在军队服役，因战、因公负伤致残，已取得革命伤残军人证，到用人单位后旧伤复发的。 　　职工有前款第（一）项、第（二）项情形的，按照本条例的有关规定享受工伤保险待遇；职工有前款第（三）项情形的，按照本条例的有关规定享受除一次性伤残补助金以外的工伤保险待遇。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10516, '《工伤保险条例》', '第十六条', '劳动', '行政法规', NULL, NULL, '第三章 　工伤认定　　', NULL, '第十六条　职工符合本条例第十四条、第十五条的规定，但是有下列情形之一的，不得认定为工伤或者视同工伤： 　　（一）故意犯罪的； 　　（二）醉酒或者吸毒的； 　　（三）自残或者自杀的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10517, '《工伤保险条例》', '第十七条', '劳动', '行政法规', NULL, NULL, '第三章 　工伤认定　　', NULL, '第十七条　职工发生事故伤害或者按照职业病防治法规定被诊断、鉴定为职业病，所在单位应当自事故伤害发生之日或者被诊断、鉴定为职业病之日起30日内，向统筹地区社会保险行政部门提出工伤认定申请。遇有特殊情况，经报社会保险行政部门同意，申请时限可以适当延长。 　　用人单位未按前款规定提出工伤认定申请的，工伤职工或者其近亲属、工会组织在事故伤害发生之日或者被诊断、鉴定为职业病之日起1年内，可以直接向用人单位所在地统筹地区社会保险行政部门提出工伤认定申请。 　　按照本条第一款规定应当由省级社会保险行政部门进行工伤认定的事项，根据属地原则由用人单位所在地的设区的市级社会保险行政部门办理。 　　用人单位未在本条第一款规定的时限内提交工伤认定申请，在此期间发生符合本条例规定的工伤待遇等有关费用由该用人单位负担。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10518, '《工伤保险条例》', '第十八条', '劳动', '行政法规', NULL, NULL, '第三章 　工伤认定　　', NULL, '第十八条　提出工伤认定申请应当提交下列材料： 　　（一）工伤认定申请表； 　　（二）与用人单位存在劳动关系（包括事实劳动关系）的证明材料； 　　（三）医疗诊断证明或者职业病诊断证明书（或者职业病诊断鉴定书）。 　　工伤认定申请表应当包括事故发生的时间、地点、原因以及职工伤害程度等基本情况。 　　工伤认定申请人提供材料不完整的，社会保险行政部门应当一次性书面告知工伤认定申请人需要补正的全部材料。申请人按照书面告知要求补正材料后，社会保险行政部门应当受理。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10519, '《工伤保险条例》', '第十九条', '劳动', '行政法规', NULL, NULL, '第三章 　工伤认定　　', NULL, '第十九条　社会保险行政部门受理工伤认定申请后，根据审核需要可以对事故伤害进行调查核实，用人单位、职工、工会组织、医疗机构以及有关部门应当予以协助。职业病诊断和诊断争议的鉴定，依照职业病防治法的有关规定执行。对依法取得职业病诊断证明书或者职业病诊断鉴定书的，社会保险行政部门不再进行调查核实。 　　职工或者其近亲属认为是工伤，用人单位不认为是工伤的，由用人单位承担举证责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10520, '《工伤保险条例》', '第二十条', '劳动', '行政法规', NULL, NULL, '第三章 　工伤认定　　', NULL, '第二十条　社会保险行政部门应当自受理工伤认定申请之日起60日内作出工伤认定的决定，并书面通知申请工伤认定的职工或者其近亲属和该职工所在单位。 　　社会保险行政部门对受理的事实清楚、权利义务明确的工伤认定申请，应当在15日内作出工伤认定的决定。 　　作出工伤认定决定需要以司法机关或者有关行政主管部门的结论为依据的，在司法机关或者有关行政主管部门尚未作出结论期间，作出工伤认定决定的时限中止。 　　社会保险行政部门工作人员与工伤认定申请人有利害关系的，应当回避。 第四章　劳动能力鉴定 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10521, '《工伤保险条例》', '第二十一条', '劳动', '行政法规', NULL, NULL, '第四章 　劳动能力鉴定　　', NULL, '第二十一条　职工发生工伤，经治疗伤情相对稳定后存在残疾、影响劳动能力的，应当进行劳动能力鉴定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10522, '《工伤保险条例》', '第二十二条', '劳动', '行政法规', NULL, NULL, '第四章 　劳动能力鉴定　　', NULL, '第二十二条　劳动能力鉴定是指劳动功能障碍程度和生活自理障碍程度的等级鉴定。 　　劳动功能障碍分为十个伤残等级，最重的为一级，最轻的为十级。 　　生活自理障碍分为三个等级：生活完全不能自理、生活大部分不能自理和生活部分不能自理。 　　劳动能力鉴定标准由国务院社会保险行政部门会同国务院卫生行政部门等部门制定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10523, '《工伤保险条例》', '第二十三条', '劳动', '行政法规', NULL, NULL, '第四章 　劳动能力鉴定　　', NULL, '第二十三条　劳动能力鉴定由用人单位、工伤职工或者其近亲属向设区的市级劳动能力鉴定委员会提出申请，并提供工伤认定决定和职工工伤医疗的有关资料。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10524, '《工伤保险条例》', '第二十四条', '劳动', '行政法规', NULL, NULL, '第四章 　劳动能力鉴定　　', NULL, '第二十四条　省、自治区、直辖市劳动能力鉴定委员会和设区的市级劳动能力鉴定委员会分别由省、自治区、直辖市和设区的市级社会保险行政部门、卫生行政部门、工会组织、经办机构代表以及用人单位代表组成。 　　劳动能力鉴定委员会建立医疗卫生专家库。列入专家库的医疗卫生专业技术人员应当具备下列条件： 　　（一）具有医疗卫生高级专业技术职务任职资格； 　　（二）掌握劳动能力鉴定的相关知识； 　　（三）具有良好的职业品德。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10525, '《工伤保险条例》', '第二十五条', '劳动', '行政法规', NULL, NULL, '第四章 　劳动能力鉴定　　', NULL, '第二十五条　设区的市级劳动能力鉴定委员会收到劳动能力鉴定申请后，应当从其建立的医疗卫生专家库中随机抽取3名或者5名相关专家组成专家组，由专家组提出鉴定意见。设区的市级劳动能力鉴定委员会根据专家组的鉴定意见作出工伤职工劳动能力鉴定结论；必要时，可以委托具备资格的医疗机构协助进行有关的诊断。 　　设区的市级劳动能力鉴定委员会应当自收到劳动能力鉴定申请之日起60日内作出劳动能力鉴定结论，必要时，作出劳动能力鉴定结论的期限可以延长30日。劳动能力鉴定结论应当及时送达申请鉴定的单位和个人。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10526, '《工伤保险条例》', '第二十六条', '劳动', '行政法规', NULL, NULL, '第四章 　劳动能力鉴定　　', NULL, '第二十六条　申请鉴定的单位或者个人对设区的市级劳动能力鉴定委员会作出的鉴定结论不服的，可以在收到该鉴定结论之日起15日内向省、自治区、直辖市劳动能力鉴定委员会提出再次鉴定申请。省、自治区、直辖市劳动能力鉴定委员会作出的劳动能力鉴定结论为最终结论。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10527, '《工伤保险条例》', '第二十七条', '劳动', '行政法规', NULL, NULL, '第四章 　劳动能力鉴定　　', NULL, '第二十七条　劳动能力鉴定工作应当客观、公正。劳动能力鉴定委员会组成人员或者参加鉴定的专家与当事人有利害关系的，应当回避。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10528, '《工伤保险条例》', '第二十八条', '劳动', '行政法规', NULL, NULL, '第四章 　劳动能力鉴定　　', NULL, '第二十八条　自劳动能力鉴定结论作出之日起1年后，工伤职工或者其近亲属、所在单位或者经办机构认为伤残情况发生变化的，可以申请劳动能力复查鉴定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10529, '《工伤保险条例》', '第二十九条', '劳动', '行政法规', NULL, NULL, '第四章 　劳动能力鉴定　　', NULL, '第二十九条　劳动能力鉴定委员会依照本条例第二十六条和第二十八条的规定进行再次鉴定和复查鉴定的期限，依照本条例第二十五条第二款的规定执行。 第五章　工伤保险待遇 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10530, '《工伤保险条例》', '第三十条', '劳动', '行政法规', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第三十条　职工因工作遭受事故伤害或者患职业病进行治疗，享受工伤医疗待遇。 　　职工治疗工伤应当在签订服务协议的医疗机构就医，情况紧急时可以先到就近的医疗机构急救。 　　治疗工伤所需费用符合工伤保险诊疗项目目录、工伤保险药品目录、工伤保险住院服务标准的，从工伤保险基金支付。工伤保险诊疗项目目录、工伤保险药品目录、工伤保险住院服务标准，由国务院社会保险行政部门会同国务院卫生行政部门、食品药品监督管理部门等部门规定。 　　职工住院治疗工伤的伙食补助费，以及经医疗机构出具证明，报经办机构同意，工伤职工到统筹地区以外就医所需的交通、食宿费用从工伤保险基金支付，基金支付的具体标准由统筹地区人民政府规定。 　　工伤职工治疗非工伤引发的疾病，不享受工伤医疗待遇，按照基本医疗保险办法处理。 　　工伤职工到签订服务协议的医疗机构进行工伤康复的费用，符合规定的，从工伤保险基金支付。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10531, '《工伤保险条例》', '第三十一条', '劳动', '行政法规', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第三十一条　社会保险行政部门作出认定为工伤的决定后发生行政复议、行政诉讼的，行政复议和行政诉讼期间不停止支付工伤职工治疗工伤的医疗费用。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10532, '《工伤保险条例》', '第三十二条', '劳动', '行政法规', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第三十二条　工伤职工因日常生活或者就业需要，经劳动能力鉴定委员会确认，可以安装假肢、矫形器、假眼、假牙和配置轮椅等辅助器具，所需费用按照国家规定的标准从工伤保险基金支付。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10533, '《工伤保险条例》', '第三十三条', '劳动', '行政法规', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第三十三条　职工因工作遭受事故伤害或者患职业病需要暂停工作接受工伤医疗的，在停工留薪期内，原工资福利待遇不变，由所在单位按月支付。 　　停工留薪期一般不超过12个月。伤情严重或者情况特殊，经设区的市级劳动能力鉴定委员会确认，可以适当延长，但延长不得超过12个月。工伤职工评定伤残等级后，停发原待遇，按照本章的有关规定享受伤残待遇。工伤职工在停工留薪期满后仍需治疗的，继续享受工伤医疗待遇。 　　生活不能自理的工伤职工在停工留薪期需要护理的，由所在单位负责。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10534, '《工伤保险条例》', '第三十四条', '劳动', '行政法规', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第三十四条　工伤职工已经评定伤残等级并经劳动能力鉴定委员会确认需要生活护理的，从工伤保险基金按月支付生活护理费。 　　生活护理费按照生活完全不能自理、生活大部分不能自理或者生活部分不能自理3个不同等级支付，其标准分别为统筹地区上年度职工月平均工资的50%、40%或者30%。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10535, '《工伤保险条例》', '第三十五条', '劳动', '行政法规', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第三十五条　职工因工致残被鉴定为一级至四级伤残的，保留劳动关系，退出工作岗位，享受以下待遇： 　　（一）从工伤保险基金按伤残等级支付一次性伤残补助金，标准为：一级伤残为27个月的本人工资，二级伤残为25个月的本人工资，三级伤残为23个月的本人工资，四级伤残为21个月的本人工资； 　　（二）从工伤保险基金按月支付伤残津贴，标准为：一级伤残为本人工资的90%，二级伤残为本人工资的85%，三级伤残为本人工资的80%，四级伤残为本人工资的75%。伤残津贴实际金额低于当地最低工资标准的，由工伤保险基金补足差额； 　　（三）工伤职工达到退休年龄并办理退休手续后，停发伤残津贴，按照国家有关规定享受基本养老保险待遇。基本养老保险待遇低于伤残津贴的，由工伤保险基金补足差额。 　　职工因工致残被鉴定为一级至四级伤残的，由用人单位和职工个人以伤残津贴为基数，缴纳基本医疗保险费。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10536, '《工伤保险条例》', '第三十六条', '劳动', '行政法规', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第三十六条　职工因工致残被鉴定为五级、六级伤残的，享受以下待遇： 　　（一）从工伤保险基金按伤残等级支付一次性伤残补助金，标准为：五级伤残为18个月的本人工资，六级伤残为16个月的本人工资； 　　（二）保留与用人单位的劳动关系，由用人单位安排适当工作。难以安排工作的，由用人单位按月发给伤残津贴，标准为：五级伤残为本人工资的70%，六级伤残为本人工资的60%，并由用人单位按照规定为其缴纳应缴纳的各项社会保险费。伤残津贴实际金额低于当地最低工资标准的，由用人单位补足差额。 　　经工伤职工本人提出，该职工可以与用人单位解除或者终止劳动关系，由工伤保险基金支付一次性工伤医疗补助金，由用人单位支付一次性伤残就业补助金。一次性工伤医疗补助金和一次性伤残就业补助金的具体标准由省、自治区、直辖市人民政府规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10537, '《工伤保险条例》', '第三十七条', '劳动', '行政法规', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第三十七条　职工因工致残被鉴定为七级至十级伤残的，享受以下待遇： 　　（一）从工伤保险基金按伤残等级支付一次性伤残补助金，标准为：七级伤残为13个月的本人工资，八级伤残为11个月的本人工资，九级伤残为9个月的本人工资，十级伤残为7个月的本人工资； 　　（二）劳动、聘用合同期满终止，或者职工本人提出解除劳动、聘用合同的，由工伤保险基金支付一次性工伤医疗补助金，由用人单位支付一次性伤残就业补助金。一次性工伤医疗补助金和一次性伤残就业补助金的具体标准由省、自治区、直辖市人民政府规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10538, '《工伤保险条例》', '第三十八条', '劳动', '行政法规', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第三十八条　工伤职工工伤复发，确认需要治疗的，享受本条例第三十条、第三十二条和第三十三条规定的工伤待遇。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10539, '《工伤保险条例》', '第三十九条', '劳动', '行政法规', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第三十九条　职工因工死亡，其近亲属按照下列规定从工伤保险基金领取丧葬补助金、供养亲属抚恤金和一次性工亡补助金： 　　（一）丧葬补助金为6个月的统筹地区上年度职工月平均工资； 　　（二）供养亲属抚恤金按照职工本人工资的一定比例发给由因工死亡职工生前提供主要生活来源、无劳动能力的亲属。标准为：配偶每月40%，其他亲属每人每月30%，孤寡老人或者孤儿每人每月在上述标准的基础上增加10%。核定的各供养亲属的抚恤金之和不应高于因工死亡职工生前的工资。供养亲属的具体范围由国务院社会保险行政部门规定； 　　（三）一次性工亡补助金标准为上一年度全国城镇居民人均可支配收入的20倍。 　　伤残职工在停工留薪期内因工伤导致死亡的，其近亲属享受本条第一款规定的待遇。 　　一级至四级伤残职工在停工留薪期满后死亡的，其近亲属可以享受本条第一款第（一）项、第（二）项规定的待遇。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10540, '《工伤保险条例》', '第四十条', '劳动', '行政法规', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第四十条　伤残津贴、供养亲属抚恤金、生活护理费由统筹地区社会保险行政部门根据职工平均工资和生活费用变化等情况适时调整。调整办法由省、自治区、直辖市人民政府规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10541, '《工伤保险条例》', '第四十一条', '劳动', '行政法规', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第四十一条　职工因工外出期间发生事故或者在抢险救灾中下落不明的，从事故发生当月起3个月内照发工资，从第4个月起停发工资，由工伤保险基金向其供养亲属按月支付供养亲属抚恤金。生活有困难的，可以预支一次性工亡补助金的50%。职工被人民法院宣告死亡的，按照本条例第三十九条职工因工死亡的规定处理。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10542, '《工伤保险条例》', '第四十二条', '劳动', '行政法规', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第四十二条　工伤职工有下列情形之一的，停止享受工伤保险待遇： 　　（一）丧失享受待遇条件的； 　　（二）拒不接受劳动能力鉴定的； 　　（三）拒绝治疗的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10543, '《工伤保险条例》', '第四十三条', '劳动', '行政法规', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第四十三条　用人单位分立、合并、转让的，承继单位应当承担原用人单位的工伤保险责任；原用人单位已经参加工伤保险的，承继单位应当到当地经办机构办理工伤保险变更登记。 　　用人单位实行承包经营的，工伤保险责任由职工劳动关系所在单位承担。 　　职工被借调期间受到工伤事故伤害的，由原用人单位承担工伤保险责任，但原用人单位与借调单位可以约定补偿办法。 　　企业破产的，在破产清算时依法拨付应当由单位支付的工伤保险待遇费用。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10544, '《工伤保险条例》', '第四十四条', '劳动', '行政法规', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第四十四条　职工被派遣出境工作，依据前往国家或者地区的法律应当参加当地工伤保险的，参加当地工伤保险，其国内工伤保险关系中止；不能参加当地工伤保险的，其国内工伤保险关系不中止。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10545, '《工伤保险条例》', '第四十五条', '劳动', '行政法规', NULL, NULL, '第五章 　工伤保险待遇　　', NULL, '第四十五条　职工再次发生工伤，根据规定应当享受伤残津贴的，按照新认定的伤残等级享受伤残津贴待遇。 第六章　监督管理 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10546, '《工伤保险条例》', '第四十六条', '劳动', '行政法规', NULL, NULL, '第六章 　监督管理　　', NULL, '第四十六条　经办机构具体承办工伤保险事务，履行下列职责： 　　（一）根据省、自治区、直辖市人民政府规定，征收工伤保险费； 　　（二）核查用人单位的工资总额和职工人数，办理工伤保险登记，并负责保存用人单位缴费和职工享受工伤保险待遇情况的记录； 　　（三）进行工伤保险的调查、统计； 　　（四）按照规定管理工伤保险基金的支出； 　　（五）按照规定核定工伤保险待遇； 　　（六）为工伤职工或者其近亲属免费提供咨询服务。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10547, '《工伤保险条例》', '第四十七条', '劳动', '行政法规', NULL, NULL, '第六章 　监督管理　　', NULL, '第四十七条　经办机构与医疗机构、辅助器具配置机构在平等协商的基础上签订服务协议，并公布签订服务协议的医疗机构、辅助器具配置机构的名单。具体办法由国务院社会保险行政部门分别会同国务院卫生行政部门、民政部门等部门制定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10548, '《工伤保险条例》', '第四十八条', '劳动', '行政法规', NULL, NULL, '第六章 　监督管理　　', NULL, '第四十八条　经办机构按照协议和国家有关目录、标准对工伤职工医疗费用、康复费用、辅助器具费用的使用情况进行核查，并按时足额结算费用。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10549, '《工伤保险条例》', '第四十九条', '劳动', '行政法规', NULL, NULL, '第六章 　监督管理　　', NULL, '第四十九条　经办机构应当定期公布工伤保险基金的收支情况，及时向社会保险行政部门提出调整费率的建议。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10550, '《工伤保险条例》', '第五十条', '劳动', '行政法规', NULL, NULL, '第六章 　监督管理　　', NULL, '第五十条　社会保险行政部门、经办机构应当定期听取工伤职工、医疗机构、辅助器具配置机构以及社会各界对改进工伤保险工作的意见。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10551, '《工伤保险条例》', '第五十一条', '劳动', '行政法规', NULL, NULL, '第六章 　监督管理　　', NULL, '第五十一条　社会保险行政部门依法对工伤保险费的征缴和工伤保险基金的支付情况进行监督检查。 　　财政部门和审计机关依法对工伤保险基金的收支、管理情况进行监督。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10552, '《工伤保险条例》', '第五十二条', '劳动', '行政法规', NULL, NULL, '第六章 　监督管理　　', NULL, '第五十二条　任何组织和个人对有关工伤保险的违法行为，有权举报。社会保险行政部门对举报应当及时调查，按照规定处理，并为举报人保密。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10553, '《工伤保险条例》', '第五十三条', '劳动', '行政法规', NULL, NULL, '第六章 　监督管理　　', NULL, '第五十三条　工会组织依法维护工伤职工的合法权益，对用人单位的工伤保险工作实行监督。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10554, '《工伤保险条例》', '第五十四条', '劳动', '行政法规', NULL, NULL, '第六章 　监督管理　　', NULL, '第五十四条　职工与用人单位发生工伤待遇方面的争议，按照处理劳动争议的有关规定处理。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10555, '《工伤保险条例》', '第五十五条', '劳动', '行政法规', NULL, NULL, '第六章 　监督管理　　', NULL, '第五十五条　有下列情形之一的，有关单位或者个人可以依法申请行政复议，也可以依法向人民法院提起行政诉讼： 　　（一）申请工伤认定的职工或者其近亲属、该职工所在单位对工伤认定申请不予受理的决定不服的； 　　（二）申请工伤认定的职工或者其近亲属、该职工所在单位对工伤认定结论不服的； 　　（三）用人单位对经办机构确定的单位缴费费率不服的； 　　（四）签订服务协议的医疗机构、辅助器具配置机构认为经办机构未履行有关协议或者规定的； 　　（五）工伤职工或者其近亲属对经办机构核定的工伤保险待遇有异议的。 第七章　法律责任 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10556, '《工伤保险条例》', '第五十六条', '劳动', '行政法规', NULL, NULL, '第七章 　法律责任　　', NULL, '第五十六条　单位或者个人违反本条例第十二条规定挪用工伤保险基金，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分或者纪律处分。被挪用的基金由社会保险行政部门追回，并入工伤保险基金；没收的违法所得依法上缴国库。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10557, '《工伤保险条例》', '第五十七条', '劳动', '行政法规', NULL, NULL, '第七章 　法律责任　　', NULL, '第五十七条　社会保险行政部门工作人员有下列情形之一的，依法给予处分；情节严重，构成犯罪的，依法追究刑事责任： 　　（一）无正当理由不受理工伤认定申请，或者弄虚作假将不符合工伤条件的人员认定为工伤职工的； 　　（二）未妥善保管申请工伤认定的证据材料，致使有关证据灭失的； 　　（三）收受当事人财物的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10558, '《工伤保险条例》', '第五十八条', '劳动', '行政法规', NULL, NULL, '第七章 　法律责任　　', NULL, '第五十八条　经办机构有下列行为之一的，由社会保险行政部门责令改正，对直接负责的主管人员和其他责任人员依法给予纪律处分；情节严重，构成犯罪的，依法追究刑事责任；造成当事人经济损失的，由经办机构依法承担赔偿责任： 　　（一）未按规定保存用人单位缴费和职工享受工伤保险待遇情况记录的； 　　（二）不按规定核定工伤保险待遇的； 　　（三）收受当事人财物的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10559, '《工伤保险条例》', '第五十九条', '劳动', '行政法规', NULL, NULL, '第七章 　法律责任　　', NULL, '第五十九条　医疗机构、辅助器具配置机构不按服务协议提供服务的，经办机构可以解除服务协议。 　　经办机构不按时足额结算费用的，由社会保险行政部门责令改正；医疗机构、辅助器具配置机构可以解除服务协议。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10560, '《工伤保险条例》', '第六十条', '劳动', '行政法规', NULL, NULL, '第七章 　法律责任　　', NULL, '第六十条　用人单位、工伤职工或者其近亲属骗取工伤保险待遇，医疗机构、辅助器具配置机构骗取工伤保险基金支出的，由社会保险行政部门责令退还，处骗取金额2倍以上5倍以下的罚款；情节严重，构成犯罪的，依法追究刑事责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10561, '《工伤保险条例》', '第六十一条', '劳动', '行政法规', NULL, NULL, '第七章 　法律责任　　', NULL, '第六十一条　从事劳动能力鉴定的组织或者个人有下列情形之一的，由社会保险行政部门责令改正，处2000元以上1万元以下的罚款；情节严重，构成犯罪的，依法追究刑事责任： 　　（一）提供虚假鉴定意见的； 　　（二）提供虚假诊断证明的； 　　（三）收受当事人财物的。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10562, '《工伤保险条例》', '第六十二条', '劳动', '行政法规', NULL, NULL, '第七章 　法律责任　　', NULL, '第六十二条　用人单位依照本条例规定应当参加工伤保险而未参加的，由社会保险行政部门责令限期参加，补缴应当缴纳的工伤保险费，并自欠缴之日起，按日加收万分之五的滞纳金；逾期仍不缴纳的，处欠缴数额1倍以上3倍以下的罚款。 　　依照本条例规定应当参加工伤保险而未参加工伤保险的用人单位职工发生工伤的，由该用人单位按照本条例规定的工伤保险待遇项目和标准支付费用。 　　用人单位参加工伤保险并补缴应当缴纳的工伤保险费、滞纳金后，由工伤保险基金和用人单位依照本条例的规定支付新发生的费用。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10563, '《工伤保险条例》', '第六十三条', '劳动', '行政法规', NULL, NULL, '第七章 　法律责任　　', NULL, '第六十三条　用人单位违反本条例第十九条的规定，拒不协助社会保险行政部门对事故进行调查核实的，由社会保险行政部门责令改正，处2000元以上2万元以下的罚款。 第八章　附　　则 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10564, '《工伤保险条例》', '第六十四条', '劳动', '行政法规', NULL, NULL, '第八章 　附　　则　　', NULL, '第六十四条　本条例所称工资总额，是指用人单位直接支付给本单位全部职工的劳动报酬总额。 　　本条例所称本人工资，是指工伤职工因工作遭受事故伤害或者患职业病前12个月平均月缴费工资。本人工资高于统筹地区职工平均工资300%的，按照统筹地区职工平均工资的300%计算；本人工资低于统筹地区职工平均工资60%的，按照统筹地区职工平均工资的60%计算。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10565, '《工伤保险条例》', '第六十五条', '劳动', '行政法规', NULL, NULL, '第八章 　附　　则　　', NULL, '第六十五条　公务员和参照公务员法管理的事业单位、社会团体的工作人员因工作遭受事故伤害或者患职业病的，由所在单位支付费用。具体办法由国务院社会保险行政部门会同国务院财政部门规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10566, '《工伤保险条例》', '第六十六条', '劳动', '行政法规', NULL, NULL, '第八章 　附　　则　　', NULL, '第六十六条　无营业执照或者未经依法登记、备案的单位以及被依法吊销营业执照或者撤销登记、备案的单位的职工受到事故伤害或者患职业病的，由该单位向伤残职工或者死亡职工的近亲属给予一次性赔偿，赔偿标准不得低于本条例规定的工伤保险待遇；用人单位不得使用童工，用人单位使用童工造成童工伤残、死亡的，由该单位向童工或者童工的近亲属给予一次性赔偿，赔偿标准不得低于本条例规定的工伤保险待遇。具体办法由国务院社会保险行政部门规定。 　　前款规定的伤残职工或者死亡职工的近亲属就赔偿数额与单位发生争议的，以及前款规定的童工或者童工的近亲属就赔偿数额与单位发生争议的，按照处理劳动争议的有关规定处理。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10567, '《工伤保险条例》', '第六十七条', '劳动', '行政法规', NULL, NULL, '第八章 　附　　则　　', NULL, '第六十七条　本条例自2004年1月1日起施行。本条例施行前已受到事故伤害或者患职业病的职工尚未完成工伤认定的，按照本条例的规定执行。 【E-mail推荐 】', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10601, '《失业保险条例》', '第一条', '劳动', '行政法规', NULL, NULL, '第一章 　总则', NULL, '第一条　为了保障失业人员失业期间的基本生活，促进其再就业，制定本条例。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10602, '《失业保险条例》', '第二条', '劳动', '行政法规', NULL, NULL, '第一章 　总则', NULL, '第二条　城镇企业事业单位、城镇企业事业单位职工依照本条例的规定，缴纳失业保险费。 城镇企业事业单位失业人员依照本条例的规定，享受失业保险待遇。 本条所称城镇企业，是指国有企业、城镇集体企业、外商投资企业、城镇私营企业以及其他城镇企业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10603, '《失业保险条例》', '第三条', '劳动', '行政法规', NULL, NULL, '第一章 　总则', NULL, '第三条　国务院劳动保障行政部门主管全国的失业保险工作。县级以上地方各级人民政府劳动保障行政部门主管本行政区域内的失业保险工作。劳动保障行政部门按照国务院规定设立的经办失业保险业务的社会保险经办机构依照本条例的规定，具体承办失业保险工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10604, '《失业保险条例》', '第四条', '劳动', '行政法规', NULL, NULL, '第一章 　总则', NULL, '第四条　失业保险费按照国家有关规定征缴。 第二章　失业保险基金', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10605, '《失业保险条例》', '第五条', '劳动', '行政法规', NULL, NULL, '第二章 　失业保险基金', NULL, '第五条　失业保险基金由下列各项构成： (一)城镇企业事业单位、城镇企业事业单位职工缴纳的失业保险费； (二)失业保险基金的利息； (三)财政补贴； (四)依法纳入失业保险基金的其他资金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10606, '《失业保险条例》', '第六条', '劳动', '行政法规', NULL, NULL, '第二章 　失业保险基金', NULL, '第六条　城镇企业事业单位按照本单位工资总额的2%缴纳失业保险费。城镇企业事业单位职工按照本人工资的1%缴纳失业保险费。城镇企业事业单位招用的农民合同制工人本人不缴纳失业保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10607, '《失业保险条例》', '第七条', '劳动', '行政法规', NULL, NULL, '第二章 　失业保险基金', NULL, '第七条　失业保险基金在直辖市和设区的市实行全市统筹；其他地区的统筹层次由省、自治区人民政府规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10608, '《失业保险条例》', '第八条', '劳动', '行政法规', NULL, NULL, '第二章 　失业保险基金', NULL, '第八条　省、自治区可以建立失业保险调剂金。 失业保险调剂金以统筹地区依法应当征收的失业保险费为基数，按照省、自治区人民政府规定的比例筹集。 统筹地区的失业保险基金不敷使用时，由失业保险调剂金调剂、地方财政补贴。 失业保险调剂金的筹集、调剂使用以及地方财政补贴的具体办法，由省、自治区人民政府规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10609, '《失业保险条例》', '第九条', '劳动', '行政法规', NULL, NULL, '第二章 　失业保险基金', NULL, '第九条　省、自治区、直辖市人民政府根据本行政区域失业人员数量和失业保险基金数额，报经国务院批准，可以适当调整本行政区域失业保险费的费率。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10610, '《失业保险条例》', '第十条', '劳动', '行政法规', NULL, NULL, '第二章 　失业保险基金', NULL, '第十条　失业保险基金用于下列支出： (一)失业保险金； (二)领取失业保险金期间的医疗补助金； (三)领取失业保险金期间死亡的失业人员的丧葬补助金和其供养的配偶、直系亲属的抚恤金； (四)领取失业保险金期间接受职业培训、职业介绍的补贴，补贴的办法和标准由省、自治区、直辖市人民政府规定； (五)国务院规定或者批准的与失业保险有关的其他费用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10611, '《失业保险条例》', '第十一条', '劳动', '行政法规', NULL, NULL, '第二章 　失业保险基金', NULL, '第十一条　失业保险基金必须存入财政部门在国有商业银行开设的社会保障基金财政专户，实行收支两条线管理，由财政部门依法进行监督。 存入银行和按照国家规定购买国债的失业保险基金，分别按照城乡居民同期存款利率和国债利息计息。失业保险基金的利息并入失业保险基金。 失业保险基金专款专用，不得挪作他用，不得用于平衡财政收支。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10612, '《失业保险条例》', '第十二条', '劳动', '行政法规', NULL, NULL, '第二章 　失业保险基金', NULL, '第十二条　失业保险基金收支的预算、决算，由统筹地区社会保险经办机构编制，经同级劳动保障行政部门复核、同级财政部门审核，报同级人民政府审批。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10613, '《失业保险条例》', '第十三条', '劳动', '行政法规', NULL, NULL, '第二章 　失业保险基金', NULL, '第十三条　失业保险基金的财务制度和会计制度按照国家有关规定执行。 第三章　失业保险待遇', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10614, '《失业保险条例》', '第十四条', '劳动', '行政法规', NULL, NULL, '第三章 　失业保险待遇', NULL, '第十四条　具备下列条件的失业人员，可以领取失业保险金： (一)按照规定参加失业保险，所在单位和本人已按照规定履行缴费义务满1年的； (二)非因本人意愿中断就业的； (三)已办理失业登记，并有求职要求的。 失业人员在领取失业保险金期间，按照规定同时享受其他失业保险待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10615, '《失业保险条例》', '第十五条', '劳动', '行政法规', NULL, NULL, '第三章 　失业保险待遇', NULL, '第十五条　失业人员在领取失业保险金期间有下列情形之一的，停止领取失业保险金，并同时停止享受其他失业保险待遇： (一)重新就业的； (二)应征服兵役的； (三)移居境外的； (四)享受基本养老保险待遇的； (五)被判刑收监执行或者被劳动教养的； (六)无正当理由，拒不接受当地人民政府指定的部门或者机构介绍的工作的； (七)有法律、行政法规规定的其他情形的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10616, '《失业保险条例》', '第十六条', '劳动', '行政法规', NULL, NULL, '第三章 　失业保险待遇', NULL, '第十六条　城镇企业事业单位应当及时为失业人员出具终止或者解除劳动关系的证明，告知其按照规定享受失业保险待遇的权利，并将失业人员的名单自终止或者解除劳动关系之日起7日内报社会保险经办机构备案。 城镇企业事业单位职工失业后，应当持本单位为其出具的终止或者解除劳动关系的证明，及时到指定的社会保险经办机构办理失业登记。失业保险金自办理失业登记之日起计算。 失业保险金由社会保险经办机构按月发放。社会保险经办机构为失业人员开具领取失业保险金的单证，失业人员凭单证到指定银行领取失业保险金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10617, '《失业保险条例》', '第十七条', '劳动', '行政法规', NULL, NULL, '第三章 　失业保险待遇', NULL, '第十七条　失业人员失业前所在单位和本人按照规定累计缴费时间满1年不足5年的，领取失业保险金的期限最长为12个月；累计缴费时间满5年不足10年的，领取失业保险金的期限最长为18个月；累计缴费时间10年以上的，领取失业保险金的期限最长为24个月。重新就业后，再次失业的，缴费时间重新计算，领取失业保险金的期限可以与前次失业应领取而尚未领取的失业保险金的期限合并计算，但是最长不得超过24个月。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10618, '《失业保险条例》', '第十八条', '劳动', '行政法规', NULL, NULL, '第三章 　失业保险待遇', NULL, '第十八条　失业保险金的标准，按照低于当地最低工资标准、高于城市居民最低生活保障标准的水平，由省、自治区、直辖市人民政府确定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10619, '《失业保险条例》', '第十九条', '劳动', '行政法规', NULL, NULL, '第三章 　失业保险待遇', NULL, '第十九条　失业人员在领取失业保险金期间患病就医的，可以按照规定向社会保险经办机构申请领取医疗补助金。医疗补助金的标准由省、自治区、直辖市人民政府规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10620, '《失业保险条例》', '第二十条', '劳动', '行政法规', NULL, NULL, '第三章 　失业保险待遇', NULL, '第二十条　失业人员在领取失业保险金期间死亡的，参照当地对在职职工的规定，对其家属一次性发给丧葬补助金和抚恤金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10621, '《失业保险条例》', '第二十一条', '劳动', '行政法规', NULL, NULL, '第三章 　失业保险待遇', NULL, '第二十一条　单位招用的农民合同制工人连续工作满1年，本单位并已缴纳失业保险费，劳动合同期满未续订或者提前解除劳动合同的，由社会保险经办机构根据其工作时间长短，对其支付一次性生活补助。补助的办法和标准由省、自治区、直辖市人民政府规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10622, '《失业保险条例》', '第二十二条', '劳动', '行政法规', NULL, NULL, '第三章 　失业保险待遇', NULL, '第二十二条　城镇企业事业单位成建制跨统筹地区转移，失业人员跨统筹地区流动的，失业保险关系随之转迁。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10623, '《失业保险条例》', '第二十三条', '劳动', '行政法规', NULL, NULL, '第三章 　失业保险待遇', NULL, '第二十三条　失业人员符合城市居民最低生活保障条件的，按照规定享受城市居民最低生活保障待遇。 第四章　管理和监督', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10624, '《失业保险条例》', '第二十四条', '劳动', '行政法规', NULL, NULL, '第四章 　管理和监督', NULL, '第二十四条　劳动保障行政部门管理失业保险工作，履行下列职责： (一)贯彻实施失业保险法律、法规； (二)指导社会保险经办机构的工作； (三)对失业保险费的征收和失业保险待遇的支付进行监督检查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10625, '《失业保险条例》', '第二十五条', '劳动', '行政法规', NULL, NULL, '第四章 　管理和监督', NULL, '第二十五条　社会保险经办机构具体承办失业保险工作，履行下列职责： (一)负责失业人员的登记、调查、统计； (二)按照规定负责失业保险基金的管理； (三)按照规定核定失业保险待遇，开具失业人员在指定银行领取失业保险金和其他补助金的单证； (四)拨付失业人员职业培训、职业介绍补贴费用； (五)为失业人员提供免费咨询服务； (六)国家规定由其履行的其他职责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10626, '《失业保险条例》', '第二十六条', '劳动', '行政法规', NULL, NULL, '第四章 　管理和监督', NULL, '第二十六条　财政部门和审计部门依法对失业保险基金的收支、管理情况进行监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10627, '《失业保险条例》', '第二十七条', '劳动', '行政法规', NULL, NULL, '第四章 　管理和监督', NULL, '第二十七条　社会保险经办机构所需经费列入预算，由财政拨付。 第五章　罚则', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10628, '《失业保险条例》', '第二十八条', '劳动', '行政法规', NULL, NULL, '第五章 　罚则', NULL, '第二十八条　不符合享受失业保险待遇条件，骗取失业保险金和其他失业保险待遇的，由社会保险经办机构责令退还；情节严重的，由劳动保障行政部门处骗取金额1倍以上3倍以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10629, '《失业保险条例》', '第二十九条', '劳动', '行政法规', NULL, NULL, '第五章 　罚则', NULL, '第二十九条　社会保险经办机构工作人员违反规定向失业人员开具领取失业保险金或者享受其他失业保险待遇单证，致使失业保险基金损失的，由劳动保障行政部门责令追回；情节严重的，依法给予行政处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10630, '《失业保险条例》', '第三十条', '劳动', '行政法规', NULL, NULL, '第五章 　罚则', NULL, '第三十条　劳动保障行政部门和社会保险经办机构的工作人员滥用职权、徇私舞弊、玩忽职守，造成失业保险基金损失的，由劳动保障行政部门追回损失的失业保险基金；构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10631, '《失业保险条例》', '第三十一条', '劳动', '行政法规', NULL, NULL, '第五章 　罚则', NULL, '第三十一条　任何单位、个人挪用失业保险基金的，追回挪用的失业保险基金；有违法所得的，没收违法所得，并入失业保险基金；构成犯罪的，依法追究刑事责任；尚不构成犯罪的，对直接负责的主管人员和其他直接责任人员依法给予行政处分。 第六章　附则', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10632, '《失业保险条例》', '第三十二条', '劳动', '行政法规', NULL, NULL, '第六章 　附则', NULL, '第三十二条　省、自治区、直辖市人民政府根据当地实际情况，可以决定本条例适用于本行政区域内的社会团体及其专职人员、民办非企业单位及其职工、有雇工的城镇个体工商户及其雇工。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10633, '《失业保险条例》', '第三十三条', '劳动', '行政法规', NULL, NULL, '第六章 　附则', NULL, '第三十三条　本条例自发布之日起施行。1993年4月12日国务院发布的《国有企业职工待业保险规定》同时废止。 返回 顶部 中华人民共和国司法部 版权所有 京ICP备0505517 司法部信息中心 运维保障 Copyright © 2017 All Rights Reserved', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10701, '《职工带薪年休假条例》', '第一条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第一条 为了维护职工休息休假权利，调动职工工作积极性，根据劳动法和公务员法，制定本条例。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10702, '《职工带薪年休假条例》', '第二条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第二条 机关、团体、企业、事业单位、民办非企业单位、有雇工的个体工商户等单位的职工连续工作1年以上的，享受带薪年休假（以下简称年休假）。单位应当保证职工享受年休假。职工在年休假期间享受与正常工作期间相同的工资收入。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10703, '《职工带薪年休假条例》', '第三条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第三条 职工累计工作已满1年不满10年的，年休假5天；已满10年不满20年的，年休假10天；已满20年的，年休假15天。 国家法定休假日、休息日不计入年休假的假期。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10704, '《职工带薪年休假条例》', '第四条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第四条 职工有下列情形之一的，不享受当年的年休假： （一）职工依法享受寒暑假，其休假天数多于年休假天数的； （二）职工请事假累计20天以上且单位按照规定不扣工资的； （三）累计工作满1年不满10年的职工，请病假累计2个月以上的； （四）累计工作满10年不满20年的职工，请病假累计3个月以上的； （五）累计工作满20年以上的职工，请病假累计4个月以上的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10705, '《职工带薪年休假条例》', '第五条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第五条 单位根据生产、工作的具体情况，并考虑职工本人意愿，统筹安排职工年休假。 年休假在1个年度内可以集中安排，也可以分段安排，一般不跨年度安排。单位因生产、工作特点确有必要跨年度安排职工年休假的，可以跨1个年度安排。 单位确因工作需要不能安排职工休年休假的，经职工本人同意，可以不安排职工休年休假。对职工应休未休的年休假天数，单位应当按照该职工日工资收入的300%支付年休假工资报酬。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10706, '《职工带薪年休假条例》', '第六条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第六条 县级以上地方人民政府人事部门、劳动保障部门应当依据职权对单位执行本条例的情况主动进行监督检查。 工会组织依法维护职工的年休假权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10707, '《职工带薪年休假条例》', '第七条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第七条 单位不安排职工休年休假又不依照本条例规定给予年休假工资报酬的，由县级以上地方人民政府人事部门或者劳动保障部门依据职权责令限期改正；对逾期不改正的，除责令该单位支付年休假工资报酬外，单位还应当按照年休假工资报酬的数额向职工加付赔偿金；对拒不支付年休假工资报酬、赔偿金的，属于公务员和参照公务员法管理的人员所在单位的，对直接负责的主管人员以及其他直接责任人员依法给予处分；属于其他单位的，由劳动保障部门、人事部门或者职工申请人民法院强制执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10708, '《职工带薪年休假条例》', '第八条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第八条 职工与单位因年休假发生的争议，依照国家有关法律、行政法规的规定处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10709, '《职工带薪年休假条例》', '第九条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第九条 国务院人事部门、国务院劳动保障部门依据职权，分别制定本条例的实施办法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10710, '《职工带薪年休假条例》', '第十条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第十条 本条例自2008年1月1日起施行。 【E-mail推荐 】', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10801, '《女职工劳动保护特别规定》', '第一条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第一条　为了减少和解决女职工在劳动中因生理特点造成的特殊困难，保护女职工健康，制定本规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10802, '《女职工劳动保护特别规定》', '第二条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第二条　中华人民共和国境内的国家机关、企业、事业单位、社会团体、个体经济组织以及其他社会组织等用人单位及其女职工，适用本规定。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10803, '《女职工劳动保护特别规定》', '第三条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第三条　用人单位应当加强女职工劳动保护，采取措施改善女职工劳动安全卫生条件，对女职工进行劳动安全卫生知识培训。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10804, '《女职工劳动保护特别规定》', '第四条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第四条　用人单位应当遵守女职工禁忌从事的劳动范围的规定。用人单位应当将本单位属于女职工禁忌从事的劳动范围的岗位书面告知女职工。 　　女职工禁忌从事的劳动范围由本规定附录列示。国务院安全生产监督管理部门会同国务院人力资源社会保障行政部门、国务院卫生行政部门根据经济社会发展情况，对女职工禁忌从事的劳动范围进行调整。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10805, '《女职工劳动保护特别规定》', '第五条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第五条　用人单位不得因女职工怀孕、生育、哺乳降低其工资、予以辞退、与其解除劳动或者聘用合同。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10806, '《女职工劳动保护特别规定》', '第六条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第六条　女职工在孕期不能适应原劳动的，用人单位应当根据医疗机构的证明，予以减轻劳动量或者安排其他能够适应的劳动。 　　对怀孕7个月以上的女职工，用人单位不得延长劳动时间或者安排夜班劳动，并应当在劳动时间内安排一定的休息时间。 　　怀孕女职工在劳动时间内进行产前检查，所需时间计入劳动时间。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10807, '《女职工劳动保护特别规定》', '第七条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第七条　女职工生育享受98天产假，其中产前可以休假15天；难产的，增加产假15天；生育多胞胎的，每多生育1个婴儿，增加产假15天。 　　女职工怀孕未满4个月流产的，享受15天产假；怀孕满4个月流产的，享受42天产假。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10808, '《女职工劳动保护特别规定》', '第八条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第八条　女职工产假期间的生育津贴，对已经参加生育保险的，按照用人单位上年度职工月平均工资的标准由生育保险基金支付；对未参加生育保险的，按照女职工产假前工资的标准由用人单位支付。 　　女职工生育或者流产的医疗费用，按照生育保险规定的项目和标准，对已经参加生育保险的，由生育保险基金支付；对未参加生育保险的，由用人单位支付。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10809, '《女职工劳动保护特别规定》', '第九条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第九条　对哺乳未满1周岁婴儿的女职工，用人单位不得延长劳动时间或者安排夜班劳动。 　　用人单位应当在每天的劳动时间内为哺乳期女职工安排1小时哺乳时间；女职工生育多胞胎的，每多哺乳1个婴儿每天增加1小时哺乳时间。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10810, '《女职工劳动保护特别规定》', '第十条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第十条　女职工比较多的用人单位应当根据女职工的需要，建立女职工卫生室、孕妇休息室、哺乳室等设施，妥善解决女职工在生理卫生、哺乳方面的困难。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10811, '《女职工劳动保护特别规定》', '第十一条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第十一条　在劳动场所，用人单位应当预防和制止对女职工的性骚扰。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10812, '《女职工劳动保护特别规定》', '第十二条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第十二条　县级以上人民政府人力资源社会保障行政部门、安全生产监督管理部门按照各自职责负责对用人单位遵守本规定的情况进行监督检查。 　　工会、妇女组织依法对用人单位遵守本规定的情况进行监督。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10813, '《女职工劳动保护特别规定》', '第十三条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第十三条　用人单位违反本规定第六条第二款、第七条、第九条第一款规定的，由县级以上人民政府人力资源社会保障行政部门责令限期改正，按照受侵害女职工每人1000元以上5000元以下的标准计算，处以罚款。 　　用人单位违反本规定附录第一条、第二条规定的，由县级以上人民政府安全生产监督管理部门责令限期改正，按照受侵害女职工每人1000元以上5000元以下的标准计算，处以罚款。用人单位违反本规定附录第三条、第四条规定的，由县级以上人民政府安全生产监督管理部门责令限期治理，处5万元以上30万元以下的罚款；情节严重的，责令停止有关作业，或者提请有关人民政府按照国务院规定的权限责令关闭。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10814, '《女职工劳动保护特别规定》', '第十四条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第十四条　用人单位违反本规定，侵害女职工合法权益的，女职工可以依法投诉、举报、申诉，依法向劳动人事争议调解仲裁机构申请调解仲裁，对仲裁裁决不服的，依法向人民法院提起诉讼。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10815, '《女职工劳动保护特别规定》', '第十五条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第十五条　用人单位违反本规定，侵害女职工合法权益，造成女职工损害的，依法给予赔偿；用人单位及其直接负责的主管人员和其他直接责任人员构成犯罪的，依法追究刑事责任。 　　', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (10816, '《女职工劳动保护特别规定》', '第十六条', '劳动', '行政法规', NULL, NULL, NULL, NULL, '第十六条　本规定自公布之日起施行。1988年7月21日国务院发布的《女职工劳动保护规定》同时废止。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200000, '《中华人民共和国社会保险法》', '第一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '为了规范社会保险关系，维护公民参加社会保险和享受社会保险待遇的合法权益，使公民共享发展成果，促进社会和谐稳定，根据宪法，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200001, '《中华人民共和国社会保险法》', '第二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '国家建立基本养老保险、基本医疗保险、工伤保险、失业保险、生育保险等社会保险制度，保障公民在年老、疾病、工伤、失业、生育等情况下依法从国家和社会获得物质帮助的权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200002, '《中华人民共和国社会保险法》', '第三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '社会保险制度坚持广覆盖、保基本、多层次、可持续的方针，社会保险水平应当与经济社会发展水平相适应。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200003, '《中华人民共和国社会保险法》', '第四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '中华人民共和国境内的用人单位和个人依法缴纳社会保险费，有权查询缴费记录、个人权益记录，要求社会保险经办机构提供社会保险咨询等相关服务。 个人依法享受社会保险待遇，有权监督本单位为其缴费情况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200004, '《中华人民共和国社会保险法》', '第五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '县级以上人民政府将社会保险事业纳入国民经济和社会发展规划。 国家多渠道筹集社会保险资金。县级以上人民政府对社会保险事业给予必要的经费支持。 国家通过税收优惠政策支持社会保险事业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200005, '《中华人民共和国社会保险法》', '第六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '国家对社会保险基金实行严格监管。 国务院和省、自治区、直辖市人民政府建立健全社会保险基金监督管理制度，保障社会保险基金安全、有效运行。 县级以上人民政府采取措施，鼓励和支持社会各方面参与社会保险基金的监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200006, '《中华人民共和国社会保险法》', '第七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '国务院社会保险行政部门负责全国的社会保险管理工作，国务院其他有关部门在各自的职责范围内负责有关的社会保险工作。 县级以上地方人民政府社会保险行政部门负责本行政区域的社会保险管理工作，县级以上地方人民政府其他有关部门在各自的职责范围内负责有关的社会保险工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200007, '《中华人民共和国社会保险法》', '第八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '社会保险经办机构提供社会保险服务，负责社会保险登记、个人权益记录、社会保险待遇支付等工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200008, '《中华人民共和国社会保险法》', '第九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '工会依法维护职工的合法权益，有权参与社会保险重大事项的研究，参加社会保险监督委员会，对与职工社会保险权益有关的事项进行监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200009, '《中华人民共和国社会保险法》', '第十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '职工应当参加基本养老保险，由用人单位和职工共同缴纳基本养老保险费。 无雇工的个体工商户、未在用人单位参加基本养老保险的非全日制从业人员以及其他灵活就业人员可以参加基本养老保险，由个人缴纳基本养老保险费。 公务员和参照公务员法管理的工作人员养老保险的办法由国务院规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200010, '《中华人民共和国社会保险法》', '第十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '基本养老保险实行社会统筹与个人账户相结合。 基本养老保险基金由用人单位和个人缴费以及政府补贴等组成。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200011, '《中华人民共和国社会保险法》', '第十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '用人单位应当按照国家规定的本单位职工工资总额的比例缴纳基本养老保险费，记入基本养老保险统筹基金。 职工应当按照国家规定的本人工资的比例缴纳基本养老保险费，记入个人账户。 无雇工的个体工商户、未在用人单位参加基本养老保险的非全日制从业人员以及其他灵活就业人员参加基本养老保险的，应当按照国家规定缴纳基本养老保险费，分别记入基本养老保险统筹基金和个人账户。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200012, '《中华人民共和国社会保险法》', '第十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '国有企业、事业单位职工参加基本养老保险前，视同缴费年限期间应当缴纳的基本养老保险费由政府承担。 基本养老保险基金出现支付不足时，政府给予补贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200013, '《中华人民共和国社会保险法》', '第十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '个人账户不得提前支取，记账利率不得低于银行定期存款利率，免征利息税。个人死亡的，个人账户余额可以继承。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200014, '《中华人民共和国社会保险法》', '第十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '基本养老金由统筹养老金和个人账户养老金组成。 基本养老金根据个人累计缴费年限、缴费工资、当地职工平均工资、个人账户金额、城镇人口平均预期寿命等因素确定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200015, '《中华人民共和国社会保险法》', '第十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '参加基本养老保险的个人，达到法定退休年龄时累计缴费满十五年的，按月领取基本养老金。 参加基本养老保险的个人，达到法定退休年龄时累计缴费不足十五年的，可以缴费至满十五年，按月领取基本养老金；也可以转入新型农村社会养老保险或者城镇居民社会养老保险，按照国务院规定享受相应的养老保险待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200016, '《中华人民共和国社会保险法》', '第十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '参加基本养老保险的个人，因病或者非因工死亡的，其遗属可以领取丧葬补助金和抚恤金；在未达到法定退休年龄时因病或者非因工致残完全丧失劳动能力的，可以领取病残津贴。所需资金从基本养老保险基金中支付。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200017, '《中华人民共和国社会保险法》', '第十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '国家建立基本养老金正常调整机制。根据职工平均工资增长、物价上涨情况，适时提高基本养老保险待遇水平。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200018, '《中华人民共和国社会保险法》', '第十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '个人跨统筹地区就业的，其基本养老保险关系随本人转移，缴费年限累计计算。个人达到法定退休年龄时，基本养老金分段计算、统一支付。具体办法由国务院规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200019, '《中华人民共和国社会保险法》', '第二十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '国家建立和完善新型农村社会养老保险制度。 新型农村社会养老保险实行个人缴费、集体补助和政府补贴相结合。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200020, '《中华人民共和国社会保险法》', '第二十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '新型农村社会养老保险待遇由基础养老金和个人账户养老金组成。 参加新型农村社会养老保险的农村居民，符合国家规定条件的，按月领取新型农村社会养老保险待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200021, '《中华人民共和国社会保险法》', '第二十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 基本养老保险', NULL, '国家建立和完善城镇居民社会养老保险制度。 省、自治区、直辖市人民政府根据实际情况，可以将城镇居民社会养老保险和新型农村社会养老保险合并实施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200022, '《中华人民共和国社会保险法》', '第二十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 基本医疗保险', NULL, '职工应当参加职工基本医疗保险，由用人单位和职工按照国家规定共同缴纳基本医疗保险费。 无雇工的个体工商户、未在用人单位参加职工基本医疗保险的非全日制从业人员以及其他灵活就业人员可以参加职工基本医疗保险，由个人按照国家规定缴纳基本医疗保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200023, '《中华人民共和国社会保险法》', '第二十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 基本医疗保险', NULL, '国家建立和完善新型农村合作医疗制度。 新型农村合作医疗的管理办法，由国务院规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200024, '《中华人民共和国社会保险法》', '第二十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 基本医疗保险', NULL, '国家建立和完善城镇居民基本医疗保险制度。 城镇居民基本医疗保险实行个人缴费和政府补贴相结合。 享受最低生活保障的人、丧失劳动能力的残疾人、低收入家庭六十周岁以上的老年人和未成年人等所需个人缴费部分，由政府给予补贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200025, '《中华人民共和国社会保险法》', '第二十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 基本医疗保险', NULL, '职工基本医疗保险、新型农村合作医疗和城镇居民基本医疗保险的待遇标准按照国家规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200026, '《中华人民共和国社会保险法》', '第二十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 基本医疗保险', NULL, '参加职工基本医疗保险的个人，达到法定退休年龄时累计缴费达到国家规定年限的，退休后不再缴纳基本医疗保险费，按照国家规定享受基本医疗保险待遇；未达到国家规定年限的，可以缴费至国家规定年限。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200027, '《中华人民共和国社会保险法》', '第二十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 基本医疗保险', NULL, '符合基本医疗保险药品目录、诊疗项目、医疗服务设施标准以及急诊、抢救的医疗费用，按照国家规定从基本医疗保险基金中支付。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200028, '《中华人民共和国社会保险法》', '第二十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 基本医疗保险', NULL, '参保人员医疗费用中应当由基本医疗保险基金支付的部分，由社会保险经办机构与医疗机构、药品经营单位直接结算。 社会保险行政部门和卫生行政部门应当建立异地就医医疗费用结算制度，方便参保人员享受基本医疗保险待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200029, '《中华人民共和国社会保险法》', '第三十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 基本医疗保险', NULL, '下列医疗费用不纳入基本医疗保险基金支付范围： （一）应当从工伤保险基金中支付的； （二）应当由第三人负担的； （三）应当由公共卫生负担的； （四）在境外就医的。 医疗费用依法应当由第三人负担，第三人不支付或者无法确定第三人的，由基本医疗保险基金先行支付。基本医疗保险基金先行支付后，有权向第三人追偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200030, '《中华人民共和国社会保险法》', '第三十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 基本医疗保险', NULL, '社会保险经办机构根据管理服务的需要，可以与医疗机构、药品经营单位签订服务协议，规范医疗服务行为。 医疗机构应当为参保人员提供合理、必要的医疗服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200031, '《中华人民共和国社会保险法》', '第三十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 基本医疗保险', NULL, '个人跨统筹地区就业的，其基本医疗保险关系随本人转移，缴费年限累计计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200032, '《中华人民共和国社会保险法》', '第三十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '职工应当参加工伤保险，由用人单位缴纳工伤保险费，职工不缴纳工伤保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200033, '《中华人民共和国社会保险法》', '第三十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '国家根据不同行业的工伤风险程度确定行业的差别费率，并根据使用工伤保险基金、工伤发生率等情况在每个行业内确定费率档次。行业差别费率和行业内费率档次由国务院社会保险行政部门制定，报国务院批准后公布施行。 社会保险经办机构根据用人单位使用工伤保险基金、工伤发生率和所属行业费率档次等情况，确定用人单位缴费费率。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200034, '《中华人民共和国社会保险法》', '第三十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '用人单位应当按照本单位职工工资总额，根据社会保险经办机构确定的费率缴纳工伤保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200035, '《中华人民共和国社会保险法》', '第三十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '职工因工作原因受到事故伤害或者患职业病，且经工伤认定的，享受工伤保险待遇；其中，经劳动能力鉴定丧失劳动能力的，享受伤残待遇。 工伤认定和劳动能力鉴定应当简捷、方便。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200036, '《中华人民共和国社会保险法》', '第三十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '职工因下列情形之一导致本人在工作中伤亡的，不认定为工伤： （一）故意犯罪； （二）醉酒或者吸毒； （三）自残或者自杀； （四）法律、行政法规规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200037, '《中华人民共和国社会保险法》', '第三十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '因工伤发生的下列费用，按照国家规定从工伤保险基金中支付： （一）治疗工伤的医疗费用和康复费用； （二）住院伙食补助费； （三）到统筹地区以外就医的交通食宿费； （四）安装配置伤残辅助器具所需费用； （五）生活不能自理的，经劳动能力鉴定委员会确认的生活护理费； （六）一次性伤残补助金和一至四级伤残职工按月领取的伤残津贴； （七）终止或者解除劳动合同时，应当享受的一次性医疗补助金； （八）因工死亡的，其遗属领取的丧葬补助金、供养亲属抚恤金和因工死亡补助金； （九）劳动能力鉴定费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200038, '《中华人民共和国社会保险法》', '第三十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '因工伤发生的下列费用，按照国家规定由用人单位支付： （一）治疗工伤期间的工资福利； （二）五级、六级伤残职工按月领取的伤残津贴； （三）终止或者解除劳动合同时，应当享受的一次性伤残就业补助金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200039, '《中华人民共和国社会保险法》', '第四十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '工伤职工符合领取基本养老金条件的，停发伤残津贴，享受基本养老保险待遇。基本养老保险待遇低于伤残津贴的，从工伤保险基金中补足差额。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200040, '《中华人民共和国社会保险法》', '第四十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '职工所在用人单位未依法缴纳工伤保险费，发生工伤事故的，由用人单位支付工伤保险待遇。用人单位不支付的，从工伤保险基金中先行支付。 从工伤保险基金中先行支付的工伤保险待遇应当由用人单位偿还。用人单位不偿还的，社会保险经办机构可以依照本法第六十三条的规定追偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200041, '《中华人民共和国社会保险法》', '第四十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '由于第三人的原因造成工伤，第三人不支付工伤医疗费用或者无法确定第三人的，由工伤保险基金先行支付。工伤保险基金先行支付后，有权向第三人追偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200042, '《中华人民共和国社会保险法》', '第四十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 工伤保险', NULL, '工伤职工有下列情形之一的，停止享受工伤保险待遇： （一）丧失享受待遇条件的； （二）拒不接受劳动能力鉴定的； （三）拒绝治疗的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200043, '《中华人民共和国社会保险法》', '第四十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 失业保险', NULL, '职工应当参加失业保险，由用人单位和职工按照国家规定共同缴纳失业保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200044, '《中华人民共和国社会保险法》', '第四十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 失业保险', NULL, '失业人员符合下列条件的，从失业保险基金中领取失业保险金： （一）失业前用人单位和本人已经缴纳失业保险费满一年的； （二）非因本人意愿中断就业的； （三）已经进行失业登记，并有求职要求的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200045, '《中华人民共和国社会保险法》', '第四十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 失业保险', NULL, '失业人员失业前用人单位和本人累计缴费满一年不足五年的，领取失业保险金的期限最长为十二个月；累计缴费满五年不足十年的，领取失业保险金的期限最长为十八个月；累计缴费十年以上的，领取失业保险金的期限最长为二十四个月。重新就业后，再次失业的，缴费时间重新计算，领取失业保险金的期限与前次失业应当领取而尚未领取的失业保险金的期限合并计算，最长不超过二十四个月。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200046, '《中华人民共和国社会保险法》', '第四十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 失业保险', NULL, '失业保险金的标准，由省、自治区、直辖市人民政府确定，不得低于城市居民最低生活保障标准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200047, '《中华人民共和国社会保险法》', '第四十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 失业保险', NULL, '失业人员在领取失业保险金期间，参加职工基本医疗保险，享受基本医疗保险待遇。 失业人员应当缴纳的基本医疗保险费从失业保险基金中支付，个人不缴纳基本医疗保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200048, '《中华人民共和国社会保险法》', '第四十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 失业保险', NULL, '失业人员在领取失业保险金期间死亡的，参照当地对在职职工死亡的规定，向其遗属发给一次性丧葬补助金和抚恤金。所需资金从失业保险基金中支付。 个人死亡同时符合领取基本养老保险丧葬补助金、工伤保险丧葬补助金和失业保险丧葬补助金条件的，其遗属只能选择领取其中的一项。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200049, '《中华人民共和国社会保险法》', '第五十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 失业保险', NULL, '用人单位应当及时为失业人员出具终止或者解除劳动关系的证明，并将失业人员的名单自终止或者解除劳动关系之日起十五日内告知社会保险经办机构。 失业人员应当持本单位为其出具的终止或者解除劳动关系的证明，及时到指定的公共就业服务机构办理失业登记。 失业人员凭失业登记证明和个人身份证明，到社会保险经办机构办理领取失业保险金的手续。失业保险金领取期限自办理失业登记之日起计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200050, '《中华人民共和国社会保险法》', '第五十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 失业保险', NULL, '失业人员在领取失业保险金期间有下列情形之一的，停止领取失业保险金，并同时停止享受其他失业保险待遇： （一）重新就业的； （二）应征服兵役的； （三）移居境外的； （四）享受基本养老保险待遇的； （五）无正当理由，拒不接受当地人民政府指定部门或者机构介绍的适当工作或者提供的培训的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200051, '《中华人民共和国社会保险法》', '第五十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 失业保险', NULL, '职工跨统筹地区就业的，其失业保险关系随本人转移，缴费年限累计计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200052, '《中华人民共和国社会保险法》', '第五十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 生育保险', NULL, '职工应当参加生育保险，由用人单位按照国家规定缴纳生育保险费，职工不缴纳生育保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200053, '《中华人民共和国社会保险法》', '第五十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 生育保险', NULL, '用人单位已经缴纳生育保险费的，其职工享受生育保险待遇；职工未就业配偶按照国家规定享受生育医疗费用待遇。所需资金从生育保险基金中支付。 生育保险待遇包括生育医疗费用和生育津贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200054, '《中华人民共和国社会保险法》', '第五十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 生育保险', NULL, '生育医疗费用包括下列各项： （一）生育的医疗费用； （二）计划生育的医疗费用； （三）法律、法规规定的其他项目费用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200055, '《中华人民共和国社会保险法》', '第五十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 生育保险', NULL, '职工有下列情形之一的，可以按照国家规定享受生育津贴： （一）女职工生育享受产假； （二）享受计划生育手术休假； （三）法律、法规规定的其他情形。 生育津贴按照职工所在用人单位上年度职工月平均工资计发。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200056, '《中华人民共和国社会保险法》', '第五十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 社会保险费征缴', NULL, '用人单位应当自成立之日起三十日内凭营业执照、登记证书或者单位印章，向当地社会保险经办机构申请办理社会保险登记。社会保险经办机构应当自收到申请之日起十五日内予以审核，发给社会保险登记证件。 用人单位的社会保险登记事项发生变更或者用人单位依法终止的，应当自变更或者终止之日起三十日内，到社会保险经办机构办理变更或者注销社会保险登记。 市场监督管理部门、民政部门和机构编制管理机关应当及时向社会保险经办机构通报用人单位的成立、终止情况，公安机关应当及时向社会保险经办机构通报个人的出生、死亡以及户口登记、迁移、注销等情况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200057, '《中华人民共和国社会保险法》', '第五十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 社会保险费征缴', NULL, '用人单位应当自用工之日起三十日内为其职工向社会保险经办机构申请办理社会保险登记。未办理社会保险登记的，由社会保险经办机构核定其应当缴纳的社会保险费。 自愿参加社会保险的无雇工的个体工商户、未在用人单位参加社会保险的非全日制从业人员以及其他灵活就业人员，应当向社会保险经办机构申请办理社会保险登记。 国家建立全国统一的个人社会保障号码。个人社会保障号码为公民身份号码。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200058, '《中华人民共和国社会保险法》', '第五十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 社会保险费征缴', NULL, '县级以上人民政府加强社会保险费的征收工作。 社会保险费实行统一征收，实施步骤和具体办法由国务院规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200059, '《中华人民共和国社会保险法》', '第六十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 社会保险费征缴', NULL, '用人单位应当自行申报、按时足额缴纳社会保险费，非因不可抗力等法定事由不得缓缴、减免。职工应当缴纳的社会保险费由用人单位代扣代缴，用人单位应当按月将缴纳社会保险费的明细情况告知本人。 无雇工的个体工商户、未在用人单位参加社会保险的非全日制从业人员以及其他灵活就业人员，可以直接向社会保险费征收机构缴纳社会保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200060, '《中华人民共和国社会保险法》', '第六十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 社会保险费征缴', NULL, '社会保险费征收机构应当依法按时足额征收社会保险费，并将缴费情况定期告知用人单位和个人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200061, '《中华人民共和国社会保险法》', '第六十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 社会保险费征缴', NULL, '用人单位未按规定申报应当缴纳的社会保险费数额的，按照该单位上月缴费额的百分之一百一十确定应当缴纳数额；缴费单位补办申报手续后，由社会保险费征收机构按照规定结算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200062, '《中华人民共和国社会保险法》', '第六十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 社会保险费征缴', NULL, '用人单位未按时足额缴纳社会保险费的，由社会保险费征收机构责令其限期缴纳或者补足。 用人单位逾期仍未缴纳或者补足社会保险费的，社会保险费征收机构可以向银行和其他金融机构查询其存款账户；并可以申请县级以上有关行政部门作出划拨社会保险费的决定，书面通知其开户银行或者其他金融机构划拨社会保险费。用人单位账户余额少于应当缴纳的社会保险费的，社会保险费征收机构可以要求该用人单位提供担保，签订延期缴费协议。 用人单位未足额缴纳社会保险费且未提供担保的，社会保险费征收机构可以申请人民法院扣押、查封、拍卖其价值相当于应当缴纳社会保险费的财产，以拍卖所得抵缴社会保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200063, '《中华人民共和国社会保险法》', '第六十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 社会保险基金', NULL, '社会保险基金包括基本养老保险基金、基本医疗保险基金、工伤保险基金、失业保险基金和生育保险基金。除基本医疗保险基金与生育保险基金合并建账及核算外，其他各项社会保险基金按照社会保险险种分别建账，分账核算。社会保险基金执行国家统一的会计制度。 社会保险基金专款专用，任何组织和个人不得侵占或者挪用。 基本养老保险基金逐步实行全国统筹，其他社会保险基金逐步实行省级统筹，具体时间、步骤由国务院规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200064, '《中华人民共和国社会保险法》', '第六十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 社会保险基金', NULL, '社会保险基金通过预算实现收支平衡。 县级以上人民政府在社会保险基金出现支付不足时，给予补贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200065, '《中华人民共和国社会保险法》', '第六十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 社会保险基金', NULL, '社会保险基金按照统筹层次设立预算。除基本医疗保险基金与生育保险基金预算合并编制外，其他社会保险基金预算按照社会保险项目分别编制。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200066, '《中华人民共和国社会保险法》', '第六十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 社会保险基金', NULL, '社会保险基金预算、决算草案的编制、审核和批准，依照法律和国务院规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200067, '《中华人民共和国社会保险法》', '第六十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 社会保险基金', NULL, '社会保险基金存入财政专户，具体管理办法由国务院规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200068, '《中华人民共和国社会保险法》', '第六十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 社会保险基金', NULL, '社会保险基金在保证安全的前提下，按照国务院规定投资运营实现保值增值。 社会保险基金不得违规投资运营，不得用于平衡其他政府预算，不得用于兴建、改建办公场所和支付人员经费、运行费用、管理费用，或者违反法律、行政法规规定挪作其他用途。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200069, '《中华人民共和国社会保险法》', '第七十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 社会保险基金', NULL, '社会保险经办机构应当定期向社会公布参加社会保险情况以及社会保险基金的收入、支出、结余和收益情况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200070, '《中华人民共和国社会保险法》', '第七十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 社会保险基金', NULL, '国家设立全国社会保障基金，由中央财政预算拨款以及国务院批准的其他方式筹集的资金构成，用于社会保障支出的补充、调剂。全国社会保障基金由全国社会保障基金管理运营机构负责管理运营，在保证安全的前提下实现保值增值。 全国社会保障基金应当定期向社会公布收支、管理和投资运营的情况。国务院财政部门、社会保险行政部门、审计机关对全国社会保障基金的收支、管理和投资运营情况实施监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200071, '《中华人民共和国社会保险法》', '第七十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第九章 社会保险经办', NULL, '统筹地区设立社会保险经办机构。社会保险经办机构根据工作需要，经所在地的社会保险行政部门和机构编制管理机关批准，可以在本统筹地区设立分支机构和服务网点。 社会保险经办机构的人员经费和经办社会保险发生的基本运行费用、管理费用，由同级财政按照国家规定予以保障。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200072, '《中华人民共和国社会保险法》', '第七十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第九章 社会保险经办', NULL, '社会保险经办机构应当建立健全业务、财务、安全和风险管理制度。 社会保险经办机构应当按时足额支付社会保险待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200073, '《中华人民共和国社会保险法》', '第七十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第九章 社会保险经办', NULL, '社会保险经办机构通过业务经办、统计、调查获取社会保险工作所需的数据，有关单位和个人应当及时、如实提供。 社会保险经办机构应当及时为用人单位建立档案，完整、准确地记录参加社会保险的人员、缴费等社会保险数据，妥善保管登记、申报的原始凭证和支付结算的会计凭证。 社会保险经办机构应当及时、完整、准确地记录参加社会保险的个人缴费和用人单位为其缴费，以及享受社会保险待遇等个人权益记录，定期将个人权益记录单免费寄送本人。 用人单位和个人可以免费向社会保险经办机构查询、核对其缴费和享受社会保险待遇记录，要求社会保险经办机构提供社会保险咨询等相关服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200074, '《中华人民共和国社会保险法》', '第七十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第九章 社会保险经办', NULL, '全国社会保险信息系统按照国家统一规划，由县级以上人民政府按照分级负责的原则共同建设。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200075, '《中华人民共和国社会保险法》', '第七十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 社会保险监督', NULL, '各级人民代表大会常务委员会听取和审议本级人民政府对社会保险基金的收支、管理、投资运营以及监督检查情况的专项工作报告，组织对本法实施情况的执法检查等，依法行使监督职权。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200076, '《中华人民共和国社会保险法》', '第七十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 社会保险监督', NULL, '县级以上人民政府社会保险行政部门应当加强对用人单位和个人遵守社会保险法律、法规情况的监督检查。 社会保险行政部门实施监督检查时，被检查的用人单位和个人应当如实提供与社会保险有关的资料，不得拒绝检查或者谎报、瞒报。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200077, '《中华人民共和国社会保险法》', '第七十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 社会保险监督', NULL, '财政部门、审计机关按照各自职责，对社会保险基金的收支、管理和投资运营情况实施监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200078, '《中华人民共和国社会保险法》', '第七十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 社会保险监督', NULL, '社会保险行政部门对社会保险基金的收支、管理和投资运营情况进行监督检查，发现存在问题的，应当提出整改建议，依法作出处理决定或者向有关行政部门提出处理建议。社会保险基金检查结果应当定期向社会公布。 社会保险行政部门对社会保险基金实施监督检查，有权采取下列措施： （一）查阅、记录、复制与社会保险基金收支、管理和投资运营相关的资料，对可能被转移、隐匿或者灭失的资料予以封存； （二）询问与调查事项有关的单位和个人，要求其对与调查事项有关的问题作出说明、提供有关证明材料； （三）对隐匿、转移、侵占、挪用社会保险基金的行为予以制止并责令改正。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200079, '《中华人民共和国社会保险法》', '第八十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 社会保险监督', NULL, '统筹地区人民政府成立由用人单位代表、参保人员代表，以及工会代表、专家等组成的社会保险监督委员会，掌握、分析社会保险基金的收支、管理和投资运营情况，对社会保险工作提出咨询意见和建议，实施社会监督。 社会保险经办机构应当定期向社会保险监督委员会汇报社会保险基金的收支、管理和投资运营情况。社会保险监督委员会可以聘请会计师事务所对社会保险基金的收支、管理和投资运营情况进行年度审计和专项审计。审计结果应当向社会公开。 社会保险监督委员会发现社会保险基金收支、管理和投资运营中存在问题的，有权提出改正建议；对社会保险经办机构及其工作人员的违法行为，有权向有关部门提出依法处理建议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200080, '《中华人民共和国社会保险法》', '第八十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 社会保险监督', NULL, '社会保险行政部门和其他有关行政部门、社会保险经办机构、社会保险费征收机构及其工作人员，应当依法为用人单位和个人的信息保密，不得以任何形式泄露。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200081, '《中华人民共和国社会保险法》', '第八十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 社会保险监督', NULL, '任何组织或者个人有权对违反社会保险法律、法规的行为进行举报、投诉。 社会保险行政部门、卫生行政部门、社会保险经办机构、社会保险费征收机构和财政部门、审计机关对属于本部门、本机构职责范围的举报、投诉，应当依法处理；对不属于本部门、本机构职责范围的，应当书面通知并移交有权处理的部门、机构处理。有权处理的部门、机构应当及时处理，不得推诿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200082, '《中华人民共和国社会保险法》', '第八十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十章 社会保险监督', NULL, '用人单位或者个人认为社会保险费征收机构的行为侵害自己合法权益的，可以依法申请行政复议或者提起行政诉讼。 用人单位或者个人对社会保险经办机构不依法办理社会保险登记、核定社会保险费、支付社会保险待遇、办理社会保险转移接续手续或者侵害其他社会保险权益的行为，可以依法申请行政复议或者提起行政诉讼。 个人与所在用人单位发生社会保险争议的，可以依法申请调解、仲裁，提起诉讼。用人单位侵害个人社会保险权益的，个人也可以要求社会保险行政部门或者社会保险费征收机构依法处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200083, '《中华人民共和国社会保险法》', '第八十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '用人单位不办理社会保险登记的，由社会保险行政部门责令限期改正；逾期不改正的，对用人单位处应缴社会保险费数额一倍以上三倍以下的罚款，对其直接负责的主管人员和其他直接责任人员处五百元以上三千元以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200084, '《中华人民共和国社会保险法》', '第八十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '用人单位拒不出具终止或者解除劳动关系证明的，依照《中华人民共和国劳动合同法》的规定处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200085, '《中华人民共和国社会保险法》', '第八十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '用人单位未按时足额缴纳社会保险费的，由社会保险费征收机构责令限期缴纳或者补足，并自欠缴之日起，按日加收万分之五的滞纳金；逾期仍不缴纳的，由有关行政部门处欠缴数额一倍以上三倍以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200086, '《中华人民共和国社会保险法》', '第八十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '社会保险经办机构以及医疗机构、药品经营单位等社会保险服务机构以欺诈、伪造证明材料或者其他手段骗取社会保险基金支出的，由社会保险行政部门责令退回骗取的社会保险金，处骗取金额二倍以上五倍以下的罚款；属于社会保险服务机构的，解除服务协议；直接负责的主管人员和其他直接责任人员有执业资格的，依法吊销其执业资格。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200087, '《中华人民共和国社会保险法》', '第八十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '以欺诈、伪造证明材料或者其他手段骗取社会保险待遇的，由社会保险行政部门责令退回骗取的社会保险金，处骗取金额二倍以上五倍以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200088, '《中华人民共和国社会保险法》', '第八十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '社会保险经办机构及其工作人员有下列行为之一的，由社会保险行政部门责令改正；给社会保险基金、用人单位或者个人造成损失的，依法承担赔偿责任；对直接负责的主管人员和其他直接责任人员依法给予处分： （一）未履行社会保险法定职责的； （二）未将社会保险基金存入财政专户的； （三）克扣或者拒不按时支付社会保险待遇的； （四）丢失或者篡改缴费记录、享受社会保险待遇记录等社会保险数据、个人权益记录的； （五）有违反社会保险法律、法规的其他行为的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200089, '《中华人民共和国社会保险法》', '第九十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '社会保险费征收机构擅自更改社会保险费缴费基数、费率，导致少收或者多收社会保险费的，由有关行政部门责令其追缴应当缴纳的社会保险费或者退还不应当缴纳的社会保险费；对直接负责的主管人员和其他直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200090, '《中华人民共和国社会保险法》', '第九十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '违反本法规定，隐匿、转移、侵占、挪用社会保险基金或者违规投资运营的，由社会保险行政部门、财政部门、审计机关责令追回；有违法所得的，没收违法所得；对直接负责的主管人员和其他直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200091, '《中华人民共和国社会保险法》', '第九十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '社会保险行政部门和其他有关行政部门、社会保险经办机构、社会保险费征收机构及其工作人员泄露用人单位和个人信息的，对直接负责的主管人员和其他直接责任人员依法给予处分；给用人单位或者个人造成损失的，应当承担赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200092, '《中华人民共和国社会保险法》', '第九十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '国家工作人员在社会保险管理、监督工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200093, '《中华人民共和国社会保险法》', '第九十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十一章 法律责任', NULL, '违反本法规定，构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200094, '《中华人民共和国社会保险法》', '第九十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 附 则', NULL, '进城务工的农村居民依照本法规定参加社会保险。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200095, '《中华人民共和国社会保险法》', '第九十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 附 则', NULL, '征收农村集体所有的土地，应当足额安排被征地农民的社会保险费，按照国务院规定将被征地农民纳入相应的社会保险制度。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200096, '《中华人民共和国社会保险法》', '第九十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 附 则', NULL, '外国人在中国境内就业的，参照本法规定参加社会保险。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (200097, '《中华人民共和国社会保险法》', '第九十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第十二章 附 则', NULL, '本法自2011年7月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201000, '《中华人民共和国工会法》', '第一条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第一章 总 则', NULL, '为保障工会在国家政治、经济和社会生活中的地位，确定工会的权利与义务，发挥工会在社会主义现代化建设事业中的作用，根据宪法，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201001, '《中华人民共和国工会法》', '第二条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第一章 总 则', NULL, '工会是中国共产党领导的职工自愿结合的工人阶级群众组织，是中国共产党联系职工群众的桥梁和纽带。 中华全国总工会及其各工会组织代表职工的利益，依法维护职工的合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201002, '《中华人民共和国工会法》', '第三条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第一章 总 则', NULL, '在中国境内的企业、事业单位、机关、社会组织（以下统称用人单位）中以工资收入为主要生活来源的劳动者，不分民族、种族、性别、职业、宗教信仰、教育程度，都有依法参加和组织工会的权利。任何组织和个人不得阻挠和限制。 工会适应企业组织形式、职工队伍结构、劳动关系、就业形态等方面的发展变化，依法维护劳动者参加和组织工会的权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201003, '《中华人民共和国工会法》', '第四条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第一章 总 则', NULL, '工会必须遵守和维护宪法，以宪法为根本的活动准则，以经济建设为中心，坚持社会主义道路，坚持人民民主专政，坚持中国共产党的领导，坚持马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想，坚持改革开放，保持和增强政治性、先进性、群众性，依照工会章程独立自主地开展工作。 工会会员全国代表大会制定或者修改《中国工会章程》，章程不得与宪法和法律相抵触。 国家保护工会的合法权益不受侵犯。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201004, '《中华人民共和国工会法》', '第五条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第一章 总 则', NULL, '工会组织和教育职工依照宪法和法律的规定行使民主权利，发挥国家主人翁的作用，通过各种途径和形式，参与管理国家事务、管理经济和文化事业、管理社会事务；协助人民政府开展工作，维护工人阶级领导的、以工农联盟为基础的人民民主专政的社会主义国家政权。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201005, '《中华人民共和国工会法》', '第六条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第一章 总 则', NULL, '维护职工合法权益、竭诚服务职工群众是工会的基本职责。工会在维护全国人民总体利益的同时，代表和维护职工的合法权益。 工会通过平等协商和集体合同制度等，推动健全劳动关系协调机制，维护职工劳动权益，构建和谐劳动关系。 工会依照法律规定通过职工代表大会或者其他形式，组织职工参与本单位的民主选举、民主协商、民主决策、民主管理和民主监督。 工会建立联系广泛、服务职工的工会工作体系，密切联系职工，听取和反映职工的意见和要求，关心职工的生活，帮助职工解决困难，全心全意为职工服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201006, '《中华人民共和国工会法》', '第七条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第一章 总 则', NULL, '工会动员和组织职工积极参加经济建设，努力完成生产任务和工作任务。教育职工不断提高思想道德、技术业务和科学文化素质，建设有理想、有道德、有文化、有纪律的职工队伍。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201007, '《中华人民共和国工会法》', '第八条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第一章 总 则', NULL, '工会推动产业工人队伍建设改革，提高产业工人队伍整体素质，发挥产业工人骨干作用，维护产业工人合法权益，保障产业工人主人翁地位，造就一支有理想守信念、懂技术会创新、敢担当讲奉献的宏大产业工人队伍。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201008, '《中华人民共和国工会法》', '第九条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第一章 总 则', NULL, '中华全国总工会根据独立、平等、互相尊重、互不干涉内部事务的原则，加强同各国工会组织的友好合作关系。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201009, '《中华人民共和国工会法》', '第十条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第二章 工会组织', NULL, '工会各级组织按照民主集中制原则建立。 各级工会委员会由会员大会或者会员代表大会民主选举产生。企业主要负责人的近亲属不得作为本企业基层工会委员会成员的人选。 各级工会委员会向同级会员大会或者会员代表大会负责并报告工作，接受其监督。 工会会员大会或者会员代表大会有权撤换或者罢免其所选举的代表或者工会委员会组成人员。 上级工会组织领导下级工会组织。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201010, '《中华人民共和国工会法》', '第十一条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第二章 工会组织', NULL, '用人单位有会员二十五人以上的，应当建立基层工会委员会；不足二十五人的，可以单独建立基层工会委员会，也可以由两个以上单位的会员联合建立基层工会委员会，也可以选举组织员一人，组织会员开展活动。女职工人数较多的，可以建立工会女职工委员会，在同级工会领导下开展工作；女职工人数较少的，可以在工会委员会中设女职工委员。 企业职工较多的乡镇、城市街道，可以建立基层工会的联合会。 县级以上地方建立地方各级总工会。 同一行业或者性质相近的几个行业，可以根据需要建立全国的或者地方的产业工会。 全国建立统一的中华全国总工会。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201011, '《中华人民共和国工会法》', '第十二条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第二章 工会组织', NULL, '基层工会、地方各级总工会、全国或者地方产业工会组织的建立，必须报上一级工会批准。 上级工会可以派员帮助和指导企业职工组建工会，任何单位和个人不得阻挠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201012, '《中华人民共和国工会法》', '第十三条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第二章 工会组织', NULL, '任何组织和个人不得随意撤销、合并工会组织。 基层工会所在的用人单位终止或者被撤销，该工会组织相应撤销，并报告上一级工会。 依前款规定被撤销的工会，其会员的会籍可以继续保留，具体管理办法由中华全国总工会制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201013, '《中华人民共和国工会法》', '第十四条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第二章 工会组织', NULL, '职工二百人以上的企业、事业单位、社会组织的工会，可以设专职工会主席。工会专职工作人员的人数由工会与企业、事业单位、社会组织协商确定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201014, '《中华人民共和国工会法》', '第十五条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第二章 工会组织', NULL, '中华全国总工会、地方总工会、产业工会具有社会团体法人资格。 基层工会组织具备民法典规定的法人条件的，依法取得社会团体法人资格。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201015, '《中华人民共和国工会法》', '第十六条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第二章 工会组织', NULL, '基层工会委员会每届任期三年或者五年。各级地方总工会委员会和产业工会委员会每届任期五年。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201016, '《中华人民共和国工会法》', '第十七条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第二章 工会组织', NULL, '基层工会委员会定期召开会员大会或者会员代表大会，讨论决定工会工作的重大问题。经基层工会委员会或者三分之一以上的工会会员提议，可以临时召开会员大会或者会员代表大会。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201017, '《中华人民共和国工会法》', '第十八条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第二章 工会组织', NULL, '工会主席、副主席任期未满时，不得随意调动其工作。因工作需要调动时，应当征得本级工会委员会和上一级工会的同意。 罢免工会主席、副主席必须召开会员大会或者会员代表大会讨论，非经会员大会全体会员或者会员代表大会全体代表过半数通过，不得罢免。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201018, '《中华人民共和国工会法》', '第十九条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第二章 工会组织', NULL, '基层工会专职主席、副主席或者委员自任职之日起，其劳动合同期限自动延长，延长期限相当于其任职期间；非专职主席、副主席或者委员自任职之日起，其尚未履行的劳动合同期限短于任期的，劳动合同期限自动延长至任期期满。但是，任职期间个人严重过失或者达到法定退休年龄的除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201019, '《中华人民共和国工会法》', '第二十条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '企业、事业单位、社会组织违反职工代表大会制度和其他民主管理制度，工会有权要求纠正，保障职工依法行使民主管理的权利。 法律、法规规定应当提交职工大会或者职工代表大会审议、通过、决定的事项，企业、事业单位、社会组织应当依法办理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201020, '《中华人民共和国工会法》', '第二十一条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '工会帮助、指导职工与企业、实行企业化管理的事业单位、社会组织签订劳动合同。 工会代表职工与企业、实行企业化管理的事业单位、社会组织进行平等协商，依法签订集体合同。集体合同草案应当提交职工代表大会或者全体职工讨论通过。 工会签订集体合同，上级工会应当给予支持和帮助。 企业、事业单位、社会组织违反集体合同，侵犯职工劳动权益的，工会可以依法要求企业、事业单位、社会组织予以改正并承担责任；因履行集体合同发生争议，经协商解决不成的，工会可以向劳动争议仲裁机构提请仲裁，仲裁机构不予受理或者对仲裁裁决不服的，可以向人民法院提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201021, '《中华人民共和国工会法》', '第二十二条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '企业、事业单位、社会组织处分职工，工会认为不适当的，有权提出意见。 用人单位单方面解除职工劳动合同时，应当事先将理由通知工会，工会认为用人单位违反法律、法规和有关合同，要求重新研究处理时，用人单位应当研究工会的意见，并将处理结果书面通知工会。 职工认为用人单位侵犯其劳动权益而申请劳动争议仲裁或者向人民法院提起诉讼的，工会应当给予支持和帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201022, '《中华人民共和国工会法》', '第二十三条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '企业、事业单位、社会组织违反劳动法律法规规定，有下列侵犯职工劳动权益情形，工会应当代表职工与企业、事业单位、社会组织交涉，要求企业、事业单位、社会组织采取措施予以改正；企业、事业单位、社会组织应当予以研究处理，并向工会作出答复；企业、事业单位、社会组织拒不改正的，工会可以提请当地人民政府依法作出处理： （一）克扣、拖欠职工工资的； （二）不提供劳动安全卫生条件的； （三）随意延长劳动时间的； （四）侵犯女职工和未成年工特殊权益的； （五）其他严重侵犯职工劳动权益的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201023, '《中华人民共和国工会法》', '第二十四条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '工会依照国家规定对新建、扩建企业和技术改造工程中的劳动条件和安全卫生设施与主体工程同时设计、同时施工、同时投产使用进行监督。对工会提出的意见，企业或者主管部门应当认真处理，并将处理结果书面通知工会。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201024, '《中华人民共和国工会法》', '第二十五条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '工会发现企业违章指挥、强令工人冒险作业，或者生产过程中发现明显重大事故隐患和职业危害，有权提出解决的建议，企业应当及时研究答复；发现危及职工生命安全的情况时，工会有权向企业建议组织职工撤离危险现场，企业必须及时作出处理决定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201025, '《中华人民共和国工会法》', '第二十六条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '工会有权对企业、事业单位、社会组织侵犯职工合法权益的问题进行调查，有关单位应当予以协助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201026, '《中华人民共和国工会法》', '第二十七条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '职工因工伤亡事故和其他严重危害职工健康问题的调查处理，必须有工会参加。工会应当向有关部门提出处理意见，并有权要求追究直接负责的主管人员和有关责任人员的责任。对工会提出的意见，应当及时研究，给予答复。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201027, '《中华人民共和国工会法》', '第二十八条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '企业、事业单位、社会组织发生停工、怠工事件，工会应当代表职工同企业、事业单位、社会组织或者有关方面协商，反映职工的意见和要求并提出解决意见。对于职工的合理要求，企业、事业单位、社会组织应当予以解决。工会协助企业、事业单位、社会组织做好工作，尽快恢复生产、工作秩序。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201028, '《中华人民共和国工会法》', '第二十九条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '工会参加企业的劳动争议调解工作。 地方劳动争议仲裁组织应当有同级工会代表参加。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201029, '《中华人民共和国工会法》', '第三十条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '县级以上各级总工会依法为所属工会和职工提供法律援助等法律服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201030, '《中华人民共和国工会法》', '第三十一条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '工会协助用人单位办好职工集体福利事业，做好工资、劳动安全卫生和社会保险工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201031, '《中华人民共和国工会法》', '第三十二条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '工会会同用人单位加强对职工的思想政治引领，教育职工以国家主人翁态度对待劳动，爱护国家和单位的财产；组织职工开展群众性的合理化建议、技术革新、劳动和技能竞赛活动，进行业余文化技术学习和职工培训，参加职业教育和文化体育活动，推进职业安全健康教育和劳动保护工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201032, '《中华人民共和国工会法》', '第三十三条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '根据政府委托，工会与有关部门共同做好劳动模范和先进生产（工作）者的评选、表彰、培养和管理工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201033, '《中华人民共和国工会法》', '第三十四条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '国家机关在组织起草或者修改直接涉及职工切身利益的法律、法规、规章时，应当听取工会意见。 县级以上各级人民政府制定国民经济和社会发展计划，对涉及职工利益的重大问题，应当听取同级工会的意见。 县级以上各级人民政府及其有关部门研究制定劳动就业、工资、劳动安全卫生、社会保险等涉及职工切身利益的政策、措施时，应当吸收同级工会参加研究，听取工会意见。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201034, '《中华人民共和国工会法》', '第三十五条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第三章 工会的权利和义务', NULL, '县级以上地方各级人民政府可以召开会议或者采取适当方式，向同级工会通报政府的重要的工作部署和与工会工作有关的行政措施，研究解决工会反映的职工群众的意见和要求。 各级人民政府劳动行政部门应当会同同级工会和企业方面代表，建立劳动关系三方协商机制，共同研究解决劳动关系方面的重大问题。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201035, '《中华人民共和国工会法》', '第三十六条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第四章 基层工会组织', NULL, '国有企业职工代表大会是企业实行民主管理的基本形式，是职工行使民主管理权力的机构，依照法律规定行使职权。 国有企业的工会委员会是职工代表大会的工作机构，负责职工代表大会的日常工作，检查、督促职工代表大会决议的执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201036, '《中华人民共和国工会法》', '第三十七条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第四章 基层工会组织', NULL, '集体企业的工会委员会，应当支持和组织职工参加民主管理和民主监督，维护职工选举和罢免管理人员、决定经营管理的重大问题的权力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201037, '《中华人民共和国工会法》', '第三十八条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第四章 基层工会组织', NULL, '本法第三十六条、第三十七条规定以外的其他企业、事业单位的工会委员会，依照法律规定组织职工采取与企业、事业单位相适应的形式，参与企业、事业单位民主管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201038, '《中华人民共和国工会法》', '第三十九条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第四章 基层工会组织', NULL, '企业、事业单位、社会组织研究经营管理和发展的重大问题应当听取工会的意见；召开会议讨论有关工资、福利、劳动安全卫生、工作时间、休息休假、女职工保护和社会保险等涉及职工切身利益的问题，必须有工会代表参加。 企业、事业单位、社会组织应当支持工会依法开展工作，工会应当支持企业、事业单位、社会组织依法行使经营管理权。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201039, '《中华人民共和国工会法》', '第四十条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第四章 基层工会组织', NULL, '公司的董事会、监事会中职工代表的产生，依照公司法有关规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201040, '《中华人民共和国工会法》', '第四十一条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第四章 基层工会组织', NULL, '基层工会委员会召开会议或者组织职工活动，应当在生产或者工作时间以外进行，需要占用生产或者工作时间的，应当事先征得企业、事业单位、社会组织的同意。 基层工会的非专职委员占用生产或者工作时间参加会议或者从事工会工作，每月不超过三个工作日，其工资照发，其他待遇不受影响。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201041, '《中华人民共和国工会法》', '第四十二条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第四章 基层工会组织', NULL, '用人单位工会委员会的专职工作人员的工资、奖励、补贴，由所在单位支付。社会保险和其他福利待遇等，享受本单位职工同等待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201042, '《中华人民共和国工会法》', '第四十三条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第五章 工会的经费和财产', NULL, '工会经费的来源： （一）工会会员缴纳的会费； （二）建立工会组织的用人单位按每月全部职工工资总额的百分之二向工会拨缴的经费； （三）工会所属的企业、事业单位上缴的收入； （四）人民政府的补助； （五）其他收入。 前款第二项规定的企业、事业单位、社会组织拨缴的经费在税前列支。 工会经费主要用于为职工服务和工会活动。经费使用的具体办法由中华全国总工会制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201043, '《中华人民共和国工会法》', '第四十四条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第五章 工会的经费和财产', NULL, '企业、事业单位、社会组织无正当理由拖延或者拒不拨缴工会经费，基层工会或者上级工会可以向当地人民法院申请支付令；拒不执行支付令的，工会可以依法申请人民法院强制执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201044, '《中华人民共和国工会法》', '第四十五条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第五章 工会的经费和财产', NULL, '工会应当根据经费独立原则，建立预算、决算和经费审查监督制度。 各级工会建立经费审查委员会。 各级工会经费收支情况应当由同级工会经费审查委员会审查，并且定期向会员大会或者会员代表大会报告，接受监督。工会会员大会或者会员代表大会有权对经费使用情况提出意见。 工会经费的使用应当依法接受国家的监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201045, '《中华人民共和国工会法》', '第四十六条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第五章 工会的经费和财产', NULL, '各级人民政府和用人单位应当为工会办公和开展活动，提供必要的设施和活动场所等物质条件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201046, '《中华人民共和国工会法》', '第四十七条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第五章 工会的经费和财产', NULL, '工会的财产、经费和国家拨给工会使用的不动产，任何组织和个人不得侵占、挪用和任意调拨。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201047, '《中华人民共和国工会法》', '第四十八条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第五章 工会的经费和财产', NULL, '工会所属的为职工服务的企业、事业单位，其隶属关系不得随意改变。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201048, '《中华人民共和国工会法》', '第四十九条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第五章 工会的经费和财产', NULL, '县级以上各级工会的离休、退休人员的待遇，与国家机关工作人员同等对待。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201049, '《中华人民共和国工会法》', '第五十条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第六章 法律责任', NULL, '工会对违反本法规定侵犯其合法权益的，有权提请人民政府或者有关部门予以处理，或者向人民法院提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201050, '《中华人民共和国工会法》', '第五十一条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第六章 法律责任', NULL, '违反本法第三条、第十二条规定，阻挠职工依法参加和组织工会或者阻挠上级工会帮助、指导职工筹建工会的，由劳动行政部门责令其改正；拒不改正的，由劳动行政部门提请县级以上人民政府处理；以暴力、威胁等手段阻挠造成严重后果，构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201051, '《中华人民共和国工会法》', '第五十二条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第六章 法律责任', NULL, '违反本法规定，对依法履行职责的工会工作人员无正当理由调动工作岗位，进行打击报复的，由劳动行政部门责令改正、恢复原工作；造成损失的，给予赔偿。 对依法履行职责的工会工作人员进行侮辱、诽谤或者进行人身伤害，构成犯罪的，依法追究刑事责任；尚未构成犯罪的，由公安机关依照治安管理处罚法的规定处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201052, '《中华人民共和国工会法》', '第五十三条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第六章 法律责任', NULL, '违反本法规定，有下列情形之一的，由劳动行政部门责令恢复其工作，并补发被解除劳动合同期间应得的报酬，或者责令给予本人年收入二倍的赔偿： （一）职工因参加工会活动而被解除劳动合同的； （二）工会工作人员因履行本法规定的职责而被解除劳动合同的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201053, '《中华人民共和国工会法》', '第五十四条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第六章 法律责任', NULL, '违反本法规定，有下列情形之一的，由县级以上人民政府责令改正，依法处理： （一）妨碍工会组织职工通过职工代表大会和其他形式依法行使民主权利的； （二）非法撤销、合并工会组织的； （三）妨碍工会参加职工因工伤亡事故以及其他侵犯职工合法权益问题的调查处理的； （四）无正当理由拒绝进行平等协商的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201054, '《中华人民共和国工会法》', '第五十五条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第六章 法律责任', NULL, '违反本法第四十七条规定，侵占工会经费和财产拒不返还的，工会可以向人民法院提起诉讼，要求返还，并赔偿损失。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201055, '《中华人民共和国工会法》', '第五十六条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第六章 法律责任', NULL, '工会工作人员违反本法规定，损害职工或者工会权益的，由同级工会或者上级工会责令改正，或者予以处分；情节严重的，依照《中国工会章程》予以罢免；造成损失的，应当承担赔偿责任；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201056, '《中华人民共和国工会法》', '第五十七条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第七章 附 则', NULL, '中华全国总工会会同有关国家机关制定机关工会实施本法的具体办法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (201057, '《中华人民共和国工会法》', '第五十八条', '劳动', '法律', NULL, '全国人民代表大会 2021-12-24', '第七章 附 则', NULL, '本法自公布之日起施行。1950年6月29日中央人民政府颁布的《中华人民共和国工会法》同时废止。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202000, '《中华人民共和国就业促进法》', '第一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第一章 总 则', NULL, '为了促进就业，促进经济发展与扩大就业相协调，促进社会和谐稳定，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202001, '《中华人民共和国就业促进法》', '第二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第一章 总 则', NULL, '国家把扩大就业放在经济社会发展的突出位置，实施积极的就业政策，坚持劳动者自主择业、市场调节就业、政府促进就业的方针，多渠道扩大就业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202002, '《中华人民共和国就业促进法》', '第三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第一章 总 则', NULL, '劳动者依法享有平等就业和自主择业的权利。 劳动者就业，不因民族、种族、性别、宗教信仰等不同而受歧视。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202003, '《中华人民共和国就业促进法》', '第四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第一章 总 则', NULL, '县级以上人民政府把扩大就业作为经济和社会发展的重要目标，纳入国民经济和社会发展规划，并制定促进就业的中长期规划和年度工作计划。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202004, '《中华人民共和国就业促进法》', '第五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第一章 总 则', NULL, '县级以上人民政府通过发展经济和调整产业结构、规范人力资源市场、完善就业服务、加强职业教育和培训、提供就业援助等措施，创造就业条件，扩大就业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202005, '《中华人民共和国就业促进法》', '第六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第一章 总 则', NULL, '国务院建立全国促进就业工作协调机制，研究就业工作中的重大问题，协调推动全国的促进就业工作。国务院劳动行政部门具体负责全国的促进就业工作。 省、自治区、直辖市人民政府根据促进就业工作的需要，建立促进就业工作协调机制，协调解决本行政区域就业工作中的重大问题。 县级以上人民政府有关部门按照各自的职责分工，共同做好促进就业工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202006, '《中华人民共和国就业促进法》', '第七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第一章 总 则', NULL, '国家倡导劳动者树立正确的择业观念，提高就业能力和创业能力；鼓励劳动者自主创业、自谋职业。 各级人民政府和有关部门应当简化程序，提高效率，为劳动者自主创业、自谋职业提供便利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202007, '《中华人民共和国就业促进法》', '第八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第一章 总 则', NULL, '用人单位依法享有自主用人的权利。 用人单位应当依照本法以及其他法律、法规的规定，保障劳动者的合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202008, '《中华人民共和国就业促进法》', '第九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第一章 总 则', NULL, '工会、共产主义青年团、妇女联合会、残疾人联合会以及其他社会组织，协助人民政府开展促进就业工作，依法维护劳动者的劳动权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202009, '《中华人民共和国就业促进法》', '第十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第一章 总 则', NULL, '各级人民政府和有关部门对在促进就业工作中作出显著成绩的单位和个人，给予表彰和奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202010, '《中华人民共和国就业促进法》', '第十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '县级以上人民政府应当把扩大就业作为重要职责，统筹协调产业政策与就业政策。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202011, '《中华人民共和国就业促进法》', '第十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '国家鼓励各类企业在法律、法规规定的范围内，通过兴办产业或者拓展经营，增加就业岗位。 国家鼓励发展劳动密集型产业、服务业，扶持中小企业，多渠道、多方式增加就业岗位。 国家鼓励、支持、引导非公有制经济发展，扩大就业，增加就业岗位。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202012, '《中华人民共和国就业促进法》', '第十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '国家发展国内外贸易和国际经济合作，拓宽就业渠道。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202013, '《中华人民共和国就业促进法》', '第十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '县级以上人民政府在安排政府投资和确定重大建设项目时，应当发挥投资和重大建设项目带动就业的作用，增加就业岗位。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202014, '《中华人民共和国就业促进法》', '第十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '国家实行有利于促进就业的财政政策，加大资金投入，改善就业环境，扩大就业。 县级以上人民政府应当根据就业状况和就业工作目标，在财政预算中安排就业专项资金用于促进就业工作。 就业专项资金用于职业介绍、职业培训、公益性岗位、职业技能鉴定、特定就业政策和社会保险等的补贴，小额贷款担保基金和微利项目的小额担保贷款贴息，以及扶持公共就业服务等。就业专项资金的使用管理办法由国务院财政部门和劳动行政部门规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202015, '《中华人民共和国就业促进法》', '第十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '国家建立健全失业保险制度，依法确保失业人员的基本生活，并促进其实现就业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202016, '《中华人民共和国就业促进法》', '第十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '国家鼓励企业增加就业岗位，扶持失业人员和残疾人就业，对下列企业、人员依法给予税收优惠： （一）吸纳符合国家规定条件的失业人员达到规定要求的企业； （二）失业人员创办的中小企业； （三）安置残疾人员达到规定比例或者集中使用残疾人的企业； （四）从事个体经营的符合国家规定条件的失业人员； （五）从事个体经营的残疾人； （六）国务院规定给予税收优惠的其他企业、人员。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202017, '《中华人民共和国就业促进法》', '第十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '对本法第十七条第四项、第五项规定的人员，有关部门应当在经营场地等方面给予照顾，免除行政事业性收费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202018, '《中华人民共和国就业促进法》', '第十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '国家实行有利于促进就业的金融政策，增加中小企业的融资渠道；鼓励金融机构改进金融服务，加大对中小企业的信贷支持，并对自主创业人员在一定期限内给予小额信贷等扶持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202019, '《中华人民共和国就业促进法》', '第二十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '国家实行城乡统筹的就业政策，建立健全城乡劳动者平等就业的制度，引导农业富余劳动力有序转移就业。 县级以上地方人民政府推进小城镇建设和加快县域经济发展，引导农业富余劳动力就地就近转移就业；在制定小城镇规划时，将本地区农业富余劳动力转移就业作为重要内容。 县级以上地方人民政府引导农业富余劳动力有序向城市异地转移就业；劳动力输出地和输入地人民政府应当互相配合，改善农村劳动者进城就业的环境和条件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202020, '《中华人民共和国就业促进法》', '第二十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '国家支持区域经济发展，鼓励区域协作，统筹协调不同地区就业的均衡增长。 国家支持民族地区发展经济，扩大就业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202021, '《中华人民共和国就业促进法》', '第二十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '各级人民政府统筹做好城镇新增劳动力就业、农业富余劳动力转移就业和失业人员就业工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202022, '《中华人民共和国就业促进法》', '第二十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '各级人民政府采取措施，逐步完善和实施与非全日制用工等灵活就业相适应的劳动和社会保险政策，为灵活就业人员提供帮助和服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202023, '《中华人民共和国就业促进法》', '第二十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第二章 政策支持', NULL, '地方各级人民政府和有关部门应当加强对失业人员从事个体经营的指导，提供政策咨询、就业培训和开业指导等服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202024, '《中华人民共和国就业促进法》', '第二十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第三章 公平就业', NULL, '各级人民政府创造公平就业的环境，消除就业歧视，制定政策并采取措施对就业困难人员给予扶持和援助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202025, '《中华人民共和国就业促进法》', '第二十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第三章 公平就业', NULL, '用人单位招用人员、职业中介机构从事职业中介活动，应当向劳动者提供平等的就业机会和公平的就业条件，不得实施就业歧视。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202026, '《中华人民共和国就业促进法》', '第二十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第三章 公平就业', NULL, '国家保障妇女享有与男子平等的劳动权利。 用人单位招用人员，除国家规定的不适合妇女的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。 用人单位录用女职工，不得在劳动合同中规定限制女职工结婚、生育的内容。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202027, '《中华人民共和国就业促进法》', '第二十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第三章 公平就业', NULL, '各民族劳动者享有平等的劳动权利。 用人单位招用人员，应当依法对少数民族劳动者给予适当照顾。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202028, '《中华人民共和国就业促进法》', '第二十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第三章 公平就业', NULL, '国家保障残疾人的劳动权利。 各级人民政府应当对残疾人就业统筹规划，为残疾人创造就业条件。 用人单位招用人员，不得歧视残疾人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202029, '《中华人民共和国就业促进法》', '第三十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第三章 公平就业', NULL, '用人单位招用人员，不得以是传染病病原携带者为由拒绝录用。但是，经医学鉴定传染病病原携带者在治愈前或者排除传染嫌疑前，不得从事法律、行政法规和国务院卫生行政部门规定禁止从事的易使传染病扩散的工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202030, '《中华人民共和国就业促进法》', '第三十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第三章 公平就业', NULL, '农村劳动者进城就业享有与城镇劳动者平等的劳动权利，不得对农村劳动者进城就业设置歧视性限制。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202031, '《中华人民共和国就业促进法》', '第三十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '县级以上人民政府培育和完善统一开放、竞争有序的人力资源市场，为劳动者就业提供服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202032, '《中华人民共和国就业促进法》', '第三十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '县级以上人民政府鼓励社会各方面依法开展就业服务活动，加强对公共就业服务和职业中介服务的指导和监督，逐步完善覆盖城乡的就业服务体系。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202033, '《中华人民共和国就业促进法》', '第三十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '县级以上人民政府加强人力资源市场信息网络及相关设施建设，建立健全人力资源市场信息服务体系，完善市场信息发布制度。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202034, '《中华人民共和国就业促进法》', '第三十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '县级以上人民政府建立健全公共就业服务体系，设立公共就业服务机构，为劳动者免费提供下列服务： （一）就业政策法规咨询； （二）职业供求信息、市场工资指导价位信息和职业培训信息发布； （三）职业指导和职业介绍； （四）对就业困难人员实施就业援助； （五）办理就业登记、失业登记等事务； （六）其他公共就业服务。 公共就业服务机构应当不断提高服务的质量和效率，不得从事经营性活动。 公共就业服务经费纳入同级财政预算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202035, '《中华人民共和国就业促进法》', '第三十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '县级以上地方人民政府对职业中介机构提供公益性就业服务的，按照规定给予补贴。 国家鼓励社会各界为公益性就业服务提供捐赠、资助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202036, '《中华人民共和国就业促进法》', '第三十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '地方各级人民政府和有关部门不得举办或者与他人联合举办经营性的职业中介机构。 地方各级人民政府和有关部门、公共就业服务机构举办的招聘会，不得向劳动者收取费用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202037, '《中华人民共和国就业促进法》', '第三十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '县级以上人民政府和有关部门加强对职业中介机构的管理，鼓励其提高服务质量，发挥其在促进就业中的作用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202038, '《中华人民共和国就业促进法》', '第三十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '从事职业中介活动，应当遵循合法、诚实信用、公平、公开的原则。 用人单位通过职业中介机构招用人员，应当如实向职业中介机构提供岗位需求信息。 禁止任何组织或者个人利用职业中介活动侵害劳动者的合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202039, '《中华人民共和国就业促进法》', '第四十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '设立职业中介机构应当具备下列条件： （一）有明确的章程和管理制度； （二）有开展业务必备的固定场所、办公设施和一定数额的开办资金； （三）有一定数量具备相应职业资格的专职工作人员； （四）法律、法规规定的其他条件。 设立职业中介机构应当在工商行政管理部门办理登记后，向劳动行政部门申请行政许可。 未经依法许可和登记的机构，不得从事职业中介活动。 国家对外商投资职业中介机构和向劳动者提供境外就业服务的职业中介机构另有规定的，依照其规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202040, '《中华人民共和国就业促进法》', '第四十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '职业中介机构不得有下列行为： （一）提供虚假就业信息； （二）为无合法证照的用人单位提供职业中介服务； （三）伪造、涂改、转让职业中介许可证； （四）扣押劳动者的居民身份证和其他证件，或者向劳动者收取押金； （五）其他违反法律、法规规定的行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202041, '《中华人民共和国就业促进法》', '第四十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '县级以上人民政府建立失业预警制度，对可能出现的较大规模的失业，实施预防、调节和控制。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202042, '《中华人民共和国就业促进法》', '第四十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第四章 就业服务和管理', NULL, '国家建立劳动力调查统计制度和就业登记、失业登记制度，开展劳动力资源和就业、失业状况调查统计，并公布调查统计结果。 统计部门和劳动行政部门进行劳动力调查统计和就业、失业登记时，用人单位和个人应当如实提供调查统计和登记所需要的情况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202043, '《中华人民共和国就业促进法》', '第四十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第五章 职业教育和培训', NULL, '国家依法发展职业教育，鼓励开展职业培训，促进劳动者提高职业技能，增强就业能力和创业能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202044, '《中华人民共和国就业促进法》', '第四十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第五章 职业教育和培训', NULL, '县级以上人民政府根据经济社会发展和市场需求，制定并实施职业能力开发计划。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202045, '《中华人民共和国就业促进法》', '第四十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第五章 职业教育和培训', NULL, '县级以上人民政府加强统筹协调，鼓励和支持各类职业院校、职业技能培训机构和用人单位依法开展就业前培训、在职培训、再就业培训和创业培训；鼓励劳动者参加各种形式的培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202046, '《中华人民共和国就业促进法》', '第四十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第五章 职业教育和培训', NULL, '县级以上地方人民政府和有关部门根据市场需求和产业发展方向，鼓励、指导企业加强职业教育和培训。 职业院校、职业技能培训机构与企业应当密切联系，实行产教结合，为经济建设服务，培养实用人才和熟练劳动者。 企业应当按照国家有关规定提取职工教育经费，对劳动者进行职业技能培训和继续教育培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202047, '《中华人民共和国就业促进法》', '第四十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第五章 职业教育和培训', NULL, '国家采取措施建立健全劳动预备制度，县级以上地方人民政府对有就业要求的初高中毕业生实行一定期限的职业教育和培训，使其取得相应的职业资格或者掌握一定的职业技能。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202048, '《中华人民共和国就业促进法》', '第四十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第五章 职业教育和培训', NULL, '地方各级人民政府鼓励和支持开展就业培训，帮助失业人员提高职业技能，增强其就业能力和创业能力。失业人员参加就业培训的，按照有关规定享受政府培训补贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202049, '《中华人民共和国就业促进法》', '第五十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第五章 职业教育和培训', NULL, '地方各级人民政府采取有效措施，组织和引导进城就业的农村劳动者参加技能培训，鼓励各类培训机构为进城就业的农村劳动者提供技能培训，增强其就业能力和创业能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202050, '《中华人民共和国就业促进法》', '第五十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第五章 职业教育和培训', NULL, '国家对从事涉及公共安全、人身健康、生命财产安全等特殊工种的劳动者，实行职业资格证书制度，具体办法由国务院规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202051, '《中华人民共和国就业促进法》', '第五十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第六章 就业援助', NULL, '各级人民政府建立健全就业援助制度，采取税费减免、贷款贴息、社会保险补贴、岗位补贴等办法，通过公益性岗位安置等途径，对就业困难人员实行优先扶持和重点帮助。 就业困难人员是指因身体状况、技能水平、家庭因素、失去土地等原因难以实现就业，以及连续失业一定时间仍未能实现就业的人员。就业困难人员的具体范围，由省、自治区、直辖市人民政府根据本行政区域的实际情况规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202052, '《中华人民共和国就业促进法》', '第五十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第六章 就业援助', NULL, '政府投资开发的公益性岗位，应当优先安排符合岗位要求的就业困难人员。被安排在公益性岗位工作的，按照国家规定给予岗位补贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202053, '《中华人民共和国就业促进法》', '第五十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第六章 就业援助', NULL, '地方各级人民政府加强基层就业援助服务工作，对就业困难人员实施重点帮助，提供有针对性的就业服务和公益性岗位援助。 地方各级人民政府鼓励和支持社会各方面为就业困难人员提供技能培训、岗位信息等服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202054, '《中华人民共和国就业促进法》', '第五十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第六章 就业援助', NULL, '各级人民政府采取特别扶助措施，促进残疾人就业。 用人单位应当按照国家规定安排残疾人就业，具体办法由国务院规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202055, '《中华人民共和国就业促进法》', '第五十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第六章 就业援助', NULL, '县级以上地方人民政府采取多种就业形式，拓宽公益性岗位范围，开发就业岗位，确保城市有就业需求的家庭至少有一人实现就业。 法定劳动年龄内的家庭人员均处于失业状况的城市居民家庭，可以向住所地街道、社区公共就业服务机构申请就业援助。街道、社区公共就业服务机构经确认属实的，应当为该家庭中至少一人提供适当的就业岗位。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202056, '《中华人民共和国就业促进法》', '第五十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第六章 就业援助', NULL, '国家鼓励资源开采型城市和独立工矿区发展与市场需求相适应的产业，引导劳动者转移就业。 对因资源枯竭或者经济结构调整等原因造成就业困难人员集中的地区，上级人民政府应当给予必要的扶持和帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202057, '《中华人民共和国就业促进法》', '第五十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第七章 监督检查', NULL, '各级人民政府和有关部门应当建立促进就业的目标责任制度。县级以上人民政府按照促进就业目标责任制的要求，对所属的有关部门和下一级人民政府进行考核和监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202058, '《中华人民共和国就业促进法》', '第五十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第七章 监督检查', NULL, '审计机关、财政部门应当依法对就业专项资金的管理和使用情况进行监督检查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202059, '《中华人民共和国就业促进法》', '第六十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第七章 监督检查', NULL, '劳动行政部门应当对本法实施情况进行监督检查，建立举报制度，受理对违反本法行为的举报，并及时予以核实、处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202060, '《中华人民共和国就业促进法》', '第六十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第八章 法律责任', NULL, '违反本法规定，劳动行政等有关部门及其工作人员滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202061, '《中华人民共和国就业促进法》', '第六十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第八章 法律责任', NULL, '违反本法规定，实施就业歧视的，劳动者可以向人民法院提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202062, '《中华人民共和国就业促进法》', '第六十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第八章 法律责任', NULL, '违反本法规定，地方各级人民政府和有关部门、公共就业服务机构举办经营性的职业中介机构，从事经营性职业中介活动，向劳动者收取费用的，由上级主管机关责令限期改正，将违法收取的费用退还劳动者，并对直接负责的主管人员和其他直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202063, '《中华人民共和国就业促进法》', '第六十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第八章 法律责任', NULL, '违反本法规定，未经许可和登记，擅自从事职业中介活动的，由劳动行政部门或者其他主管部门依法予以关闭；有违法所得的，没收违法所得，并处一万元以上五万元以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202064, '《中华人民共和国就业促进法》', '第六十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第八章 法律责任', NULL, '违反本法规定，职业中介机构提供虚假就业信息，为无合法证照的用人单位提供职业中介服务，伪造、涂改、转让职业中介许可证的，由劳动行政部门或者其他主管部门责令改正；有违法所得的，没收违法所得，并处一万元以上五万元以下的罚款；情节严重的，吊销职业中介许可证。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202065, '《中华人民共和国就业促进法》', '第六十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第八章 法律责任', NULL, '违反本法规定，职业中介机构扣押劳动者居民身份证等证件的，由劳动行政部门责令限期退还劳动者，并依照有关法律规定给予处罚。 违反本法规定，职业中介机构向劳动者收取押金的，由劳动行政部门责令限期退还劳动者，并以每人五百元以上二千元以下的标准处以罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202066, '《中华人民共和国就业促进法》', '第六十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第八章 法律责任', NULL, '违反本法规定，企业未按照国家规定提取职工教育经费，或者挪用职工教育经费的，由劳动行政部门责令改正，并依法给予处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202067, '《中华人民共和国就业促进法》', '第六十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第八章 法律责任', NULL, '违反本法规定，侵害劳动者合法权益，造成财产损失或者其他损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (202068, '《中华人民共和国就业促进法》', '第六十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2015-04-24', '第九章 附 则', NULL, '本法自2008年1月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203000, '《中华人民共和国安全生产法》', '第一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第一章 总 则', NULL, '为了加强安全生产工作，防止和减少生产安全事故，保障人民群众生命和财产安全，促进经济社会持续健康发展，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203001, '《中华人民共和国安全生产法》', '第二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第一章 总 则', NULL, '在中华人民共和国领域内从事生产经营活动的单位（以下统称生产经营单位）的安全生产，适用本法；有关法律、行政法规对消防安全和道路交通安全、铁路交通安全、水上交通安全、民用航空安全以及核与辐射安全、特种设备安全另有规定的，适用其规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203002, '《中华人民共和国安全生产法》', '第三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第一章 总 则', NULL, '安全生产工作坚持中国共产党的领导。 安全生产工作应当以人为本，坚持人民至上、生命至上，把保护人民生命安全摆在首位，树牢安全发展理念，坚持安全第一、预防为主、综合治理的方针，从源头上防范化解重大安全风险。 安全生产工作实行管行业必须管安全、管业务必须管安全、管生产经营必须管安全，强化和落实生产经营单位主体责任与政府监管责任，建立生产经营单位负责、职工参与、政府监管、行业自律和社会监督的机制。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203003, '《中华人民共和国安全生产法》', '第四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第一章 总 则', NULL, '生产经营单位必须遵守本法和其他有关安全生产的法律、法规，加强安全生产管理，建立健全全员安全生产责任制和安全生产规章制度，加大对安全生产资金、物资、技术、人员的投入保障力度，改善安全生产条件，加强安全生产标准化、信息化建设，构建安全风险分级管控和隐患排查治理双重预防机制，健全风险防范化解机制，提高安全生产水平，确保安全生产。 平台经济等新兴行业、领域的生产经营单位应当根据本行业、领域的特点，建立健全并落实全员安全生产责任制，加强从业人员安全生产教育和培训，履行本法和其他法律、法规规定的有关安全生产义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203004, '《中华人民共和国安全生产法》', '第五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第一章 总 则', NULL, '生产经营单位的主要负责人是本单位安全生产第一责任人，对本单位的安全生产工作全面负责。其他负责人对职责范围内的安全生产工作负责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203005, '《中华人民共和国安全生产法》', '第六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第一章 总 则', NULL, '生产经营单位的从业人员有依法获得安全生产保障的权利，并应当依法履行安全生产方面的义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203006, '《中华人民共和国安全生产法》', '第七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第一章 总 则', NULL, '工会依法对安全生产工作进行监督。 生产经营单位的工会依法组织职工参加本单位安全生产工作的民主管理和民主监督，维护职工在安全生产方面的合法权益。生产经营单位制定或者修改有关安全生产的规章制度，应当听取工会的意见。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203007, '《中华人民共和国安全生产法》', '第八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第一章 总 则', NULL, '国务院和县级以上地方各级人民政府应当根据国民经济和社会发展规划制定安全生产规划，并组织实施。安全生产规划应当与国土空间规划等相关规划相衔接。 各级人民政府应当加强安全生产基础设施建设和安全生产监管能力建设，所需经费列入本级预算。 县级以上地方各级人民政府应当组织有关部门建立完善安全风险评估与论证机制，按照安全风险管控要求，进行产业规划和空间布局，并对位置相邻、行业相近、业态相似的生产经营单位实施重大安全风险联防联控。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203008, '《中华人民共和国安全生产法》', '第九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第一章 总 则', NULL, '国务院和县级以上地方各级人民政府应当加强对安全生产工作的领导，建立健全安全生产工作协调机制，支持、督促各有关部门依法履行安全生产监督管理职责，及时协调、解决安全生产监督管理中存在的重大问题。 乡镇人民政府和街道办事处，以及开发区、工业园区、港区、风景区等应当明确负责安全生产监督管理的有关工作机构及其职责，加强安全生产监管力量建设，按照职责对本行政区域或者管理区域内生产经营单位安全生产状况进行监督检查，协助人民政府有关部门或者按照授权依法履行安全生产监督管理职责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203009, '《中华人民共和国安全生产法》', '第十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第一章 总 则', NULL, '国务院应急管理部门依照本法，对全国安全生产工作实施综合监督管理；县级以上地方各级人民政府应急管理部门依照本法，对本行政区域内安全生产工作实施综合监督管理。 国务院交通运输、住房和城乡建设、水利、民航等有关部门依照本法和其他有关法律、行政法规的规定，在各自的职责范围内对有关行业、领域的安全生产工作实施监督管理；县级以上地方各级人民政府有关部门依照本法和其他有关法律、法规的规定，在各自的职责范围内对有关行业、领域的安全生产工作实施监督管理。对新兴行业、领域的安全生产监督管理职责不明确的，由县级以上地方各级人民政府按照业务相近的原则确定监督管理部门。 应急管理部门和对有关行业、领域的安全生产工作实施监督管理的部门，统称负有安全生产监督管理职责的部门。负有安全生产监督管理职责的部门应当相互配合、齐抓共管、信息共享、资源共用，依法加强安全生产监督管理工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203010, '《中华人民共和国安全生产法》', '第十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第一章 总 则', NULL, '国务院有关部门应当按照保障安全生产的要求，依法及时制定有关的国家标准或者行业标准，并根据科技进步和经济发展适时修订。 生产经营单位必须执行依法制定的保障安全生产的国家标准或者行业标准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203011, '《中华人民共和国安全生产法》', '第十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第一章 总 则', NULL, '国务院有关部门按照职责分工负责安全生产强制性国家标准的项目提出、组织起草、征求意见、技术审查。国务院应急管理部门统筹提出安全生产强制性国家标准的立项计划。国务院标准化行政主管部门负责安全生产强制性国家标准的立项、编号、对外通报和授权批准发布工作。国务院标准化行政主管部门、有关部门依据法定职责对安全生产强制性国家标准的实施进行监督检查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203012, '《中华人民共和国安全生产法》', '第十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第一章 总 则', NULL, '各级人民政府及其有关部门应当采取多种形式，加强对有关安全生产的法律、法规和安全生产知识的宣传，增强全社会的安全生产意识。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203013, '《中华人民共和国安全生产法》', '第十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第一章 总 则', NULL, '有关协会组织依照法律、行政法规和章程，为生产经营单位提供安全生产方面的信息、培训等服务，发挥自律作用，促进生产经营单位加强安全生产管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203014, '《中华人民共和国安全生产法》', '第十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第一章 总 则', NULL, '依法设立的为安全生产提供技术、管理服务的机构，依照法律、行政法规和执业准则，接受生产经营单位的委托为其安全生产工作提供技术、管理服务。 生产经营单位委托前款规定的机构提供安全生产技术、管理服务的，保证安全生产的责任仍由本单位负责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203015, '《中华人民共和国安全生产法》', '第十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第一章 总 则', NULL, '国家实行生产安全事故责任追究制度，依照本法和有关法律、法规的规定，追究生产安全事故责任单位和责任人员的法律责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203016, '《中华人民共和国安全生产法》', '第十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第一章 总 则', NULL, '县级以上各级人民政府应当组织负有安全生产监督管理职责的部门依法编制安全生产权力和责任清单，公开并接受社会监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203017, '《中华人民共和国安全生产法》', '第十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第一章 总 则', NULL, '国家鼓励和支持安全生产科学技术研究和安全生产先进技术的推广应用，提高安全生产水平。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203018, '《中华人民共和国安全生产法》', '第十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第一章 总 则', NULL, '国家对在改善安全生产条件、防止生产安全事故、参加抢险救护等方面取得显著成绩的单位和个人，给予奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203019, '《中华人民共和国安全生产法》', '第二十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位应当具备本法和有关法律、行政法规和国家标准或者行业标准规定的安全生产条件；不具备安全生产条件的，不得从事生产经营活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203020, '《中华人民共和国安全生产法》', '第二十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位的主要负责人对本单位安全生产工作负有下列职责： （一）建立健全并落实本单位全员安全生产责任制，加强安全生产标准化建设； （二）组织制定并实施本单位安全生产规章制度和操作规程； （三）组织制定并实施本单位安全生产教育和培训计划； （四）保证本单位安全生产投入的有效实施； （五）组织建立并落实安全风险分级管控和隐患排查治理双重预防工作机制，督促、检查本单位的安全生产工作，及时消除生产安全事故隐患； （六）组织制定并实施本单位的生产安全事故应急救援预案； （七）及时、如实报告生产安全事故。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203021, '《中华人民共和国安全生产法》', '第二十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位的全员安全生产责任制应当明确各岗位的责任人员、责任范围和考核标准等内容。 生产经营单位应当建立相应的机制，加强对全员安全生产责任制落实情况的监督考核，保证全员安全生产责任制的落实。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203022, '《中华人民共和国安全生产法》', '第二十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位应当具备的安全生产条件所必需的资金投入，由生产经营单位的决策机构、主要负责人或者个人经营的投资人予以保证，并对由于安全生产所必需的资金投入不足导致的后果承担责任。 有关生产经营单位应当按照规定提取和使用安全生产费用，专门用于改善安全生产条件。安全生产费用在成本中据实列支。安全生产费用提取、使用和监督管理的具体办法由国务院财政部门会同国务院应急管理部门征求国务院有关部门意见后制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203023, '《中华人民共和国安全生产法》', '第二十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '矿山、金属冶炼、建筑施工、运输单位和危险物品的生产、经营、储存、装卸单位，应当设置安全生产管理机构或者配备专职安全生产管理人员。 前款规定以外的其他生产经营单位，从业人员超过一百人的，应当设置安全生产管理机构或者配备专职安全生产管理人员；从业人员在一百人以下的，应当配备专职或者兼职的安全生产管理人员。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203024, '《中华人民共和国安全生产法》', '第二十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位的安全生产管理机构以及安全生产管理人员履行下列职责： （一）组织或者参与拟订本单位安全生产规章制度、操作规程和生产安全事故应急救援预案； （二）组织或者参与本单位安全生产教育和培训，如实记录安全生产教育和培训情况； （三）组织开展危险源辨识和评估，督促落实本单位重大危险源的安全管理措施； （四）组织或者参与本单位应急救援演练； （五）检查本单位的安全生产状况，及时排查生产安全事故隐患，提出改进安全生产管理的建议； （六）制止和纠正违章指挥、强令冒险作业、违反操作规程的行为； （七）督促落实本单位安全生产整改措施。 生产经营单位可以设置专职安全生产分管负责人，协助本单位主要负责人履行安全生产管理职责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203025, '《中华人民共和国安全生产法》', '第二十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位的安全生产管理机构以及安全生产管理人员应当恪尽职守，依法履行职责。 生产经营单位作出涉及安全生产的经营决策，应当听取安全生产管理机构以及安全生产管理人员的意见。 生产经营单位不得因安全生产管理人员依法履行职责而降低其工资、福利等待遇或者解除与其订立的劳动合同。 危险物品的生产、储存单位以及矿山、金属冶炼单位的安全生产管理人员的任免，应当告知主管的负有安全生产监督管理职责的部门。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203026, '《中华人民共和国安全生产法》', '第二十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位的主要负责人和安全生产管理人员必须具备与本单位所从事的生产经营活动相应的安全生产知识和管理能力。 危险物品的生产、经营、储存、装卸单位以及矿山、金属冶炼、建筑施工、运输单位的主要负责人和安全生产管理人员，应当由主管的负有安全生产监督管理职责的部门对其安全生产知识和管理能力考核合格。考核不得收费。 危险物品的生产、储存、装卸单位以及矿山、金属冶炼单位应当有注册安全工程师从事安全生产管理工作。鼓励其他生产经营单位聘用注册安全工程师从事安全生产管理工作。注册安全工程师按专业分类管理，具体办法由国务院人力资源和社会保障部门、国务院应急管理部门会同国务院有关部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203027, '《中华人民共和国安全生产法》', '第二十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位应当对从业人员进行安全生产教育和培训，保证从业人员具备必要的安全生产知识，熟悉有关的安全生产规章制度和安全操作规程，掌握本岗位的安全操作技能，了解事故应急处理措施，知悉自身在安全生产方面的权利和义务。未经安全生产教育和培训合格的从业人员，不得上岗作业。 生产经营单位使用被派遣劳动者的，应当将被派遣劳动者纳入本单位从业人员统一管理，对被派遣劳动者进行岗位安全操作规程和安全操作技能的教育和培训。劳务派遣单位应当对被派遣劳动者进行必要的安全生产教育和培训。 生产经营单位接收中等职业学校、高等学校学生实习的，应当对实习学生进行相应的安全生产教育和培训，提供必要的劳动防护用品。学校应当协助生产经营单位对实习学生进行安全生产教育和培训。 生产经营单位应当建立安全生产教育和培训档案，如实记录安全生产教育和培训的时间、内容、参加人员以及考核结果等情况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203028, '《中华人民共和国安全生产法》', '第二十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位采用新工艺、新技术、新材料或者使用新设备，必须了解、掌握其安全技术特性，采取有效的安全防护措施，并对从业人员进行专门的安全生产教育和培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203029, '《中华人民共和国安全生产法》', '第三十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位的特种作业人员必须按照国家有关规定经专门的安全作业培训，取得相应资格，方可上岗作业。 特种作业人员的范围由国务院应急管理部门会同国务院有关部门确定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203030, '《中华人民共和国安全生产法》', '第三十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位新建、改建、扩建工程项目（以下统称建设项目）的安全设施，必须与主体工程同时设计、同时施工、同时投入生产和使用。安全设施投资应当纳入建设项目概算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203031, '《中华人民共和国安全生产法》', '第三十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '矿山、金属冶炼建设项目和用于生产、储存、装卸危险物品的建设项目，应当按照国家有关规定进行安全评价。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203032, '《中华人民共和国安全生产法》', '第三十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '建设项目安全设施的设计人、设计单位应当对安全设施设计负责。 矿山、金属冶炼建设项目和用于生产、储存、装卸危险物品的建设项目的安全设施设计应当按照国家有关规定报经有关部门审查，审查部门及其负责审查的人员对审查结果负责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203033, '《中华人民共和国安全生产法》', '第三十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '矿山、金属冶炼建设项目和用于生产、储存、装卸危险物品的建设项目的施工单位必须按照批准的安全设施设计施工，并对安全设施的工程质量负责。 矿山、金属冶炼建设项目和用于生产、储存、装卸危险物品的建设项目竣工投入生产或者使用前，应当由建设单位负责组织对安全设施进行验收；验收合格后，方可投入生产和使用。负有安全生产监督管理职责的部门应当加强对建设单位验收活动和验收结果的监督核查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203034, '《中华人民共和国安全生产法》', '第三十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位应当在有较大危险因素的生产经营场所和有关设施、设备上，设置明显的安全警示标志。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203035, '《中华人民共和国安全生产法》', '第三十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '安全设备的设计、制造、安装、使用、检测、维修、改造和报废，应当符合国家标准或者行业标准。 生产经营单位必须对安全设备进行经常性维护、保养，并定期检测，保证正常运转。维护、保养、检测应当作好记录，并由有关人员签字。 生产经营单位不得关闭、破坏直接关系生产安全的监控、报警、防护、救生设备、设施，或者篡改、隐瞒、销毁其相关数据、信息。 餐饮等行业的生产经营单位使用燃气的，应当安装可燃气体报警装置，并保障其正常使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203036, '《中华人民共和国安全生产法》', '第三十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位使用的危险物品的容器、运输工具，以及涉及人身安全、危险性较大的海洋石油开采特种设备和矿山井下特种设备，必须按照国家有关规定，由专业生产单位生产，并经具有专业资质的检测、检验机构检测、检验合格，取得安全使用证或者安全标志，方可投入使用。检测、检验机构对检测、检验结果负责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203037, '《中华人民共和国安全生产法》', '第三十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '国家对严重危及生产安全的工艺、设备实行淘汰制度，具体目录由国务院应急管理部门会同国务院有关部门制定并公布。法律、行政法规对目录的制定另有规定的，适用其规定。 省、自治区、直辖市人民政府可以根据本地区实际情况制定并公布具体目录，对前款规定以外的危及生产安全的工艺、设备予以淘汰。 生产经营单位不得使用应当淘汰的危及生产安全的工艺、设备。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203038, '《中华人民共和国安全生产法》', '第三十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产、经营、运输、储存、使用危险物品或者处置废弃危险物品的，由有关主管部门依照有关法律、法规的规定和国家标准或者行业标准审批并实施监督管理。 生产经营单位生产、经营、运输、储存、使用危险物品或者处置废弃危险物品，必须执行有关法律、法规和国家标准或者行业标准，建立专门的安全管理制度，采取可靠的安全措施，接受有关主管部门依法实施的监督管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203039, '《中华人民共和国安全生产法》', '第四十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位对重大危险源应当登记建档，进行定期检测、评估、监控，并制定应急预案，告知从业人员和相关人员在紧急情况下应当采取的应急措施。 生产经营单位应当按照国家有关规定将本单位重大危险源及有关安全措施、应急措施报有关地方人民政府应急管理部门和有关部门备案。有关地方人民政府应急管理部门和有关部门应当通过相关信息系统实现信息共享。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203040, '《中华人民共和国安全生产法》', '第四十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位应当建立安全风险分级管控制度，按照安全风险分级采取相应的管控措施。 生产经营单位应当建立健全并落实生产安全事故隐患排查治理制度，采取技术、管理措施，及时发现并消除事故隐患。事故隐患排查治理情况应当如实记录，并通过职工大会或者职工代表大会、信息公示栏等方式向从业人员通报。其中，重大事故隐患排查治理情况应当及时向负有安全生产监督管理职责的部门和职工大会或者职工代表大会报告。 县级以上地方各级人民政府负有安全生产监督管理职责的部门应当将重大事故隐患纳入相关信息系统，建立健全重大事故隐患治理督办制度，督促生产经营单位消除重大事故隐患。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203041, '《中华人民共和国安全生产法》', '第四十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产、经营、储存、使用危险物品的车间、商店、仓库不得与员工宿舍在同一座建筑物内，并应当与员工宿舍保持安全距离。 生产经营场所和员工宿舍应当设有符合紧急疏散要求、标志明显、保持畅通的出口、疏散通道。禁止占用、锁闭、封堵生产经营场所或者员工宿舍的出口、疏散通道。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203042, '《中华人民共和国安全生产法》', '第四十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位进行爆破、吊装、动火、临时用电以及国务院应急管理部门会同国务院有关部门规定的其他危险作业，应当安排专门人员进行现场安全管理，确保操作规程的遵守和安全措施的落实。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203043, '《中华人民共和国安全生产法》', '第四十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位应当教育和督促从业人员严格执行本单位的安全生产规章制度和安全操作规程；并向从业人员如实告知作业场所和工作岗位存在的危险因素、防范措施以及事故应急措施。 生产经营单位应当关注从业人员的身体、心理状况和行为习惯，加强对从业人员的心理疏导、精神慰藉，严格落实岗位安全生产责任，防范从业人员行为异常导致事故发生。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203044, '《中华人民共和国安全生产法》', '第四十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位必须为从业人员提供符合国家标准或者行业标准的劳动防护用品，并监督、教育从业人员按照使用规则佩戴、使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203045, '《中华人民共和国安全生产法》', '第四十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位的安全生产管理人员应当根据本单位的生产经营特点，对安全生产状况进行经常性检查；对检查中发现的安全问题，应当立即处理；不能处理的，应当及时报告本单位有关负责人，有关负责人应当及时处理。检查及处理情况应当如实记录在案。 生产经营单位的安全生产管理人员在检查中发现重大事故隐患，依照前款规定向本单位有关负责人报告，有关负责人不及时处理的，安全生产管理人员可以向主管的负有安全生产监督管理职责的部门报告，接到报告的部门应当依法及时处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203046, '《中华人民共和国安全生产法》', '第四十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位应当安排用于配备劳动防护用品、进行安全生产培训的经费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203047, '《中华人民共和国安全生产法》', '第四十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '两个以上生产经营单位在同一作业区域内进行生产经营活动，可能危及对方生产安全的，应当签订安全生产管理协议，明确各自的安全生产管理职责和应当采取的安全措施，并指定专职安全生产管理人员进行安全检查与协调。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203048, '《中华人民共和国安全生产法》', '第四十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位不得将生产经营项目、场所、设备发包或者出租给不具备安全生产条件或者相应资质的单位或者个人。 生产经营项目、场所发包或者出租给其他单位的，生产经营单位应当与承包单位、承租单位签订专门的安全生产管理协议，或者在承包合同、租赁合同中约定各自的安全生产管理职责；生产经营单位对承包单位、承租单位的安全生产工作统一协调、管理，定期进行安全检查，发现安全问题的，应当及时督促整改。 矿山、金属冶炼建设项目和用于生产、储存、装卸危险物品的建设项目的施工单位应当加强对施工项目的安全管理，不得倒卖、出租、出借、挂靠或者以其他形式非法转让施工资质，不得将其承包的全部建设工程转包给第三人或者将其承包的全部建设工程支解以后以分包的名义分别转包给第三人，不得将工程分包给不具备相应资质条件的单位。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203049, '《中华人民共和国安全生产法》', '第五十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位发生生产安全事故时，单位的主要负责人应当立即组织抢救，并不得在事故调查处理期间擅离职守。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203050, '《中华人民共和国安全生产法》', '第五十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第二章 生产经营单位的安全生产保障', NULL, '生产经营单位必须依法参加工伤保险，为从业人员缴纳保险费。 国家鼓励生产经营单位投保安全生产责任保险；属于国家规定的高危行业、领域的生产经营单位，应当投保安全生产责任保险。具体范围和实施办法由国务院应急管理部门会同国务院财政部门、国务院保险监督管理机构和相关行业主管部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203051, '《中华人民共和国安全生产法》', '第五十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第三章 从业人员的安全生产权利义务', NULL, '生产经营单位与从业人员订立的劳动合同，应当载明有关保障从业人员劳动安全、防止职业危害的事项，以及依法为从业人员办理工伤保险的事项。 生产经营单位不得以任何形式与从业人员订立协议，免除或者减轻其对从业人员因生产安全事故伤亡依法应承担的责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203052, '《中华人民共和国安全生产法》', '第五十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第三章 从业人员的安全生产权利义务', NULL, '生产经营单位的从业人员有权了解其作业场所和工作岗位存在的危险因素、防范措施及事故应急措施，有权对本单位的安全生产工作提出建议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203053, '《中华人民共和国安全生产法》', '第五十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第三章 从业人员的安全生产权利义务', NULL, '从业人员有权对本单位安全生产工作中存在的问题提出批评、检举、控告；有权拒绝违章指挥和强令冒险作业。 生产经营单位不得因从业人员对本单位安全生产工作提出批评、检举、控告或者拒绝违章指挥、强令冒险作业而降低其工资、福利等待遇或者解除与其订立的劳动合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203054, '《中华人民共和国安全生产法》', '第五十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第三章 从业人员的安全生产权利义务', NULL, '从业人员发现直接危及人身安全的紧急情况时，有权停止作业或者在采取可能的应急措施后撤离作业场所。 生产经营单位不得因从业人员在前款紧急情况下停止作业或者采取紧急撤离措施而降低其工资、福利等待遇或者解除与其订立的劳动合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203055, '《中华人民共和国安全生产法》', '第五十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第三章 从业人员的安全生产权利义务', NULL, '生产经营单位发生生产安全事故后，应当及时采取措施救治有关人员。 因生产安全事故受到损害的从业人员，除依法享有工伤保险外，依照有关民事法律尚有获得赔偿的权利的，有权提出赔偿要求。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203056, '《中华人民共和国安全生产法》', '第五十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第三章 从业人员的安全生产权利义务', NULL, '从业人员在作业过程中，应当严格落实岗位安全责任，遵守本单位的安全生产规章制度和操作规程，服从管理，正确佩戴和使用劳动防护用品。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203057, '《中华人民共和国安全生产法》', '第五十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第三章 从业人员的安全生产权利义务', NULL, '从业人员应当接受安全生产教育和培训，掌握本职工作所需的安全生产知识，提高安全生产技能，增强事故预防和应急处理能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203058, '《中华人民共和国安全生产法》', '第五十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第三章 从业人员的安全生产权利义务', NULL, '从业人员发现事故隐患或者其他不安全因素，应当立即向现场安全生产管理人员或者本单位负责人报告；接到报告的人员应当及时予以处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203059, '《中华人民共和国安全生产法》', '第六十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第三章 从业人员的安全生产权利义务', NULL, '工会有权对建设项目的安全设施与主体工程同时设计、同时施工、同时投入生产和使用进行监督，提出意见。 工会对生产经营单位违反安全生产法律、法规，侵犯从业人员合法权益的行为，有权要求纠正；发现生产经营单位违章指挥、强令冒险作业或者发现事故隐患时，有权提出解决的建议，生产经营单位应当及时研究答复；发现危及从业人员生命安全的情况时，有权向生产经营单位建议组织从业人员撤离危险场所，生产经营单位必须立即作出处理。 工会有权依法参加事故调查，向有关部门提出处理意见，并要求追究有关人员的责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203060, '《中华人民共和国安全生产法》', '第六十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第三章 从业人员的安全生产权利义务', NULL, '生产经营单位使用被派遣劳动者的，被派遣劳动者享有本法规定的从业人员的权利，并应当履行本法规定的从业人员的义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203061, '《中华人民共和国安全生产法》', '第六十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第四章 安全生产的监督管理', NULL, '县级以上地方各级人民政府应当根据本行政区域内的安全生产状况，组织有关部门按照职责分工，对本行政区域内容易发生重大生产安全事故的生产经营单位进行严格检查。 应急管理部门应当按照分类分级监督管理的要求，制定安全生产年度监督检查计划，并按照年度监督检查计划进行监督检查，发现事故隐患，应当及时处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203062, '《中华人民共和国安全生产法》', '第六十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第四章 安全生产的监督管理', NULL, '负有安全生产监督管理职责的部门依照有关法律、法规的规定，对涉及安全生产的事项需要审查批准（包括批准、核准、许可、注册、认证、颁发证照等，下同）或者验收的，必须严格依照有关法律、法规和国家标准或者行业标准规定的安全生产条件和程序进行审查；不符合有关法律、法规和国家标准或者行业标准规定的安全生产条件的，不得批准或者验收通过。对未依法取得批准或者验收合格的单位擅自从事有关活动的，负责行政审批的部门发现或者接到举报后应当立即予以取缔，并依法予以处理。对已经依法取得批准的单位，负责行政审批的部门发现其不再具备安全生产条件的，应当撤销原批准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203063, '《中华人民共和国安全生产法》', '第六十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第四章 安全生产的监督管理', NULL, '负有安全生产监督管理职责的部门对涉及安全生产的事项进行审查、验收，不得收取费用；不得要求接受审查、验收的单位购买其指定品牌或者指定生产、销售单位的安全设备、器材或者其他产品。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203064, '《中华人民共和国安全生产法》', '第六十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第四章 安全生产的监督管理', NULL, '应急管理部门和其他负有安全生产监督管理职责的部门依法开展安全生产行政执法工作，对生产经营单位执行有关安全生产的法律、法规和国家标准或者行业标准的情况进行监督检查，行使以下职权： （一）进入生产经营单位进行检查，调阅有关资料，向有关单位和人员了解情况； （二）对检查中发现的安全生产违法行为，当场予以纠正或者要求限期改正；对依法应当给予行政处罚的行为，依照本法和其他有关法律、行政法规的规定作出行政处罚决定； （三）对检查中发现的事故隐患，应当责令立即排除；重大事故隐患排除前或者排除过程中无法保证安全的，应当责令从危险区域内撤出作业人员，责令暂时停产停业或者停止使用相关设施、设备；重大事故隐患排除后，经审查同意，方可恢复生产经营和使用； （四）对有根据认为不符合保障安全生产的国家标准或者行业标准的设施、设备、器材以及违法生产、储存、使用、经营、运输的危险物品予以查封或者扣押，对违法生产、储存、使用、经营危险物品的作业场所予以查封，并依法作出处理决定。 监督检查不得影响被检查单位的正常生产经营活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203065, '《中华人民共和国安全生产法》', '第六十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第四章 安全生产的监督管理', NULL, '生产经营单位对负有安全生产监督管理职责的部门的监督检查人员（以下统称安全生产监督检查人员）依法履行监督检查职责，应当予以配合，不得拒绝、阻挠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203066, '《中华人民共和国安全生产法》', '第六十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第四章 安全生产的监督管理', NULL, '安全生产监督检查人员应当忠于职守，坚持原则，秉公执法。 安全生产监督检查人员执行监督检查任务时，必须出示有效的行政执法证件；对涉及被检查单位的技术秘密和业务秘密，应当为其保密。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203067, '《中华人民共和国安全生产法》', '第六十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第四章 安全生产的监督管理', NULL, '安全生产监督检查人员应当将检查的时间、地点、内容、发现的问题及其处理情况，作出书面记录，并由检查人员和被检查单位的负责人签字；被检查单位的负责人拒绝签字的，检查人员应当将情况记录在案，并向负有安全生产监督管理职责的部门报告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203068, '《中华人民共和国安全生产法》', '第六十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第四章 安全生产的监督管理', NULL, '负有安全生产监督管理职责的部门在监督检查中，应当互相配合，实行联合检查；确需分别进行检查的，应当互通情况，发现存在的安全问题应当由其他有关部门进行处理的，应当及时移送其他有关部门并形成记录备查，接受移送的部门应当及时进行处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203069, '《中华人民共和国安全生产法》', '第七十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第四章 安全生产的监督管理', NULL, '负有安全生产监督管理职责的部门依法对存在重大事故隐患的生产经营单位作出停产停业、停止施工、停止使用相关设施或者设备的决定，生产经营单位应当依法执行，及时消除事故隐患。生产经营单位拒不执行，有发生生产安全事故的现实危险的，在保证安全的前提下，经本部门主要负责人批准，负有安全生产监督管理职责的部门可以采取通知有关单位停止供电、停止供应民用爆炸物品等措施，强制生产经营单位履行决定。通知应当采用书面形式，有关单位应当予以配合。 负有安全生产监督管理职责的部门依照前款规定采取停止供电措施，除有危及生产安全的紧急情形外，应当提前二十四小时通知生产经营单位。生产经营单位依法履行行政决定、采取相应措施消除事故隐患的，负有安全生产监督管理职责的部门应当及时解除前款规定的措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203070, '《中华人民共和国安全生产法》', '第七十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第四章 安全生产的监督管理', NULL, '监察机关依照监察法的规定，对负有安全生产监督管理职责的部门及其工作人员履行安全生产监督管理职责实施监察。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203071, '《中华人民共和国安全生产法》', '第七十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第四章 安全生产的监督管理', NULL, '承担安全评价、认证、检测、检验职责的机构应当具备国家规定的资质条件，并对其作出的安全评价、认证、检测、检验结果的合法性、真实性负责。资质条件由国务院应急管理部门会同国务院有关部门制定。 承担安全评价、认证、检测、检验职责的机构应当建立并实施服务公开和报告公开制度，不得租借资质、挂靠、出具虚假报告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203072, '《中华人民共和国安全生产法》', '第七十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第四章 安全生产的监督管理', NULL, '负有安全生产监督管理职责的部门应当建立举报制度，公开举报电话、信箱或者电子邮件地址等网络举报平台，受理有关安全生产的举报；受理的举报事项经调查核实后，应当形成书面材料；需要落实整改措施的，报经有关负责人签字并督促落实。对不属于本部门职责，需要由其他有关部门进行调查处理的，转交其他有关部门处理。 涉及人员死亡的举报事项，应当由县级以上人民政府组织核查处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203073, '《中华人民共和国安全生产法》', '第七十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第四章 安全生产的监督管理', NULL, '任何单位或者个人对事故隐患或者安全生产违法行为，均有权向负有安全生产监督管理职责的部门报告或者举报。 因安全生产违法行为造成重大事故隐患或者导致重大事故，致使国家利益或者社会公共利益受到侵害的，人民检察院可以根据民事诉讼法、行政诉讼法的相关规定提起公益诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203074, '《中华人民共和国安全生产法》', '第七十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第四章 安全生产的监督管理', NULL, '居民委员会、村民委员会发现其所在区域内的生产经营单位存在事故隐患或者安全生产违法行为时，应当向当地人民政府或者有关部门报告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203075, '《中华人民共和国安全生产法》', '第七十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第四章 安全生产的监督管理', NULL, '县级以上各级人民政府及其有关部门对报告重大事故隐患或者举报安全生产违法行为的有功人员，给予奖励。具体奖励办法由国务院应急管理部门会同国务院财政部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203076, '《中华人民共和国安全生产法》', '第七十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第四章 安全生产的监督管理', NULL, '新闻、出版、广播、电影、电视等单位有进行安全生产公益宣传教育的义务，有对违反安全生产法律、法规的行为进行舆论监督的权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203077, '《中华人民共和国安全生产法》', '第七十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第四章 安全生产的监督管理', NULL, '负有安全生产监督管理职责的部门应当建立安全生产违法行为信息库，如实记录生产经营单位及其有关从业人员的安全生产违法行为信息；对违法行为情节严重的生产经营单位及其有关从业人员，应当及时向社会公告，并通报行业主管部门、投资主管部门、自然资源主管部门、生态环境主管部门、证券监督管理机构以及有关金融机构。有关部门和机构应当对存在失信行为的生产经营单位及其有关从业人员采取加大执法检查频次、暂停项目审批、上调有关保险费率、行业或者职业禁入等联合惩戒措施，并向社会公示。 负有安全生产监督管理职责的部门应当加强对生产经营单位行政处罚信息的及时归集、共享、应用和公开，对生产经营单位作出处罚决定后七个工作日内在监督管理部门公示系统予以公开曝光，强化对违法失信生产经营单位及其有关从业人员的社会监督，提高全社会安全生产诚信水平。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203078, '《中华人民共和国安全生产法》', '第七十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第五章 生产安全事故的应急救援与调查处理', NULL, '国家加强生产安全事故应急能力建设，在重点行业、领域建立应急救援基地和应急救援队伍，并由国家安全生产应急救援机构统一协调指挥；鼓励生产经营单位和其他社会力量建立应急救援队伍，配备相应的应急救援装备和物资，提高应急救援的专业化水平。 国务院应急管理部门牵头建立全国统一的生产安全事故应急救援信息系统，国务院交通运输、住房和城乡建设、水利、民航等有关部门和县级以上地方人民政府建立健全相关行业、领域、地区的生产安全事故应急救援信息系统，实现互联互通、信息共享，通过推行网上安全信息采集、安全监管和监测预警，提升监管的精准化、智能化水平。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203079, '《中华人民共和国安全生产法》', '第八十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第五章 生产安全事故的应急救援与调查处理', NULL, '县级以上地方各级人民政府应当组织有关部门制定本行政区域内生产安全事故应急救援预案，建立应急救援体系。 乡镇人民政府和街道办事处，以及开发区、工业园区、港区、风景区等应当制定相应的生产安全事故应急救援预案，协助人民政府有关部门或者按照授权依法履行生产安全事故应急救援工作职责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203080, '《中华人民共和国安全生产法》', '第八十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第五章 生产安全事故的应急救援与调查处理', NULL, '生产经营单位应当制定本单位生产安全事故应急救援预案，与所在地县级以上地方人民政府组织制定的生产安全事故应急救援预案相衔接，并定期组织演练。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203081, '《中华人民共和国安全生产法》', '第八十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第五章 生产安全事故的应急救援与调查处理', NULL, '危险物品的生产、经营、储存单位以及矿山、金属冶炼、城市轨道交通运营、建筑施工单位应当建立应急救援组织；生产经营规模较小的，可以不建立应急救援组织，但应当指定兼职的应急救援人员。 危险物品的生产、经营、储存、运输单位以及矿山、金属冶炼、城市轨道交通运营、建筑施工单位应当配备必要的应急救援器材、设备和物资，并进行经常性维护、保养，保证正常运转。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203082, '《中华人民共和国安全生产法》', '第八十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第五章 生产安全事故的应急救援与调查处理', NULL, '生产经营单位发生生产安全事故后，事故现场有关人员应当立即报告本单位负责人。 单位负责人接到事故报告后，应当迅速采取有效措施，组织抢救，防止事故扩大，减少人员伤亡和财产损失，并按照国家有关规定立即如实报告当地负有安全生产监督管理职责的部门，不得隐瞒不报、谎报或者迟报，不得故意破坏事故现场、毁灭有关证据。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203083, '《中华人民共和国安全生产法》', '第八十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第五章 生产安全事故的应急救援与调查处理', NULL, '负有安全生产监督管理职责的部门接到事故报告后，应当立即按照国家有关规定上报事故情况。负有安全生产监督管理职责的部门和有关地方人民政府对事故情况不得隐瞒不报、谎报或者迟报。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203084, '《中华人民共和国安全生产法》', '第八十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第五章 生产安全事故的应急救援与调查处理', NULL, '有关地方人民政府和负有安全生产监督管理职责的部门的负责人接到生产安全事故报告后，应当按照生产安全事故应急救援预案的要求立即赶到事故现场，组织事故抢救。 参与事故抢救的部门和单位应当服从统一指挥，加强协同联动，采取有效的应急救援措施，并根据事故救援的需要采取警戒、疏散等措施，防止事故扩大和次生灾害的发生，减少人员伤亡和财产损失。 事故抢救过程中应当采取必要措施，避免或者减少对环境造成的危害。 任何单位和个人都应当支持、配合事故抢救，并提供一切便利条件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203085, '《中华人民共和国安全生产法》', '第八十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第五章 生产安全事故的应急救援与调查处理', NULL, '事故调查处理应当按照科学严谨、依法依规、实事求是、注重实效的原则，及时、准确地查清事故原因，查明事故性质和责任，评估应急处置工作，总结事故教训，提出整改措施，并对事故责任单位和人员提出处理建议。事故调查报告应当依法及时向社会公布。事故调查和处理的具体办法由国务院制定。 事故发生单位应当及时全面落实整改措施，负有安全生产监督管理职责的部门应当加强监督检查。 负责事故调查处理的国务院有关部门和地方人民政府应当在批复事故调查报告后一年内，组织有关部门对事故整改和防范措施落实情况进行评估，并及时向社会公开评估结果；对不履行职责导致事故整改和防范措施没有落实的有关单位和人员，应当按照有关规定追究责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203086, '《中华人民共和国安全生产法》', '第八十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第五章 生产安全事故的应急救援与调查处理', NULL, '生产经营单位发生生产安全事故，经调查确定为责任事故的，除了应当查明事故单位的责任并依法予以追究外，还应当查明对安全生产的有关事项负有审查批准和监督职责的行政部门的责任，对有失职、渎职行为的，依照本法第九十条的规定追究法律责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203087, '《中华人民共和国安全生产法》', '第八十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第五章 生产安全事故的应急救援与调查处理', NULL, '任何单位和个人不得阻挠和干涉对事故的依法调查处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203088, '《中华人民共和国安全生产法》', '第八十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第五章 生产安全事故的应急救援与调查处理', NULL, '县级以上地方各级人民政府应急管理部门应当定期统计分析本行政区域内发生生产安全事故的情况，并定期向社会公布。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203089, '《中华人民共和国安全生产法》', '第九十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '负有安全生产监督管理职责的部门的工作人员，有下列行为之一的，给予降级或者撤职的处分；构成犯罪的，依照刑法有关规定追究刑事责任： （一）对不符合法定安全生产条件的涉及安全生产的事项予以批准或者验收通过的； （二）发现未依法取得批准、验收的单位擅自从事有关活动或者接到举报后不予取缔或者不依法予以处理的； （三）对已经依法取得批准的单位不履行监督管理职责，发现其不再具备安全生产条件而不撤销原批准或者发现安全生产违法行为不予查处的； （四）在监督检查中发现重大事故隐患，不依法及时处理的。 负有安全生产监督管理职责的部门的工作人员有前款规定以外的滥用职权、玩忽职守、徇私舞弊行为的，依法给予处分；构成犯罪的，依照刑法有关规定追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203090, '《中华人民共和国安全生产法》', '第九十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '负有安全生产监督管理职责的部门，要求被审查、验收的单位购买其指定的安全设备、器材或者其他产品的，在对安全生产事项的审查、验收中收取费用的，由其上级机关或者监察机关责令改正，责令退还收取的费用；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203091, '《中华人民共和国安全生产法》', '第九十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '承担安全评价、认证、检测、检验职责的机构出具失实报告的，责令停业整顿，并处三万元以上十万元以下的罚款；给他人造成损害的，依法承担赔偿责任。 承担安全评价、认证、检测、检验职责的机构租借资质、挂靠、出具虚假报告的，没收违法所得；违法所得在十万元以上的，并处违法所得二倍以上五倍以下的罚款，没有违法所得或者违法所得不足十万元的，单处或者并处十万元以上二十万元以下的罚款；对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；给他人造成损害的，与生产经营单位承担连带赔偿责任；构成犯罪的，依照刑法有关规定追究刑事责任。 对有前款违法行为的机构及其直接责任人员，吊销其相应资质和资格，五年内不得从事安全评价、认证、检测、检验等工作；情节严重的，实行终身行业和职业禁入。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203092, '《中华人民共和国安全生产法》', '第九十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '生产经营单位的决策机构、主要负责人或者个人经营的投资人不依照本法规定保证安全生产所必需的资金投入，致使生产经营单位不具备安全生产条件的，责令限期改正，提供必需的资金；逾期未改正的，责令生产经营单位停产停业整顿。 有前款违法行为，导致发生生产安全事故的，对生产经营单位的主要负责人给予撤职处分，对个人经营的投资人处二万元以上二十万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203093, '《中华人民共和国安全生产法》', '第九十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '生产经营单位的主要负责人未履行本法规定的安全生产管理职责的，责令限期改正，处二万元以上五万元以下的罚款；逾期未改正的，处五万元以上十万元以下的罚款，责令生产经营单位停产停业整顿。 生产经营单位的主要负责人有前款违法行为，导致发生生产安全事故的，给予撤职处分；构成犯罪的，依照刑法有关规定追究刑事责任。 生产经营单位的主要负责人依照前款规定受刑事处罚或者撤职处分的，自刑罚执行完毕或者受处分之日起，五年内不得担任任何生产经营单位的主要负责人；对重大、特别重大生产安全事故负有责任的，终身不得担任本行业生产经营单位的主要负责人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203094, '《中华人民共和国安全生产法》', '第九十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '生产经营单位的主要负责人未履行本法规定的安全生产管理职责，导致发生生产安全事故的，由应急管理部门依照下列规定处以罚款： （一）发生一般事故的，处上一年年收入百分之四十的罚款； （二）发生较大事故的，处上一年年收入百分之六十的罚款； （三）发生重大事故的，处上一年年收入百分之八十的罚款； （四）发生特别重大事故的，处上一年年收入百分之一百的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203095, '《中华人民共和国安全生产法》', '第九十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '生产经营单位的其他负责人和安全生产管理人员未履行本法规定的安全生产管理职责的，责令限期改正，处一万元以上三万元以下的罚款；导致发生生产安全事故的，暂停或者吊销其与安全生产有关的资格，并处上一年年收入百分之二十以上百分之五十以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203096, '《中华人民共和国安全生产法》', '第九十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '生产经营单位有下列行为之一的，责令限期改正，处十万元以下的罚款；逾期未改正的，责令停产停业整顿，并处十万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款： （一）未按照规定设置安全生产管理机构或者配备安全生产管理人员、注册安全工程师的； （二）危险物品的生产、经营、储存、装卸单位以及矿山、金属冶炼、建筑施工、运输单位的主要负责人和安全生产管理人员未按照规定经考核合格的； （三）未按照规定对从业人员、被派遣劳动者、实习学生进行安全生产教育和培训，或者未按照规定如实告知有关的安全生产事项的； （四）未如实记录安全生产教育和培训情况的； （五）未将事故隐患排查治理情况如实记录或者未向从业人员通报的； （六）未按照规定制定生产安全事故应急救援预案或者未定期组织演练的； （七）特种作业人员未按照规定经专门的安全作业培训并取得相应资格，上岗作业的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203097, '《中华人民共和国安全生产法》', '第九十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '生产经营单位有下列行为之一的，责令停止建设或者停产停业整顿，限期改正，并处十万元以上五十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款；逾期未改正的，处五十万元以上一百万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任： （一）未按照规定对矿山、金属冶炼建设项目或者用于生产、储存、装卸危险物品的建设项目进行安全评价的； （二）矿山、金属冶炼建设项目或者用于生产、储存、装卸危险物品的建设项目没有安全设施设计或者安全设施设计未按照规定报经有关部门审查同意的； （三）矿山、金属冶炼建设项目或者用于生产、储存、装卸危险物品的建设项目的施工单位未按照批准的安全设施设计施工的； （四）矿山、金属冶炼建设项目或者用于生产、储存、装卸危险物品的建设项目竣工投入生产或者使用前，安全设施未经验收合格的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203098, '《中华人民共和国安全生产法》', '第九十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '生产经营单位有下列行为之一的，责令限期改正，处五万元以下的罚款；逾期未改正的，处五万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处一万元以上二万元以下的罚款；情节严重的，责令停产停业整顿；构成犯罪的，依照刑法有关规定追究刑事责任： （一）未在有较大危险因素的生产经营场所和有关设施、设备上设置明显的安全警示标志的； （二）安全设备的安装、使用、检测、改造和报废不符合国家标准或者行业标准的； （三）未对安全设备进行经常性维护、保养和定期检测的； （四）关闭、破坏直接关系生产安全的监控、报警、防护、救生设备、设施，或者篡改、隐瞒、销毁其相关数据、信息的； （五）未为从业人员提供符合国家标准或者行业标准的劳动防护用品的； （六）危险物品的容器、运输工具，以及涉及人身安全、危险性较大的海洋石油开采特种设备和矿山井下特种设备未经具有专业资质的机构检测、检验合格，取得安全使用证或者安全标志，投入使用的； （七）使用应当淘汰的危及生产安全的工艺、设备的； （八）餐饮等行业的生产经营单位使用燃气未安装可燃气体报警装置的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203099, '《中华人民共和国安全生产法》', '第一百条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '未经依法批准，擅自生产、经营、运输、储存、使用危险物品或者处置废弃危险物品的，依照有关危险物品安全管理的法律、行政法规的规定予以处罚；构成犯罪的，依照刑法有关规定追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203100, '《中华人民共和国安全生产法》', '第一百零一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '生产经营单位有下列行为之一的，责令限期改正，处十万元以下的罚款；逾期未改正的，责令停产停业整顿，并处十万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任： （一）生产、经营、运输、储存、使用危险物品或者处置废弃危险物品，未建立专门安全管理制度、未采取可靠的安全措施的； （二）对重大危险源未登记建档，未进行定期检测、评估、监控，未制定应急预案，或者未告知应急措施的； （三）进行爆破、吊装、动火、临时用电以及国务院应急管理部门会同国务院有关部门规定的其他危险作业，未安排专门人员进行现场安全管理的； （四）未建立安全风险分级管控制度或者未按照安全风险分级采取相应管控措施的； （五）未建立事故隐患排查治理制度，或者重大事故隐患排查治理情况未按照规定报告的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203101, '《中华人民共和国安全生产法》', '第一百零二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '生产经营单位未采取措施消除事故隐患的，责令立即消除或者限期消除，处五万元以下的罚款；生产经营单位拒不执行的，责令停产停业整顿，对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203102, '《中华人民共和国安全生产法》', '第一百零三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '生产经营单位将生产经营项目、场所、设备发包或者出租给不具备安全生产条件或者相应资质的单位或者个人的，责令限期改正，没收违法所得；违法所得十万元以上的，并处违法所得二倍以上五倍以下的罚款；没有违法所得或者违法所得不足十万元的，单处或者并处十万元以上二十万元以下的罚款；对其直接负责的主管人员和其他直接责任人员处一万元以上二万元以下的罚款；导致发生生产安全事故给他人造成损害的，与承包方、承租方承担连带赔偿责任。 生产经营单位未与承包单位、承租单位签订专门的安全生产管理协议或者未在承包合同、租赁合同中明确各自的安全生产管理职责，或者未对承包单位、承租单位的安全生产统一协调、管理的，责令限期改正，处五万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处一万元以下的罚款；逾期未改正的，责令停产停业整顿。 矿山、金属冶炼建设项目和用于生产、储存、装卸危险物品的建设项目的施工单位未按照规定对施工项目进行安全管理的，责令限期改正，处十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以下的罚款；逾期未改正的，责令停产停业整顿。以上施工单位倒卖、出租、出借、挂靠或者以其他形式非法转让施工资质的，责令停产停业整顿，吊销资质证书，没收违法所得；违法所得十万元以上的，并处违法所得二倍以上五倍以下的罚款，没有违法所得或者违法所得不足十万元的，单处或者并处十万元以上二十万元以下的罚款；对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203103, '《中华人民共和国安全生产法》', '第一百零四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '两个以上生产经营单位在同一作业区域内进行可能危及对方安全生产的生产经营活动，未签订安全生产管理协议或者未指定专职安全生产管理人员进行安全检查与协调的，责令限期改正，处五万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处一万元以下的罚款；逾期未改正的，责令停产停业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203104, '《中华人民共和国安全生产法》', '第一百零五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '生产经营单位有下列行为之一的，责令限期改正，处五万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处一万元以下的罚款；逾期未改正的，责令停产停业整顿；构成犯罪的，依照刑法有关规定追究刑事责任： （一）生产、经营、储存、使用危险物品的车间、商店、仓库与员工宿舍在同一座建筑内，或者与员工宿舍的距离不符合安全要求的； （二）生产经营场所和员工宿舍未设有符合紧急疏散需要、标志明显、保持畅通的出口、疏散通道，或者占用、锁闭、封堵生产经营场所或者员工宿舍出口、疏散通道的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203105, '《中华人民共和国安全生产法》', '第一百零六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '生产经营单位与从业人员订立协议，免除或者减轻其对从业人员因生产安全事故伤亡依法应承担的责任的，该协议无效；对生产经营单位的主要负责人、个人经营的投资人处二万元以上十万元以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203106, '《中华人民共和国安全生产法》', '第一百零七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '生产经营单位的从业人员不落实岗位安全责任，不服从管理，违反安全生产规章制度或者操作规程的，由生产经营单位给予批评教育，依照有关规章制度给予处分；构成犯罪的，依照刑法有关规定追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203107, '《中华人民共和国安全生产法》', '第一百零八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '违反本法规定，生产经营单位拒绝、阻碍负有安全生产监督管理职责的部门依法实施监督检查的，责令改正；拒不改正的，处二万元以上二十万元以下的罚款；对其直接负责的主管人员和其他直接责任人员处一万元以上二万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203108, '《中华人民共和国安全生产法》', '第一百零九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '高危行业、领域的生产经营单位未按照国家规定投保安全生产责任保险的，责令限期改正，处五万元以上十万元以下的罚款；逾期未改正的，处十万元以上二十万元以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203109, '《中华人民共和国安全生产法》', '第一百一十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '生产经营单位的主要负责人在本单位发生生产安全事故时，不立即组织抢救或者在事故调查处理期间擅离职守或者逃匿的，给予降级、撤职的处分，并由应急管理部门处上一年年收入百分之六十至百分之一百的罚款；对逃匿的处十五日以下拘留；构成犯罪的，依照刑法有关规定追究刑事责任。 生产经营单位的主要负责人对生产安全事故隐瞒不报、谎报或者迟报的，依照前款规定处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203110, '《中华人民共和国安全生产法》', '第一百一十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '有关地方人民政府、负有安全生产监督管理职责的部门，对生产安全事故隐瞒不报、谎报或者迟报的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依照刑法有关规定追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203111, '《中华人民共和国安全生产法》', '第一百一十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '生产经营单位违反本法规定，被责令改正且受到罚款处罚，拒不改正的，负有安全生产监督管理职责的部门可以自作出责令改正之日的次日起，按照原处罚数额按日连续处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203112, '《中华人民共和国安全生产法》', '第一百一十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '生产经营单位存在下列情形之一的，负有安全生产监督管理职责的部门应当提请地方人民政府予以关闭，有关部门应当依法吊销其有关证照。生产经营单位主要负责人五年内不得担任任何生产经营单位的主要负责人；情节严重的，终身不得担任本行业生产经营单位的主要负责人： （一）存在重大事故隐患，一百八十日内三次或者一年内四次受到本法规定的行政处罚的； （二）经停产停业整顿，仍不具备法律、行政法规和国家标准或者行业标准规定的安全生产条件的； （三）不具备法律、行政法规和国家标准或者行业标准规定的安全生产条件，导致发生重大、特别重大生产安全事故的； （四）拒不执行负有安全生产监督管理职责的部门作出的停产停业整顿决定的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203113, '《中华人民共和国安全生产法》', '第一百一十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '发生生产安全事故，对负有责任的生产经营单位除要求其依法承担相应的赔偿等责任外，由应急管理部门依照下列规定处以罚款： （一）发生一般事故的，处三十万元以上一百万元以下的罚款； （二）发生较大事故的，处一百万元以上二百万元以下的罚款； （三）发生重大事故的，处二百万元以上一千万元以下的罚款； （四）发生特别重大事故的，处一千万元以上二千万元以下的罚款。 发生生产安全事故，情节特别严重、影响特别恶劣的，应急管理部门可以按照前款罚款数额的二倍以上五倍以下对负有责任的生产经营单位处以罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203114, '《中华人民共和国安全生产法》', '第一百一十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '本法规定的行政处罚，由应急管理部门和其他负有安全生产监督管理职责的部门按照职责分工决定；其中，根据本法第九十五条、第一百一十条、第一百一十四条的规定应当给予民航、铁路、电力行业的生产经营单位及其主要负责人行政处罚的，也可以由主管的负有安全生产监督管理职责的部门进行处罚。予以关闭的行政处罚，由负有安全生产监督管理职责的部门报请县级以上人民政府按照国务院规定的权限决定；给予拘留的行政处罚，由公安机关依照治安管理处罚的规定决定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203115, '《中华人民共和国安全生产法》', '第一百一十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第六章 法律责任', NULL, '生产经营单位发生生产安全事故造成人员伤亡、他人财产损失的，应当依法承担赔偿责任；拒不承担或者其负责人逃匿的，由人民法院依法强制执行。 生产安全事故的责任人未依法承担赔偿责任，经人民法院依法采取执行措施后，仍不能对受害人给予足额赔偿的，应当继续履行赔偿义务；受害人发现责任人有其他财产的，可以随时请求人民法院执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203116, '《中华人民共和国安全生产法》', '第一百一十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第七章 附 则', NULL, '本法下列用语的含义： 危险物品，是指易燃易爆物品、危险化学品、放射性物品等能够危及人身安全和财产安全的物品。 重大危险源，是指长期地或者临时地生产、搬运、使用或者储存危险物品，且危险物品的数量等于或者超过临界量的单元（包括场所和设施）。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203117, '《中华人民共和国安全生产法》', '第一百一十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第七章 附 则', NULL, '本法规定的生产安全一般事故、较大事故、重大事故、特别重大事故的划分标准由国务院规定。 国务院应急管理部门和其他负有安全生产监督管理职责的部门应当根据各自的职责分工，制定相关行业、领域重大危险源的辨识标准和重大事故隐患的判定标准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (203118, '《中华人民共和国安全生产法》', '第一百一十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2021-06-10', '第七章 附 则', NULL, '本法自2002年11月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204000, '《中华人民共和国职业病防治法》', '第一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '为了预防、控制和消除职业病危害，防治职业病，保护劳动者健康及其相关权益，促进经济社会发展，根据宪法，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204001, '《中华人民共和国职业病防治法》', '第二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '本法适用于中华人民共和国领域内的职业病防治活动。 本法所称职业病，是指企业、事业单位和个体经济组织等用人单位的劳动者在职业活动中，因接触粉尘、放射性物质和其他有毒、有害因素而引起的疾病。 职业病的分类和目录由国务院卫生行政部门会同国务院劳动保障行政部门制定、调整并公布。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204002, '《中华人民共和国职业病防治法》', '第三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '职业病防治工作坚持预防为主、防治结合的方针，建立用人单位负责、行政机关监管、行业自律、职工参与和社会监督的机制，实行分类管理、综合治理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204003, '《中华人民共和国职业病防治法》', '第四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '劳动者依法享有职业卫生保护的权利。 用人单位应当为劳动者创造符合国家职业卫生标准和卫生要求的工作环境和条件，并采取措施保障劳动者获得职业卫生保护。 工会组织依法对职业病防治工作进行监督，维护劳动者的合法权益。用人单位制定或者修改有关职业病防治的规章制度，应当听取工会组织的意见。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204004, '《中华人民共和国职业病防治法》', '第五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '用人单位应当建立、健全职业病防治责任制，加强对职业病防治的管理，提高职业病防治水平，对本单位产生的职业病危害承担责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204005, '《中华人民共和国职业病防治法》', '第六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '用人单位的主要负责人对本单位的职业病防治工作全面负责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204006, '《中华人民共和国职业病防治法》', '第七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '用人单位必须依法参加工伤保险。 国务院和县级以上地方人民政府劳动保障行政部门应当加强对工伤保险的监督管理，确保劳动者依法享受工伤保险待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204007, '《中华人民共和国职业病防治法》', '第八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '国家鼓励和支持研制、开发、推广、应用有利于职业病防治和保护劳动者健康的新技术、新工艺、新设备、新材料，加强对职业病的机理和发生规律的基础研究，提高职业病防治科学技术水平；积极采用有效的职业病防治技术、工艺、设备、材料；限制使用或者淘汰职业病危害严重的技术、工艺、设备、材料。 国家鼓励和支持职业病医疗康复机构的建设。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204008, '《中华人民共和国职业病防治法》', '第九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '国家实行职业卫生监督制度。 国务院卫生行政部门、劳动保障行政部门依照本法和国务院确定的职责，负责全国职业病防治的监督管理工作。国务院有关部门在各自的职责范围内负责职业病防治的有关监督管理工作。 县级以上地方人民政府卫生行政部门、劳动保障行政部门依据各自职责，负责本行政区域内职业病防治的监督管理工作。县级以上地方人民政府有关部门在各自的职责范围内负责职业病防治的有关监督管理工作。 县级以上人民政府卫生行政部门、劳动保障行政部门（以下统称职业卫生监督管理部门）应当加强沟通，密切配合，按照各自职责分工，依法行使职权，承担责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204009, '《中华人民共和国职业病防治法》', '第十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '国务院和县级以上地方人民政府应当制定职业病防治规划，将其纳入国民经济和社会发展计划，并组织实施。 县级以上地方人民政府统一负责、领导、组织、协调本行政区域的职业病防治工作，建立健全职业病防治工作体制、机制，统一领导、指挥职业卫生突发事件应对工作；加强职业病防治能力建设和服务体系建设，完善、落实职业病防治工作责任制。 乡、民族乡、镇的人民政府应当认真执行本法，支持职业卫生监督管理部门依法履行职责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204010, '《中华人民共和国职业病防治法》', '第十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '县级以上人民政府职业卫生监督管理部门应当加强对职业病防治的宣传教育，普及职业病防治的知识，增强用人单位的职业病防治观念，提高劳动者的职业健康意识、自我保护意识和行使职业卫生保护权利的能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204011, '《中华人民共和国职业病防治法》', '第十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '有关防治职业病的国家职业卫生标准，由国务院卫生行政部门组织制定并公布。 国务院卫生行政部门应当组织开展重点职业病监测和专项调查，对职业健康风险进行评估，为制定职业卫生标准和职业病防治政策提供科学依据。 县级以上地方人民政府卫生行政部门应当定期对本行政区域的职业病防治情况进行统计和调查分析。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204012, '《中华人民共和国职业病防治法》', '第十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '任何单位和个人有权对违反本法的行为进行检举和控告。有关部门收到相关的检举和控告后，应当及时处理。 对防治职业病成绩显著的单位和个人，给予奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204013, '《中华人民共和国职业病防治法》', '第十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 前期预防', NULL, '用人单位应当依照法律、法规要求，严格遵守国家职业卫生标准，落实职业病预防措施，从源头上控制和消除职业病危害。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204014, '《中华人民共和国职业病防治法》', '第十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 前期预防', NULL, '产生职业病危害的用人单位的设立除应当符合法律、行政法规规定的设立条件外，其工作场所还应当符合下列职业卫生要求： （一）职业病危害因素的强度或者浓度符合国家职业卫生标准； （二）有与职业病危害防护相适应的设施； （三）生产布局合理，符合有害与无害作业分开的原则； （四）有配套的更衣间、洗浴间、孕妇休息间等卫生设施； （五）设备、工具、用具等设施符合保护劳动者生理、心理健康的要求； （六）法律、行政法规和国务院卫生行政部门关于保护劳动者健康的其他要求。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204015, '《中华人民共和国职业病防治法》', '第十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 前期预防', NULL, '国家建立职业病危害项目申报制度。 用人单位工作场所存在职业病目录所列职业病的危害因素的，应当及时、如实向所在地卫生行政部门申报危害项目，接受监督。 职业病危害因素分类目录由国务院卫生行政部门制定、调整并公布。职业病危害项目申报的具体办法由国务院卫生行政部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204016, '《中华人民共和国职业病防治法》', '第十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 前期预防', NULL, '新建、扩建、改建建设项目和技术改造、技术引进项目（以下统称建设项目）可能产生职业病危害的，建设单位在可行性论证阶段应当进行职业病危害预评价。 医疗机构建设项目可能产生放射性职业病危害的，建设单位应当向卫生行政部门提交放射性职业病危害预评价报告。卫生行政部门应当自收到预评价报告之日起三十日内，作出审核决定并书面通知建设单位。未提交预评价报告或者预评价报告未经卫生行政部门审核同意的，不得开工建设。 职业病危害预评价报告应当对建设项目可能产生的职业病危害因素及其对工作场所和劳动者健康的影响作出评价，确定危害类别和职业病防护措施。 建设项目职业病危害分类管理办法由国务院卫生行政部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204017, '《中华人民共和国职业病防治法》', '第十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 前期预防', NULL, '建设项目的职业病防护设施所需费用应当纳入建设项目工程预算，并与主体工程同时设计，同时施工，同时投入生产和使用。 建设项目的职业病防护设施设计应当符合国家职业卫生标准和卫生要求；其中，医疗机构放射性职业病危害严重的建设项目的防护设施设计，应当经卫生行政部门审查同意后，方可施工。 建设项目在竣工验收前，建设单位应当进行职业病危害控制效果评价。 医疗机构可能产生放射性职业病危害的建设项目竣工验收时，其放射性职业病防护设施经卫生行政部门验收合格后，方可投入使用；其他建设项目的职业病防护设施应当由建设单位负责依法组织验收，验收合格后，方可投入生产和使用。卫生行政部门应当加强对建设单位组织的验收活动和验收结果的监督核查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204018, '《中华人民共和国职业病防治法》', '第十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 前期预防', NULL, '国家对从事放射性、高毒、高危粉尘等作业实行特殊管理。具体管理办法由国务院制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204019, '《中华人民共和国职业病防治法》', '第二十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位应当采取下列职业病防治管理措施： （一）设置或者指定职业卫生管理机构或者组织，配备专职或者兼职的职业卫生管理人员，负责本单位的职业病防治工作； （二）制定职业病防治计划和实施方案； （三）建立、健全职业卫生管理制度和操作规程； （四）建立、健全职业卫生档案和劳动者健康监护档案； （五）建立、健全工作场所职业病危害因素监测及评价制度； （六）建立、健全职业病危害事故应急救援预案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204020, '《中华人民共和国职业病防治法》', '第二十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位应当保障职业病防治所需的资金投入，不得挤占、挪用，并对因资金投入不足导致的后果承担责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204021, '《中华人民共和国职业病防治法》', '第二十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位必须采用有效的职业病防护设施，并为劳动者提供个人使用的职业病防护用品。 用人单位为劳动者个人提供的职业病防护用品必须符合防治职业病的要求；不符合要求的，不得使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204022, '《中华人民共和国职业病防治法》', '第二十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位应当优先采用有利于防治职业病和保护劳动者健康的新技术、新工艺、新设备、新材料，逐步替代职业病危害严重的技术、工艺、设备、材料。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204023, '《中华人民共和国职业病防治法》', '第二十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '产生职业病危害的用人单位，应当在醒目位置设置公告栏，公布有关职业病防治的规章制度、操作规程、职业病危害事故应急救援措施和工作场所职业病危害因素检测结果。 对产生严重职业病危害的作业岗位，应当在其醒目位置，设置警示标识和中文警示说明。警示说明应当载明产生职业病危害的种类、后果、预防以及应急救治措施等内容。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204024, '《中华人民共和国职业病防治法》', '第二十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '对可能发生急性职业损伤的有毒、有害工作场所，用人单位应当设置报警装置，配置现场急救用品、冲洗设备、应急撤离通道和必要的泄险区。 对放射工作场所和放射性同位素的运输、贮存，用人单位必须配置防护设备和报警装置，保证接触放射线的工作人员佩戴个人剂量计。 对职业病防护设备、应急救援设施和个人使用的职业病防护用品，用人单位应当进行经常性的维护、检修，定期检测其性能和效果，确保其处于正常状态，不得擅自拆除或者停止使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204025, '《中华人民共和国职业病防治法》', '第二十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位应当实施由专人负责的职业病危害因素日常监测，并确保监测系统处于正常运行状态。 用人单位应当按照国务院卫生行政部门的规定，定期对工作场所进行职业病危害因素检测、评价。检测、评价结果存入用人单位职业卫生档案，定期向所在地卫生行政部门报告并向劳动者公布。 职业病危害因素检测、评价由依法设立的取得国务院卫生行政部门或者设区的市级以上地方人民政府卫生行政部门按照职责分工给予资质认可的职业卫生技术服务机构进行。职业卫生技术服务机构所作检测、评价应当客观、真实。 发现工作场所职业病危害因素不符合国家职业卫生标准和卫生要求时，用人单位应当立即采取相应治理措施，仍然达不到国家职业卫生标准和卫生要求的，必须停止存在职业病危害因素的作业；职业病危害因素经治理后，符合国家职业卫生标准和卫生要求的，方可重新作业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204026, '《中华人民共和国职业病防治法》', '第二十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '职业卫生技术服务机构依法从事职业病危害因素检测、评价工作，接受卫生行政部门的监督检查。卫生行政部门应当依法履行监督职责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204027, '《中华人民共和国职业病防治法》', '第二十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '向用人单位提供可能产生职业病危害的设备的，应当提供中文说明书，并在设备的醒目位置设置警示标识和中文警示说明。警示说明应当载明设备性能、可能产生的职业病危害、安全操作和维护注意事项、职业病防护以及应急救治措施等内容。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204028, '《中华人民共和国职业病防治法》', '第二十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '向用人单位提供可能产生职业病危害的化学品、放射性同位素和含有放射性物质的材料的，应当提供中文说明书。说明书应当载明产品特性、主要成份、存在的有害因素、可能产生的危害后果、安全使用注意事项、职业病防护以及应急救治措施等内容。产品包装应当有醒目的警示标识和中文警示说明。贮存上述材料的场所应当在规定的部位设置危险物品标识或者放射性警示标识。 国内首次使用或者首次进口与职业病危害有关的化学材料，使用单位或者进口单位按照国家规定经国务院有关部门批准后，应当向国务院卫生行政部门报送该化学材料的毒性鉴定以及经有关部门登记注册或者批准进口的文件等资料。 进口放射性同位素、射线装置和含有放射性物质的物品的，按照国家有关规定办理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204029, '《中华人民共和国职业病防治法》', '第三十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '任何单位和个人不得生产、经营、进口和使用国家明令禁止使用的可能产生职业病危害的设备或者材料。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204030, '《中华人民共和国职业病防治法》', '第三十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '任何单位和个人不得将产生职业病危害的作业转移给不具备职业病防护条件的单位和个人。不具备职业病防护条件的单位和个人不得接受产生职业病危害的作业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204031, '《中华人民共和国职业病防治法》', '第三十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位对采用的技术、工艺、设备、材料，应当知悉其产生的职业病危害，对有职业病危害的技术、工艺、设备、材料隐瞒其危害而采用的，对所造成的职业病危害后果承担责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204032, '《中华人民共和国职业病防治法》', '第三十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位与劳动者订立劳动合同（含聘用合同，下同）时，应当将工作过程中可能产生的职业病危害及其后果、职业病防护措施和待遇等如实告知劳动者，并在劳动合同中写明，不得隐瞒或者欺骗。 劳动者在已订立劳动合同期间因工作岗位或者工作内容变更，从事与所订立劳动合同中未告知的存在职业病危害的作业时，用人单位应当依照前款规定，向劳动者履行如实告知的义务，并协商变更原劳动合同相关条款。 用人单位违反前两款规定的，劳动者有权拒绝从事存在职业病危害的作业，用人单位不得因此解除与劳动者所订立的劳动合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204033, '《中华人民共和国职业病防治法》', '第三十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位的主要负责人和职业卫生管理人员应当接受职业卫生培训，遵守职业病防治法律、法规，依法组织本单位的职业病防治工作。 用人单位应当对劳动者进行上岗前的职业卫生培训和在岗期间的定期职业卫生培训，普及职业卫生知识，督促劳动者遵守职业病防治法律、法规、规章和操作规程，指导劳动者正确使用职业病防护设备和个人使用的职业病防护用品。 劳动者应当学习和掌握相关的职业卫生知识，增强职业病防范意识，遵守职业病防治法律、法规、规章和操作规程，正确使用、维护职业病防护设备和个人使用的职业病防护用品，发现职业病危害事故隐患应当及时报告。 劳动者不履行前款规定义务的，用人单位应当对其进行教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204034, '《中华人民共和国职业病防治法》', '第三十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '对从事接触职业病危害的作业的劳动者，用人单位应当按照国务院卫生行政部门的规定组织上岗前、在岗期间和离岗时的职业健康检查，并将检查结果书面告知劳动者。职业健康检查费用由用人单位承担。 用人单位不得安排未经上岗前职业健康检查的劳动者从事接触职业病危害的作业；不得安排有职业禁忌的劳动者从事其所禁忌的作业；对在职业健康检查中发现有与所从事的职业相关的健康损害的劳动者，应当调离原工作岗位，并妥善安置；对未进行离岗前职业健康检查的劳动者不得解除或者终止与其订立的劳动合同。 职业健康检查应当由取得《医疗机构执业许可证》的医疗卫生机构承担。卫生行政部门应当加强对职业健康检查工作的规范管理，具体管理办法由国务院卫生行政部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204035, '《中华人民共和国职业病防治法》', '第三十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位应当为劳动者建立职业健康监护档案，并按照规定的期限妥善保存。 职业健康监护档案应当包括劳动者的职业史、职业病危害接触史、职业健康检查结果和职业病诊疗等有关个人健康资料。 劳动者离开用人单位时，有权索取本人职业健康监护档案复印件，用人单位应当如实、无偿提供，并在所提供的复印件上签章。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204036, '《中华人民共和国职业病防治法》', '第三十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '发生或者可能发生急性职业病危害事故时，用人单位应当立即采取应急救援和控制措施，并及时报告所在地卫生行政部门和有关部门。卫生行政部门接到报告后，应当及时会同有关部门组织调查处理；必要时，可以采取临时控制措施。卫生行政部门应当组织做好医疗救治工作。 对遭受或者可能遭受急性职业病危害的劳动者，用人单位应当及时组织救治、进行健康检查和医学观察，所需费用由用人单位承担。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204037, '《中华人民共和国职业病防治法》', '第三十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位不得安排未成年工从事接触职业病危害的作业；不得安排孕期、哺乳期的女职工从事对本人和胎儿、婴儿有危害的作业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204038, '《中华人民共和国职业病防治法》', '第三十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '劳动者享有下列职业卫生保护权利： （一）获得职业卫生教育、培训； （二）获得职业健康检查、职业病诊疗、康复等职业病防治服务； （三）了解工作场所产生或者可能产生的职业病危害因素、危害后果和应当采取的职业病防护措施； （四）要求用人单位提供符合防治职业病要求的职业病防护设施和个人使用的职业病防护用品，改善工作条件； （五）对违反职业病防治法律、法规以及危及生命健康的行为提出批评、检举和控告； （六）拒绝违章指挥和强令进行没有职业病防护措施的作业； （七）参与用人单位职业卫生工作的民主管理，对职业病防治工作提出意见和建议。 用人单位应当保障劳动者行使前款所列权利。因劳动者依法行使正当权利而降低其工资、福利等待遇或者解除、终止与其订立的劳动合同的，其行为无效。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204039, '《中华人民共和国职业病防治法》', '第四十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '工会组织应当督促并协助用人单位开展职业卫生宣传教育和培训，有权对用人单位的职业病防治工作提出意见和建议，依法代表劳动者与用人单位签订劳动安全卫生专项集体合同，与用人单位就劳动者反映的有关职业病防治的问题进行协调并督促解决。 工会组织对用人单位违反职业病防治法律、法规，侵犯劳动者合法权益的行为，有权要求纠正；产生严重职业病危害时，有权要求采取防护措施，或者向政府有关部门建议采取强制性措施；发生职业病危害事故时，有权参与事故调查处理；发现危及劳动者生命健康的情形时，有权向用人单位建议组织劳动者撤离危险现场，用人单位应当立即作出处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204040, '《中华人民共和国职业病防治法》', '第四十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '用人单位按照职业病防治要求，用于预防和治理职业病危害、工作场所卫生检测、健康监护和职业卫生培训等费用，按照国家有关规定，在生产成本中据实列支。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204041, '《中华人民共和国职业病防治法》', '第四十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 劳动过程中的防护与管理', NULL, '职业卫生监督管理部门应当按照职责分工，加强对用人单位落实职业病防护管理措施情况的监督检查，依法行使职权，承担责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204042, '《中华人民共和国职业病防治法》', '第四十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '职业病诊断应当由取得《医疗机构执业许可证》的医疗卫生机构承担。卫生行政部门应当加强对职业病诊断工作的规范管理，具体管理办法由国务院卫生行政部门制定。 承担职业病诊断的医疗卫生机构还应当具备下列条件： （一）具有与开展职业病诊断相适应的医疗卫生技术人员； （二）具有与开展职业病诊断相适应的仪器、设备； （三）具有健全的职业病诊断质量管理制度。 承担职业病诊断的医疗卫生机构不得拒绝劳动者进行职业病诊断的要求。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204043, '《中华人民共和国职业病防治法》', '第四十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '劳动者可以在用人单位所在地、本人户籍所在地或者经常居住地依法承担职业病诊断的医疗卫生机构进行职业病诊断。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204044, '《中华人民共和国职业病防治法》', '第四十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '职业病诊断标准和职业病诊断、鉴定办法由国务院卫生行政部门制定。职业病伤残等级的鉴定办法由国务院劳动保障行政部门会同国务院卫生行政部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204045, '《中华人民共和国职业病防治法》', '第四十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '职业病诊断，应当综合分析下列因素： （一）病人的职业史； （二）职业病危害接触史和工作场所职业病危害因素情况； （三）临床表现以及辅助检查结果等。 没有证据否定职业病危害因素与病人临床表现之间的必然联系的，应当诊断为职业病。 职业病诊断证明书应当由参与诊断的取得职业病诊断资格的执业医师签署，并经承担职业病诊断的医疗卫生机构审核盖章。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204046, '《中华人民共和国职业病防治法》', '第四十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '用人单位应当如实提供职业病诊断、鉴定所需的劳动者职业史和职业病危害接触史、工作场所职业病危害因素检测结果等资料；卫生行政部门应当监督检查和督促用人单位提供上述资料；劳动者和有关机构也应当提供与职业病诊断、鉴定有关的资料。 职业病诊断、鉴定机构需要了解工作场所职业病危害因素情况时，可以对工作场所进行现场调查，也可以向卫生行政部门提出，卫生行政部门应当在十日内组织现场调查。用人单位不得拒绝、阻挠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204047, '《中华人民共和国职业病防治法》', '第四十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '职业病诊断、鉴定过程中，用人单位不提供工作场所职业病危害因素检测结果等资料的，诊断、鉴定机构应当结合劳动者的临床表现、辅助检查结果和劳动者的职业史、职业病危害接触史，并参考劳动者的自述、卫生行政部门提供的日常监督检查信息等，作出职业病诊断、鉴定结论。 劳动者对用人单位提供的工作场所职业病危害因素检测结果等资料有异议，或者因劳动者的用人单位解散、破产，无用人单位提供上述资料的，诊断、鉴定机构应当提请卫生行政部门进行调查，卫生行政部门应当自接到申请之日起三十日内对存在异议的资料或者工作场所职业病危害因素情况作出判定；有关部门应当配合。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204048, '《中华人民共和国职业病防治法》', '第四十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '职业病诊断、鉴定过程中，在确认劳动者职业史、职业病危害接触史时，当事人对劳动关系、工种、工作岗位或者在岗时间有争议的，可以向当地的劳动人事争议仲裁委员会申请仲裁；接到申请的劳动人事争议仲裁委员会应当受理，并在三十日内作出裁决。 当事人在仲裁过程中对自己提出的主张，有责任提供证据。劳动者无法提供由用人单位掌握管理的与仲裁主张有关的证据的，仲裁庭应当要求用人单位在指定期限内提供；用人单位在指定期限内不提供的，应当承担不利后果。 劳动者对仲裁裁决不服的，可以依法向人民法院提起诉讼。 用人单位对仲裁裁决不服的，可以在职业病诊断、鉴定程序结束之日起十五日内依法向人民法院提起诉讼；诉讼期间，劳动者的治疗费用按照职业病待遇规定的途径支付。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204049, '《中华人民共和国职业病防治法》', '第五十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '用人单位和医疗卫生机构发现职业病病人或者疑似职业病病人时，应当及时向所在地卫生行政部门报告。确诊为职业病的，用人单位还应当向所在地劳动保障行政部门报告。接到报告的部门应当依法作出处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204050, '《中华人民共和国职业病防治法》', '第五十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '县级以上地方人民政府卫生行政部门负责本行政区域内的职业病统计报告的管理工作，并按照规定上报。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204051, '《中华人民共和国职业病防治法》', '第五十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '当事人对职业病诊断有异议的，可以向作出诊断的医疗卫生机构所在地地方人民政府卫生行政部门申请鉴定。 职业病诊断争议由设区的市级以上地方人民政府卫生行政部门根据当事人的申请，组织职业病诊断鉴定委员会进行鉴定。 当事人对设区的市级职业病诊断鉴定委员会的鉴定结论不服的，可以向省、自治区、直辖市人民政府卫生行政部门申请再鉴定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204052, '《中华人民共和国职业病防治法》', '第五十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '职业病诊断鉴定委员会由相关专业的专家组成。 省、自治区、直辖市人民政府卫生行政部门应当设立相关的专家库，需要对职业病争议作出诊断鉴定时，由当事人或者当事人委托有关卫生行政部门从专家库中以随机抽取的方式确定参加诊断鉴定委员会的专家。 职业病诊断鉴定委员会应当按照国务院卫生行政部门颁布的职业病诊断标准和职业病诊断、鉴定办法进行职业病诊断鉴定，向当事人出具职业病诊断鉴定书。职业病诊断、鉴定费用由用人单位承担。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204053, '《中华人民共和国职业病防治法》', '第五十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '职业病诊断鉴定委员会组成人员应当遵守职业道德，客观、公正地进行诊断鉴定，并承担相应的责任。职业病诊断鉴定委员会组成人员不得私下接触当事人，不得收受当事人的财物或者其他好处，与当事人有利害关系的，应当回避。 人民法院受理有关案件需要进行职业病鉴定时，应当从省、自治区、直辖市人民政府卫生行政部门依法设立的相关的专家库中选取参加鉴定的专家。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204054, '《中华人民共和国职业病防治法》', '第五十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '医疗卫生机构发现疑似职业病病人时，应当告知劳动者本人并及时通知用人单位。 用人单位应当及时安排对疑似职业病病人进行诊断；在疑似职业病病人诊断或者医学观察期间，不得解除或者终止与其订立的劳动合同。 疑似职业病病人在诊断、医学观察期间的费用，由用人单位承担。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204055, '《中华人民共和国职业病防治法》', '第五十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '用人单位应当保障职业病病人依法享受国家规定的职业病待遇。 用人单位应当按照国家有关规定，安排职业病病人进行治疗、康复和定期检查。 用人单位对不适宜继续从事原工作的职业病病人，应当调离原岗位，并妥善安置。 用人单位对从事接触职业病危害的作业的劳动者，应当给予适当岗位津贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204056, '《中华人民共和国职业病防治法》', '第五十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '职业病病人的诊疗、康复费用，伤残以及丧失劳动能力的职业病病人的社会保障，按照国家有关工伤保险的规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204057, '《中华人民共和国职业病防治法》', '第五十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '职业病病人除依法享有工伤保险外，依照有关民事法律，尚有获得赔偿的权利的，有权向用人单位提出赔偿要求。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204058, '《中华人民共和国职业病防治法》', '第五十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '劳动者被诊断患有职业病，但用人单位没有依法参加工伤保险的，其医疗和生活保障由该用人单位承担。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204059, '《中华人民共和国职业病防治法》', '第六十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '职业病病人变动工作单位，其依法享有的待遇不变。 用人单位在发生分立、合并、解散、破产等情形时，应当对从事接触职业病危害的作业的劳动者进行健康检查，并按照国家有关规定妥善安置职业病病人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204060, '《中华人民共和国职业病防治法》', '第六十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 职业病诊断与职业病病人保障', NULL, '用人单位已经不存在或者无法确认劳动关系的职业病病人，可以向地方人民政府医疗保障、民政部门申请医疗救助和生活等方面的救助。 地方各级人民政府应当根据本地区的实际情况，采取其他措施，使前款规定的职业病病人获得医疗救治。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204061, '《中华人民共和国职业病防治法》', '第六十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 监督检查', NULL, '县级以上人民政府职业卫生监督管理部门依照职业病防治法律、法规、国家职业卫生标准和卫生要求，依据职责划分，对职业病防治工作进行监督检查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204062, '《中华人民共和国职业病防治法》', '第六十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 监督检查', NULL, '卫生行政部门履行监督检查职责时，有权采取下列措施： （一）进入被检查单位和职业病危害现场，了解情况，调查取证； （二）查阅或者复制与违反职业病防治法律、法规的行为有关的资料和采集样品； （三）责令违反职业病防治法律、法规的单位和个人停止违法行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204063, '《中华人民共和国职业病防治法》', '第六十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 监督检查', NULL, '发生职业病危害事故或者有证据证明危害状态可能导致职业病危害事故发生时，卫生行政部门可以采取下列临时控制措施： （一）责令暂停导致职业病危害事故的作业； （二）封存造成职业病危害事故或者可能导致职业病危害事故发生的材料和设备； （三）组织控制职业病危害事故现场。 在职业病危害事故或者危害状态得到有效控制后，卫生行政部门应当及时解除控制措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204064, '《中华人民共和国职业病防治法》', '第六十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 监督检查', NULL, '职业卫生监督执法人员依法执行职务时，应当出示监督执法证件。 职业卫生监督执法人员应当忠于职守，秉公执法，严格遵守执法规范；涉及用人单位的秘密的，应当为其保密。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204065, '《中华人民共和国职业病防治法》', '第六十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 监督检查', NULL, '职业卫生监督执法人员依法执行职务时，被检查单位应当接受检查并予以支持配合，不得拒绝和阻碍。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204066, '《中华人民共和国职业病防治法》', '第六十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 监督检查', NULL, '卫生行政部门及其职业卫生监督执法人员履行职责时，不得有下列行为： （一）对不符合法定条件的，发给建设项目有关证明文件、资质证明文件或者予以批准； （二）对已经取得有关证明文件的，不履行监督检查职责； （三）发现用人单位存在职业病危害的，可能造成职业病危害事故，不及时依法采取控制措施； （四）其他违反本法的行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204067, '《中华人民共和国职业病防治法》', '第六十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 监督检查', NULL, '职业卫生监督执法人员应当依法经过资格认定。 职业卫生监督管理部门应当加强队伍建设，提高职业卫生监督执法人员的政治、业务素质，依照本法和其他有关法律、法规的规定，建立、健全内部监督制度，对其工作人员执行法律、法规和遵守纪律的情况，进行监督检查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204068, '《中华人民共和国职业病防治法》', '第六十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '建设单位违反本法规定，有下列行为之一的，由卫生行政部门给予警告，责令限期改正；逾期不改正的，处十万元以上五十万元以下的罚款；情节严重的，责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令停建、关闭： （一）未按照规定进行职业病危害预评价的； （二）医疗机构可能产生放射性职业病危害的建设项目未按照规定提交放射性职业病危害预评价报告，或者放射性职业病危害预评价报告未经卫生行政部门审核同意，开工建设的； （三）建设项目的职业病防护设施未按照规定与主体工程同时设计、同时施工、同时投入生产和使用的； （四）建设项目的职业病防护设施设计不符合国家职业卫生标准和卫生要求，或者医疗机构放射性职业病危害严重的建设项目的防护设施设计未经卫生行政部门审查同意擅自施工的； （五）未按照规定对职业病防护设施进行职业病危害控制效果评价的； （六）建设项目竣工投入生产和使用前，职业病防护设施未按照规定验收合格的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204069, '《中华人民共和国职业病防治法》', '第七十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '违反本法规定，有下列行为之一的，由卫生行政部门给予警告，责令限期改正；逾期不改正的，处十万元以下的罚款： （一）工作场所职业病危害因素检测、评价结果没有存档、上报、公布的； （二）未采取本法第二十条规定的职业病防治管理措施的； （三）未按照规定公布有关职业病防治的规章制度、操作规程、职业病危害事故应急救援措施的； （四）未按照规定组织劳动者进行职业卫生培训，或者未对劳动者个人职业病防护采取指导、督促措施的； （五）国内首次使用或者首次进口与职业病危害有关的化学材料，未按照规定报送毒性鉴定资料以及经有关部门登记注册或者批准进口的文件的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204070, '《中华人民共和国职业病防治法》', '第七十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '用人单位违反本法规定，有下列行为之一的，由卫生行政部门责令限期改正，给予警告，可以并处五万元以上十万元以下的罚款： （一）未按照规定及时、如实向卫生行政部门申报产生职业病危害的项目的； （二）未实施由专人负责的职业病危害因素日常监测，或者监测系统不能正常监测的； （三）订立或者变更劳动合同时，未告知劳动者职业病危害真实情况的； （四）未按照规定组织职业健康检查、建立职业健康监护档案或者未将检查结果书面告知劳动者的； （五）未依照本法规定在劳动者离开用人单位时提供职业健康监护档案复印件的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204071, '《中华人民共和国职业病防治法》', '第七十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '用人单位违反本法规定，有下列行为之一的，由卫生行政部门给予警告，责令限期改正，逾期不改正的，处五万元以上二十万元以下的罚款；情节严重的，责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令关闭： （一）工作场所职业病危害因素的强度或者浓度超过国家职业卫生标准的； （二）未提供职业病防护设施和个人使用的职业病防护用品，或者提供的职业病防护设施和个人使用的职业病防护用品不符合国家职业卫生标准和卫生要求的； （三）对职业病防护设备、应急救援设施和个人使用的职业病防护用品未按照规定进行维护、检修、检测，或者不能保持正常运行、使用状态的； （四）未按照规定对工作场所职业病危害因素进行检测、评价的； （五）工作场所职业病危害因素经治理仍然达不到国家职业卫生标准和卫生要求时，未停止存在职业病危害因素的作业的； （六）未按照规定安排职业病病人、疑似职业病病人进行诊治的； （七）发生或者可能发生急性职业病危害事故时，未立即采取应急救援和控制措施或者未按照规定及时报告的； （八）未按照规定在产生严重职业病危害的作业岗位醒目位置设置警示标识和中文警示说明的； （九）拒绝职业卫生监督管理部门监督检查的； （十）隐瞒、伪造、篡改、毁损职业健康监护档案、工作场所职业病危害因素检测评价结果等相关资料，或者拒不提供职业病诊断、鉴定所需资料的； （十一）未按照规定承担职业病诊断、鉴定费用和职业病病人的医疗、生活保障费用的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204072, '《中华人民共和国职业病防治法》', '第七十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '向用人单位提供可能产生职业病危害的设备、材料，未按照规定提供中文说明书或者设置警示标识和中文警示说明的，由卫生行政部门责令限期改正，给予警告，并处五万元以上二十万元以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204073, '《中华人民共和国职业病防治法》', '第七十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '用人单位和医疗卫生机构未按照规定报告职业病、疑似职业病的，由有关主管部门依据职责分工责令限期改正，给予警告，可以并处一万元以下的罚款；弄虚作假的，并处二万元以上五万元以下的罚款；对直接负责的主管人员和其他直接责任人员，可以依法给予降级或者撤职的处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204074, '《中华人民共和国职业病防治法》', '第七十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '违反本法规定，有下列情形之一的，由卫生行政部门责令限期治理，并处五万元以上三十万元以下的罚款；情节严重的，责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令关闭： （一）隐瞒技术、工艺、设备、材料所产生的职业病危害而采用的； （二）隐瞒本单位职业卫生真实情况的； （三）可能发生急性职业损伤的有毒、有害工作场所、放射工作场所或者放射性同位素的运输、贮存不符合本法第二十五条规定的； （四）使用国家明令禁止使用的可能产生职业病危害的设备或者材料的； （五）将产生职业病危害的作业转移给没有职业病防护条件的单位和个人，或者没有职业病防护条件的单位和个人接受产生职业病危害的作业的； （六）擅自拆除、停止使用职业病防护设备或者应急救援设施的； （七）安排未经职业健康检查的劳动者、有职业禁忌的劳动者、未成年工或者孕期、哺乳期女职工从事接触职业病危害的作业或者禁忌作业的； （八）违章指挥和强令劳动者进行没有职业病防护措施的作业的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204075, '《中华人民共和国职业病防治法》', '第七十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '生产、经营或者进口国家明令禁止使用的可能产生职业病危害的设备或者材料的，依照有关法律、行政法规的规定给予处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204076, '《中华人民共和国职业病防治法》', '第七十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '用人单位违反本法规定，已经对劳动者生命健康造成严重损害的，由卫生行政部门责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令关闭，并处十万元以上五十万元以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204077, '《中华人民共和国职业病防治法》', '第七十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '用人单位违反本法规定，造成重大职业病危害事故或者其他严重后果，构成犯罪的，对直接负责的主管人员和其他直接责任人员，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204078, '《中华人民共和国职业病防治法》', '第七十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '未取得职业卫生技术服务资质认可擅自从事职业卫生技术服务的，由卫生行政部门责令立即停止违法行为，没收违法所得；违法所得五千元以上的，并处违法所得二倍以上十倍以下的罚款；没有违法所得或者违法所得不足五千元的，并处五千元以上五万元以下的罚款；情节严重的，对直接负责的主管人员和其他直接责任人员，依法给予降级、撤职或者开除的处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204079, '《中华人民共和国职业病防治法》', '第八十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '从事职业卫生技术服务的机构和承担职业病诊断的医疗卫生机构违反本法规定，有下列行为之一的，由卫生行政部门责令立即停止违法行为，给予警告，没收违法所得；违法所得五千元以上的，并处违法所得二倍以上五倍以下的罚款；没有违法所得或者违法所得不足五千元的，并处五千元以上二万元以下的罚款；情节严重的，由原认可或者登记机关取消其相应的资格；对直接负责的主管人员和其他直接责任人员，依法给予降级、撤职或者开除的处分；构成犯罪的，依法追究刑事责任： （一）超出资质认可或者诊疗项目登记范围从事职业卫生技术服务或者职业病诊断的； （二）不按照本法规定履行法定职责的； （三）出具虚假证明文件的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204080, '《中华人民共和国职业病防治法》', '第八十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '职业病诊断鉴定委员会组成人员收受职业病诊断争议当事人的财物或者其他好处的，给予警告，没收收受的财物，可以并处三千元以上五万元以下的罚款，取消其担任职业病诊断鉴定委员会组成人员的资格，并从省、自治区、直辖市人民政府卫生行政部门设立的专家库中予以除名。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204081, '《中华人民共和国职业病防治法》', '第八十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '卫生行政部门不按照规定报告职业病和职业病危害事故的，由上一级行政部门责令改正，通报批评，给予警告；虚报、瞒报的，对单位负责人、直接负责的主管人员和其他直接责任人员依法给予降级、撤职或者开除的处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204082, '《中华人民共和国职业病防治法》', '第八十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '县级以上地方人民政府在职业病防治工作中未依照本法履行职责，本行政区域出现重大职业病危害事故、造成严重社会影响的，依法对直接负责的主管人员和其他直接责任人员给予记大过直至开除的处分。 县级以上人民政府职业卫生监督管理部门不履行本法规定的职责，滥用职权、玩忽职守、徇私舞弊，依法对直接负责的主管人员和其他直接责任人员给予记大过或者降级的处分；造成职业病危害事故或者其他严重后果的，依法给予撤职或者开除的处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204083, '《中华人民共和国职业病防治法》', '第八十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 法律责任', NULL, '违反本法规定，构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204084, '《中华人民共和国职业病防治法》', '第八十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 附 则', NULL, '本法下列用语的含义： 职业病危害，是指对从事职业活动的劳动者可能导致职业病的各种危害。职业病危害因素包括：职业活动中存在的各种有害的化学、物理、生物因素以及在作业过程中产生的其他职业有害因素。 职业禁忌，是指劳动者从事特定职业或者接触特定职业病危害因素时，比一般职业人群更易于遭受职业病危害和罹患职业病或者可能导致原有自身疾病病情加重，或者在从事作业过程中诱发可能导致对他人生命健康构成危险的疾病的个人特殊生理或者病理状态。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204085, '《中华人民共和国职业病防治法》', '第八十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 附 则', NULL, '本法第二条规定的用人单位以外的单位，产生职业病危害的，其职业病防治活动可以参照本法执行。 劳务派遣用工单位应当履行本法规定的用人单位的义务。 中国人民解放军参照执行本法的办法，由国务院、中央军事委员会制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204086, '《中华人民共和国职业病防治法》', '第八十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 附 则', NULL, '对医疗机构放射性职业病危害控制的监督管理，由卫生行政部门依照本法的规定实施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (204087, '《中华人民共和国职业病防治法》', '第八十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 附 则', NULL, '本法自2002年5月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205000, '《中华人民共和国矿山安全法》', '第一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第一章 总 则', NULL, '为了保障矿山生产安全，防止矿山事故，保护矿山职工人身安全，促进采矿业的发展，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205001, '《中华人民共和国矿山安全法》', '第二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第一章 总 则', NULL, '在中华人民共和国领域和中华人民共和国管辖的其他海域从事矿产资源开采活动，必须遵守本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205002, '《中华人民共和国矿山安全法》', '第三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第一章 总 则', NULL, '矿山企业必须具有保障安全生产的设施，建立、健全安全管理制度，采取有效措施改善职工劳动条件，加强矿山安全管理工作，保证安全生产。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205003, '《中华人民共和国矿山安全法》', '第四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第一章 总 则', NULL, '国务院劳动行政主管部门对全国矿山安全工作实施统一监督。 县级以上地方各级人民政府劳动行政主管部门对本行政区域内的矿山安全工作实施统一监督。 县级以上人民政府管理矿山企业的主管部门对矿山安全工作进行管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205004, '《中华人民共和国矿山安全法》', '第五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第一章 总 则', NULL, '国家鼓励矿山安全科学技术研究，推广先进技术，改进安全设施，提高矿山安全生产水平。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205005, '《中华人民共和国矿山安全法》', '第六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第一章 总 则', NULL, '对坚持矿山安全生产，防止矿山事故，参加矿山抢险救护，进行矿山安全科学技术研究等方面取得显著成绩的单位和个人，给予奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205006, '《中华人民共和国矿山安全法》', '第七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第二章 矿山建设的安全保障', NULL, '矿山建设工程的安全设施必须和主体工程同时设计、同时施工、同时投入生产和使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205007, '《中华人民共和国矿山安全法》', '第八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第二章 矿山建设的安全保障', NULL, '矿山建设工程的设计文件，必须符合矿山安全规程和行业技术规范，并按照国家规定经管理矿山企业的主管部门批准；不符合矿山安全规程和行业技术规范的，不得批准。 矿山建设工程安全设施的设计必须有劳动行政主管部门参加审查。 矿山安全规程和行业技术规范，由国务院管理矿山企业的主管部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205008, '《中华人民共和国矿山安全法》', '第九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第二章 矿山建设的安全保障', NULL, '矿山设计下列项目必须符合矿山安全规程和行业技术规范： （一）矿井的通风系统和供风量、风质、风速； （二）露天矿的边坡角和台阶的宽度、高度； （三）供电系统； （四）提升、运输系统； （五）防水、排水系统和防火、灭火系统； （六）防瓦斯系统和防尘系统； （七）有关矿山安全的其他项目。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205009, '《中华人民共和国矿山安全法》', '第十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第二章 矿山建设的安全保障', NULL, '每个矿井必须有两个以上能行人的安全出口，出口之间的直线水平距离必须符合矿山安全规程和行业技术规范。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205010, '《中华人民共和国矿山安全法》', '第十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第二章 矿山建设的安全保障', NULL, '矿山必须有与外界相通的、符合安全要求的运输和通讯设施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205011, '《中华人民共和国矿山安全法》', '第十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第二章 矿山建设的安全保障', NULL, '矿山建设工程必须按照管理矿山企业的主管部门批准的设计文件施工。 矿山建设工程安全设施竣工后，由管理矿山企业的主管部门验收，并须有劳动行政主管部门参加；不符合矿山安全规程和行业技术规范的，不得验收，不得投入生产。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205012, '《中华人民共和国矿山安全法》', '第十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第三章 矿山开采的安全保障', NULL, '矿山开采必须具备保障安全生产的条件，执行开采不同矿种的矿山安全规程和行业技术规范。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205013, '《中华人民共和国矿山安全法》', '第十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第三章 矿山开采的安全保障', NULL, '矿山设计规定保留的矿柱、岩柱，在规定的期限内，应当予以保护，不得开采或者毁坏。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205014, '《中华人民共和国矿山安全法》', '第十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第三章 矿山开采的安全保障', NULL, '矿山使用的有特殊安全要求的设备、器材、防护用品和安全检测仪器，必须符合国家安全标准或者行业安全标准；不符合国家安全标准或者行业安全标准的，不得使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205015, '《中华人民共和国矿山安全法》', '第十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第三章 矿山开采的安全保障', NULL, '矿山企业必须对机电设备及其防护装置、安全检测仪器，定期检查、维修，保证使用安全。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205016, '《中华人民共和国矿山安全法》', '第十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第三章 矿山开采的安全保障', NULL, '矿山企业必须对作业场所中的有毒有害物质和井下空气含氧量进行检测，保证符合安全要求。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205017, '《中华人民共和国矿山安全法》', '第十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第三章 矿山开采的安全保障', NULL, '矿山企业必须对下列危害安全的事故隐患采取预防措施： （一）冒顶、片帮、边坡滑落和地表塌陷； （二）瓦斯爆炸、煤尘爆炸； （三）冲击地压、瓦斯突出、井喷； （四）地面和井下的火灾、水害； （五）爆破器材和爆破作业发生的危害； （六）粉尘、有毒有害气体、放射性物质和其他有害物质引起的危害； （七）其他危害。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205018, '《中华人民共和国矿山安全法》', '第十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第三章 矿山开采的安全保障', NULL, '矿山企业对使用机械、电气设备，排土场、矸石山、尾矿库与矿山闭坑后可能引起的危害，应当采取预防措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205019, '《中华人民共和国矿山安全法》', '第二十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第四章 矿山企业的安全管理', NULL, '矿山企业必须建立、健全安全生产责任制。 矿长对本企业的安全生产工作负责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205020, '《中华人民共和国矿山安全法》', '第二十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第四章 矿山企业的安全管理', NULL, '矿长应当定期向职工代表大会或者职工大会报告安全生产工作，发挥职工代表大会的监督作用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205021, '《中华人民共和国矿山安全法》', '第二十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第四章 矿山企业的安全管理', NULL, '矿山企业职工必须遵守有关矿山安全的法律、法规和企业规章制度。 矿山企业职工有权对危害安全的行为，提出批评、检举和控告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205022, '《中华人民共和国矿山安全法》', '第二十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第四章 矿山企业的安全管理', NULL, '矿山企业工会依法维护职工生产安全的合法权益，组织职工对矿山安全工作进行监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205023, '《中华人民共和国矿山安全法》', '第二十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第四章 矿山企业的安全管理', NULL, '矿山企业违反有关安全的法律、法规，工会有权要求企业行政方面或者有关部门认真处理。 矿山企业召开讨论有关安全生产的会议，应当有工会代表参加，工会有权提出意见和建议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205024, '《中华人民共和国矿山安全法》', '第二十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第四章 矿山企业的安全管理', NULL, '矿山企业工会发现企业行政方面违章指挥、强令工人冒险作业或者生产过程中发现明显重大事故隐患和职业危害，有权提出解决的建议；发现危及职工生命安全的情况时，有权向矿山企业行政方面建议组织职工撤离危险现场，矿山企业行政方面必须及时作出处理决定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205025, '《中华人民共和国矿山安全法》', '第二十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第四章 矿山企业的安全管理', NULL, '矿山企业必须对职工进行安全教育、培训；未经安全教育、培训的，不得上岗作业。 矿山企业安全生产的特种作业人员必须接受专门培训，经考核合格取得操作资格证书的，方可上岗作业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205026, '《中华人民共和国矿山安全法》', '第二十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第四章 矿山企业的安全管理', NULL, '矿长必须经过考核，具备安全专业知识，具有领导安全生产和处理矿山事故的能力。 矿山企业安全工作人员必须具备必要的安全专业知识和矿山安全工作经验。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205027, '《中华人民共和国矿山安全法》', '第二十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第四章 矿山企业的安全管理', NULL, '矿山企业必须向职工发放保障安全生产所需的劳动防护用品。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205028, '《中华人民共和国矿山安全法》', '第二十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第四章 矿山企业的安全管理', NULL, '矿山企业不得录用未成年人从事矿山井下劳动。 矿山企业对女职工按照国家规定实行特殊劳动保护，不得分配女职工从事矿山井下劳动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205029, '《中华人民共和国矿山安全法》', '第三十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第四章 矿山企业的安全管理', NULL, '矿山企业必须制定矿山事故防范措施，并组织落实。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205030, '《中华人民共和国矿山安全法》', '第三十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第四章 矿山企业的安全管理', NULL, '矿山企业应当建立由专职或者兼职人员组成的救护和医疗急救组织，配备必要的装备、器材和药物。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205031, '《中华人民共和国矿山安全法》', '第三十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第四章 矿山企业的安全管理', NULL, '矿山企业必须从矿产品销售额中按照国家规定提取安全技术措施专项费用。安全技术措施专项费用必须全部用于改善矿山安全生产条件，不得挪作他用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205032, '《中华人民共和国矿山安全法》', '第三十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第五章 矿山安全的监督和管理', NULL, '县级以上各级人民政府劳动行政主管部门对矿山安全工作行使下列监督职责： （一）检查矿山企业和管理矿山企业的主管部门贯彻执行矿山安全法律、法规的情况； （二）参加矿山建设工程安全设施的设计审查和竣工验收； （三）检查矿山劳动条件和安全状况； （四）检查矿山企业职工安全教育、培训工作； （五）监督矿山企业提取和使用安全技术措施专项费用的情况； （六）参加并监督矿山事故的调查和处理； （七）法律、行政法规规定的其他监督职责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205033, '《中华人民共和国矿山安全法》', '第三十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第五章 矿山安全的监督和管理', NULL, '县级以上人民政府管理矿山企业的主管部门对矿山安全工作行使下列管理职责： （一）检查矿山企业贯彻执行矿山安全法律、法规的情况； （二）审查批准矿山建设工程安全设施的设计； （三）负责矿山建设工程安全设施的竣工验收； （四）组织矿长和矿山企业安全工作人员的培训工作； （五）调查和处理重大矿山事故； （六）法律、行政法规规定的其他管理职责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205034, '《中华人民共和国矿山安全法》', '第三十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第五章 矿山安全的监督和管理', NULL, '劳动行政主管部门的矿山安全监督人员有权进入矿山企业，在现场检查安全状况；发现有危及职工安全的紧急险情时，应当要求矿山企业立即处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205035, '《中华人民共和国矿山安全法》', '第三十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第六章 矿山事故处理', NULL, '发生矿山事故，矿山企业必须立即组织抢救，防止事故扩大，减少人员伤亡和财产损失，对伤亡事故必须立即如实报告劳动行政主管部门和管理矿山企业的主管部门。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205036, '《中华人民共和国矿山安全法》', '第三十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第六章 矿山事故处理', NULL, '发生一般矿山事故，由矿山企业负责调查和处理。 发生重大矿山事故，由政府及其有关部门、工会和矿山企业按照行政法规的规定进行调查和处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205037, '《中华人民共和国矿山安全法》', '第三十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第六章 矿山事故处理', NULL, '矿山企业对矿山事故中伤亡的职工按照国家规定给予抚恤或者补偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205038, '《中华人民共和国矿山安全法》', '第三十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第六章 矿山事故处理', NULL, '矿山事故发生后，应当尽快消除现场危险，查明事故原因，提出防范措施。现场危险消除后，方可恢复生产。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205039, '《中华人民共和国矿山安全法》', '第四十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第七章 法律责任', NULL, '违反本法规定，有下列行为之一的，由劳动行政主管部门责令改正，可以并处罚款；情节严重的，提请县级以上人民政府决定责令停产整顿；对主管人员和直接责任人员由其所在单位或者上级主管机关给予行政处分： （一）未对职工进行安全教育、培训，分配职工上岗作业的； （二）使用不符合国家安全标准或者行业安全标准的设备、器材、防护用品、安全检测仪器的； （三）未按照规定提取或者使用安全技术措施专项费用的； （四）拒绝矿山安全监督人员现场检查或者在被检查时隐瞒事故隐患、不如实反映情况的； （五）未按照规定及时、如实报告矿山事故的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205040, '《中华人民共和国矿山安全法》', '第四十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第七章 法律责任', NULL, '矿长不具备安全专业知识的，安全生产的特种作业人员未取得操作资格证书上岗作业的，由劳动行政主管部门责令限期改正；逾期不改正的，提请县级以上人民政府决定责令停产，调整配备合格人员后，方可恢复生产。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205041, '《中华人民共和国矿山安全法》', '第四十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第七章 法律责任', NULL, '矿山建设工程安全设施的设计未经批准擅自施工的，由管理矿山企业的主管部门责令停止施工；拒不执行的，由管理矿山企业的主管部门提请县级以上人民政府决定由有关主管部门吊销其采矿许可证和营业执照。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205042, '《中华人民共和国矿山安全法》', '第四十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第七章 法律责任', NULL, '矿山建设工程的安全设施未经验收或者验收不合格擅自投入生产的，由劳动行政主管部门会同管理矿山企业的主管部门责令停止生产，并由劳动行政主管部门处以罚款；拒不停止生产的，由劳动行政主管部门提请县级以上人民政府决定由有关主管部门吊销其采矿许可证和营业执照。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205043, '《中华人民共和国矿山安全法》', '第四十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第七章 法律责任', NULL, '已经投入生产的矿山企业，不具备安全生产条件而强行开采的，由劳动行政主管部门会同管理矿山企业的主管部门责令限期改进；逾期仍不具备安全生产条件的，由劳动行政主管部门提请县级以上人民政府决定责令停产整顿或者由有关主管部门吊销其采矿许可证和营业执照。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205044, '《中华人民共和国矿山安全法》', '第四十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第七章 法律责任', NULL, '当事人对行政处罚决定不服的，可以在接到处罚决定通知之日起十五日内向作出处罚决定的机关的上一级机关申请复议；当事人也可以在接到处罚决定通知之日起十五日内直接向人民法院起诉。 复议机关应当在接到复议申请之日起六十日内作出复议决定。当事人对复议决定不服的，可以在接到复议决定之日起十五日内向人民法院起诉。复议机关逾期不作出复议决定的，当事人可以在复议期满之日起十五日内向人民法院起诉。 当事人逾期不申请复议也不向人民法院起诉、又不履行处罚决定的，作出处罚决定的机关可以申请人民法院强制执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205045, '《中华人民共和国矿山安全法》', '第四十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第七章 法律责任', NULL, '矿山企业主管人员违章指挥、强令工人冒险作业，因而发生重大伤亡事故的，依照刑法有关规定追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205046, '《中华人民共和国矿山安全法》', '第四十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第七章 法律责任', NULL, '矿山企业主管人员对矿山事故隐患不采取措施，因而发生重大伤亡事故的，依照刑法有关规定追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205047, '《中华人民共和国矿山安全法》', '第四十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第七章 法律责任', NULL, '矿山安全监督人员和安全管理人员滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；不构成犯罪的，给予行政处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205048, '《中华人民共和国矿山安全法》', '第四十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第八章 附 则', NULL, '国务院劳动行政主管部门根据本法制定实施条例，报国务院批准施行。 省、自治区、直辖市人民代表大会常务委员会可以根据本法和本地区的实际情况，制定实施办法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (205049, '《中华人民共和国矿山安全法》', '第五十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', '第八章 附 则', NULL, '本法自1993年5月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206000, '《中华人民共和国特种设备安全法》', '第一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第一章 总 则', NULL, '为了加强特种设备安全工作，预防特种设备事故，保障人身和财产安全，促进经济社会发展，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206001, '《中华人民共和国特种设备安全法》', '第二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第一章 总 则', NULL, '特种设备的生产（包括设计、制造、安装、改造、修理）、经营、使用、检验、检测和特种设备安全的监督管理，适用本法。 本法所称特种设备，是指对人身和财产安全有较大危险性的锅炉、压力容器（含气瓶）、压力管道、电梯、起重机械、客运索道、大型游乐设施、场（厂）内专用机动车辆，以及法律、行政法规规定适用本法的其他特种设备。 国家对特种设备实行目录管理。特种设备目录由国务院负责特种设备安全监督管理的部门制定，报国务院批准后执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206002, '《中华人民共和国特种设备安全法》', '第三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第一章 总 则', NULL, '特种设备安全工作应当坚持安全第一、预防为主、节能环保、综合治理的原则。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206003, '《中华人民共和国特种设备安全法》', '第四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第一章 总 则', NULL, '国家对特种设备的生产、经营、使用，实施分类的、全过程的安全监督管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206004, '《中华人民共和国特种设备安全法》', '第五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第一章 总 则', NULL, '国务院负责特种设备安全监督管理的部门对全国特种设备安全实施监督管理。县级以上地方各级人民政府负责特种设备安全监督管理的部门对本行政区域内特种设备安全实施监督管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206005, '《中华人民共和国特种设备安全法》', '第六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第一章 总 则', NULL, '国务院和地方各级人民政府应当加强对特种设备安全工作的领导，督促各有关部门依法履行监督管理职责。 县级以上地方各级人民政府应当建立协调机制，及时协调、解决特种设备安全监督管理中存在的问题。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206006, '《中华人民共和国特种设备安全法》', '第七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第一章 总 则', NULL, '特种设备生产、经营、使用单位应当遵守本法和其他有关法律、法规，建立、健全特种设备安全和节能责任制度，加强特种设备安全和节能管理，确保特种设备生产、经营、使用安全，符合节能要求。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206007, '《中华人民共和国特种设备安全法》', '第八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第一章 总 则', NULL, '特种设备生产、经营、使用、检验、检测应当遵守有关特种设备安全技术规范及相关标准。 特种设备安全技术规范由国务院负责特种设备安全监督管理的部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206008, '《中华人民共和国特种设备安全法》', '第九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第一章 总 则', NULL, '特种设备行业协会应当加强行业自律，推进行业诚信体系建设，提高特种设备安全管理水平。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206009, '《中华人民共和国特种设备安全法》', '第十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第一章 总 则', NULL, '国家支持有关特种设备安全的科学技术研究，鼓励先进技术和先进管理方法的推广应用，对做出突出贡献的单位和个人给予奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206010, '《中华人民共和国特种设备安全法》', '第十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第一章 总 则', NULL, '负责特种设备安全监督管理的部门应当加强特种设备安全宣传教育，普及特种设备安全知识，增强社会公众的特种设备安全意识。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206011, '《中华人民共和国特种设备安全法》', '第十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第一章 总 则', NULL, '任何单位和个人有权向负责特种设备安全监督管理的部门和有关部门举报涉及特种设备安全的违法行为，接到举报的部门应当及时处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206012, '《中华人民共和国特种设备安全法》', '第十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第一节 一般规定', '特种设备生产、经营、使用单位及其主要负责人对其生产、经营、使用的特种设备安全负责。 特种设备生产、经营、使用单位应当按照国家有关规定配备特种设备安全管理人员、检测人员和作业人员，并对其进行必要的安全教育和技能培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206013, '《中华人民共和国特种设备安全法》', '第十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第一节 一般规定', '特种设备安全管理人员、检测人员和作业人员应当按照国家有关规定取得相应资格，方可从事相关工作。特种设备安全管理人员、检测人员和作业人员应当严格执行安全技术规范和管理制度，保证特种设备安全。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206014, '《中华人民共和国特种设备安全法》', '第十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第一节 一般规定', '特种设备生产、经营、使用单位对其生产、经营、使用的特种设备应当进行自行检测和维护保养，对国家规定实行检验的特种设备应当及时申报并接受检验。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206015, '《中华人民共和国特种设备安全法》', '第十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第一节 一般规定', '特种设备采用新材料、新技术、新工艺，与安全技术规范的要求不一致，或者安全技术规范未作要求、可能对安全性能有重大影响的，应当向国务院负责特种设备安全监督管理的部门申报，由国务院负责特种设备安全监督管理的部门及时委托安全技术咨询机构或者相关专业机构进行技术评审，评审结果经国务院负责特种设备安全监督管理的部门批准，方可投入生产、使用。 国务院负责特种设备安全监督管理的部门应当将允许使用的新材料、新技术、新工艺的有关技术要求，及时纳入安全技术规范。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206016, '《中华人民共和国特种设备安全法》', '第十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第一节 一般规定', '国家鼓励投保特种设备安全责任保险。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206017, '《中华人民共和国特种设备安全法》', '第十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第二节 生 产', '国家按照分类监督管理的原则对特种设备生产实行许可制度。特种设备生产单位应当具备下列条件，并经负责特种设备安全监督管理的部门许可，方可从事生产活动： （一）有与生产相适应的专业技术人员； （二）有与生产相适应的设备、设施和工作场所； （三）有健全的质量保证、安全管理和岗位责任等制度。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206018, '《中华人民共和国特种设备安全法》', '第十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第二节 生 产', '特种设备生产单位应当保证特种设备生产符合安全技术规范及相关标准的要求，对其生产的特种设备的安全性能负责。不得生产不符合安全性能要求和能效指标以及国家明令淘汰的特种设备。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206019, '《中华人民共和国特种设备安全法》', '第二十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第二节 生 产', '锅炉、气瓶、氧舱、客运索道、大型游乐设施的设计文件，应当经负责特种设备安全监督管理的部门核准的检验机构鉴定，方可用于制造。 特种设备产品、部件或者试制的特种设备新产品、新部件以及特种设备采用的新材料，按照安全技术规范的要求需要通过型式试验进行安全性验证的，应当经负责特种设备安全监督管理的部门核准的检验机构进行型式试验。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206020, '《中华人民共和国特种设备安全法》', '第二十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第二节 生 产', '特种设备出厂时，应当随附安全技术规范要求的设计文件、产品质量合格证明、安装及使用维护保养说明、监督检验证明等相关技术资料和文件，并在特种设备显著位置设置产品铭牌、安全警示标志及其说明。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206021, '《中华人民共和国特种设备安全法》', '第二十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第二节 生 产', '电梯的安装、改造、修理，必须由电梯制造单位或者其委托的依照本法取得相应许可的单位进行。电梯制造单位委托其他单位进行电梯安装、改造、修理的，应当对其安装、改造、修理进行安全指导和监控，并按照安全技术规范的要求进行校验和调试。电梯制造单位对电梯安全性能负责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206022, '《中华人民共和国特种设备安全法》', '第二十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第二节 生 产', '特种设备安装、改造、修理的施工单位应当在施工前将拟进行的特种设备安装、改造、修理情况书面告知直辖市或者设区的市级人民政府负责特种设备安全监督管理的部门。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206023, '《中华人民共和国特种设备安全法》', '第二十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第二节 生 产', '特种设备安装、改造、修理竣工后，安装、改造、修理的施工单位应当在验收后三十日内将相关技术资料和文件移交特种设备使用单位。特种设备使用单位应当将其存入该特种设备的安全技术档案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206024, '《中华人民共和国特种设备安全法》', '第二十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第二节 生 产', '锅炉、压力容器、压力管道元件等特种设备的制造过程和锅炉、压力容器、压力管道、电梯、起重机械、客运索道、大型游乐设施的安装、改造、重大修理过程，应当经特种设备检验机构按照安全技术规范的要求进行监督检验；未经监督检验或者监督检验不合格的，不得出厂或者交付使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206025, '《中华人民共和国特种设备安全法》', '第二十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第二节 生 产', '国家建立缺陷特种设备召回制度。因生产原因造成特种设备存在危及安全的同一性缺陷的，特种设备生产单位应当立即停止生产，主动召回。 国务院负责特种设备安全监督管理的部门发现特种设备存在应当召回而未召回的情形时，应当责令特种设备生产单位召回。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206026, '《中华人民共和国特种设备安全法》', '第二十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第三节 经 营', '特种设备销售单位销售的特种设备，应当符合安全技术规范及相关标准的要求，其设计文件、产品质量合格证明、安装及使用维护保养说明、监督检验证明等相关技术资料和文件应当齐全。 特种设备销售单位应当建立特种设备检查验收和销售记录制度。 禁止销售未取得许可生产的特种设备，未经检验和检验不合格的特种设备，或者国家明令淘汰和已经报废的特种设备。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206027, '《中华人民共和国特种设备安全法》', '第二十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第三节 经 营', '特种设备出租单位不得出租未取得许可生产的特种设备或者国家明令淘汰和已经报废的特种设备，以及未按照安全技术规范的要求进行维护保养和未经检验或者检验不合格的特种设备。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206028, '《中华人民共和国特种设备安全法》', '第二十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第三节 经 营', '特种设备在出租期间的使用管理和维护保养义务由特种设备出租单位承担，法律另有规定或者当事人另有约定的除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206029, '《中华人民共和国特种设备安全法》', '第三十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第三节 经 营', '进口的特种设备应当符合我国安全技术规范的要求，并经检验合格；需要取得我国特种设备生产许可的，应当取得许可。 进口特种设备随附的技术资料和文件应当符合本法第二十一条的规定，其安装及使用维护保养说明、产品铭牌、安全警示标志及其说明应当采用中文。 特种设备的进出口检验，应当遵守有关进出口商品检验的法律、行政法规。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206030, '《中华人民共和国特种设备安全法》', '第三十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第三节 经 营', '进口特种设备，应当向进口地负责特种设备安全监督管理的部门履行提前告知义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206031, '《中华人民共和国特种设备安全法》', '第三十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第四节 使 用', '特种设备使用单位应当使用取得许可生产并经检验合格的特种设备。 禁止使用国家明令淘汰和已经报废的特种设备。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206032, '《中华人民共和国特种设备安全法》', '第三十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第四节 使 用', '特种设备使用单位应当在特种设备投入使用前或者投入使用后三十日内，向负责特种设备安全监督管理的部门办理使用登记，取得使用登记证书。登记标志应当置于该特种设备的显著位置。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206033, '《中华人民共和国特种设备安全法》', '第三十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第四节 使 用', '特种设备使用单位应当建立岗位责任、隐患治理、应急救援等安全管理制度，制定操作规程，保证特种设备安全运行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206034, '《中华人民共和国特种设备安全法》', '第三十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第四节 使 用', '特种设备使用单位应当建立特种设备安全技术档案。安全技术档案应当包括以下内容： （一）特种设备的设计文件、产品质量合格证明、安装及使用维护保养说明、监督检验证明等相关技术资料和文件； （二）特种设备的定期检验和定期自行检查记录； （三）特种设备的日常使用状况记录； （四）特种设备及其附属仪器仪表的维护保养记录； （五）特种设备的运行故障和事故记录。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206035, '《中华人民共和国特种设备安全法》', '第三十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第四节 使 用', '电梯、客运索道、大型游乐设施等为公众提供服务的特种设备的运营使用单位，应当对特种设备的使用安全负责，设置特种设备安全管理机构或者配备专职的特种设备安全管理人员；其他特种设备使用单位，应当根据情况设置特种设备安全管理机构或者配备专职、兼职的特种设备安全管理人员。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206036, '《中华人民共和国特种设备安全法》', '第三十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第四节 使 用', '特种设备的使用应当具有规定的安全距离、安全防护措施。 与特种设备安全相关的建筑物、附属设施，应当符合有关法律、行政法规的规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206037, '《中华人民共和国特种设备安全法》', '第三十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第四节 使 用', '特种设备属于共有的，共有人可以委托物业服务单位或者其他管理人管理特种设备，受托人履行本法规定的特种设备使用单位的义务，承担相应责任。共有人未委托的，由共有人或者实际管理人履行管理义务，承担相应责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206038, '《中华人民共和国特种设备安全法》', '第三十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第四节 使 用', '特种设备使用单位应当对其使用的特种设备进行经常性维护保养和定期自行检查，并作出记录。 特种设备使用单位应当对其使用的特种设备的安全附件、安全保护装置进行定期校验、检修，并作出记录。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206039, '《中华人民共和国特种设备安全法》', '第四十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第四节 使 用', '特种设备使用单位应当按照安全技术规范的要求，在检验合格有效期届满前一个月向特种设备检验机构提出定期检验要求。 特种设备检验机构接到定期检验要求后，应当按照安全技术规范的要求及时进行安全性能检验。特种设备使用单位应当将定期检验标志置于该特种设备的显著位置。 未经定期检验或者检验不合格的特种设备，不得继续使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206040, '《中华人民共和国特种设备安全法》', '第四十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第四节 使 用', '特种设备安全管理人员应当对特种设备使用状况进行经常性检查，发现问题应当立即处理；情况紧急时，可以决定停止使用特种设备并及时报告本单位有关负责人。 特种设备作业人员在作业过程中发现事故隐患或者其他不安全因素，应当立即向特种设备安全管理人员和单位有关负责人报告；特种设备运行不正常时，特种设备作业人员应当按照操作规程采取有效措施保证安全。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206041, '《中华人民共和国特种设备安全法》', '第四十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第四节 使 用', '特种设备出现故障或者发生异常情况，特种设备使用单位应当对其进行全面检查，消除事故隐患，方可继续使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206042, '《中华人民共和国特种设备安全法》', '第四十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第四节 使 用', '客运索道、大型游乐设施在每日投入使用前，其运营使用单位应当进行试运行和例行安全检查，并对安全附件和安全保护装置进行检查确认。 电梯、客运索道、大型游乐设施的运营使用单位应当将电梯、客运索道、大型游乐设施的安全使用说明、安全注意事项和警示标志置于易于为乘客注意的显著位置。 公众乘坐或者操作电梯、客运索道、大型游乐设施，应当遵守安全使用说明和安全注意事项的要求，服从有关工作人员的管理和指挥；遇有运行不正常时，应当按照安全指引，有序撤离。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206043, '《中华人民共和国特种设备安全法》', '第四十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第四节 使 用', '锅炉使用单位应当按照安全技术规范的要求进行锅炉水（介）质处理，并接受特种设备检验机构的定期检验。 从事锅炉清洗，应当按照安全技术规范的要求进行，并接受特种设备检验机构的监督检验。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206044, '《中华人民共和国特种设备安全法》', '第四十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第四节 使 用', '电梯的维护保养应当由电梯制造单位或者依照本法取得许可的安装、改造、修理单位进行。 电梯的维护保养单位应当在维护保养中严格执行安全技术规范的要求，保证其维护保养的电梯的安全性能，并负责落实现场安全防护措施，保证施工安全。 电梯的维护保养单位应当对其维护保养的电梯的安全性能负责；接到故障通知后，应当立即赶赴现场，并采取必要的应急救援措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206045, '《中华人民共和国特种设备安全法》', '第四十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第四节 使 用', '电梯投入使用后，电梯制造单位应当对其制造的电梯的安全运行情况进行跟踪调查和了解，对电梯的维护保养单位或者使用单位在维护保养和安全运行方面存在的问题，提出改进建议，并提供必要的技术帮助；发现电梯存在严重事故隐患时，应当及时告知电梯使用单位，并向负责特种设备安全监督管理的部门报告。电梯制造单位对调查和了解的情况，应当作出记录。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206046, '《中华人民共和国特种设备安全法》', '第四十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第四节 使 用', '特种设备进行改造、修理，按照规定需要变更使用登记的，应当办理变更登记，方可继续使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206047, '《中华人民共和国特种设备安全法》', '第四十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第四节 使 用', '特种设备存在严重事故隐患，无改造、修理价值，或者达到安全技术规范规定的其他报废条件的，特种设备使用单位应当依法履行报废义务，采取必要措施消除该特种设备的使用功能，并向原登记的负责特种设备安全监督管理的部门办理使用登记证书注销手续。 前款规定报废条件以外的特种设备，达到设计使用年限可以继续使用的，应当按照安全技术规范的要求通过检验或者安全评估，并办理使用登记证书变更，方可继续使用。允许继续使用的，应当采取加强检验、检测和维护保养等措施，确保使用安全。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206048, '《中华人民共和国特种设备安全法》', '第四十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第二章 生产、经营、使用', '第四节 使 用', '移动式压力容器、气瓶充装单位，应当具备下列条件，并经负责特种设备安全监督管理的部门许可，方可从事充装活动： （一）有与充装和管理相适应的管理人员和技术人员； （二）有与充装和管理相适应的充装设备、检测手段、场地厂房、器具、安全设施； （三）有健全的充装管理制度、责任制度、处理措施。 充装单位应当建立充装前后的检查、记录制度，禁止对不符合安全技术规范要求的移动式压力容器和气瓶进行充装。 气瓶充装单位应当向气体使用者提供符合安全技术规范要求的气瓶，对气体使用者进行气瓶安全使用指导，并按照安全技术规范的要求办理气瓶使用登记，及时申报定期检验。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206049, '《中华人民共和国特种设备安全法》', '第五十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第三章 检验、检测', NULL, '从事本法规定的监督检验、定期检验的特种设备检验机构，以及为特种设备生产、经营、使用提供检测服务的特种设备检测机构，应当具备下列条件，并经负责特种设备安全监督管理的部门核准，方可从事检验、检测工作： （一）有与检验、检测工作相适应的检验、检测人员； （二）有与检验、检测工作相适应的检验、检测仪器和设备； （三）有健全的检验、检测管理制度和责任制度。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206050, '《中华人民共和国特种设备安全法》', '第五十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第三章 检验、检测', NULL, '特种设备检验、检测机构的检验、检测人员应当经考核，取得检验、检测人员资格，方可从事检验、检测工作。 特种设备检验、检测机构的检验、检测人员不得同时在两个以上检验、检测机构中执业；变更执业机构的，应当依法办理变更手续。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206051, '《中华人民共和国特种设备安全法》', '第五十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第三章 检验、检测', NULL, '特种设备检验、检测工作应当遵守法律、行政法规的规定，并按照安全技术规范的要求进行。 特种设备检验、检测机构及其检验、检测人员应当依法为特种设备生产、经营、使用单位提供安全、可靠、便捷、诚信的检验、检测服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206052, '《中华人民共和国特种设备安全法》', '第五十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第三章 检验、检测', NULL, '特种设备检验、检测机构及其检验、检测人员应当客观、公正、及时地出具检验、检测报告，并对检验、检测结果和鉴定结论负责。 特种设备检验、检测机构及其检验、检测人员在检验、检测中发现特种设备存在严重事故隐患时，应当及时告知相关单位，并立即向负责特种设备安全监督管理的部门报告。 负责特种设备安全监督管理的部门应当组织对特种设备检验、检测机构的检验、检测结果和鉴定结论进行监督抽查，但应当防止重复抽查。监督抽查结果应当向社会公布。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206053, '《中华人民共和国特种设备安全法》', '第五十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第三章 检验、检测', NULL, '特种设备生产、经营、使用单位应当按照安全技术规范的要求向特种设备检验、检测机构及其检验、检测人员提供特种设备相关资料和必要的检验、检测条件，并对资料的真实性负责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206054, '《中华人民共和国特种设备安全法》', '第五十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第三章 检验、检测', NULL, '特种设备检验、检测机构及其检验、检测人员对检验、检测过程中知悉的商业秘密，负有保密义务。 特种设备检验、检测机构及其检验、检测人员不得从事有关特种设备的生产、经营活动，不得推荐或者监制、监销特种设备。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206055, '《中华人民共和国特种设备安全法》', '第五十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第三章 检验、检测', NULL, '特种设备检验机构及其检验人员利用检验工作故意刁难特种设备生产、经营、使用单位的，特种设备生产、经营、使用单位有权向负责特种设备安全监督管理的部门投诉，接到投诉的部门应当及时进行调查处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206056, '《中华人民共和国特种设备安全法》', '第五十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第四章 监督管理', NULL, '负责特种设备安全监督管理的部门依照本法规定，对特种设备生产、经营、使用单位和检验、检测机构实施监督检查。 负责特种设备安全监督管理的部门应当对学校、幼儿园以及医院、车站、客运码头、商场、体育场馆、展览馆、公园等公众聚集场所的特种设备，实施重点安全监督检查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206057, '《中华人民共和国特种设备安全法》', '第五十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第四章 监督管理', NULL, '负责特种设备安全监督管理的部门实施本法规定的许可工作，应当依照本法和其他有关法律、行政法规规定的条件和程序以及安全技术规范的要求进行审查；不符合规定的，不得许可。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206058, '《中华人民共和国特种设备安全法》', '第五十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第四章 监督管理', NULL, '负责特种设备安全监督管理的部门在办理本法规定的许可时，其受理、审查、许可的程序必须公开，并应当自受理申请之日起三十日内，作出许可或者不予许可的决定；不予许可的，应当书面向申请人说明理由。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206059, '《中华人民共和国特种设备安全法》', '第六十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第四章 监督管理', NULL, '负责特种设备安全监督管理的部门对依法办理使用登记的特种设备应当建立完整的监督管理档案和信息查询系统；对达到报废条件的特种设备，应当及时督促特种设备使用单位依法履行报废义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206060, '《中华人民共和国特种设备安全法》', '第六十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第四章 监督管理', NULL, '负责特种设备安全监督管理的部门在依法履行监督检查职责时，可以行使下列职权： （一）进入现场进行检查，向特种设备生产、经营、使用单位和检验、检测机构的主要负责人和其他有关人员调查、了解有关情况； （二）根据举报或者取得的涉嫌违法证据，查阅、复制特种设备生产、经营、使用单位和检验、检测机构的有关合同、发票、账簿以及其他有关资料； （三）对有证据表明不符合安全技术规范要求或者存在严重事故隐患的特种设备实施查封、扣押； （四）对流入市场的达到报废条件或者已经报废的特种设备实施查封、扣押； （五）对违反本法规定的行为作出行政处罚决定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206061, '《中华人民共和国特种设备安全法》', '第六十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第四章 监督管理', NULL, '负责特种设备安全监督管理的部门在依法履行职责过程中，发现违反本法规定和安全技术规范要求的行为或者特种设备存在事故隐患时，应当以书面形式发出特种设备安全监察指令，责令有关单位及时采取措施予以改正或者消除事故隐患。紧急情况下要求有关单位采取紧急处置措施的，应当随后补发特种设备安全监察指令。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206062, '《中华人民共和国特种设备安全法》', '第六十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第四章 监督管理', NULL, '负责特种设备安全监督管理的部门在依法履行职责过程中，发现重大违法行为或者特种设备存在严重事故隐患时，应当责令有关单位立即停止违法行为、采取措施消除事故隐患，并及时向上级负责特种设备安全监督管理的部门报告。接到报告的负责特种设备安全监督管理的部门应当采取必要措施，及时予以处理。 对违法行为、严重事故隐患的处理需要当地人民政府和有关部门的支持、配合时，负责特种设备安全监督管理的部门应当报告当地人民政府，并通知其他有关部门。当地人民政府和其他有关部门应当采取必要措施，及时予以处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206063, '《中华人民共和国特种设备安全法》', '第六十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第四章 监督管理', NULL, '地方各级人民政府负责特种设备安全监督管理的部门不得要求已经依照本法规定在其他地方取得许可的特种设备生产单位重复取得许可，不得要求对已经依照本法规定在其他地方检验合格的特种设备重复进行检验。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206064, '《中华人民共和国特种设备安全法》', '第六十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第四章 监督管理', NULL, '负责特种设备安全监督管理的部门的安全监察人员应当熟悉相关法律、法规，具有相应的专业知识和工作经验，取得特种设备安全行政执法证件。 特种设备安全监察人员应当忠于职守、坚持原则、秉公执法。 负责特种设备安全监督管理的部门实施安全监督检查时，应当有二名以上特种设备安全监察人员参加，并出示有效的特种设备安全行政执法证件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206065, '《中华人民共和国特种设备安全法》', '第六十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第四章 监督管理', NULL, '负责特种设备安全监督管理的部门对特种设备生产、经营、使用单位和检验、检测机构实施监督检查，应当对每次监督检查的内容、发现的问题及处理情况作出记录，并由参加监督检查的特种设备安全监察人员和被检查单位的有关负责人签字后归档。被检查单位的有关负责人拒绝签字的，特种设备安全监察人员应当将情况记录在案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206066, '《中华人民共和国特种设备安全法》', '第六十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第四章 监督管理', NULL, '负责特种设备安全监督管理的部门及其工作人员不得推荐或者监制、监销特种设备；对履行职责过程中知悉的商业秘密负有保密义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206067, '《中华人民共和国特种设备安全法》', '第六十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第四章 监督管理', NULL, '国务院负责特种设备安全监督管理的部门和省、自治区、直辖市人民政府负责特种设备安全监督管理的部门应当定期向社会公布特种设备安全总体状况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206068, '《中华人民共和国特种设备安全法》', '第六十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第五章 事故应急救援与调查处理', NULL, '国务院负责特种设备安全监督管理的部门应当依法组织制定特种设备重特大事故应急预案，报国务院批准后纳入国家突发事件应急预案体系。 县级以上地方各级人民政府及其负责特种设备安全监督管理的部门应当依法组织制定本行政区域内特种设备事故应急预案，建立或者纳入相应的应急处置与救援体系。 特种设备使用单位应当制定特种设备事故应急专项预案，并定期进行应急演练。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206069, '《中华人民共和国特种设备安全法》', '第七十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第五章 事故应急救援与调查处理', NULL, '特种设备发生事故后，事故发生单位应当按照应急预案采取措施，组织抢救，防止事故扩大，减少人员伤亡和财产损失，保护事故现场和有关证据，并及时向事故发生地县级以上人民政府负责特种设备安全监督管理的部门和有关部门报告。 县级以上人民政府负责特种设备安全监督管理的部门接到事故报告，应当尽快核实情况，立即向本级人民政府报告，并按照规定逐级上报。必要时，负责特种设备安全监督管理的部门可以越级上报事故情况。对特别重大事故、重大事故，国务院负责特种设备安全监督管理的部门应当立即报告国务院并通报国务院安全生产监督管理部门等有关部门。 与事故相关的单位和人员不得迟报、谎报或者瞒报事故情况，不得隐匿、毁灭有关证据或者故意破坏事故现场。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206070, '《中华人民共和国特种设备安全法》', '第七十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第五章 事故应急救援与调查处理', NULL, '事故发生地人民政府接到事故报告，应当依法启动应急预案，采取应急处置措施，组织应急救援。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206071, '《中华人民共和国特种设备安全法》', '第七十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第五章 事故应急救援与调查处理', NULL, '特种设备发生特别重大事故，由国务院或者国务院授权有关部门组织事故调查组进行调查。 发生重大事故，由国务院负责特种设备安全监督管理的部门会同有关部门组织事故调查组进行调查。 发生较大事故，由省、自治区、直辖市人民政府负责特种设备安全监督管理的部门会同有关部门组织事故调查组进行调查。 发生一般事故，由设区的市级人民政府负责特种设备安全监督管理的部门会同有关部门组织事故调查组进行调查。 事故调查组应当依法、独立、公正开展调查，提出事故调查报告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206072, '《中华人民共和国特种设备安全法》', '第七十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第五章 事故应急救援与调查处理', NULL, '组织事故调查的部门应当将事故调查报告报本级人民政府，并报上一级人民政府负责特种设备安全监督管理的部门备案。有关部门和单位应当依照法律、行政法规的规定，追究事故责任单位和人员的责任。 事故责任单位应当依法落实整改措施，预防同类事故发生。事故造成损害的，事故责任单位应当依法承担赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206073, '《中华人民共和国特种设备安全法》', '第七十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，未经许可从事特种设备生产活动的，责令停止生产，没收违法制造的特种设备，处十万元以上五十万元以下罚款；有违法所得的，没收违法所得；已经实施安装、改造、修理的，责令恢复原状或者责令限期由取得许可的单位重新安装、改造、修理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206074, '《中华人民共和国特种设备安全法》', '第七十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，特种设备的设计文件未经鉴定，擅自用于制造的，责令改正，没收违法制造的特种设备，处五万元以上五十万元以下罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206075, '《中华人民共和国特种设备安全法》', '第七十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，未进行型式试验的，责令限期改正；逾期未改正的，处三万元以上三十万元以下罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206076, '《中华人民共和国特种设备安全法》', '第七十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，特种设备出厂时，未按照安全技术规范的要求随附相关技术资料和文件的，责令限期改正；逾期未改正的，责令停止制造、销售，处二万元以上二十万元以下罚款；有违法所得的，没收违法所得。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206077, '《中华人民共和国特种设备安全法》', '第七十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，特种设备安装、改造、修理的施工单位在施工前未书面告知负责特种设备安全监督管理的部门即行施工的，或者在验收后三十日内未将相关技术资料和文件移交特种设备使用单位的，责令限期改正；逾期未改正的，处一万元以上十万元以下罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206078, '《中华人民共和国特种设备安全法》', '第七十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，特种设备的制造、安装、改造、重大修理以及锅炉清洗过程，未经监督检验的，责令限期改正；逾期未改正的，处五万元以上二十万元以下罚款；有违法所得的，没收违法所得；情节严重的，吊销生产许可证。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206079, '《中华人民共和国特种设备安全法》', '第八十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，电梯制造单位有下列情形之一的，责令限期改正；逾期未改正的，处一万元以上十万元以下罚款： （一）未按照安全技术规范的要求对电梯进行校验、调试的； （二）对电梯的安全运行情况进行跟踪调查和了解时，发现存在严重事故隐患，未及时告知电梯使用单位并向负责特种设备安全监督管理的部门报告的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206080, '《中华人民共和国特种设备安全法》', '第八十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，特种设备生产单位有下列行为之一的，责令限期改正；逾期未改正的，责令停止生产，处五万元以上五十万元以下罚款；情节严重的，吊销生产许可证： （一）不再具备生产条件、生产许可证已经过期或者超出许可范围生产的； （二）明知特种设备存在同一性缺陷，未立即停止生产并召回的。 违反本法规定，特种设备生产单位生产、销售、交付国家明令淘汰的特种设备的，责令停止生产、销售，没收违法生产、销售、交付的特种设备，处三万元以上三十万元以下罚款；有违法所得的，没收违法所得。 特种设备生产单位涂改、倒卖、出租、出借生产许可证的，责令停止生产，处五万元以上五十万元以下罚款；情节严重的，吊销生产许可证。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206081, '《中华人民共和国特种设备安全法》', '第八十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，特种设备经营单位有下列行为之一的，责令停止经营，没收违法经营的特种设备，处三万元以上三十万元以下罚款；有违法所得的，没收违法所得： （一）销售、出租未取得许可生产，未经检验或者检验不合格的特种设备的； （二）销售、出租国家明令淘汰、已经报废的特种设备，或者未按照安全技术规范的要求进行维护保养的特种设备的。 违反本法规定，特种设备销售单位未建立检查验收和销售记录制度，或者进口特种设备未履行提前告知义务的，责令改正，处一万元以上十万元以下罚款。 特种设备生产单位销售、交付未经检验或者检验不合格的特种设备的，依照本条第一款规定处罚；情节严重的，吊销生产许可证。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206082, '《中华人民共和国特种设备安全法》', '第八十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，特种设备使用单位有下列行为之一的，责令限期改正；逾期未改正的，责令停止使用有关特种设备，处一万元以上十万元以下罚款： （一）使用特种设备未按照规定办理使用登记的； （二）未建立特种设备安全技术档案或者安全技术档案不符合规定要求，或者未依法设置使用登记标志、定期检验标志的； （三）未对其使用的特种设备进行经常性维护保养和定期自行检查，或者未对其使用的特种设备的安全附件、安全保护装置进行定期校验、检修，并作出记录的； （四）未按照安全技术规范的要求及时申报并接受检验的； （五）未按照安全技术规范的要求进行锅炉水（介）质处理的； （六）未制定特种设备事故应急专项预案的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206083, '《中华人民共和国特种设备安全法》', '第八十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，特种设备使用单位有下列行为之一的，责令停止使用有关特种设备，处三万元以上三十万元以下罚款： （一）使用未取得许可生产，未经检验或者检验不合格的特种设备，或者国家明令淘汰、已经报废的特种设备的； （二）特种设备出现故障或者发生异常情况，未对其进行全面检查、消除事故隐患，继续使用的； （三）特种设备存在严重事故隐患，无改造、修理价值，或者达到安全技术规范规定的其他报废条件，未依法履行报废义务，并办理使用登记证书注销手续的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206084, '《中华人民共和国特种设备安全法》', '第八十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，移动式压力容器、气瓶充装单位有下列行为之一的，责令改正，处二万元以上二十万元以下罚款；情节严重的，吊销充装许可证： （一）未按照规定实施充装前后的检查、记录制度的； （二）对不符合安全技术规范要求的移动式压力容器和气瓶进行充装的。 违反本法规定，未经许可，擅自从事移动式压力容器或者气瓶充装活动的，予以取缔，没收违法充装的气瓶，处十万元以上五十万元以下罚款；有违法所得的，没收违法所得。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206085, '《中华人民共和国特种设备安全法》', '第八十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，特种设备生产、经营、使用单位有下列情形之一的，责令限期改正；逾期未改正的，责令停止使用有关特种设备或者停产停业整顿，处一万元以上五万元以下罚款： （一）未配备具有相应资格的特种设备安全管理人员、检测人员和作业人员的； （二）使用未取得相应资格的人员从事特种设备安全管理、检测和作业的； （三）未对特种设备安全管理人员、检测人员和作业人员进行安全教育和技能培训的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206086, '《中华人民共和国特种设备安全法》', '第八十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，电梯、客运索道、大型游乐设施的运营使用单位有下列情形之一的，责令限期改正；逾期未改正的，责令停止使用有关特种设备或者停产停业整顿，处二万元以上十万元以下罚款： （一）未设置特种设备安全管理机构或者配备专职的特种设备安全管理人员的； （二）客运索道、大型游乐设施每日投入使用前，未进行试运行和例行安全检查，未对安全附件和安全保护装置进行检查确认的； （三）未将电梯、客运索道、大型游乐设施的安全使用说明、安全注意事项和警示标志置于易于为乘客注意的显著位置的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206087, '《中华人民共和国特种设备安全法》', '第八十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，未经许可，擅自从事电梯维护保养的，责令停止违法行为，处一万元以上十万元以下罚款；有违法所得的，没收违法所得。 电梯的维护保养单位未按照本法规定以及安全技术规范的要求，进行电梯维护保养的，依照前款规定处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206088, '《中华人民共和国特种设备安全法》', '第八十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '发生特种设备事故，有下列情形之一的，对单位处五万元以上二十万元以下罚款；对主要负责人处一万元以上五万元以下罚款；主要负责人属于国家工作人员的，并依法给予处分： （一）发生特种设备事故时，不立即组织抢救或者在事故调查处理期间擅离职守或者逃匿的； （二）对特种设备事故迟报、谎报或者瞒报的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206089, '《中华人民共和国特种设备安全法》', '第九十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '发生事故，对负有责任的单位除要求其依法承担相应的赔偿等责任外，依照下列规定处以罚款： （一）发生一般事故，处十万元以上二十万元以下罚款； （二）发生较大事故，处二十万元以上五十万元以下罚款； （三）发生重大事故，处五十万元以上二百万元以下罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206090, '《中华人民共和国特种设备安全法》', '第九十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '对事故发生负有责任的单位的主要负责人未依法履行职责或者负有领导责任的，依照下列规定处以罚款；属于国家工作人员的，并依法给予处分： （一）发生一般事故，处上一年年收入百分之三十的罚款； （二）发生较大事故，处上一年年收入百分之四十的罚款； （三）发生重大事故，处上一年年收入百分之六十的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206091, '《中华人民共和国特种设备安全法》', '第九十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，特种设备安全管理人员、检测人员和作业人员不履行岗位职责，违反操作规程和有关安全规章制度，造成事故的，吊销相关人员的资格。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206092, '《中华人民共和国特种设备安全法》', '第九十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，特种设备检验、检测机构及其检验、检测人员有下列行为之一的，责令改正，对机构处五万元以上二十万元以下罚款，对直接负责的主管人员和其他直接责任人员处五千元以上五万元以下罚款；情节严重的，吊销机构资质和有关人员的资格： （一）未经核准或者超出核准范围、使用未取得相应资格的人员从事检验、检测的； （二）未按照安全技术规范的要求进行检验、检测的； （三）出具虚假的检验、检测结果和鉴定结论或者检验、检测结果和鉴定结论严重失实的； （四）发现特种设备存在严重事故隐患，未及时告知相关单位，并立即向负责特种设备安全监督管理的部门报告的； （五）泄露检验、检测过程中知悉的商业秘密的； （六）从事有关特种设备的生产、经营活动的； （七）推荐或者监制、监销特种设备的； （八）利用检验工作故意刁难相关单位的。 违反本法规定，特种设备检验、检测机构的检验、检测人员同时在两个以上检验、检测机构中执业的，处五千元以上五万元以下罚款；情节严重的，吊销其资格。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206093, '《中华人民共和国特种设备安全法》', '第九十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，负责特种设备安全监督管理的部门及其工作人员有下列行为之一的，由上级机关责令改正；对直接负责的主管人员和其他直接责任人员，依法给予处分： （一）未依照法律、行政法规规定的条件、程序实施许可的； （二）发现未经许可擅自从事特种设备的生产、使用或者检验、检测活动不予取缔或者不依法予以处理的； （三）发现特种设备生产单位不再具备本法规定的条件而不吊销其许可证，或者发现特种设备生产、经营、使用违法行为不予查处的； （四）发现特种设备检验、检测机构不再具备本法规定的条件而不撤销其核准，或者对其出具虚假的检验、检测结果和鉴定结论或者检验、检测结果和鉴定结论严重失实的行为不予查处的； （五）发现违反本法规定和安全技术规范要求的行为或者特种设备存在事故隐患，不立即处理的； （六）发现重大违法行为或者特种设备存在严重事故隐患，未及时向上级负责特种设备安全监督管理的部门报告，或者接到报告的负责特种设备安全监督管理的部门不立即处理的； （七）要求已经依照本法规定在其他地方取得许可的特种设备生产单位重复取得许可，或者要求对已经依照本法规定在其他地方检验合格的特种设备重复进行检验的； （八）推荐或者监制、监销特种设备的； （九）泄露履行职责过程中知悉的商业秘密的； （十）接到特种设备事故报告未立即向本级人民政府报告，并按照规定上报的； （十一）迟报、漏报、谎报或者瞒报事故的； （十二）妨碍事故救援或者事故调查处理的； （十三）其他滥用职权、玩忽职守、徇私舞弊的行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206094, '《中华人民共和国特种设备安全法》', '第九十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，特种设备生产、经营、使用单位或者检验、检测机构拒不接受负责特种设备安全监督管理的部门依法实施的监督检查的，责令限期改正；逾期未改正的，责令停产停业整顿，处二万元以上二十万元以下罚款。 特种设备生产、经营、使用单位擅自动用、调换、转移、损毁被查封、扣押的特种设备或者其主要部件的，责令改正，处五万元以上二十万元以下罚款；情节严重的，吊销生产许可证，注销特种设备使用登记证书。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206095, '《中华人民共和国特种设备安全法》', '第九十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，被依法吊销许可证的，自吊销许可证之日起三年内，负责特种设备安全监督管理的部门不予受理其新的许可申请。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206096, '《中华人民共和国特种设备安全法》', '第九十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，造成人身、财产损害的，依法承担民事责任。 违反本法规定，应当承担民事赔偿责任和缴纳罚款、罚金，其财产不足以同时支付时，先承担民事赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206097, '《中华人民共和国特种设备安全法》', '第九十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第六章 法律责任', NULL, '违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206098, '《中华人民共和国特种设备安全法》', '第九十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第七章 附 则', NULL, '特种设备行政许可、检验的收费，依照法律、行政法规的规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206099, '《中华人民共和国特种设备安全法》', '第一百条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第七章 附 则', NULL, '军事装备、核设施、航空航天器使用的特种设备安全的监督管理不适用本法。 铁路机车、海上设施和船舶、矿山井下使用的特种设备以及民用机场专用设备安全的监督管理，房屋建筑工地、市政工程工地用起重机械和场（厂）内专用机动车辆的安装、使用的监督管理，由有关部门依照本法和其他有关法律的规定实施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (206100, '《中华人民共和国特种设备安全法》', '第一百零一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2013-06-29', '第七章 附 则', NULL, '本法自2014年1月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207000, '《中华人民共和国危险化学品安全法》', '第一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第一章 总 则', NULL, '为了加强危险化学品的安全管理，预防和减少危险化学品事故，保障人民群众身体健康、生命安全和财产安全，保护生态环境，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207001, '《中华人民共和国危险化学品安全法》', '第二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第一章 总 则', NULL, '危险化学品生产、储存、使用、经营和运输的安全管理，适用本法。 废弃危险化学品的处置，依照有关生态环境保护的法律、行政法规和国家有关规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207002, '《中华人民共和国危险化学品安全法》', '第三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第一章 总 则', NULL, '本法所称危险化学品，是指具有毒害、腐蚀、爆炸、燃烧、助燃等性质，对人体、设施、生态环境具有危害的剧毒化学品和其他化学品。 国家建立健全危险化学品目录管理制度。危险化学品目录，由国务院应急管理部门会同工业和信息化、公安、生态环境、交通运输、农业农村、卫生健康、海关、市场监督管理、铁路、民用航空等部门，根据化学品危险特性的鉴定和分类标准确定、公布，并适时调整。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207003, '《中华人民共和国危险化学品安全法》', '第四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第一章 总 则', NULL, '危险化学品安全管理工作坚持中国共产党的领导。 危险化学品安全管理工作应当坚持人民至上、生命至上，贯彻总体国家安全观，统筹发展和安全，坚持安全第一、预防为主、综合治理的方针，从源头上防范化解重大安全风险。 危险化学品安全管理工作实行管行业必须管安全、管业务必须管安全、管生产经营必须管安全，强化和落实单位主体责任与政府监管责任，建立单位负责、职工参与、政府监管、行业自律、社会监督的机制。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207004, '《中华人民共和国危险化学品安全法》', '第五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第一章 总 则', NULL, '生产、储存、使用、经营、运输危险化学品的企业、学校、科研机构、医疗机构、检测机构、检验机构等单位（以下统称危险化学品单位）应当实行全员安全生产责任制，构建安全风险分级管控和隐患排查治理双重预防机制，加强安全生产标准化、信息化建设，其主要负责人对本单位的危险化学品安全生产工作全面负责。 危险化学品单位应当具备法律、行政法规规定和国家标准、行业标准要求的安全条件，建立健全安全管理规章制度和岗位安全责任制度，对从业人员进行安全生产教育和培训，为从业人员提供符合国家标准或者行业标准的劳动防护用品，依法参加工伤保险。从业人员应当接受教育和培训，考核合格后上岗作业；对有资格要求的岗位，应当配备依法取得相应资格的人员。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207005, '《中华人民共和国危险化学品安全法》', '第六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第一章 总 则', NULL, '任何单位和个人不得生产、使用、经营国家禁止生产、使用、经营的危险化学品。 国家对危险化学品的使用有限制性规定的，任何单位和个人不得违反限制性规定使用危险化学品。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207006, '《中华人民共和国危险化学品安全法》', '第七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第一章 总 则', NULL, '对危险化学品的生产、储存、使用、经营、运输实施安全监督管理的有关部门（以下统称负有危险化学品安全监督管理职责的部门），依照下列规定履行职责： （一）应急管理部门负责危险化学品安全生产监督管理工作和危险化学品安全监督管理综合工作，组织确定、公布、调整危险化学品目录，依法对新建、改建、扩建生产、储存危险化学品（包括使用长输管道输送危险化学品，下同）的建设项目（以下统称危险化学品建设项目）进行安全条件审查和安全设施设计审查，核发危险化学品安全生产许可证、危险化学品安全使用许可证和危险化学品经营许可证，并负责危险化学品登记工作，组织危险化学品事故应急处置。 （二）公安机关负责危险化学品的公共安全管理，核发剧毒化学品购买许可证、剧毒化学品道路运输通行证，负责运输危险化学品的车辆进入危险化学品运输车辆限制通行区域的许可，并负责危险化学品运输车辆的道路交通安全管理。 （三）市场监督管理部门负责对纳入工业产品生产许可证管理目录的危险化学品及其包装物、容器（包括罐体，不包括储存危险化学品的固定式大型储罐，下同）实施工业产品生产许可证管理和产品质量监督，签发危险化学品生产、储存、经营、运输企业营业执照。 （四）生态环境主管部门负责废弃危险化学品处置的监督管理，组织危险化学品的生态环境危害性鉴定和生态环境风险程度评估，负责新化学物质环境管理登记，依照职责分工调查相关危险化学品环境污染事故和生态破坏事件，负责危险化学品事故现场的生态环境应急监测。 （五）交通运输主管部门负责危险化学品道路、水路运输活动安全监督管理，负责危险化学品道路运输、水路运输的许可或者备案，以及运输工具的安全监督管理，负责危险化学品道路运输企业、水路运输企业驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员的资格认定。铁路监管部门负责危险化学品铁路运输及其运输工具的安全监督管理。民用航空主管部门负责危险化学品航空运输以及航空运输企业及其运输工具的安全监督管理。邮政管理部门负责依法查处寄递危险化学品的行为。 （六）卫生健康主管部门负责危险化学品毒性鉴定的管理，负责危险化学品单位职业健康的监督管理，负责组织、协调危险化学品事故受伤人员的医疗卫生救援工作。 （七）自然资源主管部门负责在编制国土空间规划时，将危险化学品建设项目及化工园区、储存危险化学品的专门区域和周边安全控制距离等有关内容按照程序纳入当地国土空间规划，并做好规划监督实施。 （八）工业和信息化主管部门依照职责负责危险化学品生产、储存的相关行业规划和布局，组织制定化工园区的建设标准和认定管理办法，并推动落后工艺、产能退出。 （九）海关负责依法对进出口危险化学品及其包装实施检验。 （十）其他部门依照各自职责履行危险化学品安全监督管理职责。 对因涉及新兴行业、领域，危险化学品安全监督管理职责不明确的，由县级以上人民政府按照业务相近的原则及时确定监督管理部门。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207007, '《中华人民共和国危险化学品安全法》', '第八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第一章 总 则', NULL, '负有危险化学品安全监督管理职责的部门依法进行监督检查，可以采取下列措施： （一）进入危险化学品作业场所实施现场检查，向有关单位和人员了解情况，查阅、复制有关文件、资料，必要时可以对危险化学品实施抽样检测； （二）运用信息化手段对危险化学品单位的重大危险源开展在线巡查抽查； （三）发现危险化学品事故隐患，责令立即消除或者限期消除； （四）对不符合法律、行政法规、规章规定或者国家标准、行业标准要求的设施、设备、装置、器材、运输工具等，责令立即停止使用； （五）经本部门主要负责人批准，查封违法生产、储存、使用、经营危险化学品的场所，扣押违法生产、储存、使用、经营、运输的危险化学品以及用于违法生产、使用、运输危险化学品的原材料、设备、运输工具； （六）发现影响危险化学品安全的违法行为，当场予以纠正或者责令限期改正。 负有危险化学品安全监督管理职责的部门依法进行监督检查，监督检查人员不得少于二人，并应当出示执法证件；有关单位和个人对依法进行的监督检查应当予以配合，不得拒绝、阻挠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207008, '《中华人民共和国危险化学品安全法》', '第九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第一章 总 则', NULL, '县级以上人民政府应当建立危险化学品安全监督管理工作协调机制，支持、督促负有危险化学品安全监督管理职责的部门依法履行职责，协调、解决危险化学品安全监督管理工作中的重大问题。 负有危险化学品安全监督管理职责的部门应当加强监管协作和联合执法，密切协调配合，实现信息及时、充分、有效共享，依法加强对危险化学品的安全监督管理。发现依法应当由其他部门处理的违法行为，及时移交其他部门处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207009, '《中华人民共和国危险化学品安全法》', '第十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第一章 总 则', NULL, '任何单位和个人对违反本法规定的行为或者事故隐患，有权向负有危险化学品安全监督管理职责的部门举报或者报告。县级以上人民政府及其有关部门对举报违法行为或者报告重大事故隐患的有功人员依法给予奖励，并对举报人、报告人的信息进行严格保密。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207010, '《中华人民共和国危险化学品安全法》', '第十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第一章 总 则', NULL, '县级以上人民政府负有危险化学品安全监督管理职责的部门应当加强危险化学品信息化监管，对危险化学品实行电子标识和全生命周期信息化管理和监控。 化工园区应当明确负责安全生产监督管理的有关工作机构及其职责，加强危险化学品信息化建设，实现信息化安全监测、监控和预警，并与政府有关部门实现互联互通。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207011, '《中华人民共和国危险化学品安全法》', '第十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第一章 总 则', NULL, '国家鼓励危险化学品单位采用有利于提高安全保障水平的先进技术、工艺、设备以及自动控制系统，鼓励对危险化学品实行专门储存、统一配送、集中销售。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207012, '《中华人民共和国危险化学品安全法》', '第十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第一章 总 则', NULL, '生产、储存、使用、经营危险化学品的单位应当按照国家有关规定对危险化学品重大危险源登记建档，进行定期检测、评估、监控，制定应急预案，建立重大危险源安全责任制，并将重大危险源的储存数量、储存地点、管理人员的情况及有关安全措施、应急措施报所在地县级人民政府应急管理部门、消防救援机构和有关部门备案；在港区内储存的，报港口行政管理部门、消防救援机构和有关部门备案。 负有危险化学品安全监督管理职责的部门应当分级分类定期对危险化学品重大危险源开展专项监督检查，督促危险化学品单位及时消除事故隐患，防范重特大事故发生。 本法所称重大危险源，是指长期或者临时生产、储存、使用和经营危险化学品，且危险化学品的数量等于或者超过临界量的单元（包括场所和设施）。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207013, '《中华人民共和国危险化学品安全法》', '第十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第一章 总 则', NULL, '各级人民政府及其有关部门应当采取多种形式，加强危险化学品安全法律法规和危险化学品安全知识宣传普及工作，促进全社会危险化学品安全意识的提升。 化工园区、危险化学品单位应当对周边群众和其他生产经营单位进行危险化学品安全法律法规和危险化学品安全知识宣传。 新闻媒体应当开展危险化学品安全法律法规和危险化学品安全知识公益宣传，对危险化学品安全违法行为进行舆论监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207014, '《中华人民共和国危险化学品安全法》', '第十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第一章 总 则', NULL, '对在危险化学品安全工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207015, '《中华人民共和国危险化学品安全法》', '第十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第二章 规划布局', NULL, '国家对危险化学品的生产、储存实行统筹规划、合理布局。 国务院工业和信息化主管部门以及国务院其他有关部门依照各自职责，负责危险化学品生产、储存的行业规划和布局。 地方人民政府组织编制国土空间规划时，应当根据本地区的实际情况，按照确保安全的原则，规划适当区域（包括化工园区）专门用于危险化学品的生产、储存。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207016, '《中华人民共和国危险化学品安全法》', '第十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第二章 规划布局', NULL, '化工园区应当由省、自治区、直辖市人民政府或者其授权的部门认定公布并定期复核。 省、自治区、直辖市人民政府应当合理建设化工园区，组织开展化工园区的安全风险等级评估、论证，建立并落实管控措施。 化工园区应当对进出园区的所有危险化学品实行动态监管，对园区内企业、重点场所、重大危险源、基础设施实施风险监测预警。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207017, '《中华人民共和国危险化学品安全法》', '第十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第二章 规划布局', NULL, '新建、扩建危险化学品生产建设项目应当进入化工园区，与其他行业生产装置配套建设的项目和符合国家规定的其他项目除外。 除为化工企业提供配套服务的企业外，非化工企业禁止进入化工园区。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207018, '《中华人民共和国危险化学品安全法》', '第十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第二章 规划布局', NULL, '化工园区应当至少每三年开展一次整体性安全风险评估，提出消除、降低、管控安全风险的对策措施并有效实施。 当化工园区及危险化学品品种、数量、布局等发生变化，按照国家有关规定需要调整化工园区风险控制条件时，应当及时组织重新开展化工园区整体性安全风险评估，并修订相关应急预案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207019, '《中华人民共和国危险化学品安全法》', '第二十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第二章 规划布局', NULL, '化工园区与城市建成区、人员密集场所、重要设施、敏感目标等应当保持符合相关法律、法规规定和国家标准要求的安全距离。 化工园区应当依照相关法律、法规规定和国家标准要求，拟定化工园区周边规划安全控制线，并报送化工园区所在地设区的市级人民政府或者其授权的部门确定后，按照程序纳入当地国土空间规划。 化工园区所在地设区的市级和县级人民政府自然资源主管部门应当严格控制化工园区周边规划安全控制线内的土地开发利用，规划安全控制线范围内的建设项目应当满足安全风险控制要求。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207020, '《中华人民共和国危险化学品安全法》', '第二十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第二章 规划布局', NULL, '县级以上地方人民政府应当加强危险化学品运输安全保障，对涉及危险化学品储存、装卸、运输的物流园区、集中停车区域，以及高速公路服务区的加油站、加气站等进行规划。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207021, '《中华人民共和国危险化学品安全法》', '第二十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第二章 规划布局', NULL, '危险化学品生产装置或者储存数量构成重大危险源的危险化学品储存设施，与下列场所、设施、区域的安全距离应当符合国家有关规定： （一）居住区以及商业中心、公园等人员密集场所； （二）学校、医院、影剧院、体育场馆等公共设施； （三）饮用水水源、水厂以及饮用水水源保护区； （四）车站、码头（依法经许可从事危险化学品装卸作业的除外）、机场以及通信干线、通信枢纽、铁路线路、道路交通干线、水路交通干线、地铁风亭以及地铁站出入口； （五）生态保护红线、自然保护地、永久基本农田、基本草原、种质资源库（场、区、圃）、畜禽规模化养殖场、渔业水域以及种子、种畜禽、水产苗种生产基地； （六）河流、湖泊、水库、海洋、重要调水输水线路、蓄滞洪区； （七）军事禁区、军事管理区以及有关军事设施； （八）核设施； （九）法律、行政法规规定的其他场所、设施、区域。 已建的危险化学品生产装置或者储存数量构成重大危险源的危险化学品储存设施不符合前款规定的，由所在地设区的市级人民政府应急管理部门会同有关部门监督其所属单位在规定期限内进行整改；需要转产、停产、搬迁、关闭的，由本级人民政府决定并组织实施。 储存数量构成重大危险源的危险化学品储存设施的选址，应当避开地震活动断层和容易发生洪灾、地质灾害、森林草原火灾的区域。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207022, '《中华人民共和国危险化学品安全法》', '第二十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '危险化学品建设项目应当由应急管理部门进行安全条件审查。 建设单位应当委托具备国家规定的资质条件的机构对危险化学品建设项目进行安全评价，并将安全评价情况报建设项目所在地设区的市级以上人民政府应急管理部门；应急管理部门应当自收到报告之日起二十个工作日内作出安全条件审查决定，并书面通知建设单位。具体办法由国务院应急管理部门制定。 新建、改建、扩建储存、装卸危险化学品的港口建设项目（以下统称危险化学品港口建设项目），由港口行政管理部门按照国务院交通运输主管部门的规定进行安全条件审查。 承担安全评价等职责的机构的资质条件由国务院应急管理部门会同有关部门规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207023, '《中华人民共和国危险化学品安全法》', '第二十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '危险化学品建设项目和危险化学品港口建设项目的安全设施，必须与主体工程同时设计、同时施工、同时投入生产和使用。安全设施投资应当纳入建设项目概算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207024, '《中华人民共和国危险化学品安全法》', '第二十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '危险化学品建设项目和危险化学品港口建设项目安全设施的设计人、设计单位应当对安全设施设计负责。在安全设施设计中应当提出保障安全的措施建议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207025, '《中华人民共和国危险化学品安全法》', '第二十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '危险化学品建设项目的安全设施设计应当报所在地设区的市级以上人民政府应急管理部门审查。具体办法由国务院应急管理部门制定。 危险化学品港口建设项目的安全设施设计，由港口行政管理部门按照国家有关规定进行审查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207026, '《中华人民共和国危险化学品安全法》', '第二十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '施工单位必须按照批准的安全设施设计施工，并对安全设施的工程质量和施工安全负责。实行工程监理的危险化学品建设项目，建设单位应当对安全设施施工一并委托监理。 建设单位应当组织对安全设施进行验收，验收合格方可投入生产和使用。 对危险化学品建设项目和危险化学品港口建设项目负有安全生产监督管理职责的部门应当加强对建设单位验收活动和验收结果的监督核查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207027, '《中华人民共和国危险化学品安全法》', '第二十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '生产、储存危险化学品的单位在公共区域埋地、地面和架空的危险化学品输送管道及其附属设施的安全管理，应当符合法律、行政法规的规定和国家标准、行业标准的要求。 生产、储存危险化学品的单位，应当对其敷设的危险化学品管道设置明显标志，并对危险化学品管道定期检查、检测、巡护。 进行可能危及危险化学品管道安全的施工作业，施工单位应当在开工的七日前将施工方案书面通知管道所属单位，并与管道所属单位共同制定应急预案，采取相应的安全防护措施。管道所属单位应当指派专门人员到现场进行管道安全保护指导。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207028, '《中华人民共和国危险化学品安全法》', '第二十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '危险化学品生产企业主要负责人（包括法定代表人、实际控制人、实际负责人）和安全生产管理人员应当具备相应的安全生产知识和管理能力，并经应急管理部门考核合格。 危险化学品生产企业从业人员应当满足国家规定的学历要求，接受安全生产教育和培训，考核合格后上岗作业。 危险化学品生产企业应当建立健全安全培训管理制度，定期组织培训，提高从业人员安全意识和安全生产技能水平。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207029, '《中华人民共和国危险化学品安全法》', '第三十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '危险化学品生产企业进行生产前，应当依照有关安全生产许可法律、行政法规的规定，取得危险化学品安全生产许可证。 生产列入国家实行生产许可证制度的工业产品目录的危险化学品的企业，还应当依照有关工业产品生产许可法律、行政法规的规定，取得工业产品生产许可证。试生产的危险化学品，在取得工业产品生产许可证后，经具有相应资质的检验机构检验合格可以销售。 负责颁发危险化学品安全生产许可证、工业产品生产许可证的部门，应当将其颁发许可证的情况依照有关法律、行政法规的规定及时向社会公开。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207030, '《中华人民共和国危险化学品安全法》', '第三十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '危险化学品生产企业、进口企业应当提供与其生产、进口的危险化学品相符的中文化学品安全技术说明书，并在危险化学品包装（包括外包装件，下同）上粘贴、印刷或者拴挂与包装内危险化学品相符的中文化学品安全标签。化学品安全技术说明书和化学品安全标签应当符合国家标准的要求。 危险化学品生产企业、进口企业发现其生产或者进口的危险化学品有新的危险特性的，应当立即公告，及时修订其化学品安全技术说明书和化学品安全标签。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207031, '《中华人民共和国危险化学品安全法》', '第三十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '危险化学品的包装应当符合法律、行政法规、规章的规定和国家标准、行业标准的要求。 危险化学品包装物、容器的材质以及危险化学品包装的型式、规格、方法和单件质量，应当与所包装的危险化学品的性质和用途相适应。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207032, '《中华人民共和国危险化学品安全法》', '第三十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '生产列入国家实行生产许可证制度的工业产品目录的危险化学品包装物、容器的企业，应当依照有关工业产品生产许可法律、行政法规的规定，取得工业产品生产许可证；其生产的危险化学品包装物、容器经具有相应资质的检验机构检验合格，方可出厂销售。 运输危险化学品的船舶及其配载的容器，应当符合有关法律、行政法规、规章以及强制性标准和技术规范的要求，并经国家海事管理机构认定的船舶检验机构检验合格，方可投入使用。 对重复使用的危险化学品包装物、容器，使用单位在重复使用前应当进行检查；发现存在安全隐患的，应当及时维修或者更换。使用单位应当对检查情况作出记录，记录的保存期限不得少于三年。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207033, '《中华人民共和国危险化学品安全法》', '第三十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '生产、储存危险化学品的企业应当建立安全风险分级管控制度，开展安全风险辨识评估，按照安全风险分级采取相应的管控措施。 生产、储存危险化学品的企业的工艺、设施、设备、原料等发生变更时应当重新进行安全风险辨识评估。 生产、储存危险化学品的企业不得使用国家明令淘汰或者禁止使用的危及生产安全的工艺、技术、设施、设备，具体目录由国务院应急管理部门会同有关部门制定并公布。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207034, '《中华人民共和国危险化学品安全法》', '第三十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '生产、储存危险化学品的企业应当建立包括工艺操作、特殊作业、设备管理、储存条件、开停车和检维修、变更等全部生产作业环节在内的过程安全管理制度，明确责任人、岗位职责和操作规程，并组织有效实施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207035, '《中华人民共和国危险化学品安全法》', '第三十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '生产、储存危险化学品的企业应当按照国家标准或者行业标准装备自动控制系统和安全仪表系统，建立安全风险监测预警系统，并与政府有关部门实现互联互通。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207036, '《中华人民共和国危险化学品安全法》', '第三十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '生产、储存危险化学品的单位，应当根据其生产、储存的危险化学品的种类和危险特性，在作业场所设置相应的监测、监控、通风、防晒、调温、防火、灭火、防爆、泄压、防毒、中和、防潮、防雷、防静电、防腐、防泄漏以及防护围堤或者隔离操作等安全设施、设备，并按照国家标准、行业标准或者国家有关规定对安全设施、设备进行经常性维护、保养，保证安全设施、设备的正常使用。 生产、储存危险化学品的单位，应当在其作业场所和安全设施、设备上设置明显的安全警示标志。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207037, '《中华人民共和国危险化学品安全法》', '第三十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '生产、储存危险化学品的单位，应当在其作业场所设置通信、报警装置，并保证处于适用状态。 生产、储存危险化学品的单位，不得关闭、破坏直接关系生产安全的监控、报警、防护、救生设施、设备，或者以其他任何方式影响其正常使用，不得篡改、隐瞒、销毁其相关数据、信息。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207038, '《中华人民共和国危险化学品安全法》', '第三十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '生产、储存危险化学品的企业，应当委托具备国家规定的资质条件的机构，对本企业的安全生产条件每三年进行一次安全评价，提出安全评价报告。安全评价报告的内容应当包括对安全生产条件存在的问题进行整改的方案和整改完成后的结论性意见。安全评价报告应当按照规定向社会公开。 生产、储存危险化学品的企业，应当将安全评价报告以及整改方案的落实情况报所在地县级人民政府应急管理部门备案。 在港区内储存、装卸危险化学品的企业，应当依照本条第一款要求进行安全评价，安全评价报告以及整改方案的落实情况按照规定报港口行政管理部门或者所在地县级人民政府应急管理部门备案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207039, '《中华人民共和国危险化学品安全法》', '第四十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '生产、储存剧毒化学品或者国务院公安部门规定的可用于制造爆炸物品的危险化学品（以下简称易制爆危险化学品）的单位，应当如实记录其生产、储存的剧毒化学品、易制爆危险化学品的品种、数量、流向，并采取必要的安全防范措施，防止剧毒化学品、易制爆危险化学品丢失或者被盗；发现剧毒化学品、易制爆危险化学品丢失或者被盗的，应当立即向当地公安机关报告；公安机关应当根据实际情况及时通报应急管理等有关部门。 生产、储存剧毒化学品、易制爆危险化学品的单位，应当设置治安保卫机构，配备专职治安保卫人员，并依法报公安机关备案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207040, '《中华人民共和国危险化学品安全法》', '第四十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '危险化学品应当储存在专用仓库、专用场地或者专用储存室、储存专柜（以下统称专用储存场所）内，并由专人负责管理；剧毒化学品以及储存数量构成重大危险源的其他危险化学品，应当在专用储存场所内单独存放，实行双人收发、双人保管制度，收发记录的保存期限不得少于三年。 危险化学品的储存方式、方法以及储存数量应当符合国家标准或者国家有关规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207041, '《中华人民共和国危险化学品安全法》', '第四十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '储存危险化学品的单位应当建立危险化学品出入库核查、登记制度。 剧毒化学品储存单位应当将剧毒化学品的储存数量、储存地点以及管理人员的情况，报所在地县级人民政府应急管理部门、消防救援机构和公安机关备案；在港区内储存的，报港口行政管理部门、消防救援机构和公安机关备案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207042, '《中华人民共和国危险化学品安全法》', '第四十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '危险化学品专用储存场所应当符合国家标准、行业标准的要求，并设置明显的标志。储存剧毒化学品、易制爆危险化学品的专用储存场所，应当按照国家有关规定设置相应的实体防范、技术防范设施。 储存危险化学品的单位应当对其危险化学品专用储存场所的安全设施、设备定期进行检测、检验；检测、检验不合格的，应当停止使用，并按照规定予以维修或者更换。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207043, '《中华人民共和国危险化学品安全法》', '第四十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '研制开发单位进行危险化学品新工艺、新技术、新产品开发，应当加强研制开发过程的安全管理，确保研制开发过程安全，不得将未经小试、中试、工业化试验的新工艺、新技术直接用于工业化生产。 研制开发单位转让危险化学品新工艺、新技术时，应当提供新工艺、新技术的安全论证报告及相关资料，并进行技术指导。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207044, '《中华人民共和国危险化学品安全法》', '第四十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第三章 生产和储存安全', NULL, '生产、储存危险化学品的单位整体或者部分转产、停产、停业、解散的，应当采取有效措施，及时、妥善处置其危险化学品生产装置、储存设施以及库存的危险化学品，不得丢弃危险化学品；处置方案应当报所在地县级人民政府应急管理、工业和信息化、生态环境部门和公安机关、消防救援机构备案。应急管理部门应当会同生态环境主管部门和公安机关、消防救援机构对处置情况进行监督检查，发现未按照规定处置的，应当责令其立即处置。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207045, '《中华人民共和国危险化学品安全法》', '第四十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第四章 使用安全', NULL, '县级以上人民政府有关部门应当依照职责分工，加强对企业、学校、科研机构、医疗机构、检测机构、检验机构等单位使用危险化学品的监督管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207046, '《中华人民共和国危险化学品安全法》', '第四十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第四章 使用安全', NULL, '使用危险化学品的单位的使用条件（包括工艺）应当符合法律、行政法规的规定和国家标准、行业标准的要求，并根据所使用的危险化学品的种类、危险特性以及使用量和使用方式，建立健全使用危险化学品的安全管理规章制度和安全操作规程，保证危险化学品的安全使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207047, '《中华人民共和国危险化学品安全法》', '第四十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第四章 使用安全', NULL, '使用国家规定种类的危险化学品从事生产并且使用量达到规定数量的化工企业（属于危险化学品生产企业的除外，下同），应当依照本法的规定取得危险化学品安全使用许可证。 前款规定的危险化学品种类及其使用量的数量标准，由国务院应急管理部门会同公安、农业农村部门确定并公布。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207048, '《中华人民共和国危险化学品安全法》', '第四十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第四章 使用安全', NULL, '申请危险化学品安全使用许可证的化工企业，除应当符合本法第四十七条的规定外，还应当具备下列条件： （一）有与所使用的危险化学品相适应的专业技术人员，从业人员经考核合格； （二）有安全生产管理机构和专职安全生产管理人员； （三）有符合国家规定的危险化学品事故应急预案和必要的应急救援器材、装备、设备和物资； （四）依法进行了安全评价； （五）法律、法规规定的其他条件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207049, '《中华人民共和国危险化学品安全法》', '第五十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第四章 使用安全', NULL, '申请危险化学品安全使用许可证的化工企业，应当向所在地设区的市级人民政府应急管理部门提出申请，并提交其符合本法第四十九条规定条件的证明材料。设区的市级人民政府应急管理部门应当依法进行审查，自收到证明材料之日起二十个工作日内作出批准或者不予批准的决定。予以批准的，颁发危险化学品安全使用许可证；不予批准的，书面通知申请人并说明理由。 设区的市级人民政府应急管理部门应当将其颁发危险化学品安全使用许可证的情况依照有关法律、行政法规的规定及时向社会公开。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207050, '《中华人民共和国危险化学品安全法》', '第五十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第四章 使用安全', NULL, '使用危险化学品的单位应当将其作业场所使用的化学品安全技术说明书和化学品安全标签提供给从业人员，并加强培训教育，告知从业人员正确使用的方法和在紧急情况下应当采取的措施。 使用危险化学品的个人，应当了解危险化学品的危险特性、正确使用方法和防护措施，不得违法使用、储存、处置危险化学品。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207051, '《中华人民共和国危险化学品安全法》', '第五十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第四章 使用安全', NULL, '本法第三十七条、第三十八条、第四十条第一款、第四十五条关于生产、储存危险化学品的单位的规定，适用于使用危险化学品的单位；第三十四条、第三十五条、第三十六条、第三十九条关于生产、储存危险化学品的企业的规定，适用于使用危险化学品从事生产的企业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207052, '《中华人民共和国危险化学品安全法》', '第五十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第五章 经营安全', NULL, '国家对危险化学品经营（包括仓储经营，下同）实行许可制度。未经许可，任何单位和个人不得经营危险化学品。危险化学品经营企业不得向未经许可从事危险化学品生产、经营活动的企业采购危险化学品。 依法设立的危险化学品生产企业在其厂区范围内销售本企业生产的危险化学品，不需要取得危险化学品经营许可。 依照《中华人民共和国港口法》的规定取得港口经营许可证的港口经营人，在港区内从事危险化学品仓储经营，不需要取得危险化学品经营许可。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207053, '《中华人民共和国危险化学品安全法》', '第五十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第五章 经营安全', NULL, '从事危险化学品经营的企业应当具备下列条件： （一）有符合国家标准、行业标准的经营场所，储存危险化学品的，还应当有符合国家标准、行业标准的储存设施； （二）从业人员经过专业技术培训并经考核合格； （三）有健全的安全管理规章制度； （四）有专职安全生产管理人员，主要负责人和安全生产管理人员具备与本企业危险化学品经营活动相适应的安全生产知识和管理能力，经应急管理部门考核合格； （五）有符合国家规定的危险化学品事故应急预案和必要的应急救援器材、装备、设备和物资； （六）法律、法规规定的其他条件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207054, '《中华人民共和国危险化学品安全法》', '第五十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第五章 经营安全', NULL, '从事剧毒化学品、易制爆危险化学品经营的企业，应当向所在地设区的市级人民政府应急管理部门提出申请。从事其他危险化学品经营的企业，应当向所在地县级人民政府应急管理部门提出申请；有储存设施且储存数量构成重大危险源的，应当向所在地设区的市级人民政府应急管理部门提出申请。申请人应当提交其符合本法第五十四条规定条件的证明材料。设区的市级人民政府应急管理部门或者县级人民政府应急管理部门应当依法进行审查，并按照规定对申请人的经营场所、储存设施进行现场核查。自收到证明材料之日起二十个工作日内作出批准或者不予批准的决定。予以批准的，颁发危险化学品经营许可证；不予批准的，书面通知申请人并说明理由。 设区的市级人民政府应急管理部门和县级人民政府应急管理部门应当将其颁发危险化学品经营许可证的情况依照有关法律、行政法规的规定及时向社会公开。 申请人持危险化学品经营许可证向市场监督管理部门办理登记手续后，方可从事危险化学品经营活动。法律、行政法规或者国务院规定经营危险化学品还需要经其他有关部门许可的，申请人向市场监督管理部门办理登记手续时应当持相应的许可证件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207055, '《中华人民共和国危险化学品安全法》', '第五十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第五章 经营安全', NULL, '危险化学品经营企业储存危险化学品的，应当遵守本法第三章关于储存危险化学品的规定。危险化学品商店内只能存放民用小包装的危险化学品。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207056, '《中华人民共和国危险化学品安全法》', '第五十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第五章 经营安全', NULL, '危险化学品生产企业、经营企业在销售危险化学品时，应当向购买单位或者个人提供符合法律、行政法规规定和国家标准、行业标准要求的化学品安全技术说明书，不得经营没有化学品安全技术说明书或者化学品安全标签的危险化学品，不得擅自更改化学品安全技术说明书或者化学品安全标签。 任何单位和个人购买危险化学品时，有权向危险化学品生产企业、经营企业索取有关危险化学品的安全技术说明书，了解其危险特性、防护措施和使用方法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207057, '《中华人民共和国危险化学品安全法》', '第五十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第五章 经营安全', NULL, '依法取得危险化学品安全生产许可证、危险化学品安全使用许可证或者危险化学品经营许可证的企业，凭相应的许可证件购买剧毒化学品、易制爆危险化学品。民用爆炸物品、烟花爆竹、武器装备科研生产企业凭相应许可证购买易制爆危险化学品。 前款规定以外的单位购买剧毒化学品的，应当向所在地县级人民政府公安机关申请取得剧毒化学品购买许可证；购买易制爆危险化学品的，应当持本单位出具的合法用途说明。 个人不得购买剧毒化学品（属于剧毒化学品的农药除外）和易制爆危险化学品（含有易制爆危险化学品的食品添加剂、药品、兽药、消毒剂等生活用品除外）。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207058, '《中华人民共和国危险化学品安全法》', '第五十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第五章 经营安全', NULL, '申请取得剧毒化学品购买许可证，申请人应当向所在地县级人民政府公安机关提交下列材料： （一）营业执照或者法人证书（登记证书）的复印件； （二）拟购买的剧毒化学品品种、数量的说明； （三）购买剧毒化学品用途的说明； （四）经办人的身份证明。 县级人民政府公安机关应当自收到前款规定的材料之日起三个工作日内，作出批准或者不予批准的决定。予以批准的，颁发剧毒化学品购买许可证；不予批准的，书面通知申请人并说明理由。 剧毒化学品购买许可管理按照国务院公安部门的规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207059, '《中华人民共和国危险化学品安全法》', '第六十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第五章 经营安全', NULL, '危险化学品生产企业、经营企业销售剧毒化学品、易制爆危险化学品，应当查验本法第五十八条第一款、第二款规定的相关许可证件或者证明文件，不得向不具有相关许可证件或者证明文件的单位销售剧毒化学品、易制爆危险化学品。对持剧毒化学品购买许可证购买剧毒化学品的，应当按照许可证载明的品种、数量销售。 禁止向个人销售剧毒化学品（属于剧毒化学品的农药除外）和易制爆危险化学品（含有易制爆危险化学品的食品添加剂、药品、兽药、消毒剂等生活用品除外）。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207060, '《中华人民共和国危险化学品安全法》', '第六十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第五章 经营安全', NULL, '危险化学品生产企业、经营企业销售剧毒化学品、易制爆危险化学品，应当如实记录购买单位的名称、地址，经办人的姓名、身份证号码以及所购买的剧毒化学品、易制爆危险化学品的品种、数量、用途。销售记录以及经办人的身份证明复印件、相关许可证件复印件或者证明文件的保存期限不得少于三年。 剧毒化学品、易制爆危险化学品的销售企业、购买单位应当在销售、购买后三日内，将所销售、购买的剧毒化学品、易制爆危险化学品的品种、数量以及流向信息报所在地县级人民政府公安机关备案，并录入计算机系统。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207061, '《中华人民共和国危险化学品安全法》', '第六十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第五章 经营安全', NULL, '使用剧毒化学品、易制爆危险化学品的单位不得出借、转让其购买的剧毒化学品、易制爆危险化学品；因转产、停产、搬迁、关闭等确需转让的，应当向具有本法第五十八条第一款、第二款规定的相关许可证件或者证明文件的单位转让，并在转让后三日内将所转让的剧毒化学品、易制爆危险化学品品种、数量以及流向信息报所在地县级人民政府公安机关备案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207062, '《中华人民共和国危险化学品安全法》', '第六十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第五章 经营安全', NULL, '禁止在互联网上销售、购买剧毒化学品、易制爆危险化学品。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207063, '《中华人民共和国危险化学品安全法》', '第六十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '通过道路、水路运输按照危险货物管理的危险化学品，应当遵守本法和有关法律、行政法规、国务院交通运输主管部门关于危险货物道路、水路运输安全的规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207064, '《中华人民共和国危险化学品安全法》', '第六十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '从事危险化学品道路运输、水路运输的，应当向市场监督管理部门办理登记手续，并分别依照有关道路运输、水路运输的法律、行政法规的规定，取得危险货物道路运输许可、相应危险货物水路运输许可或者办理备案手续。 通过道路、水路运输危险化学品，应当由依法取得相应许可或者办理备案手续的运输企业承运，其他单位和个人不得承运。托运人应当委托依法取得相应许可或者办理备案手续的运输企业承运，不得委托其他单位和个人承运。其他单位和个人的危险化学品运输车辆不得挂靠经营。 危险化学品道路运输企业、水路运输企业应当配备专职安全生产管理人员。 经妥善处理后可以按照普通货物管理的危险化学品按照普通货物运输，具体办法由国务院交通运输主管部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207065, '《中华人民共和国危险化学品安全法》', '第六十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '危险化学品道路运输企业、水路运输企业的驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员应当经交通运输主管部门考核合格，取得从业资格。具体办法由国务院交通运输主管部门制定。 危险化学品的装卸作业应当遵守安全作业标准、规程和制度，并在装卸管理人员的现场指挥或者监控下进行。水路运输危险化学品的集装箱装箱作业应当在集装箱装箱现场检查员的指挥或者监控下进行，并符合积载、隔离的规范和要求；装箱作业完毕后，集装箱装箱现场检查员应当签署装箱证明书。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207066, '《中华人民共和国危险化学品安全法》', '第六十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '运输危险化学品，应当根据危险化学品的危险特性采取相应的安全防护措施，并配备必要的防护用品和应急救援器材、装备、设备和物资。 用于运输危险化学品的槽罐以及其他容器应当封口严密，能够防止危险化学品在运输过程中因温度、湿度或者压力的变化发生渗漏、洒漏；槽罐以及其他容器的溢流和泄压装置应当设置准确、启闭灵活。 运输危险化学品，驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员应当熟悉所运输的危险化学品的危险特性及其包装物、容器的使用要求，掌握出现危险情况时的应急处置方法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207067, '《中华人民共和国危险化学品安全法》', '第六十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '通过道路运输危险化学品，应当按照运输车辆的核定载质量装载危险化学品，不得超载。 危险化学品运输车辆应当符合国家标准要求的安全技术条件，并按照国家有关规定定期进行安全技术检验。 危险化学品运输车辆应当悬挂或者喷涂符合国家标准要求的警示标志，不得遮挡、拆除。 危险化学品运输车辆应当安装符合国家标准、行业标准要求的卫星定位监控装置并确保处于良好运行状态，不得拆除、关闭或者采取屏蔽信号等方式影响其正常运行，不得删除、篡改监控数据。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207068, '《中华人民共和国危险化学品安全法》', '第六十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '通过道路运输危险化学品，应当按照要求配备押运人员，并保证所运输的危险化学品处于押运人员的监控之下。具体办法由国务院交通运输主管部门会同有关部门制定。 危险化学品道路运输企业应当对运输车辆、驾驶人员的作业状态进行实时监控、管理，及时纠正超速行驶、疲劳驾驶、不按规定线路行驶等违法违规驾驶行为，实现安全监测、监控和预警。运输危险化学品车辆的驾驶人员应当严格遵守道路交通安全法律法规，日间连续驾驶时间不得超过四小时，夜间连续驾驶时间不得超过二小时，每次停车休息时间不少于二十分钟。 运输危险化学品途中需要停车的，驾驶人员、押运人员应当采取相应的安全防范措施；运输剧毒化学品或者易制爆危险化学品因住宿或者发生影响正常运输的情况，需要较长时间停车的，还应当向当地公安机关报告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207069, '《中华人民共和国危险化学品安全法》', '第七十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '未经公安机关批准，运输危险化学品的车辆不得进入危险化学品运输车辆限制通行的区域。危险化学品运输车辆限制通行的区域由县级人民政府公安机关划定或者会同有关部门划定，并设置明显的标志。 运输危险化学品的车辆进入危险化学品运输车辆限制通行区域许可管理按照国务院公安部门的规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207070, '《中华人民共和国危险化学品安全法》', '第七十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '通过道路运输剧毒化学品，托运人应当向运输始发地或者目的地县级人民政府公安机关申请剧毒化学品道路运输通行证。 申请剧毒化学品道路运输通行证，托运人应当向县级人民政府公安机关提交下列材料： （一）拟运输的剧毒化学品品种、数量的说明； （二）运输始发地、目的地、运输时间和运输路线的说明； （三）承运人取得相应危险货物道路运输许可、运输车辆取得相应营运证以及驾驶人员、押运人员取得相应上岗资格的证明文件； （四）本法第五十八条第一款、第二款规定的购买剧毒化学品的相关许可证件，或者海关出具的进出口证明文件。 县级人民政府公安机关应当自收到前款规定的材料之日起七个工作日内，作出批准或者不予批准的决定。予以批准的，颁发剧毒化学品道路运输通行证；不予批准的，书面通知申请人并说明理由。 剧毒化学品道路运输通行证管理按照国务院公安部门的规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207071, '《中华人民共和国危险化学品安全法》', '第七十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '剧毒化学品、易制爆危险化学品在道路运输途中丢失、被盗、被抢或者出现流散、泄漏等情况的，驾驶人员、押运人员应当立即采取相应的警示措施和安全措施，并向当地公安机关报告。公安机关接到报告后，应当根据实际情况立即向交通运输、应急管理、生态环境、卫生健康部门通报。有关部门应当采取必要的应急处置措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207072, '《中华人民共和国危险化学品安全法》', '第七十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '海事管理机构应当根据危险化学品的种类和危险特性，确定船舶运输危险化学品的安全运输条件。 拟交付船舶运输的化学品的安全运输条件不明确的，货物所有人或者代理人应当委托相关技术机构进行评估，明确相关安全运输条件并经海事管理机构确认后，方可交付船舶运输。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207073, '《中华人民共和国危险化学品安全法》', '第七十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '禁止通过内河封闭水域运输剧毒化学品。 禁止通过内河水域运输国家规定禁止通过内河运输的危险化学品。禁止通过内河运输的危险化学品的范围，由国务院交通运输主管部门会同生态环境、应急管理、工业和信息化部门，根据危险化学品的危险特性、危险化学品对人体和水环境的危害程度以及消除危害后果的难易程度等因素规定并公布。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207074, '《中华人民共和国危险化学品安全法》', '第七十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '国务院交通运输主管部门应当根据危险化学品的危险特性，对通过内河运输本法第七十四条规定以外的危险化学品（以下简称通过内河运输危险化学品）实行分类管理，对各类危险化学品的运输方式、包装规范和安全防护措施等分别作出规定并监督实施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207075, '《中华人民共和国危险化学品安全法》', '第七十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '通过内河运输危险化学品，应当使用依法取得危险货物适装证书的运输船舶。水路运输企业应当针对所运输的危险化学品的危险特性，制定运输船舶危险化学品事故应急救援预案，并为运输船舶配备充足、有效的应急救援器材、装备、设备和物资。 通过内河运输危险化学品的船舶，其所有人或者经营人应当取得船舶污染损害责任保险证书或者财务担保证明。船舶污染损害责任保险证书或者财务担保证明的副本应当随船携带。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207076, '《中华人民共和国危险化学品安全法》', '第七十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '通过内河运输危险化学品，危险化学品包装物的材质、型式、强度以及包装方法应当符合水路运输相关包装规范的要求。国务院交通运输主管部门对单船运输的危险化学品数量有限制性规定的，承运人应当按照规定安排运输数量。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207077, '《中华人民共和国危险化学品安全法》', '第七十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '用于危险化学品运输作业的内河码头、泊位应当符合国家有关安全规范，与饮用水取水口保持国家规定的安全距离。有关管理单位应当制定码头、泊位危险化学品事故应急预案，并为码头、泊位配备充足、有效的应急救援器材、装备、设备和物资。 用于危险化学品运输作业的内河码头、泊位，按照国家有关规定验收合格后方可投入使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207078, '《中华人民共和国危险化学品安全法》', '第七十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '船舶载运危险化学品进出内河港口，应当依照法律、行政法规的规定向海事管理机构报告。海事管理机构接到报告后，应当在国务院交通运输主管部门规定的时间内作出是否同意的决定，通知报告人，同时通报港口行政管理部门。 在内河港口内进行危险化学品的装卸、过驳作业，应当将危险化学品的名称、危险特性、包装和作业的时间、地点等事项报告港口行政管理部门。港口行政管理部门接到报告后，应当在国务院交通运输主管部门规定的时间内作出是否同意的决定，通知报告人，同时通报海事管理机构。 载运危险化学品的船舶在内河航行，通过通航建筑物的，应当符合通航建筑物安全管理有关要求，并提前向通航建筑物运行单位报告。运行单位应当及时转报交通运输主管部门。载运危险化学品的船舶通过通航建筑物时，应当接受交通运输主管部门的管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207079, '《中华人民共和国危险化学品安全法》', '第八十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '载运危险化学品的船舶在内河航行、装卸或者停泊，应当悬挂专用的警示标志，按照规定显示专用信号。 载运危险化学品的船舶在内河航行，依照法律、行政法规以及国务院交通运输主管部门的规定需要引航的，应当申请引航。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207080, '《中华人民共和国危险化学品安全法》', '第八十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '载运危险化学品的船舶在内河航行，应当遵守法律、行政法规和国家其他有关饮用水水源和自然保护地保护的规定。内河航道发展规划应当与依法经批准的饮用水水源保护区划定方案和自然保护地总体规划相协调。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207081, '《中华人民共和国危险化学品安全法》', '第八十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '托运危险化学品，托运人应当向承运人提交电子或者纸质的危险货物托运清单，说明所托运的危险化学品的种类、数量、危险特性以及发生危险情况的应急处置措施，提供化学品安全技术说明书，并按照国家有关规定对所托运的危险化学品妥善包装，在危险化学品包装上粘贴、印刷或者拴挂与包装内危险化学品相符的化学品安全标签，并保证随时可查。 运输危险化学品需要添加抑制剂或者稳定剂的，托运人应当按照规定添加，并将有关情况告知承运人。 装货人应当在充装或者装载危险化学品前履行查验责任，并按照标准要求进行充装、装载作业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207082, '《中华人民共和国危险化学品安全法》', '第八十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '托运人不得在托运的普通货物中夹带危险化学品，不得将危险化学品匿报或者谎报为普通货物托运。 任何单位和个人不得交寄危险化学品或者在邮件、快件内夹带危险化学品，不得将危险化学品匿报或者谎报为普通物品交寄。邮政企业、快递企业不得收寄危险化学品。 对涉嫌违反本条第一款、第二款规定的，交通运输主管部门、邮政管理部门可以依法开拆，并通过取样检验等多种方式开展查验。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207083, '《中华人民共和国危险化学品安全法》', '第八十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第六章 运输安全', NULL, '通过铁路、航空运输危险化学品的安全管理，依照有关铁路、航空运输的法律、行政法规、规章的规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207084, '《中华人民共和国危险化学品安全法》', '第八十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第七章 危险化学品登记', NULL, '国家实行危险化学品登记制度，为危险化学品安全管理以及危险化学品事故预防和应急救援提供技术、信息支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207085, '《中华人民共和国危险化学品安全法》', '第八十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第七章 危险化学品登记', NULL, '危险化学品生产企业、进口企业应当向国务院应急管理部门负责危险化学品登记的机构（以下简称危险化学品登记机构）办理危险化学品登记。 危险化学品登记包括下列内容： （一）分类和标签信息； （二）物理、化学性质； （三）主要用途； （四）危险特性； （五）储存、使用、运输的安全要求； （六）出现危险情况的应急处置措施。 对同一企业生产、进口的同一品种的危险化学品，不进行重复登记。危险化学品生产企业、进口企业发现其生产、进口的危险化学品有新的危险特性或者其他登记内容发生变更的，应当及时向危险化学品登记机构办理登记内容变更手续。 危险化学品登记的具体办法由国务院应急管理部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207086, '《中华人民共和国危险化学品安全法》', '第八十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第七章 危险化学品登记', NULL, '国家对研究开发、试产试销过程中的低量低释放、低暴露的危险化学品等免予登记。免予登记的具体办法由国务院应急管理部门会同工业和信息化、公安、生态环境、农业农村、卫生健康、海关等部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207087, '《中华人民共和国危险化学品安全法》', '第八十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第七章 危险化学品登记', NULL, '危险化学品登记机构应当将危险化学品登记信息数据与工业和信息化、公安、自然资源、生态环境、交通运输、农业农村、卫生健康、海关、市场监督管理、能源、军事机关等单位共享。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207088, '《中华人民共和国危险化学品安全法》', '第八十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第七章 危险化学品登记', NULL, '新化学物质环境管理登记，依照有关生态环境保护的法律、行政法规、规章的规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207089, '《中华人民共和国危险化学品安全法》', '第九十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第八章 事故应急救援', NULL, '县级以上地方人民政府应急管理部门应当会同工业和信息化、公安、生态环境、交通运输、卫生健康、市场监督管理等部门，根据本地区实际情况，制定危险化学品事故应急预案，报本级人民政府批准，并依法向社会公布。 负有危险化学品安全监督管理职责的部门在制定本部门应急预案时应当包含危险化学品事故应急处置的内容。 中国人民解放军、中国人民武装警察部队按照中央军事委员会的命令，依法参加危险化学品事故应急救援工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207090, '《中华人民共和国危险化学品安全法》', '第九十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第八章 事故应急救援', NULL, '危险化学品单位应当做好应急准备工作，健全应急管理制度，制定本单位危险化学品事故应急预案，依法建立专职或者兼职应急救援队伍，配备必要的应急救援器材、装备、设备和物资，并定期组织应急救援演练，提高从业人员的应急处置能力。生产经营规模较小的，可以不建立应急救援队伍，但应当指定兼职的应急救援人员，并可以与邻近的应急救援队伍签订应急救援协议。 危险化学品单位应当将其危险化学品事故应急预案按照国家有关规定报送县级以上人民政府应急管理部门备案，并依法向社会公布。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207091, '《中华人民共和国危险化学品安全法》', '第九十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第八章 事故应急救援', NULL, '县级以上地方人民政府根据生产安全事故应急工作的实际需要，加强化工园区危险化学品专业应急救援力量建设，可以依托有条件的生产经营单位、社会组织共同建立危险化学品专业应急救援队伍，配备必要的应急救援器材、装备、设备和物资，并定期组织训练。 化工园区内的危险化学品单位，可以联合建立应急救援队伍。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207092, '《中华人民共和国危险化学品安全法》', '第九十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第八章 事故应急救援', NULL, '发生危险化学品事故，事故单位主要负责人应当立即按照本单位危险化学品事故应急预案组织救援，并向当地应急管理、生态环境、公安、卫生健康、市场监督管理部门报告，及时通知可能受影响的单位和人员；道路运输、水路运输过程中发生危险化学品事故的，驾驶人员、船员或者押运人员还应当向事故发生地交通运输主管部门报告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207093, '《中华人民共和国危险化学品安全法》', '第九十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第八章 事故应急救援', NULL, '危险化学品单位发生直接危及人身安全的紧急情况时，在确保安全的前提下，作业现场带班人员、班组长、调度人员有权立即下达停产撤人命令，指挥有关遇险人员撤离。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207094, '《中华人民共和国危险化学品安全法》', '第九十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第八章 事故应急救援', NULL, '发生危险化学品事故，有关地方人民政府应当立即组织应急管理、生态环境、公安、卫生健康、交通运输等有关部门，按照本地区危险化学品事故应急预案组织实施救援，不得拖延、推诿。 有关地方人民政府及其有关部门应当按照下列规定，采取必要的应急处置措施，减少事故损失，防止事故蔓延、扩大： （一）立即组织营救和救治受害人员，转移、疏散、撤离并妥善安置受到威胁的其他人员或者采取其他保护措施； （二）迅速控制危害源，测定危险化学品的性质，评估事故的危害区域及危害程度； （三）针对事故对人体、动植物、土壤、水源、水体、大气造成的现实危害和可能产生的危害，迅速采取封闭、隔离、洗消等措施； （四）对危险化学品事故造成的环境污染和生态破坏状况进行监测、评估，并采取相应的环境污染治理和生态修复措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207095, '《中华人民共和国危险化学品安全法》', '第九十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第八章 事故应急救援', NULL, '有关危险化学品单位应当为危险化学品事故应急救援提供技术指导和必要的协助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207096, '《中华人民共和国危险化学品安全法》', '第九十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第八章 事故应急救援', NULL, '危险化学品事故造成环境污染和生态破坏的，由履行统一领导职责的人民政府统一发布有关信息。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207097, '《中华人民共和国危险化学品安全法》', '第九十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '生产、使用、经营国家禁止生产、使用、经营的危险化学品的，由应急管理部门责令停止生产、使用、经营活动，有违法所得的，没收违法所得，并没收违法生产、使用、经营的危险化学品以及用于违法生产、使用、经营的工具、设备、原料等；违法生产、使用、经营的危险化学品货值金额不足十万元的，并处三十万元以上五十万元以下的罚款；货值金额十万元以上的，并处货值金额五倍以上十倍以下的罚款。 有前款规定行为的，应急管理部门还应当责令其对所生产、使用、经营的危险化学品进行无害化处理。 违反国家关于危险化学品使用的限制性规定使用危险化学品的，依照本条第一款的规定处理、处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207098, '《中华人民共和国危险化学品安全法》', '第九十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '有下列情形之一的，由负有危险化学品安全监督管理职责的部门按照职责分工责令停止建设或者停产停业整顿，限期改正，并处十万元以上五十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款；逾期未改正的，处五十万元以上一百万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款： （一）危险化学品建设项目未经安全条件审查； （二）危险化学品建设项目没有安全设施设计或者安全设施设计未报有关应急管理部门审查同意； （三）施工单位未按照批准的安全设施设计施工； （四）实行工程监理的危险化学品建设项目，建设单位未对安全设施施工一并委托监理； （五）危险化学品建设项目竣工投入生产或者使用前，安全设施未经验收合格。 危险化学品港口建设项目有前款规定情形的，由港口行政管理部门依照前款规定予以处理、处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207099, '《中华人民共和国危险化学品安全法》', '第一百条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '未依法取得危险化学品安全生产许可证从事危险化学品生产，或者未依法取得工业产品生产许可证从事危险化学品及其包装物、容器生产的，分别依照有关安全生产许可、工业产品生产许可法律、行政法规的规定处理、处罚。 违反本法规定，化工企业未取得危险化学品安全使用许可证，使用危险化学品从事生产的，由应急管理部门责令限期改正，处十万元以上五十万元以下的罚款；逾期不改正的，责令停产整顿。 违反本法规定，未取得危险化学品经营许可证从事危险化学品经营的，由应急管理部门责令停止经营活动，没收违法经营的危险化学品以及违法所得，并处十万元以上五十万元以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207100, '《中华人民共和国危险化学品安全法》', '第一百零一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '有下列情形之一的，由负有危险化学品安全监督管理职责的部门按照职责分工责令限期改正，可以处十万元以下的罚款；逾期未改正的，处十万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款；情节严重的，责令停产停业整顿： （一）危险化学品生产企业、进口企业未提供中文化学品安全技术说明书，或者未在危险化学品包装上粘贴、印刷、拴挂中文化学品安全标签； （二）危险化学品生产企业、进口企业提供的中文化学品安全技术说明书与其生产、进口的危险化学品不相符，在危险化学品包装上粘贴、印刷、拴挂的中文化学品安全标签与包装内危险化学品不相符，或者化学品安全技术说明书、化学品安全标签不符合国家标准要求； （三）危险化学品生产企业、进口企业发现其生产或者进口的危险化学品有新的危险特性不立即公告，或者不及时修订其化学品安全技术说明书、化学品安全标签； （四）生产、储存危险化学品的单位未对其敷设的危险化学品管道设置明显标志，或者未对危险化学品管道定期检查、检测、巡护； （五）进行可能危及危险化学品管道安全的施工作业，施工单位未按照规定将施工方案书面通知管道所属单位，未与管道所属单位共同制定应急预案、采取相应的安全防护措施，或者管道所属单位未指派专门人员到现场进行管道安全保护指导； （六）危险化学品生产企业从业人员未满足国家规定的学历要求，未接受安全生产教育和培训，或者未经考核合格上岗作业； （七）危险化学品包装物、容器的材质以及包装的型式、规格、方法和单件质量与所包装的危险化学品的性质和用途不相适应； （八）生产、储存危险化学品的企业以及使用危险化学品从事生产的企业未明确责任人、岗位职责和操作规程； （九）生产、储存危险化学品的企业以及使用危险化学品从事生产的企业未按照规定装备自动控制系统和安全仪表系统，未建立安全风险监测预警系统，或者安全风险监测预警系统未与政府有关部门实现互联互通； （十）生产、储存、使用危险化学品的单位未在作业场所和安全设施、设备上设置明显的安全警示标志，或者未在作业场所设置通信、报警装置并处于适用状态； （十一）危险化学品专用储存场所未设专人负责管理，对储存的剧毒化学品以及储存数量构成重大危险源的其他危险化学品未实行双人收发、双人保管制度，或者收发记录的保存期限少于三年； （十二）储存危险化学品的单位未建立危险化学品出入库核查、登记制度； （十三）危险化学品专用储存场所未设置明显标志； （十四）研制开发单位将未经小试、中试、工业化试验的新工艺、新技术直接用于工业化生产，或者转让危险化学品新工艺、新技术时，未提供新工艺、新技术的安全论证报告及相关资料； （十五）使用危险化学品的单位未将其作业场所使用的化学品安全技术说明书、化学品安全标签提供给从业人员，或者未告知从业人员正确使用的方法、在紧急情况下应当采取的措施； （十六）危险化学品生产企业、经营企业经营没有化学品安全技术说明书、化学品安全标签的危险化学品，或者擅自更改化学品安全技术说明书、化学品安全标签； （十七）危险化学品生产企业、进口企业不办理危险化学品登记，或者发现其生产、进口的危险化学品有新的危险特性、其他登记内容发生变更，不办理危险化学品登记内容变更手续。 从事危险化学品仓储经营的港口经营人有前款规定情形的，由港口行政管理部门依照前款规定予以处理、处罚。储存剧毒化学品、易制爆危险化学品的专用储存场所未按照国家有关规定设置相应的实体防范、技术防范设施的，由公安机关依照前款规定予以处理、处罚。 生产、储存剧毒化学品、易制爆危险化学品的单位未设置治安保卫机构、配备专职治安保卫人员的，依照有关企业事业单位内部治安保卫法律、行政法规的规定处理、处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207101, '《中华人民共和国危险化学品安全法》', '第一百零二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '危险化学品包装物、容器生产企业销售未经检验或者经检验不合格的危险化学品包装物、容器的，由市场监督管理部门责令限期改正，处二十万元以上五十万元以下的罚款，有违法所得的，没收违法所得；逾期不改正的，责令停产停业整顿，对其直接负责的主管人员和其他直接责任人员处一万元以上五万元以下的罚款。 将未经检验合格的运输危险化学品的船舶及其配载的容器投入使用的，由海事管理机构依照前款规定予以处理、处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207102, '《中华人民共和国危险化学品安全法》', '第一百零三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '有下列情形之一的，由负有危险化学品安全监督管理职责的部门按照职责分工责令限期改正，处五万元以上十万元以下的罚款；逾期不改正的，责令停产停业整顿直至由原发证机关吊销其相关许可证件，并处十万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款；相关许可证件被吊销的，由市场监督管理部门责令其办理经营范围变更登记或者吊销其营业执照： （一）未按照国家有关规定对危险化学品重大危险源登记建档，未进行定期检测、评估、监控，未制定应急预案，或者未建立重大危险源安全责任制； （二）对重复使用的危险化学品包装物、容器，在重复使用前不进行检查，或者使用存在安全隐患的危险化学品包装物、容器； （三）未根据其生产、储存的危险化学品的种类和危险特性，在作业场所设置相关安全设施、设备，或者未按照国家标准、行业标准或者国家有关规定对安全设施、设备进行经常性维护、保养； （四）未依照本法规定对其安全生产条件定期进行安全评价； （五）未将危险化学品储存在专用储存场所内，或者未将剧毒化学品以及储存数量构成重大危险源的其他危险化学品在专用储存场所内单独存放； （六）危险化学品的储存方式、方法或者储存数量不符合国家标准或者国家有关规定； （七）危险化学品专用储存场所不符合国家标准、行业标准的要求； （八）未对危险化学品专用储存场所的安全设施、设备定期进行检测、检验，或者经检测、检验不合格，没有停止使用并按照规定予以维修或者更换； （九）生产、储存危险化学品的企业以及使用危险化学品从事生产的企业未建立安全风险分级管控制度，未开展安全风险辨识评估，未按照安全风险分级采取相应安全管控措施，或者工艺、设施、设备、原料等发生变更时未重新进行安全风险辨识评估。 从事危险化学品仓储经营的港口经营人有前款规定情形的，由港口行政管理部门依照前款规定予以处理、处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207103, '《中华人民共和国危险化学品安全法》', '第一百零四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '有下列情形之一的，由公安机关责令限期改正，可以处二万元以上十万元以下的罚款；逾期不改正的，处十万元以上二十万元以下的罚款，对直接负责的主管人员和其他直接责任人员处一万元以上五万元以下的罚款： （一）生产、储存、使用剧毒化学品、易制爆危险化学品的单位不如实记录其生产、储存、使用的剧毒化学品、易制爆危险化学品的品种、数量、流向； （二）生产、储存、使用剧毒化学品、易制爆危险化学品的单位发现剧毒化学品、易制爆危险化学品丢失或者被盗，不立即向公安机关报告； （三）储存剧毒化学品的单位未将剧毒化学品的储存数量、储存地点以及管理人员的情况报所在地县级人民政府公安机关备案； （四）危险化学品生产企业、经营企业不如实记录剧毒化学品、易制爆危险化学品购买单位的名称、地址，经办人的姓名、身份证号码以及所购买的剧毒化学品、易制爆危险化学品的品种、数量、用途，或者保存销售记录和相关材料的时间少于三年； （五）剧毒化学品、易制爆危险化学品的销售企业、购买单位未在规定的时限内将所销售、购买的剧毒化学品、易制爆危险化学品的品种、数量以及流向信息报所在地县级人民政府公安机关备案； （六）使用剧毒化学品、易制爆危险化学品的单位依照本法规定转让其购买的剧毒化学品、易制爆危险化学品，未将有关情况在转让后三日内向所在地县级人民政府公安机关备案。 生产、储存危险化学品的企业，使用危险化学品从事生产的企业，或者在港区内储存、装卸危险化学品的企业未依照本法规定将安全评价报告以及整改方案的落实情况报所在地县级人民政府应急管理部门或者港口行政管理部门备案的，分别由应急管理部门或者港口行政管理部门依照前款规定予以处理、处罚。 未依照本法规定将剧毒化学品以及危险化学品重大危险源的情况报应急管理部门、港口行政管理部门或者消防救援机构备案的，分别由应急管理部门、港口行政管理部门或者消防救援机构依照本条第一款的规定予以处理、处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207104, '《中华人民共和国危险化学品安全法》', '第一百零五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '生产、储存、使用危险化学品的单位转产、停产、停业或者解散，未采取有效措施及时、妥善处置其危险化学品生产装置、储存设施以及库存的危险化学品，或者丢弃危险化学品的，由应急管理部门责令限期改正，处十万元以上五十万元以下的罚款。 生产、储存、使用危险化学品的单位转产、停产、停业或者解散，未依照本法规定将其危险化学品生产装置、储存设施以及库存危险化学品的处置方案报有关部门备案的，分别由有关部门责令限期改正，可以处二万元以上十万元以下的罚款；逾期不改正的，处十万元以上二十万元以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207105, '《中华人民共和国危险化学品安全法》', '第一百零六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '危险化学品经营企业向未经许可违法从事危险化学品生产、经营活动的企业采购危险化学品的，由应急管理部门责令限期改正，处二十万元以上五十万元以下的罚款；逾期不改正的，责令停业整顿直至由原发证机关吊销其危险化学品经营许可证，对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；相关许可证件被吊销的，由市场监督管理部门责令其办理经营范围变更登记或者吊销其营业执照。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207106, '《中华人民共和国危险化学品安全法》', '第一百零七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '危险化学品生产企业、经营企业有下列情形之一的，由应急管理部门责令限期改正，没收违法所得，并处二十万元以上五十万元以下的罚款；逾期不改正的，责令停产停业整顿直至由原发证机关吊销其危险化学品安全生产许可证、危险化学品经营许可证，对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；相关许可证件被吊销的，由市场监督管理部门责令其办理经营范围变更登记或者吊销其营业执照： （一）向不具有本法第五十八条第一款、第二款规定的相关许可证件或者证明文件的单位销售剧毒化学品、易制爆危险化学品； （二）不按照剧毒化学品购买许可证载明的品种、数量销售剧毒化学品； （三）向个人销售剧毒化学品（属于剧毒化学品的农药除外）、易制爆危险化学品（含有易制爆危险化学品的食品添加剂、药品、兽药、消毒剂等生活用品除外）。 不具有本法第五十八条第一款、第二款规定的相关许可证件或者证明文件的单位购买剧毒化学品、易制爆危险化学品，或者个人购买剧毒化学品（属于剧毒化学品的农药除外）、易制爆危险化学品（含有易制爆危险化学品的食品添加剂、药品、兽药、消毒剂等生活用品除外）的，由公安机关没收所购买的剧毒化学品、易制爆危险化学品，可以并处二万元以上五万元以下的罚款。 使用剧毒化学品、易制爆危险化学品的单位出借或者向不具有本法第五十八条第一款、第二款规定的相关许可证件或者证明文件的单位转让其购买的剧毒化学品、易制爆危险化学品，或者向个人转让其购买的剧毒化学品（属于剧毒化学品的农药除外）、易制爆危险化学品（含有易制爆危险化学品的食品添加剂、药品、兽药、消毒剂等生活用品除外）的，由公安机关责令限期改正，没收违法所得，并处十万元以上五十万元以下的罚款；逾期不改正的，责令停产停业整顿。 违反本法规定，在互联网上销售剧毒化学品、易制爆危险化学品的，由负有危险化学品安全监督管理职责的部门按照职责分工依照本条第一款的规定予以处理、处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207107, '《中华人民共和国危险化学品安全法》', '第一百零八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '未依法取得危险货物道路运输许可、相应危险货物水路运输许可或者未办理备案手续，从事危险化学品道路运输、水路运输的，分别依照有关道路运输、水路运输的法律、行政法规的规定处理、处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207108, '《中华人民共和国危险化学品安全法》', '第一百零九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '有下列情形之一的，由交通运输主管部门责令限期改正，处五万元以上五十万元以下的罚款；逾期不改正的，责令停产停业整顿，对其直接负责的主管人员和其他直接责任人员处一万元以上五万元以下的罚款： （一）危险化学品道路运输企业、水路运输企业的驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员未取得从业资格上岗作业； （二）危险化学品的装卸作业未遵守安全作业标准、规程和制度，或者未在装卸管理人员的现场指挥或者监控下进行； （三）水路运输危险化学品的集装箱装箱作业未在集装箱装箱现场检查员的指挥或者监控下进行，或者不符合积载、隔离的规范和要求； （四）运输危险化学品，未根据危险化学品的危险特性采取相应的安全防护措施，或者未配备必要的防护用品和应急救援器材、装备、设备和物资； （五）危险化学品道路运输企业未对运输车辆、驾驶人员的作业状态进行实时监控、管理； （六）使用未依法取得危险货物适装证书的船舶，通过内河运输危险化学品； （七）通过内河运输危险化学品的承运人违反国务院交通运输主管部门对单船运输的危险化学品数量的限制性规定运输危险化学品； （八）用于危险化学品运输作业的内河码头、泊位不符合国家有关安全规范，未与饮用水取水口保持国家规定的安全距离，或者未按照国家有关规定验收合格投入使用； （九）托运人未向承运人提交电子或者纸质的危险货物托运清单说明所托运的危险化学品相关情况，未提供化学品安全技术说明书，或者未按照国家有关规定对所托运的危险化学品妥善包装并在危险化学品包装上粘贴、印刷、拴挂与包装内危险化学品相符的化学品安全标签； （十）运输危险化学品需要添加抑制剂或者稳定剂，托运人未按照规定添加或者未将有关情况告知承运人。 水路运输企业的申报人员、集装箱装箱现场检查员违反法律、行政法规或者规章关于危险化学品安全管理规定的，由交通运输主管部门责令限期改正，给予警告；情节严重的，责令暂停从业活动直至吊销其从业资格。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207109, '《中华人民共和国危险化学品安全法》', '第一百一十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '有下列情形之一的，由交通运输主管部门责令限期改正，处二十万元以上三十万元以下的罚款，有违法所得的，没收违法所得；逾期不改正的，责令停产停业整顿，对其直接负责的主管人员和其他直接责任人员处一万元以上五万元以下的罚款： （一）委托未依法取得相应许可或者办理备案手续的单位或者个人承运危险化学品； （二）通过内河封闭水域运输剧毒化学品； （三）通过内河水域运输国家规定禁止通过内河运输的危险化学品； （四）载运危险化学品的船舶在内河航行时通过通航建筑物，未提前向通航建筑物运行单位报告，或者不服从交通运输主管部门管理； （五）在托运的普通货物中夹带危险化学品，或者将危险化学品匿报、谎报为普通货物托运。 邮政企业、快递企业收寄危险化学品的，依照《中华人民共和国邮政法》的规定处理、处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207110, '《中华人民共和国危险化学品安全法》', '第一百一十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '有下列情形之一的，由公安机关责令限期改正，处十万元以上二十万元以下的罚款： （一）超过运输车辆的核定载质量装载危险化学品； （二）使用安全技术条件不符合国家标准要求的车辆运输危险化学品； （三）运输危险化学品的车辆未经公安机关批准进入危险化学品运输车辆限制通行的区域； （四）未取得剧毒化学品道路运输通行证，通过道路运输剧毒化学品。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207111, '《中华人民共和国危险化学品安全法》', '第一百一十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '有下列情形之一的，由公安机关责令限期改正，处五万元以上十万元以下的罚款： （一）危险化学品运输车辆未悬挂、喷涂或者遮挡、拆除警示标志，或者警示标志不符合国家标准要求； （二）通过道路运输危险化学品，不按照要求配备押运人员； （三）运输剧毒化学品或者易制爆危险化学品途中需要较长时间停车，驾驶人员、押运人员不向当地公安机关报告； （四）剧毒化学品、易制爆危险化学品在道路运输途中丢失、被盗、被抢或者出现流散、泄漏等情况，驾驶人员、押运人员不采取相应的警示措施和安全措施，或者不向当地公安机关报告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207112, '《中华人民共和国危险化学品安全法》', '第一百一十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '对发生交通事故负有全部责任或者主要责任的危险化学品道路运输企业，由公安机关责令消除安全隐患，未消除安全隐患的危险化学品运输车辆，禁止上道路行驶。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207113, '《中华人民共和国危险化学品安全法》', '第一百一十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '有下列情形之一的，由交通运输主管部门责令限期改正，可以处五万元以下的罚款；逾期不改正的，处五万元以上十万元以下的罚款： （一）危险化学品道路运输企业、水路运输企业未配备专职安全生产管理人员； （二）用于危险化学品运输作业的内河码头、泊位的管理单位未制定码头、泊位危险化学品事故应急预案，或者未为码头、泊位配备充足、有效的应急救援器材、装备、设备和物资。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207114, '《中华人民共和国危险化学品安全法》', '第一百一十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '有下列情形之一的，依照有关内河交通安全管理法律、行政法规的规定处理、处罚： （一）通过内河运输危险化学品的水路运输企业未制定运输船舶危险化学品事故应急救援预案，或者未为运输船舶配备充足、有效的应急救援器材、装备、设备和物资； （二）通过内河运输危险化学品的船舶的所有人或者经营人未取得船舶污染损害责任保险证书或者财务担保证明； （三）船舶载运危险化学品进出内河港口，未依照法律、行政法规的规定报告海事管理机构并经其同意； （四）载运危险化学品的船舶在内河航行、装卸或者停泊，未悬挂专用的警示标志，未按照规定显示专用信号，或者未按照规定申请引航。 未向港口行政管理部门报告并经其同意，在内河港口内进行危险化学品的装卸、过驳作业的，依照《中华人民共和国港口法》的规定处理、处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207115, '《中华人民共和国危险化学品安全法》', '第一百一十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '伪造、变造或者出租、出借、转让危险化学品安全生产许可证、工业产品生产许可证，或者使用伪造、变造的危险化学品安全生产许可证、工业产品生产许可证的，分别依照有关安全生产许可、工业产品生产许可法律、行政法规的规定处理、处罚。 伪造、变造或者出租、出借、转让本法规定的其他许可证，或者使用伪造、变造的本法规定的其他许可证的，分别由相关许可证的颁发管理机关处二十万元以上三十万元以下的罚款，有违法所得的，没收违法所得。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207116, '《中华人民共和国危险化学品安全法》', '第一百一十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '危险化学品单位发生危险化学品事故，其主要负责人不立即组织救援或者不立即向有关部门报告的，依照有关生产安全事故报告和调查处理法律、行政法规的规定处理、处罚。 危险化学品单位的主要负责人未履行安全生产管理职责，导致发生生产安全事故的，依照《中华人民共和国安全生产法》的规定限制从业。 危险化学品单位发生危险化学品事故，造成他人人身伤害或者财产损失的，依法承担赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207117, '《中华人民共和国危险化学品安全法》', '第一百一十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '发生危险化学品事故，有关地方人民政府及其有关部门不立即组织实施救援，或者不采取必要的应急处置措施减少事故损失，防止事故蔓延、扩大的，对负有责任的领导人员和直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207118, '《中华人民共和国危险化学品安全法》', '第一百一十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '负有危险化学品安全监督管理职责的部门的工作人员，在危险化学品安全监督管理工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207119, '《中华人民共和国危险化学品安全法》', '第一百二十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第九章 法律责任', NULL, '违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207120, '《中华人民共和国危险化学品安全法》', '第一百二十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第十章 附 则', NULL, '监控化学品、属于危险化学品的药品和农药的安全管理，依照本法的规定执行；法律、行政法规另有规定的，依照其规定。 民用爆炸物品、烟花爆竹、放射性物品、核能物质以及用于国防科研生产的危险化学品的安全管理，不适用本法。 法律、行政法规对燃气的安全管理另有规定的，依照其规定。 危险化学品容器属于特种设备的，其安全管理依照有关特种设备安全的法律、行政法规的规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207121, '《中华人民共和国危险化学品安全法》', '第一百二十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第十章 附 则', NULL, '危险化学品的进出口管理，依照有关对外贸易的法律、行政法规、规章的规定执行；出口危险化学品涉及《中华人民共和国出口管制法》规定的管制物项的，依照有关出口管制的法律、行政法规、规章的规定执行；进口的危险化学品的储存、使用、经营、运输的安全管理，依照本法的规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207122, '《中华人民共和国危险化学品安全法》', '第一百二十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第十章 附 则', NULL, '公众发现、捡拾的无主危险化学品，由公安机关或者应急管理部门接收。有关部门接收或者依法没收的危险化学品，需要进行处置的，交由生态环境主管部门组织其认定的专业单位进行处置，或者交由有关危险化学品生产企业进行处置。处置所需费用由政府负担。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207123, '《中华人民共和国危险化学品安全法》', '第一百二十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第十章 附 则', NULL, '化学品的危险特性尚未确定的，由国务院应急管理、生态环境、卫生健康部门分别负责组织对该化学品的物理危险性、生态环境危害性、毒理特性进行鉴定。根据鉴定结果需要调整危险化学品目录的，依照本法第三条第二款的规定办理。 化学品的危险特性尚未确定的，任何单位和个人不得擅自从事该化学品的生产、储存、使用、经营、运输等活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207124, '《中华人民共和国危险化学品安全法》', '第一百二十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第十章 附 则', NULL, '港区内危险化学品生产和使用危险化学品的生产装置及相连储罐部分，由应急管理部门负责安全监督管理；仅与危险化学品码头相连的储罐部分，由港口行政管理部门负责安全监督管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207125, '《中华人民共和国危险化学品安全法》', '第一百二十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第十章 附 则', NULL, '中国人民解放军、中国人民武装警察部队的危险化学品安全管理，依照本法有关规定和中央军事委员会的规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (207126, '《中华人民共和国危险化学品安全法》', '第一百二十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2025-12-27', '第十章 附 则', NULL, '本法自2026年5月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208000, '《中华人民共和国军人保险法》', '第一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第一章 总 则', NULL, '为了规范军人保险关系，维护军人合法权益，促进国防和军队建设，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208001, '《中华人民共和国军人保险法》', '第二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第一章 总 则', NULL, '国家建立军人保险制度。 军人伤亡保险、退役养老保险、退役医疗保险和随军未就业的军人配偶保险的建立、缴费和转移接续等适用本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208002, '《中华人民共和国军人保险法》', '第三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第一章 总 则', NULL, '军人保险制度应当体现军人职业特点，与社会保险制度相衔接，与经济社会发展水平相适应。 国家根据社会保险制度的发展，适时补充完善军人保险制度。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208003, '《中华人民共和国军人保险法》', '第四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第一章 总 则', NULL, '国家促进军人保险事业的发展，为军人保险提供财政拨款和政策支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208004, '《中华人民共和国军人保险法》', '第五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第一章 总 则', NULL, '中国人民解放军军人保险主管部门负责全军的军人保险工作。国务院社会保险行政部门、财政部门和军队其他有关部门在各自职责范围内负责有关的军人保险工作。 军队后勤（联勤）机关财务部门负责承办军人保险登记、个人权益记录、军人保险待遇支付等工作。 军队后勤（联勤）机关财务部门和地方社会保险经办机构，按照各自职责办理军人保险与社会保险关系转移接续手续。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208005, '《中华人民共和国军人保险法》', '第六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第一章 总 则', NULL, '军人依法参加军人保险并享受相应的保险待遇。 军人有权查询、核对个人缴费记录和个人权益记录，要求军队后勤（联勤）机关财务部门和地方社会保险经办机构依法办理养老、医疗等保险关系转移接续手续，提供军人保险和社会保险咨询等相关服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208006, '《中华人民共和国军人保险法》', '第七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第二章 军人伤亡保险', NULL, '军人因战、因公死亡的，按照认定的死亡性质和相应的保险金标准，给付军人死亡保险金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208007, '《中华人民共和国军人保险法》', '第八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第二章 军人伤亡保险', NULL, '军人因战、因公、因病致残的，按照评定的残疾等级和相应的保险金标准，给付军人残疾保险金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208008, '《中华人民共和国军人保险法》', '第九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第二章 军人伤亡保险', NULL, '军人死亡和残疾的性质认定、残疾等级评定和相应的保险金标准，按照国家和军队有关规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208009, '《中华人民共和国军人保险法》', '第十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第二章 军人伤亡保险', NULL, '军人因下列情形之一死亡或者致残的，不享受军人伤亡保险待遇： （一）故意犯罪的； （二）醉酒或者吸毒的； （三）自残或者自杀的； （四）法律、行政法规和军事法规规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208010, '《中华人民共和国军人保险法》', '第十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第二章 军人伤亡保险', NULL, '已经评定残疾等级的因战、因公致残的军人退出现役参加工作后旧伤复发的，依法享受相应的工伤待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208011, '《中华人民共和国军人保险法》', '第十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第二章 军人伤亡保险', NULL, '军人伤亡保险所需资金由国家承担，个人不缴纳保险费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208012, '《中华人民共和国军人保险法》', '第十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第三章 退役养老保险', NULL, '军人退出现役参加基本养老保险的，国家给予退役养老保险补助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208013, '《中华人民共和国军人保险法》', '第十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第三章 退役养老保险', NULL, '军人退役养老保险补助标准，由中国人民解放军总后勤部会同国务院有关部门，按照国家规定的基本养老保险缴费标准、军人工资水平等因素拟订，报国务院、中央军事委员会批准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208014, '《中华人民共和国军人保险法》', '第十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第三章 退役养老保险', NULL, '军人入伍前已经参加基本养老保险的，由地方社会保险经办机构和军队后勤（联勤）机关财务部门办理基本养老保险关系转移接续手续。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208015, '《中华人民共和国军人保险法》', '第十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第三章 退役养老保险', NULL, '军人退出现役后参加职工基本养老保险的，由军队后勤（联勤）机关财务部门将军人退役养老保险关系和相应资金转入地方社会保险经办机构，地方社会保险经办机构办理相应的转移接续手续。 军人服现役年限与入伍前和退出现役后参加职工基本养老保险的缴费年限合并计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208016, '《中华人民共和国军人保险法》', '第十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第三章 退役养老保险', NULL, '军人退出现役后参加新型农村社会养老保险或者城镇居民社会养老保险的，按照国家有关规定办理转移接续手续。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208017, '《中华人民共和国军人保险法》', '第十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第三章 退役养老保险', NULL, '军人退出现役到公务员岗位或者参照公务员法管理的工作人员岗位的，以及现役军官、文职干部退出现役自主择业的，其养老保险办法按照国家有关规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208018, '《中华人民共和国军人保险法》', '第十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第三章 退役养老保险', NULL, '军人退出现役采取退休方式安置的，其养老办法按照国务院和中央军事委员会的有关规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208019, '《中华人民共和国军人保险法》', '第二十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第四章 退役医疗保险', NULL, '参加军人退役医疗保险的军官、文职干部和士官应当缴纳军人退役医疗保险费，国家按照个人缴纳的军人退役医疗保险费的同等数额给予补助。 义务兵和供给制学员不缴纳军人退役医疗保险费，国家按照规定的标准给予军人退役医疗保险补助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208020, '《中华人民共和国军人保险法》', '第二十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第四章 退役医疗保险', NULL, '军人退役医疗保险个人缴费标准和国家补助标准，由中国人民解放军总后勤部会同国务院有关部门，按照国家规定的缴费比例、军人工资水平等因素确定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208021, '《中华人民共和国军人保险法》', '第二十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第四章 退役医疗保险', NULL, '军人入伍前已经参加基本医疗保险的，由地方社会保险经办机构和军队后勤（联勤）机关财务部门办理基本医疗保险关系转移接续手续。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208022, '《中华人民共和国军人保险法》', '第二十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第四章 退役医疗保险', NULL, '军人退出现役后参加职工基本医疗保险的，由军队后勤（联勤）机关财务部门将军人退役医疗保险关系和相应资金转入地方社会保险经办机构，地方社会保险经办机构办理相应的转移接续手续。 军人服现役年限视同职工基本医疗保险缴费年限，与入伍前和退出现役后参加职工基本医疗保险的缴费年限合并计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208023, '《中华人民共和国军人保险法》', '第二十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第四章 退役医疗保险', NULL, '军人退出现役后参加新型农村合作医疗或者城镇居民基本医疗保险的，按照国家有关规定办理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208024, '《中华人民共和国军人保险法》', '第二十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第五章 随军未就业的军人配偶保险', NULL, '国家为随军未就业的军人配偶建立养老保险、医疗保险等。随军未就业的军人配偶参加保险，应当缴纳养老保险费和医疗保险费，国家给予相应的补助。 随军未就业的军人配偶保险个人缴费标准和国家补助标准，按照国家有关规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208025, '《中华人民共和国军人保险法》', '第二十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第五章 随军未就业的军人配偶保险', NULL, '随军未就业的军人配偶随军前已经参加社会保险的，由地方社会保险经办机构和军队后勤（联勤）机关财务部门办理保险关系转移接续手续。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208026, '《中华人民共和国军人保险法》', '第二十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第五章 随军未就业的军人配偶保险', NULL, '随军未就业的军人配偶实现就业或者军人退出现役时，由军队后勤（联勤）机关财务部门将其养老保险、医疗保险关系和相应资金转入地方社会保险经办机构，地方社会保险经办机构办理相应的转移接续手续。 军人配偶在随军未就业期间的养老保险、医疗保险缴费年限与其在地方参加职工基本养老保险、职工基本医疗保险的缴费年限合并计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208027, '《中华人民共和国军人保险法》', '第二十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第五章 随军未就业的军人配偶保险', NULL, '随军未就业的军人配偶达到国家规定的退休年龄时，按照国家有关规定确定退休地，由军队后勤（联勤）机关财务部门将其养老保险关系和相应资金转入退休地社会保险经办机构，享受相应的基本养老保险待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208028, '《中华人民共和国军人保险法》', '第二十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第五章 随军未就业的军人配偶保险', NULL, '地方人民政府和有关部门应当为随军未就业的军人配偶提供就业指导、培训等方面的服务。 随军未就业的军人配偶无正当理由拒不接受当地人民政府就业安置，或者无正当理由拒不接受当地人民政府指定部门、机构介绍的适当工作、提供的就业培训的，停止给予保险缴费补助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208029, '《中华人民共和国军人保险法》', '第三十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第六章 军人保险基金', NULL, '军人保险基金包括军人伤亡保险基金、军人退役养老保险基金、军人退役医疗保险基金和随军未就业的军人配偶保险基金。各项军人保险基金按照军人保险险种分别建账，分账核算，执行军队的会计制度。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208030, '《中华人民共和国军人保险法》', '第三十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第六章 军人保险基金', NULL, '军人保险基金由个人缴费、中央财政负担的军人保险资金以及利息收入等资金构成。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208031, '《中华人民共和国军人保险法》', '第三十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第六章 军人保险基金', NULL, '军人应当缴纳的保险费，由其所在单位代扣代缴。 随军未就业的军人配偶应当缴纳的保险费，由军人所在单位代扣代缴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208032, '《中华人民共和国军人保险法》', '第三十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第六章 军人保险基金', NULL, '中央财政负担的军人保险资金，由国务院财政部门纳入年度国防费预算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208033, '《中华人民共和国军人保险法》', '第三十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第六章 军人保险基金', NULL, '军人保险基金按照国家和军队的预算管理制度，实行预算、决算管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208034, '《中华人民共和国军人保险法》', '第三十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第六章 军人保险基金', NULL, '军人保险基金实行专户存储，具体管理办法按照国家和军队有关规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208035, '《中华人民共和国军人保险法》', '第三十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第六章 军人保险基金', NULL, '军人保险基金由中国人民解放军总后勤部军人保险基金管理机构集中管理。 军人保险基金管理机构应当严格管理军人保险基金，保证基金安全。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208036, '《中华人民共和国军人保险法》', '第三十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第六章 军人保险基金', NULL, '军人保险基金应当专款专用，按照规定的项目、范围和标准支出，任何单位和个人不得贪污、侵占、挪用，不得变更支出项目、扩大支出范围或者改变支出标准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208037, '《中华人民共和国军人保险法》', '第三十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第七章 保险经办与监督', NULL, '军队后勤（联勤）机关财务部门和地方社会保险经办机构应当建立健全军人保险经办管理制度。 军队后勤（联勤）机关财务部门应当按时足额支付军人保险金。 军队后勤（联勤）机关财务部门和地方社会保险经办机构应当及时办理军人保险和社会保险关系转移接续手续。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208038, '《中华人民共和国军人保险法》', '第三十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第七章 保险经办与监督', NULL, '军队后勤（联勤）机关财务部门应当为军人及随军未就业的军人配偶建立保险档案，及时、完整、准确地记录其个人缴费和国家补助，以及享受军人保险待遇等个人权益记录，并定期将个人权益记录单送达本人。 军队后勤（联勤）机关财务部门和地方社会保险经办机构应当为军人及随军未就业的军人配偶提供军人保险和社会保险咨询等相关服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208039, '《中华人民共和国军人保险法》', '第四十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第七章 保险经办与监督', NULL, '军人保险信息系统由中国人民解放军总后勤部负责统一建设。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208040, '《中华人民共和国军人保险法》', '第四十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第七章 保险经办与监督', NULL, '中国人民解放军总后勤部财务部门和中国人民解放军审计机关按照各自职责，对军人保险基金的收支和管理情况实施监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208041, '《中华人民共和国军人保险法》', '第四十二条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第七章 保险经办与监督', NULL, '军队后勤（联勤）机关、地方社会保险行政部门，应当对单位和个人遵守本法的情况进行监督检查。 军队后勤（联勤）机关、地方社会保险行政部门实施监督检查时，被检查单位和个人应当如实提供与军人保险有关的资料，不得拒绝检查或者谎报、瞒报。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208042, '《中华人民共和国军人保险法》', '第四十三条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第七章 保险经办与监督', NULL, '军队后勤（联勤）机关财务部门和地方社会保险经办机构及其工作人员，应当依法为军队单位和军人的信息保密，不得以任何形式泄露。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208043, '《中华人民共和国军人保险法》', '第四十四条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第七章 保险经办与监督', NULL, '任何单位或者个人有权对违反本法规定的行为进行举报、投诉。 军队和地方有关部门、机构对属于职责范围内的举报、投诉，应当依法处理；对不属于本部门、本机构职责范围的，应当书面通知并移交有权处理的部门、机构处理。有权处理的部门、机构应当及时处理，不得推诿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208044, '《中华人民共和国军人保险法》', '第四十五条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第八章 法律责任', NULL, '军队后勤（联勤）机关财务部门、社会保险经办机构，有下列情形之一的，由军队后勤（联勤）机关或者社会保险行政部门责令改正；对直接负责的主管人员和其他直接责任人员依法给予处分；造成损失的，依法承担赔偿责任： （一）不按照规定建立、转移接续军人保险关系的； （二）不按照规定收缴、上缴个人缴纳的保险费的； （三）不按照规定给付军人保险金的； （四）篡改或者丢失个人缴费记录等军人保险档案资料的； （五）泄露军队单位和军人的信息的； （六）违反规定划拨、存储军人保险基金的； （七）有违反法律、法规损害军人保险权益的其他行为的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208045, '《中华人民共和国军人保险法》', '第四十六条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第八章 法律责任', NULL, '贪污、侵占、挪用军人保险基金的，由军队后勤（联勤）机关责令限期退回，对直接负责的主管人员和其他直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208046, '《中华人民共和国军人保险法》', '第四十七条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第八章 法律责任', NULL, '以欺诈、伪造证明材料等手段骗取军人保险待遇的，由军队后勤（联勤）机关和社会保险行政部门责令限期退回，并依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208047, '《中华人民共和国军人保险法》', '第四十八条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第八章 法律责任', NULL, '违反本法规定，构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208048, '《中华人民共和国军人保险法》', '第四十九条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第九章 附 则', NULL, '军人退出现役后参加失业保险的，其服现役年限视同失业保险缴费年限，与入伍前和退出现役后参加失业保险的缴费年限合并计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208049, '《中华人民共和国军人保险法》', '第五十条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第九章 附 则', NULL, '本法关于军人保险权益和义务的规定，适用于人民武装警察；中国人民武装警察部队保险基金管理，按照中国人民武装警察部队资金管理体制执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (208050, '《中华人民共和国军人保险法》', '第五十一条', '劳动', '法律', NULL, '全国人民代表大会常务委员会 2012-04-27', '第九章 附 则', NULL, '本法自2012年7月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209000, '《中华人民共和国妇女权益保障法》', '第一条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第一章 总 则', NULL, '为了保障妇女的合法权益，促进男女平等和妇女全面发展，充分发挥妇女在全面建设社会主义现代化国家中的作用，弘扬社会主义核心价值观，根据宪法，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209001, '《中华人民共和国妇女权益保障法》', '第二条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第一章 总 则', NULL, '男女平等是国家的基本国策。妇女在政治的、经济的、文化的、社会的和家庭的生活等各方面享有同男子平等的权利。 国家采取必要措施，促进男女平等，消除对妇女一切形式的歧视，禁止排斥、限制妇女依法享有和行使各项权益。 国家保护妇女依法享有的特殊权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209002, '《中华人民共和国妇女权益保障法》', '第三条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第一章 总 则', NULL, '坚持中国共产党对妇女权益保障工作的领导，建立政府主导、各方协同、社会参与的保障妇女权益工作机制。 各级人民政府应当重视和加强妇女权益的保障工作。 县级以上人民政府负责妇女儿童工作的机构，负责组织、协调、指导、督促有关部门做好妇女权益的保障工作。 县级以上人民政府有关部门在各自的职责范围内做好妇女权益的保障工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209003, '《中华人民共和国妇女权益保障法》', '第四条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第一章 总 则', NULL, '保障妇女的合法权益是全社会的共同责任。国家机关、社会团体、企业事业单位、基层群众性自治组织以及其他组织和个人，应当依法保障妇女的权益。 国家采取有效措施，为妇女依法行使权利提供必要的条件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209004, '《中华人民共和国妇女权益保障法》', '第五条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第一章 总 则', NULL, '国务院制定和组织实施中国妇女发展纲要，将其纳入国民经济和社会发展规划，保障和促进妇女在各领域的全面发展。 县级以上地方各级人民政府根据中国妇女发展纲要，制定和组织实施本行政区域的妇女发展规划，将其纳入国民经济和社会发展规划。 县级以上人民政府应当将妇女权益保障所需经费列入本级预算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209005, '《中华人民共和国妇女权益保障法》', '第六条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第一章 总 则', NULL, '中华全国妇女联合会和地方各级妇女联合会依照法律和中华全国妇女联合会章程，代表和维护各族各界妇女的利益，做好维护妇女权益、促进男女平等和妇女全面发展的工作。 工会、共产主义青年团、残疾人联合会等群团组织应当在各自的工作范围内，做好维护妇女权益的工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209006, '《中华人民共和国妇女权益保障法》', '第七条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第一章 总 则', NULL, '国家鼓励妇女自尊、自信、自立、自强，运用法律维护自身合法权益。 妇女应当遵守国家法律，尊重社会公德、职业道德和家庭美德，履行法律所规定的义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209007, '《中华人民共和国妇女权益保障法》', '第八条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第一章 总 则', NULL, '有关机关制定或者修改涉及妇女权益的法律、法规、规章和其他规范性文件，应当听取妇女联合会的意见，充分考虑妇女的特殊权益，必要时开展男女平等评估。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209008, '《中华人民共和国妇女权益保障法》', '第九条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第一章 总 则', NULL, '国家建立健全妇女发展状况统计调查制度，完善性别统计监测指标体系，定期开展妇女发展状况和权益保障统计调查和分析，发布有关信息。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209009, '《中华人民共和国妇女权益保障法》', '第十条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第一章 总 则', NULL, '国家将男女平等基本国策纳入国民教育体系，开展宣传教育，增强全社会的男女平等意识，培育尊重和关爱妇女的社会风尚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209010, '《中华人民共和国妇女权益保障法》', '第十一条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第一章 总 则', NULL, '国家对保障妇女合法权益成绩显著的组织和个人，按照有关规定给予表彰和奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209011, '《中华人民共和国妇女权益保障法》', '第十二条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第二章 政治权利', NULL, '国家保障妇女享有与男子平等的政治权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209012, '《中华人民共和国妇女权益保障法》', '第十三条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第二章 政治权利', NULL, '妇女有权通过各种途径和形式，依法参与管理国家事务、管理经济和文化事业、管理社会事务。 妇女和妇女组织有权向各级国家机关提出妇女权益保障方面的意见和建议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209013, '《中华人民共和国妇女权益保障法》', '第十四条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第二章 政治权利', NULL, '妇女享有与男子平等的选举权和被选举权。 全国人民代表大会和地方各级人民代表大会的代表中，应当保证有适当数量的妇女代表。国家采取措施，逐步提高全国人民代表大会和地方各级人民代表大会的妇女代表的比例。 居民委员会、村民委员会成员中，应当保证有适当数量的妇女成员。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209014, '《中华人民共和国妇女权益保障法》', '第十五条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第二章 政治权利', NULL, '国家积极培养和选拔女干部，重视培养和选拔少数民族女干部。 国家机关、群团组织、企业事业单位培养、选拔和任用干部，应当坚持男女平等的原则，并有适当数量的妇女担任领导成员。 妇女联合会及其团体会员，可以向国家机关、群团组织、企业事业单位推荐女干部。 国家采取措施支持女性人才成长。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209015, '《中华人民共和国妇女权益保障法》', '第十六条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第二章 政治权利', NULL, '妇女联合会代表妇女积极参与国家和社会事务的民主协商、民主决策、民主管理和民主监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209016, '《中华人民共和国妇女权益保障法》', '第十七条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第二章 政治权利', NULL, '对于有关妇女权益保障工作的批评或者合理可行的建议，有关部门应当听取和采纳；对于有关侵害妇女权益的申诉、控告和检举，有关部门应当查清事实，负责处理，任何组织和个人不得压制或者打击报复。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209017, '《中华人民共和国妇女权益保障法》', '第十八条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第三章 人身和人格权益', NULL, '国家保障妇女享有与男子平等的人身和人格权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209018, '《中华人民共和国妇女权益保障法》', '第十九条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第三章 人身和人格权益', NULL, '妇女的人身自由不受侵犯。禁止非法拘禁和以其他非法手段剥夺或者限制妇女的人身自由；禁止非法搜查妇女的身体。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209019, '《中华人民共和国妇女权益保障法》', '第二十条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第三章 人身和人格权益', NULL, '妇女的人格尊严不受侵犯。禁止用侮辱、诽谤等方式损害妇女的人格尊严。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209020, '《中华人民共和国妇女权益保障法》', '第二十一条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第三章 人身和人格权益', NULL, '妇女的生命权、身体权、健康权不受侵犯。禁止虐待、遗弃、残害、买卖以及其他侵害女性生命健康权益的行为。 禁止进行非医学需要的胎儿性别鉴定和选择性别的人工终止妊娠。 医疗机构施行生育手术、特殊检查或者特殊治疗时，应当征得妇女本人同意；在妇女与其家属或者关系人意见不一致时，应当尊重妇女本人意愿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209021, '《中华人民共和国妇女权益保障法》', '第二十二条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第三章 人身和人格权益', NULL, '禁止拐卖、绑架妇女；禁止收买被拐卖、绑架的妇女；禁止阻碍解救被拐卖、绑架的妇女。 各级人民政府和公安、民政、人力资源和社会保障、卫生健康等部门及村民委员会、居民委员会按照各自的职责及时发现报告，并采取措施解救被拐卖、绑架的妇女，做好被解救妇女的安置、救助和关爱等工作。妇女联合会协助和配合做好有关工作。任何组织和个人不得歧视被拐卖、绑架的妇女。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209022, '《中华人民共和国妇女权益保障法》', '第二十三条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第三章 人身和人格权益', NULL, '禁止违背妇女意愿，以言语、文字、图像、肢体行为等方式对其实施性骚扰。 受害妇女可以向有关单位和国家机关投诉。接到投诉的有关单位和国家机关应当及时处理，并书面告知处理结果。 受害妇女可以向公安机关报案，也可以向人民法院提起民事诉讼，依法请求行为人承担民事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209023, '《中华人民共和国妇女权益保障法》', '第二十四条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第三章 人身和人格权益', NULL, '学校应当根据女学生的年龄阶段，进行生理卫生、心理健康和自我保护教育，在教育、管理、设施等方面采取措施，提高其防范性侵害、性骚扰的自我保护意识和能力，保障女学生的人身安全和身心健康发展。 学校应当建立有效预防和科学处置性侵害、性骚扰的工作制度。对性侵害、性骚扰女学生的违法犯罪行为，学校不得隐瞒，应当及时通知受害未成年女学生的父母或者其他监护人，向公安机关、教育行政部门报告，并配合相关部门依法处理。 对遭受性侵害、性骚扰的女学生，学校、公安机关、教育行政部门等相关单位和人员应当保护其隐私和个人信息，并提供必要的保护措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209024, '《中华人民共和国妇女权益保障法》', '第二十五条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第三章 人身和人格权益', NULL, '用人单位应当采取下列措施预防和制止对妇女的性骚扰： （一）制定禁止性骚扰的规章制度； （二）明确负责机构或者人员； （三）开展预防和制止性骚扰的教育培训活动； （四）采取必要的安全保卫措施； （五）设置投诉电话、信箱等，畅通投诉渠道； （六）建立和完善调查处置程序，及时处置纠纷并保护当事人隐私和个人信息； （七）支持、协助受害妇女依法维权，必要时为受害妇女提供心理疏导； （八）其他合理的预防和制止性骚扰措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209025, '《中华人民共和国妇女权益保障法》', '第二十六条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第三章 人身和人格权益', NULL, '住宿经营者应当及时准确登记住宿人员信息，健全住宿服务规章制度，加强安全保障措施；发现可能侵害妇女权益的违法犯罪行为，应当及时向公安机关报告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209026, '《中华人民共和国妇女权益保障法》', '第二十七条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第三章 人身和人格权益', NULL, '禁止卖淫、嫖娼；禁止组织、强迫、引诱、容留、介绍妇女卖淫或者对妇女进行猥亵活动；禁止组织、强迫、引诱、容留、介绍妇女在任何场所或者利用网络进行淫秽表演活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209027, '《中华人民共和国妇女权益保障法》', '第二十八条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第三章 人身和人格权益', NULL, '妇女的姓名权、肖像权、名誉权、荣誉权、隐私权和个人信息等人格权益受法律保护。 媒体报道涉及妇女事件应当客观、适度，不得通过夸大事实、过度渲染等方式侵害妇女的人格权益。 禁止通过大众传播媒介或者其他方式贬低损害妇女人格。未经本人同意，不得通过广告、商标、展览橱窗、报纸、期刊、图书、音像制品、电子出版物、网络等形式使用妇女肖像，但法律另有规定的除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209028, '《中华人民共和国妇女权益保障法》', '第二十九条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第三章 人身和人格权益', NULL, '禁止以恋爱、交友为由或者在终止恋爱关系、离婚之后，纠缠、骚扰妇女，泄露、传播妇女隐私和个人信息。 妇女遭受上述侵害或者面临上述侵害现实危险的，可以向人民法院申请人身安全保护令。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209029, '《中华人民共和国妇女权益保障法》', '第三十条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第三章 人身和人格权益', NULL, '国家建立健全妇女健康服务体系，保障妇女享有基本医疗卫生服务，开展妇女常见病、多发病的预防、筛查和诊疗，提高妇女健康水平。 国家采取必要措施，开展经期、孕期、产期、哺乳期和更年期的健康知识普及、卫生保健和疾病防治，保障妇女特殊生理时期的健康需求，为有需要的妇女提供心理健康服务支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209030, '《中华人民共和国妇女权益保障法》', '第三十一条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第三章 人身和人格权益', NULL, '县级以上地方人民政府应当设立妇幼保健机构，为妇女提供保健以及常见病防治服务。 国家鼓励和支持社会力量通过依法捐赠、资助或者提供志愿服务等方式，参与妇女卫生健康事业，提供安全的生理健康用品或者服务，满足妇女多样化、差异化的健康需求。 用人单位应当定期为女职工安排妇科疾病、乳腺疾病检查以及妇女特殊需要的其他健康检查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209031, '《中华人民共和国妇女权益保障法》', '第三十二条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第三章 人身和人格权益', NULL, '妇女依法享有生育子女的权利，也有不生育子女的自由。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209032, '《中华人民共和国妇女权益保障法》', '第三十三条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第三章 人身和人格权益', NULL, '国家实行婚前、孕前、孕产期和产后保健制度，逐步建立妇女全生育周期系统保健制度。医疗保健机构应当提供安全、有效的医疗保健服务，保障妇女生育安全和健康。 有关部门应当提供安全、有效的避孕药具和技术，保障妇女的健康和安全。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209033, '《中华人民共和国妇女权益保障法》', '第三十四条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第三章 人身和人格权益', NULL, '各级人民政府在规划、建设基础设施时，应当考虑妇女的特殊需求，配备满足妇女需要的公共厕所和母婴室等公共设施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209034, '《中华人民共和国妇女权益保障法》', '第三十五条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第四章 文化教育权益', NULL, '国家保障妇女享有与男子平等的文化教育权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209035, '《中华人民共和国妇女权益保障法》', '第三十六条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第四章 文化教育权益', NULL, '父母或者其他监护人应当履行保障适龄女性未成年人接受并完成义务教育的义务。 对无正当理由不送适龄女性未成年人入学的父母或者其他监护人，由当地乡镇人民政府或者县级人民政府教育行政部门给予批评教育，依法责令其限期改正。居民委员会、村民委员会应当协助政府做好相关工作。 政府、学校应当采取有效措施，解决适龄女性未成年人就学存在的实际困难，并创造条件，保证适龄女性未成年人完成义务教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209036, '《中华人民共和国妇女权益保障法》', '第三十七条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第四章 文化教育权益', NULL, '学校和有关部门应当执行国家有关规定，保障妇女在入学、升学、授予学位、派出留学、就业指导和服务等方面享有与男子平等的权利。 学校在录取学生时，除国家规定的特殊专业外，不得以性别为由拒绝录取女性或者提高对女性的录取标准。 各级人民政府应当采取措施，保障女性平等享有接受中高等教育的权利和机会。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209037, '《中华人民共和国妇女权益保障法》', '第三十八条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第四章 文化教育权益', NULL, '各级人民政府应当依照规定把扫除妇女中的文盲、半文盲工作，纳入扫盲和扫盲后继续教育规划，采取符合妇女特点的组织形式和工作方法，组织、监督有关部门具体实施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209038, '《中华人民共和国妇女权益保障法》', '第三十九条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第四章 文化教育权益', NULL, '国家健全全民终身学习体系，为妇女终身学习创造条件。 各级人民政府和有关部门应当采取措施，根据城镇和农村妇女的需要，组织妇女接受职业教育和实用技术培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209039, '《中华人民共和国妇女权益保障法》', '第四十条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第四章 文化教育权益', NULL, '国家机关、社会团体和企业事业单位应当执行国家有关规定，保障妇女从事科学、技术、文学、艺术和其他文化活动，享有与男子平等的权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209040, '《中华人民共和国妇女权益保障法》', '第四十一条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第五章 劳动和社会保障权益', NULL, '国家保障妇女享有与男子平等的劳动权利和社会保障权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209041, '《中华人民共和国妇女权益保障法》', '第四十二条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第五章 劳动和社会保障权益', NULL, '各级人民政府和有关部门应当完善就业保障政策措施，防止和纠正就业性别歧视，为妇女创造公平的就业创业环境，为就业困难的妇女提供必要的扶持和援助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209042, '《中华人民共和国妇女权益保障法》', '第四十三条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第五章 劳动和社会保障权益', NULL, '用人单位在招录（聘）过程中，除国家另有规定外，不得实施下列行为： （一）限定为男性或者规定男性优先； （二）除个人基本信息外，进一步询问或者调查女性求职者的婚育情况； （三）将妊娠测试作为入职体检项目； （四）将限制结婚、生育或者婚姻、生育状况作为录（聘）用条件； （五）其他以性别为由拒绝录（聘）用妇女或者差别化地提高对妇女录（聘）用标准的行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209043, '《中华人民共和国妇女权益保障法》', '第四十四条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第五章 劳动和社会保障权益', NULL, '用人单位在录（聘）用女职工时，应当依法与其签订劳动（聘用）合同或者服务协议，劳动（聘用）合同或者服务协议中应当具备女职工特殊保护条款，并不得规定限制女职工结婚、生育等内容。 职工一方与用人单位订立的集体合同中应当包含男女平等和女职工权益保护相关内容，也可以就相关内容制定专章、附件或者单独订立女职工权益保护专项集体合同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209044, '《中华人民共和国妇女权益保障法》', '第四十五条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第五章 劳动和社会保障权益', NULL, '实行男女同工同酬。妇女在享受福利待遇方面享有与男子平等的权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209045, '《中华人民共和国妇女权益保障法》', '第四十六条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第五章 劳动和社会保障权益', NULL, '在晋职、晋级、评聘专业技术职称和职务、培训等方面，应当坚持男女平等的原则，不得歧视妇女。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209046, '《中华人民共和国妇女权益保障法》', '第四十七条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第五章 劳动和社会保障权益', NULL, '用人单位应当根据妇女的特点，依法保护妇女在工作和劳动时的安全、健康以及休息的权利。 妇女在经期、孕期、产期、哺乳期受特殊保护。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209047, '《中华人民共和国妇女权益保障法》', '第四十八条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第五章 劳动和社会保障权益', NULL, '用人单位不得因结婚、怀孕、产假、哺乳等情形，降低女职工的工资和福利待遇，限制女职工晋职、晋级、评聘专业技术职称和职务，辞退女职工，单方解除劳动（聘用）合同或者服务协议。 女职工在怀孕以及依法享受产假期间，劳动（聘用）合同或者服务协议期满的，劳动（聘用）合同或者服务协议期限自动延续至产假结束。但是，用人单位依法解除、终止劳动（聘用）合同、服务协议，或者女职工依法要求解除、终止劳动（聘用）合同、服务协议的除外。 用人单位在执行国家退休制度时，不得以性别为由歧视妇女。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209048, '《中华人民共和国妇女权益保障法》', '第四十九条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第五章 劳动和社会保障权益', NULL, '人力资源和社会保障部门应当将招聘、录取、晋职、晋级、评聘专业技术职称和职务、培训、辞退等过程中的性别歧视行为纳入劳动保障监察范围。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209049, '《中华人民共和国妇女权益保障法》', '第五十条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第五章 劳动和社会保障权益', NULL, '国家发展社会保障事业，保障妇女享有社会保险、社会救助和社会福利等权益。 国家提倡和鼓励为帮助妇女而开展的社会公益活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209050, '《中华人民共和国妇女权益保障法》', '第五十一条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第五章 劳动和社会保障权益', NULL, '国家实行生育保险制度，建立健全婴幼儿托育服务等与生育相关的其他保障制度。 国家建立健全职工生育休假制度，保障孕产期女职工依法享有休息休假权益。 地方各级人民政府和有关部门应当按照国家有关规定，为符合条件的困难妇女提供必要的生育救助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209051, '《中华人民共和国妇女权益保障法》', '第五十二条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第五章 劳动和社会保障权益', NULL, '各级人民政府和有关部门应当采取必要措施，加强贫困妇女、老龄妇女、残疾妇女等困难妇女的权益保障，按照有关规定为其提供生活帮扶、就业创业支持等关爱服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209052, '《中华人民共和国妇女权益保障法》', '第五十三条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第六章 财产权益', NULL, '国家保障妇女享有与男子平等的财产权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209053, '《中华人民共和国妇女权益保障法》', '第五十四条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第六章 财产权益', NULL, '在夫妻共同财产、家庭共有财产关系中，不得侵害妇女依法享有的权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209054, '《中华人民共和国妇女权益保障法》', '第五十五条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第六章 财产权益', NULL, '妇女在农村集体经济组织成员身份确认、土地承包经营、集体经济组织收益分配、土地征收补偿安置或者征用补偿以及宅基地使用等方面，享有与男子平等的权利。 申请农村土地承包经营权、宅基地使用权等不动产登记，应当在不动产登记簿和权属证书上将享有权利的妇女等家庭成员全部列明。征收补偿安置或者征用补偿协议应当将享有相关权益的妇女列入，并记载权益内容。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209055, '《中华人民共和国妇女权益保障法》', '第五十六条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第六章 财产权益', NULL, '村民自治章程、村规民约，村民会议、村民代表会议的决定以及其他涉及村民利益事项的决定，不得以妇女未婚、结婚、离婚、丧偶、户无男性等为由，侵害妇女在农村集体经济组织中的各项权益。 因结婚男方到女方住所落户的，男方和子女享有与所在地农村集体经济组织成员平等的权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209056, '《中华人民共和国妇女权益保障法》', '第五十七条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第六章 财产权益', NULL, '国家保护妇女在城镇集体所有财产关系中的权益。妇女依照法律、法规的规定享有相关权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209057, '《中华人民共和国妇女权益保障法》', '第五十八条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第六章 财产权益', NULL, '妇女享有与男子平等的继承权。妇女依法行使继承权，不受歧视。 丧偶妇女有权依法处分继承的财产，任何组织和个人不得干涉。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209058, '《中华人民共和国妇女权益保障法》', '第五十九条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第六章 财产权益', NULL, '丧偶儿媳对公婆尽了主要赡养义务的，作为第一顺序继承人，其继承权不受子女代位继承的影响。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209059, '《中华人民共和国妇女权益保障法》', '第六十条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第七章 婚姻家庭权益', NULL, '国家保障妇女享有与男子平等的婚姻家庭权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209060, '《中华人民共和国妇女权益保障法》', '第六十一条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第七章 婚姻家庭权益', NULL, '国家保护妇女的婚姻自主权。禁止干涉妇女的结婚、离婚自由。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209061, '《中华人民共和国妇女权益保障法》', '第六十二条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第七章 婚姻家庭权益', NULL, '国家鼓励男女双方在结婚登记前，共同进行医学检查或者相关健康体检。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209062, '《中华人民共和国妇女权益保障法》', '第六十三条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第七章 婚姻家庭权益', NULL, '婚姻登记机关应当提供婚姻家庭辅导服务，引导当事人建立平等、和睦、文明的婚姻家庭关系。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209063, '《中华人民共和国妇女权益保障法》', '第六十四条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第七章 婚姻家庭权益', NULL, '女方在怀孕期间、分娩后一年内或者终止妊娠后六个月内，男方不得提出离婚；但是，女方提出离婚或者人民法院认为确有必要受理男方离婚请求的除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209064, '《中华人民共和国妇女权益保障法》', '第六十五条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第七章 婚姻家庭权益', NULL, '禁止对妇女实施家庭暴力。 县级以上人民政府有关部门、司法机关、社会团体、企业事业单位、基层群众性自治组织以及其他组织，应当在各自的职责范围内预防和制止家庭暴力，依法为受害妇女提供救助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209065, '《中华人民共和国妇女权益保障法》', '第六十六条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第七章 婚姻家庭权益', NULL, '妇女对夫妻共同财产享有与其配偶平等的占有、使用、收益和处分的权利，不受双方收入状况等情形的影响。 对夫妻共同所有的不动产以及可以联名登记的动产，女方有权要求在权属证书上记载其姓名；认为记载的权利人、标的物、权利比例等事项有错误的，有权依法申请更正登记或者异议登记，有关机构应当按照其申请依法办理相应登记手续。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209066, '《中华人民共和国妇女权益保障法》', '第六十七条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第七章 婚姻家庭权益', NULL, '离婚诉讼期间，夫妻一方申请查询登记在对方名下财产状况且确因客观原因不能自行收集的，人民法院应当进行调查取证，有关部门和单位应当予以协助。 离婚诉讼期间，夫妻双方均有向人民法院申报全部夫妻共同财产的义务。一方隐藏、转移、变卖、损毁、挥霍夫妻共同财产，或者伪造夫妻共同债务企图侵占另一方财产的，在离婚分割夫妻共同财产时，对该方可以少分或者不分财产。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209067, '《中华人民共和国妇女权益保障法》', '第六十八条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第七章 婚姻家庭权益', NULL, '夫妻双方应当共同负担家庭义务，共同照顾家庭生活。 女方因抚育子女、照料老人、协助男方工作等负担较多义务的，有权在离婚时要求男方予以补偿。补偿办法由双方协议确定；协议不成的，可以向人民法院提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209068, '《中华人民共和国妇女权益保障法》', '第六十九条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第七章 婚姻家庭权益', NULL, '离婚时，分割夫妻共有的房屋或者处理夫妻共同租住的房屋，由双方协议解决；协议不成的，可以向人民法院提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209069, '《中华人民共和国妇女权益保障法》', '第七十条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第七章 婚姻家庭权益', NULL, '父母双方对未成年子女享有平等的监护权。 父亲死亡、无监护能力或者有其他情形不能担任未成年子女的监护人的，母亲的监护权任何组织和个人不得干涉。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209070, '《中华人民共和国妇女权益保障法》', '第七十一条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第七章 婚姻家庭权益', NULL, '女方丧失生育能力的，在离婚处理子女抚养问题时，应当在最有利于未成年子女的条件下，优先考虑女方的抚养要求。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209071, '《中华人民共和国妇女权益保障法》', '第七十二条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第八章 救济措施', NULL, '对侵害妇女合法权益的行为，任何组织和个人都有权予以劝阻、制止或者向有关部门提出控告或者检举。有关部门接到控告或者检举后，应当依法及时处理，并为控告人、检举人保密。 妇女的合法权益受到侵害的，有权要求有关部门依法处理，或者依法申请调解、仲裁，或者向人民法院起诉。 对符合条件的妇女，当地法律援助机构或者司法机关应当给予帮助，依法为其提供法律援助或者司法救助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209072, '《中华人民共和国妇女权益保障法》', '第七十三条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第八章 救济措施', NULL, '妇女的合法权益受到侵害的，可以向妇女联合会等妇女组织求助。妇女联合会等妇女组织应当维护被侵害妇女的合法权益，有权要求并协助有关部门或者单位查处。有关部门或者单位应当依法查处，并予以答复；不予处理或者处理不当的，县级以上人民政府负责妇女儿童工作的机构、妇女联合会可以向其提出督促处理意见，必要时可以提请同级人民政府开展督查。 受害妇女进行诉讼需要帮助的，妇女联合会应当给予支持和帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209073, '《中华人民共和国妇女权益保障法》', '第七十四条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第八章 救济措施', NULL, '用人单位侵害妇女劳动和社会保障权益的，人力资源和社会保障部门可以联合工会、妇女联合会约谈用人单位，依法进行监督并要求其限期纠正。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209074, '《中华人民共和国妇女权益保障法》', '第七十五条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第八章 救济措施', NULL, '妇女在农村集体经济组织成员身份确认等方面权益受到侵害的，可以申请乡镇人民政府等进行协调，或者向人民法院起诉。 乡镇人民政府应当对村民自治章程、村规民约，村民会议、村民代表会议的决定以及其他涉及村民利益事项的决定进行指导，对其中违反法律、法规和国家政策规定，侵害妇女合法权益的内容责令改正；受侵害妇女向农村土地承包仲裁机构申请仲裁或者向人民法院起诉的，农村土地承包仲裁机构或者人民法院应当依法受理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209075, '《中华人民共和国妇女权益保障法》', '第七十六条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第八章 救济措施', NULL, '县级以上人民政府应当开通全国统一的妇女权益保护服务热线，及时受理、移送有关侵害妇女合法权益的投诉、举报；有关部门或者单位接到投诉、举报后，应当及时予以处置。 鼓励和支持群团组织、企业事业单位、社会组织和个人参与建设妇女权益保护服务热线，提供妇女权益保护方面的咨询、帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209076, '《中华人民共和国妇女权益保障法》', '第七十七条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第八章 救济措施', NULL, '侵害妇女合法权益，导致社会公共利益受损的，检察机关可以发出检察建议；有下列情形之一的，检察机关可以依法提起公益诉讼： （一）确认农村妇女集体经济组织成员身份时侵害妇女权益或者侵害妇女享有的农村土地承包和集体收益、土地征收征用补偿分配权益和宅基地使用权益； （二）侵害妇女平等就业权益； （三）相关单位未采取合理措施预防和制止性骚扰； （四）通过大众传播媒介或者其他方式贬低损害妇女人格； （五）其他严重侵害妇女权益的情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209077, '《中华人民共和国妇女权益保障法》', '第七十八条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第八章 救济措施', NULL, '国家机关、社会团体、企业事业单位对侵害妇女权益的行为，可以支持受侵害的妇女向人民法院起诉。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209078, '《中华人民共和国妇女权益保障法》', '第七十九条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第九章 法律责任', NULL, '违反本法第二十二条第二款规定，未履行报告义务的，依法对直接负责的主管人员和其他直接责任人员给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209079, '《中华人民共和国妇女权益保障法》', '第八十条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第九章 法律责任', NULL, '违反本法规定，对妇女实施性骚扰的，由公安机关给予批评教育或者出具告诫书，并由所在单位依法给予处分。 学校、用人单位违反本法规定，未采取必要措施预防和制止性骚扰，造成妇女权益受到侵害或者社会影响恶劣的，由上级机关或者主管部门责令改正；拒不改正或者情节严重的，依法对直接负责的主管人员和其他直接责任人员给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209080, '《中华人民共和国妇女权益保障法》', '第八十一条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第九章 法律责任', NULL, '违反本法第二十六条规定，未履行报告等义务的，依法给予警告、责令停业整顿或者吊销营业执照、吊销相关许可证，并处一万元以上五万元以下罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209081, '《中华人民共和国妇女权益保障法》', '第八十二条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第九章 法律责任', NULL, '违反本法规定，通过大众传播媒介或者其他方式贬低损害妇女人格的，由公安、网信、文化旅游、广播电视、新闻出版或者其他有关部门依据各自的职权责令改正，并依法给予行政处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209082, '《中华人民共和国妇女权益保障法》', '第八十三条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第九章 法律责任', NULL, '用人单位违反本法第四十三条和第四十八条规定的，由人力资源和社会保障部门责令改正；拒不改正或者情节严重的，处一万元以上五万元以下罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209083, '《中华人民共和国妇女权益保障法》', '第八十四条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第九章 法律责任', NULL, '违反本法规定，对侵害妇女权益的申诉、控告、检举，推诿、拖延、压制不予查处，或者对提出申诉、控告、检举的人进行打击报复的，依法责令改正，并对直接负责的主管人员和其他直接责任人员给予处分。 国家机关及其工作人员未依法履行职责，对侵害妇女权益的行为未及时制止或者未给予受害妇女必要帮助，造成严重后果的，依法对直接负责的主管人员和其他直接责任人员给予处分。 违反本法规定，侵害妇女人身和人格权益、文化教育权益、劳动和社会保障权益、财产权益以及婚姻家庭权益的，依法责令改正，直接负责的主管人员和其他直接责任人员属于国家工作人员的，依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209084, '《中华人民共和国妇女权益保障法》', '第八十五条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第九章 法律责任', NULL, '违反本法规定，侵害妇女的合法权益，其他法律、法规规定行政处罚的，从其规定；造成财产损失或者人身损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (209085, '《中华人民共和国妇女权益保障法》', '第八十六条', '劳动', '法律', NULL, '全国人民代表大会 2022-10-30', '第十章 附 则', NULL, '本法自2023年1月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210000, '《中华人民共和国未成年人保护法》', '第一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第一章 总 则', NULL, '为了保护未成年人身心健康，保障未成年人合法权益，促进未成年人德智体美劳全面发展，培养有理想、有道德、有文化、有纪律的社会主义建设者和接班人，培养担当民族复兴大任的时代新人，根据宪法，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210001, '《中华人民共和国未成年人保护法》', '第二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第一章 总 则', NULL, '本法所称未成年人是指未满十八周岁的公民。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210002, '《中华人民共和国未成年人保护法》', '第三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第一章 总 则', NULL, '国家保障未成年人的生存权、发展权、受保护权、参与权等权利。 未成年人依法平等地享有各项权利，不因本人及其父母或者其他监护人的民族、种族、性别、户籍、职业、宗教信仰、教育程度、家庭状况、身心健康状况等受到歧视。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210003, '《中华人民共和国未成年人保护法》', '第四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第一章 总 则', NULL, '保护未成年人，应当坚持最有利于未成年人的原则。处理涉及未成年人事项，应当符合下列要求： （一）给予未成年人特殊、优先保护； （二）尊重未成年人人格尊严； （三）保护未成年人隐私权和个人信息； （四）适应未成年人身心健康发展的规律和特点； （五）听取未成年人的意见； （六）保护与教育相结合。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210004, '《中华人民共和国未成年人保护法》', '第五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第一章 总 则', NULL, '国家、社会、学校和家庭应当对未成年人进行理想教育、道德教育、科学教育、文化教育、法治教育、国家安全教育、健康教育、劳动教育，加强爱国主义、集体主义和中国特色社会主义的教育，培养爱祖国、爱人民、爱劳动、爱科学、爱社会主义的公德，抵制资本主义、封建主义和其他腐朽思想的侵蚀，引导未成年人树立和践行社会主义核心价值观。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210005, '《中华人民共和国未成年人保护法》', '第六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第一章 总 则', NULL, '保护未成年人，是国家机关、武装力量、政党、人民团体、企业事业单位、社会组织、城乡基层群众性自治组织、未成年人的监护人以及其他成年人的共同责任。 国家、社会、学校和家庭应当教育和帮助未成年人维护自身合法权益，增强自我保护的意识和能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210006, '《中华人民共和国未成年人保护法》', '第七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第一章 总 则', NULL, '未成年人的父母或者其他监护人依法对未成年人承担监护职责。 国家采取措施指导、支持、帮助和监督未成年人的父母或者其他监护人履行监护职责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210007, '《中华人民共和国未成年人保护法》', '第八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第一章 总 则', NULL, '县级以上人民政府应当将未成年人保护工作纳入国民经济和社会发展规划，相关经费纳入本级政府预算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210008, '《中华人民共和国未成年人保护法》', '第九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第一章 总 则', NULL, '各级人民政府应当重视和加强未成年人保护工作。县级以上人民政府负责妇女儿童工作的机构，负责未成年人保护工作的组织、协调、指导、督促，有关部门在各自职责范围内做好相关工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210009, '《中华人民共和国未成年人保护法》', '第十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第一章 总 则', NULL, '共产主义青年团、妇女联合会、工会、残疾人联合会、关心下一代工作委员会、青年联合会、学生联合会、少年先锋队以及其他人民团体、有关社会组织，应当协助各级人民政府及其有关部门、人民检察院、人民法院做好未成年人保护工作，维护未成年人合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210010, '《中华人民共和国未成年人保护法》', '第十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第一章 总 则', NULL, '任何组织或者个人发现不利于未成年人身心健康或者侵犯未成年人合法权益的情形，都有权劝阻、制止或者向公安、民政、教育等有关部门提出检举、控告。 国家机关、居民委员会、村民委员会、密切接触未成年人的单位及其工作人员，在工作中发现未成年人身心健康受到侵害、疑似受到侵害或者面临其他危险情形的，应当立即向公安、民政、教育等有关部门报告。 有关部门接到涉及未成年人的检举、控告或者报告，应当依法及时受理、处置，并以适当方式将处理结果告知相关单位和人员。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210011, '《中华人民共和国未成年人保护法》', '第十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第一章 总 则', NULL, '国家鼓励和支持未成年人保护方面的科学研究，建设相关学科、设置相关专业，加强人才培养。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210012, '《中华人民共和国未成年人保护法》', '第十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第一章 总 则', NULL, '国家建立健全未成年人统计调查制度，开展未成年人健康、受教育等状况的统计、调查和分析，发布未成年人保护的有关信息。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210013, '《中华人民共和国未成年人保护法》', '第十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第一章 总 则', NULL, '国家对保护未成年人有显著成绩的组织和个人给予表彰和奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210014, '《中华人民共和国未成年人保护法》', '第十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第二章 家庭保护', NULL, '未成年人的父母或者其他监护人应当学习家庭教育知识，接受家庭教育指导，创造良好、和睦、文明的家庭环境。 共同生活的其他成年家庭成员应当协助未成年人的父母或者其他监护人抚养、教育和保护未成年人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210015, '《中华人民共和国未成年人保护法》', '第十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第二章 家庭保护', NULL, '未成年人的父母或者其他监护人应当履行下列监护职责： （一）为未成年人提供生活、健康、安全等方面的保障； （二）关注未成年人的生理、心理状况和情感需求； （三）教育和引导未成年人遵纪守法、勤俭节约，养成良好的思想品德和行为习惯； （四）对未成年人进行安全教育，提高未成年人的自我保护意识和能力； （五）尊重未成年人受教育的权利，保障适龄未成年人依法接受并完成义务教育； （六）保障未成年人休息、娱乐和体育锻炼的时间，引导未成年人进行有益身心健康的活动； （七）妥善管理和保护未成年人的财产； （八）依法代理未成年人实施民事法律行为； （九）预防和制止未成年人的不良行为和违法犯罪行为，并进行合理管教； （十）其他应当履行的监护职责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210016, '《中华人民共和国未成年人保护法》', '第十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第二章 家庭保护', NULL, '未成年人的父母或者其他监护人不得实施下列行为： （一）虐待、遗弃、非法送养未成年人或者对未成年人实施家庭暴力； （二）放任、教唆或者利用未成年人实施违法犯罪行为； （三）放任、唆使未成年人参与邪教、迷信活动或者接受恐怖主义、分裂主义、极端主义等侵害； （四）放任、唆使未成年人吸烟（含电子烟，下同）、饮酒、赌博、流浪乞讨或者欺凌他人； （五）放任或者迫使应当接受义务教育的未成年人失学、辍学； （六）放任未成年人沉迷网络，接触危害或者可能影响其身心健康的图书、报刊、电影、广播电视节目、音像制品、电子出版物和网络信息等； （七）放任未成年人进入营业性娱乐场所、酒吧、互联网上网服务营业场所等不适宜未成年人活动的场所； （八）允许或者迫使未成年人从事国家规定以外的劳动； （九）允许、迫使未成年人结婚或者为未成年人订立婚约； （十）违法处分、侵吞未成年人的财产或者利用未成年人牟取不正当利益； （十一）其他侵犯未成年人身心健康、财产权益或者不依法履行未成年人保护义务的行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210017, '《中华人民共和国未成年人保护法》', '第十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第二章 家庭保护', NULL, '未成年人的父母或者其他监护人应当为未成年人提供安全的家庭生活环境，及时排除引发触电、烫伤、跌落等伤害的安全隐患；采取配备儿童安全座椅、教育未成年人遵守交通规则等措施，防止未成年人受到交通事故的伤害；提高户外安全保护意识，避免未成年人发生溺水、动物伤害等事故。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210018, '《中华人民共和国未成年人保护法》', '第十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第二章 家庭保护', NULL, '未成年人的父母或者其他监护人应当根据未成年人的年龄和智力发展状况，在作出与未成年人权益有关的决定前，听取未成年人的意见，充分考虑其真实意愿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210019, '《中华人民共和国未成年人保护法》', '第二十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第二章 家庭保护', NULL, '未成年人的父母或者其他监护人发现未成年人身心健康受到侵害、疑似受到侵害或者其他合法权益受到侵犯的，应当及时了解情况并采取保护措施；情况严重的，应当立即向公安、民政、教育等部门报告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210020, '《中华人民共和国未成年人保护法》', '第二十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第二章 家庭保护', NULL, '未成年人的父母或者其他监护人不得使未满八周岁或者由于身体、心理原因需要特别照顾的未成年人处于无人看护状态，或者将其交由无民事行为能力、限制民事行为能力、患有严重传染性疾病或者其他不适宜的人员临时照护。 未成年人的父母或者其他监护人不得使未满十六周岁的未成年人脱离监护单独生活。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210021, '《中华人民共和国未成年人保护法》', '第二十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第二章 家庭保护', NULL, '未成年人的父母或者其他监护人因外出务工等原因在一定期限内不能完全履行监护职责的，应当委托具有照护能力的完全民事行为能力人代为照护；无正当理由的，不得委托他人代为照护。 未成年人的父母或者其他监护人在确定被委托人时，应当综合考虑其道德品质、家庭状况、身心健康状况、与未成年人生活情感上的联系等情况，并听取有表达意愿能力未成年人的意见。 具有下列情形之一的，不得作为被委托人： （一）曾实施性侵害、虐待、遗弃、拐卖、暴力伤害等违法犯罪行为； （二）有吸毒、酗酒、赌博等恶习； （三）曾拒不履行或者长期怠于履行监护、照护职责； （四）其他不适宜担任被委托人的情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210022, '《中华人民共和国未成年人保护法》', '第二十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第二章 家庭保护', NULL, '未成年人的父母或者其他监护人应当及时将委托照护情况书面告知未成年人所在学校、幼儿园和实际居住地的居民委员会、村民委员会，加强和未成年人所在学校、幼儿园的沟通；与未成年人、被委托人至少每周联系和交流一次，了解未成年人的生活、学习、心理等情况，并给予未成年人亲情关爱。 未成年人的父母或者其他监护人接到被委托人、居民委员会、村民委员会、学校、幼儿园等关于未成年人心理、行为异常的通知后，应当及时采取干预措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210023, '《中华人民共和国未成年人保护法》', '第二十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第二章 家庭保护', NULL, '未成年人的父母离婚时，应当妥善处理未成年子女的抚养、教育、探望、财产等事宜，听取有表达意愿能力未成年人的意见。不得以抢夺、藏匿未成年子女等方式争夺抚养权。 未成年人的父母离婚后，不直接抚养未成年子女的一方应当依照协议、人民法院判决或者调解确定的时间和方式，在不影响未成年人学习、生活的情况下探望未成年子女，直接抚养的一方应当配合，但被人民法院依法中止探望权的除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210024, '《中华人民共和国未成年人保护法》', '第二十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第三章 学校保护', NULL, '学校应当全面贯彻国家教育方针，坚持立德树人，实施素质教育，提高教育质量，注重培养未成年学生认知能力、合作能力、创新能力和实践能力，促进未成年学生全面发展。 学校应当建立未成年学生保护工作制度，健全学生行为规范，培养未成年学生遵纪守法的良好行为习惯。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210025, '《中华人民共和国未成年人保护法》', '第二十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第三章 学校保护', NULL, '幼儿园应当做好保育、教育工作，遵循幼儿身心发展规律，实施启蒙教育，促进幼儿在体质、智力、品德等方面和谐发展。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210026, '《中华人民共和国未成年人保护法》', '第二十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第三章 学校保护', NULL, '学校、幼儿园的教职员工应当尊重未成年人人格尊严，不得对未成年人实施体罚、变相体罚或者其他侮辱人格尊严的行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210027, '《中华人民共和国未成年人保护法》', '第二十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第三章 学校保护', NULL, '学校应当保障未成年学生受教育的权利，不得违反国家规定开除、变相开除未成年学生。 学校应当对尚未完成义务教育的辍学未成年学生进行登记并劝返复学；劝返无效的，应当及时向教育行政部门书面报告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210028, '《中华人民共和国未成年人保护法》', '第二十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第三章 学校保护', NULL, '学校应当关心、爱护未成年学生，不得因家庭、身体、心理、学习能力等情况歧视学生。对家庭困难、身心有障碍的学生，应当提供关爱；对行为异常、学习有困难的学生，应当耐心帮助。 学校应当配合政府有关部门建立留守未成年学生、困境未成年学生的信息档案，开展关爱帮扶工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210029, '《中华人民共和国未成年人保护法》', '第三十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第三章 学校保护', NULL, '学校应当根据未成年学生身心发展特点，进行社会生活指导、心理健康辅导、青春期教育和生命教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210030, '《中华人民共和国未成年人保护法》', '第三十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第三章 学校保护', NULL, '学校应当组织未成年学生参加与其年龄相适应的日常生活劳动、生产劳动和服务性劳动，帮助未成年学生掌握必要的劳动知识和技能，养成良好的劳动习惯。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210031, '《中华人民共和国未成年人保护法》', '第三十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第三章 学校保护', NULL, '学校、幼儿园应当开展勤俭节约、反对浪费、珍惜粮食、文明饮食等宣传教育活动，帮助未成年人树立浪费可耻、节约为荣的意识，养成文明健康、绿色环保的生活习惯。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210032, '《中华人民共和国未成年人保护法》', '第三十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第三章 学校保护', NULL, '学校应当与未成年学生的父母或者其他监护人互相配合，合理安排未成年学生的学习时间，保障其休息、娱乐和体育锻炼的时间。 学校不得占用国家法定节假日、休息日及寒暑假期，组织义务教育阶段的未成年学生集体补课，加重其学习负担。 幼儿园、校外培训机构不得对学龄前未成年人进行小学课程教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210033, '《中华人民共和国未成年人保护法》', '第三十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第三章 学校保护', NULL, '学校、幼儿园应当提供必要的卫生保健条件，协助卫生健康部门做好在校、在园未成年人的卫生保健工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210034, '《中华人民共和国未成年人保护法》', '第三十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第三章 学校保护', NULL, '学校、幼儿园应当建立安全管理制度，对未成年人进行安全教育，完善安保设施、配备安保人员，保障未成年人在校、在园期间的人身和财产安全。 学校、幼儿园不得在危及未成年人人身安全、身心健康的校舍和其他设施、场所中进行教育教学活动。 学校、幼儿园安排未成年人参加文化娱乐、社会实践等集体活动，应当保护未成年人的身心健康，防止发生人身伤害事故。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210035, '《中华人民共和国未成年人保护法》', '第三十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第三章 学校保护', NULL, '使用校车的学校、幼儿园应当建立健全校车安全管理制度，配备安全管理人员，定期对校车进行安全检查，对校车驾驶人进行安全教育，并向未成年人讲解校车安全乘坐知识，培养未成年人校车安全事故应急处理技能。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210036, '《中华人民共和国未成年人保护法》', '第三十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第三章 学校保护', NULL, '学校、幼儿园应当根据需要，制定应对自然灾害、事故灾难、公共卫生事件等突发事件和意外伤害的预案，配备相应设施并定期进行必要的演练。 未成年人在校内、园内或者本校、本园组织的校外、园外活动中发生人身伤害事故的，学校、幼儿园应当立即救护，妥善处理，及时通知未成年人的父母或者其他监护人，并向有关部门报告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210037, '《中华人民共和国未成年人保护法》', '第三十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第三章 学校保护', NULL, '学校、幼儿园不得安排未成年人参加商业性活动，不得向未成年人及其父母或者其他监护人推销或者要求其购买指定的商品和服务。 学校、幼儿园不得与校外培训机构合作为未成年人提供有偿课程辅导。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210038, '《中华人民共和国未成年人保护法》', '第三十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第三章 学校保护', NULL, '学校应当建立学生欺凌防控工作制度，对教职员工、学生等开展防治学生欺凌的教育和培训。 学校对学生欺凌行为应当立即制止，通知实施欺凌和被欺凌未成年学生的父母或者其他监护人参与欺凌行为的认定和处理；对相关未成年学生及时给予心理辅导、教育和引导；对相关未成年学生的父母或者其他监护人给予必要的家庭教育指导。 对实施欺凌的未成年学生，学校应当根据欺凌行为的性质和程度，依法加强管教。对严重的欺凌行为，学校不得隐瞒，应当及时向公安机关、教育行政部门报告，并配合相关部门依法处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210039, '《中华人民共和国未成年人保护法》', '第四十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第三章 学校保护', NULL, '学校、幼儿园应当建立预防性侵害、性骚扰未成年人工作制度。对性侵害、性骚扰未成年人等违法犯罪行为，学校、幼儿园不得隐瞒，应当及时向公安机关、教育行政部门报告，并配合相关部门依法处理。 学校、幼儿园应当对未成年人开展适合其年龄的性教育，提高未成年人防范性侵害、性骚扰的自我保护意识和能力。对遭受性侵害、性骚扰的未成年人，学校、幼儿园应当及时采取相关的保护措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210040, '《中华人民共和国未成年人保护法》', '第四十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第三章 学校保护', NULL, '婴幼儿照护服务机构、早期教育服务机构、校外培训机构、校外托管机构等应当参照本章有关规定，根据不同年龄阶段未成年人的成长特点和规律，做好未成年人保护工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210041, '《中华人民共和国未成年人保护法》', '第四十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '全社会应当树立关心、爱护未成年人的良好风尚。 国家鼓励、支持和引导人民团体、企业事业单位、社会组织以及其他组织和个人，开展有利于未成年人健康成长的社会活动和服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210042, '《中华人民共和国未成年人保护法》', '第四十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '居民委员会、村民委员会应当设置专人专岗负责未成年人保护工作，协助政府有关部门宣传未成年人保护方面的法律法规，指导、帮助和监督未成年人的父母或者其他监护人依法履行监护职责，建立留守未成年人、困境未成年人的信息档案并给予关爱帮扶。 居民委员会、村民委员会应当协助政府有关部门监督未成年人委托照护情况，发现被委托人缺乏照护能力、怠于履行照护职责等情况，应当及时向政府有关部门报告，并告知未成年人的父母或者其他监护人，帮助、督促被委托人履行照护职责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210043, '《中华人民共和国未成年人保护法》', '第四十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '爱国主义教育基地、图书馆、青少年宫、儿童活动中心、儿童之家应当对未成年人免费开放；博物馆、纪念馆、科技馆、展览馆、美术馆、文化馆、社区公益性互联网上网服务场所以及影剧院、体育场馆、动物园、植物园、公园等场所，应当按照有关规定对未成年人免费或者优惠开放。 国家鼓励爱国主义教育基地、博物馆、科技馆、美术馆等公共场馆开设未成年人专场，为未成年人提供有针对性的服务。 国家鼓励国家机关、企业事业单位、部队等开发自身教育资源，设立未成年人开放日，为未成年人主题教育、社会实践、职业体验等提供支持。 国家鼓励科研机构和科技类社会组织对未成年人开展科学普及活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210044, '《中华人民共和国未成年人保护法》', '第四十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '城市公共交通以及公路、铁路、水路、航空客运等应当按照有关规定对未成年人实施免费或者优惠票价。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210045, '《中华人民共和国未成年人保护法》', '第四十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '国家鼓励大型公共场所、公共交通工具、旅游景区景点等设置母婴室、婴儿护理台以及方便幼儿使用的坐便器、洗手台等卫生设施，为未成年人提供便利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210046, '《中华人民共和国未成年人保护法》', '第四十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '任何组织或者个人不得违反有关规定，限制未成年人应当享有的照顾或者优惠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210047, '《中华人民共和国未成年人保护法》', '第四十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '国家鼓励创作、出版、制作和传播有利于未成年人健康成长的图书、报刊、电影、广播电视节目、舞台艺术作品、音像制品、电子出版物和网络信息等。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210048, '《中华人民共和国未成年人保护法》', '第四十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '新闻媒体应当加强未成年人保护方面的宣传，对侵犯未成年人合法权益的行为进行舆论监督。新闻媒体采访报道涉及未成年人事件应当客观、审慎和适度，不得侵犯未成年人的名誉、隐私和其他合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210049, '《中华人民共和国未成年人保护法》', '第五十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '禁止制作、复制、出版、发布、传播含有宣扬淫秽、色情、暴力、邪教、迷信、赌博、引诱自杀、恐怖主义、分裂主义、极端主义等危害未成年人身心健康内容的图书、报刊、电影、广播电视节目、舞台艺术作品、音像制品、电子出版物和网络信息等。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210050, '《中华人民共和国未成年人保护法》', '第五十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '任何组织或者个人出版、发布、传播的图书、报刊、电影、广播电视节目、舞台艺术作品、音像制品、电子出版物或者网络信息，包含可能影响未成年人身心健康内容的，应当以显著方式作出提示。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210051, '《中华人民共和国未成年人保护法》', '第五十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '禁止制作、复制、发布、传播或者持有有关未成年人的淫秽色情物品和网络信息。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210052, '《中华人民共和国未成年人保护法》', '第五十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '任何组织或者个人不得刊登、播放、张贴或者散发含有危害未成年人身心健康内容的广告；不得在学校、幼儿园播放、张贴或者散发商业广告；不得利用校服、教材等发布或者变相发布商业广告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210053, '《中华人民共和国未成年人保护法》', '第五十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '禁止拐卖、绑架、虐待、非法收养未成年人，禁止对未成年人实施性侵害、性骚扰。 禁止胁迫、引诱、教唆未成年人参加黑社会性质组织或者从事违法犯罪活动。 禁止胁迫、诱骗、利用未成年人乞讨。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210054, '《中华人民共和国未成年人保护法》', '第五十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '生产、销售用于未成年人的食品、药品、玩具、用具和游戏游艺设备、游乐设施等，应当符合国家或者行业标准，不得危害未成年人的人身安全和身心健康。上述产品的生产者应当在显著位置标明注意事项，未标明注意事项的不得销售。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210055, '《中华人民共和国未成年人保护法》', '第五十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '未成年人集中活动的公共场所应当符合国家或者行业安全标准，并采取相应安全保护措施。对可能存在安全风险的设施，应当定期进行维护，在显著位置设置安全警示标志并标明适龄范围和注意事项；必要时应当安排专门人员看管。 大型的商场、超市、医院、图书馆、博物馆、科技馆、游乐场、车站、码头、机场、旅游景区景点等场所运营单位应当设置搜寻走失未成年人的安全警报系统。场所运营单位接到求助后，应当立即启动安全警报系统，组织人员进行搜寻并向公安机关报告。 公共场所发生突发事件时，应当优先救护未成年人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210056, '《中华人民共和国未成年人保护法》', '第五十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '旅馆、宾馆、酒店等住宿经营者接待未成年人入住，或者接待未成年人和成年人共同入住时，应当询问父母或者其他监护人的联系方式、入住人员的身份关系等有关情况；发现有违法犯罪嫌疑的，应当立即向公安机关报告，并及时联系未成年人的父母或者其他监护人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210057, '《中华人民共和国未成年人保护法》', '第五十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '学校、幼儿园周边不得设置营业性娱乐场所、酒吧、互联网上网服务营业场所等不适宜未成年人活动的场所。营业性歌舞娱乐场所、酒吧、互联网上网服务营业场所等不适宜未成年人活动场所的经营者，不得允许未成年人进入；游艺娱乐场所设置的电子游戏设备，除国家法定节假日外，不得向未成年人提供。经营者应当在显著位置设置未成年人禁入、限入标志；对难以判明是否是未成年人的，应当要求其出示身份证件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210058, '《中华人民共和国未成年人保护法》', '第五十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '学校、幼儿园周边不得设置烟、酒、彩票销售网点。禁止向未成年人销售烟、酒、彩票或者兑付彩票奖金。烟、酒和彩票经营者应当在显著位置设置不向未成年人销售烟、酒或者彩票的标志；对难以判明是否是未成年人的，应当要求其出示身份证件。 任何人不得在学校、幼儿园和其他未成年人集中活动的公共场所吸烟、饮酒。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210059, '《中华人民共和国未成年人保护法》', '第六十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '禁止向未成年人提供、销售管制刀具或者其他可能致人严重伤害的器具等物品。经营者难以判明购买者是否是未成年人的，应当要求其出示身份证件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210060, '《中华人民共和国未成年人保护法》', '第六十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '任何组织或者个人不得招用未满十六周岁未成年人，国家另有规定的除外。 营业性娱乐场所、酒吧、互联网上网服务营业场所等不适宜未成年人活动的场所不得招用已满十六周岁的未成年人。 招用已满十六周岁未成年人的单位和个人应当执行国家在工种、劳动时间、劳动强度和保护措施等方面的规定，不得安排其从事过重、有毒、有害等危害未成年人身心健康的劳动或者危险作业。 任何组织或者个人不得组织未成年人进行危害其身心健康的表演等活动。经未成年人的父母或者其他监护人同意，未成年人参与演出、节目制作等活动，活动组织方应当根据国家有关规定，保障未成年人合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210061, '《中华人民共和国未成年人保护法》', '第六十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '密切接触未成年人的单位招聘工作人员时，应当向公安机关、人民检察院查询应聘者是否具有性侵害、虐待、拐卖、暴力伤害等违法犯罪记录；发现其具有前述行为记录的，不得录用。 密切接触未成年人的单位应当每年定期对工作人员是否具有上述违法犯罪记录进行查询。通过查询或者其他方式发现其工作人员具有上述行为的，应当及时解聘。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210062, '《中华人民共和国未成年人保护法》', '第六十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第四章 社会保护', NULL, '任何组织或者个人不得隐匿、毁弃、非法删除未成年人的信件、日记、电子邮件或者其他网络通讯内容。 除下列情形外，任何组织或者个人不得开拆、查阅未成年人的信件、日记、电子邮件或者其他网络通讯内容： （一）无民事行为能力未成年人的父母或者其他监护人代未成年人开拆、查阅； （二）因国家安全或者追查刑事犯罪依法进行检查； （三）紧急情况下为了保护未成年人本人的人身安全。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210063, '《中华人民共和国未成年人保护法》', '第六十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第五章 网络保护', NULL, '国家、社会、学校和家庭应当加强未成年人网络素养宣传教育，培养和提高未成年人的网络素养，增强未成年人科学、文明、安全、合理使用网络的意识和能力，保障未成年人在网络空间的合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210064, '《中华人民共和国未成年人保护法》', '第六十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第五章 网络保护', NULL, '国家鼓励和支持有利于未成年人健康成长的网络内容的创作与传播，鼓励和支持专门以未成年人为服务对象、适合未成年人身心健康特点的网络技术、产品、服务的研发、生产和使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210065, '《中华人民共和国未成年人保护法》', '第六十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第五章 网络保护', NULL, '网信部门及其他有关部门应当加强对未成年人网络保护工作的监督检查，依法惩处利用网络从事危害未成年人身心健康的活动，为未成年人提供安全、健康的网络环境。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210066, '《中华人民共和国未成年人保护法》', '第六十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第五章 网络保护', NULL, '网信部门会同公安、文化和旅游、新闻出版、电影、广播电视等部门根据保护不同年龄阶段未成年人的需要，确定可能影响未成年人身心健康网络信息的种类、范围和判断标准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210067, '《中华人民共和国未成年人保护法》', '第六十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第五章 网络保护', NULL, '新闻出版、教育、卫生健康、文化和旅游、网信等部门应当定期开展预防未成年人沉迷网络的宣传教育，监督网络产品和服务提供者履行预防未成年人沉迷网络的义务，指导家庭、学校、社会组织互相配合，采取科学、合理的方式对未成年人沉迷网络进行预防和干预。 任何组织或者个人不得以侵害未成年人身心健康的方式对未成年人沉迷网络进行干预。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210068, '《中华人民共和国未成年人保护法》', '第六十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第五章 网络保护', NULL, '学校、社区、图书馆、文化馆、青少年宫等场所为未成年人提供的互联网上网服务设施，应当安装未成年人网络保护软件或者采取其他安全保护技术措施。 智能终端产品的制造者、销售者应当在产品上安装未成年人网络保护软件，或者以显著方式告知用户未成年人网络保护软件的安装渠道和方法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210069, '《中华人民共和国未成年人保护法》', '第七十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第五章 网络保护', NULL, '学校应当合理使用网络开展教学活动。未经学校允许，未成年学生不得将手机等智能终端产品带入课堂，带入学校的应当统一管理。 学校发现未成年学生沉迷网络的，应当及时告知其父母或者其他监护人，共同对未成年学生进行教育和引导，帮助其恢复正常的学习生活。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210070, '《中华人民共和国未成年人保护法》', '第七十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第五章 网络保护', NULL, '未成年人的父母或者其他监护人应当提高网络素养，规范自身使用网络的行为，加强对未成年人使用网络行为的引导和监督。 未成年人的父母或者其他监护人应当通过在智能终端产品上安装未成年人网络保护软件、选择适合未成年人的服务模式和管理功能等方式，避免未成年人接触危害或者可能影响其身心健康的网络信息，合理安排未成年人使用网络的时间，有效预防未成年人沉迷网络。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210071, '《中华人民共和国未成年人保护法》', '第七十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第五章 网络保护', NULL, '信息处理者通过网络处理未成年人个人信息的，应当遵循合法、正当和必要的原则。处理不满十四周岁未成年人个人信息的，应当征得未成年人的父母或者其他监护人同意，但法律、行政法规另有规定的除外。 未成年人、父母或者其他监护人要求信息处理者更正、删除未成年人个人信息的，信息处理者应当及时采取措施予以更正、删除，但法律、行政法规另有规定的除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210072, '《中华人民共和国未成年人保护法》', '第七十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第五章 网络保护', NULL, '网络服务提供者发现未成年人通过网络发布私密信息的，应当及时提示，并采取必要的保护措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210073, '《中华人民共和国未成年人保护法》', '第七十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第五章 网络保护', NULL, '网络产品和服务提供者不得向未成年人提供诱导其沉迷的产品和服务。 网络游戏、网络直播、网络音视频、网络社交等网络服务提供者应当针对未成年人使用其服务设置相应的时间管理、权限管理、消费管理等功能。 以未成年人为服务对象的在线教育网络产品和服务，不得插入网络游戏链接，不得推送广告等与教学无关的信息。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210074, '《中华人民共和国未成年人保护法》', '第七十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第五章 网络保护', NULL, '网络游戏经依法审批后方可运营。 国家建立统一的未成年人网络游戏电子身份认证系统。网络游戏服务提供者应当要求未成年人以真实身份信息注册并登录网络游戏。 网络游戏服务提供者应当按照国家有关规定和标准，对游戏产品进行分类，作出适龄提示，并采取技术措施，不得让未成年人接触不适宜的游戏或者游戏功能。 网络游戏服务提供者不得在每日二十二时至次日八时向未成年人提供网络游戏服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210075, '《中华人民共和国未成年人保护法》', '第七十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第五章 网络保护', NULL, '网络直播服务提供者不得为未满十六周岁的未成年人提供网络直播发布者账号注册服务；为年满十六周岁的未成年人提供网络直播发布者账号注册服务时，应当对其身份信息进行认证，并征得其父母或者其他监护人同意。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210076, '《中华人民共和国未成年人保护法》', '第七十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第五章 网络保护', NULL, '任何组织或者个人不得通过网络以文字、图片、音视频等形式，对未成年人实施侮辱、诽谤、威胁或者恶意损害形象等网络欺凌行为。 遭受网络欺凌的未成年人及其父母或者其他监护人有权通知网络服务提供者采取删除、屏蔽、断开链接等措施。网络服务提供者接到通知后，应当及时采取必要的措施制止网络欺凌行为，防止信息扩散。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210077, '《中华人民共和国未成年人保护法》', '第七十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第五章 网络保护', NULL, '网络产品和服务提供者应当建立便捷、合理、有效的投诉和举报渠道，公开投诉、举报方式等信息，及时受理并处理涉及未成年人的投诉、举报。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210078, '《中华人民共和国未成年人保护法》', '第七十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第五章 网络保护', NULL, '任何组织或者个人发现网络产品、服务含有危害未成年人身心健康的信息，有权向网络产品和服务提供者或者网信、公安等部门投诉、举报。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210079, '《中华人民共和国未成年人保护法》', '第八十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第五章 网络保护', NULL, '网络服务提供者发现用户发布、传播可能影响未成年人身心健康的信息且未作显著提示的，应当作出提示或者通知用户予以提示；未作出提示的，不得传输相关信息。 网络服务提供者发现用户发布、传播含有危害未成年人身心健康内容的信息的，应当立即停止传输相关信息，采取删除、屏蔽、断开链接等处置措施，保存有关记录，并向网信、公安等部门报告。 网络服务提供者发现用户利用其网络服务对未成年人实施违法犯罪行为的，应当立即停止向该用户提供网络服务，保存有关记录，并向公安机关报告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210080, '《中华人民共和国未成年人保护法》', '第八十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第六章 政府保护', NULL, '县级以上人民政府承担未成年人保护协调机制具体工作的职能部门应当明确相关内设机构或者专门人员，负责承担未成年人保护工作。 乡镇人民政府和街道办事处应当设立未成年人保护工作站或者指定专门人员，及时办理未成年人相关事务；支持、指导居民委员会、村民委员会设立专人专岗，做好未成年人保护工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210081, '《中华人民共和国未成年人保护法》', '第八十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第六章 政府保护', NULL, '各级人民政府应当将家庭教育指导服务纳入城乡公共服务体系，开展家庭教育知识宣传，鼓励和支持有关人民团体、企业事业单位、社会组织开展家庭教育指导服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210082, '《中华人民共和国未成年人保护法》', '第八十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第六章 政府保护', NULL, '各级人民政府应当保障未成年人受教育的权利，并采取措施保障留守未成年人、困境未成年人、残疾未成年人接受义务教育。 对尚未完成义务教育的辍学未成年学生，教育行政部门应当责令父母或者其他监护人将其送入学校接受义务教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210083, '《中华人民共和国未成年人保护法》', '第八十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第六章 政府保护', NULL, '各级人民政府应当发展托育、学前教育事业，办好婴幼儿照护服务机构、幼儿园，支持社会力量依法兴办母婴室、婴幼儿照护服务机构、幼儿园。 县级以上地方人民政府及其有关部门应当培养和培训婴幼儿照护服务机构、幼儿园的保教人员，提高其职业道德素质和业务能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210084, '《中华人民共和国未成年人保护法》', '第八十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第六章 政府保护', NULL, '各级人民政府应当发展职业教育，保障未成年人接受职业教育或者职业技能培训，鼓励和支持人民团体、企业事业单位、社会组织为未成年人提供职业技能培训服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210085, '《中华人民共和国未成年人保护法》', '第八十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第六章 政府保护', NULL, '各级人民政府应当保障具有接受普通教育能力、能适应校园生活的残疾未成年人就近在普通学校、幼儿园接受教育；保障不具有接受普通教育能力的残疾未成年人在特殊教育学校、幼儿园接受学前教育、义务教育和职业教育。 各级人民政府应当保障特殊教育学校、幼儿园的办学、办园条件，鼓励和支持社会力量举办特殊教育学校、幼儿园。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210086, '《中华人民共和国未成年人保护法》', '第八十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第六章 政府保护', NULL, '地方人民政府及其有关部门应当保障校园安全，监督、指导学校、幼儿园等单位落实校园安全责任，建立突发事件的报告、处置和协调机制。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210087, '《中华人民共和国未成年人保护法》', '第八十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第六章 政府保护', NULL, '公安机关和其他有关部门应当依法维护校园周边的治安和交通秩序，设置监控设备和交通安全设施，预防和制止侵害未成年人的违法犯罪行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210088, '《中华人民共和国未成年人保护法》', '第八十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第六章 政府保护', NULL, '地方人民政府应当建立和改善适合未成年人的活动场所和设施，支持公益性未成年人活动场所和设施的建设和运行，鼓励社会力量兴办适合未成年人的活动场所和设施，并加强管理。 地方人民政府应当采取措施，鼓励和支持学校在国家法定节假日、休息日及寒暑假期将文化体育设施对未成年人免费或者优惠开放。 地方人民政府应当采取措施，防止任何组织或者个人侵占、破坏学校、幼儿园、婴幼儿照护服务机构等未成年人活动场所的场地、房屋和设施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210089, '《中华人民共和国未成年人保护法》', '第九十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第六章 政府保护', NULL, '各级人民政府及其有关部门应当对未成年人进行卫生保健和营养指导，提供卫生保健服务。 卫生健康部门应当依法对未成年人的疫苗预防接种进行规范，防治未成年人常见病、多发病，加强传染病防治和监督管理，做好伤害预防和干预，指导和监督学校、幼儿园、婴幼儿照护服务机构开展卫生保健工作。 教育行政部门应当加强未成年人的心理健康教育，建立未成年人心理问题的早期发现和及时干预机制。卫生健康部门应当做好未成年人心理治疗、心理危机干预以及精神障碍早期识别和诊断治疗等工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210090, '《中华人民共和国未成年人保护法》', '第九十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第六章 政府保护', NULL, '各级人民政府及其有关部门对困境未成年人实施分类保障，采取措施满足其生活、教育、安全、医疗康复、住房等方面的基本需要。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210091, '《中华人民共和国未成年人保护法》', '第九十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第六章 政府保护', NULL, '具有下列情形之一的，民政部门应当依法对未成年人进行临时监护： （一）未成年人流浪乞讨或者身份不明，暂时查找不到父母或者其他监护人； （二）监护人下落不明且无其他人可以担任监护人； （三）监护人因自身客观原因或者因发生自然灾害、事故灾难、公共卫生事件等突发事件不能履行监护职责，导致未成年人监护缺失； （四）监护人拒绝或者怠于履行监护职责，导致未成年人处于无人照料的状态； （五）监护人教唆、利用未成年人实施违法犯罪行为，未成年人需要被带离安置； （六）未成年人遭受监护人严重伤害或者面临人身安全威胁，需要被紧急安置； （七）法律规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210092, '《中华人民共和国未成年人保护法》', '第九十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第六章 政府保护', NULL, '对临时监护的未成年人，民政部门可以采取委托亲属抚养、家庭寄养等方式进行安置，也可以交由未成年人救助保护机构或者儿童福利机构进行收留、抚养。 临时监护期间，经民政部门评估，监护人重新具备履行监护职责条件的，民政部门可以将未成年人送回监护人抚养。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210093, '《中华人民共和国未成年人保护法》', '第九十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第六章 政府保护', NULL, '具有下列情形之一的，民政部门应当依法对未成年人进行长期监护： （一）查找不到未成年人的父母或者其他监护人； （二）监护人死亡或者被宣告死亡且无其他人可以担任监护人； （三）监护人丧失监护能力且无其他人可以担任监护人； （四）人民法院判决撤销监护人资格并指定由民政部门担任监护人； （五）法律规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210094, '《中华人民共和国未成年人保护法》', '第九十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第六章 政府保护', NULL, '民政部门进行收养评估后，可以依法将其长期监护的未成年人交由符合条件的申请人收养。收养关系成立后，民政部门与未成年人的监护关系终止。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210095, '《中华人民共和国未成年人保护法》', '第九十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第六章 政府保护', NULL, '民政部门承担临时监护或者长期监护职责的，财政、教育、卫生健康、公安等部门应当根据各自职责予以配合。 县级以上人民政府及其民政部门应当根据需要设立未成年人救助保护机构、儿童福利机构，负责收留、抚养由民政部门监护的未成年人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210096, '《中华人民共和国未成年人保护法》', '第九十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第六章 政府保护', NULL, '县级以上人民政府应当开通全国统一的未成年人保护热线，及时受理、转介侵犯未成年人合法权益的投诉、举报；鼓励和支持人民团体、企业事业单位、社会组织参与建设未成年人保护服务平台、服务热线、服务站点，提供未成年人保护方面的咨询、帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210097, '《中华人民共和国未成年人保护法》', '第九十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第六章 政府保护', NULL, '国家建立性侵害、虐待、拐卖、暴力伤害等违法犯罪人员信息查询系统，向密切接触未成年人的单位提供免费查询服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210098, '《中华人民共和国未成年人保护法》', '第九十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第六章 政府保护', NULL, '地方人民政府应当培育、引导和规范有关社会组织、社会工作者参与未成年人保护工作，开展家庭教育指导服务，为未成年人的心理辅导、康复救助、监护及收养评估等提供专业服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210099, '《中华人民共和国未成年人保护法》', '第一百条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第七章 司法保护', NULL, '公安机关、人民检察院、人民法院和司法行政部门应当依法履行职责，保障未成年人合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210100, '《中华人民共和国未成年人保护法》', '第一百零一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第七章 司法保护', NULL, '公安机关、人民检察院、人民法院和司法行政部门应当确定专门机构或者指定专门人员，负责办理涉及未成年人案件。办理涉及未成年人案件的人员应当经过专门培训，熟悉未成年人身心特点。专门机构或者专门人员中，应当有女性工作人员。 公安机关、人民检察院、人民法院和司法行政部门应当对上述机构和人员实行与未成年人保护工作相适应的评价考核标准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210101, '《中华人民共和国未成年人保护法》', '第一百零二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第七章 司法保护', NULL, '公安机关、人民检察院、人民法院和司法行政部门办理涉及未成年人案件，应当考虑未成年人身心特点和健康成长的需要，使用未成年人能够理解的语言和表达方式，听取未成年人的意见。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210102, '《中华人民共和国未成年人保护法》', '第一百零三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第七章 司法保护', NULL, '公安机关、人民检察院、人民法院、司法行政部门以及其他组织和个人不得披露有关案件中未成年人的姓名、影像、住所、就读学校以及其他可能识别出其身份的信息，但查找失踪、被拐卖未成年人等情形除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210103, '《中华人民共和国未成年人保护法》', '第一百零四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第七章 司法保护', NULL, '对需要法律援助或者司法救助的未成年人，法律援助机构或者公安机关、人民检察院、人民法院和司法行政部门应当给予帮助，依法为其提供法律援助或者司法救助。 法律援助机构应当指派熟悉未成年人身心特点的律师为未成年人提供法律援助服务。 法律援助机构和律师协会应当对办理未成年人法律援助案件的律师进行指导和培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210104, '《中华人民共和国未成年人保护法》', '第一百零五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第七章 司法保护', NULL, '人民检察院通过行使检察权，对涉及未成年人的诉讼活动等依法进行监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210105, '《中华人民共和国未成年人保护法》', '第一百零六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第七章 司法保护', NULL, '未成年人合法权益受到侵犯，相关组织和个人未代为提起诉讼的，人民检察院可以督促、支持其提起诉讼；涉及公共利益的，人民检察院有权提起公益诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210106, '《中华人民共和国未成年人保护法》', '第一百零七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第七章 司法保护', NULL, '人民法院审理继承案件，应当依法保护未成年人的继承权和受遗赠权。 人民法院审理离婚案件，涉及未成年子女抚养问题的，应当尊重已满八周岁未成年子女的真实意愿，根据双方具体情况，按照最有利于未成年子女的原则依法处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210107, '《中华人民共和国未成年人保护法》', '第一百零八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第七章 司法保护', NULL, '未成年人的父母或者其他监护人不依法履行监护职责或者严重侵犯被监护的未成年人合法权益的，人民法院可以根据有关人员或者单位的申请，依法作出人身安全保护令或者撤销监护人资格。 被撤销监护人资格的父母或者其他监护人应当依法继续负担抚养费用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210108, '《中华人民共和国未成年人保护法》', '第一百零九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第七章 司法保护', NULL, '人民法院审理离婚、抚养、收养、监护、探望等案件涉及未成年人的，可以自行或者委托社会组织对未成年人的相关情况进行社会调查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210109, '《中华人民共和国未成年人保护法》', '第一百一十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第七章 司法保护', NULL, '公安机关、人民检察院、人民法院讯问未成年犯罪嫌疑人、被告人，询问未成年被害人、证人，应当依法通知其法定代理人或者其成年亲属、所在学校的代表等合适成年人到场，并采取适当方式，在适当场所进行，保障未成年人的名誉权、隐私权和其他合法权益。 人民法院开庭审理涉及未成年人案件，未成年被害人、证人一般不出庭作证；必须出庭的，应当采取保护其隐私的技术手段和心理干预等保护措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210110, '《中华人民共和国未成年人保护法》', '第一百一十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第七章 司法保护', NULL, '公安机关、人民检察院、人民法院应当与其他有关政府部门、人民团体、社会组织互相配合，对遭受性侵害或者暴力伤害的未成年被害人及其家庭实施必要的心理干预、经济救助、法律援助、转学安置等保护措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210111, '《中华人民共和国未成年人保护法》', '第一百一十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第七章 司法保护', NULL, '公安机关、人民检察院、人民法院办理未成年人遭受性侵害或者暴力伤害案件，在询问未成年被害人、证人时，应当采取同步录音录像等措施，尽量一次完成；未成年被害人、证人是女性的，应当由女性工作人员进行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210112, '《中华人民共和国未成年人保护法》', '第一百一十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第七章 司法保护', NULL, '对违法犯罪的未成年人，实行教育、感化、挽救的方针，坚持教育为主、惩罚为辅的原则。 对违法犯罪的未成年人依法处罚后，在升学、就业等方面不得歧视。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210113, '《中华人民共和国未成年人保护法》', '第一百一十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第七章 司法保护', NULL, '公安机关、人民检察院、人民法院和司法行政部门发现有关单位未尽到未成年人教育、管理、救助、看护等保护职责的，应当向该单位提出建议。被建议单位应当在一个月内作出书面回复。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210114, '《中华人民共和国未成年人保护法》', '第一百一十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第七章 司法保护', NULL, '公安机关、人民检察院、人民法院和司法行政部门应当结合实际，根据涉及未成年人案件的特点，开展未成年人法治宣传教育工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210115, '《中华人民共和国未成年人保护法》', '第一百一十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第七章 司法保护', NULL, '国家鼓励和支持社会组织、社会工作者参与涉及未成年人案件中未成年人的心理干预、法律援助、社会调查、社会观护、教育矫治、社区矫正等工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210116, '《中华人民共和国未成年人保护法》', '第一百一十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第八章 法律责任', NULL, '违反本法第十一条第二款规定，未履行报告义务造成严重后果的，由上级主管部门或者所在单位对直接负责的主管人员和其他直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210117, '《中华人民共和国未成年人保护法》', '第一百一十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第八章 法律责任', NULL, '未成年人的父母或者其他监护人不依法履行监护职责或者侵犯未成年人合法权益的，由其居住地的居民委员会、村民委员会予以劝诫、制止；情节严重的，居民委员会、村民委员会应当及时向公安机关报告。 公安机关接到报告或者公安机关、人民检察院、人民法院在办理案件过程中发现未成年人的父母或者其他监护人存在上述情形的，应当予以训诫，并可以责令其接受家庭教育指导。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210118, '《中华人民共和国未成年人保护法》', '第一百一十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第八章 法律责任', NULL, '学校、幼儿园、婴幼儿照护服务等机构及其教职员工违反本法第二十七条、第二十八条、第三十九条规定的，由公安、教育、卫生健康、市场监督管理等部门按照职责分工责令改正；拒不改正或者情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210119, '《中华人民共和国未成年人保护法》', '第一百二十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第八章 法律责任', NULL, '违反本法第四十四条、第四十五条、第四十七条规定，未给予未成年人免费或者优惠待遇的，由市场监督管理、文化和旅游、交通运输等部门按照职责分工责令限期改正，给予警告；拒不改正的，处一万元以上十万元以下罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210120, '《中华人民共和国未成年人保护法》', '第一百二十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第八章 法律责任', NULL, '违反本法第五十条、第五十一条规定的，由新闻出版、广播电视、电影、网信等部门按照职责分工责令限期改正，给予警告，没收违法所得，可以并处十万元以下罚款；拒不改正或者情节严重的，责令暂停相关业务、停产停业或者吊销营业执照、吊销相关许可证，违法所得一百万元以上的，并处违法所得一倍以上十倍以下的罚款，没有违法所得或者违法所得不足一百万元的，并处十万元以上一百万元以下罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210121, '《中华人民共和国未成年人保护法》', '第一百二十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第八章 法律责任', NULL, '场所运营单位违反本法第五十六条第二款规定、住宿经营者违反本法第五十七条规定的，由市场监督管理、应急管理、公安等部门按照职责分工责令限期改正，给予警告；拒不改正或者造成严重后果的，责令停业整顿或者吊销营业执照、吊销相关许可证，并处一万元以上十万元以下罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210122, '《中华人民共和国未成年人保护法》', '第一百二十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第八章 法律责任', NULL, '相关经营者违反本法第五十八条、第五十九条第一款、第六十条规定的，由文化和旅游、市场监督管理、烟草专卖、公安等部门按照职责分工责令限期改正，给予警告，没收违法所得，可以并处五万元以下罚款；拒不改正或者情节严重的，责令停业整顿或者吊销营业执照、吊销相关许可证，可以并处五万元以上五十万元以下罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210123, '《中华人民共和国未成年人保护法》', '第一百二十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第八章 法律责任', NULL, '违反本法第五十九条第二款规定，在学校、幼儿园和其他未成年人集中活动的公共场所吸烟、饮酒的，由卫生健康、教育、市场监督管理等部门按照职责分工责令改正，给予警告，可以并处五百元以下罚款；场所管理者未及时制止的，由卫生健康、教育、市场监督管理等部门按照职责分工给予警告，并处一万元以下罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210124, '《中华人民共和国未成年人保护法》', '第一百二十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第八章 法律责任', NULL, '违反本法第六十一条规定的，由文化和旅游、人力资源和社会保障、市场监督管理等部门按照职责分工责令限期改正，给予警告，没收违法所得，可以并处十万元以下罚款；拒不改正或者情节严重的，责令停产停业或者吊销营业执照、吊销相关许可证，并处十万元以上一百万元以下罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210125, '《中华人民共和国未成年人保护法》', '第一百二十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第八章 法律责任', NULL, '密切接触未成年人的单位违反本法第六十二条规定，未履行查询义务，或者招用、继续聘用具有相关违法犯罪记录人员的，由教育、人力资源和社会保障、市场监督管理等部门按照职责分工责令限期改正，给予警告，并处五万元以下罚款；拒不改正或者造成严重后果的，责令停业整顿或者吊销营业执照、吊销相关许可证，并处五万元以上五十万元以下罚款，对直接负责的主管人员和其他直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210126, '《中华人民共和国未成年人保护法》', '第一百二十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第八章 法律责任', NULL, '信息处理者违反本法第七十二条规定，或者网络产品和服务提供者违反本法第七十三条、第七十四条、第七十五条、第七十六条、第七十七条、第八十条规定的，由公安、网信、电信、新闻出版、广播电视、文化和旅游等有关部门按照职责分工责令改正，给予警告，没收违法所得，违法所得一百万元以上的，并处违法所得一倍以上十倍以下罚款，没有违法所得或者违法所得不足一百万元的，并处十万元以上一百万元以下罚款，对直接负责的主管人员和其他责任人员处一万元以上十万元以下罚款；拒不改正或者情节严重的，并可以责令暂停相关业务、停业整顿、关闭网站、吊销营业执照或者吊销相关许可证。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210127, '《中华人民共和国未成年人保护法》', '第一百二十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第八章 法律责任', NULL, '国家机关工作人员玩忽职守、滥用职权、徇私舞弊，损害未成年人合法权益的，依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210128, '《中华人民共和国未成年人保护法》', '第一百二十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第八章 法律责任', NULL, '违反本法规定，侵犯未成年人合法权益，造成人身、财产或者其他损害的，依法承担民事责任。 违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210129, '《中华人民共和国未成年人保护法》', '第一百三十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第九章 附 则', NULL, '本法中下列用语的含义： （一）密切接触未成年人的单位，是指学校、幼儿园等教育机构；校外培训机构；未成年人救助保护机构、儿童福利机构等未成年人安置、救助机构；婴幼儿照护服务机构、早期教育服务机构；校外托管、临时看护机构；家政服务机构；为未成年人提供医疗服务的医疗机构；其他对未成年人负有教育、培训、监护、救助、看护、医疗等职责的企业事业单位、社会组织等。 （二）学校，是指普通中小学、特殊教育学校、中等职业学校、专门学校。 （三）学生欺凌，是指发生在学生之间，一方蓄意或者恶意通过肢体、语言及网络等手段实施欺压、侮辱，造成另一方人身伤害、财产损失或者精神损害的行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210130, '《中华人民共和国未成年人保护法》', '第一百三十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第九章 附 则', NULL, '对中国境内未满十八周岁的外国人、无国籍人，依照本法有关规定予以保护。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (210131, '《中华人民共和国未成年人保护法》', '第一百三十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-04-26', '第九章 附 则', NULL, '本法自2021年6月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211000, '《中华人民共和国预防未成年人犯罪法》', '第一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第一章 总 则', NULL, '为了保障未成年人身心健康，培养未成年人良好品行，有效预防未成年人违法犯罪，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211001, '《中华人民共和国预防未成年人犯罪法》', '第二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第一章 总 则', NULL, '预防未成年人犯罪，立足于教育和保护未成年人相结合，坚持预防为主、提前干预，对未成年人的不良行为和严重不良行为及时进行分级预防、干预和矫治。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211002, '《中华人民共和国预防未成年人犯罪法》', '第三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第一章 总 则', NULL, '开展预防未成年人犯罪工作，应当尊重未成年人人格尊严，保护未成年人的名誉权、隐私权和个人信息等合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211003, '《中华人民共和国预防未成年人犯罪法》', '第四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第一章 总 则', NULL, '预防未成年人犯罪，在各级人民政府组织下，实行综合治理。 国家机关、人民团体、社会组织、企业事业单位、居民委员会、村民委员会、学校、家庭等各负其责、相互配合，共同做好预防未成年人犯罪工作，及时消除滋生未成年人违法犯罪行为的各种消极因素，为未成年人身心健康发展创造良好的社会环境。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211004, '《中华人民共和国预防未成年人犯罪法》', '第五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第一章 总 则', NULL, '各级人民政府在预防未成年人犯罪方面的工作职责是： （一）制定预防未成年人犯罪工作规划； （二）组织公安、教育、民政、文化和旅游、市场监督管理、网信、卫生健康、新闻出版、电影、广播电视、司法行政等有关部门开展预防未成年人犯罪工作； （三）为预防未成年人犯罪工作提供政策支持和经费保障； （四）对本法的实施情况和工作规划的执行情况进行检查； （五）组织开展预防未成年人犯罪宣传教育； （六）其他预防未成年人犯罪工作职责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211005, '《中华人民共和国预防未成年人犯罪法》', '第六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第一章 总 则', NULL, '国家加强专门学校建设，对有严重不良行为的未成年人进行专门教育。专门教育是国民教育体系的组成部分，是对有严重不良行为的未成年人进行教育和矫治的重要保护处分措施。 省级人民政府应当将专门教育发展和专门学校建设纳入经济社会发展规划。县级以上地方人民政府成立专门教育指导委员会，根据需要合理设置专门学校。 专门教育指导委员会由教育、民政、财政、人力资源社会保障、公安、司法行政、人民检察院、人民法院、共产主义青年团、妇女联合会、关心下一代工作委员会、专门学校等单位，以及律师、社会工作者等人员组成，研究确定专门学校教学、管理等相关工作。 专门学校建设和专门教育具体办法，由国务院规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211006, '《中华人民共和国预防未成年人犯罪法》', '第七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第一章 总 则', NULL, '公安机关、人民检察院、人民法院、司法行政部门应当由专门机构或者经过专业培训、熟悉未成年人身心特点的专门人员负责预防未成年人犯罪工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211007, '《中华人民共和国预防未成年人犯罪法》', '第八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第一章 总 则', NULL, '共产主义青年团、妇女联合会、工会、残疾人联合会、关心下一代工作委员会、青年联合会、学生联合会、少年先锋队以及有关社会组织，应当协助各级人民政府及其有关部门、人民检察院和人民法院做好预防未成年人犯罪工作，为预防未成年人犯罪培育社会力量，提供支持服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211008, '《中华人民共和国预防未成年人犯罪法》', '第九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第一章 总 则', NULL, '国家鼓励、支持和指导社会工作服务机构等社会组织参与预防未成年人犯罪相关工作，并加强监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211009, '《中华人民共和国预防未成年人犯罪法》', '第十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第一章 总 则', NULL, '任何组织或者个人不得教唆、胁迫、引诱未成年人实施不良行为或者严重不良行为，以及为未成年人实施上述行为提供条件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211010, '《中华人民共和国预防未成年人犯罪法》', '第十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第一章 总 则', NULL, '未成年人应当遵守法律法规及社会公共道德规范，树立自尊、自律、自强意识，增强辨别是非和自我保护的能力，自觉抵制各种不良行为以及违法犯罪行为的引诱和侵害。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211011, '《中华人民共和国预防未成年人犯罪法》', '第十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第一章 总 则', NULL, '预防未成年人犯罪，应当结合未成年人不同年龄的生理、心理特点，加强青春期教育、心理关爱、心理矫治和预防犯罪对策的研究。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211012, '《中华人民共和国预防未成年人犯罪法》', '第十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第一章 总 则', NULL, '国家鼓励和支持预防未成年人犯罪相关学科建设、专业设置、人才培养及科学研究，开展国际交流与合作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211013, '《中华人民共和国预防未成年人犯罪法》', '第十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第一章 总 则', NULL, '国家对预防未成年人犯罪工作有显著成绩的组织和个人，给予表彰和奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211014, '《中华人民共和国预防未成年人犯罪法》', '第十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第二章 预防犯罪的教育', NULL, '国家、社会、学校和家庭应当对未成年人加强社会主义核心价值观教育，开展预防犯罪教育，增强未成年人的法治观念，使未成年人树立遵纪守法和防范违法犯罪的意识，提高自我管控能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211015, '《中华人民共和国预防未成年人犯罪法》', '第十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第二章 预防犯罪的教育', NULL, '未成年人的父母或者其他监护人对未成年人的预防犯罪教育负有直接责任，应当依法履行监护职责，树立优良家风，培养未成年人良好品行；发现未成年人心理或者行为异常的，应当及时了解情况并进行教育、引导和劝诫，不得拒绝或者怠于履行监护职责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211016, '《中华人民共和国预防未成年人犯罪法》', '第十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第二章 预防犯罪的教育', NULL, '教育行政部门、学校应当将预防犯罪教育纳入学校教学计划，指导教职员工结合未成年人的特点，采取多种方式对未成年学生进行有针对性的预防犯罪教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211017, '《中华人民共和国预防未成年人犯罪法》', '第十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第二章 预防犯罪的教育', NULL, '学校应当聘任从事法治教育的专职或者兼职教师，并可以从司法和执法机关、法学教育和法律服务机构等单位聘请法治副校长、校外法治辅导员。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211018, '《中华人民共和国预防未成年人犯罪法》', '第十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第二章 预防犯罪的教育', NULL, '学校应当配备专职或者兼职的心理健康教育教师，开展心理健康教育。学校可以根据实际情况与专业心理健康机构合作，建立心理健康筛查和早期干预机制，预防和解决学生心理、行为异常问题。 学校应当与未成年学生的父母或者其他监护人加强沟通，共同做好未成年学生心理健康教育；发现未成年学生可能患有精神障碍的，应当立即告知其父母或者其他监护人送相关专业机构诊治。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211019, '《中华人民共和国预防未成年人犯罪法》', '第二十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第二章 预防犯罪的教育', NULL, '教育行政部门应当会同有关部门建立学生欺凌防控制度。学校应当加强日常安全管理，完善学生欺凌发现和处置的工作流程，严格排查并及时消除可能导致学生欺凌行为的各种隐患。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211020, '《中华人民共和国预防未成年人犯罪法》', '第二十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第二章 预防犯罪的教育', NULL, '教育行政部门鼓励和支持学校聘请社会工作者长期或者定期进驻学校，协助开展道德教育、法治教育、生命教育和心理健康教育，参与预防和处理学生欺凌等行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211021, '《中华人民共和国预防未成年人犯罪法》', '第二十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第二章 预防犯罪的教育', NULL, '教育行政部门、学校应当通过举办讲座、座谈、培训等活动，介绍科学合理的教育方法，指导教职员工、未成年学生的父母或者其他监护人有效预防未成年人犯罪。 学校应当将预防犯罪教育计划告知未成年学生的父母或者其他监护人。未成年学生的父母或者其他监护人应当配合学校对未成年学生进行有针对性的预防犯罪教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211022, '《中华人民共和国预防未成年人犯罪法》', '第二十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第二章 预防犯罪的教育', NULL, '教育行政部门应当将预防犯罪教育的工作效果纳入学校年度考核内容。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211023, '《中华人民共和国预防未成年人犯罪法》', '第二十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第二章 预防犯罪的教育', NULL, '各级人民政府及其有关部门、人民检察院、人民法院、共产主义青年团、少年先锋队、妇女联合会、残疾人联合会、关心下一代工作委员会等应当结合实际，组织、举办多种形式的预防未成年人犯罪宣传教育活动。有条件的地方可以建立青少年法治教育基地，对未成年人开展法治教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211024, '《中华人民共和国预防未成年人犯罪法》', '第二十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第二章 预防犯罪的教育', NULL, '居民委员会、村民委员会应当积极开展有针对性的预防未成年人犯罪宣传活动，协助公安机关维护学校周围治安，及时掌握本辖区内未成年人的监护、就学和就业情况，组织、引导社区社会组织参与预防未成年人犯罪工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211025, '《中华人民共和国预防未成年人犯罪法》', '第二十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第二章 预防犯罪的教育', NULL, '青少年宫、儿童活动中心等校外活动场所应当把预防犯罪教育作为一项重要的工作内容，开展多种形式的宣传教育活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211026, '《中华人民共和国预防未成年人犯罪法》', '第二十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第二章 预防犯罪的教育', NULL, '职业培训机构、用人单位在对已满十六周岁准备就业的未成年人进行职业培训时，应当将预防犯罪教育纳入培训内容。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211027, '《中华人民共和国预防未成年人犯罪法》', '第二十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第三章 对不良行为的干预', NULL, '本法所称不良行为，是指未成年人实施的不利于其健康成长的下列行为： （一）吸烟、饮酒； （二）多次旷课、逃学； （三）无故夜不归宿、离家出走； （四）沉迷网络； （五）与社会上具有不良习性的人交往，组织或者参加实施不良行为的团伙； （六）进入法律法规规定未成年人不宜进入的场所； （七）参与赌博、变相赌博，或者参加封建迷信、邪教等活动； （八）阅览、观看或者收听宣扬淫秽、色情、暴力、恐怖、极端等内容的读物、音像制品或者网络信息等； （九）其他不利于未成年人身心健康成长的不良行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211028, '《中华人民共和国预防未成年人犯罪法》', '第二十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第三章 对不良行为的干预', NULL, '未成年人的父母或者其他监护人发现未成年人有不良行为的，应当及时制止并加强管教。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211029, '《中华人民共和国预防未成年人犯罪法》', '第三十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第三章 对不良行为的干预', NULL, '公安机关、居民委员会、村民委员会发现本辖区内未成年人有不良行为的，应当及时制止，并督促其父母或者其他监护人依法履行监护职责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211030, '《中华人民共和国预防未成年人犯罪法》', '第三十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第三章 对不良行为的干预', NULL, '学校对有不良行为的未成年学生，应当加强管理教育，不得歧视；对拒不改正或者情节严重的，学校可以根据情况予以处分或者采取以下管理教育措施： （一）予以训导； （二）要求遵守特定的行为规范； （三）要求参加特定的专题教育； （四）要求参加校内服务活动； （五）要求接受社会工作者或者其他专业人员的心理辅导和行为干预； （六）其他适当的管理教育措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211031, '《中华人民共和国预防未成年人犯罪法》', '第三十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第三章 对不良行为的干预', NULL, '学校和家庭应当加强沟通，建立家校合作机制。学校决定对未成年学生采取管理教育措施的，应当及时告知其父母或者其他监护人；未成年学生的父母或者其他监护人应当支持、配合学校进行管理教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211032, '《中华人民共和国预防未成年人犯罪法》', '第三十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第三章 对不良行为的干预', NULL, '未成年学生偷窃少量财物，或者有殴打、辱骂、恐吓、强行索要财物等学生欺凌行为，情节轻微的，可以由学校依照本法第三十一条规定采取相应的管理教育措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211033, '《中华人民共和国预防未成年人犯罪法》', '第三十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第三章 对不良行为的干预', NULL, '未成年学生旷课、逃学的，学校应当及时联系其父母或者其他监护人，了解有关情况；无正当理由的，学校和未成年学生的父母或者其他监护人应当督促其返校学习。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211034, '《中华人民共和国预防未成年人犯罪法》', '第三十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第三章 对不良行为的干预', NULL, '未成年人无故夜不归宿、离家出走的，父母或者其他监护人、所在的寄宿制学校应当及时查找，必要时向公安机关报告。 收留夜不归宿、离家出走未成年人的，应当及时联系其父母或者其他监护人、所在学校；无法取得联系的，应当及时向公安机关报告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211035, '《中华人民共和国预防未成年人犯罪法》', '第三十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第三章 对不良行为的干预', NULL, '对夜不归宿、离家出走或者流落街头的未成年人，公安机关、公共场所管理机构等发现或者接到报告后，应当及时采取有效保护措施，并通知其父母或者其他监护人、所在的寄宿制学校，必要时应当护送其返回住所、学校；无法与其父母或者其他监护人、学校取得联系的，应当护送未成年人到救助保护机构接受救助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211036, '《中华人民共和国预防未成年人犯罪法》', '第三十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第三章 对不良行为的干预', NULL, '未成年人的父母或者其他监护人、学校发现未成年人组织或者参加实施不良行为的团伙，应当及时制止；发现该团伙有违法犯罪嫌疑的，应当立即向公安机关报告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211037, '《中华人民共和国预防未成年人犯罪法》', '第三十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第四章 对严重不良行为的矫治', NULL, '本法所称严重不良行为，是指未成年人实施的有刑法规定、因不满法定刑事责任年龄不予刑事处罚的行为，以及严重危害社会的下列行为： （一）结伙斗殴，追逐、拦截他人，强拿硬要或者任意损毁、占用公私财物等寻衅滋事行为； （二）非法携带枪支、弹药或者弩、匕首等国家规定的管制器具； （三）殴打、辱骂、恐吓，或者故意伤害他人身体； （四）盗窃、哄抢、抢夺或者故意损毁公私财物； （五）传播淫秽的读物、音像制品或者信息等； （六）卖淫、嫖娼，或者进行淫秽表演； （七）吸食、注射毒品，或者向他人提供毒品； （八）参与赌博赌资较大； （九）其他严重危害社会的行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211038, '《中华人民共和国预防未成年人犯罪法》', '第三十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第四章 对严重不良行为的矫治', NULL, '未成年人的父母或者其他监护人、学校、居民委员会、村民委员会发现有人教唆、胁迫、引诱未成年人实施严重不良行为的，应当立即向公安机关报告。公安机关接到报告或者发现有上述情形的，应当及时依法查处；对人身安全受到威胁的未成年人，应当立即采取有效保护措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211039, '《中华人民共和国预防未成年人犯罪法》', '第四十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第四章 对严重不良行为的矫治', NULL, '公安机关接到举报或者发现未成年人有严重不良行为的，应当及时制止，依法调查处理，并可以责令其父母或者其他监护人消除或者减轻违法后果，采取措施严加管教。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211040, '《中华人民共和国预防未成年人犯罪法》', '第四十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第四章 对严重不良行为的矫治', NULL, '对有严重不良行为的未成年人，公安机关可以根据具体情况，采取以下矫治教育措施： （一）予以训诫； （二）责令赔礼道歉、赔偿损失； （三）责令具结悔过； （四）责令定期报告活动情况； （五）责令遵守特定的行为规范，不得实施特定行为、接触特定人员或者进入特定场所； （六）责令接受心理辅导、行为矫治； （七）责令参加社会服务活动； （八）责令接受社会观护，由社会组织、有关机构在适当场所对未成年人进行教育、监督和管束； （九）其他适当的矫治教育措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211041, '《中华人民共和国预防未成年人犯罪法》', '第四十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第四章 对严重不良行为的矫治', NULL, '公安机关在对未成年人进行矫治教育时，可以根据需要邀请学校、居民委员会、村民委员会以及社会工作服务机构等社会组织参与。 未成年人的父母或者其他监护人应当积极配合矫治教育措施的实施，不得妨碍阻挠或者放任不管。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211042, '《中华人民共和国预防未成年人犯罪法》', '第四十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第四章 对严重不良行为的矫治', NULL, '对有严重不良行为的未成年人，未成年人的父母或者其他监护人、所在学校无力管教或者管教无效的，可以向教育行政部门提出申请，经专门教育指导委员会评估同意后，由教育行政部门决定送入专门学校接受专门教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211043, '《中华人民共和国预防未成年人犯罪法》', '第四十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第四章 对严重不良行为的矫治', NULL, '未成年人有下列情形之一的，经专门教育指导委员会评估同意，教育行政部门会同公安机关可以决定将其送入专门学校接受专门教育： （一）实施严重危害社会的行为，情节恶劣或者造成严重后果； （二）多次实施严重危害社会的行为； （三）拒不接受或者配合本法第四十一条规定的矫治教育措施； （四）法律、行政法规规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211044, '《中华人民共和国预防未成年人犯罪法》', '第四十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第四章 对严重不良行为的矫治', NULL, '未成年人实施刑法规定的行为、因不满法定刑事责任年龄不予刑事处罚的，经专门教育指导委员会评估同意，教育行政部门会同公安机关可以决定对其进行专门矫治教育。 省级人民政府应当结合本地的实际情况，至少确定一所专门学校按照分校区、分班级等方式设置专门场所，对前款规定的未成年人进行专门矫治教育。 前款规定的专门场所实行闭环管理，公安机关、司法行政部门负责未成年人的矫治工作，教育行政部门承担未成年人的教育工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211045, '《中华人民共和国预防未成年人犯罪法》', '第四十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第四章 对严重不良行为的矫治', NULL, '专门学校应当在每个学期适时提请专门教育指导委员会对接受专门教育的未成年学生的情况进行评估。对经评估适合转回普通学校就读的，专门教育指导委员会应当向原决定机关提出书面建议，由原决定机关决定是否将未成年学生转回普通学校就读。 原决定机关决定将未成年学生转回普通学校的，其原所在学校不得拒绝接收；因特殊情况，不适宜转回原所在学校的，由教育行政部门安排转学。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211046, '《中华人民共和国预防未成年人犯罪法》', '第四十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第四章 对严重不良行为的矫治', NULL, '专门学校应当对接受专门教育的未成年人分级分类进行教育和矫治，有针对性地开展道德教育、法治教育、心理健康教育，并根据实际情况进行职业教育；对没有完成义务教育的未成年人，应当保证其继续接受义务教育。 专门学校的未成年学生的学籍保留在原学校，符合毕业条件的，原学校应当颁发毕业证书。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211047, '《中华人民共和国预防未成年人犯罪法》', '第四十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第四章 对严重不良行为的矫治', NULL, '专门学校应当与接受专门教育的未成年人的父母或者其他监护人加强联系，定期向其反馈未成年人的矫治和教育情况，为父母或者其他监护人、亲属等看望未成年人提供便利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211048, '《中华人民共和国预防未成年人犯罪法》', '第四十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第四章 对严重不良行为的矫治', NULL, '未成年人及其父母或者其他监护人对本章规定的行政决定不服的，可以依法提起行政复议或者行政诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211049, '《中华人民共和国预防未成年人犯罪法》', '第五十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第五章 对重新犯罪的预防', NULL, '公安机关、人民检察院、人民法院办理未成年人刑事案件，应当根据未成年人的生理、心理特点和犯罪的情况，有针对性地进行法治教育。 对涉及刑事案件的未成年人进行教育，其法定代理人以外的成年亲属或者教师、辅导员等参与有利于感化、挽救未成年人的，公安机关、人民检察院、人民法院应当邀请其参加有关活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211050, '《中华人民共和国预防未成年人犯罪法》', '第五十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第五章 对重新犯罪的预防', NULL, '公安机关、人民检察院、人民法院办理未成年人刑事案件，可以自行或者委托有关社会组织、机构对未成年犯罪嫌疑人或者被告人的成长经历、犯罪原因、监护、教育等情况进行社会调查；根据实际需要并经未成年犯罪嫌疑人、被告人及其法定代理人同意，可以对未成年犯罪嫌疑人、被告人进行心理测评。 社会调查和心理测评的报告可以作为办理案件和教育未成年人的参考。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211051, '《中华人民共和国预防未成年人犯罪法》', '第五十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第五章 对重新犯罪的预防', NULL, '公安机关、人民检察院、人民法院对于无固定住所、无法提供保证人的未成年人适用取保候审的，应当指定合适成年人作为保证人，必要时可以安排取保候审的未成年人接受社会观护。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211052, '《中华人民共和国预防未成年人犯罪法》', '第五十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第五章 对重新犯罪的预防', NULL, '对被拘留、逮捕以及在未成年犯管教所执行刑罚的未成年人，应当与成年人分别关押、管理和教育。对未成年人的社区矫正，应当与成年人分别进行。 对有上述情形且没有完成义务教育的未成年人，公安机关、人民检察院、人民法院、司法行政部门应当与教育行政部门相互配合，保证其继续接受义务教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211053, '《中华人民共和国预防未成年人犯罪法》', '第五十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第五章 对重新犯罪的预防', NULL, '未成年犯管教所、社区矫正机构应当对未成年犯、未成年社区矫正对象加强法治教育，并根据实际情况对其进行职业教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211054, '《中华人民共和国预防未成年人犯罪法》', '第五十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第五章 对重新犯罪的预防', NULL, '社区矫正机构应当告知未成年社区矫正对象安置帮教的有关规定，并配合安置帮教工作部门落实或者解决未成年社区矫正对象的就学、就业等问题。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211055, '《中华人民共和国预防未成年人犯罪法》', '第五十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第五章 对重新犯罪的预防', NULL, '对刑满释放的未成年人，未成年犯管教所应当提前通知其父母或者其他监护人按时接回，并协助落实安置帮教措施。没有父母或者其他监护人、无法查明其父母或者其他监护人的，未成年犯管教所应当提前通知未成年人原户籍所在地或者居住地的司法行政部门安排人员按时接回，由民政部门或者居民委员会、村民委员会依法对其进行监护。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211056, '《中华人民共和国预防未成年人犯罪法》', '第五十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第五章 对重新犯罪的预防', NULL, '未成年人的父母或者其他监护人和学校、居民委员会、村民委员会对接受社区矫正、刑满释放的未成年人，应当采取有效的帮教措施，协助司法机关以及有关部门做好安置帮教工作。 居民委员会、村民委员会可以聘请思想品德优秀，作风正派，热心未成年人工作的离退休人员、志愿者或其他人员协助做好前款规定的安置帮教工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211057, '《中华人民共和国预防未成年人犯罪法》', '第五十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第五章 对重新犯罪的预防', NULL, '刑满释放和接受社区矫正的未成年人，在复学、升学、就业等方面依法享有与其他未成年人同等的权利，任何单位和个人不得歧视。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211058, '《中华人民共和国预防未成年人犯罪法》', '第五十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第五章 对重新犯罪的预防', NULL, '未成年人的犯罪记录依法被封存的，公安机关、人民检察院、人民法院和司法行政部门不得向任何单位或者个人提供，但司法机关因办案需要或者有关单位根据国家有关规定进行查询的除外。依法进行查询的单位和个人应当对相关记录信息予以保密。 未成年人接受专门矫治教育、专门教育的记录，以及被行政处罚、采取刑事强制措施和不起诉的记录，适用前款规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211059, '《中华人民共和国预防未成年人犯罪法》', '第六十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第五章 对重新犯罪的预防', NULL, '人民检察院通过依法行使检察权，对未成年人重新犯罪预防工作等进行监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211060, '《中华人民共和国预防未成年人犯罪法》', '第六十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第六章 法律责任', NULL, '公安机关、人民检察院、人民法院在办理案件过程中发现实施严重不良行为的未成年人的父母或者其他监护人不依法履行监护职责的，应当予以训诫，并可以责令其接受家庭教育指导。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211061, '《中华人民共和国预防未成年人犯罪法》', '第六十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第六章 法律责任', NULL, '学校及其教职员工违反本法规定，不履行预防未成年人犯罪工作职责，或者虐待、歧视相关未成年人的，由教育行政等部门责令改正，通报批评；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。构成违反治安管理行为的，由公安机关依法予以治安管理处罚。 教职员工教唆、胁迫、引诱未成年人实施不良行为或者严重不良行为，以及品行不良、影响恶劣的，教育行政部门、学校应当依法予以解聘或者辞退。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211062, '《中华人民共和国预防未成年人犯罪法》', '第六十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第六章 法律责任', NULL, '违反本法规定，在复学、升学、就业等方面歧视相关未成年人的，由所在单位或者教育、人力资源社会保障等部门责令改正；拒不改正的，对直接负责的主管人员或者其他直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211063, '《中华人民共和国预防未成年人犯罪法》', '第六十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第六章 法律责任', NULL, '有关社会组织、机构及其工作人员虐待、歧视接受社会观护的未成年人，或者出具虚假社会调查、心理测评报告的，由民政、司法行政等部门对直接负责的主管人员或者其他直接责任人员依法给予处分，构成违反治安管理行为的，由公安机关予以治安管理处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211064, '《中华人民共和国预防未成年人犯罪法》', '第六十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第六章 法律责任', NULL, '教唆、胁迫、引诱未成年人实施不良行为或者严重不良行为，构成违反治安管理行为的，由公安机关依法予以治安管理处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211065, '《中华人民共和国预防未成年人犯罪法》', '第六十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第六章 法律责任', NULL, '国家机关及其工作人员在预防未成年人犯罪工作中滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员，依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211066, '《中华人民共和国预防未成年人犯罪法》', '第六十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第六章 法律责任', NULL, '违反本法规定，构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (211067, '《中华人民共和国预防未成年人犯罪法》', '第六十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-12-26', '第七章 附 则', NULL, '本法自2021年6月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212000, '《中华人民共和国老年人权益保障法》', '第一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '为了保障老年人合法权益，发展老龄事业，弘扬中华民族敬老、养老、助老的美德，根据宪法，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212001, '《中华人民共和国老年人权益保障法》', '第二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '本法所称老年人是指六十周岁以上的公民。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212002, '《中华人民共和国老年人权益保障法》', '第三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '国家保障老年人依法享有的权益。 老年人有从国家和社会获得物质帮助的权利，有享受社会服务和社会优待的权利，有参与社会发展和共享发展成果的权利。 禁止歧视、侮辱、虐待或者遗弃老年人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212003, '《中华人民共和国老年人权益保障法》', '第四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '积极应对人口老龄化是国家的一项长期战略任务。 国家和社会应当采取措施，健全保障老年人权益的各项制度，逐步改善保障老年人生活、健康、安全以及参与社会发展的条件，实现老有所养、老有所医、老有所为、老有所学、老有所乐。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212004, '《中华人民共和国老年人权益保障法》', '第五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '国家建立多层次的社会保障体系，逐步提高对老年人的保障水平。 国家建立和完善以居家为基础、社区为依托、机构为支撑的社会养老服务体系。 倡导全社会优待老年人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212005, '《中华人民共和国老年人权益保障法》', '第六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '各级人民政府应当将老龄事业纳入国民经济和社会发展规划，将老龄事业经费列入财政预算，建立稳定的经费保障机制，并鼓励社会各方面投入，使老龄事业与经济、社会协调发展。 国务院制定国家老龄事业发展规划。县级以上地方人民政府根据国家老龄事业发展规划，制定本行政区域的老龄事业发展规划和年度计划。 县级以上人民政府负责老龄工作的机构，负责组织、协调、指导、督促有关部门做好老年人权益保障工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212006, '《中华人民共和国老年人权益保障法》', '第七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '保障老年人合法权益是全社会的共同责任。 国家机关、社会团体、企业事业单位和其他组织应当按照各自职责，做好老年人权益保障工作。 基层群众性自治组织和依法设立的老年人组织应当反映老年人的要求，维护老年人合法权益，为老年人服务。 提倡、鼓励义务为老年人服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212007, '《中华人民共和国老年人权益保障法》', '第八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '国家进行人口老龄化国情教育，增强全社会积极应对人口老龄化意识。 全社会应当广泛开展敬老、养老、助老宣传教育活动，树立尊重、关心、帮助老年人的社会风尚。 青少年组织、学校和幼儿园应当对青少年和儿童进行敬老、养老、助老的道德教育和维护老年人合法权益的法制教育。 广播、电影、电视、报刊、网络等应当反映老年人的生活，开展维护老年人合法权益的宣传，为老年人服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212008, '《中华人民共和国老年人权益保障法》', '第九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '国家支持老龄科学研究，建立老年人状况统计调查和发布制度。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212009, '《中华人民共和国老年人权益保障法》', '第十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '各级人民政府和有关部门对维护老年人合法权益和敬老、养老、助老成绩显著的组织、家庭或者个人，对参与社会发展做出突出贡献的老年人，按照国家有关规定给予表彰或者奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212010, '《中华人民共和国老年人权益保障法》', '第十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '老年人应当遵纪守法，履行法律规定的义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212011, '《中华人民共和国老年人权益保障法》', '第十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第一章 总 则', NULL, '每年农历九月初九为老年节。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212012, '《中华人民共和国老年人权益保障法》', '第十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 家庭赡养与扶养', NULL, '老年人养老以居家为基础，家庭成员应当尊重、关心和照料老年人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212013, '《中华人民共和国老年人权益保障法》', '第十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 家庭赡养与扶养', NULL, '赡养人应当履行对老年人经济上供养、生活上照料和精神上慰藉的义务，照顾老年人的特殊需要。 赡养人是指老年人的子女以及其他依法负有赡养义务的人。 赡养人的配偶应当协助赡养人履行赡养义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212014, '《中华人民共和国老年人权益保障法》', '第十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 家庭赡养与扶养', NULL, '赡养人应当使患病的老年人及时得到治疗和护理；对经济困难的老年人，应当提供医疗费用。 对生活不能自理的老年人，赡养人应当承担照料责任；不能亲自照料的，可以按照老年人的意愿委托他人或者养老机构等照料。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212015, '《中华人民共和国老年人权益保障法》', '第十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 家庭赡养与扶养', NULL, '赡养人应当妥善安排老年人的住房，不得强迫老年人居住或者迁居条件低劣的房屋。 老年人自有的或者承租的住房，子女或者其他亲属不得侵占，不得擅自改变产权关系或者租赁关系。 老年人自有的住房，赡养人有维修的义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212016, '《中华人民共和国老年人权益保障法》', '第十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 家庭赡养与扶养', NULL, '赡养人有义务耕种或者委托他人耕种老年人承包的田地，照管或者委托他人照管老年人的林木和牲畜等，收益归老年人所有。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212017, '《中华人民共和国老年人权益保障法》', '第十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 家庭赡养与扶养', NULL, '家庭成员应当关心老年人的精神需求，不得忽视、冷落老年人。 与老年人分开居住的家庭成员，应当经常看望或者问候老年人。 用人单位应当按照国家有关规定保障赡养人探亲休假的权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212018, '《中华人民共和国老年人权益保障法》', '第十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 家庭赡养与扶养', NULL, '赡养人不得以放弃继承权或者其他理由，拒绝履行赡养义务。 赡养人不履行赡养义务，老年人有要求赡养人付给赡养费等权利。 赡养人不得要求老年人承担力不能及的劳动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212019, '《中华人民共和国老年人权益保障法》', '第二十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 家庭赡养与扶养', NULL, '经老年人同意，赡养人之间可以就履行赡养义务签订协议。赡养协议的内容不得违反法律的规定和老年人的意愿。 基层群众性自治组织、老年人组织或者赡养人所在单位监督协议的履行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212020, '《中华人民共和国老年人权益保障法》', '第二十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 家庭赡养与扶养', NULL, '老年人的婚姻自由受法律保护。子女或者其他亲属不得干涉老年人离婚、再婚及婚后的生活。 赡养人的赡养义务不因老年人的婚姻关系变化而消除。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212021, '《中华人民共和国老年人权益保障法》', '第二十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 家庭赡养与扶养', NULL, '老年人对个人的财产，依法享有占有、使用、收益和处分的权利，子女或者其他亲属不得干涉，不得以窃取、骗取、强行索取等方式侵犯老年人的财产权益。 老年人有依法继承父母、配偶、子女或者其他亲属遗产的权利，有接受赠与的权利。子女或者其他亲属不得侵占、抢夺、转移、隐匿或者损毁应当由老年人继承或者接受赠与的财产。 老年人以遗嘱处分财产，应当依法为老年配偶保留必要的份额。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212022, '《中华人民共和国老年人权益保障法》', '第二十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 家庭赡养与扶养', NULL, '老年人与配偶有相互扶养的义务。 由兄、姐扶养的弟、妹成年后，有负担能力的，对年老无赡养人的兄、姐有扶养的义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212023, '《中华人民共和国老年人权益保障法》', '第二十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 家庭赡养与扶养', NULL, '赡养人、扶养人不履行赡养、扶养义务的，基层群众性自治组织、老年人组织或者赡养人、扶养人所在单位应当督促其履行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212024, '《中华人民共和国老年人权益保障法》', '第二十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 家庭赡养与扶养', NULL, '禁止对老年人实施家庭暴力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212025, '《中华人民共和国老年人权益保障法》', '第二十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 家庭赡养与扶养', NULL, '具备完全民事行为能力的老年人，可以在近亲属或者其他与自己关系密切、愿意承担监护责任的个人、组织中协商确定自己的监护人。监护人在老年人丧失或者部分丧失民事行为能力时，依法承担监护责任。 老年人未事先确定监护人的，其丧失或者部分丧失民事行为能力时，依照有关法律的规定确定监护人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212026, '《中华人民共和国老年人权益保障法》', '第二十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第二章 家庭赡养与扶养', NULL, '国家建立健全家庭养老支持政策，鼓励家庭成员与老年人共同生活或者就近居住，为老年人随配偶或者赡养人迁徙提供条件，为家庭成员照料老年人提供帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212027, '《中华人民共和国老年人权益保障法》', '第二十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 社会保障', NULL, '国家通过基本养老保险制度，保障老年人的基本生活。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212028, '《中华人民共和国老年人权益保障法》', '第二十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 社会保障', NULL, '国家通过基本医疗保险制度，保障老年人的基本医疗需要。享受最低生活保障的老年人和符合条件的低收入家庭中的老年人参加新型农村合作医疗和城镇居民基本医疗保险所需个人缴费部分，由政府给予补贴。 有关部门制定医疗保险办法，应当对老年人给予照顾。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212029, '《中华人民共和国老年人权益保障法》', '第三十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 社会保障', NULL, '国家逐步开展长期护理保障工作，保障老年人的护理需求。 对生活长期不能自理、经济困难的老年人，地方各级人民政府应当根据其失能程度等情况给予护理补贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212030, '《中华人民共和国老年人权益保障法》', '第三十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 社会保障', NULL, '国家对经济困难的老年人给予基本生活、医疗、居住或者其他救助。 老年人无劳动能力、无生活来源、无赡养人和扶养人，或者其赡养人和扶养人确无赡养能力或者扶养能力的，由地方各级人民政府依照有关规定给予供养或者救助。 对流浪乞讨、遭受遗弃等生活无着的老年人，由地方各级人民政府依照有关规定给予救助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212031, '《中华人民共和国老年人权益保障法》', '第三十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 社会保障', NULL, '地方各级人民政府在实施廉租住房、公共租赁住房等住房保障制度或者进行危旧房屋改造时，应当优先照顾符合条件的老年人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212032, '《中华人民共和国老年人权益保障法》', '第三十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 社会保障', NULL, '国家建立和完善老年人福利制度，根据经济社会发展水平和老年人的实际需要，增加老年人的社会福利。 国家鼓励地方建立八十周岁以上低收入老年人高龄津贴制度。 国家建立和完善计划生育家庭老年人扶助制度。 农村可以将未承包的集体所有的部分土地、山林、水面、滩涂等作为养老基地，收益供老年人养老。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212033, '《中华人民共和国老年人权益保障法》', '第三十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 社会保障', NULL, '老年人依法享有的养老金、医疗待遇和其他待遇应当得到保障，有关机构必须按时足额支付，不得克扣、拖欠或者挪用。 国家根据经济发展以及职工平均工资增长、物价上涨等情况，适时提高养老保障水平。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212034, '《中华人民共和国老年人权益保障法》', '第三十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 社会保障', NULL, '国家鼓励慈善组织以及其他组织和个人为老年人提供物质帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212035, '《中华人民共和国老年人权益保障法》', '第三十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第三章 社会保障', NULL, '老年人可以与集体经济组织、基层群众性自治组织、养老机构等组织或者个人签订遗赠扶养协议或者其他扶助协议。 负有扶养义务的组织或者个人按照遗赠扶养协议，承担该老年人生养死葬的义务，享有受遗赠的权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212036, '《中华人民共和国老年人权益保障法》', '第三十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 社会服务', NULL, '地方各级人民政府和有关部门应当采取措施，发展城乡社区养老服务，鼓励、扶持专业服务机构及其他组织和个人，为居家的老年人提供生活照料、紧急救援、医疗护理、精神慰藉、心理咨询等多种形式的服务。 对经济困难的老年人，地方各级人民政府应当逐步给予养老服务补贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212037, '《中华人民共和国老年人权益保障法》', '第三十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 社会服务', NULL, '地方各级人民政府和有关部门、基层群众性自治组织，应当将养老服务设施纳入城乡社区配套设施建设规划，建立适应老年人需要的生活服务、文化体育活动、日间照料、疾病护理与康复等服务设施和网点，就近为老年人提供服务。 发扬邻里互助的传统，提倡邻里间关心、帮助有困难的老年人。 鼓励慈善组织、志愿者为老年人服务。倡导老年人互助服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212038, '《中华人民共和国老年人权益保障法》', '第三十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 社会服务', NULL, '各级人民政府应当根据经济发展水平和老年人服务需求，逐步增加对养老服务的投入。 各级人民政府和有关部门在财政、税费、土地、融资等方面采取措施，鼓励、扶持企业事业单位、社会组织或者个人兴办、运营养老、老年人日间照料、老年文化体育活动等设施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212039, '《中华人民共和国老年人权益保障法》', '第四十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 社会服务', NULL, '地方各级人民政府和有关部门应当按照老年人口比例及分布情况，将养老服务设施建设纳入城乡规划和土地利用总体规划，统筹安排养老服务设施建设用地及所需物资。 公益性养老服务设施用地，可以依法使用国有划拨土地或者农民集体所有的土地。 养老服务设施用地，非经法定程序不得改变用途。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212040, '《中华人民共和国老年人权益保障法》', '第四十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 社会服务', NULL, '政府投资兴办的养老机构，应当优先保障经济困难的孤寡、失能、高龄等老年人的服务需求。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212041, '《中华人民共和国老年人权益保障法》', '第四十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 社会服务', NULL, '国务院有关部门制定养老服务设施建设、养老服务质量和养老服务职业等标准，建立健全养老机构分类管理和养老服务评估制度。 各级人民政府应当规范养老服务收费项目和标准，加强监督和管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212042, '《中华人民共和国老年人权益保障法》', '第四十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 社会服务', NULL, '设立公益性养老机构，应当依法办理相应的登记。 设立经营性养老机构，应当在市场监督管理部门办理登记。 养老机构登记后即可开展服务活动，并向县级以上人民政府民政部门备案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212043, '《中华人民共和国老年人权益保障法》', '第四十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 社会服务', NULL, '地方各级人民政府加强对本行政区域养老机构管理工作的领导，建立养老机构综合监管制度。 县级以上人民政府民政部门负责养老机构的指导、监督和管理，其他有关部门依照职责分工对养老机构实施监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212044, '《中华人民共和国老年人权益保障法》', '第四十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 社会服务', NULL, '县级以上人民政府民政部门依法履行监督检查职责，可以采取以下措施： （一）向养老机构和个人了解情况； （二）进入涉嫌违法的养老机构进行现场检查； （三）查阅或者复制有关合同、票据、账簿及其他有关资料； （四）发现养老机构存在可能危及人身健康和生命财产安全风险的，责令限期改正，逾期不改正的，责令停业整顿。 县级以上人民政府民政部门调查养老机构涉嫌违法的行为，应当遵守《中华人民共和国行政强制法》和其他有关法律、行政法规的规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212045, '《中华人民共和国老年人权益保障法》', '第四十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 社会服务', NULL, '养老机构变更或者终止的，应当妥善安置收住的老年人，并依照规定到有关部门办理手续。有关部门应当为养老机构妥善安置老年人提供帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212046, '《中华人民共和国老年人权益保障法》', '第四十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 社会服务', NULL, '国家建立健全养老服务人才培养、使用、评价和激励制度，依法规范用工，促进从业人员劳动报酬合理增长，发展专职、兼职和志愿者相结合的养老服务队伍。 国家鼓励高等学校、中等职业学校和职业培训机构设置相关专业或者培训项目，培养养老服务专业人才。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212047, '《中华人民共和国老年人权益保障法》', '第四十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 社会服务', NULL, '养老机构应当与接受服务的老年人或者其代理人签订服务协议，明确双方的权利、义务。 养老机构及其工作人员不得以任何方式侵害老年人的权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212048, '《中华人民共和国老年人权益保障法》', '第四十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 社会服务', NULL, '国家鼓励养老机构投保责任保险，鼓励保险公司承保责任保险。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212049, '《中华人民共和国老年人权益保障法》', '第五十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 社会服务', NULL, '各级人民政府和有关部门应当将老年医疗卫生服务纳入城乡医疗卫生服务规划，将老年人健康管理和常见病预防等纳入国家基本公共卫生服务项目。鼓励为老年人提供保健、护理、临终关怀等服务。 国家鼓励医疗机构开设针对老年病的专科或者门诊。 医疗卫生机构应当开展老年人的健康服务和疾病防治工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212050, '《中华人民共和国老年人权益保障法》', '第五十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 社会服务', NULL, '国家采取措施，加强老年医学的研究和人才培养，提高老年病的预防、治疗、科研水平，促进老年病的早期发现、诊断和治疗。 国家和社会采取措施，开展各种形式的健康教育，普及老年保健知识，增强老年人自我保健意识。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212051, '《中华人民共和国老年人权益保障法》', '第五十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第四章 社会服务', NULL, '国家采取措施，发展老龄产业，将老龄产业列入国家扶持行业目录。扶持和引导企业开发、生产、经营适应老年人需要的用品和提供相关的服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212052, '《中华人民共和国老年人权益保障法》', '第五十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 社会优待', NULL, '县级以上人民政府及其有关部门根据经济社会发展情况和老年人的特殊需要，制定优待老年人的办法，逐步提高优待水平。 对常住在本行政区域内的外埠老年人给予同等优待。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212053, '《中华人民共和国老年人权益保障法》', '第五十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 社会优待', NULL, '各级人民政府和有关部门应当为老年人及时、便利地领取养老金、结算医疗费和享受其他物质帮助提供条件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212054, '《中华人民共和国老年人权益保障法》', '第五十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 社会优待', NULL, '各级人民政府和有关部门办理房屋权属关系变更、户口迁移等涉及老年人权益的重大事项时，应当就办理事项是否为老年人的真实意思表示进行询问，并依法优先办理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212055, '《中华人民共和国老年人权益保障法》', '第五十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 社会优待', NULL, '老年人因其合法权益受侵害提起诉讼交纳诉讼费确有困难的，可以缓交、减交或者免交；需要获得律师帮助，但无力支付律师费用的，可以获得法律援助。 鼓励律师事务所、公证处、基层法律服务所和其他法律服务机构为经济困难的老年人提供免费或者优惠服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212056, '《中华人民共和国老年人权益保障法》', '第五十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 社会优待', NULL, '医疗机构应当为老年人就医提供方便，对老年人就医予以优先。有条件的地方，可以为老年人设立家庭病床，开展巡回医疗、护理、康复、免费体检等服务。 提倡为老年人义诊。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212057, '《中华人民共和国老年人权益保障法》', '第五十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 社会优待', NULL, '提倡与老年人日常生活密切相关的服务行业为老年人提供优先、优惠服务。 城市公共交通、公路、铁路、水路和航空客运，应当为老年人提供优待和照顾。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212058, '《中华人民共和国老年人权益保障法》', '第五十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 社会优待', NULL, '博物馆、美术馆、科技馆、纪念馆、公共图书馆、文化馆、影剧院、体育场馆、公园、旅游景点等场所，应当对老年人免费或者优惠开放。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212059, '《中华人民共和国老年人权益保障法》', '第六十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第五章 社会优待', NULL, '农村老年人不承担兴办公益事业的筹劳义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212060, '《中华人民共和国老年人权益保障法》', '第六十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 宜居环境', NULL, '国家采取措施，推进宜居环境建设，为老年人提供安全、便利和舒适的环境。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212061, '《中华人民共和国老年人权益保障法》', '第六十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 宜居环境', NULL, '各级人民政府在制定城乡规划时，应当根据人口老龄化发展趋势、老年人口分布和老年人的特点，统筹考虑适合老年人的公共基础设施、生活服务设施、医疗卫生设施和文化体育设施建设。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212062, '《中华人民共和国老年人权益保障法》', '第六十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 宜居环境', NULL, '国家制定和完善涉及老年人的工程建设标准体系，在规划、设计、施工、监理、验收、运行、维护、管理等环节加强相关标准的实施与监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212063, '《中华人民共和国老年人权益保障法》', '第六十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 宜居环境', NULL, '国家制定无障碍设施工程建设标准。新建、改建和扩建道路、公共交通设施、建筑物、居住区等，应当符合国家无障碍设施工程建设标准。 各级人民政府和有关部门应当按照国家无障碍设施工程建设标准，优先推进与老年人日常生活密切相关的公共服务设施的改造。 无障碍设施的所有人和管理人应当保障无障碍设施正常使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212064, '《中华人民共和国老年人权益保障法》', '第六十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第六章 宜居环境', NULL, '国家推动老年宜居社区建设，引导、支持老年宜居住宅的开发，推动和扶持老年人家庭无障碍设施的改造，为老年人创造无障碍居住环境。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212065, '《中华人民共和国老年人权益保障法》', '第六十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 参与社会发展', NULL, '国家和社会应当重视、珍惜老年人的知识、技能、经验和优良品德，发挥老年人的专长和作用，保障老年人参与经济、政治、文化和社会生活。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212066, '《中华人民共和国老年人权益保障法》', '第六十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 参与社会发展', NULL, '老年人可以通过老年人组织，开展有益身心健康的活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212067, '《中华人民共和国老年人权益保障法》', '第六十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 参与社会发展', NULL, '制定法律、法规、规章和公共政策，涉及老年人权益重大问题的，应当听取老年人和老年人组织的意见。 老年人和老年人组织有权向国家机关提出老年人权益保障、老龄事业发展等方面的意见和建议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212068, '《中华人民共和国老年人权益保障法》', '第六十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 参与社会发展', NULL, '国家为老年人参与社会发展创造条件。根据社会需要和可能，鼓励老年人在自愿和量力的情况下，从事下列活动： （一）对青少年和儿童进行社会主义、爱国主义、集体主义和艰苦奋斗等优良传统教育； （二）传授文化和科技知识； （三）提供咨询服务； （四）依法参与科技开发和应用； （五）依法从事经营和生产活动； （六）参加志愿服务、兴办社会公益事业； （七）参与维护社会治安、协助调解民间纠纷； （八）参加其他社会活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212069, '《中华人民共和国老年人权益保障法》', '第七十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 参与社会发展', NULL, '老年人参加劳动的合法收入受法律保护。 任何单位和个人不得安排老年人从事危害其身心健康的劳动或者危险作业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212070, '《中华人民共和国老年人权益保障法》', '第七十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 参与社会发展', NULL, '老年人有继续受教育的权利。 国家发展老年教育，把老年教育纳入终身教育体系，鼓励社会办好各类老年学校。 各级人民政府对老年教育应当加强领导，统一规划，加大投入。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212071, '《中华人民共和国老年人权益保障法》', '第七十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第七章 参与社会发展', NULL, '国家和社会采取措施，开展适合老年人的群众性文化、体育、娱乐活动，丰富老年人的精神文化生活。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212072, '《中华人民共和国老年人权益保障法》', '第七十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 法律责任', NULL, '老年人合法权益受到侵害的，被侵害人或者其代理人有权要求有关部门处理，或者依法向人民法院提起诉讼。 人民法院和有关部门，对侵犯老年人合法权益的申诉、控告和检举，应当依法及时受理，不得推诿、拖延。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212073, '《中华人民共和国老年人权益保障法》', '第七十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 法律责任', NULL, '不履行保护老年人合法权益职责的部门或者组织，其上级主管部门应当给予批评教育，责令改正。 国家工作人员违法失职，致使老年人合法权益受到损害的，由其所在单位或者上级机关责令改正，或者依法给予处分；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212074, '《中华人民共和国老年人权益保障法》', '第七十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 法律责任', NULL, '老年人与家庭成员因赡养、扶养或者住房、财产等发生纠纷，可以申请人民调解委员会或者其他有关组织进行调解，也可以直接向人民法院提起诉讼。 人民调解委员会或者其他有关组织调解前款纠纷时，应当通过说服、疏导等方式化解矛盾和纠纷；对有过错的家庭成员，应当给予批评教育。 人民法院对老年人追索赡养费或者扶养费的申请，可以依法裁定先予执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212075, '《中华人民共和国老年人权益保障法》', '第七十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 法律责任', NULL, '干涉老年人婚姻自由，对老年人负有赡养义务、扶养义务而拒绝赡养、扶养，虐待老年人或者对老年人实施家庭暴力的，由有关单位给予批评教育；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212076, '《中华人民共和国老年人权益保障法》', '第七十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 法律责任', NULL, '家庭成员盗窃、诈骗、抢夺、侵占、勒索、故意损毁老年人财物，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212077, '《中华人民共和国老年人权益保障法》', '第七十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 法律责任', NULL, '侮辱、诽谤老年人，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212078, '《中华人民共和国老年人权益保障法》', '第七十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 法律责任', NULL, '养老机构及其工作人员侵害老年人人身和财产权益，或者未按照约定提供服务的，依法承担民事责任；有关主管部门依法给予行政处罚；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212079, '《中华人民共和国老年人权益保障法》', '第八十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 法律责任', NULL, '对养老机构负有管理和监督职责的部门及其工作人员滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212080, '《中华人民共和国老年人权益保障法》', '第八十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 法律责任', NULL, '不按规定履行优待老年人义务的，由有关主管部门责令改正。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212081, '《中华人民共和国老年人权益保障法》', '第八十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第八章 法律责任', NULL, '涉及老年人的工程不符合国家规定的标准或者无障碍设施所有人、管理人未尽到维护和管理职责的，由有关主管部门责令改正；造成损害的，依法承担民事责任；对有关单位、个人依法给予行政处罚；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212082, '《中华人民共和国老年人权益保障法》', '第八十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第九章 附 则', NULL, '民族自治地方的人民代表大会，可以根据本法的原则，结合当地民族风俗习惯的具体情况，依照法定程序制定变通的或者补充的规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212083, '《中华人民共和国老年人权益保障法》', '第八十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第九章 附 则', NULL, '本法施行前设立的养老机构不符合本法规定条件的，应当限期整改。具体办法由国务院民政部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (212084, '《中华人民共和国老年人权益保障法》', '第八十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-12-29', '第九章 附 则', NULL, '本法自2013年7月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213000, '《中华人民共和国残疾人保障法》', '第一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第一章 总 则', NULL, '为了维护残疾人的合法权益，发展残疾人事业，保障残疾人平等地充分参与社会生活，共享社会物质文化成果，根据宪法，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213001, '《中华人民共和国残疾人保障法》', '第二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第一章 总 则', NULL, '残疾人是指在心理、生理、人体结构上，某种组织、功能丧失或者不正常，全部或者部分丧失以正常方式从事某种活动能力的人。 残疾人包括视力残疾、听力残疾、言语残疾、肢体残疾、智力残疾、精神残疾、多重残疾和其他残疾的人。 残疾标准由国务院规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213002, '《中华人民共和国残疾人保障法》', '第三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第一章 总 则', NULL, '残疾人在政治、经济、文化、社会和家庭生活等方面享有同其他公民平等的权利。 残疾人的公民权利和人格尊严受法律保护。 禁止基于残疾的歧视。禁止侮辱、侵害残疾人。禁止通过大众传播媒介或者其他方式贬低损害残疾人人格。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213003, '《中华人民共和国残疾人保障法》', '第四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第一章 总 则', NULL, '国家采取辅助方法和扶持措施，对残疾人给予特别扶助，减轻或者消除残疾影响和外界障碍，保障残疾人权利的实现。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213004, '《中华人民共和国残疾人保障法》', '第五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第一章 总 则', NULL, '县级以上人民政府应当将残疾人事业纳入国民经济和社会发展规划，加强领导，综合协调，并将残疾人事业经费列入财政预算，建立稳定的经费保障机制。 国务院制定中国残疾人事业发展纲要，县级以上地方人民政府根据中国残疾人事业发展纲要，制定本行政区域的残疾人事业发展规划和年度计划，使残疾人事业与经济、社会协调发展。 县级以上人民政府负责残疾人工作的机构，负责组织、协调、指导、督促有关部门做好残疾人事业的工作。 各级人民政府和有关部门，应当密切联系残疾人，听取残疾人的意见，按照各自的职责，做好残疾人工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213005, '《中华人民共和国残疾人保障法》', '第六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第一章 总 则', NULL, '国家采取措施，保障残疾人依照法律规定，通过各种途径和形式，管理国家事务，管理经济和文化事业，管理社会事务。 制定法律、法规、规章和公共政策，对涉及残疾人权益和残疾人事业的重大问题，应当听取残疾人和残疾人组织的意见。 残疾人和残疾人组织有权向各级国家机关提出残疾人权益保障、残疾人事业发展等方面的意见和建议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213006, '《中华人民共和国残疾人保障法》', '第七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第一章 总 则', NULL, '全社会应当发扬人道主义精神，理解、尊重、关心、帮助残疾人，支持残疾人事业。 国家鼓励社会组织和个人为残疾人提供捐助和服务。 国家机关、社会团体、企业事业单位和城乡基层群众性自治组织，应当做好所属范围内的残疾人工作。 从事残疾人工作的国家工作人员和其他人员，应当依法履行职责，努力为残疾人服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213007, '《中华人民共和国残疾人保障法》', '第八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第一章 总 则', NULL, '中国残疾人联合会及其地方组织，代表残疾人的共同利益，维护残疾人的合法权益，团结教育残疾人，为残疾人服务。 中国残疾人联合会及其地方组织依照法律、法规、章程或者接受政府委托，开展残疾人工作，动员社会力量，发展残疾人事业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213008, '《中华人民共和国残疾人保障法》', '第九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第一章 总 则', NULL, '残疾人的扶养人必须对残疾人履行扶养义务。 残疾人的监护人必须履行监护职责，尊重被监护人的意愿，维护被监护人的合法权益。 残疾人的亲属、监护人应当鼓励和帮助残疾人增强自立能力。 禁止对残疾人实施家庭暴力，禁止虐待、遗弃残疾人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213009, '《中华人民共和国残疾人保障法》', '第十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第一章 总 则', NULL, '国家鼓励残疾人自尊、自信、自强、自立，为社会主义建设贡献力量。 残疾人应当遵守法律、法规，履行应尽的义务，遵守公共秩序，尊重社会公德。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213010, '《中华人民共和国残疾人保障法》', '第十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第一章 总 则', NULL, '国家有计划地开展残疾预防工作，加强对残疾预防工作的领导，宣传、普及母婴保健和预防残疾的知识，建立健全出生缺陷预防和早期发现、早期治疗机制，针对遗传、疾病、药物、事故、灾害、环境污染和其他致残因素，组织和动员社会力量，采取措施，预防残疾的发生，减轻残疾程度。 国家建立健全残疾人统计调查制度，开展残疾人状况的统计调查和分析。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213011, '《中华人民共和国残疾人保障法》', '第十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第一章 总 则', NULL, '国家和社会对残疾军人、因公致残人员以及其他为维护国家和人民利益致残的人员实行特别保障，给予抚恤和优待。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213012, '《中华人民共和国残疾人保障法》', '第十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第一章 总 则', NULL, '对在社会主义建设中做出显著成绩的残疾人，对维护残疾人合法权益、发展残疾人事业、为残疾人服务做出显著成绩的单位和个人，各级人民政府和有关部门给予表彰和奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213013, '《中华人民共和国残疾人保障法》', '第十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第一章 总 则', NULL, '每年5月的第三个星期日为全国助残日。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213014, '《中华人民共和国残疾人保障法》', '第十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第二章 康 复', NULL, '国家保障残疾人享有康复服务的权利。 各级人民政府和有关部门应当采取措施，为残疾人康复创造条件，建立和完善残疾人康复服务体系，并分阶段实施重点康复项目，帮助残疾人恢复或者补偿功能，增强其参与社会生活的能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213015, '《中华人民共和国残疾人保障法》', '第十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第二章 康 复', NULL, '康复工作应当从实际出发，将现代康复技术与我国传统康复技术相结合；以社区康复为基础，康复机构为骨干，残疾人家庭为依托；以实用、易行、受益广的康复内容为重点，优先开展残疾儿童抢救性治疗和康复；发展符合康复要求的科学技术，鼓励自主创新，加强康复新技术的研究、开发和应用，为残疾人提供有效的康复服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213016, '《中华人民共和国残疾人保障法》', '第十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第二章 康 复', NULL, '各级人民政府鼓励和扶持社会力量兴办残疾人康复机构。 地方各级人民政府和有关部门，应当组织和指导城乡社区服务组织、医疗预防保健机构、残疾人组织、残疾人家庭和其他社会力量，开展社区康复工作。 残疾人教育机构、福利性单位和其他为残疾人服务的机构，应当创造条件，开展康复训练活动。 残疾人在专业人员的指导和有关工作人员、志愿工作者及亲属的帮助下，应当努力进行功能、自理能力和劳动技能的训练。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213017, '《中华人民共和国残疾人保障法》', '第十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第二章 康 复', NULL, '地方各级人民政府和有关部门应当根据需要有计划地在医疗机构设立康复医学科室，举办残疾人康复机构，开展康复医疗与训练、人员培训、技术指导、科学研究等工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213018, '《中华人民共和国残疾人保障法》', '第十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第二章 康 复', NULL, '医学院校和其他有关院校应当有计划地开设康复课程，设置相关专业，培养各类康复专业人才。 政府和社会采取多种形式对从事康复工作的人员进行技术培训；向残疾人、残疾人亲属、有关工作人员和志愿工作者普及康复知识，传授康复方法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213019, '《中华人民共和国残疾人保障法》', '第二十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第二章 康 复', NULL, '政府有关部门应当组织和扶持残疾人康复器械、辅助器具的研制、生产、供应、维修服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213020, '《中华人民共和国残疾人保障法》', '第二十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第三章 教 育', NULL, '国家保障残疾人享有平等接受教育的权利。 各级人民政府应当将残疾人教育作为国家教育事业的组成部分，统一规划，加强领导，为残疾人接受教育创造条件。 政府、社会、学校应当采取有效措施，解决残疾儿童、少年就学存在的实际困难，帮助其完成义务教育。 各级人民政府对接受义务教育的残疾学生、贫困残疾人家庭的学生提供免费教科书，并给予寄宿生活费等费用补助；对接受义务教育以外其他教育的残疾学生、贫困残疾人家庭的学生按照国家有关规定给予资助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213021, '《中华人民共和国残疾人保障法》', '第二十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第三章 教 育', NULL, '残疾人教育，实行普及与提高相结合、以普及为重点的方针，保障义务教育，着重发展职业教育，积极开展学前教育，逐步发展高级中等以上教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213022, '《中华人民共和国残疾人保障法》', '第二十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第三章 教 育', NULL, '残疾人教育应当根据残疾人的身心特性和需要，按照下列要求实施： （一）在进行思想教育、文化教育的同时，加强身心补偿和职业教育； （二）依据残疾类别和接受能力，采取普通教育方式或者特殊教育方式； （三）特殊教育的课程设置、教材、教学方法、入学和在校年龄，可以有适度弹性。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213023, '《中华人民共和国残疾人保障法》', '第二十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第三章 教 育', NULL, '县级以上人民政府应当根据残疾人的数量、分布状况和残疾类别等因素，合理设置残疾人教育机构，并鼓励社会力量办学、捐资助学。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213024, '《中华人民共和国残疾人保障法》', '第二十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第三章 教 育', NULL, '普通教育机构对具有接受普通教育能力的残疾人实施教育，并为其学习提供便利和帮助。 普通小学、初级中等学校，必须招收能适应其学习生活的残疾儿童、少年入学；普通高级中等学校、中等职业学校和高等学校，必须招收符合国家规定的录取要求的残疾考生入学，不得因其残疾而拒绝招收；拒绝招收的，当事人或者其亲属、监护人可以要求有关部门处理，有关部门应当责令该学校招收。 普通幼儿教育机构应当接收能适应其生活的残疾幼儿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213025, '《中华人民共和国残疾人保障法》', '第二十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第三章 教 育', NULL, '残疾幼儿教育机构、普通幼儿教育机构附设的残疾儿童班、特殊教育机构的学前班、残疾儿童福利机构、残疾儿童家庭，对残疾儿童实施学前教育。 初级中等以下特殊教育机构和普通教育机构附设的特殊教育班，对不具有接受普通教育能力的残疾儿童、少年实施义务教育。 高级中等以上特殊教育机构、普通教育机构附设的特殊教育班和残疾人职业教育机构，对符合条件的残疾人实施高级中等以上文化教育、职业教育。 提供特殊教育的机构应当具备适合残疾人学习、康复、生活特点的场所和设施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213026, '《中华人民共和国残疾人保障法》', '第二十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第三章 教 育', NULL, '政府有关部门、残疾人所在单位和有关社会组织应当对残疾人开展扫除文盲、职业培训、创业培训和其他成人教育，鼓励残疾人自学成才。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213027, '《中华人民共和国残疾人保障法》', '第二十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第三章 教 育', NULL, '国家有计划地举办各级各类特殊教育师范院校、专业，在普通师范院校附设特殊教育班，培养、培训特殊教育师资。普通师范院校开设特殊教育课程或者讲授有关内容，使普通教师掌握必要的特殊教育知识。 特殊教育教师和手语翻译，享受特殊教育津贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213028, '《中华人民共和国残疾人保障法》', '第二十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第三章 教 育', NULL, '政府有关部门应当组织和扶持盲文、手语的研究和应用，特殊教育教材的编写和出版，特殊教育教学用具及其他辅助用品的研制、生产和供应。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213029, '《中华人民共和国残疾人保障法》', '第三十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第四章 劳动就业', NULL, '国家保障残疾人劳动的权利。 各级人民政府应当对残疾人劳动就业统筹规划，为残疾人创造劳动就业条件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213030, '《中华人民共和国残疾人保障法》', '第三十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第四章 劳动就业', NULL, '残疾人劳动就业，实行集中与分散相结合的方针，采取优惠政策和扶持保护措施，通过多渠道、多层次、多种形式，使残疾人劳动就业逐步普及、稳定、合理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213031, '《中华人民共和国残疾人保障法》', '第三十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第四章 劳动就业', NULL, '政府和社会举办残疾人福利企业、盲人按摩机构和其他福利性单位，集中安排残疾人就业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213032, '《中华人民共和国残疾人保障法》', '第三十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第四章 劳动就业', NULL, '国家实行按比例安排残疾人就业制度。 国家机关、社会团体、企业事业单位、民办非企业单位应当按照规定的比例安排残疾人就业，并为其选择适当的工种和岗位。达不到规定比例的，按照国家有关规定履行保障残疾人就业义务。国家鼓励用人单位超过规定比例安排残疾人就业。 残疾人就业的具体办法由国务院规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213033, '《中华人民共和国残疾人保障法》', '第三十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第四章 劳动就业', NULL, '国家鼓励和扶持残疾人自主择业、自主创业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213034, '《中华人民共和国残疾人保障法》', '第三十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第四章 劳动就业', NULL, '地方各级人民政府和农村基层组织，应当组织和扶持农村残疾人从事种植业、养殖业、手工业和其他形式的生产劳动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213035, '《中华人民共和国残疾人保障法》', '第三十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第四章 劳动就业', NULL, '国家对安排残疾人就业达到、超过规定比例或者集中安排残疾人就业的用人单位和从事个体经营的残疾人，依法给予税收优惠，并在生产、经营、技术、资金、物资、场地等方面给予扶持。国家对从事个体经营的残疾人，免除行政事业性收费。 县级以上地方人民政府及其有关部门应当确定适合残疾人生产、经营的产品、项目，优先安排残疾人福利性单位生产或者经营，并根据残疾人福利性单位的生产特点确定某些产品由其专产。 政府采购，在同等条件下应当优先购买残疾人福利性单位的产品或者服务。 地方各级人民政府应当开发适合残疾人就业的公益性岗位。 对申请从事个体经营的残疾人，有关部门应当优先核发营业执照。 对从事各类生产劳动的农村残疾人，有关部门应当在生产服务、技术指导、农用物资供应、农副产品购销和信贷等方面，给予帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213036, '《中华人民共和国残疾人保障法》', '第三十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第四章 劳动就业', NULL, '政府有关部门设立的公共就业服务机构，应当为残疾人免费提供就业服务。 残疾人联合会举办的残疾人就业服务机构，应当组织开展免费的职业指导、职业介绍和职业培训，为残疾人就业和用人单位招用残疾人提供服务和帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213037, '《中华人民共和国残疾人保障法》', '第三十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第四章 劳动就业', NULL, '国家保护残疾人福利性单位的财产所有权和经营自主权，其合法权益不受侵犯。 在职工的招用、转正、晋级、职称评定、劳动报酬、生活福利、休息休假、社会保险等方面，不得歧视残疾人。 残疾职工所在单位应当根据残疾职工的特点，提供适当的劳动条件和劳动保护，并根据实际需要对劳动场所、劳动设备和生活设施进行改造。 国家采取措施，保障盲人保健和医疗按摩人员从业的合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213038, '《中华人民共和国残疾人保障法》', '第三十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第四章 劳动就业', NULL, '残疾职工所在单位应当对残疾职工进行岗位技术培训，提高其劳动技能和技术水平。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213039, '《中华人民共和国残疾人保障法》', '第四十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第四章 劳动就业', NULL, '任何单位和个人不得以暴力、威胁或者非法限制人身自由的手段强迫残疾人劳动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213040, '《中华人民共和国残疾人保障法》', '第四十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第五章 文化生活', NULL, '国家保障残疾人享有平等参与文化生活的权利。 各级人民政府和有关部门鼓励、帮助残疾人参加各种文化、体育、娱乐活动，积极创造条件，丰富残疾人精神文化生活。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213041, '《中华人民共和国残疾人保障法》', '第四十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第五章 文化生活', NULL, '残疾人文化、体育、娱乐活动应当面向基层，融于社会公共文化生活，适应各类残疾人的不同特点和需要，使残疾人广泛参与。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213042, '《中华人民共和国残疾人保障法》', '第四十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第五章 文化生活', NULL, '政府和社会采取下列措施，丰富残疾人的精神文化生活： （一）通过广播、电影、电视、报刊、图书、网络等形式，及时宣传报道残疾人的工作、生活等情况，为残疾人服务； （二）组织和扶持盲文读物、盲人有声读物及其他残疾人读物的编写和出版，根据盲人的实际需要，在公共图书馆设立盲文读物、盲人有声读物图书室； （三）开办电视手语节目，开办残疾人专题广播栏目，推进电视栏目、影视作品加配字幕、解说； （四）组织和扶持残疾人开展群众性文化、体育、娱乐活动，举办特殊艺术演出和残疾人体育运动会，参加国际性比赛和交流； （五）文化、体育、娱乐和其他公共活动场所，为残疾人提供方便和照顾。有计划地兴办残疾人活动场所。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213043, '《中华人民共和国残疾人保障法》', '第四十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第五章 文化生活', NULL, '政府和社会鼓励、帮助残疾人从事文学、艺术、教育、科学、技术和其他有益于人民的创造性劳动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213044, '《中华人民共和国残疾人保障法》', '第四十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第五章 文化生活', NULL, '政府和社会促进残疾人与其他公民之间的相互理解和交流，宣传残疾人事业和扶助残疾人的事迹，弘扬残疾人自强不息的精神，倡导团结、友爱、互助的社会风尚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213045, '《中华人民共和国残疾人保障法》', '第四十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第六章 社会保障', NULL, '国家保障残疾人享有各项社会保障的权利。 政府和社会采取措施，完善对残疾人的社会保障，保障和改善残疾人的生活。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213046, '《中华人民共和国残疾人保障法》', '第四十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第六章 社会保障', NULL, '残疾人及其所在单位应当按照国家有关规定参加社会保险。 残疾人所在城乡基层群众性自治组织、残疾人家庭，应当鼓励、帮助残疾人参加社会保险。 对生活确有困难的残疾人，按照国家有关规定给予社会保险补贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213047, '《中华人民共和国残疾人保障法》', '第四十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第六章 社会保障', NULL, '各级人民政府对生活确有困难的残疾人，通过多种渠道给予生活、教育、住房和其他社会救助。 县级以上地方人民政府对享受最低生活保障待遇后生活仍有特别困难的残疾人家庭，应当采取其他措施保障其基本生活。 各级人民政府对贫困残疾人的基本医疗、康复服务、必要的辅助器具的配置和更换，应当按照规定给予救助。 对生活不能自理的残疾人，地方各级人民政府应当根据情况给予护理补贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213048, '《中华人民共和国残疾人保障法》', '第四十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第六章 社会保障', NULL, '地方各级人民政府对无劳动能力、无扶养人或者扶养人不具有扶养能力、无生活来源的残疾人，按照规定予以供养。 国家鼓励和扶持社会力量举办残疾人供养、托养机构。 残疾人供养、托养机构及其工作人员不得侮辱、虐待、遗弃残疾人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213049, '《中华人民共和国残疾人保障法》', '第五十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第六章 社会保障', NULL, '县级以上人民政府对残疾人搭乘公共交通工具，应当根据实际情况给予便利和优惠。残疾人可以免费携带随身必备的辅助器具。 盲人持有效证件免费乘坐市内公共汽车、电车、地铁、渡船等公共交通工具。盲人读物邮件免费寄递。 国家鼓励和支持提供电信、广播电视服务的单位对盲人、听力残疾人、言语残疾人给予优惠。 各级人民政府应当逐步增加对残疾人的其他照顾和扶助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213050, '《中华人民共和国残疾人保障法》', '第五十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第六章 社会保障', NULL, '政府有关部门和残疾人组织应当建立和完善社会各界为残疾人捐助和服务的渠道，鼓励和支持发展残疾人慈善事业，开展志愿者助残等公益活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213051, '《中华人民共和国残疾人保障法》', '第五十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第七章 无障碍环境', NULL, '国家和社会应当采取措施，逐步完善无障碍设施，推进信息交流无障碍，为残疾人平等参与社会生活创造无障碍环境。 各级人民政府应当对无障碍环境建设进行统筹规划，综合协调，加强监督管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213052, '《中华人民共和国残疾人保障法》', '第五十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第七章 无障碍环境', NULL, '无障碍设施的建设和改造，应当符合残疾人的实际需要。 新建、改建和扩建建筑物、道路、交通设施等，应当符合国家有关无障碍设施工程建设标准。 各级人民政府和有关部门应当按照国家无障碍设施工程建设规定，逐步推进已建成设施的改造，优先推进与残疾人日常工作、生活密切相关的公共服务设施的改造。 对无障碍设施应当及时维修和保护。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213053, '《中华人民共和国残疾人保障法》', '第五十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第七章 无障碍环境', NULL, '国家采取措施，为残疾人信息交流无障碍创造条件。 各级人民政府和有关部门应当采取措施，为残疾人获取公共信息提供便利。 国家和社会研制、开发适合残疾人使用的信息交流技术和产品。 国家举办的各类升学考试、职业资格考试和任职考试，有盲人参加的，应当为盲人提供盲文试卷、电子试卷或者由专门的工作人员予以协助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213054, '《中华人民共和国残疾人保障法》', '第五十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第七章 无障碍环境', NULL, '公共服务机构和公共场所应当创造条件，为残疾人提供语音和文字提示、手语、盲文等信息交流服务，并提供优先服务和辅助性服务。 公共交通工具应当逐步达到无障碍设施的要求。有条件的公共停车场应当为残疾人设置专用停车位。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213055, '《中华人民共和国残疾人保障法》', '第五十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第七章 无障碍环境', NULL, '组织选举的部门应当为残疾人参加选举提供便利；有条件的，应当为盲人提供盲文选票。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213056, '《中华人民共和国残疾人保障法》', '第五十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第七章 无障碍环境', NULL, '国家鼓励和扶持无障碍辅助设备、无障碍交通工具的研制和开发。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213057, '《中华人民共和国残疾人保障法》', '第五十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第七章 无障碍环境', NULL, '盲人携带导盲犬出入公共场所，应当遵守国家有关规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213058, '《中华人民共和国残疾人保障法》', '第五十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第八章 法律责任', NULL, '残疾人的合法权益受到侵害的，可以向残疾人组织投诉，残疾人组织应当维护残疾人的合法权益，有权要求有关部门或者单位查处。有关部门或者单位应当依法查处，并予以答复。 残疾人组织对残疾人通过诉讼维护其合法权益需要帮助的，应当给予支持。 残疾人组织对侵害特定残疾人群体利益的行为，有权要求有关部门依法查处。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213059, '《中华人民共和国残疾人保障法》', '第六十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第八章 法律责任', NULL, '残疾人的合法权益受到侵害的，有权要求有关部门依法处理，或者依法向仲裁机构申请仲裁，或者依法向人民法院提起诉讼。 对有经济困难或者其他原因确需法律援助或者司法救助的残疾人，当地法律援助机构或者人民法院应当给予帮助，依法为其提供法律援助或者司法救助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213060, '《中华人民共和国残疾人保障法》', '第六十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第八章 法律责任', NULL, '违反本法规定，对侵害残疾人权益行为的申诉、控告、检举，推诿、拖延、压制不予查处，或者对提出申诉、控告、检举的人进行打击报复的，由其所在单位、主管部门或者上级机关责令改正，并依法对直接负责的主管人员和其他直接责任人员给予处分。 国家工作人员未依法履行职责，对侵害残疾人权益的行为未及时制止或者未给予受害残疾人必要帮助，造成严重后果的，由其所在单位或者上级机关依法对直接负责的主管人员和其他直接责任人员给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213061, '《中华人民共和国残疾人保障法》', '第六十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第八章 法律责任', NULL, '违反本法规定，通过大众传播媒介或者其他方式贬低损害残疾人人格的，由文化、广播电视、电影、新闻出版或者其他有关主管部门依据各自的职权责令改正，并依法给予行政处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213062, '《中华人民共和国残疾人保障法》', '第六十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第八章 法律责任', NULL, '违反本法规定，有关教育机构拒不接收残疾学生入学，或者在国家规定的录取要求以外附加条件限制残疾学生就学的，由有关主管部门责令改正，并依法对直接负责的主管人员和其他直接责任人员给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213063, '《中华人民共和国残疾人保障法》', '第六十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第八章 法律责任', NULL, '违反本法规定，在职工的招用等方面歧视残疾人的，由有关主管部门责令改正；残疾人劳动者可以依法向人民法院提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213064, '《中华人民共和国残疾人保障法》', '第六十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第八章 法律责任', NULL, '违反本法规定，供养、托养机构及其工作人员侮辱、虐待、遗弃残疾人的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成违反治安管理行为的，依法给予行政处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213065, '《中华人民共和国残疾人保障法》', '第六十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第八章 法律责任', NULL, '违反本法规定，新建、改建和扩建建筑物、道路、交通设施，不符合国家有关无障碍设施工程建设标准，或者对无障碍设施未进行及时维修和保护造成后果的，由有关主管部门依法处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213066, '《中华人民共和国残疾人保障法》', '第六十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第八章 法律责任', NULL, '违反本法规定，侵害残疾人的合法权益，其他法律、法规规定行政处罚的，从其规定；造成财产损失或者其他损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (213067, '《中华人民共和国残疾人保障法》', '第六十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2018-10-26', '第九章 附 则', NULL, '本法自2008年7月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214000, '《中华人民共和国慈善法》', '第一条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第一章 总 则', NULL, '为了发展慈善事业，弘扬慈善文化，规范慈善活动，保护慈善组织、捐赠人、志愿者、受益人等慈善活动参与者的合法权益，促进社会进步，共享发展成果，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214001, '《中华人民共和国慈善法》', '第二条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第一章 总 则', NULL, '自然人、法人和非法人组织开展慈善活动以及与慈善有关的活动，适用本法。其他法律有特别规定的，依照其规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214002, '《中华人民共和国慈善法》', '第三条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第一章 总 则', NULL, '本法所称慈善活动，是指自然人、法人和非法人组织以捐赠财产或者提供服务等方式，自愿开展的下列公益活动： （一）扶贫、济困； （二）扶老、救孤、恤病、助残、优抚； （三）救助自然灾害、事故灾难和公共卫生事件等突发事件造成的损害； （四）促进教育、科学、文化、卫生、体育等事业的发展； （五）防治污染和其他公害，保护和改善生态环境； （六）符合本法规定的其他公益活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214003, '《中华人民共和国慈善法》', '第四条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第一章 总 则', NULL, '慈善工作坚持中国共产党的领导。 开展慈善活动，应当遵循合法、自愿、诚信、非营利的原则，不得违背社会公德，不得危害国家安全、损害社会公共利益和他人合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214004, '《中华人民共和国慈善法》', '第五条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第一章 总 则', NULL, '国家鼓励和支持自然人、法人和非法人组织践行社会主义核心价值观，弘扬中华民族传统美德，依法开展慈善活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214005, '《中华人民共和国慈善法》', '第六条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第一章 总 则', NULL, '县级以上人民政府应当统筹、协调、督促和指导有关部门在各自职责范围内做好慈善事业的扶持发展和规范管理工作。 国务院民政部门主管全国慈善工作，县级以上地方各级人民政府民政部门主管本行政区域内的慈善工作；县级以上人民政府有关部门依照本法和其他有关法律法规，在各自的职责范围内做好相关工作，加强对慈善活动的监督、管理和服务；慈善组织有业务主管单位的，业务主管单位应当对其进行指导、监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214006, '《中华人民共和国慈善法》', '第七条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第一章 总 则', NULL, '每年9月5日为“中华慈善日”。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214007, '《中华人民共和国慈善法》', '第八条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第二章 慈善组织', NULL, '本法所称慈善组织，是指依法成立、符合本法规定，以面向社会开展慈善活动为宗旨的非营利性组织。 慈善组织可以采取基金会、社会团体、社会服务机构等组织形式。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214008, '《中华人民共和国慈善法》', '第九条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第二章 慈善组织', NULL, '慈善组织应当符合下列条件： （一）以开展慈善活动为宗旨； （二）不以营利为目的； （三）有自己的名称和住所； （四）有组织章程； （五）有必要的财产； （六）有符合条件的组织机构和负责人； （七）法律、行政法规规定的其他条件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214009, '《中华人民共和国慈善法》', '第十条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第二章 慈善组织', NULL, '设立慈善组织，应当向县级以上人民政府民政部门申请登记，民政部门应当自受理申请之日起三十日内作出决定。符合本法规定条件的，准予登记并向社会公告；不符合本法规定条件的，不予登记并书面说明理由。 已经设立的基金会、社会团体、社会服务机构等非营利性组织，可以向办理其登记的民政部门申请认定为慈善组织，民政部门应当自受理申请之日起二十日内作出决定。符合慈善组织条件的，予以认定并向社会公告；不符合慈善组织条件的，不予认定并书面说明理由。 有特殊情况需要延长登记或者认定期限的，报经国务院民政部门批准，可以适当延长，但延长的期限不得超过六十日。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214010, '《中华人民共和国慈善法》', '第十一条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第二章 慈善组织', NULL, '慈善组织的章程，应当符合法律法规的规定，并载明下列事项： （一）名称和住所； （二）组织形式； （三）宗旨和活动范围； （四）财产来源及构成； （五）决策、执行机构的组成及职责； （六）内部监督机制； （七）财产管理使用制度； （八）项目管理制度； （九）终止情形及终止后的清算办法； （十）其他重要事项。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214011, '《中华人民共和国慈善法》', '第十二条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第二章 慈善组织', NULL, '慈善组织应当根据法律法规以及章程的规定，建立健全内部治理结构，明确决策、执行、监督等方面的职责权限，开展慈善活动。 慈善组织应当执行国家统一的会计制度，依法进行会计核算，建立健全会计监督制度，并接受政府有关部门的监督管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214012, '《中华人民共和国慈善法》', '第十三条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第二章 慈善组织', NULL, '慈善组织应当每年向办理其登记的民政部门报送年度工作报告和财务会计报告。报告应当包括年度开展募捐和接受捐赠、慈善财产的管理使用、慈善项目实施、募捐成本、慈善组织工作人员工资福利以及与境外组织或者个人开展合作等情况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214013, '《中华人民共和国慈善法》', '第十四条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第二章 慈善组织', NULL, '慈善组织的发起人、主要捐赠人以及管理人员，不得利用其关联关系损害慈善组织、受益人的利益和社会公共利益。 慈善组织的发起人、主要捐赠人以及管理人员与慈善组织发生交易行为的，不得参与慈善组织有关该交易行为的决策，有关交易情况应当向社会公开。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214014, '《中华人民共和国慈善法》', '第十五条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第二章 慈善组织', NULL, '慈善组织不得从事、资助危害国家安全和社会公共利益的活动，不得接受附加违反法律法规和违背社会公德条件的捐赠，不得对受益人附加违反法律法规和违背社会公德的条件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214015, '《中华人民共和国慈善法》', '第十六条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第二章 慈善组织', NULL, '有下列情形之一的，不得担任慈善组织的负责人： （一）无民事行为能力或者限制民事行为能力的； （二）因故意犯罪被判处刑罚，自刑罚执行完毕之日起未逾五年的； （三）在被吊销登记证书或者被取缔的组织担任负责人，自该组织被吊销登记证书或者被取缔之日起未逾五年的； （四）法律、行政法规规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214016, '《中华人民共和国慈善法》', '第十七条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第二章 慈善组织', NULL, '慈善组织有下列情形之一的，应当终止： （一）出现章程规定的终止情形的； （二）因分立、合并需要终止的； （三）连续二年未从事慈善活动的； （四）依法被撤销登记或者吊销登记证书的； （五）法律、行政法规规定应当终止的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214017, '《中华人民共和国慈善法》', '第十八条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第二章 慈善组织', NULL, '慈善组织终止，应当进行清算。 慈善组织的决策机构应当在本法第十七条规定的终止情形出现之日起三十日内成立清算组进行清算，并向社会公告。不成立清算组或者清算组不履行职责的，办理其登记的民政部门可以申请人民法院指定有关人员组成清算组进行清算。 慈善组织清算后的剩余财产，应当按照慈善组织章程的规定转给宗旨相同或者相近的慈善组织；章程未规定的，由办理其登记的民政部门主持转给宗旨相同或者相近的慈善组织，并向社会公告。 慈善组织清算结束后，应当向办理其登记的民政部门办理注销登记，并由民政部门向社会公告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214018, '《中华人民共和国慈善法》', '第十九条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第二章 慈善组织', NULL, '慈善组织依法成立行业组织。 慈善行业组织应当反映行业诉求，推动行业交流，提高慈善行业公信力，促进慈善事业发展。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214019, '《中华人民共和国慈善法》', '第二十条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第二章 慈善组织', NULL, '慈善组织的组织形式、登记管理的具体办法由国务院制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214020, '《中华人民共和国慈善法》', '第二十一条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第三章 慈善募捐', NULL, '本法所称慈善募捐，是指慈善组织基于慈善宗旨募集财产的活动。 慈善募捐，包括面向社会公众的公开募捐和面向特定对象的定向募捐。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214021, '《中华人民共和国慈善法》', '第二十二条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第三章 慈善募捐', NULL, '慈善组织开展公开募捐，应当取得公开募捐资格。依法登记满一年的慈善组织，可以向办理其登记的民政部门申请公开募捐资格。民政部门应当自受理申请之日起二十日内作出决定。慈善组织符合内部治理结构健全、运作规范的条件的，发给公开募捐资格证书；不符合条件的，不发给公开募捐资格证书并书面说明理由。 其他法律、行政法规规定可以公开募捐的非营利性组织，由县级以上人民政府民政部门直接发给公开募捐资格证书。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214022, '《中华人民共和国慈善法》', '第二十三条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第三章 慈善募捐', NULL, '开展公开募捐，可以采取下列方式： （一）在公共场所设置募捐箱； （二）举办面向社会公众的义演、义赛、义卖、义展、义拍、慈善晚会等； （三）通过广播、电视、报刊、互联网等媒体发布募捐信息； （四）其他公开募捐方式。 慈善组织采取前款第一项、第二项规定的方式开展公开募捐的，应当在办理其登记的民政部门管辖区域内进行，确有必要在办理其登记的民政部门管辖区域外进行的，应当报其开展募捐活动所在地的县级以上人民政府民政部门备案。捐赠人的捐赠行为不受地域限制。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214023, '《中华人民共和国慈善法》', '第二十四条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第三章 慈善募捐', NULL, '开展公开募捐，应当制定募捐方案。募捐方案包括募捐目的、起止时间和地域、活动负责人姓名和办公地址、接受捐赠方式、银行账户、受益人、募得款物用途、募捐成本、剩余财产的处理等。 募捐方案应当在开展募捐活动前报慈善组织登记的民政部门备案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214024, '《中华人民共和国慈善法》', '第二十五条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第三章 慈善募捐', NULL, '开展公开募捐，应当在募捐活动现场或者募捐活动载体的显著位置，公布募捐组织名称、公开募捐资格证书、募捐方案、联系方式、募捐信息查询方法等。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214025, '《中华人民共和国慈善法》', '第二十六条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第三章 慈善募捐', NULL, '不具有公开募捐资格的组织或者个人基于慈善目的，可以与具有公开募捐资格的慈善组织合作，由该慈善组织开展公开募捐，合作方不得以任何形式自行开展公开募捐。具有公开募捐资格的慈善组织应当对合作方进行评估，依法签订书面协议，在募捐方案中载明合作方的相关信息，并对合作方的相关行为进行指导和监督。 具有公开募捐资格的慈善组织负责对合作募得的款物进行管理和会计核算，将全部收支纳入其账户。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214026, '《中华人民共和国慈善法》', '第二十七条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第三章 慈善募捐', NULL, '慈善组织通过互联网开展公开募捐的，应当在国务院民政部门指定的互联网公开募捐服务平台进行，并可以同时在其网站进行。 国务院民政部门指定的互联网公开募捐服务平台，提供公开募捐信息展示、捐赠支付、捐赠财产使用情况查询等服务；无正当理由不得拒绝为具有公开募捐资格的慈善组织提供服务，不得向其收费，不得在公开募捐信息页面插入商业广告和商业活动链接。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214027, '《中华人民共和国慈善法》', '第二十八条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第三章 慈善募捐', NULL, '广播、电视、报刊以及网络服务提供者、电信运营商，应当对利用其平台开展公开募捐的慈善组织的登记证书、公开募捐资格证书进行验证。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214028, '《中华人民共和国慈善法》', '第二十九条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第三章 慈善募捐', NULL, '慈善组织自登记之日起可以开展定向募捐。 慈善组织开展定向募捐，应当在发起人、理事会成员和会员等特定对象的范围内进行，并向募捐对象说明募捐目的、募得款物用途等事项。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214029, '《中华人民共和国慈善法》', '第三十条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第三章 慈善募捐', NULL, '开展定向募捐，不得采取或者变相采取本法第二十三条规定的方式。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214030, '《中华人民共和国慈善法》', '第三十一条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第三章 慈善募捐', NULL, '开展募捐活动，应当尊重和维护募捐对象的合法权益，保障募捐对象的知情权，不得通过虚构事实等方式欺骗、诱导募捐对象实施捐赠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214031, '《中华人民共和国慈善法》', '第三十二条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第三章 慈善募捐', NULL, '开展募捐活动，不得摊派或者变相摊派，不得妨碍公共秩序、企业生产经营和居民生活。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214032, '《中华人民共和国慈善法》', '第三十三条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第三章 慈善募捐', NULL, '禁止任何组织或者个人假借慈善名义或者假冒慈善组织开展募捐活动，骗取财产。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214033, '《中华人民共和国慈善法》', '第三十四条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第四章 慈善捐赠', NULL, '本法所称慈善捐赠，是指自然人、法人和非法人组织基于慈善目的，自愿、无偿赠与财产的活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214034, '《中华人民共和国慈善法》', '第三十五条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第四章 慈善捐赠', NULL, '捐赠人可以通过慈善组织捐赠，也可以直接向受益人捐赠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214035, '《中华人民共和国慈善法》', '第三十六条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第四章 慈善捐赠', NULL, '捐赠人捐赠的财产应当是其有权处分的合法财产。捐赠财产包括货币、实物、房屋、有价证券、股权、知识产权等有形和无形财产。 捐赠人捐赠的实物应当具有使用价值，符合安全、卫生、环保等标准。 捐赠人捐赠本企业产品的，应当依法承担产品质量责任和义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214036, '《中华人民共和国慈善法》', '第三十七条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第四章 慈善捐赠', NULL, '自然人、法人和非法人组织开展演出、比赛、销售、拍卖等经营性活动，承诺将全部或者部分所得用于慈善目的的，应当在举办活动前与慈善组织或者其他接受捐赠的人签订捐赠协议，活动结束后按照捐赠协议履行捐赠义务，并将捐赠情况向社会公开。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214037, '《中华人民共和国慈善法》', '第三十八条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第四章 慈善捐赠', NULL, '慈善组织接受捐赠，应当向捐赠人开具由财政部门统一监（印）制的捐赠票据。捐赠票据应当载明捐赠人、捐赠财产的种类及数量、慈善组织名称和经办人姓名、票据日期等。捐赠人匿名或者放弃接受捐赠票据的，慈善组织应当做好相关记录。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214038, '《中华人民共和国慈善法》', '第三十九条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第四章 慈善捐赠', NULL, '慈善组织接受捐赠，捐赠人要求签订书面捐赠协议的，慈善组织应当与捐赠人签订书面捐赠协议。 书面捐赠协议包括捐赠人和慈善组织名称，捐赠财产的种类、数量、质量、用途、交付时间等内容。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214039, '《中华人民共和国慈善法》', '第四十条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第四章 慈善捐赠', NULL, '捐赠人与慈善组织约定捐赠财产的用途和受益人时，不得指定或者变相指定捐赠人的利害关系人作为受益人。 任何组织和个人不得利用慈善捐赠违反法律规定宣传烟草制品，不得利用慈善捐赠以任何方式宣传法律禁止宣传的产品和事项。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214040, '《中华人民共和国慈善法》', '第四十一条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第四章 慈善捐赠', NULL, '捐赠人应当按照捐赠协议履行捐赠义务。捐赠人违反捐赠协议逾期未交付捐赠财产，有下列情形之一的，慈善组织或者其他接受捐赠的人可以要求交付；捐赠人拒不交付的，慈善组织和其他接受捐赠的人可以依法向人民法院申请支付令或者提起诉讼： （一）捐赠人通过广播、电视、报刊、互联网等媒体公开承诺捐赠的； （二）捐赠财产用于本法第三条第一项至第三项规定的慈善活动，并签订书面捐赠协议的。 捐赠人公开承诺捐赠或者签订书面捐赠协议后经济状况显著恶化，严重影响其生产经营或者家庭生活的，经向公开承诺捐赠地或者书面捐赠协议签订地的县级以上人民政府民政部门报告并向社会公开说明情况后，可以不再履行捐赠义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214041, '《中华人民共和国慈善法》', '第四十二条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第四章 慈善捐赠', NULL, '捐赠人有权查询、复制其捐赠财产管理使用的有关资料，慈善组织应当及时主动向捐赠人反馈有关情况。 慈善组织违反捐赠协议约定的用途，滥用捐赠财产的，捐赠人有权要求其改正；拒不改正的，捐赠人可以向县级以上人民政府民政部门投诉、举报或者向人民法院提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214042, '《中华人民共和国慈善法》', '第四十三条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第四章 慈善捐赠', NULL, '国有企业实施慈善捐赠应当遵守有关国有资产管理的规定，履行批准和备案程序。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214043, '《中华人民共和国慈善法》', '第四十四条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第五章 慈善信托', NULL, '本法所称慈善信托属于公益信托，是指委托人基于慈善目的，依法将其财产委托给受托人，由受托人按照委托人意愿以受托人名义进行管理和处分，开展慈善活动的行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214044, '《中华人民共和国慈善法》', '第四十五条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第五章 慈善信托', NULL, '设立慈善信托、确定受托人和监察人，应当采取书面形式。受托人应当在慈善信托文件签订之日起七日内，将相关文件向受托人所在地县级以上人民政府民政部门备案。 未按照前款规定将相关文件报民政部门备案的，不享受税收优惠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214045, '《中华人民共和国慈善法》', '第四十六条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第五章 慈善信托', NULL, '慈善信托的委托人不得指定或者变相指定其利害关系人作为受益人。 慈善信托的受托人确定受益人，应当坚持公开、公平、公正的原则，不得指定或者变相指定受托人及其工作人员的利害关系人作为受益人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214046, '《中华人民共和国慈善法》', '第四十七条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第五章 慈善信托', NULL, '慈善信托的受托人，可以由委托人确定其信赖的慈善组织或者信托公司担任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214047, '《中华人民共和国慈善法》', '第四十八条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第五章 慈善信托', NULL, '慈善信托的受托人违反信托义务或者难以履行职责的，委托人可以变更受托人。变更后的受托人应当自变更之日起七日内，将变更情况报原备案的民政部门重新备案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214048, '《中华人民共和国慈善法》', '第四十九条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第五章 慈善信托', NULL, '慈善信托的受托人管理和处分信托财产，应当按照信托目的，恪尽职守，履行诚信、谨慎管理的义务。 慈善信托的受托人应当根据信托文件和委托人的要求，及时向委托人报告信托事务处理情况、信托财产管理使用情况。慈善信托的受托人应当每年至少一次将信托事务处理情况及财务状况向办理其备案的民政部门报告，并向社会公开。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214049, '《中华人民共和国慈善法》', '第五十条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第五章 慈善信托', NULL, '慈善信托的委托人根据需要，可以确定信托监察人。 信托监察人对受托人的行为进行监督，依法维护委托人和受益人的权益。信托监察人发现受托人违反信托义务或者难以履行职责的，应当向委托人报告，并有权以自己的名义向人民法院提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214050, '《中华人民共和国慈善法》', '第五十一条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第五章 慈善信托', NULL, '慈善信托的设立、信托财产的管理、信托当事人、信托的终止和清算等事项，本章未规定的，适用本法其他有关规定；本法未规定的，适用《中华人民共和国信托法》的有关规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214051, '《中华人民共和国慈善法》', '第五十二条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第六章 慈善财产', NULL, '慈善组织的财产包括： （一）发起人捐赠、资助的创始财产； （二）募集的财产； （三）其他合法财产。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214052, '《中华人民共和国慈善法》', '第五十三条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第六章 慈善财产', NULL, '慈善组织的财产应当根据章程和捐赠协议的规定全部用于慈善目的，不得在发起人、捐赠人以及慈善组织成员中分配。 任何组织和个人不得私分、挪用、截留或者侵占慈善财产。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214053, '《中华人民共和国慈善法》', '第五十四条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第六章 慈善财产', NULL, '慈善组织对募集的财产，应当登记造册，严格管理，专款专用。 捐赠人捐赠的实物不易储存、运输或者难以直接用于慈善目的的，慈善组织可以依法拍卖或者变卖，所得收入扣除必要费用后，应当全部用于慈善目的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214054, '《中华人民共和国慈善法》', '第五十五条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第六章 慈善财产', NULL, '慈善组织为实现财产保值、增值进行投资的，应当遵循合法、安全、有效的原则，投资取得的收益应当全部用于慈善目的。慈善组织的重大投资方案应当经决策机构组成人员三分之二以上同意。政府资助的财产和捐赠协议约定不得投资的财产，不得用于投资。慈善组织的负责人和工作人员不得在慈善组织投资的企业兼职或者领取报酬。 前款规定事项的具体办法，由国务院民政部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214055, '《中华人民共和国慈善法》', '第五十六条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第六章 慈善财产', NULL, '慈善组织开展慈善活动，应当依照法律法规和章程的规定，按照募捐方案或者捐赠协议使用捐赠财产。慈善组织确需变更募捐方案规定的捐赠财产用途的，应当报原备案的民政部门备案；确需变更捐赠协议约定的捐赠财产用途的，应当征得捐赠人同意。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214056, '《中华人民共和国慈善法》', '第五十七条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第六章 慈善财产', NULL, '慈善组织应当合理设计慈善项目，优化实施流程，降低运行成本，提高慈善财产使用效益。 慈善组织应当建立项目管理制度，对项目实施情况进行跟踪监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214057, '《中华人民共和国慈善法》', '第五十八条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第六章 慈善财产', NULL, '慈善项目终止后捐赠财产有剩余的，按照募捐方案或者捐赠协议处理；募捐方案未规定或者捐赠协议未约定的，慈善组织应当将剩余财产用于目的相同或者相近的其他慈善项目，并向社会公开。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214058, '《中华人民共和国慈善法》', '第五十九条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第六章 慈善财产', NULL, '慈善组织确定慈善受益人，应当坚持公开、公平、公正的原则，不得指定或者变相指定慈善组织管理人员的利害关系人作为受益人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214059, '《中华人民共和国慈善法》', '第六十条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第六章 慈善财产', NULL, '慈善组织根据需要可以与受益人签订协议，明确双方权利义务，约定慈善财产的用途、数额和使用方式等内容。 受益人应当珍惜慈善资助，按照协议使用慈善财产。受益人未按照协议使用慈善财产或者有其他严重违反协议情形的，慈善组织有权要求其改正；受益人拒不改正的，慈善组织有权解除协议并要求受益人返还财产。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214060, '《中华人民共和国慈善法》', '第六十一条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第六章 慈善财产', NULL, '慈善组织应当积极开展慈善活动，遵循管理费用、募捐成本等最必要原则，厉行节约，减少不必要的开支，充分、高效运用慈善财产。具有公开募捐资格的基金会开展慈善活动的年度支出，不得低于上一年总收入的百分之七十或者前三年收入平均数额的百分之七十；年度管理费用不得超过当年总支出的百分之十；特殊情况下，年度支出和管理费用难以符合前述规定的，应当报告办理其登记的民政部门并向社会公开说明情况。 慈善组织开展慈善活动的年度支出、管理费用和募捐成本的标准由国务院民政部门会同财政、税务等部门制定。 捐赠协议对单项捐赠财产的慈善活动支出和管理费用有约定的，按照其约定。 慈善信托的年度支出和管理费用标准，由国务院民政部门会同财政、税务和金融监督管理等部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214061, '《中华人民共和国慈善法》', '第六十二条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第七章 慈善服务', NULL, '本法所称慈善服务，是指慈善组织和其他组织以及个人基于慈善目的，向社会或者他人提供的志愿无偿服务以及其他非营利服务。 慈善组织开展慈善服务，可以自己提供或者招募志愿者提供，也可以委托有服务专长的其他组织提供。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214062, '《中华人民共和国慈善法》', '第六十三条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第七章 慈善服务', NULL, '开展慈善服务，应当尊重受益人、志愿者的人格尊严，不得侵害受益人、志愿者的隐私。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214063, '《中华人民共和国慈善法》', '第六十四条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第七章 慈善服务', NULL, '开展医疗康复、教育培训等慈善服务，需要专门技能的，应当执行国家或者行业组织制定的标准和规程。 慈善组织招募志愿者参与慈善服务，需要专门技能的，应当对志愿者开展相关培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214064, '《中华人民共和国慈善法》', '第六十五条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第七章 慈善服务', NULL, '慈善组织招募志愿者参与慈善服务，应当公示与慈善服务有关的全部信息，告知服务过程中可能发生的风险。 慈善组织根据需要可以与志愿者签订协议，明确双方权利义务，约定服务的内容、方式和时间等。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214065, '《中华人民共和国慈善法》', '第六十六条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第七章 慈善服务', NULL, '慈善组织应当对志愿者实名登记，记录志愿者的服务时间、内容、评价等信息。根据志愿者的要求，慈善组织应当无偿、如实出具志愿服务记录证明。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214066, '《中华人民共和国慈善法》', '第六十七条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第七章 慈善服务', NULL, '慈善组织安排志愿者参与慈善服务，应当与志愿者的年龄、文化程度、技能和身体状况相适应。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214067, '《中华人民共和国慈善法》', '第六十八条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第七章 慈善服务', NULL, '志愿者接受慈善组织安排参与慈善服务的，应当服从管理，接受必要的培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214068, '《中华人民共和国慈善法》', '第六十九条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第七章 慈善服务', NULL, '慈善组织应当为志愿者参与慈善服务提供必要条件，保障志愿者的合法权益。 慈善组织安排志愿者参与可能发生人身危险的慈善服务前，应当为志愿者购买相应的人身意外伤害保险。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214069, '《中华人民共和国慈善法》', '第七十条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第八章 应急慈善', NULL, '发生重大突发事件需要迅速开展救助时，履行统一领导职责或者组织处置突发事件的人民政府应当依法建立协调机制，明确专门机构、人员，提供需求信息，及时有序引导慈善组织、志愿者等社会力量开展募捐和救助活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214070, '《中华人民共和国慈善法》', '第七十一条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第八章 应急慈善', NULL, '国家鼓励慈善组织、慈善行业组织建立应急机制，加强信息共享、协商合作，提高慈善组织运行和慈善资源使用的效率。 在发生重大突发事件时，鼓励慈善组织、志愿者等在有关人民政府的协调引导下依法开展或者参与慈善活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214071, '《中华人民共和国慈善法》', '第七十二条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第八章 应急慈善', NULL, '为应对重大突发事件开展公开募捐的，应当及时分配或者使用募得款物，在应急处置与救援阶段至少每五日公开一次募得款物的接收情况，及时公开分配、使用情况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214072, '《中华人民共和国慈善法》', '第七十三条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第八章 应急慈善', NULL, '为应对重大突发事件开展公开募捐，无法在募捐活动前办理募捐方案备案的，应当在活动开始后十日内补办备案手续。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214073, '《中华人民共和国慈善法》', '第七十四条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第八章 应急慈善', NULL, '县级以上人民政府及其有关部门应当为捐赠款物分配送达提供便利条件。乡级人民政府、街道办事处和村民委员会、居民委员会，应当为捐赠款物分配送达、信息统计等提供力所能及的帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214074, '《中华人民共和国慈善法》', '第七十五条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第九章 信息公开', NULL, '国家建立健全慈善信息统计和发布制度。 国务院民政部门建立健全统一的慈善信息平台，免费提供慈善信息发布服务。 县级以上人民政府民政部门应当在前款规定的平台及时向社会公开慈善信息。 慈善组织和慈善信托的受托人应当在本条第二款规定的平台发布慈善信息，并对信息的真实性负责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214075, '《中华人民共和国慈善法》', '第七十六条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第九章 信息公开', NULL, '县级以上人民政府民政部门和其他有关部门应当及时向社会公开下列慈善信息： （一）慈善组织登记事项； （二）慈善信托备案事项； （三）具有公开募捐资格的慈善组织名单； （四）具有出具公益性捐赠税前扣除票据资格的慈善组织名单； （五）对慈善活动的税收优惠、资助补贴等促进措施； （六）向慈善组织购买服务的信息； （七）对慈善组织、慈善信托开展检查、评估的结果； （八）对慈善组织和其他组织以及个人的表彰、处罚结果； （九）法律法规规定应当公开的其他信息。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214076, '《中华人民共和国慈善法》', '第七十七条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第九章 信息公开', NULL, '慈善组织、慈善信托的受托人应当依法履行信息公开义务。信息公开应当真实、完整、及时。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214077, '《中华人民共和国慈善法》', '第七十八条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第九章 信息公开', NULL, '慈善组织应当向社会公开组织章程和决策、执行、监督机构成员信息以及国务院民政部门要求公开的其他信息。上述信息有重大变更的，慈善组织应当及时向社会公开。 慈善组织应当每年向社会公开其年度工作报告和财务会计报告。具有公开募捐资格的慈善组织的财务会计报告须经审计。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214078, '《中华人民共和国慈善法》', '第七十九条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第九章 信息公开', NULL, '具有公开募捐资格的慈善组织应当定期向社会公开其募捐情况和慈善项目实施情况。 公开募捐周期超过六个月的，至少每三个月公开一次募捐情况，公开募捐活动结束后三个月内应当全面、详细公开募捐情况。 慈善项目实施周期超过六个月的，至少每三个月公开一次项目实施情况，项目结束后三个月内应当全面、详细公开项目实施情况和募得款物使用情况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214079, '《中华人民共和国慈善法》', '第八十条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第九章 信息公开', NULL, '慈善组织开展定向募捐的，应当及时向捐赠人告知募捐情况、募得款物的管理使用情况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214080, '《中华人民共和国慈善法》', '第八十一条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第九章 信息公开', NULL, '慈善组织、慈善信托的受托人应当向受益人告知其资助标准、工作流程和工作规范等信息。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214081, '《中华人民共和国慈善法》', '第八十二条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第九章 信息公开', NULL, '涉及国家秘密、商业秘密、个人隐私的信息以及捐赠人、慈善信托的委托人不同意公开的姓名、名称、住所、通讯方式等信息，不得公开。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214082, '《中华人民共和国慈善法》', '第八十三条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十章 促进措施', NULL, '县级以上人民政府应当将慈善事业纳入国民经济和社会发展规划，制定促进慈善事业发展的政策和措施。 县级以上人民政府有关部门应当在各自职责范围内，向慈善组织、慈善信托受托人等提供慈善需求信息，为慈善活动提供指导和帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214083, '《中华人民共和国慈善法》', '第八十四条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十章 促进措施', NULL, '县级以上人民政府民政部门应当建立与其他部门之间的慈善信息共享机制。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214084, '《中华人民共和国慈善法》', '第八十五条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十章 促进措施', NULL, '国家鼓励、引导、支持有意愿有能力的自然人、法人和非法人组织积极参与慈善事业。 国家对慈善事业实施税收优惠政策，具体办法由国务院财政、税务部门会同民政部门依照税收法律、行政法规的规定制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214085, '《中华人民共和国慈善法》', '第八十六条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十章 促进措施', NULL, '慈善组织及其取得的收入依法享受税收优惠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214086, '《中华人民共和国慈善法》', '第八十七条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十章 促进措施', NULL, '自然人、法人和非法人组织捐赠财产用于慈善活动的，依法享受税收优惠。企业慈善捐赠支出超过法律规定的准予在计算企业所得税应纳税所得额时当年扣除的部分，允许结转以后三年内在计算应纳税所得额时扣除。 境外捐赠用于慈善活动的物资，依法减征或者免征进口关税和进口环节增值税。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214087, '《中华人民共和国慈善法》', '第八十八条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十章 促进措施', NULL, '自然人、法人和非法人组织设立慈善信托开展慈善活动的，依法享受税收优惠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214088, '《中华人民共和国慈善法》', '第八十九条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十章 促进措施', NULL, '受益人接受慈善捐赠，依法享受税收优惠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214089, '《中华人民共和国慈善法》', '第九十条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十章 促进措施', NULL, '慈善组织、捐赠人、受益人依法享受税收优惠的，有关部门应当及时办理相关手续。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214090, '《中华人民共和国慈善法》', '第九十一条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十章 促进措施', NULL, '捐赠人向慈善组织捐赠实物、有价证券、股权和知识产权的，依法免征权利转让的相关行政事业性费用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214091, '《中华人民共和国慈善法》', '第九十二条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十章 促进措施', NULL, '国家对开展扶贫济困、参与重大突发事件应对、参与重大国家战略的慈善活动，实行特殊的优惠政策。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214092, '《中华人民共和国慈善法》', '第九十三条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十章 促进措施', NULL, '慈善组织开展本法第三条第一项、第二项规定的慈善活动需要慈善服务设施用地的，可以依法申请使用国有划拨土地或者农村集体建设用地。慈善服务设施用地非经法定程序不得改变用途。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214093, '《中华人民共和国慈善法》', '第九十四条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十章 促进措施', NULL, '国家为慈善事业提供金融政策支持，鼓励金融机构为慈善组织、慈善信托提供融资和结算等金融服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214094, '《中华人民共和国慈善法》', '第九十五条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十章 促进措施', NULL, '各级人民政府及其有关部门可以依法通过购买服务等方式，支持符合条件的慈善组织向社会提供服务，并依照有关政府采购的法律法规向社会公开相关情况。 国家鼓励在慈善领域应用现代信息技术；鼓励社会力量通过公益创投、孵化培育、人员培训、项目指导等方式，为慈善组织提供资金支持和能力建设服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214095, '《中华人民共和国慈善法》', '第九十六条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十章 促进措施', NULL, '国家鼓励有条件的地方设立社区慈善组织，加强社区志愿者队伍建设，发展社区慈善事业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214096, '《中华人民共和国慈善法》', '第九十七条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十章 促进措施', NULL, '国家采取措施弘扬慈善文化，培育公民慈善意识。 学校等教育机构应当将慈善文化纳入教育教学内容。国家鼓励高等学校培养慈善专业人才，支持高等学校和科研机构开展慈善理论研究。 广播、电视、报刊、互联网等媒体应当积极开展慈善公益宣传活动，普及慈善知识，传播慈善文化。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214097, '《中华人民共和国慈善法》', '第九十八条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十章 促进措施', NULL, '国家鼓励企业事业单位和其他组织为开展慈善活动提供场所和其他便利条件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214098, '《中华人民共和国慈善法》', '第九十九条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十章 促进措施', NULL, '经受益人同意，捐赠人对其捐赠的慈善项目可以冠名纪念，法律法规规定需要批准的，从其规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214099, '《中华人民共和国慈善法》', '第一百条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十章 促进措施', NULL, '国家建立慈善表彰制度，对在慈善事业发展中做出突出贡献的自然人、法人和非法人组织，由县级以上人民政府或者有关部门予以表彰。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214100, '《中华人民共和国慈善法》', '第一百零一条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十章 促进措施', NULL, '县级以上人民政府民政等有关部门将慈善捐赠、志愿服务记录等信息纳入相关主体信用记录，健全信用激励制度。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214101, '《中华人民共和国慈善法》', '第一百零二条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十章 促进措施', NULL, '国家鼓励开展慈善国际交流与合作。 慈善组织接受境外慈善捐赠、与境外组织或者个人合作开展慈善活动的，根据国家有关规定履行批准、备案程序。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214102, '《中华人民共和国慈善法》', '第一百零三条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十一章 监督管理', NULL, '县级以上人民政府民政部门应当依法履行职责，对慈善活动进行监督检查，对慈善行业组织进行指导。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214103, '《中华人民共和国慈善法》', '第一百零四条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十一章 监督管理', NULL, '县级以上人民政府民政部门对涉嫌违反本法规定的慈善组织、慈善信托的受托人，有权采取下列措施： （一）对慈善组织、慈善信托的受托人的住所和慈善活动发生地进行现场检查； （二）要求慈善组织、慈善信托的受托人作出说明，查阅、复制有关资料； （三）向与慈善活动有关的单位和个人调查与监督管理有关的情况； （四）经本级人民政府批准，可以查询慈善组织的金融账户； （五）法律、行政法规规定的其他措施。 慈善组织、慈善信托的受托人涉嫌违反本法规定的，县级以上人民政府民政部门可以对有关负责人进行约谈，要求其说明情况、提出改进措施。 其他慈善活动参与者涉嫌违反本法规定的，县级以上人民政府民政部门可以会同有关部门调查和处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214104, '《中华人民共和国慈善法》', '第一百零五条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十一章 监督管理', NULL, '县级以上人民政府民政部门对慈善组织、有关单位和个人进行检查或者调查时，检查人员或者调查人员不得少于二人，并应当出示合法证件和检查、调查通知书。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214105, '《中华人民共和国慈善法》', '第一百零六条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十一章 监督管理', NULL, '县级以上人民政府民政部门应当建立慈善组织及其负责人、慈善信托的受托人信用记录制度，并向社会公布。 县级以上人民政府民政部门应当建立慈善组织评估制度，鼓励和支持第三方机构对慈善组织的内部治理、财务状况、项目开展情况以及信息公开等进行评估，并向社会公布评估结果。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214106, '《中华人民共和国慈善法》', '第一百零七条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十一章 监督管理', NULL, '慈善行业组织应当建立健全行业规范，加强行业自律。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214107, '《中华人民共和国慈善法》', '第一百零八条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十一章 监督管理', NULL, '任何单位和个人发现慈善组织、慈善信托有违法行为的，可以向县级以上人民政府民政部门、其他有关部门或者慈善行业组织投诉、举报。民政部门、其他有关部门或者慈善行业组织接到投诉、举报后，应当及时调查处理。 国家鼓励公众、媒体对慈善活动进行监督，对假借慈善名义或者假冒慈善组织骗取财产以及慈善组织、慈善信托的违法违规行为予以曝光，发挥舆论和社会监督作用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214108, '《中华人民共和国慈善法》', '第一百零九条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十二章 法律责任', NULL, '慈善组织有下列情形之一的，由县级以上人民政府民政部门责令限期改正，予以警告或者责令限期停止活动，并没收违法所得；情节严重的，吊销登记证书并予以公告： （一）未按照慈善宗旨开展活动的； （二）私分、挪用、截留或者侵占慈善财产的； （三）接受附加违反法律法规或者违背社会公德条件的捐赠，或者对受益人附加违反法律法规或者违背社会公德的条件的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214109, '《中华人民共和国慈善法》', '第一百一十条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十二章 法律责任', NULL, '慈善组织有下列情形之一的，由县级以上人民政府民政部门责令限期改正，予以警告，并没收违法所得；逾期不改正的，责令限期停止活动并进行整改： （一）违反本法第十四条规定造成慈善财产损失的； （二）指定或者变相指定捐赠人、慈善组织管理人员的利害关系人作为受益人的； （三）将不得用于投资的财产用于投资的； （四）擅自改变捐赠财产用途的； （五）因管理不善造成慈善财产重大损失的； （六）开展慈善活动的年度支出、管理费用或者募捐成本违反规定的； （七）未依法履行信息公开义务的； （八）未依法报送年度工作报告、财务会计报告或者报备募捐方案的； （九）泄露捐赠人、志愿者、受益人个人隐私以及捐赠人、慈善信托的委托人不同意公开的姓名、名称、住所、通讯方式等信息的。 慈善组织违反本法规定泄露国家秘密、商业秘密的，依照有关法律的规定予以处罚。 慈善组织有前两款规定的情形，经依法处理后一年内再出现前款规定的情形，或者有其他情节严重情形的，由县级以上人民政府民政部门吊销登记证书并予以公告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214110, '《中华人民共和国慈善法》', '第一百一十一条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十二章 法律责任', NULL, '慈善组织开展募捐活动有下列情形之一的，由县级以上人民政府民政部门予以警告，责令停止募捐活动；责令退还违法募集的财产，无法退还的，由民政部门予以收缴，转给其他慈善组织用于慈善目的；情节严重的，吊销公开募捐资格证书或者登记证书并予以公告，公开募捐资格证书被吊销的，五年内不得再次申请： （一）通过虚构事实等方式欺骗、诱导募捐对象实施捐赠的； （二）向单位或者个人摊派或者变相摊派的； （三）妨碍公共秩序、企业生产经营或者居民生活的； （四）与不具有公开募捐资格的组织或者个人合作，违反本法第二十六条规定的； （五）通过互联网开展公开募捐，违反本法第二十七条规定的； （六）为应对重大突发事件开展公开募捐，不及时分配、使用募得款物的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214111, '《中华人民共和国慈善法》', '第一百一十二条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十二章 法律责任', NULL, '慈善组织有本法第一百零九条、第一百一十条、第一百一十一条规定情形的，由县级以上人民政府民政部门对直接负责的主管人员和其他直接责任人员处二万元以上二十万元以下罚款，并没收违法所得；情节严重的，禁止其一年至五年内担任慈善组织的管理人员。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214112, '《中华人民共和国慈善法》', '第一百一十三条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十二章 法律责任', NULL, '不具有公开募捐资格的组织或者个人擅自开展公开募捐的，由县级以上人民政府民政部门予以警告，责令停止募捐活动；责令退还违法募集的财产，无法退还的，由民政部门予以收缴，转给慈善组织用于慈善目的；情节严重的，对有关组织或者个人处二万元以上二十万元以下罚款。 自然人、法人或者非法人组织假借慈善名义或者假冒慈善组织骗取财产的，由公安机关依法查处。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214113, '《中华人民共和国慈善法》', '第一百一十四条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十二章 法律责任', NULL, '互联网公开募捐服务平台违反本法第二十七条规定的，由省级以上人民政府民政部门责令限期改正；逾期不改正的，由国务院民政部门取消指定。 未经指定的互联网信息服务提供者擅自提供互联网公开募捐服务的，由县级以上人民政府民政部门责令限期改正；逾期不改正的，由县级以上人民政府民政部门会同网信、工业和信息化部门依法进行处理。 广播、电视、报刊以及网络服务提供者、电信运营商未依法履行验证义务的，由其主管部门责令限期改正，予以警告；逾期不改正的，予以通报批评。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214114, '《中华人民共和国慈善法》', '第一百一十五条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十二章 法律责任', NULL, '慈善组织不依法向捐赠人开具捐赠票据、不依法向志愿者出具志愿服务记录证明或者不及时主动向捐赠人反馈有关情况的，由县级以上人民政府民政部门予以警告，责令限期改正；逾期不改正的，责令限期停止活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214115, '《中华人民共和国慈善法》', '第一百一十六条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十二章 法律责任', NULL, '慈善组织弄虚作假骗取税收优惠的，由税务机关依法查处；情节严重的，由县级以上人民政府民政部门吊销登记证书并予以公告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214116, '《中华人民共和国慈善法》', '第一百一十七条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十二章 法律责任', NULL, '慈善组织从事、资助危害国家安全或者社会公共利益活动的，由有关机关依法查处，由县级以上人民政府民政部门吊销登记证书并予以公告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214117, '《中华人民共和国慈善法》', '第一百一十八条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十二章 法律责任', NULL, '慈善信托的委托人、受托人有下列情形之一的，由县级以上人民政府民政部门责令限期改正，予以警告，并没收违法所得；对直接负责的主管人员和其他直接责任人员处二万元以上二十万元以下罚款： （一）将信托财产及其收益用于非慈善目的的； （二）指定或者变相指定委托人、受托人及其工作人员的利害关系人作为受益人的； （三）未按照规定将信托事务处理情况及财务状况向民政部门报告的； （四）违反慈善信托的年度支出或者管理费用标准的； （五）未依法履行信息公开义务的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214118, '《中华人民共和国慈善法》', '第一百一十九条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十二章 法律责任', NULL, '慈善服务过程中，因慈善组织或者志愿者过错造成受益人、第三人损害的，慈善组织依法承担赔偿责任；损害是由志愿者故意或者重大过失造成的，慈善组织可以向其追偿。 志愿者在参与慈善服务过程中，因慈善组织过错受到损害的，慈善组织依法承担赔偿责任；损害是由不可抗力造成的，慈善组织应当给予适当补偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214119, '《中华人民共和国慈善法》', '第一百二十条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十二章 法律责任', NULL, '县级以上人民政府民政部门和其他有关部门及其工作人员有下列情形之一的，由上级机关或者监察机关责令改正；依法应当给予处分的，由任免机关或者监察机关对直接负责的主管人员和其他直接责任人员给予处分： （一）未依法履行信息公开义务的； （二）摊派或者变相摊派捐赠任务，强行指定志愿者、慈善组织提供服务的； （三）未依法履行监督管理职责的； （四）违法实施行政强制措施和行政处罚的； （五）私分、挪用、截留或者侵占慈善财产的； （六）其他滥用职权、玩忽职守、徇私舞弊的行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214120, '《中华人民共和国慈善法》', '第一百二十一条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十二章 法律责任', NULL, '违反本法规定，构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214121, '《中华人民共和国慈善法》', '第一百二十二条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十三章 附 则', NULL, '城乡社区组织、单位可以在本社区、单位内部开展群众性互助互济活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214122, '《中华人民共和国慈善法》', '第一百二十三条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十三章 附 则', NULL, '慈善组织以外的其他组织可以开展力所能及的慈善活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214123, '《中华人民共和国慈善法》', '第一百二十四条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十三章 附 则', NULL, '个人因疾病等原因导致家庭经济困难，向社会发布求助信息的，求助人和信息发布人应当对信息真实性负责，不得通过虚构、隐瞒事实等方式骗取救助。 从事个人求助网络服务的平台应当经国务院民政部门指定，对通过其发布的求助信息真实性进行查验，并及时、全面向社会公开相关信息。具体管理办法由国务院民政部门会同网信、工业和信息化等部门另行制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (214124, '《中华人民共和国慈善法》', '第一百二十五条', '社会', '法律', NULL, '全国人民代表大会 2023-12-29', '第十三章 附 则', NULL, '本法自2016年9月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215000, '《中华人民共和国红十字会法》', '第一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第一章 总 则', NULL, '为了保护人的生命和健康，维护人的尊严，发扬人道主义精神，促进和平进步事业，保障和规范红十字会依法履行职责，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215001, '《中华人民共和国红十字会法》', '第二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第一章 总 则', NULL, '中国红十字会是中华人民共和国统一的红十字组织，是从事人道主义工作的社会救助团体。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215002, '《中华人民共和国红十字会法》', '第三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第一章 总 则', NULL, '中华人民共和国公民，不分民族、种族、性别、职业、宗教信仰、教育程度，承认中国红十字会章程并缴纳会费的，可以自愿参加中国红十字会。 企业、事业单位及有关团体通过申请可以成为红十字会的团体会员。 国家鼓励自然人、法人以及其他组织参与红十字志愿服务。 国家支持在学校开展红十字青少年工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215003, '《中华人民共和国红十字会法》', '第四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第一章 总 则', NULL, '中国红十字会应当遵守宪法和法律，遵循国际红十字和红新月运动确立的基本原则，依照中国批准或者加入的日内瓦公约及其附加议定书和中国红十字会章程，独立自主地开展工作。 中国红十字会全国会员代表大会依法制定或者修改中国红十字会章程，章程不得与宪法和法律相抵触。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215004, '《中华人民共和国红十字会法》', '第五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第一章 总 则', NULL, '各级人民政府对红十字会给予支持和资助，保障红十字会依法履行职责，并对其活动进行监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215005, '《中华人民共和国红十字会法》', '第六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第一章 总 则', NULL, '中国红十字会根据独立、平等、互相尊重的原则，发展同各国红十字会和红新月会的友好合作关系。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215006, '《中华人民共和国红十字会法》', '第七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第二章 组 织', NULL, '全国建立中国红十字会总会。中国红十字会总会对外代表中国红十字会。 县级以上地方按行政区域建立地方各级红十字会，根据实际工作需要配备专职工作人员。 全国性行业根据需要可以建立行业红十字会。 上级红十字会指导下级红十字会工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215007, '《中华人民共和国红十字会法》', '第八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第二章 组 织', NULL, '各级红十字会设立理事会、监事会。理事会、监事会由会员代表大会选举产生，向会员代表大会负责并报告工作，接受其监督。 理事会民主选举产生会长和副会长。理事会执行会员代表大会的决议。 执行委员会是理事会的常设执行机构，其人员组成由理事会决定，向理事会负责并报告工作。 监事会民主推选产生监事长和副监事长。理事会、执行委员会工作受监事会监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215008, '《中华人民共和国红十字会法》', '第九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第二章 组 织', NULL, '中国红十字会总会可以设名誉会长和名誉副会长。名誉会长和名誉副会长由中国红十字会总会理事会聘请。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215009, '《中华人民共和国红十字会法》', '第十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第二章 组 织', NULL, '中国红十字会总会具有社会团体法人资格；地方各级红十字会、行业红十字会依法取得社会团体法人资格。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215010, '《中华人民共和国红十字会法》', '第十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第三章 职 责', NULL, '红十字会履行下列职责： （一）开展救援、救灾的相关工作，建立红十字应急救援体系。在战争、武装冲突和自然灾害、事故灾难、公共卫生事件等突发事件中，对伤病人员和其他受害者提供紧急救援和人道救助； （二）开展应急救护培训，普及应急救护、防灾避险和卫生健康知识，组织志愿者参与现场救护； （三）参与、推动无偿献血、遗体和人体器官捐献工作，参与开展造血干细胞捐献的相关工作； （四）组织开展红十字志愿服务、红十字青少年工作； （五）参加国际人道主义救援工作； （六）宣传国际红十字和红新月运动的基本原则和日内瓦公约及其附加议定书； （七）依照国际红十字和红新月运动的基本原则，完成人民政府委托事宜； （八）依照日内瓦公约及其附加议定书的有关规定开展工作； （九）协助人民政府开展与其职责相关的其他人道主义服务活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215011, '《中华人民共和国红十字会法》', '第十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第三章 职 责', NULL, '在战争、武装冲突和自然灾害、事故灾难、公共卫生事件等突发事件中，执行救援、救助任务并标有红十字标志的人员、物资和交通工具有优先通行的权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215012, '《中华人民共和国红十字会法》', '第十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第三章 职 责', NULL, '任何组织和个人不得阻碍红十字会工作人员依法履行救援、救助、救护职责。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215013, '《中华人民共和国红十字会法》', '第十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第四章 标志与名称', NULL, '中国红十字会使用白底红十字标志。 红十字标志具有保护作用和标明作用。 红十字标志的保护使用，是标示在战争、武装冲突中必须受到尊重和保护的人员和设备、设施。其使用办法，依照日内瓦公约及其附加议定书的有关规定执行。 红十字标志的标明使用，是标示与红十字活动有关的人或者物。其使用办法，由国务院和中央军事委员会依据本法规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215014, '《中华人民共和国红十字会法》', '第十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第四章 标志与名称', NULL, '国家武装力量的医疗卫生机构使用红十字标志，应当符合日内瓦公约及其附加议定书的有关规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215015, '《中华人民共和国红十字会法》', '第十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第四章 标志与名称', NULL, '红十字标志和名称受法律保护。禁止利用红十字标志和名称牟利，禁止以任何形式冒用、滥用、篡改红十字标志和名称。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215016, '《中华人民共和国红十字会法》', '第十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第五章 财产与监管', NULL, '红十字会财产的主要来源： （一）红十字会会员缴纳的会费； （二）境内外组织和个人捐赠的款物； （三）动产和不动产的收入； （四）人民政府的拨款； （五）其他合法收入。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215017, '《中华人民共和国红十字会法》', '第十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第五章 财产与监管', NULL, '国家对红十字会兴办的与其宗旨相符的公益事业给予扶持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215018, '《中华人民共和国红十字会法》', '第十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第五章 财产与监管', NULL, '红十字会可以依法进行募捐活动。募捐活动应当符合《中华人民共和国慈善法》的有关规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215019, '《中华人民共和国红十字会法》', '第二十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第五章 财产与监管', NULL, '红十字会依法接受自然人、法人以及其他组织捐赠的款物，应当向捐赠人开具由财政部门统一监（印）制的公益事业捐赠票据。捐赠人匿名或者放弃接受捐赠票据的，红十字会应当做好相关记录。 捐赠人依法享受税收优惠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215020, '《中华人民共和国红十字会法》', '第二十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第五章 财产与监管', NULL, '红十字会应当按照募捐方案、捐赠人意愿或者捐赠协议处分其接受的捐赠款物。 捐赠人有权查询、复制其捐赠财产管理使用的有关资料，红十字会应当及时主动向捐赠人反馈有关情况。 红十字会违反募捐方案、捐赠人意愿或者捐赠协议约定的用途，滥用捐赠财产的，捐赠人有权要求其改正；拒不改正的，捐赠人可以向人民政府民政部门投诉、举报或者向人民法院提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215021, '《中华人民共和国红十字会法》', '第二十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第五章 财产与监管', NULL, '红十字会应当建立财务管理、内部控制、审计公开和监督检查制度。 红十字会的财产使用应当与其宗旨相一致。 红十字会对接受的境外捐赠款物，应当建立专项审查监督制度。 红十字会应当及时聘请依法设立的独立第三方机构，对捐赠款物的收入和使用情况进行审计，将审计结果向红十字会理事会和监事会报告，并向社会公布。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215022, '《中华人民共和国红十字会法》', '第二十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第五章 财产与监管', NULL, '红十字会应当建立健全信息公开制度，规范信息发布，在统一的信息平台及时向社会公布捐赠款物的收入和使用情况，接受社会监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215023, '《中华人民共和国红十字会法》', '第二十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第五章 财产与监管', NULL, '红十字会财产的收入和使用情况依法接受人民政府审计等部门的监督。 红十字会接受社会捐赠及其使用情况，依法接受人民政府民政部门的监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215024, '《中华人民共和国红十字会法》', '第二十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第五章 财产与监管', NULL, '任何组织和个人不得私分、挪用、截留或者侵占红十字会的财产。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215025, '《中华人民共和国红十字会法》', '第二十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第六章 法律责任', NULL, '红十字会及其工作人员有下列情形之一的，由同级人民政府审计、民政等部门责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分；造成损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任： （一）违背募捐方案、捐赠人意愿或者捐赠协议，擅自处分其接受的捐赠款物的； （二）私分、挪用、截留或者侵占财产的； （三）未依法向捐赠人反馈情况或者开具捐赠票据的； （四）未依法对捐赠款物的收入和使用情况进行审计的； （五）未依法公开信息的； （六）法律、法规规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215026, '《中华人民共和国红十字会法》', '第二十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第六章 法律责任', NULL, '自然人、法人或者其他组织有下列情形之一，造成损害的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任： （一）冒用、滥用、篡改红十字标志和名称的； （二）利用红十字标志和名称牟利的； （三）制造、发布、传播虚假信息，损害红十字会名誉的； （四）盗窃、损毁或者以其他方式侵害红十字会财产的； （五）阻碍红十字会工作人员依法履行救援、救助、救护职责的； （六）法律、法规规定的其他情形。 红十字会及其工作人员有前款第一项、第二项所列行为的，按照前款规定处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215027, '《中华人民共和国红十字会法》', '第二十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第六章 法律责任', NULL, '各级人民政府有关部门及其工作人员在实施监督管理中滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215028, '《中华人民共和国红十字会法》', '第二十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第七章 附 则', NULL, '本法所称“国际红十字和红新月运动确立的基本原则”，是指一九八六年十月日内瓦国际红十字大会第二十五次会议通过的“国际红十字和红新月运动章程”中确立的人道、公正、中立、独立、志愿服务、统一和普遍七项基本原则。 本法所称“日内瓦公约”，是指中国批准的于一九四九年八月十二日订立的日内瓦四公约，即：《改善战地武装部队伤者病者境遇之日内瓦公约》、《改善海上武装部队伤者病者及遇船难者境遇之日内瓦公约》、《关于战俘待遇之日内瓦公约》和《关于战时保护平民之日内瓦公约》。 本法所称日内瓦公约“附加议定书”，是指中国加入的于一九七七年六月八日订立的《一九四九年八月十二日日内瓦四公约关于保护国际性武装冲突受难者的附加议定书》和《一九四九年八月十二日日内瓦四公约关于保护非国际性武装冲突受难者的附加议定书》。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (215029, '《中华人民共和国红十字会法》', '第三十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-02-24', '第七章 附 则', NULL, '本法自2017年5月8日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216000, '《中华人民共和国公益事业捐赠法》', '第一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第一章 总 则', NULL, '为了鼓励捐赠，规范捐赠和受赠行为，保护捐赠人、受赠人和受益人的合法权益，促进公益事业的发展，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216001, '《中华人民共和国公益事业捐赠法》', '第二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第一章 总 则', NULL, '自然人、法人或者其他组织自愿无偿向依法成立的公益性社会团体和公益性非营利的事业单位捐赠财产，用于公益事业的，适用本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216002, '《中华人民共和国公益事业捐赠法》', '第三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第一章 总 则', NULL, '本法所称公益事业是指非营利的下列事项： （一）救助灾害、救济贫困、扶助残疾人等困难的社会群体和个人的活动； （二）教育、科学、文化、卫生、体育事业； （三）环境保护、社会公共设施建设； （四）促进社会发展和进步的其他社会公共和福利事业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216003, '《中华人民共和国公益事业捐赠法》', '第四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第一章 总 则', NULL, '捐赠应当是自愿和无偿的，禁止强行摊派或者变相摊派，不得以捐赠为名从事营利活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216004, '《中华人民共和国公益事业捐赠法》', '第五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第一章 总 则', NULL, '捐赠财产的使用应当尊重捐赠人的意愿，符合公益目的，不得将捐赠财产挪作他用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216005, '《中华人民共和国公益事业捐赠法》', '第六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第一章 总 则', NULL, '捐赠应当遵守法律、法规，不得违背社会公德，不得损害公共利益和其他公民的合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216006, '《中华人民共和国公益事业捐赠法》', '第七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第一章 总 则', NULL, '公益性社会团体受赠的财产及其增值为社会公共财产，受国家法律保护，任何单位和个人不得侵占、挪用和损毁。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216007, '《中华人民共和国公益事业捐赠法》', '第八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第一章 总 则', NULL, '国家鼓励公益事业的发展，对公益性社会团体和公益性非营利的事业单位给予扶持和优待。 国家鼓励自然人、法人或者其他组织对公益事业进行捐赠。 对公益事业捐赠有突出贡献的自然人、法人或者其他组织，由人民政府或者有关部门予以表彰。对捐赠人进行公开表彰，应当事先征求捐赠人的意见。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216008, '《中华人民共和国公益事业捐赠法》', '第九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第二章 捐赠和受赠', NULL, '自然人、法人或者其他组织可以选择符合其捐赠意愿的公益性社会团体和公益性非营利的事业单位进行捐赠。捐赠的财产应当是其有权处分的合法财产。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216009, '《中华人民共和国公益事业捐赠法》', '第十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第二章 捐赠和受赠', NULL, '公益性社会团体和公益性非营利的事业单位可以依照本法接受捐赠。 本法所称公益性社会团体是指依法成立的，以发展公益事业为宗旨的基金会、慈善组织等社会团体。 本法所称公益性非营利的事业单位是指依法成立的，从事公益事业的不以营利为目的的教育机构、科学研究机构、医疗卫生机构、社会公共文化机构、社会公共体育机构和社会福利机构等。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216010, '《中华人民共和国公益事业捐赠法》', '第十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第二章 捐赠和受赠', NULL, '在发生自然灾害时或者境外捐赠人要求县级以上人民政府及其部门作为受赠人时，县级以上人民政府及其部门可以接受捐赠，并依照本法的有关规定对捐赠财产进行管理。 县级以上人民政府及其部门可以将受赠财产转交公益性社会团体或者公益性非营利的事业单位；也可以按照捐赠人的意愿分发或者兴办公益事业，但是不得以本机关为受益对象。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216011, '《中华人民共和国公益事业捐赠法》', '第十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第二章 捐赠和受赠', NULL, '捐赠人可以与受赠人就捐赠财产的种类、质量、数量和用途等内容订立捐赠协议。捐赠人有权决定捐赠的数量、用途和方式。 捐赠人应当依法履行捐赠协议，按照捐赠协议约定的期限和方式将捐赠财产转移给受赠人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216012, '《中华人民共和国公益事业捐赠法》', '第十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第二章 捐赠和受赠', NULL, '捐赠人捐赠财产兴建公益事业工程项目，应当与受赠人订立捐赠协议，对工程项目的资金、建设、管理和使用作出约定。 捐赠的公益事业工程项目由受赠单位按照国家有关规定办理项目审批手续，并组织施工或者由受赠人和捐赠人共同组织施工。工程质量应当符合国家质量标准。 捐赠的公益事业工程项目竣工后，受赠单位应当将工程建设、建设资金的使用和工程质量验收情况向捐赠人通报。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216013, '《中华人民共和国公益事业捐赠法》', '第十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第二章 捐赠和受赠', NULL, '捐赠人对于捐赠的公益事业工程项目可以留名纪念；捐赠人单独捐赠的工程项目或者主要由捐赠人出资兴建的工程项目，可以由捐赠人提出工程项目的名称，报县级以上人民政府批准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216014, '《中华人民共和国公益事业捐赠法》', '第十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第二章 捐赠和受赠', NULL, '境外捐赠人捐赠的财产，由受赠人按照国家有关规定办理入境手续；捐赠实行许可证管理的物品，由受赠人按照国家有关规定办理许可证申领手续，海关凭许可证验放、监管。 华侨向境内捐赠的，县级以上人民政府侨务部门可以协助办理有关入境手续，为捐赠人实施捐赠项目提供帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216015, '《中华人民共和国公益事业捐赠法》', '第十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第三章 捐赠财产的使用和管理', NULL, '受赠人接受捐赠后，应当向捐赠人出具合法、有效的收据，将受赠财产登记造册，妥善保管。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216016, '《中华人民共和国公益事业捐赠法》', '第十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第三章 捐赠财产的使用和管理', NULL, '公益性社会团体应当将受赠财产用于资助符合其宗旨的活动和事业。对于接受的救助灾害的捐赠财产，应当及时用于救助活动。基金会每年用于资助公益事业的资金数额，不得低于国家规定的比例。 公益性社会团体应当严格遵守国家的有关规定，按照合法、安全、有效的原则，积极实现捐赠财产的保值增值。 公益性非营利的事业单位应当将受赠财产用于发展本单位的公益事业，不得挪作他用。 对于不易储存、运输和超过实际需要的受赠财产，受赠人可以变卖，所取得的全部收入，应当用于捐赠目的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216017, '《中华人民共和国公益事业捐赠法》', '第十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第三章 捐赠财产的使用和管理', NULL, '受赠人与捐赠人订立了捐赠协议的，应当按照协议约定的用途使用捐赠财产，不得擅自改变捐赠财产的用途。如果确需改变用途的，应当征得捐赠人的同意。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216018, '《中华人民共和国公益事业捐赠法》', '第十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第三章 捐赠财产的使用和管理', NULL, '受赠人应当依照国家有关规定，建立健全财务会计制度和受赠财产的使用制度，加强对受赠财产的管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216019, '《中华人民共和国公益事业捐赠法》', '第二十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第三章 捐赠财产的使用和管理', NULL, '受赠人每年度应当向政府有关部门报告受赠财产的使用、管理情况，接受监督。必要时，政府有关部门可以对其财务进行审计。 海关对减免关税的捐赠物品依法实施监督和管理。 县级以上人民政府侨务部门可以参与对华侨向境内捐赠财产使用与管理的监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216020, '《中华人民共和国公益事业捐赠法》', '第二十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第三章 捐赠财产的使用和管理', NULL, '捐赠人有权向受赠人查询捐赠财产的使用、管理情况，并提出意见和建议。对于捐赠人的查询，受赠人应当如实答复。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216021, '《中华人民共和国公益事业捐赠法》', '第二十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第三章 捐赠财产的使用和管理', NULL, '受赠人应当公开接受捐赠的情况和受赠财产的使用、管理情况，接受社会监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216022, '《中华人民共和国公益事业捐赠法》', '第二十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第三章 捐赠财产的使用和管理', NULL, '公益性社会团体应当厉行节约，降低管理成本，工作人员的工资和办公费用从利息等收入中按照国家规定的标准开支。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216023, '《中华人民共和国公益事业捐赠法》', '第二十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第四章 优惠措施', NULL, '公司和其他企业依照本法的规定捐赠财产用于公益事业，依照法律、行政法规的规定享受企业所得税方面的优惠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216024, '《中华人民共和国公益事业捐赠法》', '第二十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第四章 优惠措施', NULL, '自然人和个体工商户依照本法的规定捐赠财产用于公益事业，依照法律、行政法规的规定享受个人所得税方面的优惠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216025, '《中华人民共和国公益事业捐赠法》', '第二十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第四章 优惠措施', NULL, '境外向公益性社会团体和公益性非营利的事业单位捐赠的用于公益事业的物资，依照法律、行政法规的规定减征或者免征进口关税和进口环节的增值税。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216026, '《中华人民共和国公益事业捐赠法》', '第二十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第四章 优惠措施', NULL, '对于捐赠的工程项目，当地人民政府应当给予支持和优惠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216027, '《中华人民共和国公益事业捐赠法》', '第二十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第五章 法律责任', NULL, '受赠人未征得捐赠人的许可，擅自改变捐赠财产的性质、用途的，由县级以上人民政府有关部门责令改正，给予警告。拒不改正的，经征求捐赠人的意见，由县级以上人民政府将捐赠财产交由与其宗旨相同或者相似的公益性社会团体或者公益性非营利的事业单位管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216028, '《中华人民共和国公益事业捐赠法》', '第二十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第五章 法律责任', NULL, '挪用、侵占或者贪污捐赠款物的，由县级以上人民政府有关部门责令退还所用、所得款物，并处以罚款；对直接责任人员，由所在单位依照有关规定予以处理；构成犯罪的，依法追究刑事责任。 依照前款追回、追缴的捐赠款物，应当用于原捐赠目的和用途。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216029, '《中华人民共和国公益事业捐赠法》', '第三十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第五章 法律责任', NULL, '在捐赠活动中，有下列行为之一的，依照法律、法规的有关规定予以处罚；构成犯罪的，依法追究刑事责任： （一）逃汇、骗购外汇的； （二）偷税、逃税的； （三）进行走私活动的； （四）未经海关许可并且未补缴应缴税额，擅自将减税、免税进口的捐赠物资在境内销售、转让或者移作他用的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216030, '《中华人民共和国公益事业捐赠法》', '第三十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第五章 法律责任', NULL, '受赠单位的工作人员，滥用职权，玩忽职守，徇私舞弊，致使捐赠财产造成重大损失的，由所在单位依照有关规定予以处理；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (216031, '《中华人民共和国公益事业捐赠法》', '第三十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 1999-06-28', '第六章 附 则', NULL, '本法自1999年9月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217000, '《中华人民共和国法律援助法》', '第一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第一章 总 则', NULL, '为了规范和促进法律援助工作，保障公民和有关当事人的合法权益，保障法律正确实施，维护社会公平正义，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217001, '《中华人民共和国法律援助法》', '第二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第一章 总 则', NULL, '本法所称法律援助，是国家建立的为经济困难公民和符合法定条件的其他当事人无偿提供法律咨询、代理、刑事辩护等法律服务的制度，是公共法律服务体系的组成部分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217002, '《中华人民共和国法律援助法》', '第三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第一章 总 则', NULL, '法律援助工作坚持中国共产党领导，坚持以人民为中心，尊重和保障人权，遵循公开、公平、公正的原则，实行国家保障与社会参与相结合。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217003, '《中华人民共和国法律援助法》', '第四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第一章 总 则', NULL, '县级以上人民政府应当将法律援助工作纳入国民经济和社会发展规划、基本公共服务体系，保障法律援助事业与经济社会协调发展。 县级以上人民政府应当健全法律援助保障体系，将法律援助相关经费列入本级政府预算，建立动态调整机制，保障法律援助工作需要，促进法律援助均衡发展。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217004, '《中华人民共和国法律援助法》', '第五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第一章 总 则', NULL, '国务院司法行政部门指导、监督全国的法律援助工作。县级以上地方人民政府司法行政部门指导、监督本行政区域的法律援助工作。 县级以上人民政府其他有关部门依照各自职责，为法律援助工作提供支持和保障。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217005, '《中华人民共和国法律援助法》', '第六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第一章 总 则', NULL, '人民法院、人民检察院、公安机关应当在各自职责范围内保障当事人依法获得法律援助，为法律援助人员开展工作提供便利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217006, '《中华人民共和国法律援助法》', '第七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第一章 总 则', NULL, '律师协会应当指导和支持律师事务所、律师参与法律援助工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217007, '《中华人民共和国法律援助法》', '第八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第一章 总 则', NULL, '国家鼓励和支持群团组织、事业单位、社会组织在司法行政部门指导下，依法提供法律援助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217008, '《中华人民共和国法律援助法》', '第九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第一章 总 则', NULL, '国家鼓励和支持企业事业单位、社会组织和个人等社会力量，依法通过捐赠等方式为法律援助事业提供支持；对符合条件的，给予税收优惠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217009, '《中华人民共和国法律援助法》', '第十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第一章 总 则', NULL, '司法行政部门应当开展经常性的法律援助宣传教育，普及法律援助知识。 新闻媒体应当积极开展法律援助公益宣传，并加强舆论监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217010, '《中华人民共和国法律援助法》', '第十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第一章 总 则', NULL, '国家对在法律援助工作中做出突出贡献的组织和个人，按照有关规定给予表彰、奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217011, '《中华人民共和国法律援助法》', '第十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第二章 机构和人员', NULL, '县级以上人民政府司法行政部门应当设立法律援助机构。法律援助机构负责组织实施法律援助工作，受理、审查法律援助申请，指派律师、基层法律服务工作者、法律援助志愿者等法律援助人员提供法律援助，支付法律援助补贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217012, '《中华人民共和国法律援助法》', '第十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第二章 机构和人员', NULL, '法律援助机构根据工作需要，可以安排本机构具有律师资格或者法律职业资格的工作人员提供法律援助；可以设置法律援助工作站或者联络点，就近受理法律援助申请。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217013, '《中华人民共和国法律援助法》', '第十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第二章 机构和人员', NULL, '法律援助机构可以在人民法院、人民检察院和看守所等场所派驻值班律师，依法为没有辩护人的犯罪嫌疑人、被告人提供法律援助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217014, '《中华人民共和国法律援助法》', '第十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第二章 机构和人员', NULL, '司法行政部门可以通过政府采购等方式，择优选择律师事务所等法律服务机构为受援人提供法律援助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217015, '《中华人民共和国法律援助法》', '第十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第二章 机构和人员', NULL, '律师事务所、基层法律服务所、律师、基层法律服务工作者负有依法提供法律援助的义务。 律师事务所、基层法律服务所应当支持和保障本所律师、基层法律服务工作者履行法律援助义务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217016, '《中华人民共和国法律援助法》', '第十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第二章 机构和人员', NULL, '国家鼓励和规范法律援助志愿服务；支持符合条件的个人作为法律援助志愿者，依法提供法律援助。 高等院校、科研机构可以组织从事法学教育、研究工作的人员和法学专业学生作为法律援助志愿者，在司法行政部门指导下，为当事人提供法律咨询、代拟法律文书等法律援助。 法律援助志愿者具体管理办法由国务院有关部门规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217017, '《中华人民共和国法律援助法》', '第十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第二章 机构和人员', NULL, '国家建立健全法律服务资源依法跨区域流动机制，鼓励和支持律师事务所、律师、法律援助志愿者等在法律服务资源相对短缺地区提供法律援助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217018, '《中华人民共和国法律援助法》', '第十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第二章 机构和人员', NULL, '法律援助人员应当依法履行职责，及时为受援人提供符合标准的法律援助服务，维护受援人的合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217019, '《中华人民共和国法律援助法》', '第二十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第二章 机构和人员', NULL, '法律援助人员应当恪守职业道德和执业纪律，不得向受援人收取任何财物。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217020, '《中华人民共和国法律援助法》', '第二十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第二章 机构和人员', NULL, '法律援助机构、法律援助人员对提供法律援助过程中知悉的国家秘密、商业秘密和个人隐私应当予以保密。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217021, '《中华人民共和国法律援助法》', '第二十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第三章 形式和范围', NULL, '法律援助机构可以组织法律援助人员依法提供下列形式的法律援助服务： （一）法律咨询； （二）代拟法律文书； （三）刑事辩护与代理； （四）民事案件、行政案件、国家赔偿案件的诉讼代理及非诉讼代理； （五）值班律师法律帮助； （六）劳动争议调解与仲裁代理； （七）法律、法规、规章规定的其他形式。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217022, '《中华人民共和国法律援助法》', '第二十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第三章 形式和范围', NULL, '法律援助机构应当通过服务窗口、电话、网络等多种方式提供法律咨询服务；提示当事人享有依法申请法律援助的权利，并告知申请法律援助的条件和程序。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217023, '《中华人民共和国法律援助法》', '第二十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第三章 形式和范围', NULL, '刑事案件的犯罪嫌疑人、被告人因经济困难或者其他原因没有委托辩护人的，本人及其近亲属可以向法律援助机构申请法律援助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217024, '《中华人民共和国法律援助法》', '第二十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第三章 形式和范围', NULL, '刑事案件的犯罪嫌疑人、被告人属于下列人员之一，没有委托辩护人的，人民法院、人民检察院、公安机关应当通知法律援助机构指派律师担任辩护人： （一）未成年人； （二）视力、听力、言语残疾人； （三）不能完全辨认自己行为的成年人； （四）可能被判处无期徒刑、死刑的人； （五）申请法律援助的死刑复核案件被告人； （六）缺席审判案件的被告人； （七）法律法规规定的其他人员。 其他适用普通程序审理的刑事案件，被告人没有委托辩护人的，人民法院可以通知法律援助机构指派律师担任辩护人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217025, '《中华人民共和国法律援助法》', '第二十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第三章 形式和范围', NULL, '对可能被判处无期徒刑、死刑的人，以及死刑复核案件的被告人，法律援助机构收到人民法院、人民检察院、公安机关通知后，应当指派具有三年以上相关执业经历的律师担任辩护人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217026, '《中华人民共和国法律援助法》', '第二十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第三章 形式和范围', NULL, '人民法院、人民检察院、公安机关通知法律援助机构指派律师担任辩护人时，不得限制或者损害犯罪嫌疑人、被告人委托辩护人的权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217027, '《中华人民共和国法律援助法》', '第二十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第三章 形式和范围', NULL, '强制医疗案件的被申请人或者被告人没有委托诉讼代理人的，人民法院应当通知法律援助机构指派律师为其提供法律援助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217028, '《中华人民共和国法律援助法》', '第二十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第三章 形式和范围', NULL, '刑事公诉案件的被害人及其法定代理人或者近亲属，刑事自诉案件的自诉人及其法定代理人，刑事附带民事诉讼案件的原告人及其法定代理人，因经济困难没有委托诉讼代理人的，可以向法律援助机构申请法律援助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217029, '《中华人民共和国法律援助法》', '第三十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第三章 形式和范围', NULL, '值班律师应当依法为没有辩护人的犯罪嫌疑人、被告人提供法律咨询、程序选择建议、申请变更强制措施、对案件处理提出意见等法律帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217030, '《中华人民共和国法律援助法》', '第三十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第三章 形式和范围', NULL, '下列事项的当事人，因经济困难没有委托代理人的，可以向法律援助机构申请法律援助： （一）依法请求国家赔偿； （二）请求给予社会保险待遇或者社会救助； （三）请求发给抚恤金； （四）请求给付赡养费、抚养费、扶养费； （五）请求确认劳动关系或者支付劳动报酬； （六）请求认定公民无民事行为能力或者限制民事行为能力； （七）请求工伤事故、交通事故、食品药品安全事故、医疗事故人身损害赔偿； （八）请求环境污染、生态破坏损害赔偿； （九）法律、法规、规章规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217031, '《中华人民共和国法律援助法》', '第三十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第三章 形式和范围', NULL, '有下列情形之一，当事人申请法律援助的，不受经济困难条件的限制： （一）英雄烈士近亲属为维护英雄烈士的人格权益； （二）因见义勇为行为主张相关民事权益； （三）再审改判无罪请求国家赔偿； （四）遭受虐待、遗弃或者家庭暴力的受害人主张相关权益； （五）法律、法规、规章规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217032, '《中华人民共和国法律援助法》', '第三十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第三章 形式和范围', NULL, '当事人不服司法机关生效裁判或者决定提出申诉或者申请再审，人民法院决定、裁定再审或者人民检察院提出抗诉，因经济困难没有委托辩护人或者诉讼代理人的，本人及其近亲属可以向法律援助机构申请法律援助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217033, '《中华人民共和国法律援助法》', '第三十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第三章 形式和范围', NULL, '经济困难的标准，由省、自治区、直辖市人民政府根据本行政区域经济发展状况和法律援助工作需要确定，并实行动态调整。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217034, '《中华人民共和国法律援助法》', '第三十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第四章 程序和实施', NULL, '人民法院、人民检察院、公安机关和有关部门在办理案件或者相关事务中，应当及时告知有关当事人有权依法申请法律援助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217035, '《中华人民共和国法律援助法》', '第三十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第四章 程序和实施', NULL, '人民法院、人民检察院、公安机关办理刑事案件，发现有本法第二十五条第一款、第二十八条规定情形的，应当在三日内通知法律援助机构指派律师。法律援助机构收到通知后，应当在三日内指派律师并通知人民法院、人民检察院、公安机关。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217036, '《中华人民共和国法律援助法》', '第三十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第四章 程序和实施', NULL, '人民法院、人民检察院、公安机关应当保障值班律师依法提供法律帮助，告知没有辩护人的犯罪嫌疑人、被告人有权约见值班律师，并依法为值班律师了解案件有关情况、阅卷、会见等提供便利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217037, '《中华人民共和国法律援助法》', '第三十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第四章 程序和实施', NULL, '对诉讼事项的法律援助，由申请人向办案机关所在地的法律援助机构提出申请；对非诉讼事项的法律援助，由申请人向争议处理机关所在地或者事由发生地的法律援助机构提出申请。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217038, '《中华人民共和国法律援助法》', '第三十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第四章 程序和实施', NULL, '被羁押的犯罪嫌疑人、被告人、服刑人员，以及强制隔离戒毒人员等提出法律援助申请的，办案机关、监管场所应当在二十四小时内将申请转交法律援助机构。 犯罪嫌疑人、被告人通过值班律师提出代理、刑事辩护等法律援助申请的，值班律师应当在二十四小时内将申请转交法律援助机构。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217039, '《中华人民共和国法律援助法》', '第四十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第四章 程序和实施', NULL, '无民事行为能力人或者限制民事行为能力人需要法律援助的，可以由其法定代理人代为提出申请。法定代理人侵犯无民事行为能力人、限制民事行为能力人合法权益的，其他法定代理人或者近亲属可以代为提出法律援助申请。 被羁押的犯罪嫌疑人、被告人、服刑人员，以及强制隔离戒毒人员，可以由其法定代理人或者近亲属代为提出法律援助申请。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217040, '《中华人民共和国法律援助法》', '第四十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第四章 程序和实施', NULL, '因经济困难申请法律援助的，申请人应当如实说明经济困难状况。 法律援助机构核查申请人的经济困难状况，可以通过信息共享查询，或者由申请人进行个人诚信承诺。 法律援助机构开展核查工作，有关部门、单位、村民委员会、居民委员会和个人应当予以配合。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217041, '《中华人民共和国法律援助法》', '第四十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第四章 程序和实施', NULL, '法律援助申请人有材料证明属于下列人员之一的，免予核查经济困难状况： （一）无固定生活来源的未成年人、老年人、残疾人等特定群体； （二）社会救助、司法救助或者优抚对象； （三）申请支付劳动报酬或者请求工伤事故人身损害赔偿的进城务工人员； （四）法律、法规、规章规定的其他人员。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217042, '《中华人民共和国法律援助法》', '第四十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第四章 程序和实施', NULL, '法律援助机构应当自收到法律援助申请之日起七日内进行审查，作出是否给予法律援助的决定。决定给予法律援助的，应当自作出决定之日起三日内指派法律援助人员为受援人提供法律援助；决定不给予法律援助的，应当书面告知申请人，并说明理由。 申请人提交的申请材料不齐全的，法律援助机构应当一次性告知申请人需要补充的材料或者要求申请人作出说明。申请人未按要求补充材料或者作出说明的，视为撤回申请。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217043, '《中华人民共和国法律援助法》', '第四十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第四章 程序和实施', NULL, '法律援助机构收到法律援助申请后，发现有下列情形之一的，可以决定先行提供法律援助： （一）距法定时效或者期限届满不足七日，需要及时提起诉讼或者申请仲裁、行政复议； （二）需要立即申请财产保全、证据保全或者先予执行； （三）法律、法规、规章规定的其他情形。 法律援助机构先行提供法律援助的，受援人应当及时补办有关手续，补充有关材料。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217044, '《中华人民共和国法律援助法》', '第四十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第四章 程序和实施', NULL, '法律援助机构为老年人、残疾人提供法律援助服务的，应当根据实际情况提供无障碍设施设备和服务。 法律法规对向特定群体提供法律援助有其他特别规定的，依照其规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217045, '《中华人民共和国法律援助法》', '第四十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第四章 程序和实施', NULL, '法律援助人员接受指派后，无正当理由不得拒绝、拖延或者终止提供法律援助服务。 法律援助人员应当按照规定向受援人通报法律援助事项办理情况，不得损害受援人合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217046, '《中华人民共和国法律援助法》', '第四十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第四章 程序和实施', NULL, '受援人应当向法律援助人员如实陈述与法律援助事项有关的情况，及时提供证据材料，协助、配合办理法律援助事项。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217047, '《中华人民共和国法律援助法》', '第四十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第四章 程序和实施', NULL, '有下列情形之一的，法律援助机构应当作出终止法律援助的决定： （一）受援人以欺骗或者其他不正当手段获得法律援助； （二）受援人故意隐瞒与案件有关的重要事实或者提供虚假证据； （三）受援人利用法律援助从事违法活动； （四）受援人的经济状况发生变化，不再符合法律援助条件； （五）案件终止审理或者已经被撤销； （六）受援人自行委托律师或者其他代理人； （七）受援人有正当理由要求终止法律援助； （八）法律法规规定的其他情形。 法律援助人员发现有前款规定情形的，应当及时向法律援助机构报告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217048, '《中华人民共和国法律援助法》', '第四十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第四章 程序和实施', NULL, '申请人、受援人对法律援助机构不予法律援助、终止法律援助的决定有异议的，可以向设立该法律援助机构的司法行政部门提出。 司法行政部门应当自收到异议之日起五日内进行审查，作出维持法律援助机构决定或者责令法律援助机构改正的决定。 申请人、受援人对司法行政部门维持法律援助机构决定不服的，可以依法申请行政复议或者提起行政诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217049, '《中华人民共和国法律援助法》', '第五十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第四章 程序和实施', NULL, '法律援助事项办理结束后，法律援助人员应当及时向法律援助机构报告，提交有关法律文书的副本或者复印件、办理情况报告等材料。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217050, '《中华人民共和国法律援助法》', '第五十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第五章 保障和监督', NULL, '国家加强法律援助信息化建设，促进司法行政部门与司法机关及其他有关部门实现信息共享和工作协同。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217051, '《中华人民共和国法律援助法》', '第五十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第五章 保障和监督', NULL, '法律援助机构应当依照有关规定及时向法律援助人员支付法律援助补贴。 法律援助补贴的标准，由省、自治区、直辖市人民政府司法行政部门会同同级财政部门，根据当地经济发展水平和法律援助的服务类型、承办成本、基本劳务费用等确定，并实行动态调整。 法律援助补贴免征增值税和个人所得税。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217052, '《中华人民共和国法律援助法》', '第五十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第五章 保障和监督', NULL, '人民法院应当根据情况对受援人缓收、减收或者免收诉讼费用；对法律援助人员复制相关材料等费用予以免收或者减收。 公证机构、司法鉴定机构应当对受援人减收或者免收公证费、鉴定费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217053, '《中华人民共和国法律援助法》', '第五十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第五章 保障和监督', NULL, '县级以上人民政府司法行政部门应当有计划地对法律援助人员进行培训，提高法律援助人员的专业素质和服务能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217054, '《中华人民共和国法律援助法》', '第五十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第五章 保障和监督', NULL, '受援人有权向法律援助机构、法律援助人员了解法律援助事项办理情况；法律援助机构、法律援助人员未依法履行职责的，受援人可以向司法行政部门投诉，并可以请求法律援助机构更换法律援助人员。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217055, '《中华人民共和国法律援助法》', '第五十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第五章 保障和监督', NULL, '司法行政部门应当建立法律援助工作投诉查处制度；接到投诉后，应当依照有关规定受理和调查处理，并及时向投诉人告知处理结果。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217056, '《中华人民共和国法律援助法》', '第五十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第五章 保障和监督', NULL, '司法行政部门应当加强对法律援助服务的监督，制定法律援助服务质量标准，通过第三方评估等方式定期进行质量考核。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217057, '《中华人民共和国法律援助法》', '第五十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第五章 保障和监督', NULL, '司法行政部门、法律援助机构应当建立法律援助信息公开制度，定期向社会公布法律援助资金使用、案件办理、质量考核结果等情况，接受社会监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217058, '《中华人民共和国法律援助法》', '第五十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第五章 保障和监督', NULL, '法律援助机构应当综合运用庭审旁听、案卷检查、征询司法机关意见和回访受援人等措施，督促法律援助人员提升服务质量。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217059, '《中华人民共和国法律援助法》', '第六十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第五章 保障和监督', NULL, '律师协会应当将律师事务所、律师履行法律援助义务的情况纳入年度考核内容，对拒不履行或者怠于履行法律援助义务的律师事务所、律师，依照有关规定进行惩戒。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217060, '《中华人民共和国法律援助法》', '第六十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第六章 法律责任', NULL, '法律援助机构及其工作人员有下列情形之一的，由设立该法律援助机构的司法行政部门责令限期改正；有违法所得的，责令退还或者没收违法所得；对直接负责的主管人员和其他直接责任人员，依法给予处分： （一）拒绝为符合法律援助条件的人员提供法律援助，或者故意为不符合法律援助条件的人员提供法律援助； （二）指派不符合本法规定的人员提供法律援助； （三）收取受援人财物； （四）从事有偿法律服务； （五）侵占、私分、挪用法律援助经费； （六）泄露法律援助过程中知悉的国家秘密、商业秘密和个人隐私； （七）法律法规规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217061, '《中华人民共和国法律援助法》', '第六十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第六章 法律责任', NULL, '律师事务所、基层法律服务所有下列情形之一的，由司法行政部门依法给予处罚： （一）无正当理由拒绝接受法律援助机构指派； （二）接受指派后，不及时安排本所律师、基层法律服务工作者办理法律援助事项或者拒绝为本所律师、基层法律服务工作者办理法律援助事项提供支持和保障； （三）纵容或者放任本所律师、基层法律服务工作者怠于履行法律援助义务或者擅自终止提供法律援助； （四）法律法规规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217062, '《中华人民共和国法律援助法》', '第六十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第六章 法律责任', NULL, '律师、基层法律服务工作者有下列情形之一的，由司法行政部门依法给予处罚： （一）无正当理由拒绝履行法律援助义务或者怠于履行法律援助义务； （二）擅自终止提供法律援助； （三）收取受援人财物； （四）泄露法律援助过程中知悉的国家秘密、商业秘密和个人隐私； （五）法律法规规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217063, '《中华人民共和国法律援助法》', '第六十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第六章 法律责任', NULL, '受援人以欺骗或者其他不正当手段获得法律援助的，由司法行政部门责令其支付已实施法律援助的费用，并处三千元以下罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217064, '《中华人民共和国法律援助法》', '第六十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第六章 法律责任', NULL, '违反本法规定，冒用法律援助名义提供法律服务并谋取利益的，由司法行政部门责令改正，没收违法所得，并处违法所得一倍以上三倍以下罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217065, '《中华人民共和国法律援助法》', '第六十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第六章 法律责任', NULL, '国家机关及其工作人员在法律援助工作中滥用职权、玩忽职守、徇私舞弊的，对直接负责的主管人员和其他直接责任人员，依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217066, '《中华人民共和国法律援助法》', '第六十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第六章 法律责任', NULL, '违反本法规定，构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217067, '《中华人民共和国法律援助法》', '第六十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第七章 附 则', NULL, '工会、共产主义青年团、妇女联合会、残疾人联合会等群团组织开展法律援助工作，参照适用本法的相关规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217068, '《中华人民共和国法律援助法》', '第六十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第七章 附 则', NULL, '对外国人和无国籍人提供法律援助，我国法律有规定的，适用法律规定；我国法律没有规定的，可以根据我国缔结或者参加的国际条约，或者按照互惠原则，参照适用本法的相关规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217069, '《中华人民共和国法律援助法》', '第七十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第七章 附 则', NULL, '对军人军属提供法律援助的具体办法，由国务院和中央军事委员会有关部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (217070, '《中华人民共和国法律援助法》', '第七十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-08-20', '第七章 附 则', NULL, '本法自2022年1月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218000, '《中华人民共和国反家庭暴力法》', '第一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第一章 总 则', NULL, '为了预防和制止家庭暴力，保护家庭成员的合法权益，维护平等、和睦、文明的家庭关系，促进家庭和谐、社会稳定，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218001, '《中华人民共和国反家庭暴力法》', '第二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第一章 总 则', NULL, '本法所称家庭暴力，是指家庭成员之间以殴打、捆绑、残害、限制人身自由以及经常性谩骂、恐吓等方式实施的身体、精神等侵害行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218002, '《中华人民共和国反家庭暴力法》', '第三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第一章 总 则', NULL, '家庭成员之间应当互相帮助，互相关爱，和睦相处，履行家庭义务。 反家庭暴力是国家、社会和每个家庭的共同责任。 国家禁止任何形式的家庭暴力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218003, '《中华人民共和国反家庭暴力法》', '第四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第一章 总 则', NULL, '县级以上人民政府负责妇女儿童工作的机构，负责组织、协调、指导、督促有关部门做好反家庭暴力工作。 县级以上人民政府有关部门、司法机关、人民团体、社会组织、居民委员会、村民委员会、企业事业单位，应当依照本法和有关法律规定，做好反家庭暴力工作。 各级人民政府应当对反家庭暴力工作给予必要的经费保障。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218004, '《中华人民共和国反家庭暴力法》', '第五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第一章 总 则', NULL, '反家庭暴力工作遵循预防为主，教育、矫治与惩处相结合原则。 反家庭暴力工作应当尊重受害人真实意愿，保护当事人隐私。 未成年人、老年人、残疾人、孕期和哺乳期的妇女、重病患者遭受家庭暴力的，应当给予特殊保护。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218005, '《中华人民共和国反家庭暴力法》', '第六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第二章 家庭暴力的预防', NULL, '国家开展家庭美德宣传教育，普及反家庭暴力知识，增强公民反家庭暴力意识。 工会、共产主义青年团、妇女联合会、残疾人联合会应当在各自工作范围内，组织开展家庭美德和反家庭暴力宣传教育。 广播、电视、报刊、网络等应当开展家庭美德和反家庭暴力宣传。 学校、幼儿园应当开展家庭美德和反家庭暴力教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218006, '《中华人民共和国反家庭暴力法》', '第七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第二章 家庭暴力的预防', NULL, '县级以上人民政府有关部门、司法机关、妇女联合会应当将预防和制止家庭暴力纳入业务培训和统计工作。 医疗机构应当做好家庭暴力受害人的诊疗记录。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218007, '《中华人民共和国反家庭暴力法》', '第八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第二章 家庭暴力的预防', NULL, '乡镇人民政府、街道办事处应当组织开展家庭暴力预防工作，居民委员会、村民委员会、社会工作服务机构应当予以配合协助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218008, '《中华人民共和国反家庭暴力法》', '第九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第二章 家庭暴力的预防', NULL, '各级人民政府应当支持社会工作服务机构等社会组织开展心理健康咨询、家庭关系指导、家庭暴力预防知识教育等服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218009, '《中华人民共和国反家庭暴力法》', '第十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第二章 家庭暴力的预防', NULL, '人民调解组织应当依法调解家庭纠纷，预防和减少家庭暴力的发生。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218010, '《中华人民共和国反家庭暴力法》', '第十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第二章 家庭暴力的预防', NULL, '用人单位发现本单位人员有家庭暴力情况的，应当给予批评教育，并做好家庭矛盾的调解、化解工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218011, '《中华人民共和国反家庭暴力法》', '第十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第二章 家庭暴力的预防', NULL, '未成年人的监护人应当以文明的方式进行家庭教育，依法履行监护和教育职责，不得实施家庭暴力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218012, '《中华人民共和国反家庭暴力法》', '第十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第三章 家庭暴力的处置', NULL, '家庭暴力受害人及其法定代理人、近亲属可以向加害人或者受害人所在单位、居民委员会、村民委员会、妇女联合会等单位投诉、反映或者求助。有关单位接到家庭暴力投诉、反映或者求助后，应当给予帮助、处理。 家庭暴力受害人及其法定代理人、近亲属也可以向公安机关报案或者依法向人民法院起诉。 单位、个人发现正在发生的家庭暴力行为，有权及时劝阻。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218013, '《中华人民共和国反家庭暴力法》', '第十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第三章 家庭暴力的处置', NULL, '学校、幼儿园、医疗机构、居民委员会、村民委员会、社会工作服务机构、救助管理机构、福利机构及其工作人员在工作中发现无民事行为能力人、限制民事行为能力人遭受或者疑似遭受家庭暴力的，应当及时向公安机关报案。公安机关应当对报案人的信息予以保密。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218014, '《中华人民共和国反家庭暴力法》', '第十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第三章 家庭暴力的处置', NULL, '公安机关接到家庭暴力报案后应当及时出警，制止家庭暴力，按照有关规定调查取证，协助受害人就医、鉴定伤情。 无民事行为能力人、限制民事行为能力人因家庭暴力身体受到严重伤害、面临人身安全威胁或者处于无人照料等危险状态的，公安机关应当通知并协助民政部门将其安置到临时庇护场所、救助管理机构或者福利机构。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218015, '《中华人民共和国反家庭暴力法》', '第十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第三章 家庭暴力的处置', NULL, '家庭暴力情节较轻，依法不给予治安管理处罚的，由公安机关对加害人给予批评教育或者出具告诫书。 告诫书应当包括加害人的身份信息、家庭暴力的事实陈述、禁止加害人实施家庭暴力等内容。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218016, '《中华人民共和国反家庭暴力法》', '第十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第三章 家庭暴力的处置', NULL, '公安机关应当将告诫书送交加害人、受害人，并通知居民委员会、村民委员会。 居民委员会、村民委员会、公安派出所应当对收到告诫书的加害人、受害人进行查访，监督加害人不再实施家庭暴力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218017, '《中华人民共和国反家庭暴力法》', '第十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第三章 家庭暴力的处置', NULL, '县级或者设区的市级人民政府可以单独或者依托救助管理机构设立临时庇护场所，为家庭暴力受害人提供临时生活帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218018, '《中华人民共和国反家庭暴力法》', '第十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第三章 家庭暴力的处置', NULL, '法律援助机构应当依法为家庭暴力受害人提供法律援助。 人民法院应当依法对家庭暴力受害人缓收、减收或者免收诉讼费用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218019, '《中华人民共和国反家庭暴力法》', '第二十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第三章 家庭暴力的处置', NULL, '人民法院审理涉及家庭暴力的案件，可以根据公安机关出警记录、告诫书、伤情鉴定意见等证据，认定家庭暴力事实。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218020, '《中华人民共和国反家庭暴力法》', '第二十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第三章 家庭暴力的处置', NULL, '监护人实施家庭暴力严重侵害被监护人合法权益的，人民法院可以根据被监护人的近亲属、居民委员会、村民委员会、县级人民政府民政部门等有关人员或者单位的申请，依法撤销其监护人资格，另行指定监护人。 被撤销监护人资格的加害人，应当继续负担相应的赡养、扶养、抚养费用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218021, '《中华人民共和国反家庭暴力法》', '第二十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第三章 家庭暴力的处置', NULL, '工会、共产主义青年团、妇女联合会、残疾人联合会、居民委员会、村民委员会等应当对实施家庭暴力的加害人进行法治教育，必要时可以对加害人、受害人进行心理辅导。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218022, '《中华人民共和国反家庭暴力法》', '第二十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第四章 人身安全保护令', NULL, '当事人因遭受家庭暴力或者面临家庭暴力的现实危险，向人民法院申请人身安全保护令的，人民法院应当受理。 当事人是无民事行为能力人、限制民事行为能力人，或者因受到强制、威吓等原因无法申请人身安全保护令的，其近亲属、公安机关、妇女联合会、居民委员会、村民委员会、救助管理机构可以代为申请。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218023, '《中华人民共和国反家庭暴力法》', '第二十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第四章 人身安全保护令', NULL, '申请人身安全保护令应当以书面方式提出；书面申请确有困难的，可以口头申请，由人民法院记入笔录。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218024, '《中华人民共和国反家庭暴力法》', '第二十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第四章 人身安全保护令', NULL, '人身安全保护令案件由申请人或者被申请人居住地、家庭暴力发生地的基层人民法院管辖。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218025, '《中华人民共和国反家庭暴力法》', '第二十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第四章 人身安全保护令', NULL, '人身安全保护令由人民法院以裁定形式作出。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218026, '《中华人民共和国反家庭暴力法》', '第二十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第四章 人身安全保护令', NULL, '作出人身安全保护令，应当具备下列条件： （一）有明确的被申请人； （二）有具体的请求； （三）有遭受家庭暴力或者面临家庭暴力现实危险的情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218027, '《中华人民共和国反家庭暴力法》', '第二十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第四章 人身安全保护令', NULL, '人民法院受理申请后，应当在七十二小时内作出人身安全保护令或者驳回申请；情况紧急的，应当在二十四小时内作出。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218028, '《中华人民共和国反家庭暴力法》', '第二十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第四章 人身安全保护令', NULL, '人身安全保护令可以包括下列措施： （一）禁止被申请人实施家庭暴力； （二）禁止被申请人骚扰、跟踪、接触申请人及其相关近亲属； （三）责令被申请人迁出申请人住所； （四）保护申请人人身安全的其他措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218029, '《中华人民共和国反家庭暴力法》', '第三十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第四章 人身安全保护令', NULL, '人身安全保护令的有效期不超过六个月，自作出之日起生效。人身安全保护令失效前，人民法院可以根据申请人的申请撤销、变更或者延长。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218030, '《中华人民共和国反家庭暴力法》', '第三十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第四章 人身安全保护令', NULL, '申请人对驳回申请不服或者被申请人对人身安全保护令不服的，可以自裁定生效之日起五日内向作出裁定的人民法院申请复议一次。人民法院依法作出人身安全保护令的，复议期间不停止人身安全保护令的执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218031, '《中华人民共和国反家庭暴力法》', '第三十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第四章 人身安全保护令', NULL, '人民法院作出人身安全保护令后，应当送达申请人、被申请人、公安机关以及居民委员会、村民委员会等有关组织。人身安全保护令由人民法院执行，公安机关以及居民委员会、村民委员会等应当协助执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218032, '《中华人民共和国反家庭暴力法》', '第三十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第五章 法律责任', NULL, '加害人实施家庭暴力，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218033, '《中华人民共和国反家庭暴力法》', '第三十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第五章 法律责任', NULL, '被申请人违反人身安全保护令，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，人民法院应当给予训诫，可以根据情节轻重处以一千元以下罚款、十五日以下拘留。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218034, '《中华人民共和国反家庭暴力法》', '第三十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第五章 法律责任', NULL, '学校、幼儿园、医疗机构、居民委员会、村民委员会、社会工作服务机构、救助管理机构、福利机构及其工作人员未依照本法第十四条规定向公安机关报案，造成严重后果的，由上级主管部门或者本单位对直接负责的主管人员和其他直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218035, '《中华人民共和国反家庭暴力法》', '第三十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第五章 法律责任', NULL, '负有反家庭暴力职责的国家工作人员玩忽职守、滥用职权、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218036, '《中华人民共和国反家庭暴力法》', '第三十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第六章 附 则', NULL, '家庭成员以外共同生活的人之间实施的暴力行为，参照本法规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (218037, '《中华人民共和国反家庭暴力法》', '第三十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2015-12-27', '第六章 附 则', NULL, '本法自2016年3月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219000, '《中华人民共和国家庭教育促进法》', '第一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第一章 总 则', NULL, '为了发扬中华民族重视家庭教育的优良传统，引导全社会注重家庭、家教、家风，增进家庭幸福与社会和谐，培养德智体美劳全面发展的社会主义建设者和接班人，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219001, '《中华人民共和国家庭教育促进法》', '第二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第一章 总 则', NULL, '本法所称家庭教育，是指父母或者其他监护人为促进未成年人全面健康成长，对其实施的道德品质、身体素质、生活技能、文化修养、行为习惯等方面的培育、引导和影响。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219002, '《中华人民共和国家庭教育促进法》', '第三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第一章 总 则', NULL, '家庭教育以立德树人为根本任务，培育和践行社会主义核心价值观，弘扬中华民族优秀传统文化、革命文化、社会主义先进文化，促进未成年人健康成长。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219003, '《中华人民共和国家庭教育促进法》', '第四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第一章 总 则', NULL, '未成年人的父母或者其他监护人负责实施家庭教育。 国家和社会为家庭教育提供指导、支持和服务。 国家工作人员应当带头树立良好家风，履行家庭教育责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219004, '《中华人民共和国家庭教育促进法》', '第五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第一章 总 则', NULL, '家庭教育应当符合以下要求： （一）尊重未成年人身心发展规律和个体差异； （二）尊重未成年人人格尊严，保护未成年人隐私权和个人信息，保障未成年人合法权益； （三）遵循家庭教育特点，贯彻科学的家庭教育理念和方法； （四）家庭教育、学校教育、社会教育紧密结合、协调一致； （五）结合实际情况采取灵活多样的措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219005, '《中华人民共和国家庭教育促进法》', '第六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第一章 总 则', NULL, '各级人民政府指导家庭教育工作，建立健全家庭学校社会协同育人机制。县级以上人民政府负责妇女儿童工作的机构，组织、协调、指导、督促有关部门做好家庭教育工作。 教育行政部门、妇女联合会统筹协调社会资源，协同推进覆盖城乡的家庭教育指导服务体系建设，并按照职责分工承担家庭教育工作的日常事务。 县级以上精神文明建设部门和县级以上人民政府公安、民政、司法行政、人力资源和社会保障、文化和旅游、卫生健康、市场监督管理、广播电视、体育、新闻出版、网信等有关部门在各自的职责范围内做好家庭教育工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219006, '《中华人民共和国家庭教育促进法》', '第七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第一章 总 则', NULL, '县级以上人民政府应当制定家庭教育工作专项规划，将家庭教育指导服务纳入城乡公共服务体系和政府购买服务目录，将相关经费列入财政预算，鼓励和支持以政府购买服务的方式提供家庭教育指导。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219007, '《中华人民共和国家庭教育促进法》', '第八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第一章 总 则', NULL, '人民法院、人民检察院发挥职能作用，配合同级人民政府及其有关部门建立家庭教育工作联动机制，共同做好家庭教育工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219008, '《中华人民共和国家庭教育促进法》', '第九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第一章 总 则', NULL, '工会、共产主义青年团、残疾人联合会、科学技术协会、关心下一代工作委员会以及居民委员会、村民委员会等应当结合自身工作，积极开展家庭教育工作，为家庭教育提供社会支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219009, '《中华人民共和国家庭教育促进法》', '第十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第一章 总 则', NULL, '国家鼓励和支持企业事业单位、社会组织及个人依法开展公益性家庭教育服务活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219010, '《中华人民共和国家庭教育促进法》', '第十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第一章 总 则', NULL, '国家鼓励开展家庭教育研究，鼓励高等学校开设家庭教育专业课程，支持师范院校和有条件的高等学校加强家庭教育学科建设，培养家庭教育服务专业人才，开展家庭教育服务人员培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219011, '《中华人民共和国家庭教育促进法》', '第十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第一章 总 则', NULL, '国家鼓励和支持自然人、法人和非法人组织为家庭教育事业进行捐赠或者提供志愿服务，对符合条件的，依法给予税收优惠。 国家对在家庭教育工作中做出突出贡献的组织和个人，按照有关规定给予表彰、奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219012, '《中华人民共和国家庭教育促进法》', '第十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第一章 总 则', NULL, '每年5月15日国际家庭日所在周为全国家庭教育宣传周。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219013, '《中华人民共和国家庭教育促进法》', '第十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第二章 家庭责任', NULL, '父母或者其他监护人应当树立家庭是第一个课堂、家长是第一任老师的责任意识，承担对未成年人实施家庭教育的主体责任，用正确思想、方法和行为教育未成年人养成良好思想、品行和习惯。 共同生活的具有完全民事行为能力的其他家庭成员应当协助和配合未成年人的父母或者其他监护人实施家庭教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219014, '《中华人民共和国家庭教育促进法》', '第十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第二章 家庭责任', NULL, '未成年人的父母或者其他监护人及其他家庭成员应当注重家庭建设，培育积极健康的家庭文化，树立和传承优良家风，弘扬中华民族家庭美德，共同构建文明、和睦的家庭关系，为未成年人健康成长营造良好的家庭环境。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219015, '《中华人民共和国家庭教育促进法》', '第十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第二章 家庭责任', NULL, '未成年人的父母或者其他监护人应当针对不同年龄段未成年人的身心发展特点，以下列内容为指引，开展家庭教育： （一）教育未成年人爱党、爱国、爱人民、爱集体、爱社会主义，树立维护国家统一的观念，铸牢中华民族共同体意识，培养家国情怀； （二）教育未成年人崇德向善、尊老爱幼、热爱家庭、勤俭节约、团结互助、诚信友爱、遵纪守法，培养其良好社会公德、家庭美德、个人品德意识和法治意识； （三）帮助未成年人树立正确的成才观，引导其培养广泛兴趣爱好、健康审美追求和良好学习习惯，增强科学探索精神、创新意识和能力； （四）保证未成年人营养均衡、科学运动、睡眠充足、身心愉悦，引导其养成良好生活习惯和行为习惯，促进其身心健康发展； （五）关注未成年人心理健康，教导其珍爱生命，对其进行交通出行、健康上网和防欺凌、防溺水、防诈骗、防拐卖、防性侵等方面的安全知识教育，帮助其掌握安全知识和技能，增强其自我保护的意识和能力； （六）帮助未成年人树立正确的劳动观念，参加力所能及的劳动，提高生活自理能力和独立生活能力，养成吃苦耐劳的优秀品格和热爱劳动的良好习惯。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219016, '《中华人民共和国家庭教育促进法》', '第十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第二章 家庭责任', NULL, '未成年人的父母或者其他监护人实施家庭教育，应当关注未成年人的生理、心理、智力发展状况，尊重其参与相关家庭事务和发表意见的权利，合理运用以下方式方法： （一）亲自养育，加强亲子陪伴； （二）共同参与，发挥父母双方的作用； （三）相机而教，寓教于日常生活之中； （四）潜移默化，言传与身教相结合； （五）严慈相济，关心爱护与严格要求并重； （六）尊重差异，根据年龄和个性特点进行科学引导； （七）平等交流，予以尊重、理解和鼓励； （八）相互促进，父母与子女共同成长； （九）其他有益于未成年人全面发展、健康成长的方式方法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219017, '《中华人民共和国家庭教育促进法》', '第十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第二章 家庭责任', NULL, '未成年人的父母或者其他监护人应当树立正确的家庭教育理念，自觉学习家庭教育知识，在孕期和未成年人进入婴幼儿照护服务机构、幼儿园、中小学校等重要时段进行有针对性的学习，掌握科学的家庭教育方法，提高家庭教育的能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219018, '《中华人民共和国家庭教育促进法》', '第十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第二章 家庭责任', NULL, '未成年人的父母或者其他监护人应当与中小学校、幼儿园、婴幼儿照护服务机构、社区密切配合，积极参加其提供的公益性家庭教育指导和实践活动，共同促进未成年人健康成长。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219019, '《中华人民共和国家庭教育促进法》', '第二十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第二章 家庭责任', NULL, '未成年人的父母分居或者离异的，应当相互配合履行家庭教育责任，任何一方不得拒绝或者怠于履行；除法律另有规定外，不得阻碍另一方实施家庭教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219020, '《中华人民共和国家庭教育促进法》', '第二十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第二章 家庭责任', NULL, '未成年人的父母或者其他监护人依法委托他人代为照护未成年人的，应当与被委托人、未成年人保持联系，定期了解未成年人学习、生活情况和心理状况，与被委托人共同履行家庭教育责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219021, '《中华人民共和国家庭教育促进法》', '第二十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第二章 家庭责任', NULL, '未成年人的父母或者其他监护人应当合理安排未成年人学习、休息、娱乐和体育锻炼的时间，避免加重未成年人学习负担，预防未成年人沉迷网络。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219022, '《中华人民共和国家庭教育促进法》', '第二十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第二章 家庭责任', NULL, '未成年人的父母或者其他监护人不得因性别、身体状况、智力等歧视未成年人，不得实施家庭暴力，不得胁迫、引诱、教唆、纵容、利用未成年人从事违反法律法规和社会公德的活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219023, '《中华人民共和国家庭教育促进法》', '第二十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第三章 国家支持', NULL, '国务院应当组织有关部门制定、修订并及时颁布全国家庭教育指导大纲。 省级人民政府或者有条件的设区的市级人民政府应当组织有关部门编写或者采用适合当地实际的家庭教育指导读本，制定相应的家庭教育指导服务工作规范和评估规范。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219024, '《中华人民共和国家庭教育促进法》', '第二十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第三章 国家支持', NULL, '省级以上人民政府应当组织有关部门统筹建设家庭教育信息化共享服务平台，开设公益性网上家长学校和网络课程，开通服务热线，提供线上家庭教育指导服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219025, '《中华人民共和国家庭教育促进法》', '第二十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第三章 国家支持', NULL, '县级以上地方人民政府应当加强监督管理，减轻义务教育阶段学生作业负担和校外培训负担，畅通学校家庭沟通渠道，推进学校教育和家庭教育相互配合。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219026, '《中华人民共和国家庭教育促进法》', '第二十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第三章 国家支持', NULL, '县级以上地方人民政府及有关部门组织建立家庭教育指导服务专业队伍，加强对专业人员的培养，鼓励社会工作者、志愿者参与家庭教育指导服务工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219027, '《中华人民共和国家庭教育促进法》', '第二十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第三章 国家支持', NULL, '县级以上地方人民政府可以结合当地实际情况和需要，通过多种途径和方式确定家庭教育指导机构。 家庭教育指导机构对辖区内社区家长学校、学校家长学校及其他家庭教育指导服务站点进行指导，同时开展家庭教育研究、服务人员队伍建设和培训、公共服务产品研发。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219028, '《中华人民共和国家庭教育促进法》', '第二十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第三章 国家支持', NULL, '家庭教育指导机构应当及时向有需求的家庭提供服务。 对于父母或者其他监护人履行家庭教育责任存在一定困难的家庭，家庭教育指导机构应当根据具体情况，与相关部门协作配合，提供有针对性的服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219029, '《中华人民共和国家庭教育促进法》', '第三十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第三章 国家支持', NULL, '设区的市、县、乡级人民政府应当结合当地实际采取措施，对留守未成年人和困境未成年人家庭建档立卡，提供生活帮扶、创业就业支持等关爱服务，为留守未成年人和困境未成年人的父母或者其他监护人实施家庭教育创造条件。 教育行政部门、妇女联合会应当采取有针对性的措施，为留守未成年人和困境未成年人的父母或者其他监护人实施家庭教育提供服务，引导其积极关注未成年人身心健康状况、加强亲情关爱。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219030, '《中华人民共和国家庭教育促进法》', '第三十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第三章 国家支持', NULL, '家庭教育指导机构开展家庭教育指导服务活动，不得组织或者变相组织营利性教育培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219031, '《中华人民共和国家庭教育促进法》', '第三十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第三章 国家支持', NULL, '婚姻登记机构和收养登记机构应当通过现场咨询辅导、播放宣传教育片等形式，向办理婚姻登记、收养登记的当事人宣传家庭教育知识，提供家庭教育指导。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219032, '《中华人民共和国家庭教育促进法》', '第三十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第三章 国家支持', NULL, '儿童福利机构、未成年人救助保护机构应当对本机构安排的寄养家庭、接受救助保护的未成年人的父母或者其他监护人提供家庭教育指导。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219033, '《中华人民共和国家庭教育促进法》', '第三十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第三章 国家支持', NULL, '人民法院在审理离婚案件时，应当对有未成年子女的夫妻双方提供家庭教育指导。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219034, '《中华人民共和国家庭教育促进法》', '第三十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第三章 国家支持', NULL, '妇女联合会发挥妇女在弘扬中华民族家庭美德、树立良好家风等方面的独特作用，宣传普及家庭教育知识，通过家庭教育指导机构、社区家长学校、文明家庭建设等多种渠道组织开展家庭教育实践活动，提供家庭教育指导服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219035, '《中华人民共和国家庭教育促进法》', '第三十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第三章 国家支持', NULL, '自然人、法人和非法人组织可以依法设立非营利性家庭教育服务机构。 县级以上地方人民政府及有关部门可以采取政府补贴、奖励激励、购买服务等扶持措施，培育家庭教育服务机构。 教育、民政、卫生健康、市场监督管理等有关部门应当在各自职责范围内，依法对家庭教育服务机构及从业人员进行指导和监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219036, '《中华人民共和国家庭教育促进法》', '第三十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第三章 国家支持', NULL, '国家机关、企业事业单位、群团组织、社会组织应当将家风建设纳入单位文化建设，支持职工参加相关的家庭教育服务活动。 文明城市、文明村镇、文明单位、文明社区、文明校园和文明家庭等创建活动，应当将家庭教育情况作为重要内容。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219037, '《中华人民共和国家庭教育促进法》', '第三十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第四章 社会协同', NULL, '居民委员会、村民委员会可以依托城乡社区公共服务设施，设立社区家长学校等家庭教育指导服务站点，配合家庭教育指导机构组织面向居民、村民的家庭教育知识宣传，为未成年人的父母或者其他监护人提供家庭教育指导服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219038, '《中华人民共和国家庭教育促进法》', '第三十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第四章 社会协同', NULL, '中小学校、幼儿园应当将家庭教育指导服务纳入工作计划，作为教师业务培训的内容。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219039, '《中华人民共和国家庭教育促进法》', '第四十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第四章 社会协同', NULL, '中小学校、幼儿园可以采取建立家长学校等方式，针对不同年龄段未成年人的特点，定期组织公益性家庭教育指导服务和实践活动，并及时联系、督促未成年人的父母或者其他监护人参加。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219040, '《中华人民共和国家庭教育促进法》', '第四十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第四章 社会协同', NULL, '中小学校、幼儿园应当根据家长的需求，邀请有关人员传授家庭教育理念、知识和方法，组织开展家庭教育指导服务和实践活动，促进家庭与学校共同教育。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219041, '《中华人民共和国家庭教育促进法》', '第四十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第四章 社会协同', NULL, '具备条件的中小学校、幼儿园应当在教育行政部门的指导下，为家庭教育指导服务站点开展公益性家庭教育指导服务活动提供支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219042, '《中华人民共和国家庭教育促进法》', '第四十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第四章 社会协同', NULL, '中小学校发现未成年学生严重违反校规校纪的，应当及时制止、管教，告知其父母或者其他监护人，并为其父母或者其他监护人提供有针对性的家庭教育指导服务；发现未成年学生有不良行为或者严重不良行为的，按照有关法律规定处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219043, '《中华人民共和国家庭教育促进法》', '第四十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第四章 社会协同', NULL, '婴幼儿照护服务机构、早期教育服务机构应当为未成年人的父母或者其他监护人提供科学养育指导等家庭教育指导服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219044, '《中华人民共和国家庭教育促进法》', '第四十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第四章 社会协同', NULL, '医疗保健机构在开展婚前保健、孕产期保健、儿童保健、预防接种等服务时，应当对有关成年人、未成年人的父母或者其他监护人开展科学养育知识和婴幼儿早期发展的宣传和指导。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219045, '《中华人民共和国家庭教育促进法》', '第四十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第四章 社会协同', NULL, '图书馆、博物馆、文化馆、纪念馆、美术馆、科技馆、体育场馆、青少年宫、儿童活动中心等公共文化服务机构和爱国主义教育基地每年应当定期开展公益性家庭教育宣传、家庭教育指导服务和实践活动，开发家庭教育类公共文化服务产品。 广播、电视、报刊、互联网等新闻媒体应当宣传正确的家庭教育知识，传播科学的家庭教育理念和方法，营造重视家庭教育的良好社会氛围。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219046, '《中华人民共和国家庭教育促进法》', '第四十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第四章 社会协同', NULL, '家庭教育服务机构应当加强自律管理，制定家庭教育服务规范，组织从业人员培训，提高从业人员的业务素质和能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219047, '《中华人民共和国家庭教育促进法》', '第四十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第五章 法律责任', NULL, '未成年人住所地的居民委员会、村民委员会、妇女联合会，未成年人的父母或者其他监护人所在单位，以及中小学校、幼儿园等有关密切接触未成年人的单位，发现父母或者其他监护人拒绝、怠于履行家庭教育责任，或者非法阻碍其他监护人实施家庭教育的，应当予以批评教育、劝诫制止，必要时督促其接受家庭教育指导。 未成年人的父母或者其他监护人依法委托他人代为照护未成年人，有关单位发现被委托人不依法履行家庭教育责任的，适用前款规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219048, '《中华人民共和国家庭教育促进法》', '第四十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第五章 法律责任', NULL, '公安机关、人民检察院、人民法院在办理案件过程中，发现未成年人存在严重不良行为或者实施犯罪行为，或者未成年人的父母或者其他监护人不正确实施家庭教育侵害未成年人合法权益的，根据情况对父母或者其他监护人予以训诫，并可以责令其接受家庭教育指导。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219049, '《中华人民共和国家庭教育促进法》', '第五十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第五章 法律责任', NULL, '负有家庭教育工作职责的政府部门、机构有下列情形之一的，由其上级机关或者主管单位责令限期改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法予以处分： （一）不履行家庭教育工作职责； （二）截留、挤占、挪用或者虚报、冒领家庭教育工作经费； （三）其他滥用职权、玩忽职守或者徇私舞弊的情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219050, '《中华人民共和国家庭教育促进法》', '第五十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第五章 法律责任', NULL, '家庭教育指导机构、中小学校、幼儿园、婴幼儿照护服务机构、早期教育服务机构违反本法规定，不履行或者不正确履行家庭教育指导服务职责的，由主管部门责令限期改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法予以处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219051, '《中华人民共和国家庭教育促进法》', '第五十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第五章 法律责任', NULL, '家庭教育服务机构有下列情形之一的，由主管部门责令限期改正；拒不改正或者情节严重的，由主管部门责令停业整顿、吊销营业执照或者撤销登记： （一）未依法办理设立手续； （二）从事超出许可业务范围的行为或作虚假、引人误解宣传，产生不良后果； （三）侵犯未成年人及其父母或者其他监护人合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219052, '《中华人民共和国家庭教育促进法》', '第五十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第五章 法律责任', NULL, '未成年人的父母或者其他监护人在家庭教育过程中对未成年人实施家庭暴力的，依照《中华人民共和国未成年人保护法》、《中华人民共和国反家庭暴力法》等法律的规定追究法律责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219053, '《中华人民共和国家庭教育促进法》', '第五十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第五章 法律责任', NULL, '违反本法规定，构成违反治安管理行为的，由公安机关依法予以治安管理处罚；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (219054, '《中华人民共和国家庭教育促进法》', '第五十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2021-10-23', '第六章 附 则', NULL, '本法自2022年1月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220000, '《中华人民共和国无障碍环境建设法》', '第一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第一章 总 则', NULL, '为了加强无障碍环境建设，保障残疾人、老年人平等、充分、便捷地参与和融入社会生活，促进社会全体人员共享经济社会发展成果，弘扬社会主义核心价值观，根据宪法和有关法律，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220001, '《中华人民共和国无障碍环境建设法》', '第二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第一章 总 则', NULL, '国家采取措施推进无障碍环境建设，为残疾人、老年人自主安全地通行道路、出入建筑物以及使用其附属设施、搭乘公共交通运输工具，获取、使用和交流信息，获得社会服务等提供便利。 残疾人、老年人之外的其他人有无障碍需求的，可以享受无障碍环境便利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220002, '《中华人民共和国无障碍环境建设法》', '第三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第一章 总 则', NULL, '无障碍环境建设应当坚持中国共产党的领导，发挥政府主导作用，调动市场主体积极性，引导社会组织和公众广泛参与，推动全社会共建共治共享。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220003, '《中华人民共和国无障碍环境建设法》', '第四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第一章 总 则', NULL, '无障碍环境建设应当与适老化改造相结合，遵循安全便利、实用易行、广泛受益的原则。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220004, '《中华人民共和国无障碍环境建设法》', '第五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第一章 总 则', NULL, '无障碍环境建设应当与经济社会发展水平相适应，统筹城镇和农村发展，逐步缩小城乡无障碍环境建设的差距。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220005, '《中华人民共和国无障碍环境建设法》', '第六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第一章 总 则', NULL, '县级以上人民政府应当将无障碍环境建设纳入国民经济和社会发展规划，将所需经费纳入本级预算，建立稳定的经费保障机制。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220006, '《中华人民共和国无障碍环境建设法》', '第七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第一章 总 则', NULL, '县级以上人民政府应当统筹协调和督促指导有关部门在各自职责范围内做好无障碍环境建设工作。 县级以上人民政府住房和城乡建设、民政、工业和信息化、交通运输、自然资源、文化和旅游、教育、卫生健康等部门应当在各自职责范围内，开展无障碍环境建设工作。 乡镇人民政府、街道办事处应当协助有关部门做好无障碍环境建设工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220007, '《中华人民共和国无障碍环境建设法》', '第八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第一章 总 则', NULL, '残疾人联合会、老龄协会等组织依照法律、法规以及各自章程，协助各级人民政府及其有关部门做好无障碍环境建设工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220008, '《中华人民共和国无障碍环境建设法》', '第九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第一章 总 则', NULL, '制定或者修改涉及无障碍环境建设的法律、法规、规章、规划和其他规范性文件，应当征求残疾人、老年人代表以及残疾人联合会、老龄协会等组织的意见。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220009, '《中华人民共和国无障碍环境建设法》', '第十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第一章 总 则', NULL, '国家鼓励和支持企业事业单位、社会组织、个人等社会力量，通过捐赠、志愿服务等方式参与无障碍环境建设。 国家支持开展无障碍环境建设工作的国际交流与合作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220010, '《中华人民共和国无障碍环境建设法》', '第十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第一章 总 则', NULL, '对在无障碍环境建设工作中做出显著成绩的单位和个人，按照国家有关规定给予表彰和奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220011, '《中华人民共和国无障碍环境建设法》', '第十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第二章 无障碍设施建设', NULL, '新建、改建、扩建的居住建筑、居住区、公共建筑、公共场所、交通运输设施、城乡道路等，应当符合无障碍设施工程建设标准。 无障碍设施应当与主体工程同步规划、同步设计、同步施工、同步验收、同步交付使用，并与周边的无障碍设施有效衔接、实现贯通。 无障碍设施应当设置符合标准的无障碍标识，并纳入周边环境或者建筑物内部的引导标识系统。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220012, '《中华人民共和国无障碍环境建设法》', '第十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第二章 无障碍设施建设', NULL, '国家鼓励工程建设、设计、施工等单位采用先进的理念和技术，建设人性化、系统化、智能化并与周边环境相协调的无障碍设施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220013, '《中华人民共和国无障碍环境建设法》', '第十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第二章 无障碍设施建设', NULL, '工程建设单位应当将无障碍设施建设经费纳入工程建设项目概预算。 工程建设单位不得明示或者暗示设计、施工单位违反无障碍设施工程建设标准；不得擅自将未经验收或者验收不合格的无障碍设施交付使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220014, '《中华人民共和国无障碍环境建设法》', '第十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第二章 无障碍设施建设', NULL, '工程设计单位应当按照无障碍设施工程建设标准进行设计。 依法需要进行施工图设计文件审查的，施工图审查机构应当按照法律、法规和无障碍设施工程建设标准，对无障碍设施设计内容进行审查；不符合有关规定的，不予审查通过。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220015, '《中华人民共和国无障碍环境建设法》', '第十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第二章 无障碍设施建设', NULL, '工程施工、监理单位应当按照施工图设计文件以及相关标准进行无障碍设施施工和监理。 住房和城乡建设等主管部门对未按照法律、法规和无障碍设施工程建设标准开展无障碍设施验收或者验收不合格的，不予办理竣工验收备案手续。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220016, '《中华人民共和国无障碍环境建设法》', '第十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第二章 无障碍设施建设', NULL, '国家鼓励工程建设单位在新建、改建、扩建建设项目的规划、设计和竣工验收等环节，邀请残疾人、老年人代表以及残疾人联合会、老龄协会等组织，参加意见征询和体验试用等活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220017, '《中华人民共和国无障碍环境建设法》', '第十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第二章 无障碍设施建设', NULL, '对既有的不符合无障碍设施工程建设标准的居住建筑、居住区、公共建筑、公共场所、交通运输设施、城乡道路等，县级以上人民政府应当根据实际情况，制定有针对性的无障碍设施改造计划并组织实施。 无障碍设施改造由所有权人或者管理人负责。所有权人、管理人和使用人之间约定改造责任的，由约定的责任人负责。 不具备无障碍设施改造条件的，责任人应当采取必要的替代性措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220018, '《中华人民共和国无障碍环境建设法》', '第十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第二章 无障碍设施建设', NULL, '县级以上人民政府应当支持、指导家庭无障碍设施改造。对符合条件的残疾人、老年人家庭应当给予适当补贴。 居民委员会、村民委员会、居住区管理服务单位以及业主委员会应当支持并配合家庭无障碍设施改造。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220019, '《中华人民共和国无障碍环境建设法》', '第二十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第二章 无障碍设施建设', NULL, '残疾人集中就业单位应当按照有关标准和要求，建设和改造无障碍设施。 国家鼓励和支持用人单位开展就业场所无障碍设施建设和改造，为残疾人职工提供必要的劳动条件和便利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220020, '《中华人民共和国无障碍环境建设法》', '第二十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第二章 无障碍设施建设', NULL, '新建、改建、扩建公共建筑、公共场所、交通运输设施以及居住区的公共服务设施，应当按照无障碍设施工程建设标准，配套建设无障碍设施；既有的上述建筑、场所和设施不符合无障碍设施工程建设标准的，应当进行必要的改造。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220021, '《中华人民共和国无障碍环境建设法》', '第二十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第二章 无障碍设施建设', NULL, '国家支持城镇老旧小区既有多层住宅加装电梯或者其他无障碍设施，为残疾人、老年人提供便利。 县级以上人民政府及其有关部门应当采取措施、创造条件，并发挥社区基层组织作用，推动既有多层住宅加装电梯或者其他无障碍设施。 房屋所有权人应当弘扬中华民族与邻为善、守望相助等传统美德，加强沟通协商，依法配合既有多层住宅加装电梯或者其他无障碍设施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220022, '《中华人民共和国无障碍环境建设法》', '第二十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第二章 无障碍设施建设', NULL, '新建、改建、扩建和具备改造条件的城市主干路、主要商业区和大型居住区的人行天桥和人行地下通道，应当按照无障碍设施工程建设标准，建设或者改造无障碍设施。 城市主干路、主要商业区等无障碍需求比较集中的区域的人行道，应当按照标准设置盲道；城市中心区、残疾人集中就业单位和集中就读学校周边的人行横道的交通信号设施，应当按照标准安装过街音响提示装置。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220023, '《中华人民共和国无障碍环境建设法》', '第二十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第二章 无障碍设施建设', NULL, '停车场应当按照无障碍设施工程建设标准，设置无障碍停车位，并设置显著标志标识。 无障碍停车位优先供肢体残疾人驾驶或者乘坐的机动车使用。优先使用无障碍停车位的，应当在显著位置放置残疾人车辆专用标志或者提供残疾人证。 在无障碍停车位充足的情况下，其他行动不便的残疾人、老年人、孕妇、婴幼儿等驾驶或者乘坐的机动车也可以使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220024, '《中华人民共和国无障碍环境建设法》', '第二十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第二章 无障碍设施建设', NULL, '新投入运营的民用航空器、客运列车、客运船舶、公共汽电车、城市轨道交通车辆等公共交通运输工具，应当确保一定比例符合无障碍标准。 既有公共交通运输工具具备改造条件的，应当进行无障碍改造，逐步符合无障碍标准的要求；不具备改造条件的，公共交通运输工具的运营单位应当采取必要的替代性措施。 县级以上地方人民政府根据当地情况，逐步建立城市无障碍公交导乘系统，规划配置适量的无障碍出租汽车。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220025, '《中华人民共和国无障碍环境建设法》', '第二十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第二章 无障碍设施建设', NULL, '无障碍设施所有权人或者管理人应当对无障碍设施履行以下维护和管理责任，保障无障碍设施功能正常和使用安全： （一）对损坏的无障碍设施和标识进行维修或者替换； （二）对需改造的无障碍设施进行改造； （三）纠正占用无障碍设施的行为； （四）进行其他必要的维护和保养。 所有权人、管理人和使用人之间有约定的，由约定的责任人负责维护和管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220026, '《中华人民共和国无障碍环境建设法》', '第二十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第二章 无障碍设施建设', NULL, '因特殊情况设置的临时无障碍设施，应当符合无障碍设施工程建设标准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220027, '《中华人民共和国无障碍环境建设法》', '第二十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第二章 无障碍设施建设', NULL, '任何单位和个人不得擅自改变无障碍设施的用途或者非法占用、损坏无障碍设施。 因特殊情况临时占用无障碍设施的，应当公告并设置护栏、警示标志或者信号设施，同时采取必要的替代性措施。临时占用期满，应当及时恢复原状。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220028, '《中华人民共和国无障碍环境建设法》', '第二十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第三章 无障碍信息交流', NULL, '各级人民政府及其有关部门应当为残疾人、老年人获取公共信息提供便利；发布涉及自然灾害、事故灾难、公共卫生事件、社会安全事件等突发事件信息时，条件具备的同步采取语音、大字、盲文、手语等无障碍信息交流方式。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220029, '《中华人民共和国无障碍环境建设法》', '第三十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第三章 无障碍信息交流', NULL, '利用财政资金设立的电视台应当在播出电视节目时配备同步字幕，条件具备的每天至少播放一次配播手语的新闻节目，并逐步扩大配播手语的节目范围。 国家鼓励公开出版发行的影视类录像制品、网络视频节目加配字幕、手语或者口述音轨。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220030, '《中华人民共和国无障碍环境建设法》', '第三十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第三章 无障碍信息交流', NULL, '国家鼓励公开出版发行的图书、报刊配备有声、大字、盲文、电子等无障碍格式版本，方便残疾人、老年人阅读。 国家鼓励教材编写、出版单位根据不同教育阶段实际，编写、出版盲文版、低视力版教学用书，满足盲人和其他有视力障碍的学生的学习需求。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220031, '《中华人民共和国无障碍环境建设法》', '第三十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第三章 无障碍信息交流', NULL, '利用财政资金建立的互联网网站、服务平台、移动互联网应用程序，应当逐步符合无障碍网站设计标准和国家信息无障碍标准。 国家鼓励新闻资讯、社交通讯、生活购物、医疗健康、金融服务、学习教育、交通出行等领域的互联网网站、移动互联网应用程序，逐步符合无障碍网站设计标准和国家信息无障碍标准。 国家鼓励地图导航定位产品逐步完善无障碍设施的标识和无障碍出行路线导航功能。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220032, '《中华人民共和国无障碍环境建设法》', '第三十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第三章 无障碍信息交流', NULL, '音视频以及多媒体设备、移动智能终端设备、电信终端设备制造者提供的产品，应当逐步具备语音、大字等无障碍功能。 银行、医院、城市轨道交通车站、民用运输机场航站区、客运站、客运码头、大型景区等的自助公共服务终端设备，应当具备语音、大字、盲文等无障碍功能。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220033, '《中华人民共和国无障碍环境建设法》', '第三十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第三章 无障碍信息交流', NULL, '电信业务经营者提供基础电信服务时，应当为残疾人、老年人提供必要的语音、大字信息服务或者人工服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220034, '《中华人民共和国无障碍环境建设法》', '第三十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第三章 无障碍信息交流', NULL, '政务服务便民热线和报警求助、消防应急、交通事故、医疗急救等紧急呼叫系统，应当逐步具备语音、大字、盲文、一键呼叫等无障碍功能。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220035, '《中华人民共和国无障碍环境建设法》', '第三十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第三章 无障碍信息交流', NULL, '提供公共文化服务的图书馆、博物馆、文化馆、科技馆等应当考虑残疾人、老年人的特点，积极创造条件，提供适合其需要的文献信息、无障碍设施设备和服务等。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220036, '《中华人民共和国无障碍环境建设法》', '第三十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第三章 无障碍信息交流', NULL, '国务院有关部门应当完善药品标签、说明书的管理规范，要求药品生产经营者提供语音、大字、盲文、电子等无障碍格式版本的标签、说明书。 国家鼓励其他商品的生产经营者提供语音、大字、盲文、电子等无障碍格式版本的标签、说明书，方便残疾人、老年人识别和使用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220037, '《中华人民共和国无障碍环境建设法》', '第三十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第三章 无障碍信息交流', NULL, '国家推广和使用国家通用手语、国家通用盲文。 基本公共服务使用手语、盲文以及各类学校开展手语、盲文教育教学时，应当采用国家通用手语、国家通用盲文。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220038, '《中华人民共和国无障碍环境建设法》', '第三十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第四章 无障碍社会服务', NULL, '公共服务场所应当配备必要的无障碍设备和辅助器具，标注指引无障碍设施，为残疾人、老年人提供无障碍服务。 公共服务场所涉及医疗健康、社会保障、金融业务、生活缴费等服务事项的，应当保留现场指导、人工办理等传统服务方式。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220039, '《中华人民共和国无障碍环境建设法》', '第四十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第四章 无障碍社会服务', NULL, '行政服务机构、社区服务机构以及供水、供电、供气、供热等公共服务机构，应当设置低位服务台或者无障碍服务窗口，配备电子信息显示屏、手写板、语音提示等设备，为残疾人、老年人提供无障碍服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220040, '《中华人民共和国无障碍环境建设法》', '第四十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第四章 无障碍社会服务', NULL, '司法机关、仲裁机构、法律援助机构应当依法为残疾人、老年人参加诉讼、仲裁活动和获得法律援助提供无障碍服务。 国家鼓励律师事务所、公证机构、司法鉴定机构、基层法律服务所等法律服务机构，结合所提供的服务内容提供无障碍服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220041, '《中华人民共和国无障碍环境建设法》', '第四十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第四章 无障碍社会服务', NULL, '交通运输设施和公共交通运输工具的运营单位应当根据各类运输方式的服务特点，结合设施设备条件和所提供的服务内容，为残疾人、老年人设置无障碍服务窗口、专用等候区域、绿色通道和优先坐席，提供辅助器具、咨询引导、字幕报站、语音提示、预约定制等无障碍服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220042, '《中华人民共和国无障碍环境建设法》', '第四十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第四章 无障碍社会服务', NULL, '教育行政部门和教育机构应当加强教育场所的无障碍环境建设，为有残疾的师生、员工提供无障碍服务。 国家举办的教育考试、职业资格考试、技术技能考试、招录招聘考试以及各类学校组织的统一考试，应当为有残疾的考生提供便利服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220043, '《中华人民共和国无障碍环境建设法》', '第四十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第四章 无障碍社会服务', NULL, '医疗卫生机构应当结合所提供的服务内容，为残疾人、老年人就医提供便利。 与残疾人、老年人相关的服务机构应当配备无障碍设备，在生活照料、康复护理等方面提供无障碍服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220044, '《中华人民共和国无障碍环境建设法》', '第四十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第四章 无障碍社会服务', NULL, '国家鼓励文化、旅游、体育、金融、邮政、电信、交通、商业、餐饮、住宿、物业管理等服务场所结合所提供的服务内容，为残疾人、老年人提供辅助器具、咨询引导等无障碍服务。 国家鼓励邮政、快递企业为行动不便的残疾人、老年人提供上门收寄服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220045, '《中华人民共和国无障碍环境建设法》', '第四十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第四章 无障碍社会服务', NULL, '公共场所经营管理单位、交通运输设施和公共交通运输工具的运营单位应当为残疾人携带导盲犬、导听犬、辅助犬等服务犬提供便利。 残疾人携带服务犬出入公共场所、使用交通运输设施和公共交通运输工具的，应当遵守国家有关规定，为服务犬佩戴明显识别装备，并采取必要的防护措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220046, '《中华人民共和国无障碍环境建设法》', '第四十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第四章 无障碍社会服务', NULL, '应急避难场所的管理人在制定以及实施工作预案时，应当考虑残疾人、老年人的无障碍需求，视情况设置语音、大字、闪光等提示装置，完善无障碍服务功能。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220047, '《中华人民共和国无障碍环境建设法》', '第四十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第四章 无障碍社会服务', NULL, '组织选举的部门和单位应当采取措施，为残疾人、老年人选民参加投票提供便利和必要协助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220048, '《中华人民共和国无障碍环境建设法》', '第四十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第四章 无障碍社会服务', NULL, '国家鼓励和支持无障碍信息服务平台建设，为残疾人、老年人提供远程实时无障碍信息服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220049, '《中华人民共和国无障碍环境建设法》', '第五十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第五章 保障措施', NULL, '国家开展无障碍环境理念的宣传教育，普及无障碍环境知识，传播无障碍环境文化，提升全社会的无障碍环境意识。 新闻媒体应当积极开展无障碍环境建设方面的公益宣传。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220050, '《中华人民共和国无障碍环境建设法》', '第五十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第五章 保障措施', NULL, '国家推广通用设计理念，建立健全国家标准、行业标准、地方标准，鼓励发展具有引领性的团体标准、企业标准，加强标准之间的衔接配合，构建无障碍环境建设标准体系。 地方结合本地实际制定的地方标准不得低于国家标准的相关技术要求。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220051, '《中华人民共和国无障碍环境建设法》', '第五十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第五章 保障措施', NULL, '制定或者修改涉及无障碍环境建设的标准，应当征求残疾人、老年人代表以及残疾人联合会、老龄协会等组织的意见。残疾人联合会、老龄协会等组织可以依法提出制定或者修改无障碍环境建设标准的建议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220052, '《中华人民共和国无障碍环境建设法》', '第五十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第五章 保障措施', NULL, '国家建立健全无障碍设计、设施、产品、服务的认证和无障碍信息的评测制度，并推动结果采信应用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220053, '《中华人民共和国无障碍环境建设法》', '第五十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第五章 保障措施', NULL, '国家通过经费支持、政府采购、税收优惠等方式，促进新科技成果在无障碍环境建设中的运用，鼓励无障碍技术、产品和服务的研发、生产、应用和推广，支持无障碍设施、信息和服务的融合发展。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220054, '《中华人民共和国无障碍环境建设法》', '第五十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第五章 保障措施', NULL, '国家建立无障碍环境建设相关领域人才培养机制。 国家鼓励高等学校、中等职业学校等开设无障碍环境建设相关专业和课程，开展无障碍环境建设理论研究、国际交流和实践活动。 建筑、交通运输、计算机科学与技术等相关学科专业应当增加无障碍环境建设的教学和实践内容，相关领域职业资格、继续教育以及其他培训的考试内容应当包括无障碍环境建设知识。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220055, '《中华人民共和国无障碍环境建设法》', '第五十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第五章 保障措施', NULL, '国家鼓励机关、企业事业单位、社会团体以及其他社会组织，对工作人员进行无障碍服务知识与技能培训。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220056, '《中华人民共和国无障碍环境建设法》', '第五十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第五章 保障措施', NULL, '文明城市、文明村镇、文明单位、文明社区、文明校园等创建活动，应当将无障碍环境建设情况作为重要内容。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220057, '《中华人民共和国无障碍环境建设法》', '第五十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第六章 监督管理', NULL, '县级以上人民政府及其有关主管部门依法对无障碍环境建设进行监督检查，根据工作需要开展联合监督检查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220058, '《中华人民共和国无障碍环境建设法》', '第五十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第六章 监督管理', NULL, '国家实施无障碍环境建设目标责任制和考核评价制度。县级以上地方人民政府根据本地区实际，制定具体考核办法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220059, '《中华人民共和国无障碍环境建设法》', '第六十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第六章 监督管理', NULL, '县级以上地方人民政府有关主管部门定期委托第三方机构开展无障碍环境建设评估，并将评估结果向社会公布，接受社会监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220060, '《中华人民共和国无障碍环境建设法》', '第六十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第六章 监督管理', NULL, '县级以上人民政府建立无障碍环境建设信息公示制度，定期发布无障碍环境建设情况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220061, '《中华人民共和国无障碍环境建设法》', '第六十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第六章 监督管理', NULL, '任何组织和个人有权向政府有关主管部门提出加强和改进无障碍环境建设的意见和建议，对违反本法规定的行为进行投诉、举报。县级以上人民政府有关主管部门接到涉及无障碍环境建设的投诉和举报，应当及时处理并予以答复。 残疾人联合会、老龄协会等组织根据需要，可以聘请残疾人、老年人代表以及具有相关专业知识的人员，对无障碍环境建设情况进行监督。 新闻媒体可以对无障碍环境建设情况开展舆论监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220062, '《中华人民共和国无障碍环境建设法》', '第六十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第六章 监督管理', NULL, '对违反本法规定损害社会公共利益的行为，人民检察院可以提出检察建议或者提起公益诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220063, '《中华人民共和国无障碍环境建设法》', '第六十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第七章 法律责任', NULL, '工程建设、设计、施工、监理单位未按照本法规定进行建设、设计、施工、监理的，由住房和城乡建设、民政、交通运输等相关主管部门责令限期改正；逾期未改正的，依照相关法律法规的规定进行处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220064, '《中华人民共和国无障碍环境建设法》', '第六十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第七章 法律责任', NULL, '违反本法规定，有下列情形之一的，由住房和城乡建设、民政、交通运输等相关主管部门责令限期改正；逾期未改正的，对单位处一万元以上三万元以下罚款，对个人处一百元以上五百元以下罚款： （一）无障碍设施责任人不履行维护和管理职责，无法保障无障碍设施功能正常和使用安全； （二）设置临时无障碍设施不符合相关规定； （三）擅自改变无障碍设施的用途或者非法占用、损坏无障碍设施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220065, '《中华人民共和国无障碍环境建设法》', '第六十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第七章 法律责任', NULL, '违反本法规定，不依法履行无障碍信息交流义务的，由网信、工业和信息化、电信、广播电视、新闻出版等相关主管部门责令限期改正；逾期未改正的，予以通报批评。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220066, '《中华人民共和国无障碍环境建设法》', '第六十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第七章 法律责任', NULL, '电信业务经营者不依法提供无障碍信息服务的，由电信主管部门责令限期改正；逾期未改正的，处一万元以上十万元以下罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220067, '《中华人民共和国无障碍环境建设法》', '第六十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第七章 法律责任', NULL, '负有公共服务职责的部门和单位未依法提供无障碍社会服务的，由本级人民政府或者上级主管部门责令限期改正；逾期未改正的，对直接负责的主管人员和其他直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220068, '《中华人民共和国无障碍环境建设法》', '第六十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第七章 法律责任', NULL, '考试举办者、组织者未依法向有残疾的考生提供便利服务的，由本级人民政府或者上级主管部门予以批评并责令改正；拒不改正的，对直接负责的主管人员和其他直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220069, '《中华人民共和国无障碍环境建设法》', '第七十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第七章 法律责任', NULL, '无障碍环境建设相关主管部门、有关组织的工作人员滥用职权、玩忽职守、徇私舞弊的，依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220070, '《中华人民共和国无障碍环境建设法》', '第七十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第七章 法律责任', NULL, '违反本法规定，造成人身损害、财产损失的，依法承担民事责任；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (220071, '《中华人民共和国无障碍环境建设法》', '第七十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2023-06-28', '第八章 附 则', NULL, '本法自2023年9月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221000, '《中华人民共和国退役军人保障法》', '第一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第一章 总 则', NULL, '为了加强退役军人保障工作，维护退役军人合法权益，让军人成为全社会尊崇的职业，根据宪法，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221001, '《中华人民共和国退役军人保障法》', '第二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第一章 总 则', NULL, '本法所称退役军人，是指从中国人民解放军依法退出现役的军官、军士和义务兵等人员。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221002, '《中华人民共和国退役军人保障法》', '第三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第一章 总 则', NULL, '退役军人为国防和军队建设做出了重要贡献，是社会主义现代化建设的重要力量。 尊重、关爱退役军人是全社会的共同责任。国家关心、优待退役军人，加强退役军人保障体系建设，保障退役军人依法享有相应的权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221003, '《中华人民共和国退役军人保障法》', '第四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第一章 总 则', NULL, '退役军人保障工作坚持中国共产党的领导，坚持为经济社会发展服务、为国防和军队建设服务的方针，遵循以人为本、分类保障、服务优先、依法管理的原则。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221004, '《中华人民共和国退役军人保障法》', '第五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第一章 总 则', NULL, '退役军人保障应当与经济发展相协调，与社会进步相适应。 退役军人安置工作应当公开、公平、公正。 退役军人的政治、生活等待遇与其服现役期间所做贡献挂钩。 国家建立参战退役军人特别优待机制。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221005, '《中华人民共和国退役军人保障法》', '第六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第一章 总 则', NULL, '退役军人应当继续发扬人民军队优良传统，模范遵守宪法和法律法规，保守军事秘密，践行社会主义核心价值观，积极参加社会主义现代化建设。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221006, '《中华人民共和国退役军人保障法》', '第七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第一章 总 则', NULL, '国务院退役军人工作主管部门负责全国的退役军人保障工作。县级以上地方人民政府退役军人工作主管部门负责本行政区域的退役军人保障工作。 中央和国家有关机关、中央军事委员会有关部门、地方各级有关机关应当在各自职责范围内做好退役军人保障工作。 军队各级负责退役军人有关工作的部门与县级以上人民政府退役军人工作主管部门应当密切配合，做好退役军人保障工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221007, '《中华人民共和国退役军人保障法》', '第八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第一章 总 则', NULL, '国家加强退役军人保障工作信息化建设，为退役军人建档立卡，实现有关部门之间信息共享，为提高退役军人保障能力提供支持。 国务院退役军人工作主管部门应当与中央和国家有关机关、中央军事委员会有关部门密切配合，统筹做好信息数据系统的建设、维护、应用和信息安全管理等工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221008, '《中华人民共和国退役军人保障法》', '第九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第一章 总 则', NULL, '退役军人保障工作所需经费由中央和地方财政共同负担。退役安置、教育培训、抚恤优待资金主要由中央财政负担。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221009, '《中华人民共和国退役军人保障法》', '第十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第一章 总 则', NULL, '国家鼓励和引导企业、社会组织、个人等社会力量依法通过捐赠、设立基金、志愿服务等方式为退役军人提供支持和帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221010, '《中华人民共和国退役军人保障法》', '第十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第一章 总 则', NULL, '对在退役军人保障工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221011, '《中华人民共和国退役军人保障法》', '第十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第二章 移交接收', NULL, '国务院退役军人工作主管部门、中央军事委员会政治工作部门、中央和国家有关机关应当制定全国退役军人的年度移交接收计划。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221012, '《中华人民共和国退役军人保障法》', '第十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第二章 移交接收', NULL, '退役军人原所在部队应当将退役军人移交安置地人民政府退役军人工作主管部门，安置地人民政府退役军人工作主管部门负责接收退役军人。 退役军人的安置地，按照国家有关规定确定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221013, '《中华人民共和国退役军人保障法》', '第十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第二章 移交接收', NULL, '退役军人应当在规定时间内，持军队出具的退役证明到安置地人民政府退役军人工作主管部门报到。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221014, '《中华人民共和国退役军人保障法》', '第十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第二章 移交接收', NULL, '安置地人民政府退役军人工作主管部门在接收退役军人时，向退役军人发放退役军人优待证。 退役军人优待证全国统一制发、统一编号，管理使用办法由国务院退役军人工作主管部门会同有关部门制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221015, '《中华人民共和国退役军人保障法》', '第十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第二章 移交接收', NULL, '军人所在部队在军人退役时，应当及时将其人事档案移交安置地人民政府退役军人工作主管部门。 安置地人民政府退役军人工作主管部门应当按照国家人事档案管理有关规定，接收、保管并向有关单位移交退役军人人事档案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221016, '《中华人民共和国退役军人保障法》', '第十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第二章 移交接收', NULL, '安置地人民政府公安机关应当按照国家有关规定，及时为退役军人办理户口登记，同级退役军人工作主管部门应当予以协助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221017, '《中华人民共和国退役军人保障法》', '第十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第二章 移交接收', NULL, '退役军人原所在部队应当按照有关法律法规规定，及时将退役军人及随军未就业配偶的养老、医疗等社会保险关系和相应资金，转入安置地社会保险经办机构。 安置地人民政府退役军人工作主管部门应当与社会保险经办机构、军队有关部门密切配合，依法做好有关社会保险关系和相应资金转移接续工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221018, '《中华人民共和国退役军人保障法》', '第十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第二章 移交接收', NULL, '退役军人移交接收过程中，发生与其服现役有关的问题，由原所在部队负责处理；发生与其安置有关的问题，由安置地人民政府负责处理；发生其他移交接收方面问题的，由安置地人民政府负责处理，原所在部队予以配合。 退役军人原所在部队撤销或者转隶、合并的，由原所在部队的上级单位或者转隶、合并后的单位按照前款规定处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221019, '《中华人民共和国退役军人保障法》', '第二十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第三章 退役安置', NULL, '地方各级人民政府应当按照移交接收计划，做好退役军人安置工作，完成退役军人安置任务。 机关、群团组织、企业事业单位和社会组织应当依法接收安置退役军人，退役军人应当接受安置。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221020, '《中华人民共和国退役军人保障法》', '第二十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第三章 退役安置', NULL, '对退役的军官，国家采取退休、转业、逐月领取退役金、复员等方式妥善安置。 以退休方式移交人民政府安置的，由安置地人民政府按照国家保障与社会化服务相结合的方式，做好服务管理工作，保障其待遇。 以转业方式安置的，由安置地人民政府根据其德才条件以及服现役期间的职务、等级、所做贡献、专长等和工作需要安排工作岗位，确定相应的职务职级。 服现役满规定年限，以逐月领取退役金方式安置的，按照国家有关规定逐月领取退役金。 以复员方式安置的，按照国家有关规定领取复员费。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221021, '《中华人民共和国退役军人保障法》', '第二十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第三章 退役安置', NULL, '对退役的军士，国家采取逐月领取退役金、自主就业、安排工作、退休、供养等方式妥善安置。 服现役满规定年限，以逐月领取退役金方式安置的，按照国家有关规定逐月领取退役金。 服现役不满规定年限，以自主就业方式安置的，领取一次性退役金。 以安排工作方式安置的，由安置地人民政府根据其服现役期间所做贡献、专长等安排工作岗位。 以退休方式安置的，由安置地人民政府按照国家保障与社会化服务相结合的方式，做好服务管理工作，保障其待遇。 以供养方式安置的，由国家供养终身。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221022, '《中华人民共和国退役军人保障法》', '第二十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第三章 退役安置', NULL, '对退役的义务兵，国家采取自主就业、安排工作、供养等方式妥善安置。 以自主就业方式安置的，领取一次性退役金。 以安排工作方式安置的，由安置地人民政府根据其服现役期间所做贡献、专长等安排工作岗位。 以供养方式安置的，由国家供养终身。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221023, '《中华人民共和国退役军人保障法》', '第二十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第三章 退役安置', NULL, '退休、转业、逐月领取退役金、复员、自主就业、安排工作、供养等安置方式的适用条件，按照相关法律法规执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221024, '《中华人民共和国退役军人保障法》', '第二十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第三章 退役安置', NULL, '转业军官、安排工作的军士和义务兵，由机关、群团组织、事业单位和国有企业接收安置。对下列退役军人，优先安置： （一）参战退役军人； （二）担任作战部队师、旅、团、营级单位主官的转业军官； （三）属于烈士子女、功臣模范的退役军人； （四）长期在艰苦边远地区或者特殊岗位服现役的退役军人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221025, '《中华人民共和国退役军人保障法》', '第二十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第三章 退役安置', NULL, '机关、群团组织、事业单位接收安置转业军官、安排工作的军士和义务兵的，应当按照国家有关规定给予编制保障。 国有企业接收安置转业军官、安排工作的军士和义务兵的，应当按照国家规定与其签订劳动合同，保障相应待遇。 前两款规定的用人单位依法裁减人员时，应当优先留用接收安置的转业和安排工作的退役军人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221026, '《中华人民共和国退役军人保障法》', '第二十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第三章 退役安置', NULL, '以逐月领取退役金方式安置的退役军官和军士，被录用为公务员或者聘用为事业单位工作人员的，自被录用、聘用下月起停发退役金，其待遇按照公务员、事业单位工作人员管理相关法律法规执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221027, '《中华人民共和国退役军人保障法》', '第二十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第三章 退役安置', NULL, '国家建立伤病残退役军人指令性移交安置、收治休养制度。军队有关部门应当及时将伤病残退役军人移交安置地人民政府安置。安置地人民政府应当妥善解决伤病残退役军人的住房、医疗、康复、护理和生活困难。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221028, '《中华人民共和国退役军人保障法》', '第二十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第三章 退役安置', NULL, '各级人民政府加强拥军优属工作，为军人和家属排忧解难。 符合条件的军官和军士退出现役时，其配偶和子女可以按照国家有关规定随调随迁。 随调配偶在机关或者事业单位工作，符合有关法律法规规定的，安置地人民政府负责安排到相应的工作单位；随调配偶在其他单位工作或者无工作单位的，安置地人民政府应当提供就业指导，协助实现就业。 随迁子女需要转学、入学的，安置地人民政府教育行政部门应当予以及时办理。对下列退役军人的随迁子女，优先保障： （一）参战退役军人； （二）属于烈士子女、功臣模范的退役军人； （三）长期在艰苦边远地区或者特殊岗位服现役的退役军人； （四）其他符合条件的退役军人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221029, '《中华人民共和国退役军人保障法》', '第三十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第三章 退役安置', NULL, '军人退役安置的具体办法由国务院、中央军事委员会制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221030, '《中华人民共和国退役军人保障法》', '第三十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第四章 教育培训', NULL, '退役军人的教育培训应当以提高就业质量为导向，紧密围绕社会需求，为退役军人提供有特色、精细化、针对性强的培训服务。 国家采取措施加强对退役军人的教育培训，帮助退役军人完善知识结构，提高思想政治水平、职业技能水平和综合职业素养，提升就业创业能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221031, '《中华人民共和国退役军人保障法》', '第三十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第四章 教育培训', NULL, '国家建立学历教育和职业技能培训并行并举的退役军人教育培训体系，建立退役军人教育培训协调机制，统筹规划退役军人教育培训工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221032, '《中华人民共和国退役军人保障法》', '第三十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第四章 教育培训', NULL, '军人退役前，所在部队在保证完成军事任务的前提下，可以根据部队特点和条件提供职业技能储备培训，组织参加高等教育自学考试和各类高等学校举办的高等学历继续教育，以及知识拓展、技能培训等非学历继续教育。 部队所在地县级以上地方人民政府退役军人工作主管部门应当为现役军人所在部队开展教育培训提供支持和协助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221033, '《中华人民共和国退役军人保障法》', '第三十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第四章 教育培训', NULL, '退役军人在接受学历教育时，按照国家有关规定享受学费和助学金资助等国家教育资助政策。 高等学校根据国家统筹安排，可以通过单列计划、单独招生等方式招考退役军人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221034, '《中华人民共和国退役军人保障法》', '第三十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第四章 教育培训', NULL, '现役军人入伍前已被普通高等学校录取或者是正在普通高等学校就学的学生，服现役期间保留入学资格或者学籍，退役后两年内允许入学或者复学，可以按照国家有关规定转入本校其他专业学习。达到报考研究生条件的，按照国家有关规定享受优惠政策。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221035, '《中华人民共和国退役军人保障法》', '第三十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第四章 教育培训', NULL, '国家依托和支持普通高等学校、职业院校（含技工院校）、专业培训机构等教育资源，为退役军人提供职业技能培训。退役军人未达到法定退休年龄需要就业创业的，可以享受职业技能培训补贴等相应扶持政策。 军人退出现役，安置地人民政府应当根据就业需求组织其免费参加职业教育、技能培训，经考试考核合格的，发给相应的学历证书、职业资格证书或者职业技能等级证书并推荐就业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221036, '《中华人民共和国退役军人保障法》', '第三十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第四章 教育培训', NULL, '省级人民政府退役军人工作主管部门会同有关部门加强动态管理，定期对为退役军人提供职业技能培训的普通高等学校、职业院校（含技工院校）、专业培训机构的培训质量进行检查和考核，提高职业技能培训质量和水平。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221037, '《中华人民共和国退役军人保障法》', '第三十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第五章 就业创业', NULL, '国家采取政府推动、市场引导、社会支持相结合的方式，鼓励和扶持退役军人就业创业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221038, '《中华人民共和国退役军人保障法》', '第三十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第五章 就业创业', NULL, '各级人民政府应当加强对退役军人就业创业的指导和服务。 县级以上地方人民政府退役军人工作主管部门应当加强对退役军人就业创业的宣传、组织、协调等工作，会同有关部门采取退役军人专场招聘会等形式，开展就业推荐、职业指导，帮助退役军人就业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221039, '《中华人民共和国退役军人保障法》', '第四十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第五章 就业创业', NULL, '服现役期间因战、因公、因病致残被评定残疾等级和退役后补评或者重新评定残疾等级的残疾退役军人，有劳动能力和就业意愿的，优先享受国家规定的残疾人就业优惠政策。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221040, '《中华人民共和国退役军人保障法》', '第四十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第五章 就业创业', NULL, '公共人力资源服务机构应当免费为退役军人提供职业介绍、创业指导等服务。 国家鼓励经营性人力资源服务机构和社会组织为退役军人就业创业提供免费或者优惠服务。 退役军人未能及时就业的，在人力资源和社会保障部门办理求职登记后，可以按照规定享受失业保险待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221041, '《中华人民共和国退役军人保障法》', '第四十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第五章 就业创业', NULL, '机关、群团组织、事业单位和国有企业在招录或者招聘人员时，对退役军人的年龄和学历条件可以适当放宽，同等条件下优先招录、招聘退役军人。退役的军士和义务兵服现役经历视为基层工作经历。 退役的军士和义务兵入伍前是机关、群团组织、事业单位或者国有企业人员的，退役后可以选择复职复工。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221042, '《中华人民共和国退役军人保障法》', '第四十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第五章 就业创业', NULL, '各地应当设置一定数量的基层公务员职位，面向服现役满五年的高校毕业生退役军人招考。 服现役满五年的高校毕业生退役军人可以报考面向服务基层项目人员定向考录的职位，同服务基层项目人员共享公务员定向考录计划。 各地应当注重从优秀退役军人中选聘党的基层组织、社区和村专职工作人员。 军队文职人员岗位、国防教育机构岗位等，应当优先选用符合条件的退役军人。 国家鼓励退役军人参加稳边固边等边疆建设工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221043, '《中华人民共和国退役军人保障法》', '第四十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第五章 就业创业', NULL, '退役军人服现役年限计算为工龄，退役后与所在单位工作年限累计计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221044, '《中华人民共和国退役军人保障法》', '第四十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第五章 就业创业', NULL, '县级以上地方人民政府投资建设或者与社会共建的创业孵化基地和创业园区，应当优先为退役军人创业提供服务。有条件的地区可以建立退役军人创业孵化基地和创业园区，为退役军人提供经营场地、投资融资等方面的优惠服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221045, '《中华人民共和国退役军人保障法》', '第四十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第五章 就业创业', NULL, '退役军人创办小微企业，可以按照国家有关规定申请创业担保贷款，并享受贷款贴息等融资优惠政策。 退役军人从事个体经营，依法享受税收优惠政策。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221046, '《中华人民共和国退役军人保障法》', '第四十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第五章 就业创业', NULL, '用人单位招用退役军人符合国家规定的，依法享受税收优惠等政策。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221047, '《中华人民共和国退役军人保障法》', '第四十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第六章 抚恤优待', NULL, '各级人民政府应当坚持普惠与优待叠加的原则，在保障退役军人享受普惠性政策和公共服务基础上，结合服现役期间所做贡献和各地实际情况给予优待。 对参战退役军人，应当提高优待标准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221048, '《中华人民共和国退役军人保障法》', '第四十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第六章 抚恤优待', NULL, '国家逐步消除退役军人抚恤优待制度城乡差异、缩小地区差异，建立统筹平衡的抚恤优待量化标准体系。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221049, '《中华人民共和国退役军人保障法》', '第五十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第六章 抚恤优待', NULL, '退役军人依法参加养老、医疗、工伤、失业、生育等社会保险，并享受相应待遇。 退役军人服现役年限与入伍前、退役后参加职工基本养老保险、职工基本医疗保险、失业保险的缴费年限依法合并计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221050, '《中华人民共和国退役军人保障法》', '第五十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第六章 抚恤优待', NULL, '退役军人符合安置住房优待条件的，实行市场购买与军地集中统建相结合，由安置地人民政府统筹规划、科学实施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221051, '《中华人民共和国退役军人保障法》', '第五十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第六章 抚恤优待', NULL, '军队医疗机构、公立医疗机构应当为退役军人就医提供优待服务，并对参战退役军人、残疾退役军人给予优惠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221052, '《中华人民共和国退役军人保障法》', '第五十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第六章 抚恤优待', NULL, '退役军人凭退役军人优待证等有效证件享受公共交通、文化和旅游等优待，具体办法由省级人民政府制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221053, '《中华人民共和国退役军人保障法》', '第五十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第六章 抚恤优待', NULL, '县级以上人民政府加强优抚医院、光荣院建设，充分利用现有医疗和养老服务资源，收治或者集中供养孤老、生活不能自理的退役军人。 各类社会福利机构应当优先接收老年退役军人和残疾退役军人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221054, '《中华人民共和国退役军人保障法》', '第五十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第六章 抚恤优待', NULL, '国家建立退役军人帮扶援助机制，在养老、医疗、住房等方面，对生活困难的退役军人按照国家有关规定给予帮扶援助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221055, '《中华人民共和国退役军人保障法》', '第五十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第六章 抚恤优待', NULL, '残疾退役军人依法享受抚恤。 残疾退役军人按照残疾等级享受残疾抚恤金，标准由国务院退役军人工作主管部门会同国务院财政部门综合考虑国家经济社会发展水平、消费物价水平、全国城镇单位就业人员工资水平、国家财力情况等因素确定。残疾抚恤金由县级人民政府退役军人工作主管部门发放。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221056, '《中华人民共和国退役军人保障法》', '第五十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第七章 褒扬激励', NULL, '国家建立退役军人荣誉激励机制，对在社会主义现代化建设中做出突出贡献的退役军人予以表彰、奖励。退役军人服现役期间获得表彰、奖励的，退役后按照国家有关规定享受相应待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221057, '《中华人民共和国退役军人保障法》', '第五十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第七章 褒扬激励', NULL, '退役军人安置地人民政府在接收退役军人时，应当举行迎接仪式。迎接仪式由安置地人民政府退役军人工作主管部门负责实施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221058, '《中华人民共和国退役军人保障法》', '第五十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第七章 褒扬激励', NULL, '地方人民政府应当为退役军人家庭悬挂光荣牌，定期开展走访慰问活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221059, '《中华人民共和国退役军人保障法》', '第六十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第七章 褒扬激励', NULL, '国家、地方和军队举行重大庆典活动时，应当邀请退役军人代表参加。 被邀请的退役军人参加重大庆典活动时，可以穿着退役时的制式服装，佩戴服现役期间和退役后荣获的勋章、奖章、纪念章等徽章。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221060, '《中华人民共和国退役军人保障法》', '第六十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第七章 褒扬激励', NULL, '国家注重发挥退役军人在爱国主义教育和国防教育活动中的积极作用。机关、群团组织、企业事业单位和社会组织可以邀请退役军人协助开展爱国主义教育和国防教育。县级以上人民政府教育行政部门可以邀请退役军人参加学校国防教育培训，学校可以聘请退役军人参与学生军事训练。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221061, '《中华人民共和国退役军人保障法》', '第六十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第七章 褒扬激励', NULL, '县级以上人民政府退役军人工作主管部门应当加强对退役军人先进事迹的宣传，通过制作公益广告、创作主题文艺作品等方式，弘扬爱国主义精神、革命英雄主义精神和退役军人敬业奉献精神。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221062, '《中华人民共和国退役军人保障法》', '第六十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第七章 褒扬激励', NULL, '县级以上地方人民政府负责地方志工作的机构应当将本行政区域内下列退役军人的名录和事迹，编辑录入地方志： （一）参战退役军人； （二）荣获二等功以上奖励的退役军人； （三）获得省部级或者战区级以上表彰的退役军人； （四）其他符合条件的退役军人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221063, '《中华人民共和国退役军人保障法》', '第六十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第七章 褒扬激励', NULL, '国家统筹规划烈士纪念设施建设，通过组织开展英雄烈士祭扫纪念活动等多种形式，弘扬英雄烈士精神。退役军人工作主管部门负责烈士纪念设施的修缮、保护和管理。 国家推进军人公墓建设。符合条件的退役军人去世后，可以安葬在军人公墓。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221064, '《中华人民共和国退役军人保障法》', '第六十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第八章 服务管理', NULL, '国家加强退役军人服务机构建设，建立健全退役军人服务体系。县级以上人民政府设立退役军人服务中心，乡镇、街道、农村和城市社区设立退役军人服务站点，提升退役军人服务保障能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221065, '《中华人民共和国退役军人保障法》', '第六十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第八章 服务管理', NULL, '退役军人服务中心、服务站点等退役军人服务机构应当加强与退役军人联系沟通，做好退役军人就业创业扶持、优抚帮扶、走访慰问、权益维护等服务保障工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221066, '《中华人民共和国退役军人保障法》', '第六十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第八章 服务管理', NULL, '县级以上人民政府退役军人工作主管部门应当加强退役军人思想政治教育工作，及时掌握退役军人的思想情况和工作生活状况，指导接收安置单位和其他组织做好退役军人的思想政治工作和有关保障工作。 接收安置单位和其他组织应当结合退役军人工作和生活状况，做好退役军人思想政治工作和有关保障工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221067, '《中华人民共和国退役军人保障法》', '第六十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第八章 服务管理', NULL, '县级以上人民政府退役军人工作主管部门、接收安置单位和其他组织应当加强对退役军人的保密教育和管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221068, '《中华人民共和国退役军人保障法》', '第六十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第八章 服务管理', NULL, '县级以上人民政府退役军人工作主管部门应当通过广播、电视、报刊、网络等多种渠道宣传与退役军人相关的法律法规和政策制度。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221069, '《中华人民共和国退役军人保障法》', '第七十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第八章 服务管理', NULL, '县级以上人民政府退役军人工作主管部门应当建立健全退役军人权益保障机制，畅通诉求表达渠道，为退役军人维护其合法权益提供支持和帮助。退役军人的合法权益受到侵害，应当依法解决。公共法律服务有关机构应当依法为退役军人提供法律援助等必要的帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221070, '《中华人民共和国退役军人保障法》', '第七十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第八章 服务管理', NULL, '县级以上人民政府退役军人工作主管部门应当依法指导、督促有关部门和单位做好退役安置、教育培训、就业创业、抚恤优待、褒扬激励、拥军优属等工作，监督检查退役军人保障相关法律法规和政策措施落实情况，推进解决退役军人保障工作中存在的问题。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221071, '《中华人民共和国退役军人保障法》', '第七十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第八章 服务管理', NULL, '国家实行退役军人保障工作责任制和考核评价制度。县级以上人民政府应当将退役军人保障工作完成情况，纳入对本级人民政府负责退役军人有关工作的部门及其负责人、下级人民政府及其负责人的考核评价内容。 对退役军人保障政策落实不到位、工作推进不力的地区和单位，由省级以上人民政府退役军人工作主管部门会同有关部门约谈该地区人民政府主要负责人或者该单位主要负责人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221072, '《中华人民共和国退役军人保障法》', '第七十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第八章 服务管理', NULL, '退役军人工作主管部门及其工作人员履行职责，应当自觉接受社会监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221073, '《中华人民共和国退役军人保障法》', '第七十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第八章 服务管理', NULL, '对退役军人保障工作中违反本法行为的检举、控告，有关机关和部门应当依法及时处理，并将处理结果告知检举人、控告人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221074, '《中华人民共和国退役军人保障法》', '第七十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第九章 法律责任', NULL, '退役军人工作主管部门及其工作人员有下列行为之一的，由其上级主管部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分： （一）未按照规定确定退役军人安置待遇的； （二）在退役军人安置工作中出具虚假文件的； （三）为不符合条件的人员发放退役军人优待证的； （四）挪用、截留、私分退役军人保障工作经费的； （五）违反规定确定抚恤优待对象、标准、数额或者给予退役军人相关待遇的； （六）在退役军人保障工作中利用职务之便为自己或者他人谋取私利的； （七）在退役军人保障工作中失职渎职的； （八）有其他违反法律法规行为的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221075, '《中华人民共和国退役军人保障法》', '第七十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第九章 法律责任', NULL, '其他负责退役军人有关工作的部门及其工作人员违反本法有关规定的，由其上级主管部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221076, '《中华人民共和国退役军人保障法》', '第七十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第九章 法律责任', NULL, '违反本法规定，拒绝或者无故拖延执行退役军人安置任务的，由安置地人民政府退役军人工作主管部门责令限期改正；逾期不改正的，予以通报批评。对该单位主要负责人和直接责任人员，由有关部门依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221077, '《中华人民共和国退役军人保障法》', '第七十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第九章 法律责任', NULL, '退役军人弄虚作假骗取退役相关待遇的，由县级以上地方人民政府退役军人工作主管部门取消相关待遇，追缴非法所得，并由其所在单位或者有关部门依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221078, '《中华人民共和国退役军人保障法》', '第七十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第九章 法律责任', NULL, '退役军人违法犯罪的，由省级人民政府退役军人工作主管部门按照国家有关规定中止、降低或者取消其退役相关待遇，报国务院退役军人工作主管部门备案。 退役军人对省级人民政府退役军人工作主管部门作出的中止、降低或者取消其退役相关待遇的决定不服的，可以依法申请行政复议或者提起行政诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221079, '《中华人民共和国退役军人保障法》', '第八十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第九章 法律责任', NULL, '违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221080, '《中华人民共和国退役军人保障法》', '第八十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第十章 附 则', NULL, '中国人民武装警察部队依法退出现役的警官、警士和义务兵等人员，适用本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221081, '《中华人民共和国退役军人保障法》', '第八十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第十章 附 则', NULL, '本法有关军官的规定适用于文职干部。 军队院校学员依法退出现役的，参照本法有关规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221082, '《中华人民共和国退役军人保障法》', '第八十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第十章 附 则', NULL, '参试退役军人参照本法有关参战退役军人的规定执行。 参战退役军人、参试退役军人的范围和认定标准、认定程序，由中央军事委员会有关部门会同国务院退役军人工作主管部门等部门规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221083, '《中华人民共和国退役军人保障法》', '第八十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第十章 附 则', NULL, '军官离职休养和军级以上职务军官退休后，按照国务院和中央军事委员会的有关规定安置管理。 本法施行前已经按照自主择业方式安置的退役军人的待遇保障，按照国务院和中央军事委员会的有关规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (221084, '《中华人民共和国退役军人保障法》', '第八十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2020-11-11', '第十章 附 则', NULL, '本法自2021年1月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222000, '《中华人民共和国母婴保健法》', '第一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第一章 总 则', NULL, '为了保障母亲和婴儿健康，提高出生人口素质，根据宪法，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222001, '《中华人民共和国母婴保健法》', '第二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第一章 总 则', NULL, '国家发展母婴保健事业，提供必要条 件和物质帮助，使母亲和婴儿获得医疗保健服务。 国家对边远贫困地区的母婴保健事业给予扶持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222002, '《中华人民共和国母婴保健法》', '第三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第一章 总 则', NULL, '各级人民政府领导母婴保健工作。 母婴保健事业应当纳入国民经济和社会发展计划。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222003, '《中华人民共和国母婴保健法》', '第四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第一章 总 则', NULL, '国务院卫生行政部门主管全国母婴保健工作，根据不同地区情况提出分级分类指导原则，并对全国母婴保健工作实施监督管理。 国务院其他有关部门在各自职责范围内，配合卫生行政部门做好母婴保健工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222004, '《中华人民共和国母婴保健法》', '第五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第一章 总 则', NULL, '国家鼓励、支持母婴保健领域的教育和科学研究，推广先进、实用的母婴保健技术，普及母婴保健科学知识。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222005, '《中华人民共和国母婴保健法》', '第六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第一章 总 则', NULL, '对在母婴保健工作中做出显著成绩和在母婴保健科学研究中取得显著成果的组织和个人，应当给予奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222006, '《中华人民共和国母婴保健法》', '第七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第二章 婚前保健', NULL, '医疗保健机构应当为公民提供婚前保健服务。 婚前保健服务包括下列内容： （一）婚前卫生指导：关于性卫生知识、生育知识和遗传病知识的教育； （二）婚前卫生咨询：对有关婚配、生育保健等问题提供医学意见； （三）婚前医学检查：对准备结婚的男女双方可能患影响结婚和生育的疾病进行医学检查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222007, '《中华人民共和国母婴保健法》', '第八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第二章 婚前保健', NULL, '婚前医学检查包括对下列疾病的检查： （一）严重遗传性疾病； （二）指定传染病； （三）有关精神病。 经婚前医学检查，医疗保健机构应当出具婚前医学检查证明。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222008, '《中华人民共和国母婴保健法》', '第九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第二章 婚前保健', NULL, '经婚前医学检查，对患指定传染病在传染期内或者有关精神病在发病期内的，医师应当提出医学意见；准备结婚的男女双方应当暂缓结婚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222009, '《中华人民共和国母婴保健法》', '第十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第二章 婚前保健', NULL, '经婚前医学检查，对诊断患医学上认为不宜生育的严重遗传性疾病的，医师应当向男女双方说明情况，提出医学意见；经男女双方同意，采取长效避孕措施或者施行结扎手术后不生育的，可以结婚。但《中华人民共和国婚姻法》规定禁止结婚的除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222010, '《中华人民共和国母婴保健法》', '第十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第二章 婚前保健', NULL, '接受婚前医学检查的人员对检查结果持有异议的，可以申请医学技术鉴定，取得医学鉴定证明。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222011, '《中华人民共和国母婴保健法》', '第十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第二章 婚前保健', NULL, '男女双方在结婚登记时，应当持有婚前医学检查证明或者医学鉴定证明。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222012, '《中华人民共和国母婴保健法》', '第十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第二章 婚前保健', NULL, '省、自治区、直辖市人民政府根据本地区的实际情况，制定婚前医学检查制度实施办法。 省、自治区、直辖市人民政府对婚前医学检查应当规定合理的收费标准，对边远贫困地区或者交费确有困难的人员应当给予减免。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222013, '《中华人民共和国母婴保健法》', '第十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 孕产期保健', NULL, '医疗保健机构应当为育龄妇女和孕产妇提供孕产期保健服务。 孕产期保健服务包括下列内容： （一）母婴保健指导：对孕育健康后代以及严重遗传性疾病和碘缺乏病等地方病的发病原因、治疗和预防方法提供医学意见； （二）孕妇、产妇保健：为孕妇、产妇提供卫生、营养、心理等方面的咨询和指导以及产前定期检查等医疗保健服务； （三）胎儿保健：为胎儿生长发育进行监护，提供咨询和医学指导； （四）新生儿保健：为新生儿生长发育、哺乳和护理提供医疗保健服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222014, '《中华人民共和国母婴保健法》', '第十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 孕产期保健', NULL, '对患严重疾病或者接触致畸物质，妊娠可能危及孕妇生命安全或者可能严重影响孕妇健康和胎儿正常发育的，医疗保健机构应当予以医学指导。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222015, '《中华人民共和国母婴保健法》', '第十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 孕产期保健', NULL, '医师发现或者怀疑患严重遗传性疾病的育龄夫妻，应当提出医学意见。育龄夫妻应当根据医师的医学意见采取相应的措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222016, '《中华人民共和国母婴保健法》', '第十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 孕产期保健', NULL, '经产前检查，医师发现或者怀疑胎儿异常的，应当对孕妇进行产前诊断。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222017, '《中华人民共和国母婴保健法》', '第十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 孕产期保健', NULL, '经产前诊断，有下列情形之一的，医师应当向夫妻双方说明情况，并提出终止妊娠的医学意见： （一）胎儿患严重遗传性疾病的； （二）胎儿有严重缺陷的； （三）因患严重疾病，继续妊娠可能危及孕妇生命安全或者严重危害孕妇健康的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222018, '《中华人民共和国母婴保健法》', '第十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 孕产期保健', NULL, '依照本法规定施行终止妊娠或者结扎手术，应当经本人同意，并签署意见。本人无行为能力的，应当经其监护人同意，并签署意见。 依照本法规定施行终止妊娠或者结扎手术的，接受免费服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222019, '《中华人民共和国母婴保健法》', '第二十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 孕产期保健', NULL, '生育过严重缺陷患儿的妇女再次妊娠前，夫妻双方应当到县级以上医疗保健机构接受医学检查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222020, '《中华人民共和国母婴保健法》', '第二十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 孕产期保健', NULL, '医师和助产人员应当严格遵守有关操作规程，提高助产技术和服务质量，预防和减少产伤。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222021, '《中华人民共和国母婴保健法》', '第二十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 孕产期保健', NULL, '不能住院分娩的孕妇应当由经过培训、具备相应接生能力的接生人员实行消毒接生。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222022, '《中华人民共和国母婴保健法》', '第二十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 孕产期保健', NULL, '医疗保健机构和从事家庭接生的人员按照国务院卫生行政部门的规定，出具统一制发的新生儿出生医学证明；有产妇和婴儿死亡以及新生儿出生缺陷情况的，应当向卫生行政部门报告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222023, '《中华人民共和国母婴保健法》', '第二十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 孕产期保健', NULL, '医疗保健机构为产妇提供科学育儿、合理营养和母乳喂养的指导。 医疗保健机构对婴儿进行体格检查和预防接种，逐步开展新生儿疾病筛查、婴儿多发病和常见病防治等医疗保健服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222024, '《中华人民共和国母婴保健法》', '第二十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第四章 技术鉴定', NULL, '县级以上地方人民政府可以设立医学技术鉴定组织，负责对婚前医学检查、遗传病诊断和产前诊断结果有异议的进行医学技术鉴定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222025, '《中华人民共和国母婴保健法》', '第二十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第四章 技术鉴定', NULL, '从事医学技术鉴定的人员，必须具有临床经验和医学遗传学知识，并具有主治医师以上的专业技术职务。 医学技术鉴定组织的组成人员，由卫生行政部门提名，同级人民政府聘任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222026, '《中华人民共和国母婴保健法》', '第二十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第四章 技术鉴定', NULL, '医学技术鉴定实行回避制度。凡与当事人有利害关系，可能影响公正鉴定的人员，应当回避。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222027, '《中华人民共和国母婴保健法》', '第二十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第五章 行政管理', NULL, '各级人民政府应当采取措施，加强母婴保健工作，提高医疗保健服务水平，积极防治由环境因素所致严重危害母亲和婴儿健康的地方性高发性疾病，促进母婴保健事业的发展。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222028, '《中华人民共和国母婴保健法》', '第二十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第五章 行政管理', NULL, '县级以上地方人民政府卫生行政部门管理本行政区域内的母婴保健工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222029, '《中华人民共和国母婴保健法》', '第三十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第五章 行政管理', NULL, '省、自治区、直辖市人民政府卫生行政部门指定的医疗保健机构负责本行政区域内的母婴保健监测和技术指导。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222030, '《中华人民共和国母婴保健法》', '第三十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第五章 行政管理', NULL, '医疗保健机构按照国务院卫生行政部门的规定，负责其职责范围内的母婴保健工作，建立医疗保健工作规范，提高医学技术水平，采取各种措施方便人民群众，做好母婴保健服务工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222031, '《中华人民共和国母婴保健法》', '第三十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第五章 行政管理', NULL, '医疗保健机构依照本法规定开展婚前医学检查、遗传病诊断、产前诊断以及施行结扎手术和终止妊娠手术的，必须符合国务院卫生行政部门规定的条件和技术标准，并经县级以上地方人民政府卫生行政部门许可。 严禁采用技术手段对胎儿进行性别鉴定，但医学上确有需要的除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222032, '《中华人民共和国母婴保健法》', '第三十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第五章 行政管理', NULL, '从事本法规定的遗传病诊断、产前诊断的人员，必须经过省、自治区、直辖市人民政府卫生行政部门的考核，并取得相应的合格证书。 从事本法规定的婚前医学检查、施行结扎手术和终止妊娠手术的人员，必须经过县级以上地方人民政府卫生行政部门的考核，并取得相应的合格证书。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222033, '《中华人民共和国母婴保健法》', '第三十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第五章 行政管理', NULL, '从事母婴保健工作的人员应当严格遵守职业道德，为当事人保守秘密。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222034, '《中华人民共和国母婴保健法》', '第三十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第六章 法律责任', NULL, '未取得国家颁发的有关合格证书的，有下列行为之一，县级以上地方人民政府卫生行政部门应当予以制止，并可以根据情节给予警告或者处以罚款： （一）从事婚前医学检查、遗传病诊断、产前诊断或者医学技术鉴定的； （二）施行终止妊娠手术的； （三）出具本法规定的有关医学证明的。 上款第（三）项出具的有关医学证明无效。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222035, '《中华人民共和国母婴保健法》', '第三十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第六章 法律责任', NULL, '未取得国家颁发的有关合格证书，施行终止妊娠手术或者采取其他方法终止妊娠，致人死亡、残疾、丧失或者基本丧失劳动能力的，依照刑法有关规定追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222036, '《中华人民共和国母婴保健法》', '第三十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第六章 法律责任', NULL, '从事母婴保健工作的人员违反本法规定，出具有关虚假医学证明或者进行胎儿性别鉴定的，由医疗保健机构或者卫生行政部门根据情节给予行政处分；情节严重的，依法取消执业资格。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222037, '《中华人民共和国母婴保健法》', '第三十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第七章 附 则', NULL, '本法下列用语的含义： 指定传染病，是指《中华人民共和国传染病防治法》中规定的艾滋病、淋病、梅毒、麻疯病以及医学上认为影响结婚和生育的其他传染病。 严重遗传性疾病，是指由于遗传因素先天形成，患者全部或者部分丧失自主生活能力，后代再现风险高，医学上认为不宜生育的遗传性疾病。 有关精神病，是指精神分裂症、躁狂抑郁型精神病以及其他重型精神病。 产前诊断，是指对胎儿进行先天性缺陷和遗传性疾病的诊断。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (222038, '《中华人民共和国母婴保健法》', '第三十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第七章 附 则', NULL, '本法自1995年6月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223000, '《中华人民共和国归侨侨眷权益保护法》', '第一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '为了保护归侨、侨眷的合法的权利和利益，根据宪法，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223001, '《中华人民共和国归侨侨眷权益保护法》', '第二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '归侨是指回国定居的华侨。华侨是指定居在国外的中国公民。 侨眷是指华侨、归侨在国内的眷属。 本法所称侨眷包括：华侨、归侨的配偶，父母，子女及其配偶，兄弟姐妹，祖父母、外祖父母，孙子女、外孙子女，以及同华侨、归侨有长期扶养关系的其他亲属。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223002, '《中华人民共和国归侨侨眷权益保护法》', '第三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '归侨、侨眷享有宪法和法律规定的公民的权利，并履行宪法和法律规定的公民的义务，任何组织或者个人不得歧视。 国家根据实际情况和归侨、侨眷的特点，给予适当照顾，具体办法由国务院或者国务院有关主管部门规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223003, '《中华人民共和国归侨侨眷权益保护法》', '第四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '县级以上各级人民政府及其负责侨务工作的机构，组织协调有关部门做好保护归侨、侨眷的合法权益的工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223004, '《中华人民共和国归侨侨眷权益保护法》', '第五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '国家对回国定居的华侨给予安置。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223005, '《中华人民共和国归侨侨眷权益保护法》', '第六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '全国人民代表大会和归侨人数较多地区的地方人民代表大会应当有适当名额的归侨代表。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223006, '《中华人民共和国归侨侨眷权益保护法》', '第七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '归侨、侨眷有权依法申请成立社会团体，进行适合归侨、侨眷需要的合法的社会活动。 归侨、侨眷依法成立的社会团体的财产受法律保护，任何组织或者个人不得侵犯。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223007, '《中华人民共和国归侨侨眷权益保护法》', '第八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '中华全国归国华侨联合会和地方归国华侨联合会代表归侨、侨眷的利益，依法维护归侨、侨眷的合法权益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223008, '《中华人民共和国归侨侨眷权益保护法》', '第九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '国家对安置归侨的农场、林场等企业给予扶持，任何组织或者个人不得侵占其合法使用的土地，不得侵犯其合法权益。 在安置归侨的农场、林场等企业所在的地方，可以根据需要合理设置学校和医疗保健机构，国家在人员、设备、经费等方面给予扶助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223009, '《中华人民共和国归侨侨眷权益保护法》', '第十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '国家依法维护归侨、侨眷职工的社会保障权益。用人单位及归侨、侨眷职工应当依法参加当地的社会保险，缴纳社会保险费用。 对丧失劳动能力又无经济来源或者生活确有困难的归侨、侨眷，当地人民政府应当给予救济。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223010, '《中华人民共和国归侨侨眷权益保护法》', '第十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '国家鼓励和引导归侨、侨眷依法投资兴办产业，特别是兴办高新技术企业，各级人民政府应当给予支持，其合法权益受法律保护。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223011, '《中华人民共和国归侨侨眷权益保护法》', '第十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '归侨、侨眷在国内兴办公益事业，各级人民政府应当给予支持，其合法权益受法律保护。 归侨、侨眷境外亲友捐赠的物资用于国内公益事业的，依照法律、行政法规的规定减征或者免征关税和进口环节的增值税。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223012, '《中华人民共和国归侨侨眷权益保护法》', '第十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '国家依法保护归侨、侨眷在国内私有房屋的所有权。 依法征收、征用、拆迁归侨、侨眷私有房屋的，建设单位应当按照国家有关规定给予合理补偿和妥善安置。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223013, '《中华人民共和国归侨侨眷权益保护法》', '第十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '各级人民政府应当对归侨、侨眷就业给予照顾，提供必要的指导和服务。 归侨学生、归侨子女和华侨在国内的子女升学，按照国家有关规定给予照顾。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223014, '《中华人民共和国归侨侨眷权益保护法》', '第十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '国家保护归侨、侨眷的侨汇收入。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223015, '《中华人民共和国归侨侨眷权益保护法》', '第十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '归侨、侨眷有权接受境外亲友的遗赠或者赠与。 归侨、侨眷继承境外遗产的权益受法律保护。 归侨、侨眷有权处分其在境外的财产。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223016, '《中华人民共和国归侨侨眷权益保护法》', '第十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '归侨、侨眷与境外亲友的往来和通讯受法律保护。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223017, '《中华人民共和国归侨侨眷权益保护法》', '第十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '归侨、侨眷申请出境，有关主管部门应当在规定期限内办理手续。 归侨、侨眷确因境外直系亲属病危、死亡或者限期处理境外财产等特殊情况急需出境的，有关主管部门应当根据申请人提供的有效证明优先办理手续。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223018, '《中华人民共和国归侨侨眷权益保护法》', '第十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '国家保障归侨、侨眷出境探亲的权利。 归侨、侨眷职工按照国家有关规定享受出境探亲的待遇。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223019, '《中华人民共和国归侨侨眷权益保护法》', '第二十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '归侨、侨眷可以按照国家有关规定申请出境定居，经批准出境定居的，任何组织或者个人不得损害其合法权益。 离休、退休、退职的归侨、侨眷职工出境定居的，其离休金、退休金、退职金、养老金照发。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223020, '《中华人民共和国归侨侨眷权益保护法》', '第二十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '归侨、侨眷申请自费出境学习、讲学的，或者因经商出境的，其所在单位和有关部门应当提供便利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223021, '《中华人民共和国归侨侨眷权益保护法》', '第二十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '国家对归侨、侨眷在境外的正当权益，根据中华人民共和国缔结或者参加的国际条约或者国际惯例，给予保护。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223022, '《中华人民共和国归侨侨眷权益保护法》', '第二十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '归侨、侨眷合法权益受到侵害时，被侵害人有权要求有关主管部门依法处理，或者向人民法院提起诉讼。归国华侨联合会应当给予支持和帮助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223023, '《中华人民共和国归侨侨眷权益保护法》', '第二十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '国家机关工作人员玩忽职守或者滥用职权，致使归侨、侨眷合法权益受到损害的，其所在单位或者上级主管机关应当责令改正或者给予行政处分；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223024, '《中华人民共和国归侨侨眷权益保护法》', '第二十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '任何组织或者个人侵害归侨、侨眷的合法权益，造成归侨、侨眷财产损失或者其他损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223025, '《中华人民共和国归侨侨眷权益保护法》', '第二十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '违反本法第九条第一款规定，非法占用安置归侨的农场、林场合法使用的土地，有关主管部门应当责令退还；造成损失的，依法承担赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223026, '《中华人民共和国归侨侨眷权益保护法》', '第二十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '违反本法第十三条规定，非法侵占归侨、侨眷在国内私有房屋的，有关主管部门应当责令退还；造成损失的，依法承担赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223027, '《中华人民共和国归侨侨眷权益保护法》', '第二十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '违反本法第二十条第二款规定，停发、扣发、侵占或者挪用出境定居的归侨、侨眷的离休金、退休金、退职金、养老金的，有关单位或者有关主管部门应当责令补发，并依法给予赔偿；对直接负责的主管人员和其他直接责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223028, '《中华人民共和国归侨侨眷权益保护法》', '第二十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '国务院根据本法制定实施办法。 省、自治区、直辖市的人民代表大会常务委员会可以根据本法和国务院的实施办法，制定实施办法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (223029, '《中华人民共和国归侨侨眷权益保护法》', '第三十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2009-08-27', NULL, NULL, '本法自1991年1月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224000, '《中华人民共和国科学技术普及法》', '第一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第一章 总 则', NULL, '为了实施科教兴国战略、人才强国战略和创新驱动发展战略，全面促进科学技术普及，加强国家科学技术普及能力建设，提高公民的科学文化素质，推进实现高水平科技自立自强，推动经济发展和社会进步，根据宪法，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224001, '《中华人民共和国科学技术普及法》', '第二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第一章 总 则', NULL, '本法适用于国家和社会普及科学技术知识、倡导科学方法、传播科学思想、弘扬科学精神的活动。 开展科学技术普及（以下简称科普），应当采取公众易于接触、理解、接受、参与的方式。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224002, '《中华人民共和国科学技术普及法》', '第三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第一章 总 则', NULL, '坚持中国共产党对科普事业的全面领导。 开展科普，应当以人民为中心，坚持面向世界科技前沿、面向经济主战场、面向国家重大需求、面向人民生命健康，培育和弘扬创新文化，推动形成崇尚科学、追求创新的风尚，服务高质量发展，为建设科技强国奠定坚实基础。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224003, '《中华人民共和国科学技术普及法》', '第四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第一章 总 则', NULL, '科普是国家创新体系的重要组成部分，是实现创新发展的基础性工作。国家把科普放在与科技创新同等重要的位置，加强科普工作总体布局、统筹部署，推动科普与科技创新紧密协同，充分发挥科普在一体推进教育科技人才事业发展中的作用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224004, '《中华人民共和国科学技术普及法》', '第五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第一章 总 则', NULL, '科普是公益事业，是社会主义物质文明和精神文明建设的重要内容。发展科普事业是国家的长期任务，国家推动科普全面融入经济、政治、文化、社会、生态文明建设，构建政府、社会、市场等协同推进的科普发展格局。 国家加强农村的科普工作，扶持革命老区、民族地区、边疆地区、经济欠发达地区的科普工作，建立完善跨区域科普合作和共享机制，促进铸牢中华民族共同体意识，推进乡村振兴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224005, '《中华人民共和国科学技术普及法》', '第六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第一章 总 则', NULL, '科普工作应当践行社会主义核心价值观，弘扬科学精神和科学家精神，遵守科技伦理，反对和抵制伪科学。 任何组织和个人不得以科普为名从事损害国家利益、社会公共利益或者他人合法权益的活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224006, '《中华人民共和国科学技术普及法》', '第七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第一章 总 则', NULL, '国家机关、武装力量、社会团体、企业事业单位、基层群众性自治组织及其他组织应当开展科普工作，可以通过多种形式广泛开展科普活动。 每年9月为全国科普月。 公民有参与科普活动的权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224007, '《中华人民共和国科学技术普及法》', '第八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第一章 总 则', NULL, '国家保护科普组织和科普人员的合法权益，鼓励科普组织和科普人员自主开展科普活动，依法兴办科普事业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224008, '《中华人民共和国科学技术普及法》', '第九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第一章 总 则', NULL, '国家支持社会力量兴办科普事业。社会力量兴办科普事业可以按照市场机制运行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224009, '《中华人民共和国科学技术普及法》', '第十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第一章 总 则', NULL, '科普工作应当坚持群众性、社会性和经常性，结合实际，因地制宜，采取多种方式。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224010, '《中华人民共和国科学技术普及法》', '第十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第一章 总 则', NULL, '国家实施全民科学素质行动，制定全民科学素质行动规划，引导公民培育科学和理性思维，树立科学的世界观和方法论，养成文明、健康、绿色、环保的科学生活方式，提高劳动、生产、创新创造的技能。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224011, '《中华人民共和国科学技术普及法》', '第十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第一章 总 则', NULL, '国家支持和促进科普对外合作与交流。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224012, '《中华人民共和国科学技术普及法》', '第十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第一章 总 则', NULL, '对在科普工作中做出突出贡献的组织和个人，按照国家有关规定给予表彰、奖励。 国家鼓励社会力量依法设立科普奖项。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224013, '《中华人民共和国科学技术普及法》', '第十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第二章 组织管理', NULL, '各级人民政府领导科普工作，应当将科普工作纳入国民经济和社会发展相关规划，为开展科普工作创造良好的环境和条件。 县级以上人民政府应当建立科普工作协调制度。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224014, '《中华人民共和国科学技术普及法》', '第十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第二章 组织管理', NULL, '国务院科学技术行政部门负责制定全国科普工作规划，实行政策引导，进行督促检查，加强统筹协调，推动科普工作发展。 国务院其他部门按照各自的职责分工，负责有关的科普工作。 县级以上地方人民政府科学技术行政部门及其他部门在同级人民政府领导下按照各自的职责分工，负责本地区有关的科普工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224015, '《中华人民共和国科学技术普及法》', '第十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第二章 组织管理', NULL, '行业主管部门应当结合本行业特点和实际情况，组织开展相关科普活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224016, '《中华人民共和国科学技术普及法》', '第十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第二章 组织管理', NULL, '科学技术协会是科普工作的主要社会力量，牵头实施全民科学素质行动，组织开展群众性、社会性和经常性的科普活动，加强国际科技人文交流，支持有关组织和企业事业单位开展科普活动，协助政府制定科普工作规划，为政府科普工作决策提供建议和咨询服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224017, '《中华人民共和国科学技术普及法》', '第十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第二章 组织管理', NULL, '工会、共产主义青年团、妇女联合会等群团组织应当结合各自工作对象的特点组织开展科普活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224018, '《中华人民共和国科学技术普及法》', '第十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第三章 社会责任', NULL, '科普是全社会的共同责任。社会各界都应当组织、参加各类科普活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224019, '《中华人民共和国科学技术普及法》', '第二十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第三章 社会责任', NULL, '各级各类学校及其他教育机构，应当把科普作为素质教育的重要内容，加强科学教育，提升师生科学文化素质，支持和组织师生开展多种形式的科普活动。 高等学校应当发挥科教资源优势，开设科技相关通识课程，开展科研诚信和科技伦理教育，把科普纳入社会服务职能，提供必要保障。 中小学校、特殊教育学校应当利用校内、校外资源，提高科学教育质量，完善科学教育课程和实践活动，激发学生对科学的兴趣，培养科学思维、创新意识和创新能力。 学前教育机构应当根据学前儿童年龄特点和身心发展规律，加强科学启蒙教育，培育、保护好奇心和探索意识。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224020, '《中华人民共和国科学技术普及法》', '第二十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第三章 社会责任', NULL, '开放大学、老年大学、老年科技大学、社区学院等应当普及卫生健康、网络通信、智能技术、应急安全等知识技能，提升老年人、残疾人等群体信息获取、识别和应用等能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224021, '《中华人民共和国科学技术普及法》', '第二十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第三章 社会责任', NULL, '科学研究和技术开发机构、高等学校应当支持和组织科学技术人员、教师开展科普活动，有条件的可以设置专职科普岗位和专门科普场所，使科普成为机构运行的重要内容，为开展科普活动提供必要的支持和保障，促进科技研发、科技成果转化与科普紧密结合。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224022, '《中华人民共和国科学技术普及法》', '第二十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第三章 社会责任', NULL, '科技企业应当把科普作为履行社会责任的重要内容，结合科技创新和职工技能培训面向公众开展科普活动。 鼓励企业将自身科技资源转化为科普资源，向公众开放实验室、生产线等科研、生产设施，有条件的可以设立向公众开放的科普场馆和设施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224023, '《中华人民共和国科学技术普及法》', '第二十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第三章 社会责任', NULL, '自然科学和社会科学类社会团体等应当组织开展专业领域科普活动，促进科学技术的普及推广。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224024, '《中华人民共和国科学技术普及法》', '第二十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第三章 社会责任', NULL, '新闻出版、电影、广播电视、文化、互联网信息服务等机构和团体应当发挥各自优势做好科普宣传工作。 综合类报纸、期刊、广播电台、电视台应当开展公益科普宣传；电影、广播电视生产、发行和播映机构应当加强科普作品的制作、发行和播映；书刊出版、发行机构应当扶持科普书刊的出版、发行；综合性互联网平台应当开设科普网页或者科普专区。 鼓励组织和个人利用新兴媒体开展多种形式的科普，拓展科普渠道和手段。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224025, '《中华人民共和国科学技术普及法》', '第二十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第三章 社会责任', NULL, '农村基层群众性自治组织协助当地人民政府根据当地经济与社会发展的需要，围绕科学生产、文明健康生活，发挥农村科普组织、农村学校、基层医疗卫生机构等作用，开展科普工作，提升农民科学文化素质。 各类农村经济组织、农业科研和技术推广机构、农民教育培训机构、农村专业技术协（学）会以及科技特派员等，应当开展农民科技培训和农业科技服务，结合推广先进适用技术和科技成果转化应用向农民普及科学技术。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224026, '《中华人民共和国科学技术普及法》', '第二十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第三章 社会责任', NULL, '城市基层群众性自治组织协助当地人民政府利用当地科技、教育、文化、旅游、医疗卫生等资源，结合居民的生活、学习等需要开展科普活动，完善社区综合服务设施科普功能，提高科普服务质量和水平。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224027, '《中华人民共和国科学技术普及法》', '第二十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第三章 社会责任', NULL, '科技馆（站）、科技活动中心和其他科普教育基地，应当组织开展科普教育活动。图书馆、博物馆、文化馆、规划展览馆等文化场所应当发挥科普教育的作用。 公园、自然保护地、风景名胜区、商场、机场、车站、码头等各类公共场所以及重大基础设施的经营管理单位，应当在所辖范围内加强科普宣传。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224028, '《中华人民共和国科学技术普及法》', '第二十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第四章 科普活动', NULL, '国家支持科普产品和服务研究开发，鼓励新颖、独创、科学性强的高质量科普作品创作，提升科普原创能力，依法保护科普成果知识产权。 鼓励科学研究和技术开发机构、高等学校、企业等依托现有资源并根据发展需要建设科普创作中心。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224029, '《中华人民共和国科学技术普及法》', '第三十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第四章 科普活动', NULL, '国家发展科普产业，鼓励兴办科普企业，促进科普与文化、旅游、体育、卫生健康、农业、生态环保等产业融合发展。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224030, '《中华人民共和国科学技术普及法》', '第三十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第四章 科普活动', NULL, '国家推动新技术、新知识在全社会各类人群中的传播与推广，鼓励各类创新主体围绕新技术、新知识开展科普，鼓励在科普中应用新技术，引导社会正确认识和使用科技成果，为科技成果应用创造良好环境。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224031, '《中华人民共和国科学技术普及法》', '第三十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第四章 科普活动', NULL, '国家部署实施新技术领域重大科技任务，在符合保密法律法规的前提下，可以组织开展必要的科普，增进公众理解、认同和支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224032, '《中华人民共和国科学技术普及法》', '第三十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第四章 科普活动', NULL, '国家加强自然灾害、事故灾难、公共卫生事件等突发事件预防、救援、应急处置等方面的科普工作，加强应急科普资源和平台建设，完善应急科普响应机制，提升公众应急处理能力和自我保护意识。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224033, '《中华人民共和国科学技术普及法》', '第三十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第四章 科普活动', NULL, '国家鼓励在职业培训、农民技能培训和干部教育培训中增加科普内容，促进培育高素质产业工人和农民，提高公职人员科学履职能力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224034, '《中华人民共和国科学技术普及法》', '第三十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第四章 科普活动', NULL, '组织和个人提供的科普产品和服务、发布的科普信息应当具有合法性、科学性，不得有虚假错误的内容。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224035, '《中华人民共和国科学技术普及法》', '第三十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第四章 科普活动', NULL, '国家加强对科普信息发布和传播的监测与评估。对传播范围广、社会危害大的虚假错误信息，科学技术或者有关主管部门应当按照职责分工及时予以澄清和纠正。 网络服务提供者发现用户传播虚假错误信息的，应当立即采取处置措施，防止信息扩散。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224036, '《中华人民共和国科学技术普及法》', '第三十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第四章 科普活动', NULL, '有条件的科普组织和科学技术人员应当结合自身专业特色组织、参与国际科普活动，开展国际科技人文交流，拓展国际科普合作渠道，促进优秀科普成果共享。国家支持开展青少年国际科普交流。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224037, '《中华人民共和国科学技术普及法》', '第三十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第四章 科普活动', NULL, '国家完善科普工作评估体系和公民科学素质监测评估体系，开展科普调查统计和公民科学素质测评，监测和评估科普事业发展成效。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224038, '《中华人民共和国科学技术普及法》', '第三十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第五章 科普人员', NULL, '国家加强科普工作人员培训和交流，提升科普工作人员思想道德品质、科学文化素质和业务水平，建立专业化科普工作人员队伍。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224039, '《中华人民共和国科学技术普及法》', '第四十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第五章 科普人员', NULL, '科学技术人员和教师应当发挥自身优势和专长，积极参与和支持科普活动。 科技领军人才和团队应当发挥表率作用，带头开展科普。 鼓励和支持老年科学技术人员积极参与科普工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224040, '《中华人民共和国科学技术普及法》', '第四十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第五章 科普人员', NULL, '国家支持有条件的高等学校、职业学校设置和完善科普相关学科和专业，培养科普专业人才。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224041, '《中华人民共和国科学技术普及法》', '第四十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第五章 科普人员', NULL, '国家完善科普志愿服务制度和工作体系，支持志愿者开展科普志愿服务，加强培训与监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224042, '《中华人民共和国科学技术普及法》', '第四十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第五章 科普人员', NULL, '国家健全科普人员评价、激励机制，鼓励相关单位建立符合科普特点的职称评定、绩效考核等评价制度，为科普人员提供有效激励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224043, '《中华人民共和国科学技术普及法》', '第四十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第六章 保障措施', NULL, '各级人民政府应当将科普经费列入本级预算，完善科普投入经费保障机制，逐步提高科普投入水平，保障科普工作顺利开展。 各级人民政府有关部门应当根据需要安排经费支持科普工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224044, '《中华人民共和国科学技术普及法》', '第四十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第六章 保障措施', NULL, '国家完善科普场馆和科普基地建设布局，扩大科普设施覆盖面，促进城乡科普设施均衡发展。 国家鼓励有条件的地方和组织建设综合型科普场馆和专业型科普场馆，发展数字科普场馆，推进科普信息化发展，加强与社区建设、文化设施融合发展。 省、自治区、直辖市人民政府和其他有条件的地方人民政府，应当将科普场馆、设施建设纳入国土空间规划；对现有科普场馆、设施应当加强利用、维修和改造升级。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224045, '《中华人民共和国科学技术普及法》', '第四十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第六章 保障措施', NULL, '各级人民政府应当对符合规划的科普场馆、设施建设给予支持，开展财政性资金资助的科普场馆运营绩效评估，保障科普场馆有效运行。 政府投资建设的科普场馆，应当配备必要的专职人员，常年向公众开放，对青少年实行免费或者优惠，并不得擅自改为他用；经费困难的，政府可以根据需要予以补贴，使其正常运行。 尚无条件建立科普场馆的地方，应当利用现有的科技、教育、文化、旅游、医疗卫生、体育、交通运输、应急等设施开展科普，并设立科普画廊、橱窗等。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224046, '《中华人民共和国科学技术普及法》', '第四十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第六章 保障措施', NULL, '国家建设完善开放、共享的国家科普资源库和科普资源公共服务平台，推动全社会科普资源共建共享。 利用财政性资金设立的科学研究和技术开发机构、高等学校、职业学校，有条件的应当向公众开放科技基础设施和科技资源，为公众了解、认识、参与科学研究活动提供便利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224047, '《中华人民共和国科学技术普及法》', '第四十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第六章 保障措施', NULL, '国家鼓励和引导社会资金投入科普事业。国家鼓励境内外的组织和个人设立科普基金，用于资助科普事业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224048, '《中华人民共和国科学技术普及法》', '第四十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第六章 保障措施', NULL, '国家鼓励境内外的组织和个人依法捐赠财产资助科普事业；对捐赠财产用于科普事业或者投资建设科普场馆、设施的，依法给予优惠。 科普组织开展科普活动、兴办科普事业，可以依法获得资助和捐赠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224049, '《中华人民共和国科学技术普及法》', '第五十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第六章 保障措施', NULL, '国家依法对科普事业实行税收优惠。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224050, '《中华人民共和国科学技术普及法》', '第五十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第六章 保障措施', NULL, '利用财政性资金设立科学技术计划项目，除涉密项目外，应当结合任务需求，合理设置科普工作任务，充分发挥社会效益。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224051, '《中华人民共和国科学技术普及法》', '第五十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第六章 保障措施', NULL, '科学研究和技术开发机构、学校、企业的主管部门以及科学技术等相关行政部门应当支持开展科普活动，建立有利于促进科普的评价标准和制度机制。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224052, '《中华人民共和国科学技术普及法》', '第五十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第六章 保障措施', NULL, '科普经费和组织、个人资助科普事业的财产，应当用于科普事业，任何组织和个人不得克扣、截留、挪用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224053, '《中华人民共和国科学技术普及法》', '第五十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第七章 法律责任', NULL, '违反本法规定，制作、发布、传播虚假错误信息，或者以科普为名损害国家利益、社会公共利益或者他人合法权益的，由有关主管部门责令改正，给予警告或者通报批评，没收违法所得，对负有责任的领导人员和直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224054, '《中华人民共和国科学技术普及法》', '第五十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第七章 法律责任', NULL, '违反本法规定，克扣、截留、挪用科普款物或者骗取科普优惠政策支持的，由有关主管部门责令限期退还相关款物；对负有责任的领导人员和直接责任人员依法给予处分；情节严重的，禁止一定期限内申请科普优惠政策支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224055, '《中华人民共和国科学技术普及法》', '第五十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第七章 法律责任', NULL, '擅自将政府投资建设的科普场馆改为他用的，由有关主管部门责令限期改正；情节严重的，给予警告或者通报批评，对负有责任的领导人员和直接责任人员依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224056, '《中华人民共和国科学技术普及法》', '第五十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第七章 法律责任', NULL, '骗取科普表彰、奖励的，由授予表彰、奖励的部门或者单位撤销其所获荣誉，收回奖章、证书，追回其所获奖金等物质奖励，并由其所在单位或者有关部门依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224057, '《中华人民共和国科学技术普及法》', '第五十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第七章 法律责任', NULL, '公职人员在科普工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224058, '《中华人民共和国科学技术普及法》', '第五十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第七章 法律责任', NULL, '违反本法规定，造成人身损害或者财产损失的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (224059, '《中华人民共和国科学技术普及法》', '第六十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2024-12-25', '第八章 附 则', NULL, '本法自公布之日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225000, '《中华人民共和国社会救助法》', '第一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第一章 总 则', NULL, '为了保障公民基本生活，让人民共享改革发展成果，健全社会救助体系，促进社会公平，维护社会和谐稳定，根据宪法，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225001, '《中华人民共和国社会救助法》', '第二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第一章 总 则', NULL, '国家建立和完善社会救助制度，依法保障公民从国家和社会获得物质帮助和救助服务的权利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225002, '《中华人民共和国社会救助法》', '第三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第一章 总 则', NULL, '社会救助坚持中国共产党的领导，坚持以人民为中心，践行全心全意为人民服务的宗旨。 社会救助坚持城乡统筹，坚持尽力而为、量力而行，坚持保基本、兜底线、救急难、可持续，坚持与其他社会保障制度相衔接，坚持与经济社会发展相适应。 社会救助工作遵循公开、公平、公正、便民、及时的原则。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225003, '《中华人民共和国社会救助法》', '第四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第一章 总 则', NULL, '社会救助实行党委领导、政府负责、民政牵头、部门协同、社会参与的工作机制。 县级以上人民政府建立社会救助协调机制，统筹、协调、督促、指导有关部门在各自职责范围内做好社会救助工作。协调机制具体工作由县级以上人民政府民政部门承担。 县级以上人民政府民政、教育、人力资源社会保障、住房城乡建设、卫生健康、应急管理、医疗保障等部门（以下统称社会救助管理部门），按照各自职责负责相应的社会救助工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225004, '《中华人民共和国社会救助法》', '第五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第一章 总 则', NULL, '乡镇人民政府、街道办事处依法做好社会救助受理、审核、动态管理等工作。 村民委员会、居民委员会依法协助做好入户走访、社会救助申请等工作。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225005, '《中华人民共和国社会救助法》', '第六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第一章 总 则', NULL, '县级以上人民政府应当将社会救助工作列入国民经济和社会发展规划。 地方各级人民政府应当结合经济社会发展水平和财力状况合理安排社会救助资金，实施预算绩效管理，资金支付按照国库集中支付管理有关规定执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225006, '《中华人民共和国社会救助法》', '第七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第一章 总 则', NULL, '国家鼓励和支持公民、法人及其他组织依法参与社会救助。 工会、共产主义青年团、妇女联合会、残疾人联合会、红十字会等组织应当按照职责或者章程参与社会救助，开展救助帮扶活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225007, '《中华人民共和国社会救助法》', '第八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第一章 总 则', NULL, '各级人民政府、县级以上人民政府社会救助管理部门和村民委员会、居民委员会，应当通过各种形式，开展社会救助法律、法规、规章和政策的宣传。 报刊、广播、电视等新闻媒体和网络服务提供者应当加强社会救助公益宣传。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225008, '《中华人民共和国社会救助法》', '第九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第一章 总 则', NULL, '各级人民政府应当采取措施，鼓励、支持和引导有劳动能力的社会救助对象自助自立、解困脱困。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225009, '《中华人民共和国社会救助法》', '第十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第一章 总 则', NULL, '国家推进社会救助信息化工作，加强低收入人口动态监测信息平台建设，实现对低收入人口的精准识别和常态化救助帮扶，提升社会救助管理服务能力和水平。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225010, '《中华人民共和国社会救助法》', '第十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第一章 总 则', NULL, '社会救助工作应当依法保护个人隐私和个人信息。 有关单位和人员处理个人信息应当遵循合法、正当、必要原则，采取有效措施保障个人信息安全，对在社会救助工作中知悉的个人信息等，应当依法予以保密。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225011, '《中华人民共和国社会救助法》', '第十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第一章 总 则', NULL, '对在社会救助工作中做出显著成绩的单位和个人，按照国家有关规定给予表彰、奖励。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225012, '《中华人民共和国社会救助法》', '第十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '社会救助对象包括特困人员、最低生活保障家庭、最低生活保障边缘家庭、刚性支出困难家庭、受灾人员、基本生活暂时出现严重困难的人员、需要疾病应急救助人员以及生活无着的流散人员等。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225013, '《中华人民共和国社会救助法》', '第十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '国家建立健全分层分类的社会救助体系，科学认定社会救助对象，根据救助对象类型、困难程度等及时有针对性地给予社会救助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225014, '《中华人民共和国社会救助法》', '第十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '社会救助分为基本生活救助、专项社会救助和急难社会救助。 基本生活救助包括特困人员供养和最低生活保障。 专项社会救助包括医疗救助、教育救助、住房救助、就业救助、受灾人员救助。 急难社会救助包括临时救助、疾病应急救助、生活无着的流散人员救助。 县级以上人民政府可以结合实际，增加相应的社会救助帮扶措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225015, '《中华人民共和国社会救助法》', '第十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '对无劳动能力、无生活来源且无法定赡养、抚养、扶养义务人，或者其法定义务人无履行义务能力的老年人、未成年人、残疾人等特困人员，由社会救助管理部门给予特困人员供养，提供基本生活条件、必要的照料服务、疾病治疗，办理丧葬事宜等。 特困人员可以在供养服务机构集中供养，也可以在家分散供养。特困人员可以自行选择供养形式。 特困人员中的未成年人年满十八周岁后，仍在义务教育或者高中阶段教育（含中等职业教育）阶段就学的，继续予以供养。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225016, '《中华人民共和国社会救助法》', '第十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '特困人员供养的基本生活标准和照料护理标准，由省、自治区、直辖市人民政府或者设区的市级人民政府确定并公布。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225017, '《中华人民共和国社会救助法》', '第十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '对家庭人均收入低于当地最低生活保障标准且财产状况符合规定的最低生活保障家庭，由社会救助管理部门给予最低生活保障，按月发放最低生活保障金。 最低生活保障金可以按照家庭人均收入低于当地最低生活保障标准的实际差额发放，也可以分档定额发放。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225018, '《中华人民共和国社会救助法》', '第十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '省、自治区、直辖市人民政府根据当地经济社会发展状况和人民生活水平，综合考虑居民人均消费支出或者人均可支配收入等因素，制定并适时调整本行政区域内最低生活保障标准或者最低生活保障指导标准。省、自治区、直辖市人民政府制定最低生活保障指导标准的，设区的市级人民政府可以制定本行政区域内最低生活保障标准，所制定标准不得低于本省、自治区、直辖市人民政府制定的最低生活保障指导标准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225019, '《中华人民共和国社会救助法》', '第二十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '对领取最低生活保障金后生活仍有特殊困难的老年人、未成年人、重度残疾人、重病患者等，县级以上地方人民政府应当采取措施给予必要的生活保障。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225020, '《中华人民共和国社会救助法》', '第二十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '对家庭人均收入低于当地最低生活保障边缘家庭标准且财产状况符合规定的最低生活保障边缘家庭，由社会救助管理部门根据实际需要给予相应的医疗、教育、住房、就业等社会救助。 对最低生活保障边缘家庭中的重度残疾人、重病患者以及确有特殊困难人员，可以纳入最低生活保障范围，按月发放最低生活保障金。 省、自治区、直辖市人民政府根据当地经济社会发展状况和人民生活水平，在当地最低生活保障标准或者最低生活保障指导标准的基础上，上浮一定比例确定最低生活保障边缘家庭标准或者最低生活保障边缘家庭指导标准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225021, '《中华人民共和国社会救助法》', '第二十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '对家庭人均收入低于上年度当地居民人均可支配收入，财产状况符合当地规定，且医疗、教育等必需支出占家庭总收入比例超过所在地设区的市级以上地方人民政府规定比例的刚性支出困难家庭，由社会救助管理部门根据实际需要给予必要的医疗、教育等社会救助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225022, '《中华人民共和国社会救助法》', '第二十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '特困人员、最低生活保障家庭、最低生活保障边缘家庭、刚性支出困难家庭的收入、财产等状况认定办法，由省、自治区、直辖市人民政府按照国家有关规定，根据当地经济社会发展状况和人民生活水平制定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225023, '《中华人民共和国社会救助法》', '第二十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '对特困人员、最低生活保障家庭、最低生活保障边缘家庭、刚性支出困难家庭，由社会救助管理部门给予相应的医疗救助。 对特困人员、最低生活保障家庭成员等参加城乡居民基本医疗保险的个人缴费部分给予资助。 对特困人员，最低生活保障家庭、最低生活保障边缘家庭、刚性支出困难家庭中的大病患者等，经基本医疗保险、大病保险和其他补充医疗保险支付后，个人及其家庭难以承担的符合规定的基本医疗自负费用，按照规定给予补助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225024, '《中华人民共和国社会救助法》', '第二十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '对特困人员，最低生活保障家庭、最低生活保障边缘家庭、刚性支出困难家庭成员，由社会救助管理部门在学前教育、义务教育、高中阶段教育（含中等职业教育）、普通高等教育阶段，按照规定采取减免相关费用，发放助学金、生活补助，提供勤工助学岗位、助学贷款等方式，给予教育救助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225025, '《中华人民共和国社会救助法》', '第二十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '对符合规定标准的住房困难的分散供养特困人员、最低生活保障家庭、最低生活保障边缘家庭、刚性支出困难家庭，由社会救助管理部门给予住房救助。属于城镇住房救助对象的，优先配租公租房或者发放公租房租赁补贴；属于农村住房救助对象的，通过农村危房改造等方式优先给予住房救助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225026, '《中华人民共和国社会救助法》', '第二十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '对最低生活保障家庭、最低生活保障边缘家庭、刚性支出困难家庭中有劳动能力且处于失业状态的成员，由社会救助管理部门通过鼓励企业吸纳就业等途径，给予就业救助。对通过上述途径仍然无法就业且符合就业困难人员条件的，按照规定通过公益性岗位安置等方式，给予就业救助。 社会救助对象中有劳动能力和就业条件的，应当积极就业。就业救助应当与最低生活保障、失业保险等制度衔接，鼓励和引导就业救助对象主动就业创业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225027, '《中华人民共和国社会救助法》', '第二十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '对基本生活受到自然灾害严重影响的人员，由社会救助管理部门给予必要的应急救助、生活救助和因灾倒损住房恢复重建救助等。 各级人民政府应当做好突发事件社会救助工作，保障遇困人员基本生活。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225028, '《中华人民共和国社会救助法》', '第二十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '对遭遇突发性、紧迫性、灾难性等困难导致基本生活暂时出现严重困难的人员，由社会救助管理部门采取发放救助金或者配发实物等方式给予临时救助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225029, '《中华人民共和国社会救助法》', '第三十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '对需要急救但身份不明或者无力支付急救费用且符合规定的急危重伤病患者，由社会救助管理部门给予疾病应急救助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225030, '《中华人民共和国社会救助法》', '第三十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '对生活无着的流散人员，由社会救助管理部门给予照料服务、急病救治、身份查询、协助返回、寻亲安置等救助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225031, '《中华人民共和国社会救助法》', '第三十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '县级以上地方人民政府应当根据物价上涨情况，及时发放价格临时补贴。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225032, '《中华人民共和国社会救助法》', '第三十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '省、自治区、直辖市人民政府可以根据地方实际将其他特殊困难家庭或者人员纳入社会救助对象范围。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225033, '《中华人民共和国社会救助法》', '第三十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '国家积极发展服务类社会救助，为社会救助对象提供必要的照护服务、生活服务、关爱服务等。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225034, '《中华人民共和国社会救助法》', '第三十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '社会救助对象遇有紧急情况的，社会救助管理部门依法及时给予救助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225035, '《中华人民共和国社会救助法》', '第三十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第二章 救助对象和措施', NULL, '对遭受犯罪侵害或者民事侵权，获得司法救助仍然面临生活困难的当事人，符合社会救助条件的，纳入社会救助对象范围。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225036, '《中华人民共和国社会救助法》', '第三十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第三章 救助程序', NULL, '申请特困人员供养、最低生活保障、医疗救助、住房救助、就业救助，由本人或者与其共同生活的家庭成员向户籍所在地乡镇人民政府、街道办事处提出。有条件的地方可以有序推进持有居住证人员在居住地申请。 申请临时救助，由本人或者与其共同生活的家庭成员向急难发生地乡镇人民政府、街道办事处提出。 本人或者与其共同生活的家庭成员申请社会救助有困难的，可以委托村民委员会、居民委员会或者他人代为提出申请。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225037, '《中华人民共和国社会救助法》', '第三十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第三章 救助程序', NULL, '申请教育救助，向就读学校提出，由学校按照国家有关规定实施。 申请住房救助，也可以按照有关规定向县级以上地方人民政府住房保障部门提出。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225038, '《中华人民共和国社会救助法》', '第三十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第三章 救助程序', NULL, '村民委员会、居民委员会和其他基层单位在工作中发现需要救助的家庭和人员，应当及时向乡镇人民政府、街道办事处或者县级人民政府社会救助管理部门报告。 乡镇人民政府、街道办事处应当主动了解本行政区域内居民生活状况，发现需要救助的家庭和人员，应当及时告知相关社会救助政策，并依法协助申请或者组织救助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225039, '《中华人民共和国社会救助法》', '第四十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第三章 救助程序', NULL, '申请社会救助，应当如实报告共同生活的家庭成员个人基本信息和家庭收入、财产、刚性支出等与申请社会救助相关的情况，并同意社会救助管理部门进行核查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225040, '《中华人民共和国社会救助法》', '第四十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第三章 救助程序', NULL, '县级人民政府民政部门可以向户籍管理、税务、社会保险、不动产登记、市场监督管理、住房公积金管理、车船管理等单位，银行、保险、证券等金融机构以及提供货币资金转移服务的非银行支付机构，核对社会救助家庭收入、财产等状况；必要时，经共同生活的家庭成员以外的法定赡养、抚养、扶养义务人同意，可以对其收入、财产等状况进行核对。有关单位和机构应当予以配合。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225041, '《中华人民共和国社会救助法》', '第四十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第三章 救助程序', NULL, '县级以上人民政府民政部门应当牵头健全社会救助家庭经济状况核对机制，促进跨部门信息共享，提高社会救助审核确认效率和准确度。 已经被确认为特困人员、最低生活保障家庭、最低生活保障边缘家庭、刚性支出困难家庭的，确认结果信息共享互认，其他社会救助管理部门可以不再重复审核其家庭经济状况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225042, '《中华人民共和国社会救助法》', '第四十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第三章 救助程序', NULL, '乡镇人民政府、街道办事处受理社会救助申请后，可以通过入户调查、邻里访问、信函索证等方式，对申请家庭或者个人的情况进行调查核实，也可以提请县级人民政府民政部门核对社会救助申请对象收入、财产等状况。 申请对象、有关单位和个人应当配合核查，如实提供相关信息。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225043, '《中华人民共和国社会救助法》', '第四十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第三章 救助程序', NULL, '乡镇人民政府、街道办事处根据调查核实结果，提出审核意见，报请县级人民政府社会救助管理部门作出社会救助确认决定。 省、自治区、直辖市人民政府可以规定由乡镇人民政府、街道办事处作出社会救助确认决定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225044, '《中华人民共和国社会救助法》', '第四十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第三章 救助程序', NULL, '县级人民政府社会救助管理部门或者乡镇人民政府、街道办事处决定给予社会救助的，应当按照规定在申请家庭或者个人所在的村、社区等范围内公布社会救助确认决定；决定不给予社会救助的，应当书面告知申请人并说明理由。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225045, '《中华人民共和国社会救助法》', '第四十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第三章 救助程序', NULL, '已经获得社会救助的对象，其共同生活的家庭成员、收入、财产等状况发生变化的，应当及时告知社会救助管理部门或者乡镇人民政府、街道办事处。 社会救助管理部门和乡镇人民政府、街道办事处应当对社会救助对象的家庭成员、收入、财产等状况定期进行核查，或者根据需要进行实地抽查。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225046, '《中华人民共和国社会救助法》', '第四十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第三章 救助程序', NULL, '社会救助管理部门或者乡镇人民政府、街道办事处，可以根据社会救助对象家庭成员、经济状况等变化情况作出相应调整、终止社会救助决定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225047, '《中华人民共和国社会救助法》', '第四十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第三章 救助程序', NULL, '社会救助管理部门或者乡镇人民政府、街道办事处作出调减、终止社会救助决定前应当听取社会救助对象的意见，作出决定后应当书面告知社会救助对象并说明理由。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225048, '《中华人民共和国社会救助法》', '第四十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第三章 救助程序', NULL, '自然灾害发生后，受灾地区人民政府按照职责及时给予受灾人员救助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225049, '《中华人民共和国社会救助法》', '第五十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第三章 救助程序', NULL, '对申请临时救助，情况紧急、救助金额较小、需立即采取救助措施的，应当先行救助。紧急情况解除后，应当按照规定补充说明情况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225050, '《中华人民共和国社会救助法》', '第五十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第三章 救助程序', NULL, '对急危重伤病患者给予疾病应急救助的，由医疗机构实施紧急救治。符合规定的紧急救治费用，由疾病应急救助基金予以补助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225051, '《中华人民共和国社会救助法》', '第五十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第三章 救助程序', NULL, '申请生活无着的流散人员救助，向急难发生地县级以上地方人民政府有关救助管理机构提出，也可以向急难发生地乡镇人民政府、街道办事处提出。救助管理机构对生活无着的流散人员实施救助。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225052, '《中华人民共和国社会救助法》', '第五十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第三章 救助程序', NULL, '社会救助管理部门应当结合社会救助工作实际情况，依法优化工作流程，提高便民化水平。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225053, '《中华人民共和国社会救助法》', '第五十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第四章 社会力量参与', NULL, '建立和完善社会力量参与社会救助机制，加强政府救助与社会力量参与有效衔接和协同，动员和引导社会力量积极参与社会救助。 社会力量参与社会救助，依法享受相关优惠政策。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225054, '《中华人民共和国社会救助法》', '第五十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第四章 社会力量参与', NULL, '鼓励社会工作专业力量参与社会救助。通过购买服务、开发岗位、政策引导、提供工作场所、设立基层社工站等方式，鼓励社会工作服务机构和社会工作者协助社会救助管理部门开展家庭经济状况调查评估、建档访视、需求分析等事务，提供访视照料、心理疏导、资源链接、能力提升、社会融入等服务。 鼓励以社会救助为主的服务机构设置社会工作专业岗位。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225055, '《中华人民共和国社会救助法》', '第五十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第四章 社会力量参与', NULL, '社会救助管理部门和乡镇人民政府、街道办事处可以将社会救助中属于政府职责范围且适合通过市场化方式提供的服务事项，通过政府购买服务方式实施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225056, '《中华人民共和国社会救助法》', '第五十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第四章 社会力量参与', NULL, '鼓励和支持公民、法人及其他组织以捐赠财产、设立项目、提供服务等方式自愿开展帮扶活动，动员和引导慈善组织等社会力量加大社会救助方面的帮扶力度。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225057, '《中华人民共和国社会救助法》', '第五十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第四章 社会力量参与', NULL, '促进社会救助领域志愿服务发展，支持和引导志愿服务组织、志愿者开展志愿服务，发挥志愿服务在汇聚社会资源、提供救助帮扶等方面的作用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225058, '《中华人民共和国社会救助法》', '第五十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第四章 社会力量参与', NULL, '县级以上人民政府及其社会救助管理部门应当建立社会力量参与社会救助的机制和渠道，依法做好信息发布、政策咨询、业务指导、项目指引、志愿服务记录或者证明等工作，为社会力量参与社会救助创造条件、提供便利。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225059, '《中华人民共和国社会救助法》', '第六十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第五章 救助监督和保障', NULL, '县级以上人民政府应当开通社会救助服务热线，受理和转介咨询、举报投诉，接受社会监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225060, '《中华人民共和国社会救助法》', '第六十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第五章 救助监督和保障', NULL, '社会救助工作人员应当客观公正、履职尽责。 各级人民政府应当关心关爱社会救助经办人员、社会救助协理员等基层社会救助工作人员，保障其履职需要。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225061, '《中华人民共和国社会救助法》', '第六十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第五章 救助监督和保障', NULL, '国家依法完善社会救助统计制度，实现社会救助信息准确完整、统一汇集、互通共享。 对可以通过社会救助家庭经济状况核对机制核实的情况，社会救助管理部门不得要求社会救助对象提供。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225062, '《中华人民共和国社会救助法》', '第六十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第五章 救助监督和保障', NULL, '县级以上地方人民政府及其社会救助管理部门应当加强互联网等信息技术在社会救助工作中的应用，并推动社会救助服务向移动端延伸，为需要救助的家庭和人员提供方便快捷的在线申请、办理查询、举报投诉等服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225063, '《中华人民共和国社会救助法》', '第六十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第五章 救助监督和保障', NULL, '县级人民政府应当建立社会救助“一门受理、协同办理”机制。乡镇人民政府、街道办事处应当设立统一受理社会救助申请的窗口，及时受理、转办申请事项。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225064, '《中华人民共和国社会救助法》', '第六十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第五章 救助监督和保障', NULL, '县级以上人民政府社会救助管理部门和乡镇人民政府、街道办事处在履行社会救助职责过程中，可以查阅、复制与社会救助事项相关的资料，询问与社会救助事项相关的单位、个人，要求其对相关情况作出说明或者提供相关材料。有关单位、个人应当配合。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225065, '《中华人民共和国社会救助法》', '第六十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第五章 救助监督和保障', NULL, '县级以上人民政府财政部门依法对社会救助资金、物资的管理和使用情况实施监督。 社会救助资金和物资的筹集、分配、管理、使用情况，应当依法接受审计监督。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225066, '《中华人民共和国社会救助法》', '第六十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第五章 救助监督和保障', NULL, '县级人民政府及其社会救助管理部门应当及时公开社会救助政策、救助标准以及社会救助资金、物资的管理和使用等情况。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225067, '《中华人民共和国社会救助法》', '第六十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第五章 救助监督和保障', NULL, '履行社会救助职责的工作人员行使职权，应当接受社会监督。 任何单位、个人有权对履行社会救助职责的工作人员在社会救助工作中的违法行为进行举报投诉。受理举报投诉的机关应当依法及时核实、处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225068, '《中华人民共和国社会救助法》', '第六十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第五章 救助监督和保障', NULL, '县级以上人民政府及其社会救助管理部门应当加强对社会救助工作的监督检查，完善相关监督管理制度，将社会救助制度落实情况纳入绩效评价。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225069, '《中华人民共和国社会救助法》', '第七十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第六章 法律责任', NULL, '违反本法规定，有下列情形之一的，责令改正；对存在故意或者重大过失的负有责任的领导人员和直接责任人员依法给予处分，造成恶劣影响或者严重后果的，依法从重给予处分： （一）对符合申请条件的救助申请不予受理； （二）对符合救助条件的申请不予审核确认； （三）对不符合救助条件的申请予以审核确认； （四）隐匿、销毁、篡改或者因重大过失丢失接受、发放、登记社会救助资金、物资或者服务记录等数据； （五）不按照规定发放救助金、救助物资或者提供相关救助服务； （六）非法查询与社会救助申请无关的个人信息，泄露、出售、非法提供个人隐私或者个人信息； （七）其他滥用职权、玩忽职守、徇私舞弊等行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225070, '《中华人民共和国社会救助法》', '第七十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第六章 法律责任', NULL, '违反本法规定，截留、挪用、私分社会救助资金、物资的，由有关部门责令限期改正；对负有责任的领导人员和直接责任人员依法给予处分；有违法所得的，没收违法所得；对有关组织、个人可以处违法所得二倍以下的罚款。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225071, '《中华人民共和国社会救助法》', '第七十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第六章 法律责任', NULL, '对出具虚假证明材料的单位或者人员，社会救助管理部门应当建议有关单位或者其上级主管机关依法对有关责任人予以处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225072, '《中华人民共和国社会救助法》', '第七十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第六章 法律责任', NULL, '采取虚报、隐瞒、伪造等手段，骗取社会救助资金、物资或者服务的，社会救助管理部门可以责令退回非法获取的财物和利益，处非法获取的财物和利益价值二倍以下的罚款；对社会救助对象可以决定调减、停止社会救助。违反其他法律、行政法规的，由有关主管部门依法处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225073, '《中华人民共和国社会救助法》', '第七十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第六章 法律责任', NULL, '拒不履行社会救助管理部门或者乡镇人民政府、街道办事处作出的调减、终止社会救助决定，非法占有社会救助财物等的，社会救助管理部门应当责令其限期退回。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225074, '《中华人民共和国社会救助法》', '第七十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第六章 法律责任', NULL, '以暴力、威胁等方式干扰社会救助工作开展，扰乱社会救助工作秩序的，依法给予处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225075, '《中华人民共和国社会救助法》', '第七十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第六章 法律责任', NULL, '对社会救助管理部门或者乡镇人民政府、街道办事处作出的关于社会救助的行政行为不服的，可以依法申请行政复议或者提起行政诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225076, '《中华人民共和国社会救助法》', '第七十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第六章 法律责任', NULL, '违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (225077, '《中华人民共和国社会救助法》', '第七十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2026-04-30', '第七章 附 则', NULL, '本法自2026年7月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226000, '《中华人民共和国境外非政府组织境内活动管理法》', '第一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第一章 总 则', NULL, '为了规范、引导境外非政府组织在中国境内的活动，保障其合法权益，促进交流与合作，制定本法。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226001, '《中华人民共和国境外非政府组织境内活动管理法》', '第二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第一章 总 则', NULL, '境外非政府组织在中国境内开展活动适用本法。 本法所称境外非政府组织，是指在境外合法成立的基金会、社会团体、智库机构等非营利、非政府的社会组织。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226002, '《中华人民共和国境外非政府组织境内活动管理法》', '第三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第一章 总 则', NULL, '境外非政府组织依照本法可以在经济、教育、科技、文化、卫生、体育、环保等领域和济困、救灾等方面开展有利于公益事业发展的活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226003, '《中华人民共和国境外非政府组织境内活动管理法》', '第四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第一章 总 则', NULL, '境外非政府组织在中国境内依法开展活动，受法律保护。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226004, '《中华人民共和国境外非政府组织境内活动管理法》', '第五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第一章 总 则', NULL, '境外非政府组织在中国境内开展活动应当遵守中国法律，不得危害中国的国家统一、安全和民族团结，不得损害中国国家利益、社会公共利益和公民、法人以及其他组织的合法权益。 境外非政府组织在中国境内不得从事或者资助营利性活动、政治活动，不得非法从事或者资助宗教活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226005, '《中华人民共和国境外非政府组织境内活动管理法》', '第六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第一章 总 则', NULL, '国务院公安部门和省级人民政府公安机关，是境外非政府组织在中国境内开展活动的登记管理机关。 国务院有关部门和单位、省级人民政府有关部门和单位，是境外非政府组织在中国境内开展活动的相应业务主管单位。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226006, '《中华人民共和国境外非政府组织境内活动管理法》', '第七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第一章 总 则', NULL, '县级以上人民政府公安机关和有关部门在各自职责范围内对境外非政府组织在中国境内开展活动依法实施监督管理、提供服务。 国家建立境外非政府组织监督管理工作协调机制，负责研究、协调、解决境外非政府组织在中国境内开展活动监督管理和服务便利中的重大问题。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226007, '《中华人民共和国境外非政府组织境内活动管理法》', '第八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第一章 总 则', NULL, '国家对为中国公益事业发展做出突出贡献的境外非政府组织给予表彰。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226008, '《中华人民共和国境外非政府组织境内活动管理法》', '第九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第二章 登记和备案', NULL, '境外非政府组织在中国境内开展活动，应当依法登记设立代表机构；未登记设立代表机构需要在中国境内开展临时活动的，应当依法备案。 境外非政府组织未登记设立代表机构、开展临时活动未经备案的，不得在中国境内开展或者变相开展活动，不得委托、资助或者变相委托、资助中国境内任何单位和个人在中国境内开展活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226009, '《中华人民共和国境外非政府组织境内活动管理法》', '第十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第二章 登记和备案', NULL, '境外非政府组织符合下列条件，根据业务范围、活动地域和开展活动的需要，可以申请在中国境内登记设立代表机构： （一）在境外合法成立； （二）能够独立承担民事责任； （三）章程规定的宗旨和业务范围有利于公益事业发展； （四）在境外存续二年以上并实质性开展活动； （五）法律、行政法规规定的其他条件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226010, '《中华人民共和国境外非政府组织境内活动管理法》', '第十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第二章 登记和备案', NULL, '境外非政府组织申请登记设立代表机构，应当经业务主管单位同意。 业务主管单位的名录由国务院公安部门和省级人民政府公安机关会同有关部门公布。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226011, '《中华人民共和国境外非政府组织境内活动管理法》', '第十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第二章 登记和备案', NULL, '境外非政府组织应当自业务主管单位同意之日起三十日内，向登记管理机关申请设立代表机构登记。申请设立代表机构登记，应当向登记管理机关提交下列文件、材料： （一）申请书； （二）符合本法第十条规定的证明文件、材料； （三）拟设代表机构首席代表的身份证明、简历及其无犯罪记录证明材料或者声明； （四）拟设代表机构的住所证明材料； （五）资金来源证明材料； （六）业务主管单位的同意文件； （七）法律、行政法规规定的其他文件、材料。 登记管理机关审查境外非政府组织代表机构设立申请，根据需要可以组织专家进行评估。 登记管理机关应当自受理申请之日起六十日内作出准予登记或者不予登记的决定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226012, '《中华人民共和国境外非政府组织境内活动管理法》', '第十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第二章 登记和备案', NULL, '对准予登记的境外非政府组织代表机构，登记管理机关发给登记证书，并向社会公告。登记事项包括： （一）名称； （二）住所； （三）业务范围； （四）活动地域； （五）首席代表； （六）业务主管单位。 境外非政府组织代表机构凭登记证书依法办理税务登记，刻制印章，在中国境内的银行开立银行账户，并将税务登记证件复印件、印章式样以及银行账户报登记管理机关备案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226013, '《中华人民共和国境外非政府组织境内活动管理法》', '第十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第二章 登记和备案', NULL, '境外非政府组织代表机构需要变更登记事项的，应当自业务主管单位同意之日起三十日内，向登记管理机关申请变更登记。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226014, '《中华人民共和国境外非政府组织境内活动管理法》', '第十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第二章 登记和备案', NULL, '有下列情形之一的，境外非政府组织代表机构由登记管理机关注销登记，并向社会公告： （一）境外非政府组织撤销代表机构的； （二）境外非政府组织终止的； （三）境外非政府组织代表机构依法被撤销登记或者吊销登记证书的； （四）由于其他原因终止的。 境外非政府组织代表机构注销登记后，设立该代表机构的境外非政府组织应当妥善办理善后事宜。境外非政府组织代表机构不具有法人资格，涉及相关法律责任的，由该境外非政府组织承担。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226015, '《中华人民共和国境外非政府组织境内活动管理法》', '第十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第二章 登记和备案', NULL, '境外非政府组织未在中国境内设立代表机构，在中国境内开展临时活动的，应当与中国的国家机关、人民团体、事业单位、社会组织（以下称中方合作单位）合作进行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226016, '《中华人民共和国境外非政府组织境内活动管理法》', '第十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第二章 登记和备案', NULL, '境外非政府组织开展临时活动，中方合作单位应当按照国家规定办理审批手续，并在开展临时活动十五日前向其所在地的登记管理机关备案。备案应当提交下列文件、材料： （一）境外非政府组织合法成立的证明文件、材料； （二）境外非政府组织与中方合作单位的书面协议； （三）临时活动的名称、宗旨、地域和期限等相关材料； （四）项目经费、资金来源证明材料及中方合作单位的银行账户； （五）中方合作单位获得批准的文件； （六）法律、行政法规规定的其他文件、材料。 在赈灾、救援等紧急情况下，需要开展临时活动的，备案时间不受前款规定的限制。 临时活动期限不超过一年，确实需要延长期限的，应当重新备案。 登记管理机关认为备案的临时活动不符合本法第五条规定的，应当及时通知中方合作单位停止临时活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226017, '《中华人民共和国境外非政府组织境内活动管理法》', '第十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 活动规范', NULL, '境外非政府组织代表机构应当以登记的名称，在登记的业务范围和活动地域内开展活动。 境外非政府组织不得在中国境内设立分支机构，国务院另有规定的除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226018, '《中华人民共和国境外非政府组织境内活动管理法》', '第十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 活动规范', NULL, '境外非政府组织代表机构应当于每年12月31日前将包含项目实施、资金使用等内容的下一年度活动计划报业务主管单位，业务主管单位同意后十日内报登记管理机关备案。特殊情况下需要调整活动计划的，应当及时向登记管理机关备案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226019, '《中华人民共和国境外非政府组织境内活动管理法》', '第二十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 活动规范', NULL, '境外非政府组织在中国境内开展活动不得对中方合作单位、受益人附加违反中国法律法规的条件。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226020, '《中华人民共和国境外非政府组织境内活动管理法》', '第二十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 活动规范', NULL, '境外非政府组织在中国境内活动资金包括： （一）境外合法来源的资金； （二）中国境内的银行存款利息； （三）中国境内合法取得的其他资金。 境外非政府组织在中国境内活动不得取得或者使用前款规定以外的资金。 境外非政府组织及其代表机构不得在中国境内进行募捐。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226021, '《中华人民共和国境外非政府组织境内活动管理法》', '第二十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 活动规范', NULL, '设立代表机构的境外非政府组织应当通过代表机构在登记管理机关备案的银行账户管理用于中国境内的资金。 开展临时活动的境外非政府组织应当通过中方合作单位的银行账户管理用于中国境内的资金，实行单独记账，专款专用。 未经前两款规定的银行账户，境外非政府组织、中方合作单位和个人不得以其他任何形式在中国境内进行项目活动资金的收付。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226022, '《中华人民共和国境外非政府组织境内活动管理法》', '第二十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 活动规范', NULL, '境外非政府组织应当按照代表机构登记的业务范围、活动地域或者与中方合作单位协议的约定使用资金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226023, '《中华人民共和国境外非政府组织境内活动管理法》', '第二十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 活动规范', NULL, '境外非政府组织代表机构应当执行中国统一的会计制度。财务会计报告应当经中国境内会计师事务所审计。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226024, '《中华人民共和国境外非政府组织境内活动管理法》', '第二十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 活动规范', NULL, '境外非政府组织在中国境内开展活动，应当按照中国有关外汇管理的规定办理外汇收支。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226025, '《中华人民共和国境外非政府组织境内活动管理法》', '第二十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 活动规范', NULL, '境外非政府组织代表机构应当依法办理税务登记、纳税申报和税款缴纳等事项。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226026, '《中华人民共和国境外非政府组织境内活动管理法》', '第二十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 活动规范', NULL, '境外非政府组织代表机构在中国境内聘用工作人员应当遵守法律、行政法规，并将聘用的工作人员信息报业务主管单位和登记管理机关备案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226027, '《中华人民共和国境外非政府组织境内活动管理法》', '第二十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 活动规范', NULL, '境外非政府组织代表机构、开展临时活动的境外非政府组织不得在中国境内发展会员，国务院另有规定的除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226028, '《中华人民共和国境外非政府组织境内活动管理法》', '第二十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 活动规范', NULL, '境外非政府组织代表机构应当设一名首席代表，可以根据业务需要设一至三名代表。 有下列情形之一的，不得担任首席代表、代表： （一）无民事行为能力或者限制民事行为能力的； （二）有犯罪记录的； （三）依法被撤销登记、吊销登记证书的代表机构的首席代表、代表，自被撤销、吊销之日起未逾五年的； （四）法律、行政法规规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226029, '《中华人民共和国境外非政府组织境内活动管理法》', '第三十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 活动规范', NULL, '开展临时活动的境外非政府组织，应当以经备案的名称开展活动。 境外非政府组织、中方合作单位应当于临时活动结束后三十日内将活动情况、资金使用情况等书面报送登记管理机关。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226030, '《中华人民共和国境外非政府组织境内活动管理法》', '第三十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 活动规范', NULL, '境外非政府组织代表机构应当于每年1月31日前向业务主管单位报送上一年度工作报告，经业务主管单位出具意见后，于3月31日前报送登记管理机关，接受年度检查。 年度工作报告应当包括经审计的财务会计报告、开展活动的情况以及人员和机构变动的情况等内容。 境外非政府组织代表机构应当将年度工作报告在登记管理机关统一的网站上向社会公开。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226031, '《中华人民共和国境外非政府组织境内活动管理法》', '第三十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第三章 活动规范', NULL, '中国境内任何单位和个人不得接受未登记代表机构、开展临时活动未经备案的境外非政府组织的委托、资助，代理或者变相代理境外非政府组织在中国境内开展活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226032, '《中华人民共和国境外非政府组织境内活动管理法》', '第三十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第四章 便利措施', NULL, '国家保障和支持境外非政府组织在中国境内依法开展活动。各级人民政府有关部门应当为境外非政府组织在中国境内依法开展活动提供必要的便利和服务。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226033, '《中华人民共和国境外非政府组织境内活动管理法》', '第三十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第四章 便利措施', NULL, '国务院公安部门和省级人民政府公安机关会同有关部门制定境外非政府组织活动领域和项目目录，公布业务主管单位名录，为境外非政府组织开展活动提供指引。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226034, '《中华人民共和国境外非政府组织境内活动管理法》', '第三十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第四章 便利措施', NULL, '县级以上人民政府有关部门应当依法为境外非政府组织提供政策咨询、活动指导服务。 登记管理机关应当通过统一的网站，公布境外非政府组织申请设立代表机构以及开展临时活动备案的程序，供境外非政府组织查询。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226035, '《中华人民共和国境外非政府组织境内活动管理法》', '第三十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第四章 便利措施', NULL, '境外非政府组织代表机构依法享受税收优惠等政策。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226036, '《中华人民共和国境外非政府组织境内活动管理法》', '第三十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第四章 便利措施', NULL, '对境外非政府组织代表机构进行年度检查不得收取费用。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226037, '《中华人民共和国境外非政府组织境内活动管理法》', '第三十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第四章 便利措施', NULL, '境外非政府组织代表机构首席代表和代表中的境外人员，可以凭登记证书、代表证明文件等依法办理就业等工作手续。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226038, '《中华人民共和国境外非政府组织境内活动管理法》', '第三十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第五章 监督管理', NULL, '境外非政府组织在中国境内开展活动，应当接受公安机关、有关部门和业务主管单位的监督管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226039, '《中华人民共和国境外非政府组织境内活动管理法》', '第四十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第五章 监督管理', NULL, '业务主管单位负责对境外非政府组织设立代表机构、变更登记事项、年度工作报告提出意见，指导、监督境外非政府组织及其代表机构依法开展活动，协助公安机关等部门查处境外非政府组织及其代表机构的违法行为。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226040, '《中华人民共和国境外非政府组织境内活动管理法》', '第四十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第五章 监督管理', NULL, '公安机关负责境外非政府组织代表机构的登记、年度检查，境外非政府组织临时活动的备案，对境外非政府组织及其代表机构的违法行为进行查处。 公安机关履行监督管理职责，发现涉嫌违反本法规定行为的，可以依法采取下列措施： （一）约谈境外非政府组织代表机构的首席代表以及其他负责人； （二）进入境外非政府组织在中国境内的住所、活动场所进行现场检查； （三）询问与被调查事件有关的单位和个人，要求其对与被调查事件有关的事项作出说明； （四）查阅、复制与被调查事件有关的文件、资料，对可能被转移、销毁、隐匿或者篡改的文件、资料予以封存； （五）查封或者扣押涉嫌违法活动的场所、设施或者财物。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226041, '《中华人民共和国境外非政府组织境内活动管理法》', '第四十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第五章 监督管理', NULL, '公安机关可以查询与被调查事件有关的单位和个人的银行账户，有关金融机构、金融监督管理机构应当予以配合。对涉嫌违法活动的银行账户资金，经设区的市级以上人民政府公安机关负责人批准，可以提请人民法院依法冻结；对涉嫌犯罪的银行账户资金，依照《中华人民共和国刑事诉讼法》的规定采取冻结措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226042, '《中华人民共和国境外非政府组织境内活动管理法》', '第四十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第五章 监督管理', NULL, '国家安全、外交外事、财政、金融监督管理、海关、税务、外国专家等部门按照各自职责对境外非政府组织及其代表机构依法实施监督管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226043, '《中华人民共和国境外非政府组织境内活动管理法》', '第四十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第五章 监督管理', NULL, '国务院反洗钱行政主管部门依法对境外非政府组织代表机构、中方合作单位以及接受境外非政府组织资金的中国境内单位和个人开立、使用银行账户过程中遵守反洗钱和反恐怖主义融资法律规定的情况进行监督管理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226044, '《中华人民共和国境外非政府组织境内活动管理法》', '第四十五条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第六章 法律责任', NULL, '境外非政府组织代表机构、开展临时活动的境外非政府组织或者中方合作单位有下列情形之一的，由设区的市级以上人民政府公安机关给予警告或者责令限期停止活动；没收非法财物和违法所得；情节严重的，由登记管理机关吊销登记证书、取缔临时活动： （一）未按照规定办理变更登记、备案相关事项的； （二）未按照登记或者备案的名称、业务范围、活动地域开展活动的； （三）从事、资助营利性活动，进行募捐或者违反规定发展会员的； （四）违反规定取得、使用资金，未按照规定开立、使用银行账户或者进行会计核算的； （五）未按照规定报送年度活动计划、报送或者公开年度工作报告的； （六）拒不接受或者不按照规定接受监督检查的。 境外非政府组织代表机构、开展临时活动的境外非政府组织或者中方合作单位以提供虚假材料等非法手段，取得代表机构登记证书或者进行临时活动备案的，或者有伪造、变造、买卖、出租、出借登记证书、印章行为的，依照前款规定处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226045, '《中华人民共和国境外非政府组织境内活动管理法》', '第四十六条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第六章 法律责任', NULL, '有下列情形之一的，由设区的市级以上人民政府公安机关予以取缔或者责令停止违法行为；没收非法财物和违法所得；对直接责任人员给予警告，情节严重的，处十日以下拘留： （一）未经登记、备案，以境外非政府组织代表机构、境外非政府组织名义开展活动的； （二）被撤销登记、吊销登记证书或者注销登记后以境外非政府组织代表机构名义开展活动的； （三）境外非政府组织临时活动期限届满或者临时活动被取缔后在中国境内开展活动的； （四）境外非政府组织未登记代表机构、临时活动未备案，委托、资助中国境内单位和个人在中国境内开展活动的。 中国境内单位和个人明知境外非政府组织未登记代表机构、临时活动未备案，与其合作的，或者接受其委托、资助，代理或者变相代理其开展活动、进行项目活动资金收付的，依照前款规定处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226046, '《中华人民共和国境外非政府组织境内活动管理法》', '第四十七条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第六章 法律责任', NULL, '境外非政府组织、境外非政府组织代表机构有下列情形之一的，由登记管理机关吊销登记证书或者取缔临时活动；尚不构成犯罪的，由设区的市级以上人民政府公安机关对直接责任人员处十五日以下拘留： （一）煽动抗拒法律、法规实施的； （二）非法获取国家秘密的； （三）造谣、诽谤或者发表、传播其他有害信息，危害国家安全或者损害国家利益的； （四）从事或者资助政治活动，非法从事或者资助宗教活动的； （五）有其他危害国家安全、损害国家利益或者社会公共利益情形的。 境外非政府组织、境外非政府组织代表机构有分裂国家、破坏国家统一、颠覆国家政权等犯罪行为的，由登记管理机关依照前款规定处罚，对直接责任人员依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226047, '《中华人民共和国境外非政府组织境内活动管理法》', '第四十八条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第六章 法律责任', NULL, '境外非政府组织、境外非政府组织代表机构违反本法规定被撤销登记、吊销登记证书或者临时活动被取缔的，自被撤销、吊销、取缔之日起五年内，不得在中国境内再设立代表机构或者开展临时活动。 未登记代表机构或者临时活动未备案开展活动的境外非政府组织，自活动被取缔之日起五年内，不得在中国境内再设立代表机构或者开展临时活动。 有本法第四十七条规定情形之一的境外非政府组织，国务院公安部门可以将其列入不受欢迎的名单，不得在中国境内再设立代表机构或者开展临时活动。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226048, '《中华人民共和国境外非政府组织境内活动管理法》', '第四十九条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第六章 法律责任', NULL, '境外非政府组织代表机构被责令限期停止活动的，由登记管理机关封存其登记证书、印章和财务凭证。对被撤销登记、吊销登记证书的，由登记管理机关收缴其登记证书、印章并公告作废。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226049, '《中华人民共和国境外非政府组织境内活动管理法》', '第五十条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第六章 法律责任', NULL, '境外人员违反本法规定的，有关机关可以依法限期出境、遣送出境或者驱逐出境。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226050, '《中华人民共和国境外非政府组织境内活动管理法》', '第五十一条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第六章 法律责任', NULL, '公安机关、有关部门和业务主管单位及其工作人员在境外非政府组织监督管理工作中，不履行职责或者滥用职权、玩忽职守、徇私舞弊的，依法追究法律责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226051, '《中华人民共和国境外非政府组织境内活动管理法》', '第五十二条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第六章 法律责任', NULL, '违反本法规定，构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226052, '《中华人民共和国境外非政府组织境内活动管理法》', '第五十三条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第七章 附 则', NULL, '境外学校、医院、自然科学和工程技术的研究机构或者学术组织与境内学校、医院、自然科学和工程技术的研究机构或者学术组织开展交流合作，按照国家有关规定办理。 前款规定的境外学校、医院、机构和组织在中国境内的活动违反本法第五条规定的，依法追究法律责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (226053, '《中华人民共和国境外非政府组织境内活动管理法》', '第五十四条', '社会', '法律', NULL, '全国人民代表大会常务委员会 2017-11-04', '第七章 附 则', NULL, '本法自2017年1月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400000, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第一条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动者与用人单位之间发生的下列纠纷，属于劳动争议，当事人不服劳动争议仲裁机构作出的裁决，依法提起诉讼的，人民法院应予受理： （一）劳动者与用人单位在履行劳动合同过程中发生的纠纷； （二）劳动者与用人单位之间没有订立书面劳动合同，但已形成劳动关系后发生的纠纷； （三）劳动者与用人单位因劳动关系是否已经解除或者终止，以及应否支付解除或者终止劳动关系经济补偿金发生的纠纷； （四）劳动者与用人单位解除或者终止劳动关系后，请求用人单位返还其收取的劳动合同定金、保证金、抵押金、抵押物发生的纠纷，或者办理劳动者的人事档案、社会保险关系等移转手续发生的纠纷； （五）劳动者以用人单位未为其办理社会保险手续，且社会保险经办机构不能补办导致其无法享受社会保险待遇为由，要求用人单位赔偿损失发生的纠纷； （六）劳动者退休后，与尚未参加社会保险统筹的原用人单位因追索养老金、医疗费、工伤保险待遇和其他社会保险待遇而发生的纠纷； （七）劳动者因为工伤、职业病，请求用人单位依法给予工伤保险待遇发生的纠纷； （八）劳动者依据劳动合同法第八十五条规定，要求用人单位支付加付赔偿金发生的纠纷； （九）因企业自主进行改制发生的纠纷。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400001, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第二条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '下列纠纷不属于劳动争议： （一）劳动者请求社会保险经办机构发放社会保险金的纠纷； （二）劳动者与用人单位因住房制度改革产生的公有住房转让纠纷； （三）劳动者对劳动能力鉴定委员会的伤残等级鉴定结论或者对职业病诊断鉴定委员会的职业病诊断鉴定结论的异议纠纷； （四）家庭或者个人与家政服务人员之间的纠纷； （五）个体工匠与帮工、学徒之间的纠纷； （六）农村承包经营户与受雇人之间的纠纷。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400002, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第三条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动争议案件由用人单位所在地或者劳动合同履行地的基层人民法院管辖。 劳动合同履行地不明确的，由用人单位所在地的基层人民法院管辖。 法律另有规定的，依照其规定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400003, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第四条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动者与用人单位均不服劳动争议仲裁机构的同一裁决，向同一人民法院起诉的，人民法院应当并案审理，双方当事人互为原告和被告，对双方的诉讼请求，人民法院应当一并作出裁决。在诉讼过程中，一方当事人撤诉的，人民法院应当根据另一方当事人的诉讼请求继续审理。双方当事人就同一仲裁裁决分别向有管辖权的人民法院起诉的，后受理的人民法院应当将案件移送给先受理的人民法院。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400004, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第五条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动争议仲裁机构以无管辖权为由对劳动争议案件不予受理，当事人提起诉讼的，人民法院按照以下情形分别处理： （一）经审查认为该劳动争议仲裁机构对案件确无管辖权的，应当告知当事人向有管辖权的劳动争议仲裁机构申请仲裁； （二）经审查认为该劳动争议仲裁机构有管辖权的，应当告知当事人申请仲裁，并将审查意见书面通知该劳动争议仲裁机构；劳动争议仲裁机构仍不受理，当事人就该劳动争议事项提起诉讼的，人民法院应予受理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400005, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第六条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动争议仲裁机构以当事人申请仲裁的事项不属于劳动争议为由，作出不予受理的书面裁决、决定或者通知，当事人不服依法提起诉讼的，人民法院应当分别情况予以处理： （一）属于劳动争议案件的，应当受理； （二）虽不属于劳动争议案件，但属于人民法院主管的其他案件，应当依法受理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400006, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第七条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动争议仲裁机构以申请仲裁的主体不适格为由，作出不予受理的书面裁决、决定或者通知，当事人不服依法提起诉讼，经审查确属主体不适格的，人民法院不予受理；已经受理的，裁定驳回起诉。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400007, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第八条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动争议仲裁机构为纠正原仲裁裁决错误重新作出裁决，当事人不服依法提起诉讼的，人民法院应当受理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400008, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第九条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动争议仲裁机构仲裁的事项不属于人民法院受理的案件范围，当事人不服依法提起诉讼的，人民法院不予受理；已经受理的，裁定驳回起诉。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400009, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第十条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '当事人不服劳动争议仲裁机构作出的预先支付劳动者劳动报酬、工伤医疗费、经济补偿或者赔偿金的裁决，依法提起诉讼的，人民法院不予受理。 用人单位不履行上述裁决中的给付义务，劳动者依法申请强制执行的，人民法院应予受理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400010, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第十一条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动争议仲裁机构作出的调解书已经发生法律效力，一方当事人反悔提起诉讼的，人民法院不予受理；已经受理的，裁定驳回起诉。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400011, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第十二条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动争议仲裁机构逾期未作出受理决定或仲裁裁决，当事人直接提起诉讼的，人民法院应予受理，但申请仲裁的案件存在下列事由的除外： （一）移送管辖的； （二）正在送达或者送达延误的； （三）等待另案诉讼结果、评残结论的； （四）正在等待劳动争议仲裁机构开庭的； （五）启动鉴定程序或者委托其他部门调查取证的； （六）其他正当事由。 当事人以劳动争议仲裁机构逾期未作出仲裁裁决为由提起诉讼的，应当提交该仲裁机构出具的受理通知书或者其他已接受仲裁申请的凭证、证明。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400012, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第十三条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动者依据劳动合同法第三十条第二款和调解仲裁法第十六条规定向人民法院申请支付令，符合民事诉讼法第十七章督促程序规定的，人民法院应予受理。 依据劳动合同法第三十条第二款规定申请支付令被人民法院裁定终结督促程序后，劳动者就劳动争议事项直接提起诉讼的，人民法院应当告知其先向劳动争议仲裁机构申请仲裁。 依据调解仲裁法第十六条规定申请支付令被人民法院裁定终结督促程序后，劳动者依据调解协议直接提起诉讼的，人民法院应予受理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400013, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第十四条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '人民法院受理劳动争议案件后，当事人增加诉讼请求的，如该诉讼请求与讼争的劳动争议具有不可分性，应当合并审理；如属独立的劳动争议，应当告知当事人向劳动争议仲裁机构申请仲裁。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400014, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第十五条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动者以用人单位的工资欠条为证据直接提起诉讼，诉讼请求不涉及劳动关系其他争议的，视为拖欠劳动报酬争议，人民法院按照普通民事纠纷受理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400015, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第十六条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动争议仲裁机构作出仲裁裁决后，当事人对裁决中的部分事项不服，依法提起诉讼的，劳动争议仲裁裁决不发生法律效力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400016, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第十七条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动争议仲裁机构对多个劳动者的劳动争议作出仲裁裁决后，部分劳动者对仲裁裁决不服，依法提起诉讼的，仲裁裁决对提起诉讼的劳动者不发生法律效力；对未提起诉讼的部分劳动者，发生法律效力，如其申请执行的，人民法院应当受理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400017, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第十八条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '仲裁裁决的类型以仲裁裁决书确定为准。仲裁裁决书未载明该裁决为终局裁决或者非终局裁决，用人单位不服该仲裁裁决向基层人民法院提起诉讼的，应当按照以下情形分别处理： （一）经审查认为该仲裁裁决为非终局裁决的，基层人民法院应予受理； （二）经审查认为该仲裁裁决为终局裁决的，基层人民法院不予受理，但应告知用人单位可以自收到不予受理裁定书之日起三十日内向劳动争议仲裁机构所在地的中级人民法院申请撤销该仲裁裁决；已经受理的，裁定驳回起诉。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400018, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第十九条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '仲裁裁决书未载明该裁决为终局裁决或者非终局裁决，劳动者依据调解仲裁法第四十七条第一项规定，追索劳动报酬、工伤医疗费、经济补偿或者赔偿金，如果仲裁裁决涉及数项，每项确定的数额均不超过当地月最低工资标准十二个月金额的，应当按照终局裁决处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400019, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第二十条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动争议仲裁机构作出的同一仲裁裁决同时包含终局裁决事项和非终局裁决事项，当事人不服该仲裁裁决向人民法院提起诉讼的，应当按照非终局裁决处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400020, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第二十一条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动者依据调解仲裁法第四十八条规定向基层人民法院提起诉讼，用人单位依据调解仲裁法第四十九条规定向劳动争议仲裁机构所在地的中级人民法院申请撤销仲裁裁决的，中级人民法院应当不予受理；已经受理的，应当裁定驳回申请。 被人民法院驳回起诉或者劳动者撤诉的，用人单位可以自收到裁定书之日起三十日内，向劳动争议仲裁机构所在地的中级人民法院申请撤销仲裁裁决。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400021, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第二十二条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '用人单位依据调解仲裁法第四十九条规定向中级人民法院申请撤销仲裁裁决，中级人民法院作出的驳回申请或者撤销仲裁裁决的裁定为终审裁定。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400022, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第二十三条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '中级人民法院审理用人单位申请撤销终局裁决的案件，应当组成合议庭开庭审理。经过阅卷、调查和询问当事人，对没有新的事实、证据或者理由，合议庭认为不需要开庭审理的，可以不开庭审理。 中级人民法院可以组织双方当事人调解。达成调解协议的，可以制作调解书。一方当事人逾期不履行调解协议的，另一方可以申请人民法院强制执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400023, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第二十四条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '当事人申请人民法院执行劳动争议仲裁机构作出的发生法律效力的裁决书、调解书，被申请人提出证据证明劳动争议仲裁裁决书、调解书有下列情形之一，并经审查核实的，人民法院可以根据民事诉讼法第二百三十七条规定，裁定不予执行： （一）裁决的事项不属于劳动争议仲裁范围，或者劳动争议仲裁机构无权仲裁的； （二）适用法律、法规确有错误的； （三）违反法定程序的； （四）裁决所根据的证据是伪造的； （五）对方当事人隐瞒了足以影响公正裁决的证据的； （六）仲裁员在仲裁该案时有索贿受贿、徇私舞弊、枉法裁决行为的； （七）人民法院认定执行该劳动争议仲裁裁决违背社会公共利益的。 人民法院在不予执行的裁定书中，应当告知当事人在收到裁定书之次日起三十日内，可以就该劳动争议事项向人民法院提起诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400024, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第二十五条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动争议仲裁机构作出终局裁决，劳动者向人民法院申请执行，用人单位向劳动争议仲裁机构所在地的中级人民法院申请撤销的，人民法院应当裁定中止执行。 用人单位撤回撤销终局裁决申请或者其申请被驳回的，人民法院应当裁定恢复执行。仲裁裁决被撤销的，人民法院应当裁定终结执行。 用人单位向人民法院申请撤销仲裁裁决被驳回后，又在执行程序中以相同理由提出不予执行抗辩的，人民法院不予支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400025, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第二十六条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '用人单位与其它单位合并的，合并前发生的劳动争议，由合并后的单位为当事人；用人单位分立为若干单位的，其分立前发生的劳动争议，由分立后的实际用人单位为当事人。 用人单位分立为若干单位后，具体承受劳动权利义务的单位不明确的，分立后的单位均为当事人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400026, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第二十七条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '用人单位招用尚未解除劳动合同的劳动者，原用人单位与劳动者发生的劳动争议，可以列新的用人单位为第三人。 原用人单位以新的用人单位侵权为由提起诉讼的，可以列劳动者为第三人。 原用人单位以新的用人单位和劳动者共同侵权为由提起诉讼的，新的用人单位和劳动者列为共同被告。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400027, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第二十八条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动者在用人单位与其他平等主体之间的承包经营期间，与发包方和承包方双方或者一方发生劳动争议，依法提起诉讼的，应当将承包方和发包方作为当事人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400028, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第二十九条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动者与未办理营业执照、营业执照被吊销或者营业期限届满仍继续经营的用人单位发生争议的，应当将用人单位或者其出资人列为当事人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400029, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第三十条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '未办理营业执照、营业执照被吊销或者营业期限届满仍继续经营的用人单位，以挂靠等方式借用他人营业执照经营的，应当将用人单位和营业执照出借方列为当事人。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400030, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第三十一条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '当事人不服劳动争议仲裁机构作出的仲裁裁决，依法提起诉讼，人民法院审查认为仲裁裁决遗漏了必须共同参加仲裁的当事人的，应当依法追加遗漏的人为诉讼当事人。 被追加的当事人应当承担责任的，人民法院应当一并处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400031, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第三十二条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '用人单位与其招用的已经依法享受养老保险待遇或者领取退休金的人员发生用工争议而提起诉讼的，人民法院应当按劳务关系处理。 企业停薪留职人员、未达到法定退休年龄的内退人员、下岗待岗人员以及企业经营性停产放长假人员，因与新的用人单位发生用工争议而提起诉讼的，人民法院应当按劳动关系处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400032, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第三十三条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '外国人、无国籍人未依法取得就业证件即与中华人民共和国境内的用人单位签订劳动合同，当事人请求确认与用人单位存在劳动关系的，人民法院不予支持。 持有《外国专家证》并取得《外国人来华工作许可证》的外国人，与中华人民共和国境内的用人单位建立用工关系的，可以认定为劳动关系。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400033, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第三十四条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动合同期满后，劳动者仍在原用人单位工作，原用人单位未表示异议的，视为双方同意以原条件继续履行劳动合同。一方提出终止劳动关系的，人民法院应予支持。 根据劳动合同法第十四条规定，用人单位应当与劳动者签订无固定期限劳动合同而未签订的，人民法院可以视为双方之间存在无固定期限劳动合同关系，并以原劳动合同确定双方的权利义务关系。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400034, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第三十五条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动者与用人单位就解除或者终止劳动合同办理相关手续、支付工资报酬、加班费、经济补偿或者赔偿金等达成的协议，不违反法律、行政法规的强制性规定，且不存在欺诈、胁迫或者乘人之危情形的，应当认定有效。 前款协议存在重大误解或者显失公平情形，当事人请求撤销的，人民法院应予支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400035, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第三十六条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '当事人在劳动合同或者保密协议中约定了竞业限制，但未约定解除或者终止劳动合同后给予劳动者经济补偿，劳动者履行了竞业限制义务，要求用人单位按照劳动者在劳动合同解除或者终止前十二个月平均工资的30%按月支付经济补偿的，人民法院应予支持。 前款规定的月平均工资的30%低于劳动合同履行地最低工资标准的，按照劳动合同履行地最低工资标准支付。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400036, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第三十七条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '当事人在劳动合同或者保密协议中约定了竞业限制和经济补偿，当事人解除劳动合同时，除另有约定外，用人单位要求劳动者履行竞业限制义务，或者劳动者履行了竞业限制义务后要求用人单位支付经济补偿的，人民法院应予支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400037, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第三十八条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '当事人在劳动合同或者保密协议中约定了竞业限制和经济补偿，劳动合同解除或者终止后，因用人单位的原因导致三个月未支付经济补偿，劳动者请求解除竞业限制约定的，人民法院应予支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400038, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第三十九条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '在竞业限制期限内，用人单位请求解除竞业限制协议的，人民法院应予支持。 在解除竞业限制协议时，劳动者请求用人单位额外支付劳动者三个月的竞业限制经济补偿的，人民法院应予支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400039, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第四十条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动者违反竞业限制约定，向用人单位支付违约金后，用人单位要求劳动者按照约定继续履行竞业限制义务的，人民法院应予支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400040, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第四十一条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动合同被确认为无效，劳动者已付出劳动的，用人单位应当按照劳动合同法第二十八条、第四十六条、第四十七条的规定向劳动者支付劳动报酬和经济补偿。 由于用人单位原因订立无效劳动合同，给劳动者造成损害的，用人单位应当赔偿劳动者因合同无效所造成的经济损失。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400041, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第四十二条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动者主张加班费的，应当就加班事实的存在承担举证责任。但劳动者有证据证明用人单位掌握加班事实存在的证据，用人单位不提供的，由用人单位承担不利后果。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400042, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第四十三条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '用人单位与劳动者协商一致变更劳动合同，虽未采用书面形式，但已经实际履行了口头变更的劳动合同超过一个月，变更后的劳动合同内容不违反法律、行政法规且不违背公序良俗，当事人以未采用书面形式为由主张劳动合同变更无效的，人民法院不予支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400043, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第四十四条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '因用人单位作出的开除、除名、辞退、解除劳动合同、减少劳动报酬、计算劳动者工作年限等决定而发生的劳动争议，用人单位负举证责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400044, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第四十五条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '用人单位有下列情形之一，迫使劳动者提出解除劳动合同的，用人单位应当支付劳动者的劳动报酬和经济补偿，并可支付赔偿金： （一）以暴力、威胁或者非法限制人身自由的手段强迫劳动的； （二）未按照劳动合同约定支付劳动报酬或者提供劳动条件的； （三）克扣或者无故拖欠劳动者工资的； （四）拒不支付劳动者延长工作时间工资报酬的； （五）低于当地最低工资标准支付劳动者工资的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400045, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第四十六条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动者非因本人原因从原用人单位被安排到新用人单位工作，原用人单位未支付经济补偿，劳动者依据劳动合同法第三十八条规定与新用人单位解除劳动合同，或者新用人单位向劳动者提出解除、终止劳动合同，在计算支付经济补偿或赔偿金的工作年限时，劳动者请求把在原用人单位的工作年限合并计算为新用人单位工作年限的，人民法院应予支持。 用人单位符合下列情形之一的，应当认定属于“劳动者非因本人原因从原用人单位被安排到新用人单位工作”： （一）劳动者仍在原工作场所、工作岗位工作，劳动合同主体由原用人单位变更为新用人单位； （二）用人单位以组织委派或任命形式对劳动者进行工作调动； （三）因用人单位合并、分立等原因导致劳动者工作调动； （四）用人单位及其关联企业与劳动者轮流订立劳动合同； （五）其他合理情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400046, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第四十七条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '建立了工会组织的用人单位解除劳动合同符合劳动合同法第三十九条、第四十条规定，但未按照劳动合同法第四十三条规定事先通知工会，劳动者以用人单位违法解除劳动合同为由请求用人单位支付赔偿金的，人民法院应予支持，但起诉前用人单位已经补正有关程序的除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400047, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第四十八条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '劳动合同法施行后，因用人单位经营期限届满不再继续经营导致劳动合同不能继续履行，劳动者请求用人单位支付经济补偿的，人民法院应予支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400048, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第四十九条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '在诉讼过程中，劳动者向人民法院申请采取财产保全措施，人民法院经审查认为申请人经济确有困难，或者有证据证明用人单位存在欠薪逃匿可能的，应当减轻或者免除劳动者提供担保的义务，及时采取保全措施。 人民法院作出的财产保全裁定中，应当告知当事人在劳动争议仲裁机构的裁决书或者在人民法院的裁判文书生效后三个月内申请强制执行。逾期不申请的，人民法院应当裁定解除保全措施。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400049, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第五十条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '用人单位根据劳动合同法第四条规定，通过民主程序制定的规章制度，不违反国家法律、行政法规及政策规定，并已向劳动者公示的，可以作为确定双方权利义务的依据。 用人单位制定的内部规章制度与集体合同或者劳动合同约定的内容不一致，劳动者请求优先适用合同约定的，人民法院应予支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400050, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第五十一条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '当事人在调解仲裁法第十条规定的调解组织主持下达成的具有劳动权利义务内容的调解协议，具有劳动合同的约束力，可以作为人民法院裁判的根据。 当事人在调解仲裁法第十条规定的调解组织主持下仅就劳动报酬争议达成调解协议，用人单位不履行调解协议确定的给付义务，劳动者直接提起诉讼的，人民法院可以按照普通民事纠纷受理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400051, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第五十二条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '当事人在人民调解委员会主持下仅就给付义务达成的调解协议，双方认为有必要的，可以共同向人民调解委员会所在地的基层人民法院申请司法确认。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400052, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第五十三条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '用人单位对劳动者作出的开除、除名、辞退等处理，或者因其他原因解除劳动合同确有错误的，人民法院可以依法判决予以撤销。 对于追索劳动报酬、养老金、医疗费以及工伤保险待遇、经济补偿金、培训费及其他相关费用等案件，给付数额不当的，人民法院可以予以变更。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (400053, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》', '第五十四条', '劳动', '司法解释', NULL, '最高人民法院 2020-12-29', NULL, NULL, '本解释自2021年1月1日起施行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401000, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第一条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '具备合法经营资格的承包人将承包业务转包或者分包给不具备合法经营资格的组织或者个人，该组织或者个人招用的劳动者请求确认承包人为承担用工主体责任单位，承担支付劳动报酬、认定工伤后的工伤保险待遇等责任的，人民法院依法予以支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401001, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第二条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '不具备合法经营资格的组织或者个人挂靠具备合法经营资格的单位对外经营，该组织或者个人招用的劳动者请求确认被挂靠单位为承担用工主体责任单位，承担支付劳动报酬、认定工伤后的工伤保险待遇等责任的，人民法院依法予以支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401002, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第三条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '劳动者被多个存在关联关系的单位交替或者同时用工，其请求确认劳动关系的，人民法院按照下列情形分别处理： （一）已订立书面劳动合同，劳动者请求按照劳动合同确认劳动关系的，人民法院依法予以支持； （二）未订立书面劳动合同的，根据用工管理行为，综合考虑工作时间、工作内容、劳动报酬支付、社会保险费缴纳等因素确认劳动关系。 劳动者请求符合前款第二项规定情形的关联单位共同承担支付劳动报酬、福利待遇等责任的，人民法院依法予以支持，但关联单位之间依法对劳动者的劳动报酬、福利待遇等作出约定且经劳动者同意的除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401003, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第四条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '外国人与中华人民共和国境内的用人单位建立用工关系，有下列情形之一，外国人请求确认与用人单位存在劳动关系的，人民法院依法予以支持： （一）已取得永久居留资格的； （二）已取得工作许可且在中国境内合法停留居留的； （三）按照国家有关规定办理相关手续的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401004, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第五条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '依法设立的外国企业常驻代表机构可以作为劳动争议案件的当事人。当事人申请追加外国企业参加诉讼的，人民法院依法予以支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401005, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第六条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '用人单位未依法与劳动者订立书面劳动合同，应当支付劳动者的二倍工资按月计算；不满一个月的，按该月实际工作日计算。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401006, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第七条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '劳动者以用人单位未订立书面劳动合同为由，请求用人单位支付二倍工资的，人民法院依法予以支持，但用人单位举证证明存在下列情形之一的除外： （一）因不可抗力导致未订立的； （二）因劳动者本人故意或者重大过失未订立的； （三）法律、行政法规规定的其他情形。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401007, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第八条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '劳动合同期满，有下列情形之一的，人民法院认定劳动合同期限依法自动续延，不属于用人单位未订立书面劳动合同的情形： （一）劳动合同法第四十二条规定的用人单位不得解除劳动合同的； （二）劳动合同法实施条例第十七条规定的服务期尚未到期的； （三）工会法第十九条规定的任期未届满的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401008, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第九条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '有证据证明存在劳动合同法第十四条第三款规定的“视为用人单位与劳动者已订立无固定期限劳动合同”情形，劳动者请求与用人单位订立书面劳动合同的，人民法院依法予以支持；劳动者以用人单位未及时补订书面劳动合同为由，请求用人单位支付视为已与劳动者订立无固定期限劳动合同期间二倍工资的，人民法院不予支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401009, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第十条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '有下列情形之一的，人民法院应认定为符合劳动合同法第十四条第二款第三项“连续订立二次固定期限劳动合同”的规定： （一）用人单位与劳动者协商延长劳动合同期限累计达到一年以上，延长期限届满的； （二）用人单位与劳动者约定劳动合同期满后自动续延，续延期限届满的； （三）劳动者非因本人原因仍在原工作场所、工作岗位工作，用人单位变换劳动合同订立主体，但继续对劳动者进行劳动管理，合同期限届满的； （四）以其他违反诚信原则的规避行为再次订立劳动合同，期限届满的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401010, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第十一条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '劳动合同期满后，劳动者仍在用人单位工作，用人单位未表示异议超过一个月，劳动者请求用人单位以原条件续订劳动合同的，人民法院依法予以支持。 符合订立无固定期限劳动合同情形，劳动者请求用人单位以原条件订立无固定期限劳动合同的，人民法院依法予以支持。 用人单位解除劳动合同，劳动者请求用人单位依法承担解除劳动合同法律后果的，人民法院依法予以支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401011, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第十二条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '除向劳动者支付正常劳动报酬外，用人单位与劳动者约定服务期限并提供特殊待遇，劳动者违反约定提前解除劳动合同且不符合劳动合同法第三十八条规定的单方解除劳动合同情形时，用人单位请求劳动者承担赔偿损失责任的，人民法院可以综合考虑实际损失、当事人的过错程度、已经履行的年限等因素确定劳动者应当承担的赔偿责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401012, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第十三条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '劳动者未知悉、接触用人单位的商业秘密和与知识产权相关的保密事项，劳动者请求确认竞业限制条款不生效的，人民法院依法予以支持。 竞业限制条款约定的竞业限制范围、地域、期限等内容与劳动者知悉、接触的商业秘密和与知识产权相关的保密事项不相适应，劳动者请求确认竞业限制条款超过合理比例部分无效的，人民法院依法予以支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401013, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第十四条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '用人单位与高级管理人员、高级技术人员和其他负有保密义务的人员约定在职期间竞业限制条款，劳动者以不得约定在职期间竞业限制、未支付经济补偿为由请求确认竞业限制条款无效的，人民法院不予支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401014, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第十五条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '劳动者违反有效的竞业限制约定，用人单位请求劳动者按照约定返还已经支付的经济补偿并支付违约金的，人民法院依法予以支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401015, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第十六条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '用人单位违法解除或者终止劳动合同后，有下列情形之一的，人民法院可以认定为劳动合同法第四十八条规定的“劳动合同已经不能继续履行”： （一）劳动合同在仲裁或者诉讼过程中期满且不存在应当依法续订、续延劳动合同情形的； （二）劳动者开始依法享受基本养老保险待遇的； （三）用人单位被宣告破产的； （四）用人单位解散的，但因合并或者分立需要解散的除外； （五）劳动者已经与其他用人单位建立劳动关系，对完成用人单位的工作任务造成严重影响，或者经用人单位提出，不与其他用人单位解除劳动合同的； （六）存在劳动合同客观不能履行的其他情形的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401016, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第十七条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '用人单位未按照国务院安全生产监督管理部门、卫生行政部门的规定组织从事接触职业病危害作业的劳动者进行离岗前的职业健康检查，劳动者在双方解除劳动合同后请求继续履行劳动合同的，人民法院依法予以支持，但有下列情形之一的除外： （一）一审法庭辩论终结前，用人单位已经组织劳动者进行职业健康检查且经检查劳动者未患职业病的； （二）一审法庭辩论终结前，用人单位组织劳动者进行职业健康检查，劳动者无正当理由拒绝检查的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401017, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第十八条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '用人单位违法解除、终止可以继续履行的劳动合同，劳动者请求用人单位支付违法解除、终止决定作出后至劳动合同继续履行前一日工资的，用人单位应当按照劳动者提供正常劳动时的工资标准向劳动者支付上述期间的工资。 用人单位、劳动者对于劳动合同解除、终止都有过错的，应当各自承担相应的责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401018, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第十九条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '用人单位与劳动者约定或者劳动者向用人单位承诺无需缴纳社会保险费的，人民法院应当认定该约定或者承诺无效。用人单位未依法缴纳社会保险费，劳动者根据劳动合同法第三十八条第一款第三项规定请求解除劳动合同、由用人单位支付经济补偿的，人民法院依法予以支持。 有前款规定情形，用人单位依法补缴社会保险费后，请求劳动者返还已支付的社会保险费补偿的，人民法院依法予以支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401019, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第二十条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '当事人在仲裁期间因自身原因未提出仲裁时效抗辩，在一审或者二审诉讼期间提出仲裁时效抗辩的，人民法院不予支持。当事人基于新的证据能够证明对方当事人请求权的仲裁时效期间届满的，人民法院应予支持。 当事人未按照前款规定提出仲裁时效抗辩，以仲裁时效期间届满为由申请再审或者提出再审抗辩的，人民法院不予支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (401020, '《最高人民法院关于审理劳动争议案件适用法律问题的解释（二）》', '第二十一条', '劳动', '司法解释', NULL, '最高人民法院 2025-07-31', NULL, NULL, '本解释自2025年9月1日起施行。《最高人民法院关于审理劳动争议案件适用法律问题的解释（一）》（法释〔2020〕26号）第三十二条第一款同时废止。最高人民法院此前发布的司法解释与本解释不一致的，以本解释为准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (402000, '《最高人民法院关于审理工伤保险行政案件若干问题的规定》', '第一条', '劳动', '司法解释', NULL, '最高人民法院 2014-06-18', NULL, NULL, '人民法院审理工伤认定行政案件，在认定是否存在《工伤保险条例》第十四条第（六）项“本人主要责任”、第十六条第（二）项“醉酒或者吸毒”和第十六条第（三）项“自残或者自杀”等情形时，应当以有权机构出具的事故责任认定书、结论性意见和人民法院生效裁判等法律文书为依据，但有相反证据足以推翻事故责任认定书和结论性意见的除外。 前述法律文书不存在或者内容不明确，社会保险行政部门就前款事实作出认定的，人民法院应当结合其提供的相关证据依法进行审查。 《工伤保险条例》第十六条第（一）项“故意犯罪”的认定，应当以刑事侦查机关、检察机关和审判机关的生效法律文书或者结论性意见为依据。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (402001, '《最高人民法院关于审理工伤保险行政案件若干问题的规定》', '第二条', '劳动', '司法解释', NULL, '最高人民法院 2014-06-18', NULL, NULL, '人民法院受理工伤认定行政案件后，发现原告或者第三人在提起行政诉讼前已经就是否存在劳动关系申请劳动仲裁或者提起民事诉讼的，应当中止行政案件的审理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (402002, '《最高人民法院关于审理工伤保险行政案件若干问题的规定》', '第三条', '劳动', '司法解释', NULL, '最高人民法院 2014-06-18', NULL, NULL, '社会保险行政部门认定下列单位为承担工伤保险责任单位的，人民法院应予支持： （一）职工与两个或两个以上单位建立劳动关系，工伤事故发生时，职工为之工作的单位为承担工伤保险责任的单位； （二）劳务派遣单位派遣的职工在用工单位工作期间因工伤亡的，派遣单位为承担工伤保险责任的单位； （三）单位指派到其他单位工作的职工因工伤亡的，指派单位为承担工伤保险责任的单位； （四）用工单位违反法律、法规规定将承包业务转包给不具备用工主体资格的组织或者自然人，该组织或者自然人聘用的职工从事承包业务时因工伤亡的，用工单位为承担工伤保险责任的单位； （五）个人挂靠其他单位对外经营，其聘用的人员因工伤亡的，被挂靠单位为承担工伤保险责任的单位。 前款第（四）、（五）项明确的承担工伤保险责任的单位承担赔偿责任或者社会保险经办机构从工伤保险基金支付工伤保险待遇后，有权向相关组织、单位和个人追偿。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (402003, '《最高人民法院关于审理工伤保险行政案件若干问题的规定》', '第四条', '劳动', '司法解释', NULL, '最高人民法院 2014-06-18', NULL, NULL, '社会保险行政部门认定下列情形为工伤的，人民法院应予支持： （一）职工在工作时间和工作场所内受到伤害，用人单位或者社会保险行政部门没有证据证明是非工作原因导致的； （二）职工参加用人单位组织或者受用人单位指派参加其他单位组织的活动受到伤害的； （三）在工作时间内，职工来往于多个与其工作职责相关的工作场所之间的合理区域因工受到伤害的； （四）其他与履行工作职责相关，在工作时间及合理区域内受到伤害的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (402004, '《最高人民法院关于审理工伤保险行政案件若干问题的规定》', '第五条', '劳动', '司法解释', NULL, '最高人民法院 2014-06-18', NULL, NULL, '社会保险行政部门认定下列情形为“因工外出期间”的，人民法院应予支持： （一）职工受用人单位指派或者因工作需要在工作场所以外从事与工作职责有关的活动期间； （二）职工受用人单位指派外出学习或者开会期间； （三）职工因工作需要的其他外出活动期间。 职工因工外出期间从事与工作或者受用人单位指派外出学习、开会无关的个人活动受到伤害，社会保险行政部门不认定为工伤的，人民法院应予支持。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (402005, '《最高人民法院关于审理工伤保险行政案件若干问题的规定》', '第六条', '劳动', '司法解释', NULL, '最高人民法院 2014-06-18', NULL, NULL, '对社会保险行政部门认定下列情形为“上下班途中”的，人民法院应予支持： （一）在合理时间内往返于工作地与住所地、经常居住地、单位宿舍的合理路线的上下班途中； （二）在合理时间内往返于工作地与配偶、父母、子女居住地的合理路线的上下班途中； （三）从事属于日常工作生活所需要的活动，且在合理时间和合理路线的上下班途中； （四）在合理时间内其他合理路线的上下班途中。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (402006, '《最高人民法院关于审理工伤保险行政案件若干问题的规定》', '第七条', '劳动', '司法解释', NULL, '最高人民法院 2014-06-18', NULL, NULL, '由于不属于职工或者其近亲属自身原因超过工伤认定申请期限的，被耽误的时间不计算在工伤认定申请期限内。 有下列情形之一耽误申请时间的，应当认定为不属于职工或者其近亲属自身原因： （一）不可抗力； （二）人身自由受到限制； （三）属于用人单位原因； （四）社会保险行政部门登记制度不完善； （五）当事人对是否存在劳动关系申请仲裁、提起民事诉讼。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (402007, '《最高人民法院关于审理工伤保险行政案件若干问题的规定》', '第八条', '劳动', '司法解释', NULL, '最高人民法院 2014-06-18', NULL, NULL, '职工因第三人的原因受到伤害，社会保险行政部门以职工或者其近亲属已经对第三人提起民事诉讼或者获得民事赔偿为由，作出不予受理工伤认定申请或者不予认定工伤决定的，人民法院不予支持。 职工因第三人的原因受到伤害，社会保险行政部门已经作出工伤认定，职工或者其近亲属未对第三人提起民事诉讼或者尚未获得民事赔偿，起诉要求社会保险经办机构支付工伤保险待遇的，人民法院应予支持。 职工因第三人的原因导致工伤，社会保险经办机构以职工或者其近亲属已经对第三人提起民事诉讼为由，拒绝支付工伤保险待遇的，人民法院不予支持，但第三人已经支付的医疗费用除外。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (402008, '《最高人民法院关于审理工伤保险行政案件若干问题的规定》', '第九条', '劳动', '司法解释', NULL, '最高人民法院 2014-06-18', NULL, NULL, '因工伤认定申请人或者用人单位隐瞒有关情况或者提供虚假材料，导致工伤认定错误的，社会保险行政部门可以在诉讼中依法予以更正。 工伤认定依法更正后，原告不申请撤诉，社会保险行政部门在作出原工伤认定时有过错的，人民法院应当判决确认违法；社会保险行政部门无过错的，人民法院可以驳回原告诉讼请求。 最高人民法院以前颁布的司法解释与本规定不一致的，以本规定为准。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (404000, '《最高人民法院关于审理拒不支付劳动报酬刑事案件适用法律若干问题的解释》', '第一条', '劳动', '司法解释', NULL, '最高人民法院 2013-01-16', NULL, NULL, '劳动者依照《中华人民共和国劳动法》和《中华人民共和国劳动合同法》等法律的规定应得的劳动报酬，包括工资、奖金、津贴、补贴、延长工作时间的工资报酬及特殊情况下支付的工资等，应当认定为刑法第二百七十六条之一第一款规定的“劳动者的劳动报酬”。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (404001, '《最高人民法院关于审理拒不支付劳动报酬刑事案件适用法律若干问题的解释》', '第二条', '劳动', '司法解释', NULL, '最高人民法院 2013-01-16', NULL, NULL, '以逃避支付劳动者的劳动报酬为目的，具有下列情形之一的，应当认定为刑法第二百七十六条之一第一款规定的“以转移财产、逃匿等方法逃避支付劳动者的劳动报酬”： （一）隐匿财产、恶意清偿、虚构债务、虚假破产、虚假倒闭或者以其他方法转移、处分财产的； （二）逃跑、藏匿的； （三）隐匿、销毁或者篡改账目、职工名册、工资支付记录、考勤记录等与劳动报酬相关的材料的； （四）以其他方法逃避支付劳动报酬的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (404002, '《最高人民法院关于审理拒不支付劳动报酬刑事案件适用法律若干问题的解释》', '第三条', '劳动', '司法解释', NULL, '最高人民法院 2013-01-16', NULL, NULL, '具有下列情形之一的，应当认定为刑法第二百七十六条之一第一款规定的“数额较大”： （一）拒不支付一名劳动者三个月以上的劳动报酬且数额在五千元至二万元以上的； （二）拒不支付十名以上劳动者的劳动报酬且数额累计在三万元至十万元以上的。 各省、自治区、直辖市高级人民法院可以根据本地区经济社会发展状况，在前款规定的数额幅度内，研究确定本地区执行的具体数额标准，报最高人民法院备案。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (404003, '《最高人民法院关于审理拒不支付劳动报酬刑事案件适用法律若干问题的解释》', '第四条', '劳动', '司法解释', NULL, '最高人民法院 2013-01-16', NULL, NULL, '经人力资源社会保障部门或者政府其他有关部门依法以限期整改指令书、行政处理决定书等文书责令支付劳动者的劳动报酬后，在指定的期限内仍不支付的，应当认定为刑法第二百七十六条之一第一款规定的“经政府有关部门责令支付仍不支付”，但有证据证明行为人有正当理由未知悉责令支付或者未及时支付劳动报酬的除外。 行为人逃匿，无法将责令支付文书送交其本人、同住成年家属或者所在单位负责收件的人的，如果有关部门已通过在行为人的住所地、生产经营场所等地张贴责令支付文书等方式责令支付，并采用拍照、录像等方式记录的，应当视为“经政府有关部门责令支付”。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (404004, '《最高人民法院关于审理拒不支付劳动报酬刑事案件适用法律若干问题的解释》', '第五条', '劳动', '司法解释', NULL, '最高人民法院 2013-01-16', NULL, NULL, '拒不支付劳动者的劳动报酬，符合本解释第三条的规定，并具有下列情形之一的，应当认定为刑法第二百七十六条之一第一款规定的“造成严重后果”： （一）造成劳动者或者其被赡养人、被扶养人、被抚养人的基本生活受到严重影响、重大疾病无法及时医治或者失学的； （二）对要求支付劳动报酬的劳动者使用暴力或者进行暴力威胁的； （三）造成其他严重后果的。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (404005, '《最高人民法院关于审理拒不支付劳动报酬刑事案件适用法律若干问题的解释》', '第六条', '劳动', '司法解释', NULL, '最高人民法院 2013-01-16', NULL, NULL, '拒不支付劳动者的劳动报酬，尚未造成严重后果，在刑事立案前支付劳动者的劳动报酬，并依法承担相应赔偿责任的，可以认定为情节显著轻微危害不大，不认为是犯罪；在提起公诉前支付劳动者的劳动报酬，并依法承担相应赔偿责任的，可以减轻或者免除刑事处罚；在一审宣判前支付劳动者的劳动报酬，并依法承担相应赔偿责任的，可以从轻处罚。 对于免除刑事处罚的，可以根据案件的不同情况，予以训诫、责令具结悔过或者赔礼道歉。 拒不支付劳动者的劳动报酬，造成严重后果，但在宣判前支付劳动者的劳动报酬，并依法承担相应赔偿责任的，可以酌情从宽处罚。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (404006, '《最高人民法院关于审理拒不支付劳动报酬刑事案件适用法律若干问题的解释》', '第七条', '劳动', '司法解释', NULL, '最高人民法院 2013-01-16', NULL, NULL, '不具备用工主体资格的单位或者个人，违法用工且拒不支付劳动者的劳动报酬，数额较大，经政府有关部门责令支付仍不支付的，应当依照刑法第二百七十六条之一的规定，以拒不支付劳动报酬罪追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (404007, '《最高人民法院关于审理拒不支付劳动报酬刑事案件适用法律若干问题的解释》', '第八条', '劳动', '司法解释', NULL, '最高人民法院 2013-01-16', NULL, NULL, '用人单位的实际控制人实施拒不支付劳动报酬行为，构成犯罪的，应当依照刑法第二百七十六条之一的规定追究刑事责任。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (404008, '《最高人民法院关于审理拒不支付劳动报酬刑事案件适用法律若干问题的解释》', '第九条', '劳动', '司法解释', NULL, '最高人民法院 2013-01-16', NULL, NULL, '单位拒不支付劳动报酬，构成犯罪的，依照本解释规定的相应个人犯罪的定罪量刑标准，对直接负责的主管人员和其他直接责任人员定罪处罚，并对单位判处罚金。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (405000, '《最高人民法院关于人民法院审理事业单位人事争议案件若干问题的规定》', '第一条', '劳动', '司法解释', NULL, '最高人民法院 2003-08-27', NULL, NULL, '事业单位与其工作人员之间因辞职、辞退及履行聘用合同所发生的争议，适用《中华人民共和国劳动法》的规定处理。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (405001, '《最高人民法院关于人民法院审理事业单位人事争议案件若干问题的规定》', '第二条', '劳动', '司法解释', NULL, '最高人民法院 2003-08-27', NULL, NULL, '当事人对依照国家有关规定设立的人事争议仲裁机构所作的人事争议仲裁裁决不服，自收到仲裁裁决之日起十五日内向人民法院提起诉讼的，人民法院应当依法受理。一方当事人在法定期间内不起诉又不履行仲裁裁决，另一方当事人向人民法院申请执行的，人民法院应当依法执行。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (405002, '《最高人民法院关于人民法院审理事业单位人事争议案件若干问题的规定》', '第三条', '劳动', '司法解释', NULL, '最高人民法院 2003-08-27', NULL, NULL, '本规定所称人事争议是指事业单位与其工作人员之间因辞职、辞退及履行聘用合同所发生的争议。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (406000, '《最高人民法院关于人民法院对经劳动争议仲裁裁决的纠纷准予撤诉或驳回起诉后劳动争议仲裁裁决从何时起生效的解释》', '第一条', '劳动', '司法解释', NULL, '最高人民法院 2000-07-10', NULL, NULL, '当事人不服劳动争议仲裁裁决向人民法院起诉后又申请撤诉，经人民法院审查准予撤诉的，原仲裁裁决自人民法院裁定送达当事人之日起发生法律效力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (406001, '《最高人民法院关于人民法院对经劳动争议仲裁裁决的纠纷准予撤诉或驳回起诉后劳动争议仲裁裁决从何时起生效的解释》', '第二条', '劳动', '司法解释', NULL, '最高人民法院 2000-07-10', NULL, NULL, '当事人因超过起诉期间而被人民法院裁定驳回起诉的，原仲裁裁决自起诉期间届满之次日起恢复法律效力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (406002, '《最高人民法院关于人民法院对经劳动争议仲裁裁决的纠纷准予撤诉或驳回起诉后劳动争议仲裁裁决从何时起生效的解释》', '第三条', '劳动', '司法解释', NULL, '最高人民法院 2000-07-10', NULL, NULL, '因仲裁裁决确定的主体资格错误或仲裁裁决事项不属于劳动争议，被人民法院驳回起诉的，原仲裁裁决不发生法律效力。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
INSERT INTO law_article (id, law_name, article_no, category, doc_type, title, version_info, chapter_info, section_info, content, deleted) VALUES (900001, '《女职工劳动保护特别规定》', '附录', '劳动', '行政法规', '女职工禁忌从事的劳动范围', '国务院 2012-04-28公布', NULL, NULL, '一、女职工禁忌从事的劳动范围： (一)矿山井下作业； (二)体力劳动强度分级标准中规定的第四级体力劳动强度的作业； (三)每小时负重6次以上、每次负重超过20公斤的作业，或者间断负重、每次负重超过25公斤的作业。 二、女职工在经期禁忌从事的劳动范围： (一)冷水作业分级标准中规定的第二级、第三级、第四级冷水作业； (二)低温作业分级标准中规定的第二级、第三级、第四级低温作业； (三)体力劳动强度分级标准中规定的第三级、第四级体力劳动强度的作业； (四)高处作业分级标准中规定的第三级、第四级高处作业。 三、女职工在孕期禁忌从事的劳动范围： (一)作业场所空气中铅及其化合物、汞及其化合物、苯、镉、铍、砷、氰化物、氮氧化物、一氧化碳、二硫化碳、氯、己内酰胺、氯丁二烯、氯乙烯、环氧乙烷、苯胺、甲醛等有毒物质浓度超过国家职业卫生标准的作业； (二)从事抗癌药物、己烯雌酚生产，接触麻醉剂气体等的作业； (三)非密封源放射性物质的操作，核事故与放射事故的应急处置； (四)高处作业分级标准中规定的高处作业； (五)冷水作业分级标准中规定的冷水作业； (六)低温作业分级标准中规定的低温作业； (七)高温作业分级标准中规定的第三级、第四级的作业； (八)噪声作业分级标准中规定的第三级、第四级的作业； (九)体力劳动强度分级标准中规定的第三级、第四级体力劳动强度的作业； (十)在密闭空间、高压室作业或者潜水作业，伴有强烈振动的作业，或者需要频繁弯腰、攀高、下蹲的作业。 四、女职工在哺乳期禁忌从事的劳动范围： (一)孕期禁忌从事的劳动范围的第一项、第三项、第九项； (二)作业场所空气中锰、氟、溴、甲醇、有机磷化合物、有机氯化合物等有毒物质浓度超过国家职业卫生标准的作业。', 0) ON CONFLICT (id) DO UPDATE SET law_name = EXCLUDED.law_name, article_no = EXCLUDED.article_no, category = EXCLUDED.category, doc_type = EXCLUDED.doc_type, title = EXCLUDED.title, version_info = EXCLUDED.version_info, chapter_info = EXCLUDED.chapter_info, section_info = EXCLUDED.section_info, content = EXCLUDED.content, deleted = EXCLUDED.deleted;
